#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

int initialize_arrays(size_t size, long **offsets, int **keys, record **records, int upper_bound) {
    *offsets = (long *)malloc(size * sizeof(long));
    *keys = (int *)malloc(size * sizeof(int));
    *records = (record *)malloc(size * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(*offsets);
        free(*keys);
        free(*records);
        return -1;
    }

    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        (*offsets)[i] = rand() % (upper_bound + 1);
        (*keys)[i] = rand() % (upper_bound + 1);
        (*records)[i].value = rand() % (upper_bound + 1);
    }

    return 0;
}

void free_arrays(long *offsets, int *keys, record *records) {
    free(offsets);
    free(keys);
    free(records);
}
