#include <stdio.h>
#include <stdlib.h>

#define MAX_SIZE 50000
#define MIN_VALUE -1000000
#define MAX_VALUE 1000000

typedef struct Node {
    int data;
    struct Node* next;
} Node;

Node* createNode(int value) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        printf("Memory allocation failed.\n");
        exit(1);
    }
    newNode->data = value;
    newNode->next = NULL;
    return newNode;
}

void insertNode(Node** head, int value) {
    Node* newNode = createNode(value);
    if (*head == NULL) {
        *head = newNode;
    } else {
        Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
}

void readIntegers(int** array, Node** linkedListHead) {
    int count = 0;
    char input[12]; // Assuming integer size won't exceed 11 digits + sign
    while (scanf("%s", input) != EOF && count < MAX_SIZE) {
        int value;
        if (sscanf(input, "%d", &value) == 1 && value >= MIN_VALUE && value <= MAX_VALUE) {
            if (*array == NULL) {
                *array = (int*)malloc(sizeof(int));
                if (*array == NULL) {
                    insertNode(linkedListHead, value);
                } else {
                    (*array)[count++] = value;
                }
            } else {
                if (count < 10000) { // Optimize for low load
                    *array = realloc(*array, (count + 1) * sizeof(int));
                    if (*array == NULL) {
                        insertNode(linkedListHead, value);
                    } else {
                        (*array)[count++] = value;
                    }
                } else {
                    insertNode(linkedListHead, value);
                }
            }
        }
    }
}

void printLargestInteger(int* array, Node* linkedListHead) {
    int largest = MIN_VALUE - 1;
    if (array != NULL) {
        for (int i = 0; i < MAX_SIZE && array[i] != '\0'; i++) {
            if (array[i] > largest) {
                largest = array[i];
            }
        }
    }
    Node* temp = linkedListHead;
    while (temp != NULL) {
        if (temp->data > largest) {
            largest = temp->data;
        }
        temp = temp->next;
    }
    if (largest == MIN_VALUE - 1) {
        printf("No valid integers.\n");
    } else {
        printf("Largest integer: %d\n", largest);
    }
}

int main() {
    int* array = NULL;
    Node* linkedListHead = NULL;

    readIntegers(&array, &linkedListHead);

    printLargestInteger(array, linkedListHead);

    if (array != NULL) {
        free(array);
    }

    while (linkedListHead != NULL) {
        Node* temp = linkedListHead;
        linkedListHead = linkedListHead->next;
        free(temp);
    }

    return 0;
}
