typedef enum {
    COMPRESSION_ZLIB,
    COMPRESSION_BZIP2,
    COMPRESSION_LZO,
    COMPRESSION_UNKNOWN
} CompressionAlgorithm;

typedef struct {
    void* stream;
    CompressionAlgorithm algorithm;
} CompressionStream;

CompressionStream* create_compression_stream(CompressionAlgorithm algorithm) {
    CompressionStream* cs = (CompressionStream*)malloc(sizeof(CompressionStream));
    if (!cs) return NULL;

    switch (algorithm) {
        case COMPRESSION_ZLIB:
            cs->stream = malloc(sizeof(z_stream));
            if (!cs->stream) {
                free(cs);
                return NULL;
            }
            memset(cs->stream, 0, sizeof(z_stream));
            break;
        case COMPRESSION_BZIP2:
            cs->stream = malloc(sizeof(bz_stream));
            if (!cs->stream) {
                free(cs);
                return NULL;
            }
            memset(cs->stream, 0, sizeof(bz_stream));
            break;
        case COMPRESSION_LZO:
            cs->stream = malloc(sizeof(lzo_stream_t));
            if (!cs->stream) {
                free(cs);
                return NULL;
            }
            memset(cs->stream, 0, sizeof(lzo_stream_t));
            break;
        default:
            free(cs);
            return NULL;
    }

    cs->algorithm = algorithm;
    return cs;
}

void destroy_compression_stream(CompressionStream* cs) {
    if (!cs) return;

    switch (cs->algorithm) {
        case COMPRESSION_ZLIB:
            deflateEnd((z_stream*)cs->stream);
            break;
        case COMPRESSION_BZIP2:
            BZ2_bzDecompressEnd((bz_stream*)cs->stream);
            break;
        case COMPRESSION_LZO:
            lzo1x_decompress_end((lzo_stream_t*)cs->stream);
            break;
    }

    free(cs->stream);
    free(cs);
}

