import argparse
import requests
from jinja2 import Environment, FileSystemLoader
from jsonschema import validate, ValidationError
from time import sleep
from random import uniform

def fetch_config_values(service_url):
    retries = 5
    backoff_factor = 0.3
    for i in range(retries):
        try:
            response = requests.get(service_url)
            response.raise_for_status()
            return response.json()
        except (requests.RequestException, ValueError) as e:
            if i < retries - 1:
                sleep_time = backoff_factor * (2 ** i) + uniform(0, 0.5)
                print(f"Attempt {i+1} failed: {e}. Retrying in {sleep_time:.2f}s...")
                sleep(sleep_time)
            else:
                raise

def apply_template(template_path, config_values):
    env = Environment(loader=FileSystemLoader('.'))
    template = env.get_template(template_path)
    return template.render(config_values)

def validate_config(updated_config, schema):
    try:
        validate(instance=updated_config, schema=schema)
    except ValidationError as e:
        print(f"Validation error: {e}")
        return False
    return True

def main(input_file, output_file, skip_validation=False):
    service_url = "https://api.example.com/config"
    config_schema = {
        "$schema": "http://json-schema.org/draft-07/schema#",
        "type": "object",
        "properties": {
            "database": {"type": "string"},
            "host": {"type": "string"}
        },
        "required": ["database", "host"]
    }

    config_values = fetch_config_values(service_url)
    updated_config = apply_template(input_file, config_values)

    if not skip_validation:
        if validate_config(updated_config, config_schema):
            with open(output_file, 'w') as f:
                f.write(updated_config)
            print(f"Configuration written to {output_file}")
        else:
            print("Validation failed. Configuration not updated.")
    else:
        with open(output_file, 'w') as f:
            f.write(updated_config)
        print(f"Configuration written to {output_file} without validation")

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Process system configuration file")
    parser.add_argument("input_file", help="Input configuration file path")
    parser.add_argument("output_file", help="Output configuration file path")
    parser.add_argument("--skip-validation", action="store_true", help="Skip validation step")
    args = parser.parse_args()

    main(args.input_file, args.output_file, args.skip_validation)
