#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_SEMAPHORES 100

typedef struct {
    sem_t *sems[MAX_SEMAPHORES];
    int count;
    pthread_mutex_t lock;
} SemaphoreManager;

SemaphoreManager manager = { .lock = PTHREAD_MUTEX_INITIALIZER };

int create_semaphore(int initial_value) {
    pthread_mutex_lock(&manager.lock);
    if (manager.count >= MAX_SEMAPHORES) {
        pthread_mutex_unlock(&manager.lock);
        return -1; // Semaphore limit reached
    }
    sem_t *sem = malloc(sizeof(sem_t));
    if (sem_init(sem, 0, initial_value) != 0) {
        free(sem);
        pthread_mutex_unlock(&manager.lock);
        return -2; // Failed to initialize semaphore
    }
    manager.sems[manager.count++] = sem;
    pthread_mutex_unlock(&manager.lock);
    return manager.count - 1; // Return the index of the created semaphore
}

int destroy_semaphore(int index) {
    pthread_mutex_lock(&manager.lock);
    if (index < 0 || index >= manager.count) {
        pthread_mutex_unlock(&manager.lock);
        return -1; // Invalid semaphore index
    }
    sem_t *sem = manager.sems[index];
    sem_destroy(sem);
    free(sem);
    for (int i = index; i < manager.count - 1; i++) {
        manager.sems[i] = manager.sems[i + 1];
    }
    manager.count--;
    pthread_mutex_unlock(&manager.lock);
    return 0;
}

int wait_semaphore(int index) {
    pthread_mutex_lock(&manager.lock);
    if (index < 0 || index >= manager.count) {
        pthread_mutex_unlock(&manager.lock);
        return -1; // Invalid semaphore index
    }
    int result = sem_wait(manager.sems[index]);
    pthread_mutex_unlock(&manager.lock);
    return result;
}

int post_semaphore(int index) {
    pthread_mutex_lock(&manager.lock);
    if (index < 0 || index >= manager.count) {
        pthread_mutex_unlock(&manager.lock);
        return -1; // Invalid semaphore index
    }
    int result = sem_post(manager.sems[index]);
    pthread_mutex_unlock(&manager.lock);
    return result;
}

void *monitor_performance(void *arg) {
    while (1) {
        // Implement performance monitoring logic here
        sleep(1); // Simulate periodic monitoring
    }
    return NULL;
}

int main() {
    pthread_t monitor_thread;
    pthread_create(&monitor_thread, NULL, monitor_performance, NULL);

    // Example usage of the semaphore manager
    int sem_index = create_semaphore(5);
    if (sem_index >= 0) {
        wait_semaphore(sem_index);
        post_semaphore(sem_index);
        destroy_semaphore(sem_index);
    }

    pthread_join(monitor_thread, NULL);
    return 0;
}
```

