#include <iostream>
#include <boost/asio.hpp>
#include <boost/thread.hpp>
#include <boost/log/trivial.hpp>
#include <boost/date_time/posix_time/posix_time.hpp>

namespace asio = boost::asio;
using boost::system::error_code;

class SandeshClient {
public:
    SandeshClient(asio::io_context& io_context, const std::string& server_address)
        : resolver_(io_context), socket_(io_context) {
        resolve(server_address);
    }

    void start() {
        do_connect();
    }

private:
    void resolve(const std::string& server_address) {
        asio::ip::tcp::resolver::query query(server_address, "80");
        resolver_.async_resolve(query,
            [this](error_code ec, asio::ip::tcp::resolver::results_type results) {
                if (!ec) {
                    do_connect(results);
                }
            });
    }

    void do_connect(asio::ip::tcp::resolver::results_type results) {
        boost::asio::async_connect(socket_, results,
            [this](error_code ec, asio::ip::tcp::endpoint endpoint) {
                if (!ec) {
                    do_read();
                } else {
                    BOOST_LOG_TRIVIAL(error) << "Connection failed: " << ec.message();
                }
            });
    }

    void do_read() {
        socket_.async_read_some(asio::buffer(data_, max_length),
            [this](error_code ec, std::size_t length) {
                if (!ec) {
                    BOOST_LOG_TRIVIAL(info) << "Received data: " << std::string(data_, length);
                    do_write(length);
                } else if (ec != asio::error::eof) {
                    BOOST_LOG_TRIVIAL(error) << "Read failed: " << ec.message();
                }
            });
    }

    void do_write(std::size_t length) {
        asio::async_write(socket_, asio::buffer(data_, length),
            [this](error_code ec, std::size_t /*length*/) {
                if (!ec) {
                    do_read();
                } else {
                    BOOST_LOG_TRIVIAL(error) << "Write failed: " << ec.message();
                }
            });
    }

    asio::ip::tcp::resolver resolver_;
    asio::ip::tcp::socket socket_;
    enum { max_length = 1024 };
    char data_[max_length];
};

int main() {
    try {
        asio::io_context io_context;
        SandeshClient client(io_context, "example.com");
        client.start();
        io_context.run();
    } catch (std::exception& e) {
        BOOST_LOG_TRIVIAL(error) << "Exception: " << e.what();
    }
    return 0;
}
```

