class HighPerformanceRNG {
public:
    HighPerformanceRNG(uint64_t seed) : gen(seed), dis(0, std::numeric_limits<uint32_t>::max()) {}

    uint32_t generate() {
        return dis(gen);
    }

private:
    std::mt19937_64 gen;
    std::uniform_int_distribution<uint32_t> dis;
};

void simulateNode(HighPerformanceRNG& rng, int nodeId) {
    for (int i = 0; i < 1000000; ++i) {
        uint32_t randomNumber = rng.generate();
        // Simulate using the random number
        std::cout << "Node " << nodeId << " generated: " << randomNumber << std::endl;
    }
}

int main() {
    const int numNodes = 4;
    const uint64_t seed = 1234567890;

    std::vector<HighPerformanceRNG> rngs(numNodes, HighPerformanceRNG(seed));

    std::vector<std::thread> nodes;
    for (int i = 0; i < numNodes; ++i) {
        nodes.emplace_back(simulateNode, std::ref(rngs[i]), i);
    }

    for (auto& thread : nodes) {
        thread.join();
    }

    return 0;
}
```

