using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;

public class UserDataRetriever
{
    public static DataTable RetrieveUserData(IDbConnection connection, FilterCriteria filterCriteria, List<string> columns)
    {
        using (var command = new SqlCommand())
        {
            command.Connection = connection;
            command.CommandType = CommandType.Text;

            // Construct the SQL query dynamically based on the filter criteria and columns
            string sqlQuery = "SELECT ";
            foreach (var column in columns)
            {
                sqlQuery += $"{column}, ";
            }
            sqlQuery = sqlQuery.TrimEnd(',', ' ') + " FROM Users";

            if (filterCriteria != null && filterCriteria.Filters.Count > 0)
            {
                sqlQuery += " WHERE ";
                for (int i = 0; i < filterCriteria.Filters.Count; i++)
                {
                    var filter = filterCriteria.Filters[i];
                    sqlQuery += $"{filter.Column} {filter.Operator} @Param{i}";
                    if (i < filterCriteria.Filters.Count - 1)
                    {
                        sqlQuery += " AND ";
                    }
                }
            }

            command.CommandText = sqlQuery;

            // Add parameters to the command
            for (int i = 0; i < filterCriteria?.Filters.Count ?? 0; i++)
            {
                var filter = filterCriteria.Filters[i];
                command.Parameters.AddWithValue($"@Param{i}", filter.Value);
            }

            // Execute the query and return the result as a DataTable
            using (var adapter = new SqlDataAdapter(command))
            {
                var dataTable = new DataTable();
                adapter.Fill(dataTable);
                return dataTable;
            }
        }
    }
}

public class FilterCriteria
{
    public List<Filter> Filters { get; set; }

    public FilterCriteria()
    {
        Filters = new List<Filter>();
    }
}

public class Filter
{
    public string Column { get; set; }
    public string Operator { get; set; }
    public object Value { get; set; }
}
```

