                    };
                    config.LevelDifficulties[i] = levelDifficulty;
                }
            }

            string spawnPointsJson = Environment.GetEnvironmentVariable("ENEMY_SPAWN_POINTS");
            if (!string.IsNullOrEmpty(spawnPointsJson))
            {
                var spawnPoints = JsonConvert.DeserializeObject<List<SpawnPoint>>(spawnPointsJson);
                config.EnemySpawnPoints.AddRange(spawnPoints);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading environment variables: {ex.Message}");
        }

        return config;
    }

    private static void MergeConfig(GameConfig target, GameConfig source)
    {
        // Merge logic for handling discrepancies between sources
        if (source.InitialPlayerHealth > 0) target.InitialPlayerHealth = source.InitialPlayerHealth;
        if (source.NumberOfLevels > 0) target.NumberOfLevels = source.NumberOfLevels;

        foreach (var levelDifficulty in source.LevelDifficulties)
        {
            if (!target.LevelDifficulties.ContainsKey(levelDifficulty.Key))
                target.LevelDifficulties[levelDifficulty.Key] = levelDifficulty.Value;
        }

        target.EnemySpawnPoints.AddRange(source.EnemySpawnPoints);
    }
