using System;
using System.Collections.Generic;
using System.IO;
using System.Xml.XPath;

public class DirectoryParser
{
    public static (object, string) ParseAndCreateDirectory(string xmlContent, string elementName, string baseDirPath, bool logDetails)
    {
        XPathDocument doc = new XPathDocument(new StringReader(xmlContent));
        XPathNavigator nav = doc.CreateNavigator();
        XPathNodeIterator nodes = nav.Select($"//{elementName}");

        List<string> paths = new List<string>();
        while (nodes.MoveNext())
        {
            string path = nodes.Current.GetAttribute("path", "");
            if (!string.IsNullOrEmpty(path))
            {
                paths.Add(Path.Combine(baseDirPath, path));
            }
        }

        if (paths.Count == 0)
        {
            return (null, "Element not found.");
        }
        else if (paths.Count > 1)
        {
            return (paths, "Multiple elements found.");
        }

        string newDirPath = Path.Combine(baseDirPath, elementName);
        if (!Directory.Exists(newDirPath))
        {
            try
            {
                Directory.CreateDirectory(newDirPath);
                Environment.SetEnvironmentVariable(elementName, newDirPath, EnvironmentVariableTarget.Process);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Failed to create directory: {ex.Message}");
                return (null, "Directory creation failed.");
            }
        }

        return (newDirPath, "Directory created successfully.");
    }
}
