import java.util.concurrent.locks.ReadWriteLock;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class HashProcessor {

    private static final String SECRET_KEY_CACHE_FILE = "secret_key_cache.txt";
    private static final long KEY_UPDATE_INTERVAL = 24 * 60 * 60 * 1000; // 24 hours
    private static final String FALLBACK_SECRET_KEY = "default_secret_key";

    private static String secretKey;
    private static long lastUpdateTimestamp;
    private static final ReadWriteLock lock = new ReentrantReadWriteLock();

    public static String customHash(String input) {
        try {
            // Trim and convert to lowercase
            String processedInput = input.trim().toLowerCase();

            // Remove non-alphanumeric characters except hyphens and underscores
            processedInput = processedInput.replaceAll("[^a-z0-9-_]", "");

            // Get the secret key with fallback mechanism
            String currentSecretKey = getSecretKey();

            // Compute the hash
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hashBytes = digest.digest((processedInput + currentSecretKey).getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : hashBytes) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }

            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            // Log error and return fallback hash
            logError("SHA-256 algorithm not found", e);
            return computeFallbackHash(input);
        }
    }

    private static String getSecretKey() {
        lock.readLock().lock();
        try {
            if (secretKey != null && System.currentTimeMillis() - lastUpdateTimestamp < KEY_UPDATE_INTERVAL) {
                return secretKey;
            }
        } finally {
            lock.readLock().unlock();
        }

        lock.writeLock().lock();
        try {
            // Check again in case another thread updated the key
            if (secretKey == null || System.currentTimeMillis() - lastUpdateTimestamp >= KEY_UPDATE_INTERVAL) {
                secretKey = fetchSecretKeyFromAPI();
                lastUpdateTimestamp = System.currentTimeMillis();
            }
            return secretKey;
        } finally {
            lock.writeLock().unlock();
        }
    }

    private static String fetchSecretKeyFromAPI() {
        // Implement secure API call to retrieve the secret key
        // Return the fetched secret key or null if failed
        return "fetched_secret_key";
    }

    private static String computeFallbackHash(String input) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hashBytes = digest.digest(input.getBytes());
            StringBuilder hexString = new StringBuilder();
            for (byte b : hashBytes) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            // Log error and return empty string
            logError("SHA-256 algorithm not found", e);
            return "";
        }
    }

    private static void logError(String message, Exception e) {
        // Implement centralized logging with structured data
        System.err.println("ERROR: " + message + " - " + e.getMessage());
    }
}
