    private $cache;

    public function __construct($db, $cache) {
        $this->db = $db;
        $this->cache = $cache;
    }

    public function manageUser($_REQUEST) {
        $id = isset($_REQUEST['id']) ? intval($_REQUEST['id']) : null;
        $name = $_REQUEST['name'] ?? '';
        $email = $_REQUEST['email'] ?? '';
        $password = $_REQUEST['password'] ?? '';
        $sub_action = $_REQUEST['sub_action'] ?? '';

        if ($sub_action === 'create') {
            return $this->createUser($id, $name, $email, $password);
        } elseif ($sub_action === 'update') {
            return $this->updateUser($id, $name, $email, $password);
        } elseif ($sub_action === 'delete') {
            return $this->deleteUser($id);
        } elseif ($sub_action === 'retrieve') {
            return $this->retrieveUser($id);
        } else {
