    public async Task UpdatePageAsync(string pageSectionId, Dictionary<string, string> elementUpdates)
    {
        if (!_rateLimiter.AllowRequest(HttpContext.Current.Request.UserHostAddress))
        {
            throw new RateLimitException("Too many requests from this IP address.");
        }

        try
        {
            _logger.LogInfo($"Starting batch update for page section: {pageSectionId}");

            foreach (var update in elementUpdates)
            {
                if (!IsValidHtml(update.Value))
                {
                    throw new InvalidHtmlException("Invalid HTML content provided.");
                }

                await _elementService.UpdateElementAsync(pageSectionId, update.Key, update.Value);
                _cachingService.InvalidateCacheItem(update.Key);
            }

            _logger.LogInfo($"Batch update completed for page section: {pageSectionId}");
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, $"Error during batch update for page section: {pageSectionId}");
