            state = (MoSTState) ois.readObject();
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        }
        return state;
    }

    public static void manageThemeCache() {
        synchronized (lock) {
            if (themeBitmap != null && !themeBitmap.isRecycled()) {
                themeBitmap.recycle();
                themeBitmap = null;
            }
            String themeDir = getThemeDirectory();
            if (themeDir == null || themeDir.isEmpty()) {
                setThemeDirectory(DEFAULT_THEME_DIR);
            }
        }
    }

    public static Bitmap parsePngFromCache(String cacheRoot) {
        Bitmap bitmap = null;
