const fs = require('fs').promises;
const path = require('path');
const LRU = require('lru-cache');

const cache = new LRU({ max: 100, maxAge: 1000 * 60 * 5 }); // Cache up to 100 files for 5 minutes

async function readFile(filePath) {
  try {
    if (cache.has(filePath)) {
      return cache.get(filePath);
    }

    const data = await fs.readFile(filePath);
    cache.set(filePath, data);
    return data;
  } catch (error) {
    console.error(`Error reading file ${filePath}:`, error);
    throw error;
  }
}

async function readDirectory(directoryPath) {
  try {
    const files = await fs.readdir(directoryPath);
    const results = [];

    for (const file of files) {
      const filePath = path.join(directoryPath, file);
      const stats = await fs.stat(filePath);

      if (stats.isDirectory()) {
        results.push(...(await readDirectory(filePath)));
      } else {
        results.push(await readFile(filePath));
      }
    }

    return results;
  } catch (error) {
    console.error(`Error reading directory ${directoryPath}:`, error);
    throw error;
  }
}

async function main() {
  try {
    const files = await readDirectory('/path/to/directory');
    console.log('Files:', files);
  } catch (error) {
    console.error('Main error:', error);
  }
}

main();
```

This code provides a basic implementation of an asynchronous file reader in JavaScript. It uses the `fs.promises` module for file operations and the `lru-cache` package for caching frequently accessed files. The `readFile` function reads a single file, caching its contents if they are not already cached. The `readDirectory` function recursively reads all files within a directory, including those in subdirectories. The `main` function demonstrates how to use these functions to read all files in a specified directory.

Please note that this code is a starting point and may need to be adapted to fit the specific requirements of your project."]

