async function manageTests(label, f, options = {}) {
  const { cacheEnabled = false } = options;
  const testCache = new Map();

  try {
    console.log(`Starting tests for module: ${label}`);

    if (cacheEnabled && testCache.has(label)) {
      console.log(`Using cached results for module: ${label}`);
      return testCache.get(label);
    }

    const module = require(label);
    const testResults = [];

    for (const [testName, testFunction] of Object.entries(module.tests)) {
      if (typeof testFunction !== 'function') {
        console.error(`Invalid test function for: ${testName}`);
        continue;
      }

      console.log(`Running test: ${testName}`);
      const startTime = performance.now();

      try {
        await testFunction();
        testResults.push({ testName, status: 'Passed', duration: performance.now() - startTime });
      } catch (error) {
        testResults.push({ testName, status: 'Failed', error, duration: performance.now() - startTime });
      }
    }

    if (cacheEnabled) {
      testCache.set(label, testResults);
    }

    console.log(`Finished tests for module: ${label}`);
    return testResults;
  } catch (error) {
    console.error(`Error managing tests for module: ${label}`, error);
    throw error;
  }
}
