class DataProcessingService {
  constructor(storage, messagingSystem) {
    this.storage = storage;
    this.messagingSystem = messagingSystem;
    this.isRunning = false;
    this.dataQueue = [];
    this.processingInterval = null;
  }

  start() {
    if (this.isRunning) return;

    this.isRunning = true;
    this.processingInterval = setInterval(this.processData.bind(this), 100);
  }

  pause() {
    if (!this.isRunning) return;

    this.isRunning = false;
    clearInterval(this.processingInterval);
  }

  resume() {
    if (this.isRunning) return;

    this.isRunning = true;
    this.processingInterval = setInterval(this.processData.bind(this), 100);
  }

  stop() {
    this.pause();
    this.notifyStop();
  }

  notifyStop() {
    this.messagingSystem.sendNotification('Service stopped');
  }

  processData() {
    if (this.dataQueue.length === 0) return;

    const data = this.dataQueue.shift();
    try {
      // Process data and store it
      this.storage.save(data);
    } catch (error) {
      // Handle processing error, e.g., retry or log
      console.error('Error processing data:', error);
      this.dataQueue.unshift(data); // Retry on next cycle
    }
  }

  enqueueData(data) {
    this.dataQueue.push(data);
  }
}

// Example usage:
const storage = {
  save: (data) => {
    // Save data to persistent storage
  }
};

const messagingSystem = {
  sendNotification: (message) => {
    // Send notification via external messaging system
  }
};

const service = new DataProcessingService(storage, messagingSystem);
