<?php

class UserUpdater {
    private $db;
    private $validationService;

    public function __construct($db, $validationService) {
        $this->db = $db;
        $this->validationService = $validationService;
    }

    public function updateUsers($updates, $retryLimit = 3) {
        $results = [
            'successful' => 0,
            'failedValidation' => [],
            'runtimeErrors' => []
        ];

        foreach ($updates as $userId => $data) {
            for ($attempt = 1; $attempt <= $retryLimit; $attempt++) {
                try {
                    if (!$this->validateData($data)) {
                        $results['failedValidation'][$userId] = $data;
                        break;
                    }

                    $this->db->beginTransaction();
                    $this->updateUser($userId, $data);
                    $this->db->commit();

                    $results['successful']++;
                    break;
                } catch (\Exception $e) {
                    if ($attempt == $retryLimit) {
                        $results['runtimeErrors'][$userId] = [
                            'data' => $data,
                            'error' => $e->getMessage()
                        ];
                    }
                    $this->db->rollBack();
                }
            }
        }

        return $results;
    }

    private function validateData($data) {
        // Integrate with external validation service
        return $this->validationService->validate($data);
    }

    private function updateUser($userId, $data) {
        // Perform database update operation
        $query = "UPDATE users SET name = :name, email = :email WHERE id = :id";
        $stmt = $this->db->prepare($query);
        $stmt->execute([':name' => $data['name'], ':email' => $data['email'], ':id' => $userId]);
    }
}

// Usage example
$db = new PDO('mysql:host=localhost;dbname=test', 'username', 'password');
$validationService = new ExternalValidationService();
$userUpdater = new UserUpdater($db, $validationService);

$updates = [
    1 => ['name' => 'John Doe', 'email' => 'john@example.com'],
    2 => ['name' => 'Jane Smith', 'email' => 'jane@example.com']
];

$results = $userUpdater->updateUsers($updates);
print_r($results);
?>
