import requests
from functools import lru_cache
from typing import Dict, Optional

API_KEY = 'your_api_key_here'
BASE_URL = 'https://api.example.com/users'

@lru_cache(maxsize=128)
def fetch_user_details(user_id: str) -> Dict[str, Optional[str]]:
    headers = {
        'Authorization': f'Bearer {API_KEY}',
        'Content-Type': 'application/json'
    }
    params = {
        'user_id': user_id
    }
    try:
        response = requests.get(f'{BASE_URL}/{user_id}', headers=headers, params=params)
        response.raise_for_status()
        return response.json()
    except requests.RequestException as e:
        print(f"Error fetching user details: {e}")
        return {}

def get_user_details(user_id: str) -> Dict[str, Optional[str]]:
    # Invalidate cache when user ID changes
    fetch_user_details.cache_clear()
    return fetch_user_details(user_id)

# Example usage
