// Generate Session Token in Node.js
const crypto = require('crypto');
const fs = require('fs');

function generateSessionToken(credentials) {
    const secretKey = fs.readFileSync('/path/to/secret/key', 'utf8').trim();
    const tokenData = credentials.userId + secretKey;

    try {
        const hash = crypto.createHmac('sha256', secretKey).update(tokenData).digest('hex');
        const expirationTime = Date.now() + 3600 * 1000; // Token expires in 1 hour
        return { token: hash, expiration: expirationTime };
    } catch (error) {
        console.error("Error generating session token:", error);
        throw error;
    }
}
