["```javascript
const axios = require('axios');
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

class CertificateGenerator {
  constructor(privateKeyUrl, certificateUrl, cacheDir) {
    this.privateKeyUrl = privateKeyUrl;
    this.certificateUrl = certificateUrl;
    this.cacheDir = cacheDir;
    this.cache = {};
    this.isPaused = false;
    this.metrics = [];
  }

  async fetchResource(url, cacheKey) {
    if (this.cache[cacheKey]) return this.cache[cacheKey];
    try {
      const response = await axios.get(url);
      this.cache[cacheKey] = response.data;
      fs.writeFileSync(path.join(this.cacheDir, `${cacheKey}.pem`), response.data);
      return response.data;
    } catch (error) {
      console.error(`Failed to fetch ${url}:`, error);
      throw error;
    }
  }

  async generateCertificate() {
    if (this.isPaused) return;

    const privateKey = await this.fetchResource(this.privateKeyUrl, 'privateKey');
    const certificate = await this.fetchResource(this.certificateUrl, 'certificate');

    // Simulate certificate generation
    const pem = crypto.createSign('SHA256').update(privateKey + certificate).sign(privateKey, 'pem');
    return pem;
  }

  pause() {
    this.isPaused = true;
  }

  resume() {
    this.isPaused = false;
  }

  logMetric(metric) {
    this.metrics.push(metric);
    fs.writeFileSync(path.join(__dirname, 'metrics.json'), JSON.stringify(this.metrics));
  }
}

// Usage example
const generator = new CertificateGenerator('https://example.com/privateKey', 'https://example.com/certificate', '/path/to/cache');
generator.generateCertificate().then(pem => {
  console.log('Generated certificate:', pem);
}).catch(error => {
  console.error('Error generating certificate:', error);
});
