#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <openssl/ssl.h>
#include <openssl/err.h>

typedef struct {
    char *ip_address;
    char *access_token;
} UserSession;

UserSession* authenticateUserWithDNS(const char *hostname, const char *username, const char *password, int dns_timeout, int oauth_timeout, int retry_count) {
    // DNS resolution
    struct addrinfo hints, *res, *p;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4 only
    hints.ai_socktype = SOCK_STREAM;

    int status;
    for (int i = 0; i < retry_count; ++i) {
        if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
            fprintf(stderr, "DNS resolution failed: %s\n", gai_strerror(status));
            sleep(dns_timeout);
            continue;
        }
        break;
    }

    if (status != 0) {
        return NULL; // DNS resolution failed after retries
    }

    char ip_address[INET_ADDRSTRLEN];
    for (p = res; p != NULL; p = p->ai_next) {
        void *addr;
        struct sockaddr_in *ipv4;

        ipv4 = (struct sockaddr_in *)p->ai_addr;
        addr = &(ipv4->sin_addr);

        inet_ntop(p->ai_family, addr, ip_address, sizeof(ip_address));
    }

    freeaddrinfo(res); // Free the linked list

    // OAuth 2.0 authentication
    SSL_CTX *ctx = SSL_CTX_new(TLS_client_method());
    if (!ctx) {
        fprintf(stderr, "Failed to create SSL context\n");
        return NULL;
    }

    int sock = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(443); // Assuming OAuth uses HTTPS on port 443
    inet_pton(AF_INET, ip_address, &server_addr.sin_addr);

    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Failed to connect to server\n");
        SSL_CTX_free(ctx);
        return NULL;
    }

    SSL *ssl = SSL_new(ctx);
    SSL_set_fd(ssl, sock);

    if (SSL_connect(ssl) <= 0) {
        ERR_print_errors_fp(stderr);
        SSL_free(ssl);
        close(sock);
        SSL_CTX_free(ctx);
        return NULL;
    }

    // Perform OAuth 2.0 token exchange
    char request[1024];
    snprintf(request, sizeof(request), "POST /token HTTP/1.1\r\nHost: %s\r\nContent-Type: application/x-www-form-urlencoded\r\nAuthorization: Basic %s\r\nContent-Length: %zu\r\n\r\ngrant_type=password&username=%s&password=%s",
             hostname,
             // Base64 encode client_id:client_secret
             "dXNlcm5hbWU6cGFzc3dvcmQ=",
             strlen("grant_type=password&username=") + strlen(username) + strlen("&password=") + strlen(password),
             username, password);

    SSL_write(ssl, request, strlen(request));

    char response[4096];
    int bytes_received = SSL_read(ssl, response, sizeof(response) - 1);
    if (bytes_received <= 0) {
        ERR_print_errors_fp(stderr);
        SSL_free(ssl);
        close(sock);
        SSL_CTX_free(ctx);
        return NULL;
    }
    response[bytes_received] = '\0';

    // Parse the JSON response to extract access token
    char *access_token_start = strstr(response, "\"access_token\":\"");
    if (!access_token_start) {
        fprintf(stderr, "Failed to parse access token from response\n");
        SSL_free(ssl);
        close(sock);
        SSL_CTX_free(ctx);
        return NULL;
    }

    access_token_start += strlen("\"access_token\":\"");
    char *access_token_end = strstr(access_token_start, "\"");
    if (!access_token_end) {
        fprintf(stderr, "Failed to parse access token from response\n");
        SSL_free(ssl);
        close(sock);
        SSL_CTX_free(ctx);
        return NULL;
    }

    size_t access_token_len = access_token_end - access_token_start;
    char *access_token = (char *)malloc(access_token_len + 1);
    strncpy(access_token, access_token_start, access_token_len);
    access_token[access_token_len] = '\0';

    SSL_free(ssl);
    close(sock);
    SSL_CTX_free(ctx);

    // Store the session data
    UserSession *session = (UserSession *)malloc(sizeof(UserSession));
    session->ip_address = strdup(ip_address);
    session->access_token = access_token;

    return session;
}
