<?php

class UserService {
    private $database;
    private $cache;
    private $rateLimiter;
    private $logger;
    private $messageQueue;

    public function __construct($database, $cache, $rateLimiter, $logger, $messageQueue) {
        $this->database = $database;
        $this->cache = $cache;
        $this->rateLimiter = $rateLimiter;
        $this->logger = $logger;
        $this->messageQueue = $messageQueue;
    }

    public function updatePassword($userId, $newPassword) {
        if (!$this->rateLimiter->allowUpdate($userId)) {
            throw new Exception("Too many password updates. Please try again later.");
        }

        if (!$this->validatePasswordStrength($newPassword)) {
            throw new Exception("Password does not meet the strength requirements.");
        }

        $hashedPassword = password_hash($newPassword, PASSWORD_BCRYPT);

        $this->database->beginTransaction();
        try {
            $this->database->updateUserPassword($userId, $hashedPassword);
            $this->cache->invalidateUserCache($userId);
            $this->messageQueue->enqueue('password_update', ['user_id' => $userId]);
            $this->logger->log('PASSWORD_UPDATE', ['user_id' => $userId, 'new_password_hash' => $hashedPassword]);
            $this->database->commit();
        } catch (Exception $e) {
            $this->database->rollBack();
            throw $e;
        }
    }

    private function validatePasswordStrength($password) {
        // Implement password strength validation logic here
        return strlen($password) >= 8 && preg_match('/[a-z]/', $password) && preg_match('/[A-Z]/', $password) && preg_match('/\d/', $password);
    }
}

