        return NULL;
    }

    State* newState = (State*)malloc(sizeof(State));
    if (!newState) {
        return NULL;
    }
    newState->id = newStateId;

    for (int i = 0; i < 256; i++) {
        newState->transitions[i] = NULL;
    }

    stateList[*numStates] = newState;
    (*numStates)++;
    return newState;
}

bool removeState(State** stateList, int* numStates, FSA* fsa, int stateId) {
    for (int i = 0; i < *numStates; i++) {
        if (stateList[i]->id == stateId) {
            free(stateList[i]);
            for (int j = i; j < *numStates - 1; j++) {
                stateList[j] = stateList[j + 1];
            }
            (*numStates)--;
            return true;
        }
    }
    return false;
}

State** manageStateList(State** stateList, int* numStates, FSA* fsa, int newStateId, int lastStateId) {
    State* newState = addState(stateList, numStates, fsa, newStateId);
    if (!newState) {
        return NULL;
    }

    // Assuming a simple transition from the last state to the new state
    if (lastStateId >= 0 && lastStateId < *numStates) {
        stateList[lastStateId]->transitions[newState->id] = newState;
    } else {
        free(newState);
        return NULL;
    }

    // Update 'next' pointer of the last state
    if (*numStates > 1) {
        stateList[*numStates - 2]->transitions[stateList[*numStates - 1]->id] = stateList[*numStates - 1];
    }

    return stateList;
}
