#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_PACKETS 10000
#define SLIDING_WINDOW_SIZE 60

typedef struct {
    int id;
    time_t timestamp;
    int sequence_number;
    int payload_size;
} Packet;

typedef struct {
    Packet packets[MAX_PACKETS];
    int front, rear;
    int size;
    pthread_mutex_t lock;
    pthread_cond_t not_full, not_empty;
} Queue;

Queue packet_queue;

void init_queue(Queue *q) {
    q->front = q->rear = -1;
    q->size = 0;
    pthread_mutex_init(&q->lock, NULL);
    pthread_cond_init(&q->not_full, NULL);
    pthread_cond_init(&q->not_empty, NULL);
}

int is_full(Queue *q) {
    return q->size == MAX_PACKETS;
}

int is_empty(Queue *q) {
    return q->size == 0;
}

void enqueue(Queue *q, Packet packet) {
    pthread_mutex_lock(&q->lock);
    while (is_full(q)) {
        pthread_cond_wait(&q->not_full, &q->lock);
    }
    if (is_empty(q)) {
        q->front = q->rear = 0;
    } else {
        q->rear = (q->rear + 1) % MAX_PACKETS;
    }
    q->packets[q->rear] = packet;
    q->size++;
    pthread_cond_signal(&q->not_empty);
    pthread_mutex_unlock(&q->lock);
}

Packet dequeue(Queue *q) {
    Packet packet;
    pthread_mutex_lock(&q->lock);
    while (is_empty(q)) {
        pthread_cond_wait(&q->not_empty, &q->lock);
    }
    packet = q->packets[q->front];
    if (q->front == q->rear) {
        q->front = q->rear = -1;
    } else {
        q->front = (q->front + 1) % MAX_PACKETS;
    }
    q->size--;
    pthread_cond_signal(&q->not_full);
    pthread_mutex_unlock(&q->lock);
    return packet;
}

void *process_packets(void *arg) {
    Queue *queue = (Queue *)arg;
    while (1) {
        Packet packet = dequeue(queue);
        // Apply filtering criteria and update statistics
        // Persist packet metadata to external database
    }
    return NULL;
}

int main() {
    init_queue(&packet_queue);

    pthread_t threads[5];
    for (int i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, process_packets, &packet_queue);
    }

    // Simulate packet processing
    for (int i = 0; i < 10000; i++) {
        Packet packet;
        packet.id = i;
        packet.timestamp = time(NULL);
        packet.sequence_number = rand() % 1000;
        packet.payload_size = rand() % 1024;
        enqueue(&packet_queue, packet);
    }

    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
