class GameCharacter {
public:
    GameCharacter(int id) : characterID(id), lastAttackTime(0), cooldown(false) {}

    void attack() {
        std::unique_lock<std::mutex> lock(mutex);
        while (cooldown && std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now() - lastAttackTime).count() < 9) {
            cv.wait(lock, [this] { return !cooldown; });
        }
        if (!cooldown) {
            int selectedAttack = rand() % 4 + 1;
            std::cout << "Character " << characterID << " attacks with attack number: " << selectedAttack << std::endl;
            lastAttackTime = std::chrono::system_clock::now();
            cooldown = true;
        }
    }

    void executeQueuedAttacks() {
        std::unique_lock<std::mutex> lock(mutex);
        if (cooldown) {
            cv.notify_all();
            cooldown = false;
        }
    }

private:
    int characterID;
    std::chrono::time_point<std::chrono::system_clock> lastAttackTime;
    bool cooldown;
    std::mutex mutex;
    std::condition_variable cv;
};

int main() {
    const int numCharacters = 1000;
    std::vector<GameCharacter> characters(numCharacters);

    // Simulate concurrent attacks
    for (int i = 0; i < numCharacters; ++i) {
        std::thread t(&GameCharacter::attack, &characters[i]);
        t.detach();
    }

    // Execute queued attacks after a delay
    std::this_thread::sleep_for(std::chrono::seconds(10));
    for (int i = 0; i < numCharacters; ++i) {
        characters[i].executeQueuedAttacks();
    }

    return 0;
}
