    private readonly double _minValue;
    private readonly double _maxValue;
    private readonly bool _isInclusiveMin;
    private readonly bool _isInclusiveMax;

    public static void ValidateRange(double minValue, double maxValue, bool isInclusiveMin = true, bool isInclusiveMax = true)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");
        // Additional validation logic can be added here
    }

    public CustomRandomGenerator(double minValue, double maxValue, bool isInclusiveMin = true, bool isInclusiveMax = true)
    {
        ValidateRange(minValue, maxValue, isInclusiveMin, isInclusiveMax);
        _minValue = minValue;
        _maxValue = maxValue;
        _isInclusiveMin = isInclusiveMin;
        _isInclusiveMax = isInclusiveMax;
        _random = new Random();
    }

    public int GenerateRandomInt()
    {
        double randomValue = _random.NextDouble() * (_maxValue - _minValue) + _minValue;
        if (_isInclusiveMin && _isInclusiveMax)
            return (int)Math.Round(randomValue);
        else if (_isInclusiveMin)
            return (int)Math.Ceiling(randomValue);
        else if (_isInclusiveMax)
            return (int)Math.Floor(randomValue);
        else
            return (int)Math.Truncate(randomValue);
    }

    public float GenerateRandomFloat()
    {
        double randomValue = _random.NextDouble() * (_maxValue - _minValue) + _minValue;
        if (_isInclusiveMin && _isInclusiveMax)
            return (float)Math.Round(randomValue, MidpointRounding.AwayFromZero);
        else if (_isInclusiveMin)
            return (float)Math.Ceiling(randomValue);
        else if (_isInclusiveMax)
            return (float)Math.Floor(randomValue);
        else
            return (float)Math.Truncate(randomValue);
    }

    public override string ToString()
    {
        return $"CustomRandomGenerator: Min={_minValue}, Max={_maxValue}, InclusiveMin={_isInclusiveMin}, InclusiveMax={_isInclusiveMax}";
    }
}
