#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

#define MAX_LINE_LENGTH 256

int apply_env_from_file(const char *file_path) {
    int fd = open(file_path, O_RDONLY);
    if (fd == -1) {
        perror("Failed to open file");
        return -1;
    }

    struct stat file_stat;
    if (fstat(fd, &file_stat) == -1) {
        perror("Failed to get file stats");
        close(fd);
        return -1;
    }

    char *buffer = malloc(file_stat.st_size + 1);
    if (!buffer) {
        perror("Failed to allocate memory for buffer");
        close(fd);
        return -1;
    }

    ssize_t bytes_read = read(fd, buffer, file_stat.st_size);
    if (bytes_read == -1) {
        perror("Failed to read file");
        free(buffer);
        close(fd);
        return -1;
    }
    buffer[bytes_read] = '\0';

    int applied_count = 0;

    char *line = strtok(buffer, "\n");
    while (line != NULL) {
        char *key_value = strchr(line, '=');
        if (key_value && key_value > line) {
            *key_value++ = '\0';
            if (setenv(line, key_value, 1) == 0) {
                applied_count++;
            } else {
                perror("Failed to set environment variable");
            }
        }
        line = strtok(NULL, "\n");
    }

    free(buffer);
    close(fd);

    return applied_count;
}

int main() {
    const char *config_file_path = "/path/to/config/file.env";
    int result = apply_env_from_file(config_file_path);
    if (result != -1) {
        printf("Successfully applied %d environment variables.\n", result);
    }
    return 0;
}
```

