// string_manipulation.h
#ifndef STRING_MANIPULATION_H
#define STRING_MANIPULATION_H

#include <stddef.h>

typedef void (*StringCallback)(const char*);

char* processString(const char* input, size_t limit, StringCallback callback);

#endif // STRING_MANIPULATION_H

// string_manipulation.c
#include "string_manipulation.h"
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

char* processString(const char* input, size_t limit, StringCallback callback) {
    pthread_mutex_lock(&mutex);
    if (strlen(input) >= limit - 1) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    char* result = realloc((char*)input, limit + 1);
    if (!result) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    strcat(result, ",");
    callback(result);

    pthread_mutex_unlock(&mutex);
    return result;
}

