#include <string.h>

static int matchesSelector(const char* tag, const char* selector) {
    // Simple selector matching logic (e.g., only checks for tag name)
    return strcmp(tag, selector) == 0;
}

void findElementsBySelector(Node* root, const char* selector, ElementCallback callback) {
    if (!root || !selector) return;

    if (matchesSelector(root->tag, selector)) {
        callback(root);
    }

    for (size_t i = 0; i < root->childCount; ++i) {
        findElementsBySelector(root->children[i], selector, callback);
    }
}
