        if (!File.Exists(filePath))
            throw new FileNotFoundException("The specified file does not exist.", filePath);

        using (var stream = File.OpenRead(filePath))
        {
            var metadata = ParseTIFFMetadata(stream);
            var hash = await ComputeMD5HashAsync(stream);

            // Store or retrieve the hash and metadata from the external data source
            await _dataSource.StoreImageInfo(filePath, metadata, hash);

            return new ImageMetadataWithHash { Metadata = metadata, Hash = hash };
        }
    }

    private ImageMetadata ParseTIFFMetadata(Stream stream)
    {
        // Implement TIFF parsing logic here
        // This is a placeholder for the actual implementation
        var metadata = new ImageMetadata
        {
            BitsPerSample = 8,
            SamplesPerPixel = 3,
            ExtraSamples = new[]
            {
                new ExtraSampleInfo { SampleIndex = 1, Description = "Alpha" }
            }
        };
        return metadata;
    }

    private async Task<string> ComputeMD5HashAsync(Stream stream)
    {
        using (var md5 = MD5.Create())
        {
            var hashBytes = await md5.ComputeHashAsync(stream);
            return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
        }
    }
}

