#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_FILENAME_LENGTH 256
#define MAX_EXTENSION_LENGTH 10

void process_filename(const char *input_filename, char *output_filename) {
    if (strlen(input_filename) > MAX_FILENAME_LENGTH) {
        input_filename = &input_filename[strlen(input_filename) - MAX_FILENAME_LENGTH];
    }

    const char *last_segment = strrchr(input_filename, '/');
    if (last_segment == NULL) {
        last_segment = input_filename;
    } else {
        last_segment++;
    }

    int vowel_count = 0;
    for (int i = 0; last_segment[i] != '\0'; i++) {
        if (strchr("aeiouAEIOU", last_segment[i]) != NULL) {
            vowel_count++;
        }
    }

    char temp_filename[MAX_FILENAME_LENGTH];
    snprintf(temp_filename, sizeof(temp_filename), "%s_%03d", last_segment, vowel_count);

    int new_extension_length = strlen(strrchr(input_filename, '.')) + 4;
    if (new_extension_length > MAX_EXTENSION_LENGTH) {
        new_extension_length = MAX_EXTENSION_LENGTH;
    }

    strlcpy(output_filename, input_filename, sizeof(output_filename));
    output_filename[strlen(output_filename) - strlen(last_segment)] = '\0';
    strcat(output_filename, temp_filename);
    strncat(output_filename, strrchr(input_filename, '.'), new_extension_length);
}

int main() {
    char filename[MAX_FILENAME_LENGTH] = "path/to/your/file name.txt";
    char processed_filename[MAX_FILENAME_LENGTH];

    process_filename(filename, processed_filename);

    printf("Original: %s\n", filename);
    printf("Processed: %s\n", processed_filename);

    return 0;
}
