void initialize_crypto_library() {
    // Initialize OpenSSL library
    SSL_library_init();
    OpenSSL_add_all_algorithms();
    ERR_load_crypto_strings();

    // Add AES cipher to the EVP library
    EVP_add_cipher(EVP_aes_256_cbc());

    // Add Camellia cipher to the EVP library
    EVP_add_cipher(EVP_camellia_256_cbc());

    // Add MD5 digest to the EVP library
    EVP_add_digest(EVP_md5());

    // Add SHA-256 digest to the EVP library
    EVP_add_digest(EVP_sha256());

    // Establish aliases for SHA-256
    EVP_add_digest_alias("SHA256", "sha256");
    EVP_add_digest_alias("SHA-256", "sha256");

    // Initialize thread safety for OpenSSL functions
    CRYPTO_set_id_callback((unsigned long (*)())pthread_self);
    CRYPTO_set_locking_callback((void (*)(int, int, const char *, int))openssl_thread_locking_function);

    // Set up logging and error handling
    ERR_load_crypto_strings();
}

void openssl_thread_locking_function(int mode, int type, const char *file, int line) {
    static pthread_mutex_t *mutexes = NULL;
    if (mode & CRYPTO_LOCK) {
        pthread_mutex_lock(&mutexes[type]);
    } else {
        pthread_mutex_unlock(&mutexes[type]);
    }
}

void initialize_threading() {
    // Initialize mutexes for OpenSSL thread safety
    int num_locks = CRYPTO_num_locks();
    mutexes = (pthread_mutex_t *)malloc(num_locks * sizeof(pthread_mutex_t));
    for (int i = 0; i < num_locks; i++) {
        pthread_mutex_init(&mutexes[i], NULL);
    }
}

void cleanup_crypto_library() {
    // Clean up OpenSSL library
    EVP_cleanup();
    ERR_free_strings();
    CRYPTO_set_id_callback(NULL);
    CRYPTO_set_locking_callback(NULL);

    // Free mutexes for OpenSSL thread safety
    int num_locks = CRYPTO_num_locks();
    for (int i = 0; i < num_locks; i++) {
        pthread_mutex_destroy(&mutexes[i]);
    }
    free(mutexes);
}

void *crypto_thread_function(void *arg) {
    // Example usage of cryptographic functions
    EVP_CIPHER_CTX *ctx;
    ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        fprintf(stderr, "Failed to create cipher context\n");
        return NULL;
    }

    // Perform cryptographic operations here

    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

int main() {
    initialize_threading();
    initialize_crypto_library();

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, crypto_thread_function, NULL);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    cleanup_crypto_library();
    return 0;
}
