// Function to initialize AES-256-CBC cipher
EVP_CIPHER_CTX* init_aes_cipher(const char* password, unsigned char** key, unsigned char** iv) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return NULL;

    // Derive key using PBKDF2
    const int key_len = 32; // AES-256 key length
    *key = (unsigned char*)malloc(key_len);
    if (!*key) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    if (!PKCS5_PBKDF2_HMAC(password, strlen(password), NULL, 0, 10000, EVP_sha256(), key_len, *key)) {
        free(*key);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Generate random IV
    *iv = (unsigned char*)malloc(16); // AES block size
    if (!*iv) {
        free(*key);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    if (!RAND_bytes(*iv, 16)) {
        free(*key);
        free(*iv);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Initialize cipher
    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, *key, *iv)) {
        free(*key);
        free(*iv);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

// Function to clean up AES cipher resources
void cleanup_aes_cipher(EVP_CIPHER_CTX* ctx, unsigned char* key, unsigned char* iv) {
    if (ctx) EVP_CIPHER_CTX_free(ctx);
    if (key) free(key);
    if (iv) free(iv);
}
