#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <signal.h>

#define MAX_TASKS 100

typedef struct {
    char command[256];
    int timeout;
    int dependencies[MAX_TASKS];
    int num_dependencies;
} Task;

Task tasks[MAX_TASKS];
int task_count = 0;

void* execute_task(void* arg) {
    int task_id = *(int*)arg;
    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return NULL;
    } else if (pid == 0) {
        // Child process
        char* args[257];
        args[0] = strtok(tasks[task_id].command, " ");
        for (int i = 1; args[i-1]; i++) {
            args[i] = strtok(NULL, " ");
        }
        execvp(args[0], args);
        perror("execvp");
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        int status;
        if (waitpid(pid, &status, 0) == -1) {
            perror("waitpid");
        }
        if (WIFEXITED(status)) {
            printf("Task %d completed with status %d\n", task_id, WEXITSTATUS(status));
        } else if (WIFSIGNALED(status)) {
            printf("Task %d terminated by signal %d\n", task_id, WTERMSIG(status));
        }
    }
    free(arg);
    return NULL;
}

void* manage_tasks(void* arg) {
    int i;
    for (i = 0; i < task_count; i++) {
        pthread_t thread;
        if (pthread_create(&thread, NULL, execute_task, &i) != 0) {
            perror("pthread_create");
            break;
        }
        pthread_detach(thread);
    }
    return NULL;
}

void handle_signal(int sig) {
    printf("Received signal %d\n", sig);
    // Implement graceful shutdown here
    exit(EXIT_SUCCESS);
}

int main() {
    // Initialize tasks from configuration file
    task_count = 0; // Populate tasks array with actual data

    pthread_t manager_thread;
    if (pthread_create(&manager_thread, NULL, manage_tasks, NULL) != 0) {
        perror("pthread_create");
        return EXIT_FAILURE;
    }
    pthread_detach(manager_thread);

    signal(SIGTERM, handle_signal);
    signal(SIGINT, handle_signal);

    // Main loop to keep the parent process running
    while (1) {
        sleep(1);
    }

    return EXIT_SUCCESS;
}
