using System.Net;
using System.Text.RegularExpressions;
using System.Threading.Tasks;

public class WebsiteManager
{
    private static readonly Regex validPathRegex = new Regex(@"^[a-zA-Z0-9\-\.\/]+$");

    public async Task<string> AddAndStartWebsiteAsync(string directoryPath, string siteName, int timeoutSeconds)
    {
        if (!validPathRegex.IsMatch(directoryPath))
        {
            LogError("Invalid directory path.");
            return null;
        }

        if (!Directory.Exists(Path.Combine(directoryPath, "web.config")) || !File.Exists(Path.Combine(directoryPath, "appsettings.json")))
        {
            LogError("Missing web.config or appsettings.json file.");
            return null;
        }

        try
        {
            var process = new Process
            {
                StartInfo =
                {
                    FileName = "dotnet",
                    Arguments = $"run --project {directoryPath}",
                    RedirectStandardOutput = true,
                    UseShellExecute = false,
                    CreateNoWindow = true
                }
            };

            using (process)
            {
                process.Start();

                if (!await Task.Run(() => process.WaitForExitAsync(timeoutSeconds * 1000)))
                {
                    LogError("Website startup timed out.");
                    process.Kill();
                    return "Timeout";
                }

                if (process.ExitCode != 0)
                {
                    LogError($"Website startup failed with exit code {process.ExitCode}.");
                    return "Failed";
                }

                return siteName;
            }
        }
        catch (Exception ex)
        {
            LogError($"An error occurred: {ex.Message}");
            return null;
        }
    }

    private static void LogError(string message)
    {
        Console.Error.WriteLine(message);
    }
}
