import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.concurrent.TimeUnit;

public class ScriptExecutor {

    public static void main(String[] args) {
        // User-defined parameters
        String scriptContent = "echo 'Hello, World!'";
        Path scriptPath = Paths.get("dynamic_script.sh");
        String[] command = {"bash", scriptPath.toString()};

        try {
            // Create and write the shell script
            Files.write(scriptPath, scriptContent.getBytes());
            scriptPath.toFile().setExecutable(true);

            // Execute the script using ProcessBuilder
            ProcessBuilder processBuilder = new ProcessBuilder(command);
            processBuilder.redirectErrorStream(true);
            Process process = processBuilder.start();

            // Capture and log output
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }

            // Wait for the script to complete and capture exit code
            int exitCode = process.waitFor();
            System.out.println("Script exited with code: " + exitCode);

        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }
}
