using System;
using System.Data;
using System.Data.SqlClient;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class DatabaseService
{
    private readonly string _connectionString;
    private readonly int _maxRetries = 3;
    private readonly TimeSpan _retryDelay = TimeSpan.FromSeconds(1);

    public DatabaseService(string connectionString)
    {
        _connectionString = connectionString;
    }

    public async Task<DataTableReader> GetDataAsync(byte[] byteArray)
    {
        using (var connection = new SqlConnection(_connectionString))
        {
            await connection.OpenAsync();
            var command = new SqlCommand("GetDataTable", connection);
            command.CommandType = CommandType.StoredProcedure;

            // Add parameters to the command
            command.Parameters.Add("@ByteArray", SqlDbType.VarBinary).Value = byteArray;

            try
            {
                using (var reader = await command.ExecuteReaderAsync(CommandBehavior.SequentialAccess))
                {
                    return reader;
                }
            }
            catch (SqlException ex)
            {
                if (ex.Number == -2) // Timeout error
                {
                    for (int i = 1; i <= _maxRetries; i++)
                    {
                        await Task.Delay(_retryDelay);
                        try
                        {
                            using (var reader = await command.ExecuteReaderAsync(CommandBehavior.SequentialAccess))
                            {
                                return reader;
                            }
                        }
                        catch (SqlException)
                        {
                            if (i == _maxRetries) throw;
                        }
                    }
                }
                throw;
            }
        }
    }

    public async Task<byte[]> EncryptDataAsync(byte[] data, byte[] key, byte[] iv)
    {
        using (Aes aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;

            ICryptoTransform encryptor = aes.CreateEncryptor(aes.Key, aes.IV);

            using (MemoryStream msEncrypt = new MemoryStream())
            {
                using (CryptoStream csEncrypt = new CryptoStream(msEncrypt, encryptor, CryptoStreamMode.Write))
                {
                    await csEncrypt.WriteAsync(data, 0, data.Length);
                }
                return msEncrypt.ToArray();
            }
        }
    }

    public async Task<byte[]> DecryptDataAsync(byte[] encryptedData, byte[] key, byte[] iv)
    {
        using (Aes aes = Aes.Create())
        {
            aes.Key = key;
            aes.IV = iv;

            ICryptoTransform decryptor = aes.CreateDecryptor(aes.Key, aes.IV);

            using (MemoryStream msDecrypt = new MemoryStream(encryptedData))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    byte[] decryptedBytes = new byte[encryptedData.Length];
                    int bytesRead = await csDecrypt.ReadAsync(decryptedBytes, 0, decryptedBytes.Length);
                    return decryptedBytes.Take(bytesRead).ToArray();
                }
            }
        }
    }
}
