using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

public class EncryptionProcessor
{
    private readonly string _encryptionAlgorithm;
    private readonly int _pbkdf2Iterations;
    private readonly ILogger _logger;

    public EncryptionProcessor(string encryptionAlgorithm, int pbkdf2Iterations, ILogger logger)
    {
        _encryptionAlgorithm = encryptionAlgorithm;
        _pbkdf2Iterations = pbkdf2Iterations;
        _logger = logger;
    }

    public async Task ProcessMessageStream(Stream encryptedStream, byte[] keyMaterial)
    {
        try
        {
            var key = DeriveKey(keyMaterial);
            using (var decryptor = CreateDecryptor(_encryptionAlgorithm, key))
            {
                await CopyAsync(encryptedStream, decryptor);
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing message stream");
        }
    }

    private byte[] DeriveKey(byte[] keyMaterial)
    {
        using (var pbkdf2 = new Rfc2898DeriveBytes(keyMaterial, Encoding.UTF8.GetBytes("salt"), _pbkdf2Iterations))
        {
            return pbkdf2.GetBytes(32); // 256-bit key for AES
        }
    }

    private ICryptoTransform CreateDecryptor(string algorithm, byte[] key)
    {
        switch (algorithm.ToLower())
        {
            case "aes":
                using (var aes = Aes.Create())
                {
                    aes.Key = key;
                    aes.Mode = CipherMode.CBC;
                    aes.Padding = PaddingMode.PKCS7;
                    return aes.CreateDecryptor();
                }
            case "tripledes":
                using (var des3 = TripleDES.Create())
                {
                    des3.Key = key;
                    des3.Mode = CipherMode.CBC;
                    des3.Padding = PaddingMode.PKCS7;
                    return des3.CreateDecryptor();
                }
            case "rsa":
                throw new NotSupportedException("RSA decryption is not supported in this implementation.");
            default:
                throw new ArgumentException("Unsupported encryption algorithm");
        }
    }

    private async Task CopyAsync(Stream source, ICryptoTransform decryptor)
    {
        using (var cryptoStream = new CryptoStream(source, decryptor, CryptoStreamMode.Read))
        using (var memoryStream = new MemoryStream())
        {
            await cryptoStream.CopyToAsync(memoryStream);
            // Process decrypted data here
        }
    }
}

public interface ILogger
{
    void LogError(Exception ex, string message);
}
```

This code snippet provides a basic structure for an `EncryptionProcessor` class that can handle decryption of encrypted streams using different algorithms (AES and Triple DES) based on runtime configuration. It uses PBKDF2 for key derivation with a configurable number of iterations. The decryption process is asynchronous to support high-throughput scenarios, and it includes error handling and logging. Note that RSA decryption is not supported in this implementation.']

