using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class VideoDecryptionModule
{
    private readonly byte[] _encryptionKey;
    private readonly byte[] _initializationVector;

    public VideoDecryptionModule(byte[] encryptionKey, byte[] initializationVector)
    {
        _encryptionKey = encryptionKey;
        _initializationVector = initializationVector;
    }

    public async Task<byte[]> DecryptVideoSegmentAsync(Stream encryptedStream, Stream hmacStream)
    {
        using (var aes = Aes.Create())
        {
            aes.Key = _encryptionKey;
            aes.IV = _initializationVector;

            using (var decryptor = aes.CreateDecryptor(aes.Key, aes.IV))
            using (var memoryStream = new MemoryStream())
            using (var cryptoStream = new CryptoStream(encryptedStream, decryptor, CryptoStreamMode.Read))
            {
                await cryptoStream.CopyToAsync(memoryStream);
                var decryptedData = memoryStream.ToArray();

                // Verify HMAC-SHA256 integrity
                var hmacSHA256 = new HMACSHA256(_encryptionKey);
                var computedHmac = hmacSHA256.ComputeHash(decryptedData);

                byte[] receivedHmac;
                using (var binaryReader = new BinaryReader(hmacStream))
                {
                    receivedHmac = binaryReader.ReadBytes(computedHmac.Length);
                }

                if (!computedHmac.SequenceEqual(receivedHmac))
                {
                    throw new InvalidOperationException("HMAC verification failed.");
                }

                return decryptedData;
            }
        }
    }
}
