    private readonly string _fileUrl;
    private readonly int _bufferSize;
    private readonly CompressionLevel _compressionLevel;

    public DataDeserializer(string fileUrl, int bufferSize = 8192, CompressionLevel compressionLevel = CompressionLevel.Optimal)
    {
        _httpClient = new HttpClient();
        _fileUrl = fileUrl;
        _bufferSize = bufferSize;
        _compressionLevel = compressionLevel;
    }

    public async Task<T> DeserializeAsync<T>()
    {
        try
        {
            using (var response = await _httpClient.GetAsync(_fileUrl, HttpCompletionOption.ResponseHeadersRead))
            {
                response.EnsureSuccessStatusCode();
                var contentStream = await response.Content.ReadAsStreamAsync();

                using (var decompressionStream = new System.IO.Compression.GZipStream(contentStream, System.IO.Compression.CompressionMode.Decompress))
                using (var memoryStream = new MemoryStream())
                {
                    await decompressionStream.CopyToAsync(memoryStream);
                    memoryStream.Position = 0;

                    var data = await JsonSerializer.DeserializeAsync<T>(memoryStream);
                    return data;
                }
            }
        }
        catch (HttpRequestException ex)
        {
            LogError("Network error", ex);
            throw;
        }
        catch (IOException ex)
        {
            LogError("File I/O error", ex);
            throw;
        }
        catch (JsonException ex)
        {
            LogError("Serialization/deserialization error", ex);
            throw;
        }
    }

    private void LogError(string message, Exception ex)
    {
        // Implement logging logic here
        Console.WriteLine($"{message}: {ex.Message}");
    }
}
