const { exec } = require('child_process');
const LRU = require('lru-cache');

// Create an LRU cache instance with a maximum size of 100 items
const commandCache = new LRU({ max: 100 });

async function executeCommand(command) {
    // Check if the result is already in the cache
    if (commandCache.has(command)) {
        return commandCache.get(command);
    }

    try {
        // Execute the shell command asynchronously
        const { stdout, stderr } = await new Promise((resolve, reject) => {
            exec(command, (error, stdout, stderr) => {
                if (error) {
                    reject(error);
                } else {
                    resolve({ stdout, stderr });
                }
            });
        });

        // Store the result in the cache
        commandCache.set(command, { stdout, stderr });

        return { stdout, stderr };
    } catch (error) {
        console.error(`Error executing command: ${command}`, error);
        throw error;
    }
}

async function fetchConfigFromAPI(apiUrl) {
    try {
        const response = await fetch(apiUrl);
        if (!response.ok) {
            throw new Error(`Failed to fetch config from API: ${apiUrl}`);
        }
        return await response.json();
    } catch (error) {
        console.error('Error fetching config from API', error);
        throw error;
    }
}

async function executeCommandWithConfig(command, apiUrl) {
    const config = await fetchConfigFromAPI(apiUrl);
    // Modify the command based on the fetched configuration
    const modifiedCommand = modifyCommandBasedOnConfig(command, config);
    return await executeCommand(modifiedCommand);
}

