use tokio::sync::mpsc;
use tokio::task;
use log::{info, error, debug};
use std::env;

#[tokio::main]
async fn main() {
    env_logger::init();

    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} <command>", args[0]);
        return;
    }

    let command = &args[1];
    match command.as_str() {
        "task1" => task1(),
        "task2" => task2(),
        _ => error!("Unknown command"),
    }
}

async fn task1() {
    info!("Starting task 1");
    // Simulate some async work
    tokio::time::sleep(tokio::time::Duration::from_secs(5)).await;
    info!("Task 1 completed");
}

async fn task2() {
    info!("Starting task 2");
    // Simulate some async work with network interaction
    let mut stream = TcpStream::connect("log-server:5000").await.unwrap();
    debug!("Connected to log server");

    let (tx, mut rx) = mpsc::channel(32);
    tokio::spawn(async move {
        while let Some(message) = rx.recv().await {
            if stream.write_all(message.as_bytes()).await.is_err() {
                error!("Failed to send message to log server");
                break;
            }
        }
    });

    tx.send("Log message 1".to_string()).await.unwrap();
    tx.send("Log message 2".to_string()).await.unwrap();

    info!("Task 2 completed");
}
