        cls._logger.info(f'Deserialized {subclass_name}: {data}')

    @classmethod
    def monitor_memory_usage(cls):
        for subclass_id, memory_usage in cls._memory_thresholds.items():
            if memory_usage > memory_usage_limit:
                cls._logger.warning(f'Memory usage exceeded threshold for subclass {subclass_id}')

    @classmethod
    def cleanup_resources(cls):
        for ref in list(cls._registry.values()):
            obj = ref()
            if obj is None:
                del cls._registry[id(obj)]

