typedef struct {
    int value;
} record;

int find_largest(int* array, int size) {
    if (size <= 0) return -1; // Handle edge case for empty array
    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

void initialize_arrays(int* keys, record** records, int size, int upper_bound) {
    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < size; i++) {
        if ((keys[i] = malloc(sizeof(int))) == NULL) {
            fprintf(stderr, "Memory allocation failed for keys\n");
            exit(EXIT_FAILURE);
        }
        *records[i].value = rand() % (upper_bound + 1); // Ensure random number within upper bound
    }

    // Additional initialization and error handling can be added here
}

void free_memory(int* keys, record** records, int size) {
    for (int i = 0; i < size; i++) {
        free(keys[i]);
        free(records[i]);
    }
}

int main() {
    int size;
    printf("Enter the number of elements: ");
    scanf("%d", &size);

    if (size <= 0) {
        fprintf(stderr, "Invalid input. Size must be greater than 0.\n");
        return EXIT_FAILURE;
    }

    int* keys = malloc(size * sizeof(int));
    record** records = malloc(size * sizeof(record*));

    if (keys == NULL || records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(keys);
        free(records);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < size; i++) {
        records[i] = malloc(sizeof(record));
        if (records[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for record %d\n", i);
            free_memory(keys, records, i); // Clean up previously allocated resources
            return EXIT_FAILURE;
        }
    }

    initialize_arrays(keys, records, size, 100); // Example upper bound of 100

    int largest = find_largest(keys, size);
    printf("Largest integer: %d\n", largest);

    free_memory(keys, records, size);

    return EXIT_SUCCESS;
}
