#include <random>
#include <mutex>

class IntegerCollection {
private:
    std::vector<int> data;
    static std::mt19937 generator;
    static std::once_flag initFlag;

public:
    IntegerCollection(size_t size) {
        std::call_once(initFlag, []() {
            generator.seed(std::random_device{}());
        });
        data.reserve(size);
        for (size_t i = 0; i < size; ++i) {
            data.push_back(generator());
        }
    }

    ~IntegerCollection() {}

    void add(int value) {
        data.push_back(value);
    }

    bool remove(int value) {
        auto it = std::find(data.begin(), data.end(), value);
        if (it != data.end()) {
            data.erase(it);
            return true;
        }
        return false;
    }

    int findLargest() const {
        if (data.empty()) {
            throw std::runtime_error("Collection is empty");
        }
        return *std::max_element(data.begin(), data.end());
    }
};

std::mt19937 IntegerCollection::generator;
std::once_flag IntegerCollection::initFlag;

int main() {
    IntegerCollection collection(10);
    collection.add(5);
    collection.remove(3);
    std::cout << "Largest: " << collection.findLargest() << std::endl;
    return 0;
}
