    private readonly Dictionary<string, User> _users = new Dictionary<string, User>();
    private readonly RateLimiter _rateLimiter = new RateLimiter();
    private readonly ExternalAuthenticator _externalAuthenticator = new ExternalAuthenticator();

    public void ResetPassword(string email)
    {
        if (!_rateLimiter.AllowReset(email))
        {
            throw new Exception("Too many password reset attempts. Please try again later.");
        }

        var user = GetUserByEmail(email);
        if (user == null)
        {
            throw new Exception("User not found.");
        }

        // Send password reset email
        SendPasswordResetEmail(user.Email, user.ResetToken);

        Console.WriteLine("Password reset email sent successfully.");
    }

    public void Authenticate(string username, string password)
    {
        var user = _users.FirstOrDefault(u => u.Username == username);
        if (user == null || !user.VerifyPassword(password))
        {
            throw new Exception("Invalid username or password.");
        }

        Console.WriteLine("Authentication successful.");
    }

    private User GetUserByEmail(string email)
    {
        // Simulate fetching user from database
        return _users.FirstOrDefault(u => u.Email == email);
    }

    private void SendPasswordResetEmail(string email, string resetToken)
    {
        var message = new MailMessage("noreply@example.com", email, "Password Reset Request", $"Click the link to reset your password: https://example.com/reset?token={resetToken}");
        using (var client = new SmtpClient("smtp.example.com"))
        {
            client.Send(message);
        }
    }

    public void AddUser(string username, string password, string email)
    {
        if (_users.ContainsKey(username))
        {
            throw new Exception("Username already exists.");
        }

        var user = new User(username, password, email);
        _users.Add(username, user);

        Console.WriteLine("User added successfully.");
    }
