// Define transaction structure
typedef struct {
    int id;
    int age;
    double weighted_sum;
} Transaction;

// Function to filter transactions based on dynamic criteria
void filter_transactions(Transaction* transactions, int num_transactions, int max_age, int recent_threshold, double* max_weighted_sum, int* max_id) {
    *max_weighted_sum = -1.0;
    *max_id = -1;

    for (int i = 0; i < num_transactions; i++) {
        if (transactions[i].age <= max_age && transactions[i].weighted_sum > *max_weighted_sum) {
            *max_weighted_sum = transactions[i].weighted_sum;
            *max_id = transactions[i].id;
        }
    }
}

