use reqwest::Client;
use std::error::Error;

#[derive(Debug)]
struct TransactionMetadata {
    id: i32,
    age: i32,
    weighted_sum: f64,
}

async fn fetch_transaction_metadata(url: &str, headers: Option<Vec<(&str, &str)>>, verify_ssl: bool) -> Result<TransactionMetadata, Box<dyn Error>> {
    let client = Client::builder()
        .default_headers(headers.map_or_else(Vec::new, |h| h.into_iter().map(|(k, v)| (k.to_string(), v.to_string())).collect()))
        .danger_accept_invalid_certs(!verify_ssl)
        .build()?;

    let response = client.get(url).send().await?;
    let metadata: TransactionMetadata = response.json().await?;

    Ok(metadata)
}
