#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <random>

struct Character {
    int lastAttackTime;
    std::mt19937 rng;
};

class GameSystem {
private:
    static const int MAX_CHARACTERS = 10000;
    std::vector<Character> characters;
    std::mutex mtx;
    std::condition_variable cv;

public:
    GameSystem() : characters(MAX_CHARACTERS) {
        for (auto& chara : characters) {
            chara.lastAttackTime = -10; // Initialize to a time before any cooldown
            chara.rng.seed(std::random_device{}());
        }
    }

    void selectAttack(int characterId) {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this, characterId] { return characters[characterId].lastAttackTime + 10 <= std::chrono::system_clock::to_time_t(std::chrono::system_clock::now()); });

        auto now = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());
        int attackNumber = (characters[characterId].rng() % 4) + 1;
        characters[characterId].lastAttackTime = now;

        lock.unlock();
        cv.notify_all();

        auto start = std::chrono::high_resolution_clock::now();
        // Simulate updating attack history
        std::this_thread::sleep_for(std::chrono::milliseconds(50)); // Simulated delay
        auto end = std::chrono::high_resolution_clock::now();
        std::cout << "Character " << characterId << " attacked with attack number " << attackNumber << ". Time taken for update: " 
                  << std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count() << " ms" << std::endl;
    }
};

int main() {
    GameSystem gameSystem;

    // Simulate multiple threads selecting attacks
    std::vector<std::thread> threads;
    for (int i = 0; i < 100; ++i) {
        threads.emplace_back(&GameSystem::selectAttack, &gameSystem, i);
    }

    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
