using System;
using System.Collections.Generic;
using System.Linq;

public class DataProcessor
{
    private List<Dictionary<string, object>> _dataset;

    public DataProcessor(List<Dictionary<string, object>> dataset)
    {
        ValidateDataset(dataset);
        _dataset = dataset;
    }

    public List<Dictionary<string, object>> FilterData(Func<Dictionary<string, object>, bool> predicate)
    {
        return _dataset.Where(predicate).ToList();
    }

    public List<Dictionary<string, object>> TransformData(Func<Dictionary<string, object>, Dictionary<string, object>> transformer)
    {
        try
        {
            return _dataset.Select(transformer).ToList();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Transformation error: {ex.Message}");
            return new List<Dictionary<string, object>>();
        }
    }

    public List<Dictionary<string, object>> QueryData(string query)
    {
        try
        {
            var parsedQuery = System.Linq.Dynamic.Core.DynamicExpressionParser.ParseLambda(typeof(Dictionary<string, object>), null, query).Compile();
            return _dataset.Where(parsedQuery as Func<Dictionary<string, object>, bool>).ToList();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Query error: {ex.Message}");
            return new List<Dictionary<string, object>>();
        }
    }

    public override string ToString()
    {
        if (_dataset == null || !_dataset.Any())
        {
            return "No data available.";
        }

        var averageValue = _dataset.Average(record => Convert.ToDouble(record["value"]));
        return $"Dataset contains {_dataset.Count} records with an average value of {averageValue}.";
    }

    public static void ValidateDataset(List<Dictionary<string, object>> dataset)
    {
        if (dataset == null || !dataset.Any())
        {
            throw new ArgumentException("Dataset cannot be null or empty.");
        }
    }
}
