    EVP_SignFinal_ex(ctx, signature, &sig_len, rsa);

    // Example usage of HMAC
    unsigned char hmac[SHA256_DIGEST_LENGTH];
    HMAC(EVP_sha256(), key, strlen(key), data, strlen(data), hmac, NULL);

