    }

    // Clean up OpenSSL library
    EVP_cleanup();
    ERR_free_strings();
}

// Thread locking callback for OpenSSL
void openssl_thread_lock(int mode, int type, const char *file, int line) {
    static pthread_mutex_t *mutexes = NULL;
    if (mode & CRYPTO_LOCK) {
        pthread_mutex_lock(&mutexes[type]);
    } else {
        pthread_mutex_unlock(&mutexes[type]);
    }
}

// Initialize mutexes for OpenSSL thread safety
void init_openssl_threading() {
    int i;
    mutexes = (pthread_mutex_t *)OPENSSL_malloc(CRYPTO_num_locks() * sizeof(pthread_mutex_t));
    for (i = 0; i < CRYPTO_num_locks(); i++) {
        pthread_mutex_init(&mutexes[i], NULL);
    }
}

// Clean up mutexes for OpenSSL thread safety
void cleanup_openssl_threading() {
    int i;
    for (i = 0; i < CRYPTO_num_locks(); i++) {
        pthread_mutex_destroy(&mutexes[i]);
    }
    OPENSSL_free(mutexes);
}
