#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_RECORDS 1000
#define MIN_VALUE 1
#define MAX_VALUE 100

typedef struct {
    int value;
} Record;

typedef struct {
    long offset;
    Record *record;
} OffsetRecordPair;

typedef struct {
    int key;
    OffsetRecordPair pair;
} MapEntry;

typedef struct {
    MapEntry entries[MAX_RECORDS];
    int size;
} Map;

typedef struct {
    FILE *file;
    pthread_mutex_t lock;
} BinaryStore;

int initializeDataStructures(Map **map, BinaryStore **store) {
    *map = (Map *)malloc(sizeof(Map));
    if (*map == NULL) {
        return -1; // Memory allocation failed
    }

    *store = (BinaryStore *)malloc(sizeof(BinaryStore));
    if (*store == NULL) {
        free(*map);
        return -2; // Memory allocation failed
    }

    (*map)->size = 0;
    pthread_mutex_init(&(*store)->lock, NULL);

    (*store)->file = fopen("data.bin", "w+b");
    if ((*store)->file == NULL) {
        free(*map);
        free(*store);
        return -3; // File opening failed
    }

    return 0; // Success
}

void cleanup(Map *map, BinaryStore *store) {
    if (map != NULL) {
        for (int i = 0; i < map->size; i++) {
            free(map->entries[i].pair.record);
        }
        free(map);
    }

    if (store != NULL) {
        fclose(store->file);
        pthread_mutex_destroy(&store->lock);
        free(store);
    }
}

void *initializeThread(void *arg) {
    Map *map = (Map *)arg;
    BinaryStore *store = (BinaryStore *)malloc(sizeof(BinaryStore));
    store->file = fopen("data.bin", "w+b");
    if (store == NULL || store->file == NULL) {
        pthread_exit(NULL);
    }

    for (int i = 0; i < MAX_RECORDS; i++) {
        OffsetRecordPair pair;
        pair.offset = ftell(store->file);
        pair.record = (Record *)malloc(sizeof(Record));
        if (pair.record == NULL) {
            cleanup(map, store);
            pthread_exit(NULL);
        }
        pair.record->value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        fwrite(pair.record, sizeof(Record), 1, store->file);
        map->entries[i] = pair;
    }

    fclose(store->file);
    free(store);
    pthread_exit(NULL);
}

int main() {
    Map *map;
    BinaryStore *store;

    if (initializeDataStructures(&map, &store) != 0) {
        fprintf(stderr, "Initialization failed\n");
        return 1;
    }

    pthread_t threads[MAX_RECORDS];
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (pthread_create(&threads[i], NULL, initializeThread, map) != 0) {
            fprintf(stderr, "Failed to create thread\n");
            cleanup(map, store);
            return 1;
        }
    }

    for (int i = 0; i < MAX_RECORDS; i++) {
        pthread_join(threads[i], NULL);
    }

    cleanup(map, store);
    return 0;
}
