            // Free previously allocated memory before exiting
            for (int j = 0; j < i; j++) {
                free(records[j]);
            }
            exit(1); // Exit with failure status
        }
        records[i]->value = keys[i];
    }
}

void free_memory(int* keys, record** records, int size) {
