#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_NAME_LENGTH 50
#define MAX_EMAIL_LENGTH 100
#define MIN_AGE 18
#define MAX_AGE 65

typedef struct {
    char name[MAX_NAME_LENGTH];
    int age;
    char email[MAX_EMAIL_LENGTH];
} Person;

Person* create_person_array(int size) {
    if (size <= 0) {
        return NULL;
    }

    Person* people = (Person*)malloc(size * sizeof(Person));
    if (!people) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < size; i++) {
        // Predefined list of names
        const char* names[] = {"Alice", "Bob", "Charlie", "David", "Eve"};
        int name_index = rand() % sizeof(names) / sizeof(names[0]);
        strncpy(people[i].name, names[name_index], MAX_NAME_LENGTH);

        // Random age within the specified range
        people[i].age = MIN_AGE + rand() % (MAX_AGE - MIN_AGE + 1);

        // Construct email based on name
        snprintf(people[i].email, MAX_EMAIL_LENGTH, "%s@example.com", people[i].name);
    }

    return people;
}

void free_person_array(Person* people, int size) {
    if (people) {
        free(people);
    }
}

int main() {
    int array_size = 10;
    Person* people = create_person_array(array_size);

    if (people) {
        for (int i = 0; i < array_size; i++) {
            printf("Person %d: Name=%s, Age=%d, Email=%s\n", i + 1, people[i].name, people[i].age, people[i].email);
        }
        free_person_array(people, array_size);
    }

    return 0;
}
```

