int initialize_arrays(size_t size, long** offsets, int** keys, record** records, int** statuses, char*** metadata) {
    if (size == 0 || size > 1000000) {
        fprintf(stderr, "Invalid array size: %zu\n", size);
        return -1;
    }

    *offsets = (long*)malloc(size * sizeof(long));
    *keys = (int*)malloc(size * sizeof(int));
    *records = (record*)malloc(size * sizeof(record));
    *statuses = (int*)malloc(size * sizeof(int));
    *metadata = (char**)malloc(size * sizeof(char*));

    if (!(*offsets) || !(*keys) || !(*records) || !(*statuses) || !(*metadata)) {
        fprintf(stderr, "Memory allocation failed\n");
