#define MAX_EMAIL_LENGTH 100

typedef struct {
    int user_id;
    char email[MAX_EMAIL_LENGTH];
    // Add other preferences fields here
} Preferences;

typedef struct UserProfile {
    int user_id;
    char email[MAX_EMAIL_LENGTH];
    Preferences preferences;
    struct UserProfile *next;
} UserProfile;

UserProfile* create_user_profile(int user_id, const char *email) {
    UserProfile *profile = (UserProfile *)malloc(sizeof(UserProfile));
    if (!profile) {
        perror("Failed to allocate memory for user profile");
        return NULL;
    }

    profile->user_id = user_id;
    strncpy(profile->email, email, MAX_EMAIL_LENGTH - 1);
    profile->email[MAX_EMAIL_LENGTH - 1] = '\0';

    // Initialize preferences with default values
    memset(&profile->preferences, 0, sizeof(Preferences));

    profile->next = NULL;

    return profile;
}

void free_user_profile(UserProfile *profile) {
    if (profile) {
        free(profile);
    }
}

void free_all_profiles(UserProfile *head) {
    UserProfile *current = head;
    while (current) {
        UserProfile *temp = current;
        current = current->next;
        free_user_profile(temp);
    }
}

int generate_random_email(char *email, size_t length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyz0123456789";
    if (length > 0) {
        email[length - 1] = '\0';
        for (size_t i = 0; i < length - 1; ++i) {
            size_t index = rand() % (sizeof(charset) - 1);
            email[i] = charset[index];
        }
    }
    return 0;
}

int main() {
    srand(time(NULL));

    UserProfile *head = NULL;

    for (int i = 0; i < 10; ++i) {
        char email[MAX_EMAIL_LENGTH];
        if (generate_random_email(email, MAX_EMAIL_LENGTH) != 0) {
            fprintf(stderr, "Failed to generate random email\n");
            free_all_profiles(head);
            return EXIT_FAILURE;
        }

        UserProfile *new_profile = create_user_profile(i + 1, email);
        if (!new_profile) {
            fprintf(stderr, "Failed to create user profile for user ID %d\n", i + 1);
            free_all_profiles(head);
            return EXIT_FAILURE;
        }

        new_profile->next = head;
        head = new_profile;
    }

    // Process profiles...

    free_all_profiles(head);

    return EXIT_SUCCESS;
}
