#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Vertex {
    int id;
    char location[100];
    char status[50];
} Vertex;

typedef struct Edge {
    int src, dest;
    float bandwidth;
} Edge;

typedef struct Graph {
    int numVertices, numEdges;
    Vertex* vertices;
    Edge* edges;
    pthread_mutex_t mutex;
} Graph;

Graph* createGraph(int numVertices, int numEdges) {
    if (numVertices <= 0 || numEdges < 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }

    Graph* graph = (Graph*)malloc(sizeof(Graph));
    if (!graph) {
        perror("Memory allocation failed");
        return NULL;
    }

    graph->numVertices = numVertices;
    graph->numEdges = numEdges;

    graph->vertices = (Vertex*)calloc(numVertices, sizeof(Vertex));
    if (!graph->vertices) {
        fprintf(stderr, "Failed to allocate memory for vertices\n");
        free(graph);
        return NULL;
    }

    graph->edges = (Edge*)calloc(numEdges, sizeof(Edge));
    if (!graph->edges) {
        fprintf(stderr, "Failed to allocate memory for edges\n");
        free(graph->vertices);
        free(graph);
        return NULL;
    }

    pthread_mutex_init(&graph->mutex, NULL);

    return graph;
}

void destroyGraph(Graph* graph) {
    if (graph) {
        pthread_mutex_destroy(&graph->mutex);
        free(graph->vertices);
        free(graph->edges);
        free(graph);
    }
}
