#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>

typedef struct {
    z_stream stream;
    int compression_level;
    size_t dictionary_size;
} CompressionObject;

CompressionObject* create_compression_object(int level, size_t dict_size) {
    CompressionObject* obj = (CompressionObject*)malloc(sizeof(CompressionObject));
    if (!obj) return NULL;

    memset(obj, 0, sizeof(CompressionObject));
    obj->compression_level = level;
    obj->dictionary_size = dict_size;

    deflateInit2(&obj->stream, level, Z_DEFLATED, -MAX_WBITS, MAX_MEM_LEVEL, Z_DEFAULT_STRATEGY);
    obj->stream.zalloc = Z_NULL;
    obj->stream.zfree = Z_NULL;
    obj->stream.opaque = Z_NULL;

    return obj;
}

void destroy_compression_object(CompressionObject* obj) {
    deflateEnd(&obj->stream);
    free(obj);
}

int compress_data(CompressionObject* obj, const char* input, size_t input_size, char** output, size_t* output_size) {
    *output = (char*)malloc(input_size + 12); // Extra space for header and trailer
    if (!*output) return -1;

    obj->stream.avail_in = input_size;
    obj->stream.next_in = (unsigned char*)input;
    obj->stream.avail_out = input_size + 12;
    obj->stream.next_out = (unsigned char*)(*output);

    deflate(&obj->stream, Z_FINISH);
    *output_size = input_size - obj->stream.avail_out;

    return 0;
}

int decompress_data(CompressionObject* obj, const char* input, size_t input_size, char** output, size_t* output_size) {
    *output = (char*)malloc(input_size); // Initial guess for output size
    if (!*output) return -1;

    obj->stream.avail_in = input_size;
    obj->stream.next_in = (unsigned char*)input;
    obj->stream.avail_out = input_size;
    obj->stream.next_out = (unsigned char*)(*output);

    inflate(&obj->stream, Z_FINISH);
    *output_size = input_size - obj->stream.avail_out;

    return 0;
}

int main(int argc, char** argv) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <input_file> <output_file> <mode> [level] [dict_size]\n", argv[0]);
        return 1;
    }

    const char* input_file = argv[1];
    const char* output_file = argv[2];
    int mode = strcmp(argv[3], "compress") == 0 ? Z_DEFLATED : Z_INFLATE;
    int level = argc > 4 ? atoi(argv[4]) : Z_DEFAULT_COMPRESSION;
    size_t dict_size = argc > 5 ? atoi(argv[5]) : 16384;

    FILE* in = fopen(input_file, "rb");
    if (!in) {
        perror("Failed to open input file");
        return 1;
    }

    FILE* out = fopen(output_file, "wb");
    if (!out) {
        perror("Failed to open output file");
        fclose(in);
        return 1;
    }

    CompressionObject* obj = create_compression_object(level, dict_size);
    if (!obj) {
        fprintf(stderr, "Failed to create compression object\n");
        fclose(in);
        fclose(out);
        return 1;
    }

    char buffer[4096];
    size_t input_size, output_size;

    while ((input_size = fread(buffer, 1, sizeof(buffer), in)) > 0) {
        if (mode == Z_DEFLATED) {
            compress_data(obj, buffer, input_size, &buffer, &output_size);
        } else {
            decompress_data(obj, buffer, input_size, &buffer, &output_size);
        }

        fwrite(buffer, 1, output_size, out);
    }

    destroy_compression_object(obj);
    fclose(in);
    fclose(out);

    return 0;
}
