#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_SEMAPHORES 100

typedef struct {
    sem_t *sems[MAX_SEMAPHORES];
    int count;
} SemaphoreManager;

SemaphoreManager *create_semaphore_manager() {
    SemaphoreManager *manager = (SemaphoreManager *)malloc(sizeof(SemaphoreManager));
    manager->count = 0;
    return manager;
}

int create_semaphore(SemaphoreManager *manager, int initial_value) {
    if (manager->count >= MAX_SEMAPHORES) {
        fprintf(stderr, "Error: Maximum number of semaphores reached.\n");
        return -1;
    }
    sem_t *sem = (sem_t *)malloc(sizeof(sem_t));
    if (sem_init(sem, 0, initial_value) != 0) {
        perror("Error initializing semaphore");
        free(sem);
        return -1;
    }
    manager->sems[manager->count++] = sem;
    return 0;
}

void use_semaphore(SemaphoreManager *manager, int index) {
    if (index < 0 || index >= manager->count) {
        fprintf(stderr, "Error: Invalid semaphore index.\n");
        return;
    }
    sem_wait(manager->sems[index]);
}

void release_semaphore(SemaphoreManager *manager, int index) {
    if (index < 0 || index >= manager->count) {
        fprintf(stderr, "Error: Invalid semaphore index.\n");
        return;
    }
    sem_post(manager->sems[index]);
}

void delete_semaphore(SemaphoreManager *manager, int index) {
    if (index < 0 || index >= manager->count) {
        fprintf(stderr, "Error: Invalid semaphore index.\n");
        return;
    }
    sem_destroy(manager->sems[index]);
    free(manager->sems[index]);
    for (int i = index; i < manager->count - 1; i++) {
        manager->sems[i] = manager->sems[i + 1];
    }
    manager->count--;
}

void destroy_semaphore_manager(SemaphoreManager *manager) {
    for (int i = 0; i < manager->count; i++) {
        sem_destroy(manager->sems[i]);
        free(manager->sems[i]);
    }
    free(manager);
}
