#define MAX_TASKS 1000

typedef struct {
    int id;
    int priority;
    char status[20];
} Task;

int compare_tasks(const void *a, const void *b) {
    return ((Task *)a)->priority - ((Task *)b)->priority;
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int read_tasks(Task **tasks, int *count) {
    *count = 0;
    while (*count < MAX_TASKS && scanf("%d %d %19s", &(*tasks)[*count].id, &(*tasks)[*count].priority, (*tasks)[*count].status) == 3) {
        (*count)++;
    }
    return *count;
}

void free_tasks(Task *tasks, int count) {
    for (int i = 0; i < count; i++) {
        // Assuming no dynamic memory was allocated within the task structure
    }
    free(tasks);
}

int save_tasks_to_file(const Task *tasks, int count, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        log_error("Failed to open file for writing.");
        return -1;
    }
    for (int i = 0; i < count; i++) {
        fprintf(file, "%d %d %s\n", tasks[i].id, tasks[i].priority, tasks[i].status);
    }
    fclose(file);
    return 0;
}

int main() {
    Task *tasks = malloc(MAX_TASKS * sizeof(Task));
    if (!tasks) {
        log_error("Failed to allocate memory for tasks.");
        return -1;
    }

    int count = read_tasks(&tasks, &count);
    if (count == -1) {
        free(tasks);
        return -1;
    }

    qsort(tasks, count, sizeof(Task), compare_tasks);

    if (save_tasks_to_file(tasks, count, "sorted_tasks.txt") != 0) {
        free_tasks(tasks, count);
        return -1;
    }

    free_tasks(tasks, count);
    return 0;
}
