#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define EARTH_RADIUS 6371000

typedef struct {
    double latitude;
    double longitude;
    double elevation;
    char name[256];
} Location;

typedef struct Node {
    Location data;
    struct Node *left, *right;
} Node;

Node* createNode(Location data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newNode->data = data;
    newNode->left = newNode->right = NULL;
    return newNode;
}

double distance(Location a, Location b) {
    double lat1 = a.latitude * M_PI / 180.0;
    double lon1 = a.longitude * M_PI / 180.0;
    double lat2 = b.latitude * M_PI / 180.0;
    double lon2 = b.longitude * M_PI / 180.0;

    double dlon = lon2 - lon1;
    double dlat = lat2 - lat1;

    double a_val = sin(dlat / 2) * sin(dlat / 2) +
                   cos(lat1) * cos(lat2) *
                   sin(dlon / 2) * sin(dlon / 2);
    double c_val = 2 * atan2(sqrt(a_val), sqrt(1 - a_val));

    return EARTH_RADIUS * c_val;
}

Node* insert(Node* root, Location data) {
    if (root == NULL)
        return createNode(data);

    if (distance(root->data, data) < distance(root->left->data, data))
        root->left = insert(root->left, data);
    else
        root->right = insert(root->right, data);

    return root;
}

Node* nearestNeighbor(Node* root, Location query, double radius) {
    if (root == NULL)
        return NULL;

    Node* closest = NULL;
    double minDist = INFINITY;

    if (distance(root->data, query) <= radius && distance(root->data, query) < minDist) {
        closest = root;
        minDist = distance(root->data, query);
    }

    if (root->left != NULL && fabs(query.latitude - root->data.latitude) * 111320 < radius)
        closest = nearestNeighbor(root->left, query, radius);

    if (root->right != NULL && fabs(query.latitude - root->data.latitude) * 111320 < radius)
        closest = nearestNeighbor(root->right, query, radius);

    return closest;
}

void freeTree(Node* node) {
    if (node == NULL)
        return;

    freeTree(node->left);
    freeTree(node->right);
    free(node);
}
