#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <pthread.h>

#define EARTH_RADIUS 6371000 // Earth's radius in meters

typedef struct {
    double latitude;
    double longitude;
    double elevation;
    char name[256];
} Location;

typedef struct Node {
    Location data;
    struct Node *left, *right;
} Node;

Node* createNode(Location data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newNode->data = data;
    newNode->left = newNode->right = NULL;
    return newNode;
}

void insertNode(Node** root, Location data) {
    if (*root == NULL) {
        *root = createNode(data);
        return;
    }

    double distanceRoot = acos(sin(data.latitude * M_PI / 180) * sin((*root)->data.latitude * M_PI / 180) +
                               cos(data.latitude * M_PI / 180) * cos((*root)->data.latitude * M_PI / 180) *
                               cos(data.longitude * M_PI / 180 - (*root)->data.longitude * M_PI / 180)) * EARTH_RADIUS;
    double distanceNew = acos(sin(data.latitude * M_PI / 180) * sin((*root)->data.latitude * M_PI / 180) +
                              cos(data.latitude * M_PI / 180) * cos((*root)->data.latitude * M_PI / 180) *
                              cos(data.longitude * M_PI / 180 - (*root)->data.longitude * M_PI / 180)) * EARTH_RADIUS;

    if (distanceNew < distanceRoot) {
        insertNode(&(*root)->left, data);
    } else {
        insertNode(&(*root)->right, data);
    }
}

Node* searchNearest(Node* root, Location query, double radius) {
    if (root == NULL) return NULL;

    double distance = acos(sin(query.latitude * M_PI / 180) * sin(root->data.latitude * M_PI / 180) +
                           cos(query.latitude * M_PI / 180) * cos(root->data.latitude * M_PI / 180) *
                           cos(query.longitude * M_PI / 180 - root->data.longitude * M_PI / 180)) * EARTH_RADIUS;

    if (distance <= radius) {
        return root;
    }

    Node* left = searchNearest(root->left, query, radius);
    Node* right = searchNearest(root->right, query, radius);

    if (left != NULL && right != NULL) {
        double distanceLeft = acos(sin(query.latitude * M_PI / 180) * sin(left->data.latitude * M_PI / 180) +
                                   cos(query.latitude * M_PI / 180) * cos(left->data.latitude * M_PI / 180) *
                                   cos(query.longitude * M_PI / 180 - left->data.longitude * M_PI / 180)) * EARTH_RADIUS;
        double distanceRight = acos(sin(query.latitude * M_PI / 180) * sin(right->data.latitude * M_PI / 180) +
                                    cos(query.latitude * M_PI / 180) * cos(right->data.latitude * M_PI / 180) *
                                    cos(query.longitude * M_PI / 180 - right->data.longitude * M_PI / 180)) * EARTH_RADIUS;

        return distanceLeft < distanceRight ? left : right;
    }

    if (left != NULL) return left;
    if (right != NULL) return right;

    return NULL;
}

int main() {
    Node* root = NULL;
    Location loc1 = {40.7128, -74.0060, 10, "New York"};
    Location loc2 = {34.0522, -118.2437, 20, "Los Angeles"};

    insertNode(&root, loc1);
    insertNode(&root, loc2);

    Location query = {39.9042, -75.1652, 0, "Philadelphia"};
    double radius = 1000000; // 1000 km

    Node* nearest = searchNearest(root, query, radius);
    if (nearest != NULL) {
        printf("Nearest location: %s\n", nearest->data.name);
    } else {
        printf("No location found within the specified radius.\n");
    }

    return 0;
}
