void initialize_arrays(int array_size, processing_context* context) {
    context->float_array = (double*)malloc(array_size * sizeof(double));
    context->char_array = (char**)malloc(array_size * sizeof(char*));
    context->data_entries = (data_entry**)malloc(array_size * sizeof(data_entry*));

    for (int i = 0; i < array_size; i++) {
        context->float_array[i] = 0.0;
        context->char_array[i] = (char*)malloc(20 * sizeof(char));
        context->data_entries[i] = (data_entry*)malloc(sizeof(data_entry));
        context->data_entries[i]->id = i;
        snprintf(context->data_entries[i]->name, 20, "Entry %d", i);
    }
}

// Function to initialize processing_context
void init_processing_context(int num_contexts, int array_size) {
    pthread_mutex_t global_mutex;
    pthread_mutex_init(&global_mutex, NULL);

    processing_context* contexts = (processing_context*)malloc(num_contexts * sizeof(processing_context));

    for (int i = 0; i < num_contexts; i++) {
        pthread_mutex_init(&contexts[i].mutex, NULL);
        initialize_arrays(array_size, &contexts[i]);
    }

    // Multi-threaded initialization routine
    pthread_t threads[num_contexts];
    for (int i = 0; i < num_contexts; i++) {
        pthread_create(&threads[i], NULL, thread_function, &contexts[i]);
    }

    for (int i = 0; i < num_contexts; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free allocated memory
    for (int i = 0; i < num_contexts; i++) {
        free(contexts[i].float_array);
        for (int j = 0; j < array_size; j++) {
            free(contexts[i].char_array[j]);
            free(contexts[i].data_entries[j]);
        }
        free(contexts[i].char_array);
        free(contexts[i].data_entries);
        pthread_mutex_destroy(&contexts[i].mutex);
    }
    free(contexts);
    pthread_mutex_destroy(&global_mutex);
}

// Thread function for multi-threaded initialization
