        (*array)[i].RNTI = rand() % 256; // Example initialization
        (*array)[i].CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG
    }

    return 0; // Success
}

void freeCRCArray(NFAPI_CRC_INDICATION_PDU_T *array) {
