typedef struct {
    float value;
    time_t timestamp;
} Transaction;

// Function to allocate memory and initialize data structures
int init_data_structures(int num_transactions, float lower_bound, float upper_bound) {
    // Allocate memory for float values
    float *float_values = (float *)malloc(num_transactions * sizeof(float));
    if (!float_values) {
        return -1; // Memory allocation failed
    }

    // Allocate memory for timestamps
    time_t *timestamps = (time_t *)malloc(num_transactions * sizeof(time_t));
    if (!timestamps) {
        free(float_values);
        return -1; // Memory allocation failed
    }

    // Allocate memory for transactions
    Transaction *transactions = (Transaction *)malloc(num_transactions * sizeof(Transaction));
    if (!transactions) {
        free(float_values);
        free(timestamps);
        return -1; // Memory allocation failed
    }

    // Initialize data structures
    srand(time(NULL)); // Seed random number generator
    for (int i = 0; i < num_transactions; i++) {
        float_values[i] = lower_bound + (float)rand() / RAND_MAX * (upper_bound - lower_bound);
        timestamps[i] = time(NULL);
        transactions[i].value = float_values[i];
        transactions[i].timestamp = timestamps[i];
    }

    // Free allocated memory
    free(float_values);
    free(timestamps);
    free(transactions);

    return 0; // Success
}

// Helper function to calculate statistics
void calculate_statistics(Transaction *transactions, int num_transactions) {
    float sum = 0;
    float max_value = transactions[0].value;

    for (int i = 1; i < num_transactions; i++) {
        sum += transactions[i].value;
        if (transactions[i].value > max_value) {
            max_value = transactions[i].value;
        }
    }

    printf("Average transaction value: %f\n", sum / num_transactions);
    printf("Maximum transaction value: %f\n", max_value);
}

int main() {
    int num_transactions = 1000;
    float lower_bound = 10.0;
    float upper_bound = 100.0;

    if (init_data_structures(num_transactions, lower_bound, upper_bound) == 0) {
        printf("Data structures initialized successfully.\n");
    } else {
        printf("Failed to initialize data structures.\n");
    }

    return 0;
}
