int find_largest(int* arr, int size) {
    if (size <= 0) return -1; // Handle edge case
    int largest = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    return largest;
}

void initialize_data(int* keys, record* recs, metadata* metas, int size, int upper_bound) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        keys[i] = rand() % (upper_bound + 1);
        recs[i].value = rand() % (upper_bound + 1);
        metas[i].timestamp = time(NULL);
        metas[i].flag = (rand() % 2 == 0) ? 1 : 0;
    }
}

void free_memory(int* keys, record* recs, metadata* metas, int size) {
    free(keys);
    free(recs);
    free(metas);
}

int main() {
    int size, upper_bound;
    printf("Enter the number of elements: ");
    scanf("%d", &size);
    printf("Enter the upper bound for random numbers: ");
    scanf("%d", &upper_bound);

    int* keys = (int*)malloc(size * sizeof(int));
    record* recs = (record*)malloc(size * sizeof(record));
    metadata* metas = (metadata*)malloc(size * sizeof(metadata));

    if (!keys || !recs || !metas) {
        printf("Memory allocation failed.\n");
        return 1;
    }

    initialize_data(keys, recs, metas, size, upper_bound);

    int largest = find_largest(keys, size);
    printf("Largest number: %d\n", largest);

    free_memory(keys, recs, metas, size);

    return 0;
}
