#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    int num_records;
} DataStructures;

typedef struct {
    long* offset_ptr;
    int* key_ptr;
    int active;
} record;

DataStructures* init_data_structures(int num_offsets, int num_keys) {
    if (num_offsets <= 0 || num_keys <= 0) {
        fprintf(stderr, "Invalid input: num_offsets and num_keys must be greater than 0.\n");
        return NULL;
    }

    DataStructures* ds = (DataStructures*)malloc(sizeof(DataStructures));
    if (!ds) {
        fprintf(stderr, "Memory allocation failed for DataStructures.\n");
        return NULL;
    }

    ds->offsets = (long*)malloc(num_offsets * sizeof(long));
    if (!ds->offsets) {
        fprintf(stderr, "Memory allocation failed for offsets array.\n");
        free(ds);
        return NULL;
    }

    ds->keys = (int*)malloc(num_keys * sizeof(int));
    if (!ds->keys) {
        fprintf(stderr, "Memory allocation failed for keys array.\n");
        free(ds->offsets);
        free(ds);
        return NULL;
    }

    ds->records = (record**)malloc(num_offsets * sizeof(record*));
    if (!ds->records) {
        fprintf(stderr, "Memory allocation failed for records array.\n");
        free(ds->keys);
        free(ds->offsets);
        free(ds);
        return NULL;
    }

    ds->num_records = num_offsets;

    srand(time(NULL));

    for (int i = 0; i < num_offsets; i++) {
        ds->records[i] = (record*)malloc(sizeof(record));
        if (!ds->records[i]) {
            fprintf(stderr, "Memory allocation failed for record %d.\n", i);
            for (int j = 0; j < i; j++) {
                free(ds->records[j]);
            }
            free(ds->records);
            free(ds->keys);
            free(ds->offsets);
            free(ds);
            return NULL;
        }

        ds->records[i]->offset_ptr = &ds->offsets[i];
        ds->records[i]->key_ptr = &ds->keys[i % num_keys]; // Cycle through keys
        ds->records[i]->active = 1;

        *ds->records[i]->offset_ptr = i; // Example offset value
        *ds->records[i]->key_ptr = rand() % 100; // Random key value
    }

    return ds;
}

void free_data_structures(DataStructures* ds) {
    if (ds) {
        for (int i = 0; i < ds->num_records; i++) {
            free(ds->records[i]);
        }
        free(ds->records);
        free(ds->keys);
        free(ds->offsets);
        free(ds);
    }
}

int main() {
    int num_offsets = 10;
    int num_keys = 5;

    DataStructures* ds = init_data_structures(num_offsets, num_keys);
    if (ds) {
        printf("Data structures initialized successfully.\n");
        // Perform operations on ds
        free_data_structures(ds);
    }

    return 0;
}
