#define MAX_LIST_SIZE 1000

typedef struct {
    time_t timestamp;
    int sequence_number;
    char guid[37]; // UUID format: xxxxxxxx-xxxx-Mxxx-Nxxx-xxxxxxxxxxxx
    NFAPI_CRC_INDICATION_PDU_T pdu;
} UniqueNFAPICRC;

UniqueNFAPICRC* dynamic_list[MAX_LIST_SIZE];
int list_size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void generate_guid(char *guid) {
    // Generate a random UUID using a simple method
    sprintf(guid, "%08x-%04x-4%03x-a%01x%03x-%012x",
            rand(), rand() % 0x1000 + 0x4000,
            rand() % 0x0fff + 0x8000, rand() & 0x3f | 0x80,
            rand() % 0x0fff, rand());
}

void insert_unique_nfaapi_crc(NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&mutex);
    if (list_size >= MAX_LIST_SIZE) {
        printf("Error: List size exceeded.\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    UniqueNFAPICRC *new_item = malloc(sizeof(UniqueNFAPICRC));
    new_item->timestamp = time(NULL);
    new_item->sequence_number = list_size + 1;
    generate_guid(new_item->guid);
    memcpy(&new_item->pdu, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    dynamic_list[list_size++] = new_item;
    pthread_mutex_unlock(&mutex);
}

UniqueNFAPICRC* retrieve_unique_nfaapi_crc(int index) {
    if (index < 0 || index >= list_size) {
        printf("Error: Invalid index.\n");
        return NULL;
    }
    return dynamic_list[index];
}

void update_rnti_values() {
    // Simulate updating RNTI values from an external data source
    for (int i = 0; i < list_size; i++) {
        pthread_mutex_lock(&mutex);
        NFAPI_CRC_INDICATION_PDU_T *pdu = &dynamic_list[i]->pdu;
        // Update RNTI logic here
        dynamic_list[i]->timestamp = time(NULL); // Update timestamp for uniqueness
        pthread_mutex_unlock(&mutex);
    }
}

void free_dynamic_list() {
    for (int i = 0; i < list_size; i++) {
        free(dynamic_list[i]);
    }
    list_size = 0;
}
```

