int main() {
    long num_offsets, num_records;
    printf("Enter number of offsets (max %ld): ", MAX_SIZE);
    scanf("%ld", &num_offsets);
    if (num_offsets > MAX_SIZE) {
        fprintf(stderr, "Error: Number of offsets exceeds maximum allowed.\n");
        return 1;
    }

    printf("Enter number of records (max %d MB): ", RECORD_SIZE / (1024 * 1024));
    scanf("%ld", &num_records);
    if (num_records * sizeof(record) > RECORD_SIZE) {
        fprintf(stderr, "Error: Number of records exceeds maximum allowed memory.\n");
        return 1;
    }

    long* offsets = malloc(num_offsets * sizeof(long));
    int* keys = malloc(num_offsets * sizeof(int));
    record* records = malloc(num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return 1;
    }

    // Initialize arrays
    for (long i = 0; i < num_offsets; ++i) {
        offsets[i] = i * sizeof(long);
        keys[i] = rand() % 1000; // Example range for keys
    }

    pthread_t threads[num_records / BATCH_SIZE];
    for (int i = 0; i < num_records / BATCH_SIZE; ++i) {
        if (pthread_create(&threads[i], NULL, initialize_data, &offsets[i * BATCH_SIZE])) {
            fprintf(stderr, "Error: Thread creation failed.\n");
            return 1;
        }
    }

    for (int i = 0; i < num_records / BATCH_SIZE; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Serialize data to file
    FILE* file = fopen("data.bin", "wb");
    if (!file) {
        fprintf(stderr, "Error: Failed to open file for writing.\n");
        return 1;
    }

    size_t written = fwrite(records, sizeof(record), num_records, file);
    if (written != num_records) {
        fprintf(stderr, "Error: Failed to write data to file.\n");
        fclose(file);
        return 1;
    }

    fclose(file);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
