#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    size_t size;
    size_t max_size;
    size_t allocated_memory;
    pthread_mutex_t lock;
} data_structure;

data_structure* create_data_structure(size_t initial_size) {
    data_structure *ds = (data_structure*)malloc(sizeof(data_structure));
    ds->offsets = (long*)calloc(initial_size, sizeof(long));
    ds->keys = (int*)calloc(initial_size, sizeof(int));
    ds->records = (record**)calloc(initial_size, sizeof(record*));
    ds->size = 0;
    ds->max_size = initial_size;
    ds->allocated_memory = initial_size * (sizeof(long) + sizeof(int) + sizeof(record*));
    pthread_mutex_init(&ds->lock, NULL);
    return ds;
}

void destroy_data_structure(data_structure *ds) {
    for (size_t i = 0; i < ds->size; ++i) {
        free(ds->records[i]);
    }
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

void add_record(data_structure *ds, long offset, int key) {
    pthread_mutex_lock(&ds->lock);
    if (ds->size == ds->max_size) {
        ds->max_size *= 2;
        ds->offsets = (long*)realloc(ds->offsets, ds->max_size * sizeof(long));
        ds->keys = (int*)realloc(ds->keys, ds->max_size * sizeof(int));
        ds->records = (record**)realloc(ds->records, ds->max_size * sizeof(record*));
        ds->allocated_memory = ds->max_size * (sizeof(long) + sizeof(int) + sizeof(record*));
    }
    ds->offsets[ds->size] = offset;
    ds->keys[ds->size] = key;
    ds->records[ds->size++] = (record*)malloc(sizeof(record));
    pthread_mutex_unlock(&ds->lock);
}

void garbage_collection(data_structure *ds) {
    pthread_mutex_lock(&ds->lock);
    for (size_t i = 0; i < ds->size; ++i) {
        free(ds->records[i]);
    }
    memset(ds->offsets, 0, ds->max_size * sizeof(long));
    memset(ds->keys, 0, ds->max_size * sizeof(int));
    memset(ds->records, 0, ds->max_size * sizeof(record*));
    ds->size = 0;
    pthread_mutex_unlock(&ds->lock);
}

void serialize_data_structure(data_structure *ds, FILE *file) {
    fwrite(&ds->size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < ds->size; ++i) {
        fwrite(&ds->offsets[i], sizeof(long), 1, file);
        fwrite(&ds->keys[i], sizeof(int), 1, file);
        fwrite(ds->records[i], sizeof(record), 1, file);
    }
}

void deserialize_data_structure(data_structure *ds, FILE *file) {
    size_t size;
    fread(&size, sizeof(size_t), 1, file);
    if (size > ds->max_size) {
        ds->max_size = size;
        ds->offsets = (long*)realloc(ds->offsets, ds->max_size * sizeof(long));
        ds->keys = (int*)realloc(ds->keys, ds->max_size * sizeof(int));
        ds->records = (record**)realloc(ds->records, ds->max_size * sizeof(record*));
    }
    for (size_t i = 0; i < size; ++i) {
        fread(&ds->offsets[i], sizeof(long), 1, file);
        fread(&ds->keys[i], sizeof(int), 1, file);
        ds->records[i] = (record*)malloc(sizeof(record));
        fread(ds->records[i], sizeof(record), 1, file);
    }
    ds->size = size;
}

void log_status(data_structure *ds) {
    printf("Size: %zu\n", ds->size);
    printf("Max Size: %zu\n", ds->max_size);
    printf("Allocated Memory: %zu\n", ds->allocated_memory);
}
