typedef struct {
    int id;
    char start_date[20];
    char end_date[20];
    float budget;
    char status[50];
} Project;

int compare_projects(const void *a, const void *b) {
    return ((Project *)a)->budget - ((Project *)b)->budget;
}

void update_budgets(Project projects[], int num_projects) {
    FILE *config = fopen(CONFIG_FILE, "r");
    if (!config) {
        perror("Failed to open config file");
        return;
    }

    float increase_percentage;
    fscanf(config, "%f", &increase_percentage);
    fclose(config);

    for (int i = 0; i < num_projects; i++) {
        projects[i].budget *= (1 + increase_percentage / 100.0);
    }
}

void serialize_to_database(Project projects[], int num_projects) {
    // Simulate database serialization
    printf("Serializing %d projects to database...\n", num_projects);
    for (int i = 0; i < num_projects; i++) {
        printf("Project ID: %d, Budget: %.2f\n", projects[i].id, projects[i].budget);
    }
}

void initialize_projects(Project *projects, int num_projects) {
    if (num_projects > MAX_PROJECTS) {
        fprintf(stderr, "Error: Number of projects exceeds maximum limit.\n");
        return;
    }

    FILE *csv = fopen("projects.csv", "r");
    if (!csv) {
        perror("Failed to open CSV file");
        return;
    }

    for (int i = 0; i < num_projects; i++) {
        fscanf(csv, "%d,%[^,],%[^,],%f,%[^\n]", &projects[i].id, projects[i].start_date, projects[i].end_date, &projects[i].budget, projects[i].status);
    }
    fclose(csv);

    update_budgets(projects, num_projects);
    qsort(projects, num_projects, sizeof(Project), compare_projects);
    serialize_to_database(projects, num_projects);
}

int main() {
    Project projects[MAX_PROJECTS];
    int num_projects = 5; // Example number of projects

    initialize_projects(projects, num_projects);

    return 0;
}
