    *offsets = (long*)malloc(size * sizeof(long));
    *keys = (int*)malloc(size * sizeof(int));
    *records = (record*)malloc(size * sizeof(record));
    *timestamps = (timestamp*)malloc(size * sizeof(timestamp));

    if (*offsets == NULL || *keys == NULL || *records == NULL || *timestamps == NULL) {
        free(*offsets);
        free(*keys);
        free(*records);
        free(*timestamps);
        return -1;
    }

    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        (*offsets)[i] = rand();
        (*keys)[i] = rand() % 1000;
        (*records)[i].value = rand() % 1000;
        (*records)[i].data = (char*)malloc(256 * sizeof(char));
        for (int j = 0; j < 255; j++) {
            (*records)[i].data[j] = 'a' + rand() % 26;
        }
        (*records)[i].data[255] = '\0';
        (*records)[i].precision = ((float)rand()) / RAND_MAX * 1.0f;
        (*timestamps)[i] = time(NULL);
    }

    return 0;
}

void free_arrays(long* offsets, int* keys, record* records, timestamp* timestamps) {
    for (int i = 0; i < size; i++) {
        free(records[i].data);
    }
    free(offsets);
    free(keys);
    free(records);
    free(timestamps);
}
