    *float_array = (float*)malloc(array_size * sizeof(float));
    if (*float_array == NULL) return -1;

    *char_array = (char*)malloc(array_size * sizeof(char));
    if (*char_array == NULL) {
        free(*float_array);
        return -1;
    }

    *linked_list = (Node**)malloc(array_size * sizeof(Node*));
    if (*linked_list == NULL) {
        free(*float_array);
        free(*char_array);
        return -1;
    }

    *timestamp_array = (double*)malloc(array_size * sizeof(double));
    if (*timestamp_array == NULL) {
        free(*float_array);
        free(*char_array);
        free(*linked_list);
        return -1;
    }

    for (int i = 0; i < array_size; i++) {
        (*linked_list)[i] = (Node*)malloc(sizeof(Node));
        if ((*linked_list)[i] == NULL) {
            for (int j = 0; j < i; j++) free((*linked_list)[j]);
            free(*float_array);
            free(*char_array);
            free(*linked_list);
            free(*timestamp_array);
            return -1;
        }
    }

    srand(time(NULL));
    for (int i = 0; i < array_size; i++) {
        (*float_array)[i] = (float)(rand() % range) / RAND_MAX;
        (*char_array)[i] = 'A' + rand() % 26;
        (*linked_list)[i]->identifier = (*char_array)[i];
        (*linked_list)[i]->value = rand() % range;
        (*linked_list)[i]->next = NULL;
        (*timestamp_array)[i] = (double)clock() / CLOCKS_PER_SEC;
    }

    return 0;
}

void free_memory(float* float_array, char* char_array, Node** linked_list, double* timestamp_array) {
    for (int i = 0; i < MAX_NODES; i++) {
        if (linked_list[i] != NULL) free(linked_list[i]);
    }
    free(float_array);
    free(char_array);
    free(linked_list);
    free(timestamp_array);
}

void log_error(const char* message) {
    printf("Error: %s\n", message);
}

int main() {
    float* float_array;
    char* char_array;
    Node** linked_list;
    double* timestamp_array;

