#define MAX_LIST_SIZE 100

typedef struct {
    int timestamp;
    int sequence_number;
    char guid[37];
    NFAPI_CRC_INDICATION_PDU_T pdu;
} Resource;

typedef struct {
    Resource *resources[MAX_LIST_SIZE];
    int size;
    pthread_mutex_t lock;
} ResourceList;

ResourceList resource_list = {0};

void init_resource_list() {
    pthread_mutex_init(&resource_list.lock, NULL);
}

int insert_resource(Resource *new_resource) {
    pthread_mutex_lock(&resource_list.lock);
    if (resource_list.size >= MAX_LIST_SIZE) {
        pthread_mutex_unlock(&resource_list.lock);
        return -1; // List is full
    }
    resource_list.resources[resource_list.size++] = new_resource;
    pthread_mutex_unlock(&resource_list.lock);
    return 0;
}

Resource* get_resource(int timestamp, int sequence_number, char *guid) {
    pthread_mutex_lock(&resource_list.lock);
    for (int i = 0; i < resource_list.size; i++) {
        if (resource_list.resources[i]->timestamp == timestamp &&
            resource_list.resources[i]->sequence_number == sequence_number &&
            strcmp(resource_list.resources[i]->guid, guid) == 0) {
            pthread_mutex_unlock(&resource_list.lock);
            return resource_list.resources[i];
        }
    }
    pthread_mutex_unlock(&resource_list.lock);
    return NULL;
}

int update_resource(Resource *updated_resource) {
    Resource *existing_resource = get_resource(updated_resource->timestamp,
                                               updated_resource->sequence_number,
                                               updated_resource->guid);
    if (existing_resource == NULL) {
        return -1; // Resource not found
    }
    pthread_mutex_lock(&resource_list.lock);
    memcpy(existing_resource, updated_resource, sizeof(Resource));
    pthread_mutex_unlock(&resource_list.lock);
    return 0;
}

int delete_resource(int timestamp, int sequence_number, char *guid) {
    pthread_mutex_lock(&resource_list.lock);
    for (int i = 0; i < resource_list.size; i++) {
        if (resource_list.resources[i]->timestamp == timestamp &&
            resource_list.resources[i]->sequence_number == sequence_number &&
            strcmp(resource_list.resources[i]->guid, guid) == 0) {
            Resource *new_resource = malloc(sizeof(Resource));
            memset(new_resource, 0, sizeof(Resource));
            memcpy(new_resource, updated_resource, sizeof(Resource));
            free(resource_list.resources[i]);
            resource_list.resources[i] = new_resource;
            pthread_mutex_unlock(&resource_list.lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&resource_list.lock);
    return -1; // Resource not found
}

