#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000
#define RECORD_SIZE sizeof(int)
#define ALIGNMENT 64

typedef struct {
    int value;
} Record;

typedef struct {
    Record *records;
    size_t count;
    size_t limit;
    pthread_mutex_t mutex;
} RecordCollection;

RecordCollection *create_record_collection(size_t limit) {
    RecordCollection *collection = (RecordCollection *)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->limit = limit;
    collection->count = 0;
    collection->records = (Record *)aligned_alloc(ALIGNMENT, RECORD_SIZE * MAX_RECORDS);
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    pthread_mutex_init(&collection->mutex, NULL);
    srand(time(NULL));
    return collection;
}

void destroy_record_collection(RecordCollection *collection) {
    pthread_mutex_lock(&collection->mutex);
    free(collection->records);
    pthread_mutex_unlock(&collection->mutex);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}

int add_random_record(RecordCollection *collection, int min, int max) {
    pthread_mutex_lock(&collection->mutex);

    if (collection->count >= MAX_RECORDS) {
        fprintf(stderr, "Error: Collection is full.\n");
        pthread_mutex_unlock(&collection->mutex);
        return -1;
    }

    if ((collection->limit - collection->count * RECORD_SIZE) < RECORD_SIZE) {
        fprintf(stderr, "Error: Limit exceeded.\n");
        pthread_mutex_unlock(&collection->mutex);
        return -1;
    }

    int value = min + rand() % (max - min + 1);
    collection->records[collection->count].value = value;
    collection->count++;
    pthread_mutex_unlock(&collection->mutex);

    return 0;
}

void *thread_function(void *arg) {
    RecordCollection *collection = (RecordCollection *)arg;
    for (int i = 0; i < 100; i++) {
        add_random_record(collection, 1, 100);
    }
    return NULL;
}

int main() {
    RecordCollection *collection = create_record_collection(1024 * RECORD_SIZE);
    if (!collection) {
        fprintf(stderr, "Error: Failed to create record collection.\n");
        return 1;
    }

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, thread_function, collection);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    destroy_record_collection(collection);
    return 0;
}
