#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define MAX_VALUES_PER_RECORD 10

typedef struct ValueNode {
    int value;
    struct ValueNode* next;
} ValueNode;

typedef struct Record {
    long offset;
    int key;
    ValueNode* values;
    pthread_mutex_t lock;
} Record;

Record** createRecords(int size, size_t maxMemory) {
    if (size <= 0 || maxMemory <= 0) {
        return NULL; // Handle edge cases
    }

    Record** records = (Record**)malloc(size * sizeof(Record*));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    size_t totalSize = 0;
    for (int i = 0; i < size; ++i) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            perror("Failed to allocate memory for record");
            // Clean up previously allocated records
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records);
            return NULL;
        }

        pthread_mutex_init(&records[i]->lock, NULL);

        records[i]->values = NULL;

        totalSize += sizeof(Record);
        if (totalSize > maxMemory) {
            perror("Exceeded maximum memory limit");
            // Clean up allocated records
            for (int j = 0; j <= i; ++j) {
                pthread_mutex_destroy(&records[j]->lock);
                free(records[j]);
            }
            free(records);
            return NULL;
        }
    }

    return records;
}

void destroyRecords(Record** records, int size) {
    if (!records || size <= 0) {
        return;
    }

    for (int i = 0; i < size; ++i) {
        pthread_mutex_destroy(&records[i]->lock);
        ValueNode* current = records[i]->values;
        while (current) {
            ValueNode* next = current->next;
            free(current);
            current = next;
        }
        free(records[i]);
    }

    free(records);
}

void insertValue(Record* record, int value) {
    pthread_mutex_lock(&record->lock);

    ValueNode* newNode = (ValueNode*)malloc(sizeof(ValueNode));
    if (!newNode) {
        perror("Failed to allocate memory for new value node");
        pthread_mutex_unlock(&record->lock);
        return;
    }

    newNode->value = value;
    newNode->next = record->values;
    record->values = newNode;

    pthread_mutex_unlock(&record->lock);
}

int getValue(Record* record, int index) {
    pthread_mutex_lock(&record->lock);

    ValueNode* current = record->values;
    for (int i = 0; current && i < index; ++i) {
        current = current->next;
    }

    if (!current) {
        pthread_mutex_unlock(&record->lock);
        return -1; // Value not found
    }

    int value = current->value;

    pthread_mutex_unlock(&record->lock);
    return value;
}
