#define MAX_RECORDS 1000
#define KEY_THRESHOLD 10000

typedef struct {
    int value;
} record;

void* initialize_data_structures(void* arg) {
    long* offset_values = (long*)malloc(MAX_RECORDS * sizeof(long));
    if (!offset_values) {
        perror("Failed to allocate memory for offset values");
        return NULL;
    }

    int* keys = (int*)malloc(MAX_RECORDS * sizeof(int));
    if (!keys) {
        free(offset_values);
        perror("Failed to allocate memory for keys");
        return NULL;
    }

    record* records = (record*)malloc(MAX_RECORDS * sizeof(record));
    if (!records) {
        free(offset_values);
        free(keys);
        perror("Failed to allocate memory for records");
        return NULL;
    }

    int key_sum = 0;
    srand(time(NULL));

    for (int i = 0; i < MAX_RECORDS; i++) {
        keys[i] = rand() % KEY_THRESHOLD;
        key_sum += keys[i];
        if (key_sum > KEY_THRESHOLD) {
            fprintf(stderr, "Key sum exceeds threshold. Exiting gracefully.\n");
            free(offset_values);
            free(keys);
            free(records);
            return NULL;
        }
        records[i].value = rand();
    }

    // Simulate concurrent access
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Perform operations with the allocated data structures

    pthread_mutex_unlock(&mutex);

    free(offset_values);
    free(keys);
    free(records);

    return NULL;
}

int main() {
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, initialize_data_structures, NULL) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    if (pthread_join(thread_id, NULL) != 0) {
        perror("Failed to join thread");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
