void find_and_print_largest(int *array, int size) {
    if (size == 0) {
        printf("No valid integers.\n");
        return;
    }

    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    printf("Largest integer: %d\n", largest);
}

