// Define record structure
typedef struct {
    int value;
} Record;

// Define resource collection structure
typedef struct {
    long offset;
    int key;
    Record *record;
} Resource;

// Memory management functions
Resource* allocate_resource(long offset, int key) {
    Resource *resource = (Resource*)malloc(sizeof(Resource));
    if (resource == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    resource->offset = offset;
    resource->key = key;
    resource->record = (Record*)malloc(sizeof(Record));
    if (resource->record == NULL) {
        free(resource);
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    resource->record->value = rand() % 100; // Initialize to random value
    return resource;
}

void deallocate_resource(Resource *resource) {
    if (resource != NULL) {
        free(resource->record);
        free(resource);
    }
}

// Data persistence functions
void serialize_to_file(Resource *resource, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }
    fwrite(&resource->offset, sizeof(long), 1, file);
    fwrite(&resource->key, sizeof(int), 1, file);
    fwrite(resource->record, sizeof(Record), 1, file);
    fclose(file);
}

Resource* deserialize_from_file(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for reading\n");
        return NULL;
    }
    Resource *resource = allocate_resource(0, 0); // Allocate resource with default values
    fread(&resource->offset, sizeof(long), 1, file);
    fread(&resource->key, sizeof(int), 1, file);
    fread(resource->record, sizeof(Record), 1, file);
    fclose(file);
    return resource;
}

// Resource update API function
void update_resource(Resource *resource, int new_value) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);
    resource->record->value = new_value; // Update record value
    pthread_mutex_unlock(&lock);
}

// Resource deletion API function
Resource* delete_resource(Resource *resource) {
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);
    Resource *new_resource = allocate_resource(0, 0); // Allocate new resource with default values
    deallocate_resource(resource); // Deallocate old resource
    pthread_mutex_unlock(&lock);
    return new_resource;
}

