["```javascript
const express = require('express');
const axios = require('axios');
const LRU = require('lru-cache');
const winston = require('winston');

// Initialize Express app
const app = express();

// Set up caching with an LRU cache
const cache = new LRU({
  max: 500,
  ttl: 300 * 1000, // 5 minutes in milliseconds
});

// Configure Winston logger
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

// Middleware for logging requests
app.use((req, res, next) => {
  logger.info(`Request received: ${req.method} ${req.url}`);
  next();
});

// Function to fetch weather data with caching and retry logic
async function getWeatherData(city) {
  const cacheKey = `weather:${city}`;
  if (cache.has(cacheKey)) {
    return cache.get(cacheKey);
  }

  let retries = 3;
  while (retries > 0) {
    try {
      const response = await axios.get(`https://api.weatherapi.com/v1/current.json?key=YOUR_API_KEY&q=${city}`);
      cache.set(cacheKey, response.data);
      return response.data;
    } catch (error) {
      retries--;
      if (retries === 0) {
        logger.error(`Failed to fetch weather data for ${city}:`, error);
        throw error;
      }
      await new Promise(resolve => setTimeout(resolve, 1000)); // Wait before retrying
    }
  }
}

// Route to serve weather data
app.get('/weather/:city', async (req, res) => {
  const city = req.params.city;
  try {
    const weatherData = await getWeatherData(city);
    res.json(weatherData);
  } catch (error) {
    logger.error(`Error serving weather data for ${city}:`, error);
    res.status(500).json({ error: 'Failed to fetch weather data' });
  }
});

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
```

This code sets up an Express server that serves real-time weather data from a third-party API. It uses caching to reduce API load and integrates with Winston for logging. The `getWeatherData` function handles retries in case of transient failures. The solution includes middleware for request logging and is designed to handle varying network conditions and potential API outages gracefully."]

