    class RNG {
    public:
        RNG(uint64_t seed) : gen(seed), dis(0, std::numeric_limits<uint32_t>::max()) {}

        uint32_t generate() {
            return dis(gen);
        }

    private:
        std::mt19937_64 gen;
        std::uniform_int_distribution<> dis;
    };

    class DirectoryManager {
    public:
        static void createDirectoryAndSetEnvVar(const std::string& dirName) {
            std::lock_guard<std::mutex> lock(mutex);
            if (std::getenv("SIM_DIR") == nullptr) {
                std::filesystem::path dirPath = std::filesystem::current_path() / dirName;
                if (std::filesystem::create_directory(dirPath)) {
                    setEnvironmentVariable("SIM_DIR", dirPath.string());
                } else {
                    throw std::runtime_error("Failed to create directory");
                }
            }
        }

    private:
        static void setEnvironmentVariable(const std::string& name, const std::string& value) {
#ifdef _WIN32
            if (!SetEnvironmentVariable(name.c_str(), value.c_str())) {
                throw std::runtime_error("Failed to set environment variable");
            }
#else
            if (setenv(name.c_str(), value.c_str(), 1) != 0) {
                throw std::runtime_error("Failed to set environment variable");
            }
#endif
        }

        static std::mutex mutex;
    };

    std::mutex DirectoryManager::mutex;
}

int main() {
