struct custom_object {
    std::vector<int> int_vector;
    std::map<std::string, std::string> string_map;
    std::shared_ptr<double> double_ptr;

    custom_object(int upper_bound) : int_vector(upper_bound), string_map(), double_ptr(std::make_shared<double>()) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, upper_bound);
        for (int i = 0; i < upper_bound; ++i) {
            int_vector[i] = dis(gen);
        }
        for (int i = 0; i < upper_bound / 10; ++i) {
            string_map[std::to_string(i)] = std::to_string(dis(gen));
        }
        *double_ptr = static_cast<double>(dis(gen)) / upper_bound;
    }
};

struct entity {
    double numerical_value;
    std::string key_identifier;
    custom_object obj;

    entity(double num, const std::string& key, int upper_bound) : numerical_value(num), key_identifier(key), obj(upper_bound) {}
};

class DataHandler {
public:
    static bool initialize_entities(int count, int upper_bound, std::vector<entity>& entities) {
        if (count * sizeof(entity) > available_memory()) {
            return false;
        }
        try {
            for (int i = 0; i < count; ++i) {
                entities.emplace_back(static_cast<double>(i), "key" + std::to_string(i), upper_bound);
            }
            return true;
        } catch (...) {
            clean_up(entities);
            throw;
        }
    }

    static void export_to_json(const std::vector<entity>& entities, const std::string& filename) {
        nlohmann::json j;
        for (const auto& e : entities) {
            j.push_back({{"numerical_value", e.numerical_value}, {"key_identifier", e.key_identifier}, {"obj", e.obj}});
        }
        std::ofstream o(filename);
        o << std::setw(4) << j << std::endl;
    }

private:
    static size_t available_memory() {
        // Simulate memory check
        return 1024 * 1024 * 1024; // 1GB
    }

    static void clean_up(std::vector<entity>& entities) {
        entities.clear();
    }
};

int main() {
    std::vector<entity> entities;
    if (DataHandler::initialize_entities(100, 1000, entities)) {
        DataHandler::export_to_json(entities, "data.json");
    } else {
        std::cerr << "Failed to initialize entities" << std::endl;
    }
    return 0;
}
