int allocate_memory(int key_size, int record_size, int* keys, record** records) {
    *keys = (int*)malloc(key_size * sizeof(int));
    if (*keys == NULL) {
        return -1; // Memory allocation failed
    }

    *records = (record*)malloc(record_size * sizeof(record));
    if (*records == NULL) {
        free(*keys);
        return -2; // Memory allocation failed
    }

    return 0; // Success
}

void initialize_records(int record_size, record* records, int min_value, int max_value) {
    srand(time(NULL));
    for (int i = 0; i < record_size; i++) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }
}

void free_memory(int* keys, record** records) {
    if (*keys != NULL) {
        free(*keys);
        *keys = NULL;
    }

    if (*records != NULL) {
        free(*records);
        *records = NULL;
    }
}

int main() {
    int key_size = 1000;
    int record_size = 1000;
    int* keys = NULL;
    record* records = NULL;

    int result = allocate_memory(key_size, record_size, &keys, &records);
    if (result != 0) {
        printf("Memory allocation failed with error code: %d\n", result);
        return 1;
    }

    initialize_records(record_size, records, 1, 100);

    free_memory(&keys, &records);

    return 0;
}
