entry* create_entries(int num_entries, const char* prefix, size_t max_length, int upper_bound) {
    entry* entries = (entry*)malloc(num_entries * sizeof(entry));
    if (!entries) {
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_entries; ++i) {
        entries[i].length = strlen(prefix) + snprintf(NULL, 0, "%d", i) + 1;
        if (entries[i].length > max_length) {
            free(entries);
            return NULL;
        }
        entries[i].str = (char*)malloc(max_length * sizeof(char));
        if (!entries[i].str) {
            for (int j = 0; j < i; ++j) {
                free(entries[j].str);
            }
            free(entries);
            return NULL;
        }

        snprintf(entries[i].str, max_length, "%s%d", prefix, i);

        for (size_t j = strlen(prefix); j < entries[i].length - 1; ++j) {
            entries[i].str[j] = '0' + rand() % upper_bound;
        }
        entries[i].str[entries[i].length - 1] = '\0';
    }

    return entries;
}

void free_entries(entry* entries, int num_entries) {
    for (int i = 0; i < num_entries; ++i) {
        free(entries[i].str);
    }
    free(entries);
