Measurement* allocateMeasurementArray(int size) {
    Measurement* array = (Measurement*)malloc(size * sizeof(Measurement));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed for measurement array\n");
        return NULL;
    }
    return array;
}

void initializeArrays(float* floatKeys, Measurement* measurements, int size, double lowerBound, double upperBound) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        floatKeys[i] = (float)(rand() % ((upperBound - lowerBound + 1) * 100)) / 100.0 + lowerBound;
        measurements[i].temperature = (double)(rand() % ((upperBound - lowerBound + 1) * 100)) / 100.0 + lowerBound;
    }
}

void freeArrays(float* floatKeys, Measurement* measurements) {
    if (floatKeys != NULL) {
        free(floatKeys);
    }
    if (measurements != NULL) {
        free(measurements);
    }
}

double calculateAverageTemperature(Measurement* measurements, int size) {
    double sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += measurements[i].temperature;
    }
    return sum / size;
}

int main() {
    int size;
    printf("Enter the number of temperature readings: ");
    scanf("%d", &size);

    float* floatKeys = allocateFloatArray(size);
    Measurement* measurements = allocateMeasurementArray(size);

    if (floatKeys == NULL || measurements == NULL) {
        freeArrays(floatKeys, measurements);
        return 1;
    }

    initializeArrays(floatKeys, measurements, size, -20.0, 40.0);

    double averageTemperature = calculateAverageTemperature(measurements, size);
    printf("Average Temperature: %.2f\n", averageTemperature);

    freeArrays(floatKeys, measurements);
    return 0;
}
