typedef struct Node {
    int value;
    struct Node* next;
} Node;

typedef struct Record {
    long offset;
    int key;
    Node* data;
} Record;

Record** createRecords(int size, long maxOffset, int maxValue) {
    if (size <= 0 || maxOffset < 0 || maxValue < 0) {
        fprintf(stderr, "Invalid input values.\n");
        return NULL;
    }

    Record** records = (Record**)malloc(size * sizeof(Record*));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records array.\n");
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed for record %d.\n", i);
            // Free previously allocated records
            for (int j = 0; j < i; j++) {
                free(records[j]);
            }
            free(records);
            return NULL;
        }

        records[i]->offset = rand() % maxOffset;
        records[i]->key = rand() % maxValue;
        records[i]->data = NULL;
    }

    return records;
}

void addDataToRecord(Record* record, int value) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed for new node.\n");
        return;
    }

    newNode->value = value;
    newNode->next = record->data;
    record->data = newNode;
}

void freeRecords(Record** records, int size) {
    for (int i = 0; i < size; i++) {
        Node* current = records[i]->data;
        while (current) {
            Node* next = current->next;
            free(current);
            current = next;
        }
        free(records[i]);
    }
    free(records);
}

// Additional functions for searching, calculating averages, etc. can be added here

int main() {
    int size = 10;
    long maxOffset = 1000;
    int maxValue = 100;

    Record** records = createRecords(size, maxOffset, maxValue);
