void find_min_max(float *array, int size, float *min, float *max) {
    if (size <= 0) {
        fprintf(stderr, "Invalid array size\n");
        return;
    }

    *min = array[0];
    *max = array[0];

    for (int i = 1; i < size; i++) {
        if (array[i] < *min) {
            *min = array[i];
        }
        if (array[i] > *max) {
            *max = array[i];
        }
    }
}

