#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <time.h>
#include <pthread.h>

#define MAX_STRUCTS 10000
#define MIN_INT_RANGE 1
#define MAX_INT_RANGE 100

typedef struct {
    char* filename;
    long offset;
    int random_value;
} MyStruct;

void log_init_details(MyStruct* s) {
    // Implement logging service integration here
}

int populate_structs(MyStruct** structs, const char* directory, int num_threads) {
    DIR* dir = opendir(directory);
    if (!dir) return -1; // Directory not found or cannot open

    struct dirent* entry;
    int count = 0;

    while ((entry = readdir(dir)) != NULL && count < MAX_STRUCTS) {
        if (entry->d_type == DT_REG) { // Regular file
            structs[count] = malloc(sizeof(MyStruct));
            if (!structs[count]) return -1; // Memory allocation failed

            structs[count]->filename = strdup(entry->d_name);
            if (!structs[count]->filename) {
                free(structs[count]);
                return -1; // Memory allocation failed
            }

            srand(time(NULL)); // Seed for random number generation
            structs[count]->offset = rand();
            structs[count]->random_value = MIN_INT_RANGE + rand() % (MAX_INT_RANGE - MIN_INT_RANGE + 1);

            log_init_details(structs[count]);
            count++;
        }
    }

    closedir(dir);
    return count;
}

void free_structs(MyStruct** structs, int num_structs) {
    for (int i = 0; i < num_structs; i++) {
        free(structs[i]->filename);
        free(structs[i]);
    }
}

// Example usage
int main() {
    MyStruct* structs[MAX_STRUCTS];
    int num_threads = 1;
    int num_structs = populate_structs(structs, "/path/to/directory", num_threads);

    if (num_structs < 0) {
        printf("Error populating structures\n");
        return 1;
    }

    // Use the structs array...

    free_structs(structs, num_structs);
    return 0;
}
```

