#include <stdio.h>
#include <stdlib.h>

typedef struct event {
    unsigned long timestamp;
    int type;
    struct event *next;
} Event;

Event* insert_event(Event **head, unsigned long timestamp, int type, int capacity) {
    if (*head == NULL || count_events(*head) < capacity) {
        Event *new_event = (Event *)malloc(sizeof(Event));
        new_event->timestamp = timestamp;
        new_event->type = type;
        new_event->next = *head;
        *head = new_event;
        return *head;
    } else {
        printf("Capacity limit reached. Cannot insert more events.\n");
        return *head;
    }
}

void remove_oldest_event(Event **head) {
    if (*head == NULL) {
        printf("List is empty. No event to remove.\n");
        return;
    }
    Event *temp = *head;
    *head = (*head)->next;
    free(temp);
}

int count_events(Event *head) {
    int count = 0;
    while (head != NULL) {
        count++;
        head = head->next;
    }
    return count;
}
