Record* initializeRecords(int size, int minValue, int maxValue) {
    if (size <= 0 || minValue > maxValue) {
        return NULL;
    }

    Record* records = (Record*)malloc(size * sizeof(Record));
    if (!records) {
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < size; ++i) {
        records[i].value = rand() % (maxValue - minValue + 1) + minValue;

        records[i].keyPtr = (int*)malloc(sizeof(int));
        if (!records[i].keyPtr) {
            // Clean up previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(records[j].keyPtr);
                free(records[j].offsetPtr);
            }
            free(records);
            return NULL;
        }

        records[i].offsetPtr = (long*)malloc(sizeof(long));
        if (!records[i].offsetPtr) {
            // Clean up previously allocated memory
            for (int j = 0; j <= i; ++j) {
                free(records[j].keyPtr);
                free(records[j].offsetPtr);
            }
            free(records);
            return NULL;
        }

        *records[i].keyPtr = records[i].value;
        *records[i].offsetPtr = i * sizeof(Record); // Example offset calculation
    }

    return records;
}
