#define MAX_RECORDS 1000
#define COMPRESSION_LEVEL 9

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    int size;
    int capacity;
} dataset;

typedef struct {
    char *message;
    int type; // 1 for allocation, 2 for validation, 3 for initialization
} log_entry;

dataset* create_dataset() {
    dataset *ds = (dataset*)malloc(sizeof(dataset));
    ds->offsets = (long*)malloc(MAX_RECORDS * sizeof(long));
    ds->keys = (int*)malloc(MAX_RECORDS * sizeof(int));
    ds->records = (record*)malloc(MAX_RECORDS * sizeof(record));
    ds->size = 0;
    ds->capacity = MAX_RECORDS;
    return ds;
}

void free_dataset(dataset *ds) {
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    free(ds);
}

int initialize_dataset(dataset *ds, int num_records) {
    if (num_records > ds->capacity) {
        // Resize dataset
        long *new_offsets = (long*)realloc(ds->offsets, num_records * sizeof(long));
        int *new_keys = (int*)realloc(ds->keys, num_records * sizeof(int));
        record *new_records = (record*)realloc(ds->records, num_records * sizeof(record));

        if (!new_offsets || !new_keys || !new_records) {
            free_dataset(ds);
            return -1; // Memory allocation failed
        }

        ds->offsets = new_offsets;
        ds->keys = new_keys;
        ds->records = new_records;
        ds->capacity = num_records;
    }

    for (int i = 0; i < num_records; i++) {
        ds->offsets[i] = i * sizeof(record);
        ds->keys[i] = i;
        ds->records[i].value = i;
    }

    ds->size = num_records;
    return 0; // Initialization successful
}

void log_event(log_entry *log, const char *message, int type) {
    log->message = strdup(message);
    log->type = type;
}

