    dataset *ds = create_dataset();
    if (initialize_dataset(ds, 1000) != 0) {
        printf("Failed to initialize dataset\n");
        free_dataset(ds);
        return 1;
    }

    // Perform operations on ds...

    free_dataset(ds);
