typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t allocation_lock = PTHREAD_MUTEX_INITIALIZER;
int successful_allocations = 0;
int failed_allocations = 0;

NFAPI_CRC_INDICATION_PDU_T* allocate_nfaapi_crc_indication_pdu(int N) {
    pthread_mutex_lock(&allocation_lock);

    if (successful_allocations + N > MAX_ALLOCATIONS || 
        (successful_allocations * sizeof(NFAPI_CRC_INDICATION_PDU_T)) + (N * sizeof(NFAPI_CRC_INDICATION_PDU_T)) > MEMORY_LIMIT) {

        failed_allocations++;
        pthread_mutex_unlock(&allocation_lock);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        failed_allocations++;
        pthread_mutex_unlock(&allocation_lock);
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        array[i].RNTI = rand() % 256;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 100;
        array[i].CRCFLAG = rand() % 2; // Randomly set to either 0 or 1
    }

    successful_allocations += N;
    pthread_mutex_unlock(&allocation_lock);
    return array;
}

void log_allocation_stats() {
    printf("Successful allocations: %d\n", successful_allocations);
    printf("Failed allocations: %d\n", failed_allocations);
}
