#define MAX_STRUCTS 10000
#define CONFIG_FILE "config.xml"

typedef struct {
    char* filename;
    long offset;
    int value;
} MyStruct;

void logInitialization(MyStruct* s) {
    // Simulate logging to an external service
    printf("Initialized: %s, Offset: %ld, Value: %d\n", s->filename, s->offset, s->value);
}

int loadConfig(char** tiles, int* width, int* height, double* cameraSpeed) {
    FILE* file = fopen(CONFIG_FILE, "r");
    if (!file) return -1;

    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file)) {
        if (sscanf(buffer, "<tiles>%s</tiles>", *tiles) == 1) continue;
        if (sscanf(buffer, "<width>%d</width>", width) == 1) continue;
        if (sscanf(buffer, "<height>%d</height>", height) == 1) continue;
        if (sscanf(buffer, "<cameraSpeed>%lf</cameraSpeed>", cameraSpeed) == 1) continue;
    }

    fclose(file);
    return 0;
}

void* initializeStructs(void* arg) {
    int start = *(int*)arg;
    MyStruct* structs = (MyStruct*)malloc(MAX_STRUCTS * sizeof(MyStruct));
    if (!structs) return NULL;

    DIR* dir = opendir(".");
    struct dirent* ent;
    int count = 0;

    while ((ent = readdir(dir)) != NULL && count < MAX_STRUCTS) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) continue;

        structs[count].filename = strdup(ent->d_name);
        structs[count].offset = rand();
        structs[count].value = rand() % 100;
        logInitialization(&structs[count]);
        count++;
    }

    closedir(dir);

    free(structs);
    return NULL;
}

int main() {
    srand(time(NULL));

    pthread_t threads[MAX_STRUCTS / 10];
    int thread_ids[MAX_STRUCTS / 10];

    for (int i = 0; i < MAX_STRUCTS / 10; i++) {
        thread_ids[i] = i * 1000;
        if (pthread_create(&threads[i], NULL, initializeStructs, &thread_ids[i]) != 0) {
            perror("Failed to create thread");
            return -1;
        }
    }

    for (int i = 0; i < MAX_STRUCTS / 10; i++) {
        pthread_join(threads[i], NULL);
    }

    char* tiles;
    int width, height;
    double cameraSpeed;

    if (loadConfig(&tiles, &width, &height, &cameraSpeed) != 0) {
        printf("Failed to load config file\n");
        return -1;
    }

    printf("Loaded config: Tiles=%s, Width=%d, Height=%d, Camera Speed=%.2f\n", tiles, width, height, cameraSpeed);

    free(tiles);
    return 0;
}
