    double temperature;
} sensor_data;

sensor_data* allocate_sensor_data(int num_records, long initial_timestamp, double min_temp, double max_temp) {
    if (num_records <= 0 || initial_timestamp < 0 || min_temp > max_temp) {
        return NULL; // Invalid input parameters
    }

    size_t total_size = num_records * sizeof(sensor_data);
    sensor_data* data = (sensor_data*)malloc(total_size);

    if (data == NULL) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < num_records; ++i) {
        data[i].timestamp = initial_timestamp + i;
        double temp = min_temp + (max_temp - min_temp) * ((double)i / (num_records - 1));
        data[i].temperature = temp;
    }

    return data;
}

void free_sensor_data(sensor_data* data) {
    if (data != NULL) {
        free(data);
    }
}
