#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>

#define MAX_HOSTNAMES 100
#define MAX_IP_ADDRESSES 5
#define TIMEOUT_SEC 5

typedef struct {
    char hostname[256];
    int ip_count;
    struct in_addr ips[MAX_IP_ADDRESSES];
    int status; // 0 for success, -1 for error
    double resolution_time;
} DNSResponse;

int resolve_hostnames(char *hostnames[], int count, DNSResponse responses[]) {
    int total_resolved = 0;
    for (int i = 0; i < count; i++) {
        struct addrinfo hints, *res, *p;
        memset(&hints, 0, sizeof(hints));
        hints.ai_family = AF_INET;
        hints.ai_socktype = SOCK_STREAM;

        int status = getaddrinfo(hostnames[i], NULL, &hints, &res);
        if (status != 0) {
            responses[i].status = -1;
            continue;
        }

        responses[i].ip_count = 0;
        for (p = res; p != NULL && responses[i].ip_count < MAX_IP_ADDRESSES; p = p->ai_next) {
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            memcpy(&responses[i].ips[responses[i].ip_count], &ipv4->sin_addr, sizeof(struct in_addr));
            responses[i].ip_count++;
        }

        freeaddrinfo(res);
        responses[i].status = 0;
        total_resolved++;
    }
    return total_resolved;
}

void print_responses(DNSResponse responses[], int count) {
    for (int i = 0; i < count; i++) {
        printf("Hostname: %s\n", responses[i].hostname);
        if (responses[i].status == 0) {
            printf("IP Addresses:\n");
            for (int j = 0; j < responses[i].ip_count; j++) {
                char ip_str[INET_ADDRSTRLEN];
                inet_ntop(AF_INET, &responses[i].ips[j], ip_str, INET_ADDRSTRLEN);
                printf("%s\n", ip_str);
            }
        } else {
            printf("Error: DNS resolution failed\n");
        }
    }
}

int main() {
    char *hostnames[MAX_HOSTNAMES] = {"google.com", "nonexistentdomain1234567890.com", "example.com"};
    int count = sizeof(hostnames) / sizeof(hostnames[0]);
    DNSResponse responses[count];

    for (int i = 0; i < count; i++) {
        strncpy(responses[i].hostname, hostnames[i], sizeof(responses[i].hostname));
    }

    int resolved_count = resolve_hostnames(hostnames, count, responses);
    print_responses(responses, resolved_count);

    return 0;
}
```

This code provides a basic implementation of a DNS resolver in C. It includes error handling, support for multiple IP addresses per hostname, and a simple client function to demonstrate usage. The actual DNS resolution is performed using the `getaddrinfo` function from the `<netdb.h>` library, which handles both IPv4 and IPv6 addresses. The code also includes basic validation of input hostnames and a mechanism to limit the number of concurrent queries (though this is not explicitly implemented in the provided code).']

