<?php

class UserAccountManager {
    private $db;
    private $logger;

    public function __construct($db, $logger) {
        $this->db = $db;
        $this->logger = $logger;
    }

    public function manageUser($_REQUEST) {
        // Validate CSRF token
        if (!isset($_REQUEST['csrf_token']) || !self::validateCsrfToken($_REQUEST['csrf_token'])) {
            return json_encode(['message' => 'error', 'details' => 'Invalid CSRF token']);
        }

        $sub_action = $_REQUEST['sub_action'] ?? '';
        $id = isset($_REQUEST['id']) ? intval($_REQUEST['id']) : null;
        $name = $_REQUEST['name'] ?? '';
        $email = $_REQUEST['email'] ?? '';
        $password = $_REQUEST['password'] ?? '';
        $locale = $_REQUEST['locale'] ?? 'en';

        try {
            switch ($sub_action) {
                case 'create':
                    if (!self::validateData($name, $email, $password)) {
                        return json_encode(['message' => 'error', 'details' => 'Invalid data']);
                    }
                    self::Save('INSERT INTO users (name, email, password) VALUES (:name, :email, :password)', [
                        ':name' => $name,
                        ':email' => $email,
                        ':password' => password_hash($password, PASSWORD_DEFAULT)
                    ]);
                    break;
                case 'update':
                    if (!self::validateData($name, $email, $password)) {
                        return json_encode(['message' => 'error', 'details' => 'Invalid data']);
                    }
                    self::Save('UPDATE users SET name = :name, email = :email, password = :password WHERE id = :id', [
                        ':name' => $name,
                        ':email' => $email,
                        ':password' => password_hash($password, PASSWORD_DEFAULT),
                        ':id' => $id
                    ]);
                    break;
                case 'delete':
                    self::Save('DELETE FROM users WHERE id = :id', [':id' => $id]);
                    break;
                case 'retrieve':
                    if ($id === null) {
                        return json_encode(['message' => 'error', 'details' => 'Missing user ID']);
                    }
                    $user = self::Get('SELECT * FROM users WHERE id = :id', [':id' => $id]);
                    if ($user) {
                        return json_encode($user);
                    } else {
                        return json_encode(['message' => 'error', 'details' => 'User not found']);
                    }
                case 'reset_password':
                    if (!self::validateData($email)) {
                        return json_encode(['message' => 'error', 'details' => 'Invalid data']);
                    }
                    $user = self::Get('SELECT * FROM users WHERE email = :email', [':email' => $email]);
                    if ($user) {
                        // Send password reset link
                        $resetToken = bin2hex(random_bytes(32));
                        self::Save('UPDATE users SET reset_token = :reset_token, reset_token_expires = NOW() + INTERVAL 1 HOUR WHERE id = :id', [
                            ':reset_token' => $resetToken,
                            ':id' => $user['id']
                        ]);
                        // Send email with reset link
                        self::sendPasswordResetEmail($email, $resetToken);
                        return json_encode(['message' => 'success']);
                    } else {
                        return json_encode(['message' => 'error', 'details' => 'User not found']);
                    }
                default:
                    return json_encode(['message' => 'error', 'details' => 'Invalid sub_action']);
            }
        } catch (PDOException $e) {
            self::logError($e->getMessage());
            return json_encode(['message' => 'error', 'details' => 'Database error']);
        }

        return json_encode(['message' => 'success']);
    }

    private static function validateData($name, $email, $password = null) {
        if (empty($name) || empty($email)) {
            return false;
        }
        if ($password && !self::validatePassword($password)) {
            return false;
        }
        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            return false;
        }
        return true;
    }

    private static function validatePassword($password) {
        $regex = '/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/';
        return preg_match($regex, $password);
    }

    private static function validateCsrfToken($token) {
        // Implement CSRF token validation logic
        return true;
    }

    private static function Save($sql, $params) {
        $stmt = self::$db->prepare($sql);
        $stmt->execute($params);
    }

    private static function Get($sql, $params) {
        $stmt = self::$db->prepare($sql);
        $stmt->execute($params);
        return $stmt->fetch(PDO::FETCH_ASSOC);
    }

    private static function sendPasswordResetEmail($email, $resetToken) {
