#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_RECORDS 1000

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record** records;
    char** audit_log;
    int* metadata;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} data_structures;

int initialize_data_structures(data_structures* ds) {
    ds->capacity = MAX_RECORDS;
    ds->size = 0;
    ds->offsets = (long*)malloc(ds->capacity * sizeof(long));
    ds->keys = (int*)malloc(ds->capacity * sizeof(int));
    ds->records = (record**)malloc(ds->capacity * sizeof(record*));
    ds->audit_log = (char**)malloc(ds->capacity * sizeof(char*));
    ds->metadata = (int*)malloc(ds->capacity * sizeof(int));

    if (!ds->offsets || !ds->keys || !ds->records || !ds->audit_log || !ds->metadata) {
        cleanup_data_structures(ds);
        return -1;
    }

    pthread_mutex_init(&ds->mutex, NULL);

    for (size_t i = 0; i < ds->capacity; ++i) {
        ds->records[i] = NULL;
        ds->audit_log[i] = NULL;
    }

    return 0;
}

void cleanup_data_structures(data_structures* ds) {
    pthread_mutex_lock(&ds->mutex);

    for (size_t i = 0; i < ds->capacity; ++i) {
        free(ds->records[i]);
        free(ds->audit_log[i]);
    }

    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    free(ds->audit_log);
    free(ds->metadata);

    pthread_mutex_unlock(&ds->mutex);
}

void resize_data_structures(data_structures* ds, size_t new_capacity) {
    pthread_mutex_lock(&ds->mutex);

    long* new_offsets = (long*)realloc(ds->offsets, new_capacity * sizeof(long));
    int* new_keys = (int*)realloc(ds->keys, new_capacity * sizeof(int));
    record** new_records = (record**)realloc(ds->records, new_capacity * sizeof(record*));
    char** new_audit_log = (char**)realloc(ds->audit_log, new_capacity * sizeof(char*));
    int* new_metadata = (int*)realloc(ds->metadata, new_capacity * sizeof(int));

    if (!new_offsets || !new_keys || !new_records || !new_audit_log || !new_metadata) {
        cleanup_data_structures(ds);
        pthread_mutex_unlock(&ds->mutex);
        return;
    }

    ds->offsets = new_offsets;
    ds->keys = new_keys;
    ds->records = new_records;
    ds->audit_log = new_audit_log;
    ds->metadata = new_metadata;

    for (size_t i = ds->capacity; i < new_capacity; ++i) {
        ds->records[i] = NULL;
        ds->audit_log[i] = NULL;
    }

    ds->capacity = new_capacity;

    pthread_mutex_unlock(&ds->mutex);
}

int add_record(data_structures* ds, int key, record* rec) {
    pthread_mutex_lock(&ds->mutex);

    if (ds->size >= ds->capacity) {
        resize_data_structures(ds, ds->capacity * 2);
    }

    ds->offsets[ds->size] = (long)rec;
    ds->keys[ds->size] = key;
    ds->records[ds->size] = rec;
    ds->audit_log[ds->size] = "Added";
    ds->metadata[ds->size] = 1;

    ++ds->size;

    pthread_mutex_unlock(&ds->mutex);

    return 0;
}

record* find_record(data_structures* ds, int key) {
    pthread_mutex_lock(&ds->mutex);

    for (size_t i = 0; i < ds->size; ++i) {
        if (ds->keys[i] == key) {
            ds->metadata[i]++;
            pthread_mutex_unlock(&ds->mutex);
            return ds->records[i];
        }
    }

    pthread_mutex_unlock(&ds->mutex);
    return NULL;
}

void print_largest_integer() {
    int num, largest = INT_MIN;

    while (scanf("%d", &num) != EOF) {
        if (num > largest) {
            largest = num;
        }
    }

    printf("Largest integer: %d\n", largest);
}
