#include <stdio.h>
#include <stdlib.h>

#define MAX_SIZE 10000
#define MIN_VALUE -1000000
#define MAX_VALUE 1000000

typedef struct {
    int *data;
    size_t size;
    size_t capacity;
} MemoryPool;

MemoryPool* create_memory_pool(size_t initial_capacity) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->data = (int*)malloc(initial_capacity * sizeof(int));
    pool->size = 0;
    pool->capacity = initial_capacity;
    return pool;
}

void destroy_memory_pool(MemoryPool *pool) {
    free(pool->data);
    free(pool);
}

void resize_memory_pool(MemoryPool *pool, size_t new_capacity) {
    int *new_data = (int*)realloc(pool->data, new_capacity * sizeof(int));
    if (new_data == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pool->data = new_data;
    pool->capacity = new_capacity;
}

void add_to_memory_pool(MemoryPool *pool, int value) {
    if (pool->size >= pool->capacity) {
        resize_memory_pool(pool, pool->capacity * 2);
    }
    pool->data[pool->size++] = value;
}

int find_largest_integer(MemoryPool *pool) {
    if (pool->size == 0) {
        printf("No valid integers.\n");
        return -1; // Assuming -1 as an error code
    }
    int largest = pool->data[0];
    for (size_t i = 1; i < pool->size; ++i) {
        if (pool->data[i] > largest) {
            largest = pool->data[i];
        }
    }
    return largest;
}

double calculate_average(MemoryPool *pool) {
    if (pool->size == 0) {
        printf("No valid integers.\n");
        return -1; // Assuming -1 as an error code
    }
    double sum = 0;
    for (size_t i = 0; i < pool->size; ++i) {
        sum += pool->data[i];
    }
    return sum / pool->size;
}

int main() {
    MemoryPool *pool = create_memory_pool(100);
    int value;
    while (scanf("%d", &value) == 1) {
        if (value >= MIN_VALUE && value <= MAX_VALUE) {
            add_to_memory_pool(pool, value);
        }
    }

    printf("Largest integer: %d\n", find_largest_integer(pool));
    printf("Average: %.2f\n", calculate_average(pool));

    destroy_memory_pool(pool);
    return 0;
}
