// Define structures for measurement data
typedef struct {
    double humidity;
} Measurement;

// Function prototypes
float* allocate_temperature_array(int size);
Measurement* allocate_humidity_array(int size);
time_t* allocate_timestamp_array(int size);
void initialize_data(float* temperatures, Measurement* humidities, time_t* timestamps, int size);
void calculate_and_print_averages(float* temperatures, Measurement* humidities, int size);
void free_memory(float* temperatures, Measurement* humidities, time_t* timestamps);

int main() {
    int size;
    printf("Enter the number of measurements: ");
    scanf("%d", &size);

    // Allocate memory for data arrays
    float* temperatures = allocate_temperature_array(size);
    Measurement* humidities = allocate_humidity_array(size);
    time_t* timestamps = allocate_timestamp_array(size);

    if (temperatures == NULL || humidities == NULL || timestamps == NULL) {
        printf("Memory allocation failed.\n");
        return 1;
    }

    // Initialize data arrays with random values
    initialize_data(temperatures, humidities, timestamps, size);

    // Calculate and print averages
    calculate_and_print_averages(temperatures, humidities, size);

    // Free allocated memory
    free_memory(temperatures, humidities, timestamps);

    return 0;
}

// Function to allocate memory for temperature array
float* allocate_temperature_array(int size) {
    return (float*)malloc(size * sizeof(float));
}

// Function to allocate memory for humidity array
Measurement* allocate_humidity_array(int size) {
    return (Measurement*)malloc(size * sizeof(Measurement));
}

// Function to allocate memory for timestamp array
time_t* allocate_timestamp_array(int size) {
    return (time_t*)malloc(size * sizeof(time_t));
}

// Function to initialize data arrays with random values
void initialize_data(float* temperatures, Measurement* humidities, time_t* timestamps, int size) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        temperatures[i] = ((float)rand() / RAND_MAX) * 40.0 - 10.0; // Random temperature between -10 and 30
        humidities[i].humidity = ((double)rand() / RAND_MAX) * 100.0; // Random humidity between 0 and 100
        timestamps[i] = time(NULL); // Current timestamp
    }
}

// Function to calculate and print averages of temperature and humidity
void calculate_and_print_averages(float* temperatures, Measurement* humidities, int size) {
    float sum_temp = 0.0;
    double sum_humidity = 0.0;

    for (int i = 0; i < size; i++) {
        sum_temp += temperatures[i];
        sum_humidity += humidities[i].humidity;
    }

    printf("Average Temperature: %.2f\n", sum_temp / size);
    printf("Average Humidity: %.2f%%\n", sum_humidity / size);
}

// Function to free allocated memory
void free_memory(float* temperatures, Measurement* humidities, time_t* timestamps) {
    free(temperatures);
    free(humidities);
    free(timestamps);
}
