#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int value;
} Record;

Record* init_records_from_config(const char* config_file_path, long** offsets, int** keys, size_t* num_records) {
    FILE* file = fopen(config_file_path, "r");
    if (!file) {
        perror("Failed to open configuration file");
        return NULL;
    }

    // Read the number of records from the first line
    fscanf(file, "%zu", num_records);
    Record* records = (Record*)malloc(*num_records * sizeof(Record));
    *offsets = (long*)malloc(*num_records * sizeof(long));
    *keys = (int*)malloc(*num_records * sizeof(int));

    if (!records || !*offsets || !*keys) {
        perror("Failed to allocate memory");
        free(records);
        free(*offsets);
        free(*keys);
        fclose(file);
        return NULL;
    }

    for (size_t i = 0; i < *num_records; ++i) {
        fscanf(file, "%ld %d", &(*offsets)[i], &(*keys)[i]);
        records[i].value = 0; // Initialize value
    }

    fclose(file);
    return records;
}

void free_records(Record* records, long* offsets, int* keys, size_t num_records) {
    free(records);
    free(offsets);
    free(keys);
}
