function refreshDialogFields(fieldNamesToRefresh) {
    var dialogFields = document.querySelectorAll('.dialog-field');
    fieldNamesToRefresh.forEach(function(fieldName) {
        var field = Array.from(dialogFields).find(f => f.name === fieldName);
        if (field) {
            window.parent.postMessage({fieldName: fieldName, value: field.value}, '*');
            window.addEventListener('message', function(event) {
                if (event.data.success && event.data.fieldName === fieldName) {
                    field.value = event.data.newValue;
                }
            });
        }
    });
}
