['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    char* str;
    int value;
    struct Node* next;
} Node;

Node* create_node(const char* str, int value) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    new_node->str = strdup(str);
    if (!new_node->str) {
        free(new_node);
        fprintf(stderr, "Memory allocation failed for string\n");
        return NULL;
    }
    new_node->value = value;
    new_node->next = NULL;
    return new_node;
}

void free_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->str);
        free(current);
        current = next;
    }
}

Node* insert_sorted(Node* head, const char* str, int value) {
    Node* new_node = create_node(str, value);
    if (!new_node) return head;

    if (head == NULL || head->value >= value) {
        new_node->next = head;
        return new_node;
    }

    Node* current = head;
    while (current->next != NULL && current->next->value < value) {
        current = current->next;
    }
    new_node->next = current->next;
    current->next = new_node;

    return head;
}

int main() {
    Node* head = NULL;
    const char* strings[] = {"apple", "banana", "cherry"};
    int values[] = {3, 1, 2};
    size_t num_nodes = sizeof(strings) / sizeof(strings[0]);

    for (size_t i = 0; i < num_nodes; ++i) {
        head = insert_sorted(head, strings[i], values[i]);
    }

    // Print the list to verify
    Node* current = head;
    while (current != NULL) {
        printf("String: %s, Value: %d\n", current->str, current->value);
        current = current->next;
    }

    free_list(head);

    return 0;
}
```

