#include <pthread.h>

typedef struct {
    int* key;
} record;

void* manage_memory(int n, int m, int min, int max) {
    long* offsets = aligned_alloc(64, n * sizeof(long));
    if (!offsets) return NULL;

    record* records = malloc(m * sizeof(record));
    if (!records) {
        free(offsets);
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < m; ++i) {
        records[i].key = malloc(sizeof(int));
        if (!records[i].key) {
            for (int j = 0; j < i; ++j) free(records[j].key);
            free(records);
            free(offsets);
            return NULL;
        }

        int random_value = rand() % (max - min + 1) + min;
        *records[i].key = random_value;

        pthread_mutex_lock(&mutex);
        // Perform any necessary updates or access patterns here
        pthread_mutex_unlock(&mutex);
    }

    // Return the initialized records
    return records;
}
