#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>

#define MAX_SIZE 1000

typedef struct {
    long offset;
    int key;
    bool valid;
} record;

bool memory_error = false;

void cleanup(record **offsets, int *keys, record **records, size_t size) {
    free(*offsets);
    free(*keys);
    free(*records);
}

record* initialize_records(size_t size) {
    if (size > MAX_SIZE) {
        fprintf(stderr, "Error: Size exceeds maximum limit.\n");
        memory_error = true;
        return NULL;
    }

    long *offsets = malloc(size * sizeof(long));
    int *keys = malloc(size * sizeof(int));
    record *records = malloc(size * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        memory_error = true;
        cleanup(&offsets, &keys, &records, size);
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        offsets[i] = rand() % 1000000L; // Random offset within a range
        keys[i] = i; // Unique key for each record
        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].valid = (offsets[i] != 0); // Valid if offset is not zero
    }

    return records;
}

int main() {
    size_t size;
    printf("Enter the number of records: ");
    scanf("%zu", &size);

    record *records = initialize_records(size);
    if (!records) {
        return EXIT_FAILURE;
    }

    // Use the records...

    cleanup(&records, NULL, NULL, size);
    return EXIT_SUCCESS;
}
```

### Explanation:
1. **Memory Allocation and Error Handling**:
   - The function `initialize_records` dynamically allocates memory for three arrays: one for offsets (`long`), one for keys (`int`), and one for records (`record`).
   - It checks if the requested size exceeds a predefined limit (`MAX_SIZE`) to prevent resource exhaustion.
   - If any allocation fails, it sets a global error flag (`memory_error`) and returns `NULL`.

2. **Cleanup Routine**:
   - The `cleanup` function is used to free all allocated memory when the function exits, ensuring that resources are freed even in the presence of errors.

3. **Record Initialization**:
   - The records are populated with unique keys and random offsets.
   - Each record's validity flag is set based on whether its offset is non-zero.

4. **Concurrency Considerations**:
   - The code does not explicitly handle race conditions, as it assumes a single-threaded environment for simplicity. For multi-threaded environments, additional synchronization mechanisms (e.g., mutexes) would be required to protect shared data.

5. **Performance and Memory Management**:
   - The use of separate memory blocks for each array can help optimize cache utilization and reduce fragmentation.
   - However, the decision to use a single block or multiple blocks depends on the specific requirements and constraints of the application.

6. **Documentation**:
   - The code includes comments explaining key parts of the implementation, such as error handling and memory allocation.
   - The `main` function demonstrates how to use the `initialize_records` function and clean up resources properly.

This solution provides a basic framework for managing memory dynamically in C, with considerations for error handling, resource management, and performance optimization.']

['```javascript
function generateSidebarMenu(config) {
    // Function to create a menu item element
    function createMenuItem(item) {
        const li = document.createElement('li');
        if (item.type === 'link') {
            const a = document.createElement('a');
            a.href = item.url;
            a.textContent = item.label;
            li.appendChild(a);
        } else if (item.type === 'submenu') {
            const ul = document.createElement('ul');
            item.items.forEach(subItem => {
                ul.appendChild(createMenuItem(subItem));
            });
            li.appendChild(ul);
        }
        return li;
    }

    // Function to create a collapsible sidebar
    function createCollapsibleSidebar() {
        const sidebar = document.createElement('div');
        sidebar.classList.add('sidebar', 'collapsible');

        const menuItems = config.menu.map(item => createMenuItem(item));
        menuItems.forEach(item => sidebar.appendChild(item));

        return sidebar;
    }

    // Function to create a hamburger menu for mobile
    function createHamburgerMenu() {
        const hamburger = document.createElement('button');
        hamburger.classList.add('hamburger');
        hamburger.textContent = '☰';

        const sidebar = createCollapsibleSidebar();
        sidebar.style.display = 'none';

        hamburger.addEventListener('click', () => {
            sidebar.style.display = sidebar.style.display === 'block' ? 'none' : 'block';
        });

        return [hamburger, sidebar];
    }

    // Function to handle lazy loading
    function handleLazyLoading() {
        const observer = new IntersectionObserver(entries => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.classList.add('loaded');
                    observer.unobserve(entry.target);
                }
            });
        });

        document.querySelectorAll('.lazy-load').forEach(item => {
            item.classList.add('lazy-load');
            observer.observe(item);
        });
    }

    // Main function to generate the sidebar
    const [hamburger, sidebar] = createHamburgerMenu();
    handleLazyLoading();

    return `
        <div class="sidebar-container">
            ${hamburger.outerHTML}
            ${sidebar.outerHTML}
        </div>
    `;
}

// Example usage:
const config = {
    menu: [
        { type: 'link', label: 'Home', url: '/' },
        { type: 'submenu', label: 'Products', items: [
            { type: 'link', label: 'Product 1', url: '/product1' },
            { type: 'link', label: 'Product 2', url: '/product2' }
        ]}
    ]
};

const sidebarHTML = generateSidebarMenu(config);
document.body.innerHTML += sidebarHTML;
```

