#define CACHE_LINE_SIZE 64

typedef struct {
    int* key;
    char* str;
} record;

int allocate_memory(long** offsets, int n, int m, record** records, int k, int min, int max, int p) {
    // Allocate memory for offsets
    *offsets = (long*)aligned_alloc(CACHE_LINE_SIZE, n * sizeof(long));
    if (*offsets == NULL) return -1;

    // Allocate memory for keys with overflow check
    int* keys = (int*)malloc(m * sizeof(int));
    if (keys == NULL) {
        free(*offsets);
        return -1;
    }
    for (int i = 0; i < m; i++) {
        if (__builtin_mul_overflow(i, m, &keys[i])) {
            free(keys);
            free(*offsets);
            return -1;
        }
    }

    // Allocate memory for records
    *records = (record*)malloc(k * sizeof(record));
    if (*records == NULL) {
        free(keys);
        free(*offsets);
        return -1;
    }

    // Initialize records and allocate strings
    for (int i = 0; i < k; i++) {
        (*records)[i].key = &keys[i];
        (*records)[i].str = (char*)malloc(256); // Example size, adjust as needed
        if ((*records)[i].str == NULL) {
            for (int j = 0; j < i; j++) free((*records)[j].str);
            free(keys);
            free(*offsets);
            free(*records);
            return -1;
        }
        strcpy((*records)[i].str, "default"); // Set default value
    }

    return 0;
}

void deallocate_memory(long* offsets, int m, record* records, int k) {
    for (int i = 0; i < k; i++) free(records[i].str);
    free(records);
    free(offsets);
}
