import java.util.*;
import java.util.concurrent.*;

public class ConfigManager {
    private final Map<String, String> configMap;
    private final ConcurrentSkipListSet<String> keySet;
    private final ScheduledExecutorService scheduler;

    public ConfigManager() {
        this.configMap = new ConcurrentHashMap<>();
        this.keySet = new ConcurrentSkipListSet<>();
        this.scheduler = Executors.newScheduledThreadPool(1);
    }

    public void addConfig(String key, String value) {
        configMap.put(key, value);
        keySet.add(key);
    }

    public void updateConfig(String key, String newValue) {
        if (configMap.containsKey(key)) {
            configMap.put(key, newValue);
        }
    }

    public void removeConfig(String key) {
        configMap.remove(key);
        keySet.remove(key);
    }

    public Iterable<String> iterateConfigs(Function<String, String> transform) {
        return () -> new Iterator<String>() {
            private final Iterator<Map.Entry<String, String>> iterator = configMap.entrySet().iterator();

            @Override
            public boolean hasNext() {
                return iterator.hasNext();
            }

            @Override
            public String next() {
                Map.Entry<String, String> entry = iterator.next();
                return transform.apply(entry.getValue());
            }
        };
    }

    public void startExternalDataUpdates(ExternalDataSource dataSource, long updateInterval) {
        scheduler.scheduleAtFixedRate(() -> {
            for (Map.Entry<String, String> entry : dataSource.getUpdatedConfigs().entrySet()) {
                configMap.put(entry.getKey(), entry.getValue());
            }
        }, 0, updateInterval, TimeUnit.MILLISECONDS);
    }

    public void insertKeyAfterLastOccurrence(String targetKey, String newKey) {
        if (!keySet.contains(targetKey)) {
            keySet.addFirst(newKey);
        } else {
            Iterator<String> iterator = keySet.iterator();
            while (iterator.hasNext()) {
                String key = iterator.next();
                if (key.equals(targetKey)) {
                    iterator.remove();
                    keySet.add(key);
                    keySet.add(newKey);
                    break;
                }
            }
        }
    }

    public void shutdown() {
        scheduler.shutdown();
    }
}

interface ExternalDataSource {
    Map<String, String> getUpdatedConfigs();
}
