#define PAGE_SIZE 4096

typedef struct log_entry {
    char* message;
} log_entry;

void* aligned_malloc(size_t size) {
    void* ptr;
    if (posix_memalign(&ptr, sizeof(long), size) != 0) {
        return NULL;
    }
    return ptr;
}

void free_aligned(void* ptr) {
    free(ptr);
}

log_entry** allocate_log_entries(int n, int m) {
    log_entry** entries = aligned_malloc(n * sizeof(log_entry*));
    if (!entries) return NULL;

    for (int i = 0; i < n; i++) {
        entries[i] = aligned_malloc(sizeof(log_entry));
        if (!entries[i]) {
            for (int j = 0; j < i; j++) free_aligned(entries[j]);
            free_aligned(entries);
            return NULL;
        }
    }

    char** messages = aligned_malloc(m * sizeof(char*));
    if (!messages) {
        for (int i = 0; i < n; i++) free_aligned(entries[i]);
        free_aligned(entries);
        return NULL;
    }

    // Simulate random message allocation
    for (int i = 0; i < m; i++) {
        size_t msg_size = rand() % 1024 + 1;
        messages[i] = aligned_malloc(msg_size);
        if (!messages[i]) {
            for (int j = 0; j < i; j++) free_aligned(messages[j]);
            free_aligned(messages);
            for (int j = 0; j < n; j++) free_aligned(entries[j]);
            free_aligned(entries);
            return NULL;
        }
    }

    // Initialize log entries
    for (int i = 0; i < n; i++) {
        int msg_index = rand() % m;
        entries[i]->message = messages[msg_index];
    }

    free(messages);
    return entries;
}

void deallocate_log_entries(log_entry** entries, int n) {
    for (int i = 0; i < n; i++) {
        free_aligned(entries[i]);
    }
    free_aligned(entries);
}

int main() {
    srand(time(NULL));
    int n = 1000;
    int m = 5000;

    log_entry** entries = allocate_log_entries(n, m);
    if (!entries) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    // Simulate logging
    for (int i = 0; i < n; i++) {
        printf("Log entry %d: %s\n", i, entries[i]->message);
    }

    deallocate_log_entries(entries, n);

    return 0;
}
