function traverseDOM(root, selector, callback, options = {}) {
  const { batchSize = 10, timeout = 5000, lockNodes = false } = options;
  let matchedElements = [];
  let currentNodeIndex = 0;

  function traverse(node) {
    if (node.nodeType === Node.ELEMENT_NODE && node.matches(selector)) {
      matchedElements.push(node);
    }

    for (let child of node.childNodes) {
      traverse(child);
    }
  }

  function processBatch() {
    const batch = [];
    while (currentNodeIndex < root.childNodes.length && batch.length < batchSize) {
      batch.push(root.childNodes[currentNodeIndex++]);
    }

    Promise.all(batch.map(node => callback(node)))
      .then(() => {
        if (currentNodeIndex < root.childNodes.length) {
          setTimeout(processBatch, timeout);
        }
      })
      .catch(error => {
        console.error('Error processing node:', error);
        if (currentNodeIndex < root.childNodes.length) {
          setTimeout(processBatch, timeout);
        }
      });
  }

  function lockDOM() {
    // Implement logic to lock DOM nodes
  }

  function unlockDOM() {
    // Implement logic to unlock DOM nodes
  }

  if (lockNodes) {
    lockDOM();
  }

  traverse(root);

  if (matchedElements.length > 0) {
    processBatch();
  } else {
    console.log('No matching elements found.');
  }

  if (lockNodes) {
    unlockDOM();
  }
}
