} record;

record* create_records(int numRecords, int keyRangeMin, int keyRangeMax, short defaultErrorCode) {
    if (numRecords <= 0 || keyRangeMin > keyRangeMax) {
        return NULL; // Invalid configuration
    }

    size_t recordSize = sizeof(record);
    size_t totalSize = numRecords * recordSize;

    // Allocate memory with alignment to 16 bytes
    void* alignedMemory = memalign(16, totalSize);
    if (!alignedMemory) {
        return NULL; // Memory allocation failed
    }

    record* records = (record*)alignedMemory;
    for (int i = 0; i < numRecords; ++i) {
        records[i].data = rand() % (keyRangeMax - keyRangeMin + 1) + keyRangeMin;
        memset(records[i].str, 'A', sizeof(records[i].str) - 1);
        records[i].str[sizeof(records[i].str) - 1] = '\0';
        records[i].errorCode = defaultErrorCode;
    }

    return records;
}

void free_records(record* records) {
    if (records) {
        free(records); // Free the allocated memory
    }
}
