// Define a function to load scripts dynamically
function loadScript(url, callback) {
    const script = document.createElement('script');
    script.src = url;
    script.onload = () => callback(null, script);
    script.onerror = (error) => callback(error, null);
    document.head.appendChild(script);
}

// Function to execute scripts sequentially with error handling and retries
function executeScripts(urls, maxRetries = 3, retryDelay = 1000) {
    let index = 0;

    function loadNextScript() {
        if (index >= urls.length) return Promise.resolve();

        const url = urls[index];
        return new Promise((resolve, reject) => {
            loadScript(url, (error, script) => {
                if (error) {
                    if (maxRetries > 0) {
                        setTimeout(() => {
                            maxRetries--;
                            loadNextScript();
                        }, retryDelay);
                    } else {
                        reject(error);
                    }
                } else {
                    resolve(script);
                }
            });
        }).then(() => {
            index++;
            return loadNextScript();
        });
    }

    return loadNextScript();
}

// Example usage
const scriptUrls = [
    'https://example.com/third-party-library.js',
    'https://example.com/your-script.js'
];

executeScripts(scriptUrls)
    .then(() => console.log('All scripts loaded successfully'))
    .catch((error) => console.error('Failed to load one or more scripts', error));
