typedef struct sensor_data {
    float humidity;
    char location[50];
    unsigned short id;
} sensor_data;

typedef struct node {
    float temperature;
    double timestamp;
    sensor_data data;
    struct node* next;
} node;

node** create_linked_lists(int num_lists, int list_size) {
    node** lists = (node**)aligned_alloc(32, num_lists * sizeof(node*));
    if (!lists) return NULL;

    for (int i = 0; i < num_lists; ++i) {
        lists[i] = (node*)aligned_alloc(32, list_size * sizeof(node));
        if (!lists[i]) {
            // Free previously allocated memory on failure
            for (int j = 0; j < i; ++j) free(lists[j]);
            free(lists);
            return NULL;
        }
    }

    // Initialize nodes
    for (int i = 0; i < num_lists; ++i) {
        for (int j = 0; j < list_size; ++j) {
            lists[i][j].next = &lists[i][(j + 1) % list_size];
        }
    }

    return lists;
}

void free_linked_lists(node** lists, int num_lists) {
    for (int i = 0; i < num_lists; ++i) {
        free(lists[i]);
    }
    free(lists);
}
