#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long* offset;
    int value;
} record;

int allocate_memory(long** offsets, int** keys, record** records, size_t size, int min_value, int max_value, unsigned int seed, bool shuffle) {
    *offsets = (long*)malloc(size * sizeof(long));
    *keys = (int*)malloc(size * sizeof(int));
    *records = (record*)malloc(size * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        free(*offsets);
        free(*keys);
        free(*records);
        return -1; // Memory allocation failed
    }

    srand(seed);

    for (size_t i = 0; i < size; ++i) {
        (*offsets)[i] = i;
        (*keys)[i] = rand() % 1001;

        if (shuffle) {
            int temp_key = (*keys)[i];
            size_t j = rand() % (i + 1);
            (*keys)[i] = (*keys)[j];
            (*keys)[j] = temp_key;
        }

        (*records)[i].offset = &(*offsets)[i];
        (*records)[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    return 0; // Success
}

void free_memory(long* offsets, int* keys, record* records, size_t size) {
    free(offsets);
    free(keys);
    free(records);
}

bool verify_data(record* records, size_t size, int min_value, int max_value) {
    for (size_t i = 0; i < size; ++i) {
        if (*records[i].offset != i || records[i].value < min_value || records[i].value > max_value) {
            return false;
        }
    }
    return true;
}

int main() {
    const size_t size = 1000;
    long* offsets;
    int* keys;
    record* records;

    if (allocate_memory(&offsets, &keys, &records, size, 10, 20, time(NULL), true) != 0) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    if (!verify_data(records, size, 10, 20)) {
        fprintf(stderr, "Data verification failed\n");
        free_memory(offsets, keys, records, size);
        return 1;
    }

    free_memory(offsets, keys, records, size);

    return 0;
}
