public class ThemeManager {
    private static final int CACHE_LIMIT = 100;
    private Map<String, BufferedImage> themeCache = new HashMap<>();
    private String defaultThemeDir = "default_theme_dir";

    public void recycleThemeBitmap(String themeId) {
        if (themeCache.containsKey(themeId)) {
            themeCache.put(themeId, null);
        }
    }

    public void setDefaultThemeDirectory(String dir) {
        if (defaultThemeDir == null || defaultThemeDir.isEmpty()) {
            defaultThemeDir = dir;
        }
    }

    public void parsePngFile(String filePath) throws IOException {
        BufferedImage image = ImageIO.read(new File(filePath));
        themeCache.put(filePath, image);
    }

    public synchronized void addToCache(String key, BufferedImage value) {
        if (themeCache.size() >= CACHE_LIMIT) {
            removeLeastRecentlyUsed();
        }
        themeCache.put(key, value);
    }

    private void removeLeastRecentlyUsed() {
        // Implement LRU logic here
    }

    public int countDisjointPairs(int[] array) {
        long startTime = System.currentTimeMillis();
        UnionFind uf = new UnionFind(array.length);
        for (int i = 0; i < array.length - 1; i++) {
            for (int j = i + 1; j < array.length; j++) {
                if (array[i] != array[j]) {
                    uf.union(i, j);
                }
            }
        }
        int disjointPairs = array.length - uf.countComponents();
        long endTime = System.currentTimeMillis();
        System.out.println("Disjoint pair check took " + (endTime - startTime) + " ms");
        return disjointPairs;
    }

    // Implement Union-Find data structure here
}

class UnionFind {
    private int[] parent;
    private int[] rank;

    public UnionFind(int size) {
        parent = new int[size];
        rank = new int[size];
        for (int i = 0; i < size; i++) {
            parent[i] = i;
            rank[i] = 1;
        }
    }

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX != rootY) {
            if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }

    public int countComponents() {
        int components = 0;
        for (int i = 0; i < parent.length; i++) {
            if (parent[i] == i) {
                components++;
            }
        }
        return components;
    }
}
