size_t current_memory_usage;
char* file_path;
int logging_level;

void log_message(int level, const char* message) {
    if (level <= logging_level) {
        printf("%s\n", message);
    }
}

void* load_data(void* arg) {
    FILE* file = fopen(file_path, "r");
    if (!file) {
        log_message(1, "Failed to open file");
        return NULL;
    }

    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file)) {
        int key, offset;
        if (sscanf(buffer, "%d %ld", &key, &offset) != 2) {
            log_message(1, "Malformed input line");
            continue;
        }

        if (current_memory_usage + sizeof(int) + sizeof(long) + sizeof(record) > memory_budget) {
            log_message(1, "Memory limit exceeded");
            break;
        }

        keys[key] = offset;
        offsets[key] = current_memory_usage;
        records[key].value = key;

        current_memory_usage += sizeof(int) + sizeof(long) + sizeof(record);
    }

    fclose(file);
    return NULL;
}

int main(int argc, char* argv[]) {
    // Parse command-line arguments and environment variables
    // Initialize memory budget, file path, and logging level

    offsets = (long*)malloc(MAX_RECORDS * sizeof(long));
    keys = (int*)malloc(MAX_RECORDS * sizeof(int));
    records = (record*)malloc(MAX_RECORDS * sizeof(record));

    if (!offsets || !keys || !records) {
        log_message(1, "Failed to allocate memory");
        return 1;
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, load_data, NULL) != 0) {
        log_message(1, "Failed to create thread");
        free(offsets);
        free(keys);
        free(records);
        return 1;
    }

    pthread_join(thread, NULL);

    // Clean up and release resources

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
