    int dictionarySize;
} CompressionObject;

CompressionObject* createCompressionObject(int dictionarySize) {
    CompressionObject* obj = (CompressionObject*)malloc(sizeof(CompressionObject));
    obj->stream = LZ4_createStream();
    if (!obj->stream) {
        fprintf(stderr, "Failed to create LZ4 stream\n");
        free(obj);
        return NULL;
    }
    LZ4_setDictSize(obj->stream, dictionarySize);
    obj->dictionarySize = dictionarySize;
    return obj;
}

void destroyCompressionObject(CompressionObject* obj) {
    if (obj->stream) {
        LZ4_freeStream(obj->stream);
    }
    free(obj);
}

int processFile(const char* inputPath, const char* outputPath, Operation operation, CompressionObject* obj) {
    FILE* inputFile = fopen(inputPath, "rb");
    if (!inputFile) {
        perror("Failed to open input file");
        return -1;
    }

    FILE* outputFile = fopen(outputPath, "wb");
    if (!outputFile) {
        perror("Failed to open output file");
        fclose(inputFile);
        return -1;
    }

    // Memory-mapped I/O for large files
    // ...

    char buffer[1024 * 1024]; // Adjust buffer size as needed
    int bytesRead, bytesWritten;

    if (operation == COMPRESS) {
        while ((bytesRead = fread(buffer, 1, sizeof(buffer), inputFile)) > 0) {
            bytesWritten = LZ4_compress_default(buffer, buffer + bytesRead, bytesRead, obj->dictionarySize);
            if (bytesWritten <= 0) {
                fprintf(stderr, "Compression failed\n");
                fclose(inputFile);
                fclose(outputFile);
                return -1;
            }
            fwrite(buffer, 1, bytesWritten, outputFile);
        }
    } else if (operation == DECOMPRESS) {
        while ((bytesRead = fread(buffer, 1, sizeof(buffer), inputFile)) > 0) {
            bytesWritten = LZ4_decompress_safe(buffer, buffer + bytesRead, bytesRead, sizeof(buffer));
            if (bytesWritten <= 0) {
                fprintf(stderr, "Decompression failed\n");
                fclose(inputFile);
                fclose(outputFile);
                return -1;
            }
            fwrite(buffer, 1, bytesWritten, outputFile);
        }
    }

    fclose(inputFile);
    fclose(outputFile);

    // Logging mechanism
    // ...

    return 0;
}

int main(int argc, char* argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <input> <output> <operation> <dictionary_size>\n", argv[0]);
        return -1;
    }

    Operation operation = strcmp(argv[3], "compress") == 0 ? COMPRESS : DECOMPRESS;
    int dictionarySize = atoi(argv[4]);

    CompressionObject* obj = createCompressionObject(dictionarySize);
    if (!obj) {
        return -1;
    }

    int result = processFile(argv[1], argv[2], operation, obj);
    destroyCompressionObject(obj);

    return result;
}
