namespace Simulation {
    class SimulationEngine {
    public:
        SimulationEngine() : rng(std::random_device{}()) {}
        ~SimulationEngine() = default;

        static void initializeRNG(unsigned int seed) {
            rng.seed(seed);
        }

        static double generateRandomNumber(double min, double max) {
            std::uniform_real_distribution<> dis(min, max);
            return dis(rng);
        }

        static void setEnvironmentVariable(const std::string& varName, const std::string& path) {
            if (std::getenv(varName.c_str()) == nullptr) {
                std::filesystem::create_directory(path);
                std::setenv(varName.c_str(), path.c_str(), 1);
            }
        }

        static void loadConfiguration() {
            // Load configuration from file or database
        }

        static void saveConfiguration() {
            // Save configuration to file or database
        }

    private:
