import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;

public class ConfigLoader {

    private static final ConcurrentHashMap<String, CacheEntry> cache = new ConcurrentHashMap<>();
    private static final long CACHE_EXPIRY_TIME = TimeUnit.MINUTES.toMillis(10);
    private static final int MAX_CACHE_SIZE = 1000;

    public static MoSTConfig loadConfig(String configId) {
        // Check cache
        CacheEntry entry = cache.get(configId);
        if (entry != null && !isExpired(entry)) {
            return entry.config;
        }

        // Fetch from network
        try {
            MoSTConfig fetchedConfig = fetchFromNetwork(configId);
            if (fetchedConfig != null) {
                putInCache(configId, fetchedConfig);
            }
            return fetchedConfig;
        } catch (Exception e) {
            handleException(e);
            return null;
        }
    }

    private static boolean isExpired(CacheEntry entry) {
        return System.currentTimeMillis() - entry.timestamp > CACHE_EXPIRY_TIME;
    }

    private static MoSTConfig fetchFromNetwork(String configId) throws Exception {
        // Simulate network call
        Thread.sleep(100); // Simulate latency
        if (Math.random() < 0.9) { // Simulate network failure
            throw new Exception("Network error");
        }
        return new MoSTConfig(configId);
    }

    private static void putInCache(String configId, MoSTConfig config) {
        cache.putIfAbsent(configId, new CacheEntry(config));
        if (cache.size() > MAX_CACHE_SIZE) {
            evictLeastRecentlyUsed();
        }
    }

    private static void evictLeastRecentlyUsed() {
        // Simple eviction policy: remove the oldest entry
        cache.entrySet().stream()
                .min((e1, e2) -> Long.compare(e1.getValue().timestamp, e2.getValue().timestamp))
                .ifPresent(entry -> cache.remove(entry.getKey()));
    }

    private static void handleException(Exception e) {
        // Log or handle exception appropriately
        System.err.println("Error loading config: " + e.getMessage());
    }

    private static class CacheEntry {
        final MoSTConfig config;
        final long timestamp;

        CacheEntry(MoSTConfig config) {
            this.config = config;
            this.timestamp = System.currentTimeMillis();
        }
    }
}

class MoSTConfig {
    private String id;

    public MoSTConfig(String id) {
        this.id = id;
    }

    // Getters and setters
}
