int initCryptoAndRunCommand(const char *command) {
    // Initialize cryptographic primitives
    if (!EVP_add_cipher(EVP_aes_256_cbc())) return 0;
    if (!EVP_add_cipher(EVP_camellia_128_ecb())) return 0;
    if (!EVP_add_digest(EVP_md5())) return 0;
    if (!EVP_add_digest(EVP_sha1())) return 0;
    if (!EVP_add_digest(EVP_sha256())) return 0;

    // Initialize RSA with SHA1
    RSA *rsa = RSA_new();
    if (RSA_generate_key_ex(rsa, 2048, RSA_F4, NULL) != 1) {
        RSA_free(rsa);
        return 0;
    }

    // Add to configuration
    crypto_config.ciphers[crypto_config.cipher_count++] = (CipherInfo){EVP_aes_256_cbc(), "AES-256-CBC"};
    crypto_config.rsa_keys[crypto_config.rsa_key_count++] = (RSACrypto){rsa, 2048};

    // Run command in background
    pid_t pid = fork();
    if (pid == -1) return 0;
    if (pid == 0) {
        execlp(command, command, NULL);
        exit(EXIT_FAILURE);
    }

    int status;
    wait(&status);
    return WIFEXITED(status) && WEXITSTATUS(status) == 0;
}

