typedef struct {
    char ip[16];
    int port;
    int status;
    time_t last_seen;
} NetworkConnection;

NetworkConnection* create_network_connections(int num_connections, const char* default_ip, int start_port) {
    if (num_connections <= 0 || start_port <= 0) {
        fprintf(stderr, "Invalid number of connections or start port.\n");
        return NULL;
    }

    NetworkConnection* connections = (NetworkConnection*)malloc(num_connections * sizeof(NetworkConnection));
    if (!connections) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < num_connections; ++i) {
        strcpy(connections[i].ip, default_ip);
        connections[i].port = start_port + i;
        connections[i].status = 0; // Assuming 0 means disconnected
        connections[i].last_seen = time(NULL);
    }

    return connections;
}

void free_network_connections(NetworkConnection* connections, int num_connections) {
    if (connections) {
        free(connections);
    }
}

int main() {
    int num_connections = 10;
    const char* default_ip = "192.168.1.1";
    int start_port = 8080;

    NetworkConnection* connections = create_network_connections(num_connections, default_ip, start_port);
    if (connections) {
        // Use the connections array here
        free_network_connections(connections, num_connections);
    }

    return 0;
}
