#define KEY_LENGTH 32
#define IV_LENGTH 16
#define PBKDF2_ITERATIONS 4096

void init_aes_cipher(const char *password, unsigned char *key, unsigned char *iv) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create cipher context\n");
        return;
    }

    if (1 != PKCS5_PBKDF2_HMAC(password, strlen(password), NULL, 0, PBKDF2_ITERATIONS, EVP_sha256(), KEY_LENGTH, key)) {
        fprintf(stderr, "PBKDF2 failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    if (1 != RAND_bytes(iv, IV_LENGTH)) {
        fprintf(stderr, "Failed to generate IV\n");
        EVP_CIPHER_CTX_free(ctx);
        return;
    }

    EVP_CIPHER_CTX_free(ctx);
}

