#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <pthread.h>

#define BUFFER_SIZE 1024
#define CIRCLE_BUFFER_SIZE 1000
#define CACHE_SIZE 500

typedef struct {
    char *data;
    int length;
} Line;

typedef struct {
    Line buffer[CIRCLE_BUFFER_SIZE];
    int head, tail, count;
    pthread_mutex_t mutex;
} CircularBuffer;

typedef struct {
    Line cache[CACHE_SIZE];
    int size;
    pthread_mutex_t mutex;
} Cache;

CircularBuffer cb;
Cache cache;

void init_buffer(CircularBuffer *cb) {
    cb->head = cb->tail = cb->count = 0;
    pthread_mutex_init(&cb->mutex, NULL);
}

void init_cache(Cache *cache) {
    cache->size = 0;
    pthread_mutex_init(&cache->mutex, NULL);
}

int is_numeric(char *str) {
    while (*str) {
        if (!isdigit(*str)) return 0;
        str++;
    }
    return 1;
}

double compute_average(Line line) {
    int count = 0, sum = 0;
    char *token = strtok(line.data, " ");
    while (token != NULL) {
        if (is_numeric(token)) {
            sum += atoi(token);
            count++;
        }
        token = strtok(NULL, " ");
    }
    return count > 2 ? (double)sum / count : 0;
}

void add_to_buffer(CircularBuffer *cb, Line line) {
    pthread_mutex_lock(&cb->mutex);
    cb->buffer[cb->tail] = line;
    cb->tail = (cb->tail + 1) % CIRCLE_BUFFER_SIZE;
    if (cb->count < CIRCLE_BUFFER_SIZE) cb->count++;
    else cb->head = (cb->head + 1) % CIRCLE_BUFFER_SIZE;
    pthread_mutex_unlock(&cb->mutex);
}

Line get_from_buffer(CircularBuffer *cb) {
    Line line;
    pthread_mutex_lock(&cb->mutex);
    if (cb->count > 0) {
        line = cb->buffer[cb->head];
        cb->head = (cb->head + 1) % CIRCLE_BUFFER_SIZE;
        cb->count--;
    } else {
        line.data = NULL;
        line.length = 0;
    }
    pthread_mutex_unlock(&cb->mutex);
    return line;
}

void add_to_cache(Cache *cache, Line line) {
    pthread_mutex_lock(&cache->mutex);
    if (cache->size < CACHE_SIZE) {
        cache->cache[cache->size++] = line;
    } else {
        // Implement dynamic expiration logic here
    }
    pthread_mutex_unlock(&cache->mutex);
}

Line get_from_cache(Cache *cache, char *key) {
    Line line;
    pthread_mutex_lock(&cache->mutex);
    for (int i = 0; i < cache->size; i++) {
        if (strcmp(cache->cache[i].data, key) == 0) {
            line = cache->cache[i];
            break;
        }
    }
    pthread_mutex_unlock(&cache->mutex);
    return line;
}

void *process_log(void *arg) {
    FILE *file = fopen((char *)arg, "r");
    if (file == NULL) {
        perror("Error opening file");
        return NULL;
    }

    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, file)) {
        Line line = {buffer, strlen(buffer)};
        add_to_buffer(&cb, line);
        Line cached_line = get_from_cache(&cache, buffer);
        if (cached_line.data == NULL) {
            double average = compute_average(line);
            char avg_str[20];
            snprintf(avg_str, sizeof(avg_str), " %.2f", average);
            strcat(line.data, avg_str);
            add_to_cache(&cache, line);
        }
    }

    fclose(file);
    return NULL;
}

void find_largest_integer() {
    int n;
    printf("Enter the number of integers: ");
    scanf("%d", &n);
    int *array = (int *)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        printf("Enter integer %d: ", i + 1);
        scanf("%d", &array[i]);
    }

    int largest = array[0];
    for (int i = 1; i < n; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    printf("The largest integer is: %d\n", largest);
    free(array);
}

int main() {
    init_buffer(&cb);
    init_cache(&cache);

    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, process_log, "log1.txt");
    pthread_create(&thread2, NULL, process_log, "log2.txt");

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    find_largest_integer();

    return 0;
}
