#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct {
    int minValue;
    int maxValue;
} CustomRandomGenerator;

CustomRandomGenerator* CreateRandomGenerator(int min, int max) {
    if (min > max) return NULL; // Invalid range
    CustomRandomGenerator* generator = (CustomRandomGenerator*)malloc(sizeof(CustomRandomGenerator));
    if (!generator) return NULL; // Memory allocation failed
    generator->minValue = min;
    generator->maxValue = max;
    srand(time(NULL)); // Seed for random number generation
    return generator;
}

void DestroyRandomGenerator(CustomRandomGenerator* generator) {
    free(generator);
}

int GenerateRandomNumber(CustomRandomGenerator* generator, int inclusiveMax) {
    if (!generator) return -1; // Invalid generator
    return rand() % (inclusiveMax + 1 - generator->minValue) + generator->minValue;
}

void initializeData(int size, CustomRandomGenerator* generator, long** offsets, int** keys, record** records) {
    *offsets = (long*)malloc(size * sizeof(long));
    *keys = (int*)malloc(size * sizeof(int));
    *records = (record*)malloc(size * sizeof(record));

    if (!(*offsets) || !(*keys) || !(*records)) {
        // Memory allocation failed
        free(*offsets);
        free(*keys);
        free(*records);
        return; // Failure indicator
    }

    for (int i = 0; i < size; i++) {
        (*offsets)[i] = GenerateRandomNumber(generator, 1000); // Example upper bound
        (*keys)[i] = GenerateRandomNumber(generator, 100);
        (*records)[i].value = GenerateRandomNumber(generator, 1000); // Example upper bound
    }
}

int main() {
    CustomRandomGenerator* generator = CreateRandomGenerator(0, 999);
    if (!generator) return -1; // Failed to create random generator

    long* offsets;
    int* keys;
    record* records;

    initializeData(1000, generator, &offsets, &keys, &records);

    DestroyRandomGenerator(generator);
    free(offsets);
    free(keys);
    free(records);

    return 0;
}
