const fs = require('fs');
const path = require('path');
const util = require('util');
const axios = require('axios');

const logger = {
  log: (message) => console.log(message),
  error: (error) => console.error(error)
};

const testCache = new Map();

async function loadModule(modulePath) {
  try {
    return await import(path.resolve(__dirname, modulePath));
  } catch (error) {
    logger.error(`Failed to load module ${modulePath}:`, error);
    throw error;
  }
}

async function runTest(testFunction, moduleName, testName) {
  const startTime = Date.now();
  try {
    await testFunction();
    logger.log(`${moduleName} - ${testName} passed in ${Date.now() - startTime}ms`);
  } catch (error) {
    logger.error(`${moduleName} - ${testName} failed:`, error);
  }
}

async function resetTestEnvironment() {
  // Implement environment reset logic here
  logger.log('Resetting test environment...');
}

async function runTests(modulePath, tests) {
  const module = await loadModule(modulePath);
  for (const testName in tests) {
    if (typeof tests[testName] === 'function') {
      await runTest(tests[testName], path.basename(modulePath), testName);
      await resetTestEnvironment();
    } else {
      logger.error(`Invalid test function ${testName} in module ${modulePath}`);
    }
  }
}

async function executeTestsInParallel(modulePaths, tests) {
  const promises = [];
  for (const modulePath of modulePaths) {
    promises.push(runTests(modulePath, tests));
  }
  await Promise.all(promises);
}

async function runTestSuite(testsDirectory, maxRetries = 3) {
  try {
    const moduleFiles = fs.readdirSync(testsDirectory).filter(file => file.endsWith('.js'));
    for (const moduleFile of moduleFiles) {
      const modulePath = path.join(testsDirectory, moduleFile);
      await executeTestsInParallel([modulePath], require(modulePath));
    }
  } catch (error) {
    logger.error('Test suite execution failed:', error);
  }
}

// Example usage
runTestSuite('./tests');
```

This code provides a basic structure for managing a test suite in a modular application. It includes functions to load modules, run tests, reset the test environment, and execute tests in parallel. The `runTestSuite` function is designed to be triggered automatically by a CI/CD pipeline, providing real-time feedback to development teams."]

