typedef struct {
    int value;
} record;

typedef struct {
    char tag[256];
} metadata;

typedef struct {
    long *offsets;
    int *keys;
    record *records;
    metadata **tags;
    size_t size;
} DataContainer;

typedef struct {
    int minValue;
    int maxValue;
} CustomRandomGenerator;

CustomRandomGenerator* CreateRandomGenerator(int min, int max) {
    if (min > max) return NULL; // Invalid range
    CustomRandomGenerator *generator = (CustomRandomGenerator*)malloc(sizeof(CustomRandomGenerator));
    generator->minValue = min;
    generator->maxValue = max;
    return generator;
}

int ValidateRange(int min, int max) {
    return min <= max;
}

void InitializeData(size_t size, DataContainer *container) {
    if (size <= 0 || container == NULL) {
        return; // Invalid input
    }

    container->offsets = (long*)malloc(size * sizeof(long));
    container->keys = (int*)malloc(size * sizeof(int));
    container->records = (record*)malloc(size * sizeof(record));
    container->tags = (metadata**)malloc(size * sizeof(metadata*));

    if (!container->offsets || !container->keys || !container->records || !container->tags) {
        // Memory allocation failed
        free(container->offsets);
        free(container->keys);
        free(container->records);
        free(container->tags);
        return;
    }

    CustomRandomGenerator *generator = CreateRandomGenerator(0, 100); // Example range
    if (!generator) {
        // Failed to create random generator
        free(container->offsets);
        free(container->keys);
        free(container->records);
        free(container->tags);
        return;
    }

    for (size_t i = 0; i < size; ++i) {
        container->offsets[i] = rand();
        container->keys[i] = rand() % (generator->maxValue - generator->minValue + 1) + generator->minValue;
        container->records[i].value = rand() % (generator->maxValue - generator->minValue + 1) + generator->minValue;
        container->tags[i] = (metadata*)malloc(sizeof(metadata));
        if (!container->tags[i]) {
            // Memory allocation failed for tag
            for (size_t j = 0; j < i; ++j) {
                free(container->tags[j]);
            }
            free(generator);
            free(container->offsets);
            free(container->keys);
            free(container->records);
            free(container->tags);
            return;
        }
    }

    container->size = size;
    free(generator);
}

void FreeDataContainer(DataContainer *container) {
    if (container == NULL) return;

    for (size_t i = 0; i < container->size; ++i) {
        free(container->tags[i]);
    }

    free(container->offsets);
    free(container->keys);
    free(container->records);
    free(container->tags);
}
