#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define BUFFER_SIZE 1024

typedef struct Record {
    int key;
    long offset;
    char buffer[BUFFER_SIZE];
    struct Record *next;
} Record;

typedef struct RecordList {
    Record *head;
    pthread_mutex_t lock;
} RecordList;

Record* create_record(int key, long offset) {
    Record *new_record = (Record*)malloc(sizeof(Record));
    if (new_record == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    new_record->key = key;
    new_record->offset = offset;
    memset(new_record->buffer, 0, BUFFER_SIZE);
    new_record->next = NULL;
    return new_record;
}

void add_record(RecordList *list, Record *record) {
    pthread_mutex_lock(&list->lock);
    record->next = list->head;
    list->head = record;
    pthread_mutex_unlock(&list->lock);
}

int find_record(RecordList *list, int key) {
    pthread_mutex_lock(&list->lock);
    Record *current = list->head;
    while (current != NULL) {
        if (current->key == key) {
            pthread_mutex_unlock(&list->lock);
            return 1;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return 0;
}

void print_records_reverse(RecordList *list) {
    pthread_mutex_lock(&list->lock);
    Record *current = list->head;
    while (current != NULL) {
        printf("Key: %d, Offset: %ld\n", current->key, current->offset);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void free_record_list(RecordList *list) {
    Record *current = list->head;
    while (current != NULL) {
        Record *temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&list->lock);
}
