typedef struct {
    int value;
    char buffer[128];
    void* opaque_data;
} Record;

typedef struct {
    Record* records;
    size_t count;
} DataStructure;

void generate_unique_string(char* str, size_t index) {
    // Generate a unique 128-character ASCII string based on the index
    for (size_t i = 0; i < 128; ++i) {
        str[i] = 'A' + (index * 37 + i) % 26;
    }
}

DataStructure* initialize_data_structures(size_t num_records, int error_code) {
    DataStructure* ds = malloc(sizeof(DataStructure));
    if (!ds) {
        return NULL; // Handle memory allocation failure
    }

    ds->records = malloc(num_records * sizeof(Record));
    if (!ds->records) {
        free(ds);
        return NULL; // Handle memory allocation failure
    }

    ds->count = num_records;

    for (size_t i = 0; i < num_records; ++i) {
        ds->records[i].value = i;
        generate_unique_string(ds->records[i].buffer, i);

        // Allocate and initialize the opaque data
        char* unique_str = malloc(128);
        if (!unique_str) {
            for (size_t j = 0; j < i; ++j) {
                free(ds->records[j].opaque_data);
            }
            free(ds->records);
            free(ds);
            return NULL; // Handle memory allocation failure
        }
        generate_unique_string(unique_str, i);
        ds->records[i].opaque_data = unique_str;
    }

    return ds;
}

void cleanup_data_structure(DataStructure* ds) {
    if (ds) {
        for (size_t i = 0; i < ds->count; ++i) {
            free(ds->records[i].opaque_data);
        }
        free(ds->records);
        free(ds);
    }
}
