void initialize_arrays(long *offsets, int *keys, record **records, int size) {
    offsets = (long *)malloc(size * sizeof(long));
    keys = (int *)malloc(size * sizeof(int));
    records = (record **)malloc(size * sizeof(record *));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        offsets[i] = rand() % 1000L;
        keys[i] = rand() % 100;
        records[i] = (record *)malloc(sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed for record %d\n", i);
            exit(1);
        }
        records[i]->value = rand() % 1000;
    }
}

int main() {
    int size = 5;
    long *offsets;
    int *keys;
    record **records;

    initialize_arrays(offsets, keys, records, size);

    // Free allocated memory
    for (int i = 0; i < size; i++) {
        free(records[i]);
    }
    free(offsets);
    free(keys);

    return 0;
}
