    $data = [
        'grant_type' => 'authorization_code',
        'code' => $_GET['code'],
        'redirect_uri' => $redirectUri,
        'client_id' => $clientId,
        'client_secret' => $clientSecret
    ];

    $options = [
        'http' => [
            'header'  => "Content-type: application/x-www-form-urlencoded\r\n",
            'method'  => 'POST',
            'content' => http_build_query($data),
        ],
    ];

    $context  = stream_context_create($options);
    $response = file_get_contents($tokenUrl, false, $context);

    if ($response === FALSE) {
        die('Network error occurred');
    }

    $responseData = json_decode($response, true);
    if (!isset($responseData['access_token'])) {
        die('Invalid token received');
    }

    $_SESSION['access_token'] = $responseData['access_token'];
}

function fetchUserData() {
    if (!isset($_SESSION['access_token'])) {
        die('Session expired or invalid');
    }

    $accessToken = $_SESSION['access_token'];
    $userDataUrl = 'https://api.example.com/user/data';

    $options = [
        'http' => [
            'header'  => "Authorization: Bearer {$accessToken}\r\n",
            'method'  => 'GET',
        ],
    ];

    $context  = stream_context_create($options);
    $response = file_get_contents($userDataUrl, false, $context);

    if ($response === FALSE) {
        die('Network error occurred');
    }

    return json_decode($response, true);
}

