RecordSet* allocate_records(size_t count, int range_min, int range_max, unsigned seed) {
    if (count == 0 || range_min > range_max) {
        return NULL; // Handle invalid input
    }

    RecordSet* record_set = malloc(sizeof(RecordSet));
    if (!record_set) {
        return NULL; // Memory allocation failed
    }

    record_set->integers = aligned_alloc(64, count * sizeof(int));
    record_set->buffers = aligned_alloc(64, count * sizeof(char*) * 128);
    record_set->count = count;

    if (!record_set->integers || !record_set->buffers) {
        free(record_set);
        return NULL; // Memory allocation failed
    }

    srand(seed);

    for (size_t i = 0; i < count; ++i) {
        record_set->integers[i] = rand() % (range_max - range_min + 1) + range_min;
        record_set->buffers[i] = aligned_alloc(64, 128);
        if (!record_set->buffers[i]) {
            // Handle memory allocation failure for individual buffer
            free(record_set->integers);
            free(record_set->buffers);
            free(record_set);
            return NULL;
        }
        // Initialize buffer with unique ASCII string using hash function
        snprintf(record_set->buffers[i], 128, "Record %zu", i);
    }

    return record_set;
}

void free_records(RecordSet* record_set) {
    if (record_set) {
        for (size_t i = 0; i < record_set->count; ++i) {
            free(record_set->buffers[i]);
        }
        free(record_set->integers);
        free(record_set->buffers);
        free(record_set);
    }
}
