#include <stdio.h>

#define MAX_RECORDS 10000
#define BUFFER_SIZE 128

typedef struct {
    int value;
    char buffer[BUFFER_SIZE];
    void* opaque_data;
} Record;

typedef struct {
    Record** records;
    size_t count;
} DataStructure;

void generate_unique_string(char* buffer, size_t index) {
    // Generate a unique ASCII string based on the index
    for (size_t i = 0; i < BUFFER_SIZE - 1; ++i) {
        buffer[i] = 'A' + (index % 26);
        index /= 26;
    }
    buffer[BUFFER_SIZE - 1] = '\0';
}

DataStructure* initialize_data_structures(size_t num_records, int* error_code) {
    if (num_records > MAX_RECORDS) {
        *error_code = -1; // Error code for too many records
        return NULL;
    }

    DataStructure* ds = malloc(sizeof(DataStructure));
    if (!ds) {
        *error_code = -2; // Error code for memory allocation failure
        return NULL;
    }

    ds->records = malloc(num_records * sizeof(Record*));
    if (!ds->records) {
        free(ds);
        *error_code = -2; // Error code for memory allocation failure
        return NULL;
    }

    ds->count = num_records;

    for (size_t i = 0; i < num_records; ++i) {
        Record* record = malloc(sizeof(Record));
        if (!record) {
            *error_code = -2; // Error code for memory allocation failure
            goto cleanup;
        }

        record->value = i;
        generate_unique_string(record->buffer, i);

        // Allocate and initialize opaque data (e.g., a dynamically allocated string)
        char* unique_string = malloc(BUFFER_SIZE);
        if (!unique_string) {
            free(record);
            *error_code = -2; // Error code for memory allocation failure
            goto cleanup;
        }
        generate_unique_string(unique_string, i);
        record->opaque_data = unique_string;

        ds->records[i] = record;
    }

    return ds;

cleanup:
    for (size_t i = 0; i < i; ++i) {
        free(ds->records[i]->opaque_data);
        free(ds->records[i]);
    }
    free(ds->records);
    free(ds);

    *error_code = -2; // Error code for memory allocation failure
    return NULL;
}

void destroy_data_structures(DataStructure* ds) {
    if (ds) {
        for (size_t i = 0; i < ds->count; ++i) {
            free(ds->records[i]->opaque_data);
            free(ds->records[i]);
        }
        free(ds->records);
        free(ds);
    }
}
