#include <stdio.h>
#include <stdlib.h>

#define MAX_SIZE 10000
#define MIN_VALUE -1000000
#define MAX_VALUE 1000000

typedef struct {
    int value;
} Record;

int readIntegers(int **array, Record **records) {
    int count = 0;
    while (count < MAX_SIZE && scanf("%d", &(*array)[count]) == 1) {
        if ((*array)[count] >= MIN_VALUE && (*array)[count] <= MAX_VALUE) {
            records[count].value = (*array)[count];
            count++;
        }
    }
    return count;
}

void findAndPrintLargest(int *array, int size) {
    if (size == 0) {
        printf("No valid integers\n");
    } else {
        int largest = array[0];
        for (int i = 1; i < size; i++) {
            if (array[i] > largest) {
                largest = array[i];
            }
        }
        printf("Largest integer: %d\n", largest);
    }
}

double calculateAverage(int *array, int size) {
    if (size == 0) {
        return 0.0;
    } else {
        double sum = 0.0;
        for (int i = 0; i < size; i++) {
            sum += array[i];
        }
        return sum / size;
    }
}

void freeMemory(int *array, Record *records) {
    free(array);
    free(records);
}

int main() {
    int *array = (int *)malloc(MAX_SIZE * sizeof(int));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    Record *records = (Record *)malloc(MAX_SIZE * sizeof(Record));
    if (records == NULL) {
        free(array);
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    int size = readIntegers(&array, records);

    findAndPrintLargest(array, size);
    printf("Average: %.2f\n", calculateAverage(array, size));

    freeMemory(array, records);

    return 0;
}
