record** create_records(int num_records, int key_range, unsigned long seed, int load_factor) {
    // Allocate memory for arrays and records
    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));
    record** records = (record**)malloc(num_records * sizeof(record*));

    if (!offsets || !keys || !records) {
        // Handle memory allocation failure
        return NULL;
    }

    // Initialize random number generator
    srand(seed);

    // Allocate and initialize records
    for (int i = 0; i < num_records; ++i) {
        keys[i] = rand() % key_range + 1; // Generate random key within range
        offsets[i] = i * load_factor; // Calculate offset based on load factor

        records[i] = (record*)malloc(sizeof(record));
        if (!records[i]) {
            // Handle memory allocation failure for a record
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }

        records[i]->value = rand() % key_range + 1; // Initialize random value

        // Allocate memory for string based on key
        records[i]->str = (char*)malloc((keys[i] + 1) * sizeof(char));
        if (!records[i]->str) {
            // Handle memory allocation failure for a string
            for (int j = 0; j <= i; ++j) {
                free(records[j]);
            }
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }

        // Initialize string with random characters
        for (int k = 0; k < keys[i]; ++k) {
            records[i]->str[k] = 'a' + rand() % 26;
        }
        records[i]->str[keys[i]] = '\0';
    }

    return records;
}

void free_records(record** records, int num_records) {
    // Free allocated memory for records and strings
    for (int i = 0; i < num_records; ++i) {
        if (records[i]) {
            free(records[i]->str);
            free(records[i]);
        }
    }
    free(records);
}

// Function to access record values and strings without copying
void get_record_info(record** records, int index, int* value, const char** str) {
    if (index >= 0 && index < num_records) {
        *value = records[index]->value;
        *str = records[index]->str;
    } else {
        // Handle invalid index
        *value = -1; // Error code
        *str = NULL;
    }
}
