#define MAX_ITEM_SIZE 1024

typedef struct {
    char *value;
    int number;
} Value;

typedef struct {
    Value **items;
    size_t size;
    size_t capacity;
} Data;

typedef struct {
    Data *data;
    int index;
    size_t data_size;
} Entry;

typedef struct {
    Entry **entries;
    size_t size;
    size_t capacity;
} EntryArray;

void log_memory_event(const char *operation, void *address) {
    time_t now = time(NULL);
    printf("%s %ld: %p\n", operation, (long)now, address);
}

EntryArray* create_entry_array(size_t initial_capacity) {
    EntryArray *array = malloc(sizeof(EntryArray));
    array->entries = malloc(initial_capacity * sizeof(Entry *));
    array->size = 0;
    array->capacity = initial_capacity;
    return array;
}

void free_entry_array(EntryArray *array) {
    for (size_t i = 0; i < array->size; ++i) {
        Entry *entry = array->entries[i];
        for (size_t j = 0; j < entry->data_size; ++j) {
            Value *value = entry->data->items[j];
            free(value->value);
            free(value);
        }
        free(entry->data->items);
        free(entry->data);
        free(entry);
    }
    free(array->entries);
    free(array);
}

void resize_entry_array(EntryArray *array, size_t new_capacity) {
    Entry **new_entries = realloc(array->entries, new_capacity * sizeof(Entry *));
    if (new_entries == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->entries = new_entries;
    array->capacity = new_capacity;
}

void add_entry(EntryArray *array, int index, size_t max_data_size) {
    if (array->size >= array->capacity) {
        resize_entry_array(array, array->capacity * 2);
    }

    Entry *entry = malloc(sizeof(Entry));
    entry->data = malloc(sizeof(Data));
    entry->data->items = malloc(max_data_size * sizeof(Value *));
    entry->data->size = 0;
    entry->data->capacity = max_data_size;
    entry->index = index;
    entry->data_size = 0;

    for (size_t i = 0; i < max_data_size; ++i) {
        Value *value = malloc(sizeof(Value));
        value->value = malloc(MAX_ITEM_SIZE);
        snprintf(value->value, MAX_ITEM_SIZE, "Item%d", rand() % 100);
        value->number = rand() % 1000;
        entry->data->items[i] = value;
    }

    array->entries[array->size++] = entry;
}

void remove_entry(EntryArray *array, size_t index) {
    for (size_t i = index; i < array->size - 1; ++i) {
        array->entries[i] = array->entries[i + 1];
    }
    array->size--;
}

int main() {
    srand(time(NULL));
    EntryArray *array = create_entry_array(4);

    add_entry(array, 0, 5);
    add_entry(array, 1, 3);
    remove_entry(array, 0);

    free_entry_array(array);
    return 0;
}
