typedef struct {
    char* value;
    int number;
} Value;

typedef struct {
    Value** items;
    int itemCount;
} Data;

typedef struct {
    Data* data;
    int index;
} Entry;

Entry* initEntries(int numEntries, int minIndex, int maxIndex) {
    Entry* entries = (Entry*)malloc(numEntries * sizeof(Entry));
    if (!entries) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < numEntries; i++) {
        entries[i].data = (Data*)malloc(sizeof(Data));
        if (!entries[i].data) {
            fprintf(stderr, "Memory allocation failed\n");
            free(entries);
            return NULL;
        }
        entries[i].data->items = (Value**)malloc(10 * sizeof(Value*)); // Assuming 10 items per data
        if (!entries[i].data->items) {
            fprintf(stderr, "Memory allocation failed\n");
            free(entries[i].data);
            free(entries);
            return NULL;
        }
        entries[i].data->itemCount = 10;

        for (int j = 0; j < 10; j++) { // Assuming 10 items per data
            entries[i].data->items[j] = (Value*)malloc(sizeof(Value));
            if (!entries[i].data->items[j]) {
                fprintf(stderr, "Memory allocation failed\n");
                for (int k = 0; k < j; k++) {
                    free(entries[i].data->items[k]);
                }
                free(entries[i].data->items);
                free(entries[i].data);
                free(entries);
                return NULL;
            }
            entries[i].data->items[j]->value = (char*)malloc(256 * sizeof(char));
            if (!entries[i].data->items[j]->value) {
                fprintf(stderr, "Memory allocation failed\n");
                for (int k = 0; k <= j; k++) {
                    free(entries[i].data->items[k]);
                }
                free(entries[i].data->items);
                free(entries[i].data);
                free(entries);
                return NULL;
            }
            snprintf(entries[i].data->items[j]->value, 256, "RandomString%d", rand() % 1000);
            entries[i].data->items[j]->number = rand() % (maxIndex - minIndex + 1) + minIndex;
        }

        entries[i].index = i;
    }

    return entries;
}

void freeEntries(Entry* entries, int numEntries) {
    for (int i = 0; i < numEntries; i++) {
        for (int j = 0; j < entries[i].data->itemCount; j++) {
            free(entries[i].data->items[j]->value);
            free(entries[i].data->items[j]);
        }
        free(entries[i].data->items);
        free(entries[i].data);
    }
    free(entries);
}

int main() {
    int numEntries = 5;
    Entry* entries = initEntries(numEntries, 10, 20);

    if (entries) {
        for (int i = 0; i < numEntries; i++) {
            printf("Entry %d: Index %d\n", i, entries[i].index);
            for (int j = 0; j < entries[i].data->itemCount; j++) {
                printf("  Item %d: Value %s, Number %d\n", j, entries[i].data->items[j]->value, entries[i].data->items[j]->number);
            }
        }

        freeEntries(entries, numEntries);
    }

    return 0;
}
