#include <openssl/evp.h>
#include <openssl/rand.h>

EVP_CIPHER* get_cipher(const char* cipher_name) {
    EVP_CIPHER* cipher = EVP_get_cipherbyname(cipher_name);
    if (cipher == NULL) {
        // Handle error: cipher not found
        return NULL;
    }
    return cipher;
}

int encrypt_data(EVP_CIPHER_CTX* ctx, const unsigned char* plaintext, int plaintext_len,
                 unsigned char* ciphertext, int* ciphertext_len) {
    *ciphertext_len = 0;
    int len;

    // Encrypt the data
    if (1 != EVP_EncryptInit_ex(ctx, NULL, NULL, NULL, NULL)) {
        // Handle error: encryption initialization failed
        return -1;
    }
    if (1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len)) {
        // Handle error: encryption update failed
        return -1;
    }
    *ciphertext_len = len;

    // Finalize the encryption
    if (1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        // Handle error: encryption finalization failed
        return -1;
    }
    *ciphertext_len += len;

    return 0;
}

int decrypt_data(EVP_CIPHER_CTX* ctx, const unsigned char* ciphertext, int ciphertext_len,
                 unsigned char* plaintext, int* plaintext_len) {
    *plaintext_len = 0;
    int len;

    // Decrypt the data
    if (1 != EVP_DecryptInit_ex(ctx, NULL, NULL, NULL, NULL)) {
        // Handle error: decryption initialization failed
        return -1;
    }
    if (1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        // Handle error: decryption update failed
        return -1;
    }
    *plaintext_len = len;

    // Finalize the decryption
    if (1 != EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) {
        // Handle error: decryption finalization failed
        return -1;
    }
    *plaintext_len += len;

    return 0;
}

void handle_cipher_error() {
    ERR_print_errors_fp(stderr);
}
