#include <iostream>
#include <vector>
#include <string>
#include <cstdlib>
#include <ctime>

struct CustomStruct {
    double value;
    std::string* data;

    CustomStruct(double v) : value(v), data(new std::string("Initial Data")) {}

    ~CustomStruct() {
        delete data;
    }

    void updateData(const std::string& newData) {
        *data = newData;
    }
};

class DynamicArrayManager {
private:
    std::vector<CustomStruct*> array;

public:
    DynamicArrayManager(size_t size, double minVal, double maxVal) {
        srand(time(0));
        for (size_t i = 0; i < size; ++i) {
            double randomValue = minVal + static_cast<double>(rand()) / (RAND_MAX / (maxVal - minVal));
            array.push_back(new CustomStruct(randomValue));
        }
    }

    ~DynamicArrayManager() {
        for (CustomStruct* cs : array) {
            delete cs;
        }
    }

    void updateAllData(const std::string& newData) {
        for (CustomStruct* cs : array) {
            cs->updateData(newData);
        }
    }

    void printArray() const {
        for (const CustomStruct* cs : array) {
            std::cout << "Value: " << cs->value << ", Data: " << *cs->data << std::endl;
        }
    }
};

int main() {
    size_t size = 1000;
    double minVal = 0.0;
    double maxVal = 100.0;

    DynamicArrayManager manager(size, minVal, maxVal);
    manager.printArray();

    std::string newData = "Updated Data";
    manager.updateAllData(newData);
    manager.printArray();

    return 0;
}
