#include <iostream>
#include <vector>
#include <random>
#include <mutex>
#include <thread>
#include <chrono>

struct Record {
    int value;
};

class RecordManager {
private:
    std::vector<Record> records;
    int sumOfValues;
    const int maxSum;
    std::mutex mutex;

public:
    RecordManager(int maxSum) : maxSum(maxSum), sumOfValues(0) {}

    void addRecord() {
        std::lock_guard<std::mutex> lock(mutex);
        if (sumOfValues >= maxSum) {
            std::cerr << "Error: Sum of values exceeds maximum limit." << std::endl;
            exit(EXIT_FAILURE);
        }
        Record newRecord;
        newRecord.value = getRandomValue();
        records.push_back(newRecord);
        sumOfValues += newRecord.value;
    }

    int getRandomValue() {
        static std::random_device rd;
        static std::mt19937 gen(rd());
        static std::uniform_int_distribution<> dis(1, 100); // Adjust range as needed
        return dis(gen);
    }

    void performAttack() {
        static std::random_device rd;
        static std::mt19937 gen(rd());
        static std::uniform_int_distribution<> dis(1, 2); // Attack numbers 1 and 2
        int attack = dis(gen);
        std::cout << "Selected attack: " << attack << std::endl;
    }

    void garbageCollect() {
        std::lock_guard<std::mutex> lock(mutex);
        sumOfValues = 0;
        records.clear();
    }
};

int main() {
    RecordManager manager(1000); // Set maxSum as needed
    for (int i = 0; i < 15; ++i) { // Adjust number of records as needed
        manager.addRecord();
    }

    std::thread attackThread(&RecordManager::performAttack, &manager);
    attackThread.join();

    manager.garbageCollect();

    return 0;
}
