#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

int findLargest(int* array, int size) {
    if (size <= 0) return -1; // Return an error code for invalid input
    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

void initializeResourceBundle(int keySize, int upperBound, Record** records, int** keys) {
    srand(time(NULL)); // Seed the random number generator

    *records = (Record*)malloc(keySize * sizeof(Record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed for records\n");
        return;
    }

    *keys = (int*)malloc(keySize * sizeof(int));
    if (*keys == NULL) {
        free(*records);
        fprintf(stderr, "Memory allocation failed for keys\n");
        return;
    }

    for (int i = 0; i < keySize; i++) {
        (*records)[i].value = rand() % (upperBound + 1);
        (*keys)[i] = i; // Assuming keys are sequential integers
    }
}

void loadResourceBundleFromFile(const char* filename, Record** records, int** keys) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading\n");
        return;
    }

    // Assuming the file contains keySize and upperBound on the first line
    int keySize, upperBound;
    fscanf(file, "%d %d", &keySize, &upperBound);

    initializeResourceBundle(keySize, upperBound, records, keys);

    if (*records == NULL || *keys == NULL) {
        fclose(file);
        return;
    }

    // Read the rest of the file to populate the records and keys
    for (int i = 0; i < keySize; i++) {
        fscanf(file, "%d %d", &(*keys)[i], &(*records)[i].value);
    }

    fclose(file);
}

void updateResourceBundleToFile(const char* filename, Record* records, int* keys, int size) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    // Write keySize and upperBound on the first line
    fprintf(file, "%d %d\n", size, records[0].value);

    // Write the rest of the data
    for (int i = 0; i < size; i++) {
        fprintf(file, "%d %d\n", keys[i], records[i].value);
    }

    fclose(file);
}

int main() {
    Record* records;
    int* keys;

    loadResourceBundleFromFile("resource_bundle.txt", &records, &keys);

    if (records != NULL && keys != NULL) {
        int largest = findLargest(keys, 10); // Assuming we want to find the largest key
        printf("Largest key: %d\n", largest);

        updateResourceBundleToFile("updated_resource_bundle.txt", records, keys, 10);
    }

    free(records);
    free(keys);

    return 0;
}
