int initialize_message_system(int key_count, int max_length) {
    srand(time(NULL));
    int *keys = (int *)malloc(key_count * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        return -1;
    }

    TextMessage *messages = (TextMessage *)malloc(key_count * sizeof(TextMessage));
    if (!messages) {
        free(keys);
        fprintf(stderr, "Memory allocation failed for messages\n");
        return -1;
    }

    int longest_length = 0;
    int longest_index = -1;

    for (int i = 0; i < key_count; i++) {
        keys[i] = i;
        int length = rand() % max_length + 1;
        if (length > MAX_TEXT_LENGTH) {
            fprintf(stderr, "Random length exceeds maximum text length\n");
            free(keys);
            free(messages);
            return -1;
        }
        messages[i].text[0] = '\0';
        for (int j = 0; j < length; j++) {
            messages[i].text[j] = 'a' + rand() % 26;
        }
        messages[i].text[length] = '\0';

        if (length > longest_length) {
            longest_length = length;
            longest_index = i;
        }
    }

    printf("Longest message: Index %d, Length %d\n", longest_index, longest_length);

    free(keys);
    free(messages);

    return 0;
}

int main() {
    int key_count;
    int max_length;

    printf("Enter the number of messages: ");
    scanf("%d", &key_count);

    printf("Enter the maximum length for each message: ");
    scanf("%d", &max_length);

    if (initialize_message_system(key_count, max_length) != 0) {
        fprintf(stderr, "Failed to initialize message system\n");
        return -1;
    }

    return 0;
}
