// Function to find and print the largest integer in an array
void findAndPrintLargest(int* arr, int size) {
    if (size <= 0) return;
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    printf("Largest integer: %d\n", max);
}

// Function to initialize records with random values
void initRecords(Record* records, int size, int upperBound) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        records[i].value = rand() % (upperBound + 1);
    }
}

// Function to free allocated memory
void freeMemory(int* keys, Record* records, int size) {
    if (keys != NULL) free(keys);
    if (records != NULL) free(records);
}

int main() {
    int size;
    printf("Enter the number of elements: ");
    scanf("%d", &size);

    // Allocate memory for keys and records
    int* keys = (int*)malloc(size * sizeof(int));
    Record* records = (Record*)malloc(size * sizeof(Record));

    if (keys == NULL || records == NULL) {
        printf("Memory allocation failed.\n");
        freeMemory(keys, records, size);
        return 1;
    }

    // Initialize keys and records
    for (int i = 0; i < size; i++) {
        keys[i] = i + 1;
    }
    initRecords(records, size, 100); // Upper bound set to 100

    // Find and print the largest integer in the array of keys
    findAndPrintLargest(keys, size);

    // Free allocated memory
    freeMemory(keys, records, size);

    return 0;
}
