        free(*int_keys);
        free(*records);
        free(*labels);
        return -1;
    }

    for (int i = 0; i < size; i++) {
        (*records)[i].value = roundf(rand() / (float)RAND_MAX * 100) / 100;
        (*labels)[i] = (char*)malloc(256 * sizeof(char));
    }

    return 0;
}

void free_memory(int* int_keys, record** records, char*** labels, int size) {
    for (int i = 0; i < size; i++) {
        free((*labels)[i]);
    }
    free(*records);
    free(*int_keys);
    free(*labels);
}

void find_min_max(float* float_array, int size, float* min, float* max) {
    *min = *max = float_array[0];
    for (int i = 1; i < size; i++) {
        if (float_array[i] < *min) *min = float_array[i];
        if (float_array[i] > *max) *max = float_array[i];
    }
}

int main() {
    int size;
    printf("Enter the number of elements: ");
    scanf("%d", &size);

    int* int_keys;
    record* records;
    char** labels;

    if (allocate_memory(&int_keys, &records, &labels, size) != 0) {
        return -1;
    }

    for (int i = 0; i < size; i++) {
        printf("Enter key and label for element %d: ", i);
        scanf("%d %s", &int_keys[i], labels[i]);
    }

    float min, max;
    find_min_max(records[0].value, size, &min, &max);

    printf("Min value: %.2f\n", min);
    printf("Max value: %.2f\n", max);

    free_memory(&int_keys, &records, &labels, size);

    return 0;
}
