int find_largest(int* arr, int size) {
    if (size <= 0) return -1; // Handle edge case for empty array
    int largest = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    return largest;
}

void free_all_memory(int* keys, record* records, int* input_ints, int key_size, int record_size, int input_size) {
    for (int i = 0; i < key_size; i++) {
        free(keys[i]);
    }
    for (int i = 0; i < record_size; i++) {
        free(records[i].key);
    }
    free(keys);
    free(records);
    free(input_ints);
}

int initialize_data(int* keys, record* records, int* input_ints, int key_size, int record_size, int input_size, int lower_bound, int upper_bound) {
    srand(time(NULL));

    // Allocate memory for keys
    if ((keys = (int*)malloc(key_size * sizeof(int))) == NULL) {
        return -1;
    }

    // Allocate memory for records
    if ((records = (record*)malloc(record_size * sizeof(record))) == NULL) {
        free_all_memory(keys, records, input_ints, key_size, record_size, input_size);
        return -1;
    }

    // Allocate memory for input integers
    if ((input_ints = (int*)malloc(input_size * sizeof(int))) == NULL) {
        free_all_memory(keys, records, input_ints, key_size, record_size, input_size);
        return -1;
    }

    // Initialize keys and records with random numbers and their string representations
    for (int i = 0; i < record_size; i++) {
        int random_value = rand() % (upper_bound - lower_bound + 1) + lower_bound;
        keys[i] = random_value;
        if ((records[i].key = (char*)malloc(20 * sizeof(char))) == NULL) { // Assuming max key length is 19 characters
            free_all_memory(keys, records, input_ints, key_size, record_size, input_size);
            return -1;
        }
        sprintf(records[i].key, "%d", random_value);
        records[i].value = random_value;
    }

    // Read integers from standard input and store in array
    for (int i = 0; i < input_size; i++) {
        scanf("%d", &input_ints[i]);
    }

    return 0;
}

int main() {
    int key_size, record_size, input_size, lower_bound, upper_bound;

    printf("Enter the number of keys: ");
    scanf("%d", &key_size);
    printf("Enter the number of records: ");
    scanf("%d", &record_size);
    printf("Enter the number of input integers: ");
    scanf("%d", &input_size);
    printf("Enter the lower bound for random numbers: ");
    scanf("%d", &lower_bound);
    printf("Enter the upper bound for random numbers: ");
    scanf("%d", &upper_bound);

    int* keys = NULL;
    record* records = NULL;
    int* input_ints = NULL;

    if (initialize_data(keys, records, input_ints, key_size, record_size, input_size, lower_bound, upper_bound) == 0) {
        printf("Largest integer in input array: %d\n", find_largest(input_ints, input_size));

        // Free all allocated memory
        free_all_memory(keys, records, input_ints, key_size, record_size, input_size);
    } else {
        printf("Memory allocation failed.\n");
    }

    return 0;
}
