#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define UPPER_BOUND 100

typedef struct {
    char name[50];
    int age;
    char email[100];
} record;

int findLargest(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

void* initializeRecords(void* arg) {
    int* keys = (int*)arg;
    record* records = malloc(MAX_RECORDS * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        pthread_exit(NULL);
    }

    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i].age = rand() % UPPER_BOUND;
        sprintf(records[i].name, "User%d", keys[i]);
        sprintf(records[i].email, "user%d@example.com", keys[i]);
    }

    // Simulate database persistence
    for (int i = 0; i < MAX_RECORDS; i++) {
        printf("Persisting record: %s, %d, %s\n", records[i].name, records[i].age, records[i].email);
    }

    free(records);
    pthread_exit(NULL);
}

int main() {
    int keys[MAX_RECORDS];
    for (int i = 0; i < MAX_RECORDS; i++) {
        scanf("%d", &keys[i]);
    }

    pthread_t threads[MAX_RECORDS];
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (pthread_create(&threads[i], NULL, initializeRecords, &keys[i]) != 0) {
            perror("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < MAX_RECORDS; i++) {
        pthread_join(threads[i], NULL);
    }

    int largest = findLargest(keys, MAX_RECORDS);
    printf("Largest integer: %d\n", largest);

    return EXIT_SUCCESS;
}
