void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

int initialize_data(int array_size, int record_upper_bound, char** string_keys, Record* records, int* integers, char** strings) {
