        string_keys[i] = (char*)safe_malloc((rand() % (MAX_STRING_LENGTH - MIN_STRING_LENGTH + 1)) + MIN_STRING_LENGTH);
        for (int j = 0; j < strlen(string_keys[i]); j++) {
            string_keys[i][j] = 'a' + rand() % 26;
        }
    }

    for (int i = 0; i < array_size; i++) {
        integers[i] = rand();
        strings[i] = (char*)safe_malloc((rand() % (MAX_STRING_LENGTH - MIN_STRING_LENGTH + 1)) + MIN_STRING_LENGTH);
        for (int j = 0; j < strlen(strings[i]); j++) {
            strings[i][j] = 'a' + rand() % 26;
        }
    }

    return 0;
}

void free_data(int array_size, char** string_keys, Record* records, int* integers, char** strings) {
    for (int i = 0; i < array_size; i++) {
        free(string_keys[i]);
        free(strings[i]);
    }
    free(records);
    free(integers);
}

void find_largest_integer_and_longest_string(int array_size, int* integers, char** strings) {
    int largest_integer = integers[0];
    char* longest_string = strings[0];

    for (int i = 1; i < array_size; i++) {
        if (integers[i] > largest_integer) {
            largest_integer = integers[i];
        }
        if (strlen(strings[i]) > strlen(longest_string)) {
            longest_string = strings[i];
        }
    }

    printf("Largest Integer: %d\n", largest_integer);
    printf("Longest String: %s\n", longest_string);
}

int main() {
    int array_size;
    printf("Enter the size of the arrays: ");
    scanf("%d", &array_size);

    Record* records = (Record*)safe_malloc(array_size * sizeof(Record));
    int* integers = (int*)safe_malloc(array_size * sizeof(int));
    char** strings = (char**)safe_malloc(array_size * sizeof(char*));

    if (initialize_data(array_size, MAX_RECORD_VALUE, strings, records, integers, strings) != 0) {
        free_data(array_size, strings, records, integers, strings);
        return EXIT_FAILURE;
    }

    find_largest_integer_and_longest_string(array_size, integers, strings);

    free_data(array_size, strings, records, integers, strings);

    return EXIT_SUCCESS;
}
