public:
    DataManager(size_t intSize, size_t recordSize, int upperBound)
        : intArray(intSize), recordArray(recordSize), dbAvailable(true) {
        initializeArrays(upperBound);
    }

    void initializeArrays(int upperBound) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, upperBound);

        try {
            for (auto& elem : intArray) {
                elem = dis(gen);
            }
            for (auto& rec : recordArray) {
                rec.value = dis(gen);
            }
        } catch (const std::bad_alloc& e) {
            std::cerr << "Memory allocation failed: " << e.what() << std::endl;
            throw;
        }
    }

