            dbAvailable = true;
        } else {
            dbAvailable = false;
        }
    }

    bool isDbAvailable() const {
        return dbAvailable;
    }

    void performDatabaseOperation() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this] { return dbAvailable; });

        // Simulate database operation
        if (dbAvailable) {
            std::cout << "Performing database operation..." << std::endl;
        } else {
            throw std::runtime_error("Database is unavailable");
        }
    }

