        std::cerr << "Error: " << error << std::endl;
    }
};

int main() {
    DataManager dm(1000, 500, 100);
    dm.connectToDatabase("primary");

    try {
        dm.performDatabaseOperation();
    } catch (const std::exception& e) {
        dm.logError(e.what());
    }

    return 0;
}
