    public string RecipientId { get; set; }
    public string Content { get; set; }
    public DateTime Timestamp { get; set; }
}

public class MessagingService
{
    public Task SendAsync(List<Message> messages)
    {
        // Simulate asynchronous message delivery
        return Task.Delay(100);
    }

    public void RetryFailedMessages(List<Message> failedMessages)
    {
        // Implement retry logic here
    }
}

public class MessageGenerator
{
    private static readonly string[] Messages = { "Hello", "World", "C#", "Programming" };
    private static readonly Random random = new Random();
    private static readonly object lockObject = new object();

    public byte[] GenerateAndSendMessages(string input, bool compressPayloads)
    {
        int numberOfMessages;
        if (!int.TryParse(input, out numberOfMessages))
        {
            Console.WriteLine("Invalid input for number of messages.");
            return null;
        }

        List<Message> messages = new List<Message>();
        try
        {
            lock (lockObject)
            {
                for (int i = 0; i < numberOfMessages; i++)
                {
                    Message message = new Message
                    {
                        SenderId = "Sender" + i,
                        RecipientId = "Recipient" + i,
                        Content = Messages[random.Next(Messages.Length)],
                        Timestamp = DateTime.UtcNow
                    };
                    messages.Add(message);
                }
            }

            MessagingService messagingService = new MessagingService();
            Task sendTask = messagingService.SendAsync(messages);

            // Implement backpressure and retry mechanisms here

            sendTask.Wait();

            if (sendTask.IsFaulted)
            {
                messagingService.RetryFailedMessages(messages.Where(m => !m.Timestamp.Equals(DateTime.UtcNow)).ToList());
            }

            Console.WriteLine($"Successfully sent {messages.Count} messages.");
        }
        catch (OutOfMemoryException ex)
        {
            Console.WriteLine($"Memory allocation failed: {ex.Message}");
            return null;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
            return null;
        }

        byte[] md5Hash = GenerateMd5Hash(input);
        return md5Hash;
    }

    private static byte[] GenerateMd5Hash(string input)
    {
        using (MD5 md5 = MD5.Create())
        {
            byte[] inputBytes = Encoding.ASCII.GetBytes(input);
            byte[] hashBytes = md5.ComputeHash(inputBytes);
            return hashBytes;
        }
    }
}
