    // Allocate memory for arrays and structures
    int* keys = (int*)malloc(array_size * sizeof(int));
    Record* records = (Record*)malloc(array_size * sizeof(Record));
    int* input_integers = (int*)malloc(array_size * sizeof(int));
    char** key_strings = (char**)malloc(array_size * sizeof(char*));
    FILE* log_file = fopen("log.txt", "w");

    if (!keys || !records || !input_integers || !key_strings || !log_file) {
        // Handle memory allocation failure
        fprintf(stderr, "Memory allocation failed\n");
        free(keys);
        free(records);
        free(input_integers);
        free(key_strings);
        fclose(log_file);
        return NULL;
    }

    // Initialize arrays and structures
    for (int i = 0; i < array_size; i++) {
        keys[i] = rand() % upper_bound;
        records[i].value = keys[i];
        records[i].key = (char*)malloc(20 * sizeof(char));
        sprintf(records[i].key, "Key%d", keys[i]);
        key_strings[i] = records[i].key;
    }

