    // Free allocated memory
    for (int i = 0; i < array_size; i++) {
        free(records[i].key);
    }
    free(keys);
    free(records);
    free(input_integers);
    free(key_strings);
    fclose(log_file);

    return NULL;
}

void* find_max(void* input_integers, int size) {
    // Find and return the largest integer
    int max_value = *(int*)input_integers;
    for (int i = 1; i < size; i++) {
        if (*(int*)((char*)input_integers + i * sizeof(int)) > max_value) {
            max_value = *(int*)((char*)input_integers + i * sizeof(int));
        }
    }
    return (void*)max_value;
}

void log_performance(FILE* log_file, int array_size, int max_value) {
    // Log performance metrics
    fprintf(log_file, "Array size: %d\n", array_size);
    fprintf(log_file, "Largest value: %d\n", max_value);
}
