#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct node {
    char* data;
    int priority;
    struct node* next;
} Node;

typedef struct {
    Node** nodes;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} NodeList;

NodeList* create_node_list(size_t initial_capacity) {
    NodeList* list = (NodeList*)malloc(sizeof(NodeList));
    if (!list) return NULL;

    list->nodes = (Node**)calloc(initial_capacity, sizeof(Node*));
    if (!list->nodes) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_node_list(NodeList* list) {
    for (size_t i = 0; i < list->size; ++i) {
        free(list->nodes[i]->data);
        free(list->nodes[i]);
    }
    free(list->nodes);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void resize_node_list(NodeList* list, size_t new_capacity) {
    Node** new_nodes = (Node**)realloc(list->nodes, new_capacity * sizeof(Node*));
    if (!new_nodes) return;

    list->nodes = new_nodes;
    list->capacity = new_capacity;
}

void insert_node(NodeList* list, const char* data, int priority) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        resize_node_list(list, new_capacity);
    }

    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    new_node->data = strdup(data);
    new_node->priority = priority;
    new_node->next = NULL;

    list->nodes[list->size++] = new_node;

    pthread_mutex_unlock(&list->lock);
}

int main() {
    NodeList* list = create_node_list(10);
    if (!list) return 1;

    insert_node(list, "Node1", 5);
    insert_node(list, "Node2", 3);
    insert_node(list, "Node3", 7);

    destroy_node_list(list);
    return 0;
}
