#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    long offset;
    int key;
} Record;

typedef struct {
    int num_records;
    int range_min;
    int range_max;
    double memory_threshold;
    pthread_mutex_t lock;
    Record* records;
    int* cache;
    int cache_size;
} Config;

void init_config(Config* config, int num_records, int range_min, int range_max, double memory_threshold) {
    config->num_records = num_records;
    config->range_min = range_min;
    config->range_max = range_max;
    config->memory_threshold = memory_threshold;
    pthread_mutex_init(&config->lock, NULL);
    config->records = (Record*)malloc(num_records * sizeof(Record));
    config->cache = (int*)malloc(num_records * sizeof(int));
    config->cache_size = 0;
}

void free_config(Config* config) {
    pthread_mutex_destroy(&config->lock);
    free(config->records);
    free(config->cache);
}

void* allocate_record(void* arg) {
    Config* config = (Config*)arg;
    Record* record = NULL;

    pthread_mutex_lock(&config->lock);

    if (config->cache_size > 0) {
        int index = config->cache[--config->cache_size];
        record = &config->records[index];
    } else {
        for (int i = 0; i < config->num_records; i++) {
            if (config->records[i].offset == -1) {
                record = &config->records[i];
                break;
            }
        }
    }

    if (record != NULL) {
        record->offset = rand() % (config->range_max - config->range_min + 1) + config->range_min;
        record->key = rand();
    } else {
        printf("Memory allocation failed\n");
    }

    pthread_mutex_unlock(&config->lock);

    return record;
}

void validate_records(Config* config) {
    for (int i = 0; i < config->num_records; i++) {
        if (config->records[i].offset == -1) {
            printf("Record %d is not initialized\n", i);
        }
    }
}

void log_memory_usage(Config* config) {
    double used_memory = sizeof(Record) * config->num_records + sizeof(int) * config->cache_size;
    if (used_memory / (sizeof(Record) * config->num_records) > config->memory_threshold) {
        printf("Memory usage exceeds threshold\n");
    }
}

int main() {
    srand(time(NULL));
    Config config;
    init_config(&config, 1000, 0, 10000, 0.8);

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, allocate_record, &config);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    validate_records(&config);
    log_memory_usage(&config);

    free_config(&config);
    return 0;
}
