#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Node {
    char* str;
    int priority;
    struct Node* next;
} Node;

typedef struct Tree {
    Node* root;
    pthread_mutex_t lock;
} Tree;

Node* create_node(const char* str, int priority) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;
    node->str = strdup(str);
    if (!node->str) {
        free(node);
        return NULL;
    }
    node->priority = priority;
    node->next = NULL;
    return node;
}

void insert_node(Tree* tree, const char* str, int priority) {
    pthread_mutex_lock(&tree->lock);
    Node* new_node = create_node(str, priority);
    if (!new_node) {
        pthread_mutex_unlock(&tree->lock);
        return;
    }
    if (!tree->root) {
        tree->root = new_node;
    } else {
        Node* current = tree->root;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&tree->lock);
}

void delete_node(Tree* tree, const char* str) {
    pthread_mutex_lock(&tree->lock);
    Node* current = tree->root;
    Node* prev = NULL;
    while (current) {
        if (strcmp(current->str, str) == 0) {
            if (prev) {
                prev->next = current->next;
            } else {
                tree->root = current->next;
            }
            free(current->str);
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&tree->lock);
}

void traverse_tree(Tree* tree) {
    pthread_mutex_lock(&tree->lock);
    Node* current = tree->root;
    while (current) {
