#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_NODES 10000000

typedef struct Node {
    char* data;
    int priority;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

Node* create_node(const char* data, int priority) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Failed to allocate memory for node");
        exit(EXIT_FAILURE);
    }
    new_node->data = strdup(data);
    new_node->priority = priority;
    new_node->next = NULL;
    return new_node;
}

void insert_node(LinkedList* list, const char* data, int priority) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = create_node(data, priority);
    if (list->head == NULL || priority > list->head->priority) {
        new_node->next = list->head;
        list->head = new_node;
    } else {
        Node* current = list->head;
        while (current->next != NULL && current->next->priority >= priority) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
    pthread_mutex_unlock(&list->lock);
}

void delete_node(LinkedList* list, const char* data) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* previous = NULL;
    while (current != NULL && strcmp(current->data, data) != 0) {
        previous = current;
        current = current->next;
    }
    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    if (previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }
    free(current->data);
    free(current);
    pthread_mutex_unlock(&list->lock);
}

void destroy_list(LinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}
