#include <string.h>
#include <time.h>

#define MAX_STRING_LENGTH 256
#define POOL_SIZE 1024 * 1024 // 1MB

typedef struct Record {
    int key;
    size_t length;
    char data[MAX_STRING_LENGTH];
    struct Record* next;
} Record;

typedef struct MemoryPool {
    char pool[POOL_SIZE];
    size_t used;
} MemoryPool;

MemoryPool memory_pool = { .used = 0 };

Record* create_record(int key, const char* data) {
    if (memory_pool.used + sizeof(Record) + strlen(data) > POOL_SIZE) {
        return NULL; // Not enough space in the pool
    }

    Record* record = (Record*)(memory_pool.pool + memory_pool.used);
    memory_pool.used += sizeof(Record);

    record->key = key;
    record->length = strlen(data);
    strncpy(record->data, data, MAX_STRING_LENGTH - 1);
    record->data[MAX_STRING_LENGTH - 1] = '\0';
    record->next = NULL;

    return record;
}

void free_records(Record* head) {
    Record* current = head;
    while (current != NULL) {
        Record* next = current->next;
        // No need to free individual strings as they are within the pool
        free(current);
        current = next;
    }
}

void print_records(Record* head) {
    Record* current = head;
    while (current != NULL) {
        printf("Key: %d, Length: %zu, Data: %s\n", current->key, current->length, current->data);
        current = current->next;
    }
}

int main() {
    srand(time(NULL));

    Record* records = NULL;

    for (int i = 0; i < 100; ++i) {
        int key = rand() % 1000;
        char data[MAX_STRING_LENGTH];
        snprintf(data, MAX_STRING_LENGTH, "Record %d", i);
        Record* new_record = create_record(key, data);
        if (new_record != NULL) {
            new_record->next = records;
            records = new_record;
        } else {
            printf("Failed to allocate memory for record %d\n", i);
        }
    }

    print_records(records);

    free_records(records);

    return 0;
}
