    pthread_t threads[config->num_records];
    for (int i = 0; i < config->num_records; i++) {
        records[i].identifier = malloc(20 * sizeof(char));
        if (!records[i].identifier) {
            perror("Failed to allocate memory for identifier");
            free(records);
            return NULL;
