#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/rand.h>
#include <arpa/inet.h>

#define MAX_TRANSACTION_SIZE 1024
#define MAX_ACCOUNT_LENGTH 50

typedef struct {
    int id;
    time_t timestamp;
    char account[MAX_ACCOUNT_LENGTH];
    double amount;
    char currency[3];
    char status[20];
} Transaction;

typedef struct {
    Transaction *transactions;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} TransactionDataset;

void initTransaction(Transaction *t, int id, time_t timestamp, const char *prefix, const char *suffix) {
    t->id = id;
    t->timestamp = timestamp;
    snprintf(t->account, MAX_ACCOUNT_LENGTH, "%s%.*s%s", prefix, MAX_ACCOUNT_LENGTH - strlen(prefix) - strlen(suffix), "random_string", suffix);
    t->amount = 0.0;
    strcpy(t->currency, "USD");
    strcpy(t->status, "Pending");
}

void processFinancialTransactions(TransactionDataset *dataset, int action, const char *hostname, int port) {
    pthread_mutex_lock(&dataset->lock);

    switch (action) {
        case INIT:
            dataset->transactions = malloc(MAX_TRANSACTION_SIZE * sizeof(Transaction));
            dataset->count = 0;
            dataset->capacity = MAX_TRANSACTION_SIZE;
            pthread_mutex_init(&dataset->lock, NULL);
            break;

        case ADD_TRANSACTION:
            if (dataset->count >= dataset->capacity) {
                dataset->capacity *= 2;
                dataset->transactions = realloc(dataset->transactions, dataset->capacity * sizeof(Transaction));
            }
            initTransaction(&dataset->transactions[dataset->count++], dataset->count, time(NULL), "ACC", "_123");
            break;

        case FREE_MEMORY:
            free(dataset->transactions);
            pthread_mutex_destroy(&dataset->lock);
            break;
    }

    pthread_mutex_unlock(&dataset->lock);

    // Simulate WebSocket update
    if (action == ADD_TRANSACTION) {
        struct sockaddr_in server_addr;
        int sockfd = socket(AF_INET, SOCK_STREAM, 0);
        memset(&server_addr, 0, sizeof(server_addr));
        server_addr.sin_family = AF_INET;
        inet_pton(AF_INET, hostname, &server_addr.sin_addr);
        server_addr.sin_port = htons(port);

        connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr));
        send(sockfd, "Transaction added", 16, 0);
        close(sockfd);
    }
}

int main() {
    TransactionDataset dataset;
    processFinancialTransactions(&dataset, INIT, "example.com", 8080);

    for (int i = 0; i < 5; i++) {
        processFinancialTransactions(&dataset, ADD_TRANSACTION, "example.com", 8080);
    }

    processFinancialTransactions(&dataset, FREE_MEMORY, NULL, 0);

    return 0;
}
