// Function to calculate distance between two locations using Haversine formula
double calculateDistance(Location loc1, Location loc2) {
    const double R = 6371.0; // Earth's radius in kilometers
    double lat1 = loc1.latitude * M_PI / 180;
    double lon1 = loc1.longitude * M_PI / 180;
    double lat2 = loc2.latitude * M_PI / 180;
    double lon2 = loc2.longitude * M_PI / 180;

    double dlon = lon2 - lon1;
    double dlat = lat2 - lat1;

    double a = sin(dlat / 2) * sin(dlat / 2) +
               cos(lat1) * cos(lat2) *
               sin(dlon / 2) * sin(dlon / 2);
    double c = 2 * atan2(sqrt(a), sqrt(1 - a));

    return R * c;
}

// Function to find the nearest location within a given radius
Location* findNearestLocation(Location locations[], int count, Location queryLoc, double radius) {
    Location* nearest = NULL;
    double minDistance = radius;

    for (int i = 0; i < count; i++) {
        double distance = calculateDistance(locations[i], queryLoc);
        if (distance <= radius && (nearest == NULL || distance < minDistance)) {
            nearest = &locations[i];
            minDistance = distance;
        }
    }

    return nearest;
}

// Function to perform parallel spatial queries using threads
void* parallelQuery(void* arg) {
    // Implement parallel query logic here
    return NULL;
}

// Main function to demonstrate the usage of the location management functions
int main() {
    Location locations[] = {
        {34.0522, -118.2437, 0, "Los Angeles"},
        {40.7128, -74.0060, 0, "New York"},
        // Add more locations as needed
    };
    int count = sizeof(locations) / sizeof(locations[0]);

    Location queryLoc = {35.0000, -119.0000, 0, "Query Location"};
    double radius = 100; // Radius in kilometers

    Location* nearest = findNearestLocation(locations, count, queryLoc, radius);
    if (nearest != NULL) {
        printf("Nearest location: %s\n", nearest->name);
    } else {
        printf("No location found within the specified radius.\n");
    }

    // Implement parallel query using threads
    pthread_t thread;
    pthread_create(&thread, NULL, parallelQuery, NULL);
    pthread_join(thread, NULL);

    return 0;
}
