#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <curl/curl.h>

#define MAX_CONCURRENT_REQUESTS 50
#define BUFFER_SIZE 1024

typedef struct {
    char url[256];
    CURL *handle;
} Request;

typedef struct {
    Request requests[MAX_CONCURRENT_REQUESTS];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} CircularBuffer;

CircularBuffer buffer;

void init_buffer() {
    memset(&buffer, 0, sizeof(buffer));
    pthread_mutex_init(&buffer.mutex, NULL);
    pthread_cond_init(&buffer.not_full, NULL);
    pthread_cond_init(&buffer.not_empty, NULL);
}

void enqueue(Request req) {
    pthread_mutex_lock(&buffer.mutex);
    while (buffer.count == MAX_CONCURRENT_REQUESTS) {
        pthread_cond_wait(&buffer.not_full, &buffer.mutex);
    }
    buffer.requests[buffer.tail] = req;
    buffer.tail = (buffer.tail + 1) % MAX_CONCURRENT_REQUESTS;
    buffer.count++;
    pthread_cond_signal(&buffer.not_empty);
    pthread_mutex_unlock(&buffer.mutex);
}

Request dequeue() {
    Request req;
    pthread_mutex_lock(&buffer.mutex);
    while (buffer.count == 0) {
        pthread_cond_wait(&buffer.not_empty, &buffer.mutex);
    }
    req = buffer.requests[buffer.head];
    buffer.head = (buffer.head + 1) % MAX_CONCURRENT_REQUESTS;
    buffer.count--;
    pthread_cond_signal(&buffer.not_full);
    pthread_mutex_unlock(&buffer.mutex);
    return req;
}

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    // Handle the received data
    return size * nmemb;
}

void* worker_thread(void* arg) {
    while (1) {
        Request req = dequeue();
        CURLcode res = curl_easy_setopt(req.handle, CURLOPT_URL, req.url);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_setopt() failed: %s\n", curl_easy_strerror(res));
            continue;
        }
        res = curl_easy_setopt(req.handle, CURLOPT_WRITEFUNCTION, write_callback);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_setopt() failed: %s\n", curl_easy_strerror(res));
            continue;
        }
        res = curl_easy_perform(req.handle);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }
    }
}

int main(int argc, char *argv[]) {
    init_buffer();

    // Initialize libcurl
    CURL *multi_handle = curl_multi_init();
    if (!multi_handle) {
        fprintf(stderr, "Failed to initialize libcurl multi handle\n");
        return 1;
    }

    // Create worker threads
    pthread_t threads[MAX_CONCURRENT_REQUESTS];
    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        Request req;
        req.handle = curl_easy_init();
        if (!req.handle) {
            fprintf(stderr, "Failed to initialize libcurl easy handle\n");
            return 1;
        }
        enqueue(req);
        pthread_create(&threads[i], NULL, worker_thread, NULL);
    }

    // Add URLs from configuration file
    FILE *config_file = fopen("urls.conf", "r");
    if (!config_file) {
        fprintf(stderr, "Failed to open configuration file\n");
        return 1;
    }
    char url[256];
    while (fgets(url, sizeof(url), config_file)) {
        url[strcspn(url, "\n")] = '\0';
        Request req;
        strcpy(req.url, url);
        enqueue(req);
    }
    fclose(config_file);

    // Wait for all worker threads to finish
    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up libcurl
    curl_multi_cleanup(multi_handle);
    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        Request req = dequeue();
        curl_easy_cleanup(req.handle);
    }

    return 0;
}
