#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <pthread.h>

#define EARTH_RADIUS 6371000 // Earth's radius in meters

typedef struct {
    double latitude;
    double longitude;
    double elevation;
    char name[256];
} Location;

typedef struct {
    Location *locations;
    int count;
    pthread_mutex_t lock;
} GeoDataset;

GeoDataset* create_dataset() {
    GeoDataset *dataset = (GeoDataset*)malloc(sizeof(GeoDataset));
    dataset->locations = NULL;
    dataset->count = 0;
    pthread_mutex_init(&dataset->lock, NULL);
    return dataset;
}

void add_location(GeoDataset *dataset, Location location) {
    pthread_mutex_lock(&dataset->lock);
    dataset->locations = (Location*)realloc(dataset->locations, (dataset->count + 1) * sizeof(Location));
    dataset->locations[dataset->count++] = location;
    pthread_mutex_unlock(&dataset->lock);
}

double haversine(double lat1, double lon1, double lat2, double lon2) {
    double dLat = (lat2 - lat1) * M_PI / 180.0;
    double dLon = (lon2 - lon1) * M_PI / 180.0;
    double a = sin(dLat / 2) * sin(dLat / 2) +
               cos(lat1 * M_PI / 180.0) * cos(lat2 * M_PI / 180.0) *
               sin(dLon / 2) * sin(dLon / 2);
    double c = 2 * atan2(sqrt(a), sqrt(1 - a));
    return EARTH_RADIUS * c;
}

Location* find_nearest_location(GeoDataset *dataset, double latitude, double longitude, double radius) {
    pthread_mutex_lock(&dataset->lock);
    Location *nearest = NULL;
    double min_distance = radius;
    for (int i = 0; i < dataset->count; i++) {
        double distance = haversine(latitude, longitude, dataset->locations[i].latitude, dataset->locations[i].longitude);
        if (distance <= min_distance) {
            nearest = &dataset->locations[i];
            min_distance = distance;
        }
    }
    pthread_mutex_unlock(&dataset->lock);
    return nearest;
}

void destroy_dataset(GeoDataset *dataset) {
    free(dataset->locations);
    pthread_mutex_destroy(&dataset->lock);
    free(dataset);
}
