#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    double latitude;
    double longitude;
    double elevation;
    char name[256];
} Location;

typedef struct Node {
    Location data;
    struct Node* left, * right;
} Node;

Node* newNode(Location item) {
    Node* temp = (Node*)malloc(sizeof(Node));
    if (!temp) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    temp->data = item;
    temp->left = temp->right = NULL;
    return temp;
}

void insert(Node** root, Location data) {
    if (*root == NULL)
        *root = newNode(data);
    else if (data.latitude < (*root)->data.latitude)
        insert(&(*root)->left, data);
    else
        insert(&(*root)->right, data);
}

Node* search(Node* root, double latitude) {
    if (root == NULL || root->data.latitude == latitude)
        return root;
    if (latitude < root->data.latitude)
        return search(root->left, latitude);
    return search(root->right, latitude);
}

int main() {
    Node* root = NULL;
    Location loc1 = {34.0522, -118.2437, 0, "Los Angeles"};
    Location loc2 = {40.7128, -74.0060, 0, "New York"};
    insert(&root, loc1);
    insert(&root, loc2);

    Node* result = search(root, 34.0522);
    if (result != NULL)
        printf("Found: %s\n", result->data.name);
    else
        printf("Not Found\n");

    return 0;
}
