#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef unsigned long offset_t;
typedef int identifier_t;

typedef struct {
    time_t timestamp;
    int status;
    identifier_t *identifier;
} entry_t;

typedef struct {
    entry_t **entries;
    size_t capacity;
    size_t size;
    void *(*allocate)(size_t);
    void (*deallocate)(void *);
} memory_pool_t;

entry_t* create_entry(time_t timestamp, int status, identifier_t *identifier) {
    entry_t *entry = (entry_t *)malloc(sizeof(entry_t));
    if (entry == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    entry->timestamp = timestamp;
    entry->status = status;
    entry->identifier = identifier;
    return entry;
}

void initialize_memory_pool(memory_pool_t *pool, size_t initial_capacity, void *(*allocate)(size_t), void (*deallocate)(void *)) {
    pool->entries = (entry_t **)malloc(initial_capacity * sizeof(entry_t *));
    if (pool->entries == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pool->capacity = initial_capacity;
    pool->size = 0;
    pool->allocate = allocate;
    pool->deallocate = deallocate;
}

void resize_memory_pool(memory_pool_t *pool, size_t new_capacity) {
    entry_t **new_entries = (entry_t **)realloc(pool->entries, new_capacity * sizeof(entry_t *));
    if (new_entries == NULL) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    pool->entries = new_entries;
    pool->capacity = new_capacity;
}

void add_entry(memory_pool_t *pool, time_t timestamp, int status, identifier_t *identifier) {
    if (pool->size == pool->capacity) {
        resize_memory_pool(pool, pool->capacity * 2);
    }
    pool->entries[pool->size++] = create_entry(timestamp, status, identifier);
}

void validate_entries(memory_pool_t *pool) {
    for (size_t i = 0; i < pool->size; ++i) {
        if (pool->entries[i]->identifier == NULL) {
            fprintf(stderr, "Invalid entry at index %zu\n", i);
            exit(EXIT_FAILURE);
        }
    }
}

void free_memory_pool(memory_pool_t *pool) {
    for (size_t i = 0; i < pool->size; ++i) {
        free(pool->entries[i]);
    }
    free(pool->entries);
}

int main() {
    memory_pool_t pool;
    initialize_memory_pool(&pool, 10, malloc, free);

    time_t start_time = time(NULL);
    for (int i = 0; i < 20; ++i) {
        add_entry(&pool, start_time + i * 60, i % 2 == 0 ? 1 : 0, &i);
    }

    validate_entries(&pool);

    free_memory_pool(&pool);
    return 0;
}
