typedef struct {
    int value;
} record;

void manage_memory(int num_entries, long **offsets, int **keys, record **records) {
    *offsets = (long *)calloc(num_entries, sizeof(long));
    if (*offsets == NULL) {
        // Handle memory allocation failure
        return;
    }

    *keys = (int *)calloc(num_entries, sizeof(int));
    if (*keys == NULL) {
        // Free previously allocated memory before exiting
        free(*offsets);
        return;
    }

    *records = (record *)malloc(1024 * sizeof(record));
    if (*records == NULL) {
        // Free previously allocated memory before exiting
        free(*offsets);
        free(*keys);
        return;
    }

    for (int i = 0; i < num_entries; i++) {
        (*offsets)[i] = 0;
        (*keys)[i] = 0;
    }

    srand(time(NULL));
    for (int i = 0; i < 1024; i++) {
        (*records)[i].value = rand() % 201 - 100; // Random between -100 and 100
    }
}

void cleanup(long *offsets, int *keys, record *records) {
    free(offsets);
    free(keys);
    free(records);
}
