import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;

public class MediaConfigParser {

    public static MediaConfig parseAndValidateMediaConfig(String json) throws ConfigurationException {
        ObjectMapper mapper = new ObjectMapper();
        try {
            JsonNode rootNode = mapper.readTree(json);
            // Validate the structure of the JSON against a predefined schema
            if (!rootNode.has("resolution") || !rootNode.has("bitrate")) {
                throw new ConfigurationException("Missing required elements in configuration");
            }
            MediaConfig config = new MediaConfig();
            config.setResolution(rootNode.get("resolution").asText());
            config.setBitrate(rootNode.get("bitrate").asInt());
            return config;
        } catch (Exception e) {
            throw new ConfigurationException("Failed to parse JSON", e);
        }
    }

    public static class MediaConfig {
        private String resolution;
        private int bitrate;

        // Getters and setters
        public String getResolution() {
            return resolution;
        }

        public void setResolution(String resolution) {
            this.resolution = resolution;
        }

        public int getBitrate() {
            return bitrate;
        }

        public void setBitrate(int bitrate) {
            this.bitrate = bitrate;
        }
    }

    public static class ConfigurationException extends Exception {
        public ConfigurationException(String message) {
            super(message);
        }

        public ConfigurationException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}
