#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>

#define MAX_TASKS 100
#define CONFIG_FILE "tasks.conf"
#define LOG_FILE "task_log.txt"

typedef struct {
    char command[256];
    int priority;
    int dependencies[MAX_TASKS];
    int num_dependencies;
} Task;

void read_config_file(Task tasks[], int *num_tasks) {
    FILE *file = fopen(CONFIG_FILE, "r");
    if (!file) {
        perror("Failed to open config file");
        return;
    }

    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file)) {
        // Skip comments and whitespace
        if (buffer[0] == '#' || isspace(buffer[0])) continue;

        Task task = {0};
        sscanf(buffer, "%s %d", task.command, &task.priority);
        // Parse dependencies if present

        tasks[*num_tasks] = task;
        (*num_tasks)++;
    }

    fclose(file);
}

void execute_task(Task *task) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("Failed to fork");
        return;
    } else if (pid == 0) {
        // Child process
        execlp(task->command, task->command, NULL);
        perror("Failed to execute command");
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        int status;
        waitpid(pid, &status, 0);
        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            printf("Task %s succeeded\n", task->command);
        } else {
            printf("Task %s failed\n", task->command);
        }
    }
}

void execute_tasks(Task tasks[], int num_tasks) {
    for (int i = 0; i < num_tasks; i++) {
        execute_task(&tasks[i]);
    }
}

int main() {
    Task tasks[MAX_TASKS];
    int num_tasks = 0;

    read_config_file(tasks, &num_tasks);
    if (num_tasks == 0) {
        printf("No valid tasks found in config file\n");
        return EXIT_FAILURE;
    }

    execute_tasks(tasks, num_tasks);

    return EXIT_SUCCESS;
}
