#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef unsigned long offset_t;
typedef int identifier_t;

typedef struct {
    time_t timestamp;
    int status;
    identifier_t *identifier;
} entry_t;

typedef struct {
    entry_t **entries;
    size_t capacity;
    size_t size;
    identifier_t *identifiers;
    size_t identifier_capacity;
    size_t identifier_size;
} data_management_system_t;

data_management_system_t* create_data_management_system(size_t initial_capacity, size_t identifier_initial_capacity) {
    data_management_system_t *system = (data_management_system_t*)malloc(sizeof(data_management_system_t));
    if (!system) return NULL;

    system->entries = (entry_t**)malloc(initial_capacity * sizeof(entry_t*));
    if (!system->entries) {
        free(system);
        return NULL;
    }

    system->identifiers = (identifier_t*)malloc(identifier_initial_capacity * sizeof(identifier_t));
    if (!system->identifiers) {
        free(system->entries);
        free(system);
        return NULL;
    }

    system->capacity = initial_capacity;
    system->size = 0;
    system->identifier_capacity = identifier_initial_capacity;
    system->identifier_size = 0;

    return system;
}

void destroy_data_management_system(data_management_system_t *system) {
    for (size_t i = 0; i < system->size; ++i) {
        free(system->entries[i]->identifier);
        free(system->entries[i]);
    }
    free(system->entries);
    free(system->identifiers);
    free(system);
}

void resize_entries(data_management_system_t *system, size_t new_capacity) {
    entry_t **new_entries = (entry_t**)realloc(system->entries, new_capacity * sizeof(entry_t*));
    if (!new_entries) return;

    system->entries = new_entries;
    system->capacity = new_capacity;
}

void resize_identifiers(data_management_system_t *system, size_t new_capacity) {
    identifier_t *new_identifiers = (identifier_t*)realloc(system->identifiers, new_capacity * sizeof(identifier_t));
    if (!new_identifiers) return;

    system->identifiers = new_identifiers;
    system->identifier_capacity = new_capacity;
}

void add_entry(data_management_system_t *system, time_t start_time, int frequency, identifier_t identifier) {
    if (system->size == system->capacity) resize_entries(system, system->capacity * 2);
    if (system->identifier_size == system->identifier_capacity) resize_identifiers(system, system->identifier_capacity * 2);

    entry_t *entry = (entry_t*)malloc(sizeof(entry_t));
    if (!entry) return;

    entry->timestamp = start_time + frequency * system->size;
    entry->status = 0; // Assuming initial status is 0
    entry->identifier = &system->identifiers[system->identifier_size++];
    *entry->identifier = identifier;

    system->entries[system->size++] = entry;
}

void validate_entries(data_management_system_t *system) {
    for (size_t i = 0; i < system->size; ++i) {
        if (!system->entries[i]->timestamp || !*system->entries[i]->identifier) {
            printf("Validation failed at index %zu\n", i);
            return;
        }
    }
    printf("All entries are valid.\n");
}

int main() {
    data_management_system_t *system = create_data_management_system(10, 5);
    if (!system) {
        fprintf(stderr, "Failed to create data management system.\n");
        return EXIT_FAILURE;
    }

    time_t start_time = time(NULL);
    for (int i = 0; i < 20; ++i) {
        add_entry(system, start_time, 10, i);
    }

    validate_entries(system);

    destroy_data_management_system(system);
    return EXIT_SUCCESS;
}
