const express = require('express');
const fs = require('fs');
const path = require('path');
const rateLimit = require('express-rate-limit');
const axios = require('axios');

const app = express();
app.use(express.json());
app.use(rateLimit({ windowMs: 1000, max: 5 }));

let dataQueue = [];
let processingBatchSize = 0;
let isProcessing = false;

// External messaging system endpoint
const MESSAGE_API_URL = 'https://external-messaging-system.com/api/messages';

// Health check endpoint
app.get('/health', (req, res) => {
  const status = {
    unprocessedDataCount: dataQueue.length,
    lastMessageTimestamp: dataQueue[dataQueue.length - 1]?.timestamp || null,
    currentProcessingBatchSize: processingBatchSize,
  };
  res.json(status);
});

// Endpoint to start the service
app.post('/start', (req, res) => {
  if (!isProcessing) {
    isProcessing = true;
    processBatch();
    res.status(200).send('Service started');
  } else {
    res.status(409).send('Service already running');
  }
});

// Endpoint to stop the service
app.post('/stop', (req, res) => {
  if (isProcessing) {
    isProcessing = false;
    saveDataToFile();
    res.status(200).send('Service stopped');
  } else {
    res.status(409).send('Service not running');
  }
});

// Endpoint to pause the service
app.post('/pause', (req, res) => {
  if (isProcessing) {
    isProcessing = false;
    res.status(200).send('Service paused');
  } else {
    res.status(409).send('Service not running');
  }
});

// Endpoint to resume the service
app.post('/resume', (req, res) => {
  if (!isProcessing) {
    isProcessing = true;
    processBatch();
    res.status(200).send('Service resumed');
  } else {
    res.status(409).send('Service already running');
  }
});

// Endpoint to add data to the queue
app.post('/data', (req, res) => {
  const newData = req.body;
  dataQueue.push(newData);
  if (!isProcessing && dataQueue.length >= processingBatchSize) {
    processBatch();
  }
  res.status(201).send('Data added');
});

// Function to process batches of data
async function processBatch() {
  while (dataQueue.length > 0 && isProcessing) {
    const batch = dataQueue.slice(0, processingBatchSize);
    dataQueue = dataQueue.slice(processingBatchSize);

    try {
      await axios.post(MESSAGE_API_URL, batch);
      console.log(`Processed ${batch.length} messages`);
    } catch (error) {
      console.error('Error sending messages:', error);
      // Retry logic can be added here
    }
  }
}

// Function to save data to a file
function saveDataToFile() {
  const filePath = path.join(__dirname, 'data.json');
  fs.writeFileSync(filePath, JSON.stringify(dataQueue));
  console.log('Data saved to file');
}

// Log rotation and retention
const logFilePath = path.join(__dirname, 'service.log');
const maxLogSize = 1024 * 1024 * 7; // 7 MB

function rotateLogs() {
  if (fs.statSync(logFilePath).size > maxLogSize) {
    fs.renameSync(logFilePath, logFilePath + '.old');
    console.log('Logs rotated and old logs retained for 7 days');
  }
}

setInterval(rotateLogs, 24 * 60 * 60 * 1000); // Rotate logs daily

app.listen(3000, () => {
  console.log('Service listening on port 3000');
});
