        exit(EXIT_FAILURE);
    }
    record->key = key;
    record->value = value;
    record->identifier = identifier;
    clock_gettime(CLOCK_MONOTONIC, &record->timestamp);
    return record;
}

void free_record(Record* record) {
    if (record != NULL) {
        free(record);
    }
}

void* init_records(void* arg) {
    int start = *(int*)arg;
    int end = start + 1000; // Assuming each thread handles 1000 records
    for (int i = start; i < end; i++) {
        Record* record = create_record(i, (float)i * 0.1, 'A' + i % 26);
        // Simulate storing the record in a database or data structure
        free_record(record); // Freeing immediately for simplicity
    }
    return NULL;
}

int main() {
    int num_threads = 4; // Number of threads to use
    pthread_t threads[num_threads];
    int thread_args[num_threads];

    for (int i = 0; i < num_threads; i++) {
        thread_args[i] = i * 1000000 / num_threads;
        if (pthread_create(&threads[i], NULL, init_records, &thread_args[i]) != 0) {
            fprintf(stderr, "Thread creation failed\n");
            exit(EXIT_FAILURE);
