EventManager *event_manager_init(int num_events) {
    EventManager *manager = (EventManager *)malloc(sizeof(EventManager));
    if (!manager) {
        return NULL;
    }
    manager->events = (Event *)calloc(num_events, sizeof(Event));
    if (!manager->events) {
        free(manager);
        return NULL;
    }
    manager->count = num_events;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void event_manager_free(EventManager *manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->lock);
        free(manager->events);
        free(manager);
    }
}

int validate_event_id(int id) {
