}

int store_event(EventManager *manager, int id) {
    pthread_mutex_lock(&manager->lock);
    if (!validate_event_id(id)) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Invalid event ID
    }
    for (int i = 0; i < manager->count; i++) {
        if (manager->events[i].id == id) {
            generate_random_value(&manager->events[i].value);
            pthread_mutex_unlock(&manager->lock);
            return 0; // Event stored successfully
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Event ID not found
}

int main() {
