    EventManager *manager = event_manager_init(MAX_EVENTS);
    if (!manager) {
        fprintf(stderr, "Failed to initialize event manager\n");
        return 1;
    }

    for (int i = 0; i < MAX_EVENTS; i++) {
        if (store_event(manager, i + 1) != 0) {
            fprintf(stderr, "Failed to store event %d\n", i + 1);
        }
    }

    event_manager_free(manager);
    return 0;
}
