#define MAX_RECORDS 1000
#define KEY_THRESHOLD 10000

typedef struct {
    int value;
} record;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

void log_info(const char *message) {
    printf("Info: %s\n", message);
}

record* create_record(int value) {
    record *r = (record*)malloc(sizeof(record));
    if (!r) {
        log_error("Failed to allocate memory for record");
        return NULL;
    }
    r->value = value;
    return r;
}

void free_record(record *r) {
    if (r) {
        free(r);
    }
}

long* initialize_offset_array(size_t size) {
    long *offsets = (long*)malloc(size * sizeof(long));
    if (!offsets) {
        log_error("Failed to allocate memory for offset array");
        return NULL;
    }
    return offsets;
}

int* initialize_key_array(size_t size, int max_value) {
    int *keys = (int*)calloc(size, sizeof(int));
    if (!keys) {
        log_error("Failed to allocate memory for key array");
        return NULL;
    }

    srand(time(NULL));
    int sum = 0;
    for (size_t i = 0; i < size; ++i) {
        keys[i] = rand() % max_value;
        sum += keys[i];
        if (sum > KEY_THRESHOLD) {
            log_error("Key threshold exceeded");
            free(keys);
            return NULL;
        }
    }

    return keys;
}

record** initialize_record_array(size_t size, int min_value, int max_value) {
    record **records = (record**)malloc(size * sizeof(record*));
    if (!records) {
        log_error("Failed to allocate memory for record array");
        return NULL;
    }

    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        records[i] = create_record(rand() % (max_value - min_value + 1) + min_value);
        if (!records[i]) {
            log_error("Failed to allocate memory for record");
            free_records(records, i);
            return NULL;
        }
    }

    return records;
}

void free_records(record **records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        free_record(records[i]);
    }
    free(records);
}

void initialize_data_structures(size_t *offset_size, int *key_size, record ***record_array, size_t initial_size, int min_value, int max_value) {
    *offset_size = initial_size;
    *key_size = initial_size;

    long *offsets = initialize_offset_array(*offset_size);
    if (!offsets) {
        return;
    }

    int *keys = initialize_key_array(*key_size, max_value);
    if (!keys) {
        free(offsets);
        return;
    }

    record **records = initialize_record_array(*record_size, min_value, max_value);
    if (!records) {
        free(keys);
        free(offsets);
        return;
    }

    *record_array = records;

    log_info("Data structures initialized successfully");
}

void* thread_function(void *arg) {
    size_t *offset_size = (size_t*)arg;
    int *key_size = (int*)arg + 1;
    record ***record_array = (record***)arg + 2;

    initialize_data_structures(offset_size, key_size, record_array, MAX_RECORDS, 0, 100);

    return NULL;
}

int main() {
    pthread_t threads[5];
    size_t offset_sizes[5] = {0};
    int key_sizes[5] = {0};
    record ***record_arrays[5];

    for (int i = 0; i < 5; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, &offset_sizes[i]) != 0) {
            log_error("Failed to create thread");
            return 1;
        }
    }

    for (int i = 0; i < 5; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
