#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define MAX_RECORDS 1000

typedef struct node {
    char identifier;
    int value;
    struct node* next;
} Node;

typedef struct record {
    int key;
    float precision;
    char identifier;
    double timestamp;
    Node* linked_list;
} Record;

Record* create_record(int range) {
    Record* rec = (Record*)malloc(sizeof(Record));
    if (!rec) return NULL;

    rec->key = rand() % range + 1;
    rec->precision = (float)(rand() % 100) / 100.0f;
    rec->identifier = 'A' + (rand() % 26);
    rec->timestamp = (double)clock() / CLOCKS_PER_SEC;

    Node* head = NULL, *tail = NULL;
    for (int i = 0; i < range; ++i) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            free_record(rec);
            return NULL;
        }
        new_node->identifier = 'a' + (rand() % 26);
        new_node->value = rand() % range + 1;
        new_node->next = NULL;

        if (!head) head = tail = new_node;
        else {
            tail->next = new_node;
            tail = new_node;
        }
    }
    rec->linked_list = head;

    return rec;
}

void free_record(Record* rec) {
    Node* current = rec->linked_list, *temp;
    while (current) {
        temp = current;
        current = current->next;
        free(temp);
    }
    free(rec);
}

int main() {
    srand(time(NULL));
    int range = 100;

    Record** records = (Record**)malloc(MAX_RECORDS * sizeof(Record*));
    if (!records) return -1;

    for (int i = 0; i < MAX_RECORDS; ++i) {
        records[i] = create_record(range);
        if (!records[i]) {
            for (int j = 0; j < i; ++j) free_record(records[j]);
            free(records);
            return -1;
        }
    }

    // Process records...

    for (int i = 0; i < MAX_RECORDS; ++i) free_record(records[i]);
    free(records);

    return 0;
}
