SemaphoreManager *create_semaphore_manager() {
    SemaphoreManager *manager = (SemaphoreManager *)malloc(sizeof(SemaphoreManager));
    if (!manager) {
        perror("Failed to allocate memory for semaphore manager");
        return NULL;
    }
    manager->count = 0;
    return manager;
}

sem_t *create_semaphore(int initial_value, SemaphoreManager *manager) {
    if (manager->count >= MAX_SEMAPHORES) {
        fprintf(stderr, "Maximum number of semaphores reached\n");
        return NULL;
    }
    sem_t *sem = (sem_t *)malloc(sizeof(sem_t));
    if (!sem) {
        perror("Failed to allocate memory for semaphore");
        return NULL;
    }
    if (sem_init(sem, 0, initial_value) != 0) {
        perror("Failed to initialize semaphore");
        free(sem);
        return NULL;
    }
    manager->sems[manager->count++] = sem;
    return sem;
}

void destroy_semaphore(sem_t *sem, SemaphoreManager *manager) {
    for (int i = 0; i < manager->count; i++) {
        if (manager->sems[i] == sem) {
            sem_destroy(sem);
            free(sem);
            for (; i < manager->count - 1; i++) {
                manager->sems[i] = manager->sems[i + 1];
            }
            manager->count--;
            break;
        }
    }
}

void destroy_semaphore_manager(SemaphoreManager *manager) {
    for (int i = 0; i < manager->count; i++) {
        sem_destroy(manager->sems[i]);
        free(manager->sems[i]);
    }
    free(manager);
}
