#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>

typedef struct {
    CURL *handle;
    char *buffer;
} HttpClient;

HttpClient *create_http_client() {
    HttpClient *client = (HttpClient *)malloc(sizeof(HttpClient));
    if (!client) {
        perror("Failed to allocate memory for HTTP client");
        return NULL;
    }
    client->handle = curl_easy_init();
    if (!client->handle) {
        fprintf(stderr, "Failed to initialize CURL handle\n");
        free(client);
        return NULL;
    }
    client->buffer = (char *)malloc(1024 * 1024); // 1MB buffer
    if (!client->buffer) {
        perror("Failed to allocate memory for HTTP response buffer");
        curl_easy_cleanup(client->handle);
        free(client);
        return NULL;
    }
    return client;
}

void destroy_http_client(HttpClient *client) {
    curl_easy_cleanup(client->handle);
    free(client->buffer);
    free(client);
}

size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    HttpClient *client = (HttpClient *)userdata;
    size_t total_size = size * nmemb;
    if (total_size > 1024 * 1024 - strlen(client->buffer)) {
        fprintf(stderr, "Response buffer overflow\n");
        return 0;
    }
    strcat(client->buffer, ptr);
    return total_size;
}

int make_http_request(HttpClient *client, const char *url) {
    curl_easy_setopt(client->handle, CURLOPT_URL, url);
    curl_easy_setopt(client->handle, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(client->handle, CURLOPT_WRITEDATA, client);
    CURLcode res = curl_easy_perform(client->handle);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to make HTTP request: %s\n", curl_easy_strerror(res));
        return -1;
    }
    printf("API Request: GET %s\n", url);
    printf("Response Data:\n%s\n", client->buffer);
    return 0;
}
