```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_CONNECTIONS 10

typedef struct {
    HttpClient *clients[MAX_CONNECTIONS];
    int count;
} ConnectionPool;

ConnectionPool *create_connection_pool() {
    ConnectionPool *pool = (ConnectionPool *)malloc(sizeof(ConnectionPool));
    if (!pool) {
        perror("Failed to allocate memory for connection pool");
        return NULL;
    }
    pool->count = 0;
    return pool;
}

HttpClient *get_connection(ConnectionPool *pool) {
    if (pool->count == MAX_CONNECTIONS) {
        fprintf(stderr, "Maximum number of connections reached\n");
        return NULL;
    }
    HttpClient *client = create_http_client();
    if (!client) {
        return NULL;
    }
    pool->clients[pool->count++] = client;
    return client;
}

void release_connection(ConnectionPool *pool, HttpClient *client) {
    for (int i = 0; i < pool->count; i++) {
        if (pool->clients[i] == client) {
            destroy_http_client(client);
            for (; i < pool->count - 1; i++) {
                pool->clients[i] = pool->clients[i + 1];
            }
            pool->count--;
            break;
        }
    }
}

void destroy_connection_pool(ConnectionPool *pool) {
    for (int i = 0; i < pool->count; i++) {
        destroy_http_client(pool->clients[i]);
    }
    free(pool);
}
