['```java
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.*;
import java.util.concurrent.*;

public class URLMetadataProcessor {

    private static final int BATCH_SIZE = 10000;
    private static final ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    private static final Map<String, List<Long>> domainResponseTimes = new ConcurrentHashMap<>();
    private static final Set<String> nonStandardStatusDomains = Collections.synchronizedSet(new HashSet<>());

    public static void processBatch(List<String> urls) {
        int batchCount = (int) Math.ceil((double) urls.size() / BATCH_SIZE);
        for (int i = 0; i < batchCount; i++) {
            List<String> subBatch = urls.subList(i * BATCH_SIZE, Math.min((i + 1) * BATCH_SIZE, urls.size()));
            CompletableFuture.runAsync(() -> processSubBatch(subBatch), executorService);
        }
    }

    private static void processSubBatch(List<String> urls) {
        for (String url : urls) {
            try {
                URL obj = new URL(url);
                HttpURLConnection con = (HttpURLConnection) obj.openConnection();
                long startTime = System.currentTimeMillis();
                int responseCode = con.getResponseCode();
                long endTime = System.currentTimeMillis();
                long responseTime = endTime - startTime;

                String domain = getDomainFromUrl(url);
                domainResponseTimes.computeIfAbsent(domain, k -> new ArrayList<>()).add(responseTime);

                if (!isStandardStatus(responseCode)) {
                    nonStandardStatusDomains.add(domain);
                }

                logPerformanceMetrics(url, responseCode, responseTime);
            } catch (Exception e) {
                logError(url, e);
            }
        }
    }

    private static String getDomainFromUrl(String url) {
        try {
            URL obj = new URL(url);
            return obj.getHost();
        } catch (Exception e) {
            return "unknown";
        }
    }

    private static boolean isStandardStatus(int responseCode) {
        return responseCode >= 200 && responseCode < 300;
    }

    private static void logPerformanceMetrics(String url, int responseCode, long responseTime) {
        System.out.println("URL: " + url + ", Response Code: " + responseCode + ", Response Time: " + responseTime + "ms");
    }

    private static void logError(String url, Exception e) {
        System.err.println("Error processing URL: " + url + ", Error: " + e.getMessage());
    }

    public static void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }

    public static Map<String, Double> getAverageResponseTimes() {
        Map<String, Double> averageResponseTimes = new HashMap<>();
        for (Map.Entry<String, List<Long>> entry : domainResponseTimes.entrySet()) {
            double averageTime = entry.getValue().stream().mapToLong(Long::longValue).average().orElse(0);
            averageResponseTimes.put(entry.getKey(), averageTime);
        }
        return averageResponseTimes;
    }

    public static Set<String> getNonStandardStatusDomains() {
        return nonStandardStatusDomains;
    }
}
