#include <math.h>

typedef struct {
    int x;
    int y;
} point;

double calculate_distance(point p1, point p2) {
    return sqrt(pow(p2.x - p1.x, 2) + pow(p2.y - p1.y, 2));
}

void compute_distances(double *distances, point **points, int num_points) {
    for (int i = 0; i < num_points; ++i) {
        for (int j = i + 1; j < num_points; ++j) {
            distances[i * num_points + j] = calculate_distance(points[i][0], points[j][0]);
        }
    }
}

void free_resources(double *doubles, char **chars, point ***points, int num_points) {
    for (int i = 0; i < num_points; ++i) {
        free((*points)[i]);
    }
    free(*points);
    free(chars);
    free(doubles);
}

int main() {
    int num_points = 5;
    double *doubles = malloc(num_points * sizeof(double));
    char **chars = malloc(num_points * sizeof(char *));
    point ***points = malloc(num_points * sizeof(point **));

    // Initialize arrays
    for (int i = 0; i < num_points; ++i) {
        chars[i] = malloc(10 * sizeof(char)); // Assuming max length of char sequence is 9
        points[i] = malloc(sizeof(point *));
        (*points)[i] = malloc(sizeof(point));
        (*points)[i]->x = i;
        (*points)[i]->y = i * 2;
    }

    double *distances = malloc(num_points * num_points * sizeof(double));

    compute_distances(distances, points, num_points);

    // Print distances
    for (int i = 0; i < num_points; ++i) {
        for (int j = i + 1; j < num_points; ++j) {
            printf("Distance between point %d and point %d: %f\n", i, j, distances[i * num_points + j]);
        }
    }

    free_resources(doubles, chars, points, num_points);

    return 0;
}
