typedef struct Node {
    int value;
    struct Node* next;
} Node;

typedef struct Record {
    long offset;
    int key;
    Node* values;
} Record;

Record* create_record(long offset, int key, int max_values) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    record->offset = offset;
    record->key = key;
    record->values = NULL;

    for (int i = 0; i < max_values; i++) {
        Node* node = (Node*)malloc(sizeof(Node));
        if (!node) {
            fprintf(stderr, "Memory allocation failed\n");
            free_record(record);
            return NULL;
        }
        node->value = rand() % 100; // Random value between 0 and 99
        node->next = record->values;
        record->values = node;
    }

    return record;
}

void free_record(Record* record) {
    Node* current = record->values;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    free(record);
}

int main() {
    srand(time(NULL)); // Seed for random number generation

    Record* records[10];
    for (int i = 0; i < 10; i++) {
        records[i] = create_record(i * 100, i, 5);
        if (!records[i]) {
            fprintf(stderr, "Failed to create record %d\n", i);
            return 1;
        }
    }

    for (int i = 0; i < 10; i++) {
        free_record(records[i]);
    }

    return 0;
}
