#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Node {
    int value;
    struct Node* next;
} Node;

typedef struct Record {
    long offset;
    int key;
    Node* values;
} Record;

Record** create_records(int num_records, int max_memory_threshold, int upper_bound) {
    if (num_records <= 0 || max_memory_threshold <= 0 || upper_bound <= 0) {
        return NULL;
    }

    Record** records = (Record**)malloc(num_records * sizeof(Record*));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_records; ++i) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            // Cleanup previously allocated resources
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records);
            return NULL;
        }

        records[i]->offset = rand() % max_memory_threshold;
        records[i]->key = rand() % upper_bound;

        Node* head = NULL;
        Node* tail = NULL;
        int total_size = 0;

        while (total_size < records[i]->offset) {
            Node* new_node = (Node*)malloc(sizeof(Node));
            if (!new_node) {
                fprintf(stderr, "Memory allocation failed\n");
                // Cleanup previously allocated resources
                for (int j = 0; j <= i; ++j) {
                    Node* current = records[j]->values;
                    while (current) {
                        Node* next = current->next;
                        free(current);
                        current = next;
                    }
                    free(records[j]);
                }
                free(records);
                return NULL;
            }

            new_node->value = rand() % upper_bound;
            new_node->next = NULL;

            if (!head) {
                head = tail = new_node;
            } else {
                tail->next = new_node;
                tail = new_node;
            }

            total_size += sizeof(Node);
        }

        records[i]->values = head;
    }

    return records;
}

void free_records(Record** records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        Node* current = records[i]->values;
        while (current) {
            Node* next = current->next;
            free(current);
            current = next;
        }
        free(records[i]);
    }
    free(records);
}

int main() {
    int num_records = 10;
    int max_memory_threshold = 1024;
    int upper_bound = 100;

    Record** records = create_records(num_records, max_memory_threshold, upper_bound);

    if (records) {
        // Use the records
        free_records(records, num_records);
    }

    return 0;
}
