#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_IDENTIFIER_LENGTH 256
#define MAX_MESSAGE_LENGTH 1024

typedef struct {
    float time_stamp;
    char* identifier;
    int status; // 0 for failure, 1 for success
} event;

typedef struct {
    float timestamp;
    char* identifier;
    char* message;
} log_entry;

int parse_config_file(const char* filename, float* success_threshold, char*** messages, int* num_messages) {
    FILE* file = fopen(filename, "r");
    if (!file) return -1; // File open failed

    *num_messages = 0;
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Skip comments and whitespace
        if (line[0] == '#' || isspace(line[0])) continue;

        (*num_messages)++;
    }
    fclose(file);

    *messages = (char**)malloc(*num_messages * sizeof(char*));
    if (!*messages) return -2; // Memory allocation failed

    file = fopen(filename, "r");
    int i = 0;
    while (fgets(line, sizeof(line), file)) {
        if (line[0] == '#' || isspace(line[0])) continue;

        (*messages)[i] = strdup(line);
        if (!(*messages)[i]) {
            for (int j = 0; j < i; j++) free((*messages)[j]);
            free(*messages);
            fclose(file);
            return -2; // Memory allocation failed
        }
        i++;
    }
    fclose(file);

    file = fopen(filename, "r");
    if (!file) {
        for (int j = 0; j < *num_messages; j++) free((*messages)[j]);
        free(*messages);
        return -1; // File open failed
    }

    i = 0;
    while (fgets(line, sizeof(line), file)) {
        if (line[0] == '#' || isspace(line[0])) continue;

        char* token = strtok(line, " ");
        *success_threshold = atof(token);

        token = strtok(NULL, "\n");
        (*messages)[i++] = strdup(token);
    }
    fclose(file);

    return 0; // Success
}

log_entry** initialize_log_entries(const char* config_file, float success_threshold, int* num_entries) {
    float threshold;
    char** messages;
    int num_messages;

    if (parse_config_file(config_file, &threshold, &messages, &num_messages) != 0) return NULL; // Parsing failed

    *num_entries = num_messages;
    log_entry** entries = (log_entry**)malloc(num_messages * sizeof(log_entry*));
    if (!entries) {
        for (int i = 0; i < num_messages; i++) free(messages[i]);
        free(messages);
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < num_messages; i++) {
        entries[i] = (log_entry*)malloc(sizeof(log_entry));
        if (!entries[i]) {
            for (int j = 0; j <= i; j++) free(entries[j]);
            free(entries);
            for (int j = 0; j < num_messages; j++) free(messages[j]);
            free(messages);
            return NULL; // Memory allocation failed
        }

        entries[i]->timestamp = threshold;
        entries[i]->identifier = strdup("default");
        if (!entries[i]->identifier) {
            free(entries[i]);
            for (int j = 0; j <= i; j++) free(entries[j]);
            free(entries);
            for (int j = 0; j < num_messages; j++) free(messages[j]);
            free(messages);
            return NULL; // Memory allocation failed
        }

        entries[i]->message = strdup(messages[i]);
        if (!entries[i]->message) {
            free(entries[i]->identifier);
            free(entries[i]);
            for (int j = 0; j <= i; j++) free(entries[j]);
            free(entries);
            for (int j = 0; j < num_messages; j++) free(messages[j]);
            free(messages);
            return NULL; // Memory allocation failed
        }

        entries[i]->status = atof(messages[i]) >= threshold;
    }

    for (int i = 0; i < num_messages; i++) free(messages[i]);
    free(messages);

    return entries;
}

void free_log_entries(log_entry** entries, int num_entries) {
    for (int i = 0; i < num_entries; i++) {
        free(entries[i]->identifier);
        free(entries[i]->message);
        free(entries[i]);
    }
    free(entries);
}
