#include <stdlib.h>
#include <stdint.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
    int *key_ref;
} Record;

Record* allocate_records(int num_records, int key_range_start, int key_range_end) {
    if (num_records <= 0 || key_range_start >= key_range_end) {
        return NULL;
    }

    size_t record_size = sizeof(Record);
    size_t key_size = sizeof(int);

    // Calculate total memory needed
    size_t total_memory = num_records * (record_size + key_size);

    // Allocate memory for the combined array
    Record *records = (Record *)aligned_alloc(alignof(long), total_memory);
    if (!records) {
        return NULL;
    }

    // Initialize keys and record references
    int *keys = (int *)(records + num_records);
    for (int i = 0; i < num_records; ++i) {
        records[i].offset = i * sizeof(Record);
        records[i].key = rand() % (key_range_end - key_range_start) + key_range_start;
        keys[i] = records[i].key;
        records[i].key_ref = &keys[i];
    }

    return records;
}

void free_records(Record *records, int num_records) {
    if (!records) {
        return;
    }
    // Free the combined memory block
    free(records);
}
