#include <stdlib.h>
#include <pthread.h>

typedef struct Value {
    double value;
    int ref_count;
    struct Value* next;
} Value;

typedef struct Node {
    int key;
    Value* values;
    pthread_mutex_t lock;
    struct Node* next;
} Node;

Node* create_node(int key) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (node == NULL) return NULL;
    node->key = key;
    node->values = NULL;
    pthread_mutex_init(&node->lock, NULL);
    node->next = NULL;
    return node;
}

void destroy_node(Node* node) {
    Value* value = node->values;
    while (value != NULL) {
        Value* next_value = value->next;
        free(value);
        value = next_value;
    }
    pthread_mutex_destroy(&node->lock);
    free(node);
}

Value* create_value(double value) {
    Value* val = (Value*)malloc(sizeof(Value));
    if (val == NULL) return NULL;
    val->value = value;
    val->ref_count = 1;
    val->next = NULL;
    return val;
}

void destroy_value(Value* value) {
    free(value);
}

void add_value_to_node(Node* node, double value) {
    pthread_mutex_lock(&node->lock);
    Value* new_val = create_value(value);
    if (new_val == NULL) {
        pthread_mutex_unlock(&node->lock);
        return;
    }
    new_val->next = node->values;
    node->values = new_val;
    pthread_mutex_unlock(&node->lock);
}

void update_values_for_node(Node* node, double* new_values, int count) {
    pthread_mutex_lock(&node->lock);
    Value* current = node->values;
    while (current != NULL) {
        current->ref_count--;
        if (current->ref_count == 0) {
            Value* next = current->next;
            destroy_value(current);
            current = next;
        } else {
            current = current->next;
        }
    }
    for (int i = 0; i < count; i++) {
        add_value_to_node(node, new_values[i]);
    }
    pthread_mutex_unlock(&node->lock);
}
