#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_NODES 1000

typedef struct Node {
    char* path;
    double value;
    size_t index;
    double* weight;
} Node;

Node* createNodes(char** paths, double baseWeightFactor, size_t initialIndex, size_t stepSize, int numNodes, int timeout) {
    Node* nodes = (Node*)aligned_alloc(64, numNodes * sizeof(Node));
    if (!nodes) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    double* weights = (double*)aligned_alloc(64, numNodes * sizeof(double));
    if (!weights) {
        fprintf(stderr, "Memory allocation failed\n");
        free(nodes);
        return NULL;
    }

    for (int i = 0; i < numNodes; ++i) {
        nodes[i].path = strdup(paths[i]);
        if (!nodes[i].path) {
            fprintf(stderr, "Memory allocation failed\n");
            for (int j = 0; j < i; ++j) {
                free(nodes[j].path);
            }
            free(weights);
            free(nodes);
            return NULL;
        }

        nodes[i].value = baseWeightFactor * strlen(paths[i]);
        nodes[i].index = initialIndex + i * stepSize;

        while (i > 0 && nodes[i].index == nodes[i - 1].index) {
            nodes[i].index += stepSize;
        }

        weights[i] = nodes[i].value * nodes[i].index;
        nodes[i].weight = &weights[i];
    }

    return nodes;
}

void updateNodeWeight(Node* node, double newWeightFactor) {
    if (node) {
        node->value *= newWeightFactor;
        *node->weight = node->value * node->index;
    }
}

void freeNodes(Node* nodes, int numNodes) {
    for (int i = 0; i < numNodes; ++i) {
        free(nodes[i].path);
    }
    free(nodes);
}
