void initialize_event_logs(EventLog** logs, int num_logs) {
    if (logs == NULL || num_logs <= 0) return;

    *logs = (EventLog*)aligned_alloc(alignof(EventLog), num_logs * sizeof(EventLog));
    if (*logs == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_logs; ++i) {
        size_t message_len = snprintf(NULL, 0, EVENT_MESSAGE_TEMPLATE, i) + 1;
        (*logs)[i].message = (char*)aligned_alloc(alignof(char), message_len);
        if ((*logs)[i].message == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        snprintf((*logs)[i].message, message_len, EVENT_MESSAGE_TEMPLATE, i);

        (*logs)[i].timestamp = time(NULL);
        (*logs)[i].log_level = i % 5; // Example log level
    }
}

void free_event_logs(EventLog* logs, int num_logs) {
    if (logs == NULL || num_logs <= 0) return;

    for (int i = 0; i < num_logs; ++i) {
        free(logs[i].message);
    }

    free(logs);
}

int main() {
    EventLog* event_logs;
    int num_logs = MAX_EVENT_LOGS;

    initialize_event_logs(&event_logs, num_logs);

    // Use the event logs...

    free_event_logs(event_logs, num_logs);

    return 0;
}
