#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct record {
    long id;
    int key;
    long *value;
} Record;

typedef struct summary {
    Record **records;
    int count;
} Summary;

Summary* create_summary() {
    Summary *s = (Summary*)malloc(sizeof(Summary));
    if (!s) return NULL;
    s->records = NULL;
    s->count = 0;
    return s;
}

Record* create_record(long id, int key, long value) {
    Record *r = (Record*)malloc(sizeof(Record));
    if (!r) return NULL;
    r->id = id;
    r->key = key;
    r->value = (long*)malloc(sizeof(long));
    if (!r->value) {
        free(r);
        return NULL;
    }
    *r->value = value;
    return r;
}

int add_record_to_summary(Summary *s, Record *r) {
    s->records = realloc(s->records, (s->count + 1) * sizeof(Record*));
    if (!s->records) return -1;
    s->records[s->count++] = r;
    return 0;
}

void print_summary(Summary *s) {
    for (int i = 0; i < s->count; i++) {
        printf("Record ID: %ld, Key: %d, Value: %ld\n", 
               s->records[i]->id, s->records[i]->key, *(s->records[i]->value));
    }
}

void free_record(Record *r) {
    if (r->value) free(r->value);
    free(r);
}

void free_summary(Summary *s) {
    for (int i = 0; i < s->count; i++) {
        free_record(s->records[i]);
    }
    free(s->records);
    free(s);
}
```

