    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys.\n");
        return 1;
    }

    Record* records = (Record*)malloc(arraySize * sizeof(Record));
    if (!records) {
        free(keys); // Clean up previously allocated resources
        fprintf(stderr, "Memory allocation failed for records.\n");
