// Define the record structure
typedef struct {
    int value;
} Record;

// Function to initialize memory and records
void* init_memory(int num_keys, int range_start, int range_end) {
    // Allocate memory for keys array
    int* keys = (int*)malloc(num_keys * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        return NULL;
    }

    // Allocate memory for records array
    Record* records = (Record*)malloc(num_keys * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        free(keys);
        return NULL;
    }

    // Initialize records with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_keys; i++) {
        keys[i] = rand() % (range_end - range_start + 1) + range_start;
        records[i].value = keys[i];
    }

    // Return a pointer to the combined structure
    return (void*)records;
}

// Helper function to find and print the largest integer
void find_and_print_largest(Record* records, int num_keys) {
    if (!records || num_keys <= 0) {
        fprintf(stderr, "Invalid input for finding largest number\n");
        return;
    }

    int max_value = records[0].value;
    for (int i = 1; i < num_keys; i++) {
        if (records[i].value > max_value) {
            max_value = records[i].value;
        }
    }

    printf("Largest integer: %d\n", max_value);
}

// Function to free allocated memory
void free_memory(void* ptr) {
    if (ptr) {
        free(ptr);
    }
}

int main() {
    // Set locale for internationalization
    setlocale(LC_ALL, "");

    // Example usage of the functions
    int num_keys = 10;
    int range_start = 1;
    int range_end = 100;

    void* records_ptr = init_memory(num_keys, range_start, range_end);
    if (records_ptr) {
        Record* records = (Record*)records_ptr;
        find_and_print_largest(records, num_keys);
        free_memory(records_ptr);
    }

    return 0;
}
