public:
    void manageMap(std::map<std::string, std::vector<int>>& sharedMap, const std::string& key, const std::string& operation) {
        if (operation == "insert") {
            insertOrAppend(sharedMap, key);
        } else if (operation == "append") {
            appendIfExists(sharedMap, key);
        }
    }

private:
    void insertOrAppend(std::map<std::string, std::vector<int>>& sharedMap, const std::string& key) {
        auto it = sharedMap.find(key);
        if (it == sharedMap.end()) {
            // Atomically insert the new key with an empty vector
            sharedMap[key] = {};
        }
    }

    void appendIfExists(std::map<std::string, std::vector<int>>& sharedMap, const std::string& key) {
        auto it = sharedMap.find(key);
        if (it != sharedMap.end()) {
