    if (size <= 0) return -1; // Assuming the array is not empty
    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

void initializeDataAndSemaphore(int size, int upperBound) {
    srand(time(NULL)); // Seed the random number generator

    long* offsetArray = (long*)malloc(size * sizeof(long));
    if (!offsetArray) {
        fprintf(stderr, "Memory allocation failed for offset array\n");
        return;
    }

    int* keyArray = (int*)malloc(size * sizeof(int));
    if (!keyArray) {
        free(offsetArray);
        fprintf(stderr, "Memory allocation failed for key array\n");
        return;
    }

    record* recordArray = (record*)malloc(size * sizeof(record));
    if (!recordArray) {
        free(offsetArray);
        free(keyArray);
        fprintf(stderr, "Memory allocation failed for record array\n");
        return;
    }

    int inputArray[size];
    printf("Enter %d integers:\n", size);
    for (int i = 0; i < size; i++) {
        scanf("%d", &inputArray[i]);
    }

    int largest = findLargest(inputArray, size);
    printf("The largest integer is: %d\n", largest);

    for (int i = 0; i < size; i++) {
        recordArray[i].value = rand() % (upperBound + 1);
    }

    // Free allocated memory
    free(offsetArray);
    free(keyArray);
    free(recordArray);
}

int main() {
    int size, upperBound;
    printf("Enter the size of the arrays: ");
    scanf("%d", &size);
    printf("Enter the upper bound for random numbers: ");
    scanf("%d", &upperBound);

