#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int key;
    long offset;
    struct Record *next;
} Record;

typedef struct RecordList {
    Record *head;
    pthread_mutex_t lock;
} RecordList;

RecordList* create_record_list() {
    RecordList *list = (RecordList*)malloc(sizeof(RecordList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void insert_record(RecordList *list, int key, long offset) {
    pthread_mutex_lock(&list->lock);
    Record *new_record = (Record*)malloc(sizeof(Record));
    new_record->key = key;
    new_record->offset = offset;
    new_record->next = list->head;
    list->head = new_record;
    pthread_mutex_unlock(&list->lock);
}

void delete_record(RecordList *list, int key) {
    pthread_mutex_lock(&list->lock);
    Record *current = list->head;
    Record *previous = NULL;

    while (current != NULL && current->key != key) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
    pthread_mutex_unlock(&list->lock);
}

void batch_insert_records(RecordList *list, int keys[], long offsets[], int size) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < size; i++) {
        Record *new_record = (Record*)malloc(sizeof(Record));
        new_record->key = keys[i];
        new_record->offset = offsets[i];
        new_record->next = list->head;
        list->head = new_record;
    }
    pthread_mutex_unlock(&list->lock);
}

void clear_records(RecordList *list) {
    pthread_mutex_lock(&list->lock);
    Record *current = list->head;
    while (current != NULL) {
        Record *temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
}

void destroy_record_list(RecordList *list) {
    clear_records(list);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
