#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int key;
    long offset;
    void* metadata;
    struct Record* next;
} Record;

typedef struct RecordManager {
    Record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} RecordManager;

RecordManager* create_record_manager(size_t initial_capacity) {
    RecordManager* manager = (RecordManager*)malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    manager->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->mutex, NULL);

    return manager;
}

void destroy_record_manager(RecordManager* manager) {
    for (size_t i = 0; i < manager->capacity; ++i) {
        Record* current = manager->records[i];
        while (current) {
            Record* next = current->next;
            free(current);
            current = next;
        }
    }

    free(manager->records);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

void insert_record(RecordManager* manager, int key, long offset, void* metadata) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->size >= manager->capacity) {
        // Handle capacity overflow
        Record** new_records = (Record**)realloc(manager->records, manager->capacity * 2 * sizeof(Record*));
        if (!new_records) {
            pthread_mutex_unlock(&manager->mutex);
            return;
        }
        manager->records = new_records;
        manager->capacity *= 2;
    }

    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    new_record->key = key;
    new_record->offset = offset;
    new_record->metadata = metadata;
    new_record->next = NULL;

    manager->records[key % manager->capacity] = new_record;
    ++manager->size;

    pthread_mutex_unlock(&manager->mutex);
}

void* get_record(RecordManager* manager, int key) {
    pthread_mutex_lock(&manager->mutex);

    Record* current = manager->records[key % manager->capacity];
    while (current) {
        if (current->key == key) {
            void* metadata = current->metadata;
            pthread_mutex_unlock(&manager->mutex);
            return metadata;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&manager->mutex);
    return NULL;
}

void batch_insert_records(RecordManager* manager, Record** records, size_t count) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < count; ++i) {
        if (manager->size >= manager->capacity) {
            // Handle capacity overflow
            Record** new_records = (Record**)realloc(manager->records, manager->capacity * 2 * sizeof(Record*));
            if (!new_records) {
                pthread_mutex_unlock(&manager->mutex);
                return;
            }
            manager->records = new_records;
            manager->capacity *= 2;
        }

        Record* record = records[i];
        manager->records[record->key % manager->capacity] = record;
        ++manager->size;
    }

    pthread_mutex_unlock(&manager->mutex);
}

void clear_records(RecordManager* manager) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->capacity; ++i) {
        Record* current = manager->records[i];
        while (current) {
            Record* next = current->next;
            free(current);
            current = next;
        }
        manager->records[i] = NULL;
    }

    manager->size = 0;

    pthread_mutex_unlock(&manager->mutex);
}
