double* double_array;
short* short_array;
Element** element_pointers;

int array_size = 0;
pthread_mutex_t mutex;

void initialize_memory() {
    pthread_mutex_init(&mutex, NULL);
    double_array = (double*)malloc(MAX_ELEMENTS * sizeof(double));
    short_array = (short*)malloc(MAX_ELEMENTS * sizeof(short));
    element_pointers = (Element**)malloc(MAX_ELEMENTS * sizeof(Element*));
}

void populate_structs(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        Element* element = (Element*)malloc(sizeof(Element));
        // Parse CSV line and populate element fields
        // Example: sscanf(line, "%f,%[^,],%zu", &element->value, element->name, &element->size);
        // Ensure size is non-zero for validation
        if (element->size == 0) {
            free(element);
            continue;
        }

        pthread_mutex_lock(&mutex);
        double_array[array_size] = element->value;
        short_array[array_size] = element->index;
        element_pointers[array_size++] = element;
        pthread_mutex_unlock(&mutex);
    }

    fclose(file);
}

void* thread_function(void* arg) {
    // Example thread function that accesses the shared data structures
    for (int i = 0; i < array_size; i++) {
        double value = double_array[i];
        short index = short_array[i];
        Element* element = element_pointers[index];

        // Perform operations on value and element
    }
    return NULL;
}

int main() {
    initialize_memory();
    populate_structs("data.csv");

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, thread_function, NULL);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up allocated memory
    for (int i = 0; i < array_size; i++) {
        free(element_pointers[i]);
    }
