#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct Record {
    int value;
    struct Record* next;
} Record;

typedef struct LinkedList {
    Record* head;
    Record* tail;
    size_t size;
    size_t max_size;
    pthread_mutex_t lock;
} LinkedList;

void initLinkedList(LinkedList* list, size_t max_size) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    list->max_size = max_size;
    pthread_mutex_init(&list->lock, NULL);
}

void freeLinkedList(LinkedList* list) {
    Record* current = list->head;
    while (current != NULL) {
        Record* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}

Record* createRecord(int value) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (record == NULL) {
        perror("Failed to allocate memory for record");
        exit(EXIT_FAILURE);
    }
    record->value = value;
    record->next = NULL;
    return record;
}

void insertRecord(LinkedList* list, int index, int value) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->max_size) {
        printf("Maximum size reached. Cannot insert new record.\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    Record* newRecord = createRecord(value);
    if (index == 0) {
        newRecord->next = list->head;
        list->head = newRecord;
        if (list->tail == NULL) {
            list->tail = newRecord;
        }
    } else if (index == list->size) {
        list->tail->next = newRecord;
        list->tail = newRecord;
    } else {
        Record* current = list->head;
        for (size_t i = 0; i < index - 1; ++i) {
            current = current->next;
        }
        newRecord->next = current->next;
        current->next = newRecord;
    }
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

int getRecord(LinkedList* list, size_t index) {
    pthread_mutex_lock(&list->lock);
    if (index >= list->size) {
        printf("Index out of bounds.\n");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    Record* current = list->head;
    for (size_t i = 0; i < index; ++i) {
        current = current->next;
    }
    int value = current->value;
    pthread_mutex_unlock(&list->lock);
    return value;
}

void logModification(LinkedList* list, const char* operation, size_t index, int oldValue, int newValue) {
    // Implement logging mechanism here
}
