typedef struct {
    float temperature;
    time_t timestamp;
    char location[100];
} Record;

int allocate_memory(int size, int **keys, Record **records, char ***logs) {
    *keys = (int *)malloc(size * sizeof(int));
    *records = (Record *)malloc(size * sizeof(Record));
    *logs = (char **)malloc(size * sizeof(char *));

    if (*keys == NULL || *records == NULL || *logs == NULL) {
        free(*keys);
        free(*records);
        free(*logs);
        return -1;
    }

    for (int i = 0; i < size; i++) {
        (*logs)[i] = (char *)malloc(256 * sizeof(char));
        if ((*logs)[i] == NULL) {
            for (int j = 0; j < i; j++) {
                free((*logs)[j]);
            }
            free(*keys);
            free(*records);
            free(*logs);
            return -1;
        }
    }

    return 0;
}

void initialize_data(int size, int *keys, Record *records, char **logs) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        keys[i] = rand() % 1000; // Example key generation
        records[i].temperature = ((float)rand() / RAND_MAX) * 100.0f; // Random temperature between 0 and 100
        records[i].timestamp = time(NULL);
        snprintf(records[i].location, sizeof(records[i].location), "Location %d", i);
    }
}

void calculate_average_temperature(int size, Record *records) {
    float sum = 0.0f;
    for (int i = 0; i < size; i++) {
        sum += records[i].temperature;
    }
    printf("Average Temperature: %.2f\n", sum / size);
}

void free_memory(int size, int *keys, Record *records, char **logs) {
    for (int i = 0; i < size; i++) {
        free(logs[i]);
    }
    free(keys);
    free(records);
    free(logs);
}

int main() {
    int size = 100;
    int *keys;
    Record *records;
    char **logs;

    if (allocate_memory(size, &keys, &records, &logs) != 0) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    initialize_data(size, keys, records, logs);
    calculate_average_temperature(size, records);

    free_memory(size, keys, records, logs);

    return 0;
}
