int initialize_records(DataStore* store, size_t num_records) {
    if (num_records == 0 || num_records > MAX_RECORDS) {
        fprintf(stderr, "Error: Invalid number of records.\n");
        return -1;
    }

    store->offsets = malloc(num_records * sizeof(int));
    store->keys = malloc(num_records * sizeof(int));
    store->records = malloc(num_records * sizeof(Record*));

    if (!store->offsets || !store->keys || !store->records) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        free(store->offsets);
        free(store->keys);
        free(store->records);
        return -1;
    }

    store->num_records = num_records;

    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        store->offsets[i] = rand();
        store->keys[i] = rand();
        store->records[i] = malloc(sizeof(Record));
        if (!store->records[i]) {
            fprintf(stderr, "Error: Memory allocation failed for record %zu.\n", i);
            for (size_t j = 0; j < i; ++j) {
                free(store->records[j]);
            }
            free(store->offsets);
            free(store->keys);
            free(store->records);
            return -1;
        }
        store->records[i]->value = rand() % num_records;
    }

    return 0;
}

void cleanup_records(DataStore* store) {
    for (size_t i = 0; i < store->num_records; ++i) {
        free(store->records[i]);
    }
    free(store->offsets);
    free(store->keys);
    free(store->records);
}
