#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_IDENTIFIER_LENGTH 100
#define MIN_PRIORITY 1
#define MAX_PRIORITY 5
#define MIN_FLOAT_VALUE 0.0f
#define MAX_FLOAT_VALUE 100.0f

typedef struct {
    char identifier[MAX_IDENTIFIER_LENGTH];
    int priority;
    float value;
} DataStruct;

DataStruct** allocate_and_initialize_array(int rows, int cols) {
    // Allocate memory for the array of pointers
    DataStruct** array = (DataStruct**)malloc(rows * sizeof(DataStruct*));
    if (!array) {
        perror("Failed to allocate memory for array of pointers");
        return NULL;
    }

    // Initialize each row
    for (int i = 0; i < rows; ++i) {
        array[i] = (DataStruct*)malloc(cols * sizeof(DataStruct));
        if (!array[i]) {
            perror("Failed to allocate memory for row");
            // Clean up previously allocated resources
            for (int j = 0; j < i; ++j) {
                free(array[j]);
            }
            free(array);
            return NULL;
        }

        // Initialize each element in the row
        for (int j = 0; j < cols; ++j) {
            snprintf(array[i][j].identifier, MAX_IDENTIFIER_LENGTH, "ID_%d_%ld_%d", i * cols + j, time(NULL), rand());
            array[i][j].priority = MIN_PRIORITY + rand() % (MAX_PRIORITY - MIN_PRIORITY + 1);
            array[i][j].value = MIN_FLOAT_VALUE + ((float)rand() / RAND_MAX) * (MAX_FLOAT_VALUE - MIN_FLOAT_VALUE);
        }
    }

    return array;
}

void free_array(DataStruct** array, int rows) {
    for (int i = 0; i < rows; ++i) {
        free(array[i]);
    }
    free(array);
}

int main() {
    srand(time(NULL));

    int rows = 5;
    int cols = 3;

    DataStruct** array = allocate_and_initialize_array(rows, cols);
    if (array) {
        // Process the data
        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < cols; ++j) {
                printf("Identifier: %s, Priority: %d, Value: %.2f\n", array[i][j].identifier, array[i][j].priority, array[i][j].value);
            }
        }

