['```rust
use tokio_tungstenite::{connect_async, tungstenite::protocol::Message};
use url::Url;
use std::time::Duration;
use rand::Rng;

#[derive(Debug)]
enum ServerEndpoint {
    Static(Url),
    Dynamic(Vec<Url>),
}

impl ServerEndpoint {
    fn next_url(&self) -> Url {
        match self {
            ServerEndpoint::Static(url) => url.clone(),
            ServerEndpoint::Dynamic(urls) => urls[rand::thread_rng().gen_range(0..urls.len())].clone(),
        }
    }
}

struct WebSocketClient {
    endpoint: ServerEndpoint,
    headers: Vec<(String, String)>,
    reconnect_interval: Duration,
    max_reconnect_attempts: u32,
    monitoring_service: Box<dyn MonitoringService>,
}

impl WebSocketClient {
    fn new(endpoint: ServerEndpoint, headers: Vec<(String, String)>, reconnect_interval: Duration, max_reconnect_attempts: u32, monitoring_service: Box<dyn MonitoringService>) -> Self {
        WebSocketClient {
            endpoint,
            headers,
            reconnect_interval,
            max_reconnect_attempts,
            monitoring_service,
        }
    }

    async fn connect(&self) -> Result<tokio_tungstenite::WebSocketStream<tokio_tungstenite::TlsStream<tokio::net::TcpStream>>, Box<dyn std::error::Error>> {
        let url = self.endpoint.next_url();
        let (mut ws_stream, _) = connect_async(url).await?;
        for (key, value) in &self.headers {
            ws_stream.send(Message::Text(format!("{}: {}", key, value))).await?;
        }
        Ok(ws_stream)
    }

    async fn run(&mut self) -> Result<(), Box<dyn std::error::Error>> {
        let mut reconnect_attempts = 0;
        loop {
            if reconnect_attempts >= self.max_reconnect_attempts {
                return Err("Max reconnect attempts reached".into());
            }
            match self.connect().await {
                Ok(mut ws_stream) => {
                    while let Some(msg) = ws_stream.next().await {
                        match msg {
                            Ok(Message::Text(text)) => {
                                self.monitoring_service.log_message(&text);
                                // Process message
                            },
                            Err(e) => {
                                self.monitoring_service.log_error(&e.to_string());
                                break;
                            }
                        }
                    }
                },
                Err(e) => {
                    self.monitoring_service.log_error(&e.to_string());
                    tokio::time::sleep(self.reconnect_interval).await;
                    reconnect_attempts += 1;
                }
            }
        }
    }
}

trait MonitoringService {
    fn log_message(&self, message: &str);
    fn log_error(&self, error: &str);
}

struct ConsoleMonitoringService;

impl MonitoringService for ConsoleMonitoringService {
    fn log_message(&self, message: &str) {
        println!("Message: {}", message);
    }

    fn log_error(&self, error: &str) {
        eprintln!("Error: {}", error);
    }
}
```']

