#define MAX_PRIORITY 5
#define MIN_FLOAT_VALUE 0.0f
#define MAX_FLOAT_VALUE 100.0f

typedef struct {
    char identifier[20];
    int priority;
    float value;
} DataStruct;

DataStruct** createAndInitializeArray(int rows, int cols) {
    DataStruct** array = (DataStruct**)malloc(rows * sizeof(DataStruct*));
    if (!array) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < rows; ++i) {
        array[i] = (DataStruct*)malloc(cols * sizeof(DataStruct));
        if (!array[i]) {
            perror("Memory allocation failed");
            // Clean up previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(array[j]);
            }
            free(array);
            return NULL;
        }

        for (int j = 0; j < cols; ++j) {
            snprintf(array[i][j].identifier, sizeof(array[i][j].identifier), "ID_%d_%ld", i * cols + j, time(NULL));
            array[i][j].priority = rand() % MAX_PRIORITY;
            array[i][j].value = (float)(rand()) / RAND_MAX * (MAX_FLOAT_VALUE - MIN_FLOAT_VALUE) + MIN_FLOAT_VALUE;
        }
    }

    return array;
}

void freeArray(DataStruct** array, int rows) {
    for (int i = 0; i < rows; ++i) {
        free(array[i]);
    }
    free(array);
}

int main() {
    int rows = 3;
    int cols = 4;

    DataStruct** array = createAndInitializeArray(rows, cols);
    if (array) {
        // Use the array
        freeArray(array, rows);
    }

    return 0;
}
