#include <stdio.h>
#include <stdlib.h>

// Define the struct for the linked list node
typedef struct Node {
    int value;
    struct Node* next;
} Node;

// Define the struct for the record
typedef struct Record {
    long offset;
    int key;
    Node* data;
    struct Record* next;
} Record;

// Define the struct for the event
typedef struct Event {
    time_t timestamp;
    int type;
    struct Event* next;
} Event;

// Function to create a new node
Node* create_node(int value) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_node->value = value;
    new_node->next = NULL;
    return new_node;
}

// Function to create a new record
Record* create_record(long offset, int key) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (new_record == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_record->offset = offset;
    new_record->key = key;
    new_record->data = NULL;
    new_record->next = NULL;
    return new_record;
}

// Function to create a new event
Event* create_event(time_t timestamp, int type) {
    Event* new_event = (Event*)malloc(sizeof(Event));
    if (new_event == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_event->timestamp = timestamp;
    new_event->type = type;
    new_event->next = NULL;
    return new_event;
}

// Function to insert a value into the record's data linked list
void insert_value(Record* record, int value) {
    Node* new_node = create_node(value);
    if (record->data == NULL) {
        record->data = new_node;
    } else {
        Node* current = record->data;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

// Function to remove the oldest event from the list if it exceeds a specified capacity
void remove_oldest_event(Event** head, int max_capacity) {
    if (*head == NULL) return;

    Event* current = *head;
    Event* previous = NULL;

    while (current != NULL && current->next != NULL) {
        previous = current;
        current = current->next;
    }

    if (previous != NULL) {
        previous->next = NULL;
        free(current);
    }
}

// Python function to process the linked list by iterating over it and applying a filtering condition
void filter_events(Event* head, int threshold) {
    Event* current = head;

    while (current != NULL) {
        if (current->type <= threshold) {
            // Remove the event from the list
            Event* temp = current;
            current = current->next;
            free(temp);
        } else {
            current = current->next;
        }
    }
}
```

This code provides a basic structure for managing dynamic collections of records and events in C. It includes functions to create nodes, records, and events, as well as functions to insert values into records and remove the oldest event from a list if it exceeds a specified capacity. The Python function `filter_events` is also provided to process the linked list by iterating over it and applying a filtering condition based on the event type.']

