#include <time.h>

typedef struct {
    int* values;
    char** buffers;
} RecordSet;

RecordSet* allocate_records(int num_records, int value_range_start, int value_range_end, unsigned int seed, int enable_logging) {
    RecordSet* record_set = (RecordSet*)malloc(sizeof(RecordSet));
    if (!record_set) {
        return NULL; // Memory allocation failed
    }

    record_set->values = (int*)calloc(num_records, sizeof(int));
    if (!record_set->values) {
        free(record_set);
        return NULL; // Memory allocation failed
    }

    record_set->buffers = (char**)malloc(num_records * sizeof(char*));
    if (!record_set->buffers) {
        free(record_set->values);
        free(record_set);
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < num_records; ++i) {
        record_set->buffers[i] = (char*)malloc(128 * sizeof(char));
        if (!record_set->buffers[i]) {
            for (int j = 0; j < i; ++j) {
                free(record_set->buffers[j]);
            }
            free(record_set->values);
            free(record_set->buffers);
            free(record_set);
            return NULL; // Memory allocation failed
        }

        if (enable_logging) {
            printf("Allocating buffer for record %d\n", i);
        }

        // Initialize integer value with random number within the specified range
        record_set->values[i] = rand_r(&seed) % (value_range_end - value_range_start + 1) + value_range_start;
        if (enable_logging) {
            printf("Assigned random value %d to record %d\n", record_set->values[i], i);
        }

        // Initialize character buffer with a unique ASCII string
        snprintf(record_set->buffers[i], 128, "Record %d: %03d", i, record_set->values[i]);
        if (enable_logging) {
            printf("Generated string for record %d: %s\n", i, record_set->buffers[i]);
        }
    }

    // Verification mechanism
    for (int i = 0; i < num_records; ++i) {
        if (record_set->values[i] < value_range_start || record_set->values[i] > value_range_end) {
            printf("Verification failed: Invalid integer value %d in record %d\n", record_set->values[i], i);
            // Handle verification failure
        }
    }

    if (enable_logging) {
        printf("Memory allocation and initialization completed successfully\n");
    }

    return record_set;
}
