#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 10000

typedef struct {
    long offset;
    int key;
    char *str;
    long long_value;
    int int_value;
} Record;

Record records[MAX_RECORDS];
int record_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* init_records(void* arg) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i].offset = rand();
        records[i].key = rand() % 100;
        records[i].str = malloc(256 * sizeof(char));
        sprintf(records[i].str, "file%d.txt", i);
        records[i].long_value = rand();
        records[i].int_value = rand() % 100;
    }
    record_count = MAX_RECORDS;
    pthread_mutex_unlock(&lock);
    return NULL;
}

void* resize_records(void* arg) {
    int new_size = *(int*)arg;
    if (new_size > MAX_RECORDS) {
        Record *new_records = realloc(records, new_size * sizeof(Record));
        if (new_records == NULL) {
            perror("Failed to resize records");
            return NULL;
        }
        records = new_records;
        for (int i = MAX_RECORDS; i < new_size; i++) {
            records[i].offset = rand();
            records[i].key = rand() % 100;
            records[i].str = malloc(256 * sizeof(char));
            sprintf(records[i].str, "file%d.txt", i);
            records[i].long_value = rand();
            records[i].int_value = rand() % 100;
        }
        record_count = new_size;
    }
    return NULL;
}
