from flask import Flask, request, jsonify
import jsonschema
from jsonschema import validate

app = Flask(__name__)

# Define a sample schema for validation
resource_schema = {
    "type": "object",
    "properties": {
        "id": {"type": "integer"},
        "name": {"type": "string"},
        "details": {
            "type": "object",
            "properties": {
                "description": {"type": "string"}
            },
            "required": ["description"]
        }
    },
    "required": ["id", "name", "details"]
}

# Sample data store
data_store = {}

@app.route('/resource/<int:resource_id>', methods=['PUT'])
def update_resource(resource_id):
    try:
        # Validate incoming request body against schema
        validate(instance=request.json, schema=resource_schema)

        # Update resource in data store
        if resource_id in data_store:
            data_store[resource_id] = request.json
            return jsonify({"message": "Resource updated successfully"}), 200
        else:
            return jsonify({"error": "Resource not found"}), 404
    except jsonschema.exceptions.ValidationError as e:
        return jsonify({"error": "Validation error", "details": str(e)}), 400

@app.route('/resource/<int:resource_id>', methods=['DELETE'])
def delete_resource(resource_id):
    try:
        if resource_id in data_store:
            # Handle related resources (e.g., archiving, marking as inactive)
            # For simplicity, we'll just remove the resource
            del data_store[resource_id]

            return jsonify({"message": "Resource deleted successfully", "affected_resources": {"archived": [], "deleted": []}}), 200
        else:
            return jsonify({"error": "Resource not found"}), 404
    except Exception as e:
        return jsonify({"error": "Failed to delete resource", "details": str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True)
