        if (!validateMemoryAllocation(records[i]) || !validateMemoryAllocation(nfapiStructs[i])) {
            logError("Failed to allocate memory for records or NFAPI structures");
            free(keys);
            for (int j = 0; j < i; j++) {
                free(records[j]);
                free(nfapiStructs[j]);
            }
            free(records);
            free(nfapiStructs);
            return 1;
        }

        records[i]->value = rand() % 1000;
        nfapiStructs[i]->value = rand() % 1000;
    }

    findAndPrintLargest(keys, size);

    for (int i = 0; i < size; i++) {
        free(records[i]);
        free(nfapiStructs[i]);
    }
    free(keys);
    free(records);
    free(nfapiStructs);

    return 0;
}

void findAndPrintLargest(int *keys, int size) {
    int largest = keys[0];
    for (int i = 1; i < size; i++) {
        if (keys[i] > largest) {
            largest = keys[i];
        }
    }
    printf("The largest number is: %d\n", largest);
}

int validateMemoryAllocation(void *ptr) {
    return ptr != NULL;
}

void logError(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}
