#define MAX_CONTACT_LENGTH 100

typedef struct UserProfile {
    int userID;
    char name[50];
    char email[100];
    char contact[MAX_CONTACT_LENGTH];
    char preferences[256];
    int membershipStatus;
} UserProfile;

typedef struct UserDataset {
    UserProfile *profiles;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} UserDataset;

void initUserDataset(UserDataset *dataset, size_t initialCapacity) {
    dataset->profiles = (UserProfile *)malloc(initialCapacity * sizeof(UserProfile));
    dataset->count = 0;
    dataset->capacity = initialCapacity;
    pthread_mutex_init(&dataset->lock, NULL);
}

void addUserProfile(UserDataset *dataset, int userID, const char *name, const char *email, const char *prefix, const char *suffix) {
    pthread_mutex_lock(&dataset->lock);
    if (dataset->count >= dataset->capacity) {
        dataset->profiles = realloc(dataset->profiles, dataset->capacity * 2 * sizeof(UserProfile));
        dataset->capacity *= 2;
    }
    UserProfile *profile = &dataset->profiles[dataset->count++];
    profile->userID = userID;
    strncpy(profile->name, name, sizeof(profile->name) - 1);
    strncpy(profile->email, email, sizeof(profile->email) - 1);
    snprintf(profile->contact, MAX_CONTACT_LENGTH, "%s%s", prefix, suffix);
    memset(profile->preferences, 0, sizeof(profile->preferences));
    profile->membershipStatus = 0;
    pthread_mutex_unlock(&dataset->lock);
}

void freeUserDataset(UserDataset *dataset) {
    pthread_mutex_lock(&dataset->lock);
    free(dataset->profiles);
    dataset->profiles = NULL;
    dataset->count = 0;
    dataset->capacity = 0;
    pthread_mutex_destroy(&dataset->lock);
}

int resolveDNS(const char *hostname, u_char *ipAddress) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        memcpy(ipAddress, &(ipv4->sin_addr), sizeof(u_char) * 4);
        freeaddrinfo(res);
        return 0;
    }

    freeaddrinfo(res);
    return -1;
}

