#define MAX_IDENTIFIER_LENGTH 10
#define MAX_RANDOM_NUMBER 1000

typedef enum {
    STATUS_OK,
    STATUS_ERROR
} status;

typedef struct node {
    long value;
    struct node* next;
} Node;

typedef union {
    double d;
    char c[MAX_IDENTIFIER_LENGTH];
    Node* n;
    int i;
    status s;
} DataUnion;

typedef struct {
    DataUnion data;
    size_t count;
} FlexibleData;

FlexibleData* create_flexible_data(size_t N) {
    FlexibleData* fd = (FlexibleData*)malloc(N * sizeof(FlexibleData));
    if (!fd) return NULL;
    for (size_t i = 0; i < N; ++i) {
        fd[i].count = 0;
    }
    return fd;
}

void free_flexible_data(FlexibleData* fd, size_t N) {
    for (size_t i = 0; i < N; ++i) {
        // Free any dynamically allocated memory within each element
        if (fd[i].data.n) {
            Node* current = fd[i].data.n;
            while (current) {
                Node* next = current->next;
                free(current);
                current = next;
            }
        }
    }
    free(fd);
}

void initialize_char(FlexibleData* fd, size_t index, const char* identifier) {
    if (fd[index].count >= MAX_IDENTIFIER_LENGTH) return;
    snprintf(fd[index].data.c, MAX_IDENTIFIER_LENGTH, "%s%d", identifier, rand() % MAX_RANDOM_NUMBER);
    ++fd[index].count;
}

void initialize_node(FlexibleData* fd, size_t index, long value) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return;
    newNode->value = value;
    newNode->next = NULL;

    if (fd[index].data.n) {
        Node* current = fd[index].data.n;
        while (current->next) {
            current = current->next;
        }
        current->next = newNode;
    } else {
        fd[index].data.n = newNode;
    }

    ++fd[index].count;
}

// Add similar functions for double, int, and status types

int main() {
    srand(time(NULL));
    FlexibleData* data = create_flexible_data(5);
    if (!data) return 1;

    initialize_char(data, 0, "char_");
    initialize_node(data, 1, 42);

    // Initialize other types similarly

    free_flexible_data(data, 5);
    return 0;
}
