// Function to allocate memory for an array of dataItems
dataItem** createDataItemList(int count) {
    dataItem** list = (dataItem**)malloc(count * sizeof(dataItem*));
    if (!list) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < count; ++i) {
        list[i] = createDataItem("default", i); // Default string and ID
        if (!list[i]) {
            // Free previously allocated items on failure
            for (int j = 0; j < i; ++j) {
                free(list[j]->str);
                free(list[j]);
            }
            free(list);
            fprintf(stderr, "Failed to allocate dataItem at index %d\n", i);
            return NULL;
