    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} entry_array;

entry_array* create_entry_array(size_t initial_capacity) {
    entry_array *array = (entry_array*)malloc(sizeof(entry_array));
    array->entries = (entry*)calloc(initial_capacity, sizeof(entry));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroy_entry_array(entry_array *array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->entries[i].str);
    }
    free(array->entries);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

void resize_entry_array(entry_array *array, size_t new_capacity) {
    entry *new_entries = (entry*)realloc(array->entries, new_capacity * sizeof(entry));
    if (new_entries == NULL) {
        // Handle allocation failure
        return;
    }
    array->entries = new_entries;
    array->capacity = new_capacity;
}

void add_entry(entry_array *array, double value, const char *str) {
    pthread_mutex_lock(&array->lock);
    if (array->size >= array->capacity) {
        resize_entry_array(array, array->capacity * 2);
    }
    entry *new_entry = &array->entries[array->size++];
    new_entry->value = value;
    new_entry->str = strdup(str); // Ensure null-termination
    pthread_mutex_unlock(&array->lock);
}

void sort_entry_array(entry_array *array) {
    qsort(array->entries, array->size, sizeof(entry), [](const void *a, const void *b) {
        return ((entry*)a)->value - ((entry*)b)->value;
    });
}

