typedef struct {
    int key;
    int value;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!array->records) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    if (array) {
        pthread_mutex_lock(&array->mutex);
        free(array->records);
        pthread_mutex_unlock(&array->mutex);
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}

int add_record(DynamicArray* array, int key, int min_value, int max_value) {
    if (!array || key < 0 || min_value > max_value) return -1;

    pthread_mutex_lock(&array->mutex);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        Record* new_records = (Record*)realloc(array->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->records = new_records;
        array->capacity = new_capacity;
    }

    array->records[array->size].key = key;
    array->records[array->size].value = rand() % (max_value - min_value + 1) + min_value;
    array->size++;

    pthread_mutex_unlock(&array->mutex);
    return 0;
}

void* garbage_collection(void* arg) {
    DynamicArray* array = (DynamicArray*)arg;

    while (1) {
        sleep(60); // Perform GC every minute

        pthread_mutex_lock(&array->mutex);

        for (size_t i = 0; i < array->size; ++i) {
            if (array->records[i].key == -1) { // Assuming -1 is a marker for unused records
                memmove(&array->records[i], &array->records[i + 1], (array->size - i - 1) * sizeof(Record));
                array->size--;
                i--; // Adjust index after removal
            }
        }

        pthread_mutex_unlock(&array->mutex);
    }

    return NULL;
}

int main() {
    srand(time(NULL));

    DynamicArray* array = create_dynamic_array(100);
    if (!array) {
        fprintf(stderr, "Failed to create dynamic array\n");
        return 1;
    }

    pthread_t gc_thread;
    pthread_create(&gc_thread, NULL, garbage_collection, array);

    // Simulate adding records
    for (int i = 0; i < 200; ++i) {
        add_record(array, i, 1, 100);
    }

    // Cleanup
    destroy_dynamic_array(array);
    pthread_join(gc_thread, NULL);

    return 0;
}
