typedef struct {
    char* name;
    int priority;
    struct timeval start_time;
} task;

typedef struct {
    int completed;
} log_entry;

task* allocate_tasks(int num_tasks, int priority_range, int* successful_allocations) {
    task* tasks = (task*)malloc(num_tasks * sizeof(task));
    if (tasks == NULL) {
        *successful_allocations = 0;
        return NULL;
    }

    for (int i = 0; i < num_tasks; i++) {
        tasks[i].name = (char*)malloc(256 * sizeof(char)); // Assuming names are up to 255 characters
        if (tasks[i].name == NULL) {
            *successful_allocations = i;
            for (int j = 0; j < i; j++) {
                free(tasks[j].name);
            }
            free(tasks);
            return NULL;
        }

        tasks[i].priority = rand() % priority_range + 1;
        gettimeofday(&tasks[i].start_time, NULL);
    }

    *successful_allocations = num_tasks;
    return tasks;
}

log_entry* allocate_logs(int num_tasks) {
    log_entry* logs = (log_entry*)malloc(num_tasks * sizeof(log_entry));
    if (logs == NULL) {
        return NULL;
    }

    for (int i = 0; i < num_tasks; i++) {
        logs[i].completed = 0;
    }

    return logs;
}

void free_task_memory(task* tasks, int num_tasks) {
    for (int i = 0; i < num_tasks; i++) {
        free(tasks[i].name);
    }
    free(tasks);
}

void free_log_memory(log_entry* logs, int num_tasks) {
    free(logs);
}
