#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 256

typedef struct {
    double value;
    char* name;
    int count;
} item;

double calculate_average(item* items, int count) {
    double sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += items[i].value;
    }
    return sum / count;
}

void free_items(item* items, int count) {
    for (int i = 0; i < count; i++) {
        free(items[i].name);
    }
    free(items);
}

item* read_data(const char* file_path, int* count) {
    FILE* file = fopen(file_path, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    item* items = NULL;
    *count = 0;

    while (1) {
        char line[MAX_LINE_LENGTH];
        if (fgets(line, sizeof(line), file) == NULL) {
            break;
        }
        (*count)++;
        items = realloc(items, (*count) * sizeof(item));
        if (!items) {
            perror("Failed to allocate memory");
            free_items(items, *count - 1);
            fclose(file);
            return NULL;
        }

        item* new_item = &items[*count - 1];
        new_item->name = malloc(MAX_LINE_LENGTH);
        if (!new_item->name) {
            perror("Failed to allocate memory for name");
            free_items(items, *count - 1);
            fclose(file);
            return NULL;
        }

        sscanf(line, "%lf %s %d", &new_item->value, new_item->name, &new_item->count);
    }

    fclose(file);
    return items;
}

int main() {
    const char* file_path = "data.txt";
    int count;
    item* items = read_data(file_path, &count);

    if (items) {
        double average = calculate_average(items, count);
        printf("Average: %f\n", average);
        free_items(items, count);
    }

    return 0;
}
