    if (!file) {
        perror("Failed to open log file");
        return;
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    int record_count = file_size / sizeof(sensor_data);
    sensor_data* records = (sensor_data*)malloc(record_count * sizeof(sensor_data));
    if (!records) {
        perror("Failed to allocate memory for records");
        fclose(file);
        return;
    }

    float* averages = (float*)malloc((record_count - window_size + 1) * sizeof(float));
    if (!averages) {
        perror("Failed to allocate memory for averages");
        free(records);
        fclose(file);
        return;
    }

    size_t bytes_read = fread(records, sizeof(sensor_data), record_count, file);
    if (bytes_read != record_count) {
        fprintf(stderr, "Error reading log file: %zu records read instead of %d\n", bytes_read, record_count);
        free(averages);
        free(records);
        fclose(file);
        return;
    }

    for (int i = 0; i <= record_count - window_size; i++) {
        averages[i] = calculate_moving_average(&records[i].value, window_size, window_size);
    }

    // Process the averages as needed

    free(averages);
    free(records);
    fclose(file);
}
