#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 256

typedef enum {
    CATEGORY_A,
    CATEGORY_B,
    NUM_CATEGORIES
} category_t;

typedef struct {
    double value;
    char* name;
    int id;
    category_t cat;
} item_t;

item_t* read_data(const char* file_path, size_t* num_items) {
    FILE* file = fopen(file_path, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    // Estimate initial number of items
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    *num_items = file_size / MAX_LINE_LENGTH; // Simplified estimation

    item_t* items = (item_t*)malloc(*num_items * sizeof(item_t));
    if (!items) {
        perror("Failed to allocate memory");
        fclose(file);
        return NULL;
    }

    size_t i = 0;
    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, file)) {
        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\n') continue;

        items[i].value = atof(strtok(line, ","));
        items[i].name = strdup(strtok(NULL, ","));
        items[i].id = atoi(strtok(NULL, ","));
        items[i].cat = (category_t)atoi(strtok(NULL, ","));

        i++;
    }

    fclose(file);
    *num_items = i;
    return items;
}

void calculate_averages(item_t* items, size_t num_items, double averages[NUM_CATEGORIES]) {
    for (size_t i = 0; i < NUM_CATEGORIES; i++) {
        averages[i] = 0.0;
    }

    for (size_t i = 0; i < num_items; i++) {
        averages[items[i].cat] += items[i].value;
    }

    for (size_t i = 0; i < NUM_CATEGORIES; i++) {
        if (i > 0) averages[i] /= num_items / NUM_CATEGORIES;
    }
}

void free_data(item_t* items, size_t num_items) {
    for (size_t i = 0; i < num_items; i++) {
        free(items[i].name);
    }
    free(items);
}

int main() {
    const char* file_path = "data.txt";
    size_t num_items;
    item_t* items = read_data(file_path, &num_items);

    if (items) {
        double averages[NUM_CATEGORIES];
        calculate_averages(items, num_items, averages);

        for (size_t i = 0; i < NUM_CATEGORIES; i++) {
            printf("Average for category %d: %.2f\n", i, averages[i]);
        }

        free_data(items, num_items);
    }

    return 0;
}
