typedef struct {
    void **data;
    size_t capacity;
    size_t count;
} FlexibleDataStructure;

FlexibleDataStructure* create_flexible_data_structure(size_t initial_capacity) {
    FlexibleDataStructure *fds = (FlexibleDataStructure *)malloc(sizeof(FlexibleDataStructure));
    if (!fds) return NULL; // Handle memory allocation failure
    fds->data = (void **)calloc(initial_capacity, sizeof(void *));
    if (!fds->data) {
        free(fds);
        return NULL; // Handle memory allocation failure
    }
    fds->capacity = initial_capacity;
    fds->count = 0;
    return fds;
}

void destroy_flexible_data_structure(FlexibleDataStructure *fds) {
    for (size_t i = 0; i < fds->count; ++i) {
        free(fds->data[i]);
    }
    free(fds->data);
    free(fds);
}

int insert_data(FlexibleDataStructure *fds, DataType type, void *value) {
    if (fds->count >= fds->capacity) {
        size_t new_capacity = fds->capacity ? fds->capacity * 2 : 1;
        void **new_data = (void **)realloc(fds->data, new_capacity * sizeof(void *));
        if (!new_data) return -1; // Handle memory allocation failure
        fds->data = new_data;
        fds->capacity = new_capacity;
    }
    fds->data[fds->count++] = value;
    return 0;
}

void* allocate_char_array(const char *label, size_t max_length) {
    size_t label_len = strlen(label);
    size_t random_len = max_length - label_len - 1;
    if (random_len < 1) return NULL; // Handle invalid input
    char *char_array = (char *)malloc(max_length * sizeof(char));
    if (!char_array) return NULL; // Handle memory allocation failure
    snprintf(char_array, max_length, "%s", label);
    for (size_t i = label_len; i < max_length - 1; ++i) {
        char_array[i] = 'A' + rand() % 26;
    }
    char_array[max_length - 1] = '\0';
    return char_array;
}

Item* insert_item(Item *list, int value) {
    Item *new_item = (Item *)malloc(sizeof(Item));
    if (!new_item) return NULL; // Handle memory allocation failure
    new_item->value = value;
    new_item->timestamp = time(NULL);
    new_item->next = list;
    return new_item;
}
