#include <time.h>

#define MAX_RECORDS 1000

typedef struct {
    int key;
} IntegerRecord;

typedef struct {
    int value;
    char* stringField;
    unsigned char* binaryData;
} CustomRecord;

int findLargestInteger(int* array, int size) {
    if (size <= 0) return -1;
    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

void initializeRecords(CustomRecord* records, int count, int upperLimit, const char* stringField, const unsigned char* binaryData) {
    for (int i = 0; i < count; i++) {
        records[i].value = rand() % (upperLimit + 1);
        if (stringField != NULL) {
            records[i].stringField = strdup(stringField);
        } else {
            records[i].stringField = strdup("Default String");
        }
        if (binaryData != NULL) {
            records[i].binaryData = malloc(sizeof(unsigned char) * strlen(binaryData));
            memcpy(records[i].binaryData, binaryData, sizeof(unsigned char) * strlen(binaryData));
        } else {
            records[i].binaryData = malloc(sizeof(unsigned char) * 10);
            memset(records[i].binaryData, 0, sizeof(unsigned char) * 10);
        }
    }
}

void freeRecords(CustomRecord* records, int count) {
    for (int i = 0; i < count; i++) {
        free(records[i].stringField);
        free(records[i].binaryData);
    }
}

int main() {
    srand(time(NULL));
    int array[MAX_RECORDS];
    CustomRecord records[MAX_RECORDS];

    // Read integers from standard input
    int size;
    printf("Enter the number of integers: ");
    scanf("%d", &size);
    for (int i = 0; i < size; i++) {
        printf("Enter integer %d: ", i + 1);
        scanf("%d", &array[i]);
    }

    // Find and print the largest integer
    int largest = findLargestInteger(array, size);
    if (largest != -1) {
        printf("The largest integer is: %d\n", largest);
    } else {
        printf("No integers entered.\n");
    }

    // Initialize records with random values and default strings/binary data
    initializeRecords(records, MAX_RECORDS, 100, NULL, (unsigned char*)"Default Binary Data");

