    int largest = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }
    return largest;
}

void initialize_records(record* records, int size, int upper_bound) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        records[i].value = rand() % (upper_bound + 1);
    }
}

void free_memory(int* keys, record* records, int size) {
    free(keys);
    free(records);
}

int main() {
    int size;
    printf("Enter the number of elements: ");
    scanf("%d", &size);

    int* keys = (int*)malloc(size * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for keys\n");
        return 1;
    }

    record* records = (record*)malloc(size * sizeof(record));
    if (!records) {
        free_memory(keys, NULL, size);
        fprintf(stderr, "Memory allocation failed for records\n");
        return 1;
    }

    printf("Enter the elements:\n");
    for (int i = 0; i < size; i++) {
        scanf("%d", &keys[i]);
    }

    int largest = find_largest(keys, size);
    printf("Largest element: %d\n", largest);

    initialize_records(records, size, 100); // Assuming upper bound is 100

    free_memory(keys, records, size);

    return 0;
}
