record* initialize_records(long offset_size, int key_range, long timestamp_range, unsigned seed, const char* log_file) {
    if (offset_size <= 0 || key_range < 0 || timestamp_range <= 0) {
        fprintf(stderr, "Invalid input parameters\n");
        exit(EXIT_FAILURE);
    }

    FILE* log = fopen(log_file, "a");
    if (log == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    long* offsets = safe_malloc(offset_size * sizeof(long), __FILE__, __LINE__);
    int* keys = safe_malloc(key_range * sizeof(int), __FILE__, __LINE__);
    record* records = safe_malloc(record_size * sizeof(record), __FILE__, __LINE__);

    srand(seed);

    for (long i = 0; i < offset_size; ++i) {
        offsets[i] = rand() % offset_range;
    }

    for (int i = 0; i < key_range; ++i) {
        keys[i] = rand() % key_range;
    }

    for (long i = 0; i < record_size; ++i) {
        records[i].timestamp = rand() % timestamp_range;
        records[i].value = rand() % key_range;
    }

    fclose(log);
    return records;
}

void free_records(record* records, long record_size) {
    free(records);
}

int main() {
    const char* log_file = "error_log.txt";
    long offset_size = 1000;
    int key_range = 100;
    long timestamp_range = 3600;
    unsigned seed = time(NULL);

    record* records = initialize_records(offset_size, key_range, timestamp_range, seed, log_file);
    // Use the records array here
    free_records(records, offset_size);

    return 0;
}
