#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct TreeNode {
    double value;
    int numChildren;
    struct TreeNode** children;
} TreeNode;

TreeNode* createNode(double value) {
    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));
    if (!node) {
        fprintf(stderr, "Memory allocation failed for new node.\n");
        return NULL;
    }
    node->value = value;
    node->numChildren = 0;
    node->children = NULL;
    return node;
}

void freeTree(TreeNode* root) {
    if (root) {
        for (int i = 0; i < root->numChildren; i++) {
            freeTree(root->children[i]);
        }
        free(root->children);
        free(root);
    }
}

TreeNode* populateTree(double rootValue, int depth, int maxChildren, double lowerBound, double upperBound) {
    if (depth == 0) return NULL;

    TreeNode* root = createNode(rootValue);
    if (!root) return NULL;

    for (int i = 0; i < maxChildren; i++) {
        double childValue = ((double)rand() / RAND_MAX) * (upperBound - lowerBound) + lowerBound;
        TreeNode* child = populateTree(childValue, depth - 1, maxChildren, lowerBound, upperBound);
        if (!child) {
            freeTree(root);
            return NULL;
        }
        root->children = realloc(root->children, (root->numChildren + 1) * sizeof(TreeNode*));
        if (!root->children) {
            fprintf(stderr, "Memory allocation failed for children array.\n");
            freeTree(child);
            freeTree(root);
            return NULL;
        }
        root->children[root->numChildren++] = child;
    }

    return root;
}

int main() {
    srand(time(NULL));
    TreeNode* tree = populateTree(0.0, 3, 2, -10.0, 10.0);
    if (tree) {
        // Use the tree
        freeTree(tree);
    }
    return 0;
}
```

