typedef struct {
    unsigned long key;
    double value;
} HashEntry;

typedef struct {
    HashEntry* entries;
    size_t capacity;
    size_t size;
} HashTable;

unsigned long hashFunction(unsigned long key, size_t capacity) {
    return key % capacity;
}

HashTable* createHashTable(size_t initialCapacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) {
        fprintf(stderr, "Memory allocation failed for hash table\n");
        return NULL;
    }
    table->entries = (HashEntry*)calloc(initialCapacity, sizeof(HashEntry));
    if (!table->entries) {
        free(table);
        fprintf(stderr, "Memory allocation failed for hash entries\n");
        return NULL;
    }
    table->capacity = initialCapacity;
    table->size = 0;
    return table;
}

void destroyHashTable(HashTable* table) {
    if (table) {
        free(table->entries);
        free(table);
    }
}

int initializeHashTables(size_t numTables, size_t* capacities, double upperBound) {
    srand(time(NULL));
    for (size_t i = 0; i < numTables; ++i) {
        HashTable* table = createHashTable(capacities[i]);
        if (!table) {
            fprintf(stderr, "Failed to initialize hash table %zu\n", i);
            // Clean up previously allocated tables
            for (size_t j = 0; j < i; ++j) {
                destroyHashTable(table[j]);
            }
            return -1;
        }
        for (size_t j = 0; j < capacities[i]; ++j) {
            table->entries[j].key = hashFunction(j, capacities[i]);
            table->entries[j].value = ((double)rand() / RAND_MAX) * upperBound;
        }
    }
    return 0;
}

int main() {
    size_t numTables = 3;
    size_t capacities[] = {100, 200, 300};
    double upperBound = 100.0;

    if (initializeHashTables(numTables, capacities, upperBound) == 0) {
        printf("Hash tables initialized successfully\n");
    } else {
        printf("Failed to initialize hash tables\n");
    }

    return 0;
}
