#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    unsigned long key;
    double value;
} Entry;

typedef struct {
    Entry *entries;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

unsigned long hash(unsigned long key, size_t capacity) {
    return key % capacity;
}

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) {
        perror("Failed to allocate memory for hash table");
        return NULL;
    }
    table->entries = (Entry*)calloc(initial_capacity, sizeof(Entry));
    if (!table->entries) {
        perror("Failed to allocate memory for entries");
        free(table);
        return NULL;
    }
    table->capacity = initial_capacity;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void destroy_hash_table(HashTable *table) {
    if (table) {
        pthread_mutex_destroy(&table->lock);
        free(table->entries);
        free(table);
    }
}

int add_entry(HashTable *table, unsigned long key, double value) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash(key, table->capacity);
    while (table->entries[index].key != 0 && table->entries[index].key != key) {
        index = (index + 1) % table->capacity;
    }
    if (table->entries[index].key == 0) {
        table->entries[index].key = key;
        table->entries[index].value = value;
        table->size++;
    } else {
        pthread_mutex_unlock(&table->lock);
        return -1; // Key already exists
    }
    pthread_mutex_unlock(&table->lock);
    return 0;
}

int main() {
    HashTable *table = create_hash_table(1024);
    if (table) {
        add_entry(table, 123456789, 3.14159);
        destroy_hash_table(table);
    }
    return 0;
}
```

