#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    double d;
    float f;
    char c;
    short s;
} Record;

typedef struct {
    Record* records;
    size_t count;
    pthread_mutex_t lock;
} DataStore;

DataStore* create_data_store() {
    DataStore* store = (DataStore*)malloc(sizeof(DataStore));
    if (!store) return NULL;
    store->records = NULL;
    store->count = 0;
    pthread_mutex_init(&store->lock, NULL);
    return store;
}

int load_data(DataStore* store, const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) return -1;

    // Assuming a simple format where each line contains a record
    Record record;
    while (fscanf(file, "%lf %f %c %hd", &record.d, &record.f, &record.c, &record.s) == 4) {
        store->records = realloc(store->records, (store->count + 1) * sizeof(Record));
        if (!store->records) {
            fclose(file);
            return -1;
        }
        store->records[store->count++] = record;
    }

    fclose(file);
    return 0;
}

void free_data_store(DataStore* store) {
    pthread_mutex_lock(&store->lock);
    free(store->records);
    store->records = NULL;
    store->count = 0;
    pthread_mutex_unlock(&store->lock);
    pthread_mutex_destroy(&store->lock);
    free(store);
}

// Example usage
int main() {
    DataStore* store = create_data_store();
    if (!store) {
        fprintf(stderr, "Failed to create data store\n");
        return 1;
    }

    if (load_data(store, "data.txt") != 0) {
        fprintf(stderr, "Failed to load data\n");
        free_data_store(store);
        return 1;
    }

    // Process the data...

    free_data_store(store);
    return 0;
}
