            }
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }

        random_func(&keys[i]); // Use the provided random function
        record->key = keys[i];
        record->offset_ptr = &offsets[keys[i] % num_offsets]; // Link to offsets array

        records[i] = record;
    }

    log_func("Memory allocation and initialization completed successfully.");
    return records;
}

void deallocate_memory(Record **records, int num_keys) {
    for (int i = 0; i < num_keys; ++i) {
        free(records[i]);
    }
    free(records);
}
