typedef struct record {
    long offset;
    int key;
    struct record *next;
    char label[256];
} Record;

Record* create_record_collection(int size, int upper_bound) {
    if (size <= 0 || upper_bound <= 0) {
        return NULL;
    }

    Record **collection = (Record **)malloc(size * sizeof(Record *));
    if (!collection) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < size; ++i) {
        collection[i] = (Record *)malloc(sizeof(Record));
        if (!collection[i]) {
            perror("Memory allocation failed");
            // Clean up previously allocated resources
            for (int j = 0; j < i; ++j) {
                free(collection[j]);
            }
            free(collection);
            return NULL;
        }

        do {
            collection[i]->key = rand() % upper_bound + 1;
        } while (i > 0 && collection[i]->key == collection[i - 1]->key);

        collection[i]->offset = i * sizeof(Record);
        collection[i]->next = NULL;
        snprintf(collection[i]->label, sizeof(collection[i]->label), "record_%d", i);
    }

    return (Record *)collection;
}

void free_record_collection(Record **collection, int size) {
    if (!collection || size <= 0) {
        return;
    }

    for (int i = 0; i < size; ++i) {
        free(collection[i]);
    }
    free(collection);
}

int main() {
    int size = 10;
    int upper_bound = 100;

    Record *collection = create_record_collection(size, upper_bound);
    if (!collection) {
        fprintf(stderr, "Failed to create record collection\n");
        return EXIT_FAILURE;
    }

    // Use the collection...

    free_record_collection((Record **)collection, size);

    return EXIT_SUCCESS;
}
