    // Allocate memory for arrays
    *offsets = (long *)malloc(size * sizeof(long));
    *keys = (int *)malloc(size * sizeof(int));
    *records = (Record **)malloc(size * sizeof(Record *));
    *statuses = (int *)malloc(size * sizeof(int));

    if (*offsets == NULL || *keys == NULL || *records == NULL || *statuses == NULL) {
        // Handle memory allocation failure
        free(*offsets);
        free(*keys);
        free(*records);
        free(*statuses);
        return FAILURE;
    }

    // Initialize arrays
    for (int i = 0; i < size; i++) {
        (*offsets)[i] = i * 10L;
        (*keys)[i] = rand() % 100;
        (*records)[i] = NULL;
        (*statuses)[i] = SUCCESS;

        // Allocate memory for record and initialize
        Record *new_record = (Record *)malloc(sizeof(Record));
        if (new_record == NULL) {
            // Handle memory allocation failure
            for (int j = 0; j < i; j++) {
                free((*records)[j]);
            }
            free(*offsets);
            free(*keys);
            free(*records);
            free(*statuses);
            return FAILURE;
        }

        new_record->value = rand() % 1000;
        new_record->prev = NULL;
        new_record->next = NULL;
        (*records)[i] = new_record;
    }

    return SUCCESS;
}

int main() {
