#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 1000
#define MAX_ELEMENTS 50
#define MAX_KEY 1000
#define UPPER_BOUND 100

typedef struct Element {
    int value;
    struct Element* next;
} Element;

typedef struct Record {
    long offset;
    int key;
    Element* elements;
    int elementCount;
} Record;

Record** records = NULL;
int recordCount = 0;
int maxRecords = 0;
long memoryThreshold = 1024 * 1024; // 1MB
long currentMemoryUsage = 0;

void initializeRecords(int size, long threshold) {
    if (records != NULL) {
        free(records);
    }
    records = (Record**)malloc(size * sizeof(Record*));
    maxRecords = size;
    memoryThreshold = threshold;
}

int addRecord(long offset, int key) {
    if (recordCount >= maxRecords || currentMemoryUsage + sizeof(Record) > memoryThreshold) {
        return -1; // Memory limit exceeded
    }
    records[recordCount] = (Record*)malloc(sizeof(Record));
    records[recordCount]->offset = offset;
    records[recordCount]->key = key;
    records[recordCount]->elements = NULL;
    records[recordCount]->elementCount = 0;
    recordCount++;
    currentMemoryUsage += sizeof(Record);
    return 0; // Success
}

void freeRecords() {
    for (int i = 0; i < recordCount; i++) {
        Element* element = records[i]->elements;
        while (element != NULL) {
            Element* next = element->next;
            free(element);
            element = next;
        }
        free(records[i]);
    }
    free(records);
    records = NULL;
    recordCount = 0;
}

int main() {
    srand(time(NULL));
    initializeRecords(MAX_RECORDS, memoryThreshold);

    for (int i = 0; i < MAX_RECORDS; i++) {
        if (addRecord(i * 100, rand() % MAX_KEY) != 0) {
            printf("Failed to add record\n");
            break;
        }
    }

    freeRecords();
    return 0;
}
