    double value;
} HashEntry;

typedef struct {
    HashEntry *entries;
    size_t capacity;
    size_t size;
} HashTable;

unsigned long hash_function(unsigned long key, size_t capacity) {
    return key % capacity;
}

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    table->entries = (HashEntry*)calloc(initial_capacity, sizeof(HashEntry));
    if (!table->entries) {
        free(table);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    table->capacity = initial_capacity;
    table->size = 0;
    return table;
}

void destroy_hash_table(HashTable *table) {
    free(table->entries);
    free(table);
}

int initialize_hash_tables(size_t num_tables, size_t *table_sizes, unsigned long upper_bound) {
    HashTable **tables = (HashTable**)malloc(num_tables * sizeof(HashTable*));
    if (!tables) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    for (size_t i = 0; i < num_tables; ++i) {
        tables[i] = create_hash_table(table_sizes[i]);
        if (!tables[i]) {
            for (size_t j = 0; j < i; ++j) {
                destroy_hash_table(tables[j]);
            }
            free(tables);
            fprintf(stderr, "Memory allocation failed\n");
            return -1;
        }

        srand(time(NULL));
        for (size_t j = 0; j < table_sizes[i]; ++j) {
            unsigned long key = hash_function(rand(), tables[i]->capacity);
            double value = ((double)rand() / RAND_MAX) * upper_bound;
            tables[i]->entries[j].key = key;
            tables[i]->entries[j].value = value;
        }
    }

    // Simulate external API interaction
    for (size_t i = 0; i < num_tables; ++i) {
        // Perform operations with the hash table
    }

    for (size_t i = 0; i < num_tables; ++i) {
        destroy_hash_table(tables[i]);
    }
    free(tables);

    return 0;
}

int main() {
    size_t table_sizes[] = {10, 20, 30};
    unsigned long upper_bound = 100.0;
    int result = initialize_hash_tables(3, table_sizes, upper_bound);
    if (result != 0) {
        fprintf(stderr, "Initialization failed\n");
        return EXIT_FAILURE;
    }
    return EXIT_SUCCESS;
}
