int allocate_memory(int** keys, record** recs, char*** tags, int size) {
    *keys = (int*)malloc(size * sizeof(int));
    *recs = (record*)malloc(size * sizeof(record));
    *tags = (char**)malloc(size * sizeof(char*));

    if (*keys == NULL || *recs == NULL || *tags == NULL) {
        free(*keys);
        free(*recs);
        free(*tags);
        return -1;
    }

    for (int i = 0; i < size; i++) {
        (*tags)[i] = (char*)malloc(20 * sizeof(char));
        if ((*tags)[i] == NULL) {
            for (int j = 0; j < i; j++) {
                free((*tags)[j]);
            }
            free(*keys);
            free(*recs);
            free(*tags);
            return -1;
        }
    }

    return 0;
}

void initialize_records(int* keys, record* recs, char** tags, int size, int upper_bound) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        keys[i] = rand() % (upper_bound + 1);
        sprintf(tags[i], "tag_%d", keys[i]);
        recs[i].value = keys[i];
        recs[i].tag = tags[i];
    }
}

void free_memory(int* keys, record* recs, char** tags, int size) {
    for (int i = 0; i < size; i++) {
        free(tags[i]);
    }
    free(keys);
    free(recs);
    free(tags);
}

