    // Find and print the largest integer
    int max_key = keys[0];
    for (int i = 1; i < size; i++) {
        if (keys[i] > max_key) {
            max_key = keys[i];
        }
    }
    printf("Largest integer: %d\n", max_key);

    // Find and print the longest string
    int max_length = strlen(tags[0]);
    char* longest_tag = tags[0];
    for (int i = 1; i < size; i++) {
        if (strlen(tags[i]) > max_length) {
            max_length = strlen(tags[i]);
            longest_tag = tags[i];
        }
    }
    printf("Longest string: %s\n", longest_tag);

    free_memory(keys, recs, tags, size);
    return 0;
}
