#define MAX_RECORD_SIZE 1024

typedef struct {
    int value;
    char timestamp[20];
    int priority;
    char category[50];
    double location[2];
    float size;
    int status;
    char source[50];
} Record;

Record* create_records(int size, int max_value, int max_priority, const char* categories[], int num_categories) {
    if (size > MAX_RECORD_SIZE) {
        fprintf(stderr, "Error: Array size exceeds maximum allowed.\n");
        return NULL;
    }

    Record* records = (Record*)malloc(size * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < size; i++) {
        records[i].value = rand() % max_value + 1;
        time_t now = time(NULL);
        strftime(records[i].timestamp, sizeof(records[i].timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        records[i].priority = rand() % max_priority + 1;

        int category_index = rand() % num_categories;
        strncpy(records[i].category, categories[category_index], sizeof(records[i].category) - 1);
        records[i].category[sizeof(records[i].category) - 1] = '\0';

        records[i].location[0] = (double)(rand() % 360000) / 1000.0; // Latitude
        records[i].location[1] = (double)(rand() % 720000) / 1000.0; // Longitude

        records[i].size = (float)(rand() % 1000) / 10.0;
        records[i].status = rand() % 2; // 0 or 1
        snprintf(records[i].source, sizeof(records[i].source), "Source%d", i);
    }

    return records;
}

int main() {
    const char* categories[] = {"CategoryA", "CategoryB", "CategoryC"};
    int num_categories = sizeof(categories) / sizeof(categories[0]);

    Record* records = create_records(10, 100, 5, categories, num_categories);
    if (records) {
        for (int i = 0; i < 10; i++) {
            printf("Record %d: Value=%d, Timestamp=%s, Priority=%d, Category=%s\n",
                   i, records[i].value, records[i].timestamp, records[i].priority, records[i].category);
        }
        free(records);
    }

    return 0;
}
