    double floatingPointNumber;
    char byteSequence[256];
    Point point;
    Rectangle rectangle;
} DataStructure;

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <num_structures> <record_upper_bound>\n", argv[0]);
        return 1;
    }

    int numStructures = atoi(argv[1]);
    int recordUpperBound = atoi(argv[2]);

    DataStructure *dataStructures = (DataStructure *)malloc(numStructures * sizeof(DataStructure));
    if (!dataStructures) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    srand(time(NULL));

    for (int i = 0; i < numStructures; i++) {
        int type = rand() % 6;
        switch (type) {
            case 0:
                dataStructures[i].integerKey = rand();
                break;
            case 1:
                for (int j = 0; j < 10; j++) {
                    dataStructures[i].record.values[j] = rand() % recordUpperBound;
                }
                break;
            case 2:
                dataStructures[i].floatingPointNumber = ((double)rand()) / RAND_MAX * 100.0;
                break;
            case 3:
                snprintf(dataStructures[i].byteSequence, sizeof(dataStructures[i].byteSequence), "Record %d", i);
                break;
            case 4:
                dataStructures[i].point.x = rand() % 100;
                dataStructures[i].point.y = rand() % 100;
                break;
            case 5:
                dataStructures[i].rectangle.width = rand() % 50;
                dataStructures[i].rectangle.height = rand() % 50;
                break;
        }
    }

    // Process input and perform operations
    int *integers = NULL;
    size_t numIntegers = 0;

    while (1) {
        int value;
        if (scanf("%d", &value) != 1) {
            break;
        }
        integers = realloc(integers, (numIntegers + 1) * sizeof(int));
        if (!integers) {
            fprintf(stderr, "Memory allocation failed\n");
            free(dataStructures);
            return 1;
        }
        integers[numIntegers++] = value;
    }

    int maxInteger = findMaxInteger(integers, numIntegers);
    printf("Largest integer: %d\n", maxInteger);

    // Free allocated memory
    free(dataStructures);
    free(integers);

    return 0;
}

int findMaxInteger(int *array, size_t size) {
    if (size == 0) {
        return INT_MIN;
    }
    int max = array[0];
    for (size_t i = 1; i < size; i++) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}
