#define MAX_FILES 1024
#define MAX_FILENAME_LENGTH 256

typedef struct {
    int key;
    char path[MAX_FILENAME_LENGTH];
    size_t size;
    time_t timestamp;
} FileRecord;

typedef struct {
    FileRecord *records;
    int count;
    pthread_mutex_t lock;
} MetadataManager;

MetadataManager* init_metadata_manager(const char *directory) {
    MetadataManager *manager = (MetadataManager*)malloc(sizeof(MetadataManager));
    if (!manager) return NULL;

    manager->records = (FileRecord*)calloc(MAX_FILES, sizeof(FileRecord));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    DIR *dir;
    struct dirent *entry;
    dir = opendir(directory);
    if (dir) {
        while ((entry = readdir(dir)) != NULL) {
            if (entry->d_type == DT_REG) {
                snprintf(manager->records[manager->count].path, MAX_FILENAME_LENGTH, "%s/%s", directory, entry->d_name);
                // Simulate file size and timestamp for demonstration
                manager->records[manager->count].size = rand() % 1024;
                manager->records[manager->count].timestamp = time(NULL);
                manager->records[manager->count].key = manager->count + 1;
                manager->count++;
            }
        }
        closedir(dir);
    }

    return manager;
}

void free_metadata_manager(MetadataManager *manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->lock);
        free(manager->records);
        free(manager);
    }
}

int main() {
    MetadataManager *manager = init_metadata_manager(".");
    if (!manager) {
        fprintf(stderr, "Failed to initialize metadata manager\n");
        return 1;
    }

    // Use the metadata manager...

    free_metadata_manager(manager);
    return 0;
}
