// Define record structure
struct Record {
    int value;
};

// Function to dynamically allocate memory for arrays and initialize records with random values
bool initializeArrays(size_t size, long*& offsets, int*& keys1, Record*& records, int*& keys2) {
    try {
        offsets = new long[size];
        keys1 = new int[size];
        records = new Record[size];
        keys2 = new int[size];

        // Initialize arrays with random values
        std::srand(std::time(0));
        for (size_t i = 0; i < size; ++i) {
            offsets[i] = static_cast<long>(std::rand());
            keys1[i] = static_cast<int>(std::rand());
            records[i].value = static_cast<int>(std::rand() % 100); // Random value up to 99
            keys2[i] = static_cast<int>(std::rand());
        }

        return true;
    } catch (const std::bad_alloc& e) {
        // Handle memory allocation failure
        cleanupMemory(offsets, keys1, records, keys2);
        return false;
    }
}

// Function to free allocated memory
void cleanupMemory(long* offsets, int* keys1, Record* records, int* keys2) {
    delete[] offsets;
    delete[] keys1;
    delete[] records;
    delete[] keys2;
}

int main() {
    size_t size = 1000; // Example size

    long* offsets;
    int* keys1;
    Record* records;
    int* keys2;

    if (initializeArrays(size, offsets, keys1, records, keys2)) {
        std::cout << "Memory allocation successful." << std::endl;
        cleanupMemory(offsets, keys1, records, keys2);
    } else {
        std::cerr << "Memory allocation failed." << std::endl;
    }

    return 0;
}
