typedef struct {
    int value;
} record;

typedef struct {
    char filename[256];
    long size;
    time_t mod_date;
} file_info;

int initialize_arrays(int key_size, int record_size, int file_info_size, int upper_bound, const char* directory) {
    int* keys = (int*)malloc(key_size * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        return -1;
    }

    record* records = (record*)malloc(record_size * sizeof(record));
    if (!records) {
        free(keys);
        perror("Failed to allocate memory for records");
        return -1;
    }

    file_info* file_infos = (file_info*)malloc(file_info_size * sizeof(file_info));
    if (!file_infos) {
        free(keys);
        free(records);
        perror("Failed to allocate memory for file_infos");
        return -1;
    }

    srand(time(NULL));

    // Initialize keys
    for (int i = 0; i < key_size; i++) {
        keys[i] = rand() % upper_bound;
    }

    // Initialize records with random values
    for (int i = 0; i < record_size; i++) {
        records[i].value = rand() % upper_bound;
    }

    DIR* dir = opendir(directory);
    if (!dir) {
        perror("Failed to open directory");
        free(keys);
        free(records);
        free(file_infos);
        return -1;
    }

    struct dirent* entry;
    int file_count = 0;

    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) {
            snprintf(file_infos[file_count].filename, sizeof(file_infos[file_count].filename), "%s/%s", directory, entry->d_name);
            // Simulate getting file size and modification date
            file_infos[file_count].size = rand() % 1024; // Random size for demonstration
            file_infos[file_count].mod_date = time(NULL); // Current time for demonstration
            file_count++;
        }
    }

    closedir(dir);

    if (file_count != file_info_size) {
        fprintf(stderr, "Warning: Not all files in the directory were processed\n");
    }

    // Free allocated memory
    free(keys);
    free(records);
    free(file_infos);

    return 0;
}

int main() {
    int key_size = 100;
    int record_size = 200;
    int file_info_size = 50;
    int upper_bound = 1000;
    const char* directory = "/path/to/directory";

    if (initialize_arrays(key_size, record_size, file_info_size, upper_bound, directory) == 0) {
        printf("Initialization successful\n");
    } else {
        printf("Initialization failed\n");
    }

    return 0;
}
