#include <pthread.h>
#include <time.h>

#define MAX_MEMORY_USAGE 0.5

typedef struct {
    int value;
} record;

void* allocate_memory(void* arg) {
    long size = *(long*)arg;
    long total_memory = sysconf(_SC_PHYS_PAGES) * sysconf(_SC_PAGE_SIZE);
    long max_allowed_memory = (long)(total_memory * MAX_MEMORY_USAGE);

    if (size * sizeof(record) > max_allowed_memory) {
        fprintf(stderr, "Memory allocation exceeds 50%% of available system RAM.\n");
        return NULL;
    }

    record* records = (record*)malloc(size * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records.");
        return NULL;
    }

    // Initialize records with random values
    srand(time(NULL));
    for (long i = 0; i < size; ++i) {
        records[i].value = rand() % 1000;
    }

    return records;
}

void validate_memory(void* records, long size) {
    record* recs = (record*)records;
    for (long i = 0; i < size; ++i) {
        if (recs[i].value < 0 || recs[i].value > 1000) {
            fprintf(stderr, "Memory validation failed at index %ld.\n", i);
            return;
        }
    }
    printf("Memory validation passed.\n");
}

void* populate_records(void* arg) {
    record** records_ptr = (record**)arg;
    long size = *(long*)records_ptr[1];
    record* records = *records_ptr;

    for (long i = 0; i < size; ++i) {
        records[i].value = rand() % 1000;
    }

    return NULL;
}

void log_memory_usage(long allocated_memory, long total_memory) {
    printf("Allocated Memory: %ld bytes\n", allocated_memory);
    printf("Total Memory: %ld bytes\n", total_memory);
    printf("Memory Usage: %.2f%%\n", (allocated_memory * 100.0 / total_memory));
}

void cleanup(void* records, long size) {
    free(records);
    printf("Memory cleaned up.\n");
}

int main() {
    long size;
    printf("Enter the number of records: ");
    scanf("%ld", &size);

    record** records_ptr = (record**)malloc(2 * sizeof(record*));
    if (!records_ptr) {
        perror("Failed to allocate memory for records pointer.");
        return 1;
    }

    records_ptr[0] = allocate_memory(&size);
    if (!records_ptr[0]) {
        free(records_ptr);
        return 1;
    }

    validate_memory(records_ptr[0], size);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, populate_records, records_ptr) != 0) {
        perror("Failed to create thread.");
        cleanup(records_ptr[0], size);
        free(records_ptr);
        return 1;
    }

    pthread_join(thread_id, NULL);

    log_memory_usage(size * sizeof(record), sysconf(_SC_PHYS_PAGES) * sysconf(_SC_PAGE_SIZE));

    cleanup(records_ptr[0], size);
    free(records_ptr);

    return 0;
}
