#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
    int status;
    time_t timestamp;
} RecordData;

typedef struct {
    int access_count;
    time_t last_accessed;
} Metadata;

typedef struct {
    long offset;
    int key;
    RecordData data;
    Metadata metadata;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} Cache;

Cache* create_cache(size_t initial_capacity) {
    Cache* cache = (Cache*)malloc(sizeof(Cache));
    if (!cache) {
        perror("Failed to allocate memory for cache");
        return NULL;
    }
    cache->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!cache->records) {
        perror("Failed to allocate memory for records");
        free(cache);
        return NULL;
    }
    cache->capacity = initial_capacity;
    cache->size = 0;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void destroy_cache(Cache* cache) {
    if (cache) {
        pthread_mutex_lock(&cache->lock);
        free(cache->records);
        pthread_mutex_unlock(&cache->lock);
        pthread_mutex_destroy(&cache->lock);
        free(cache);
    }
}

int init_records(Cache* cache, Record* records, size_t count) {
    if (!cache || !records || count == 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return -1;
    }

    pthread_mutex_lock(&cache->lock);

    if (count > cache->capacity - cache->size) {
        size_t new_capacity = cache->capacity * 2;
        Record* new_records = (Record*)realloc(cache->records, new_capacity * sizeof(Record));
        if (!new_records) {
            perror("Failed to reallocate memory for records");
            pthread_mutex_unlock(&cache->lock);
            return -1;
        }
        cache->records = new_records;
        cache->capacity = new_capacity;
    }

    for (size_t i = 0; i < count; ++i) {
        cache->records[cache->size + i] = records[i];
        cache->records[cache->size + i].metadata.access_count = 0;
        cache->records[cache->size + i].metadata.last_accessed = time(NULL);
    }

    cache->size += count;

    pthread_mutex_unlock(&cache->lock);

    return 0;
}

// Additional functions for managing the cache can be added here
