#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_IDENTIFIER_LENGTH 256

typedef struct record {
    int value;
    char *identifier;
} record;

typedef struct record_collection {
    record **records;
    size_t count;
    pthread_mutex_t lock;
} record_collection;

int generate_unique_identifier(char *prefix, int random_number, char *output) {
    snprintf(output, MAX_IDENTIFIER_LENGTH, "%s%d", prefix, random_number);
    return 0; // Assuming always successful for simplicity
}

record *create_record(int value, const char *identifier_prefix) {
    record *new_record = (record *)malloc(sizeof(record));
    if (!new_record) {
        return NULL;
    }

    new_record->value = value;

    int random_number = rand();
    char identifier[MAX_IDENTIFIER_LENGTH];
    generate_unique_identifier(identifier_prefix, random_number, identifier);

    new_record->identifier = strdup(identifier);
    if (!new_record->identifier) {
        free(new_record);
        return NULL;
    }

    return new_record;
}

int add_record(record_collection *collection, int value, const char *identifier_prefix) {
    pthread_mutex_lock(&collection->lock);

    record **new_records = (record **)realloc(collection->records, (collection->count + 1) * sizeof(record *));
    if (!new_records) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Memory allocation failed
    }

    collection->records = new_records;

    record *new_record = create_record(value, identifier_prefix);
    if (!new_record) {
        free(new_records);
        pthread_mutex_unlock(&collection->lock);
        return -2; // Record creation failed
    }

    collection->records[collection->count++] = new_record;
    pthread_mutex_unlock(&collection->lock);

    return 0; // Success
}

void print_record(const record *record) {
    if (record && record->identifier && record->value != INT_MIN) {
        printf("Identifier: %s, Value: %d\n", record->identifier, record->value);
    }
}

void free_collection(record_collection *collection) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i]) {
            free(collection->records[i]->identifier);
            free(collection->records[i]);
        }
    }

    free(collection->records);
    pthread_mutex_unlock(&collection->lock);

    pthread_mutex_destroy(&collection->lock);
}

int main() {
    record_collection collection = {NULL, 0, PTHREAD_MUTEX_INITIALIZER};

    if (add_record(&collection, 10, "user_") != 0) {
        printf("Failed to add record\n");
    }

    print_record(collection.records[0]);

    free_collection(&collection);

    return 0;
}
