long* process_and_analyze_data(int num_records, int range_min, int range_max, int size_limit) {
    long* offsets = (long*)malloc(num_records * sizeof(long));
    int* keys = (int*)malloc(num_records * sizeof(int));
    record* records = (record*)malloc(num_records * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
        offsets[i] = rand() % 1000L;
        keys[i] = i;
        records[i].value = rand() % (range_max - range_min + 1) + range_min;
    }

    int* aux_array = (int*)malloc(num_records * sizeof(int));
    if (!aux_array) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(records);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num_records; ++i) {
        aux_array[i] = records[i].value;
    }

    int largest = find_largest_integer(aux_array, num_records);
    printf("Largest integer: %d\n", largest);

    free(aux_array);

    char* input_string = (char*)malloc(size_limit * sizeof(char));
    if (!input_string) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(records);
        exit(EXIT_FAILURE);
    }

    printf("Enter a string: ");
    fgets(input_string, size_limit, stdin);

    char* result = process_string(input_string, size_limit);
    if (result) {
        printf("Processed string: %s\n", result);
        free(result);
    } else {
        printf("String too long or empty.\n");
    }

    free(offsets);
    free(keys);
    free(records);

    return offsets;
}

int find_largest_integer(int* array, int size) {
    if (size <= 0) {
        fprintf(stderr, "Invalid array size\n");
        exit(EXIT_FAILURE);
    }
    int max = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

char* process_string(char* input, int limit) {
    if (!input || strlen(input) >= limit) {
        return NULL;
    }
    char* result = (char*)malloc((strlen(input) + 2) * sizeof(char));
    if (!result) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    strcpy(result, input);
    strcat(result, "/");
    return result;
}
