    return checksum;
}

int allocateAndInitializeBuffers(CustomData **array, size_t count) {
    srand(time(NULL));
    for (size_t i = 0; i < count; ++i) {
        array[i] = (CustomData *)malloc(sizeof(CustomData));
        if (!array[i]) {
            perror("Failed to allocate memory");
            return -1;
        }
        array[i]->size = rand() % BUFFER_SIZE + 1;
        array[i]->buffer = (unsigned char *)malloc(array[i]->size);
        if (!array[i]->buffer) {
            perror("Failed to allocate buffer");
            free(array[i]);
            return -1;
        }

        // Initialize buffer with unique random byte patterns
        for (size_t j = 0; j < array[i]->size; ++j) {
            array[i]->buffer[j] = rand();
        }

        unsigned int checksum = calculateChecksum(array[i]->buffer, array[i]->size);
        printf("Buffer %zu: Size=%zu, Checksum=%u\n", i, array[i]->size, checksum);
    }
    return 0;
}

void freeBuffers(CustomData **array, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (array[i]) {
            free(array[i]->buffer);
            free(array[i]);
        }
    }
}

int main() {
    size_t count = 5;
    CustomData **buffers = (CustomData **)malloc(count * sizeof(CustomData *));
    if (!buffers) {
        perror("Failed to allocate memory for array");
        return -1;
    }

    if (allocateAndInitializeBuffers(buffers, count) != 0) {
        freeBuffers(buffers, count);
        free(buffers);
        return -1;
    }

    // Use the buffers...

    freeBuffers(buffers, count);
    free(buffers);

    return 0;
}
