#define MAX_RECORDS 1000

typedef struct {
    int value;
} record;

void process_and_analyze_data(int range_start, int range_end) {
    long *offsets = (long *)malloc(MAX_RECORDS * sizeof(long));
    int *keys = (int *)malloc(MAX_RECORDS * sizeof(int));
    record *records = (record *)malloc(MAX_RECORDS * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    for (int i = 0; i < MAX_RECORDS; ++i) {
        offsets[i] = rand() % range_end + range_start;
        keys[i] = rand() % range_end + range_start;
        records[i].value = rand() % range_end + range_start;
    }

    int *auxiliary_array = (int *)malloc(MAX_RECORDS * sizeof(int));
    if (!auxiliary_array) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(records);
        exit(EXIT_FAILURE);
    }

    printf("Enter integers (end with Ctrl+D):\n");
    int num_read = 0;
    while (scanf("%d", &auxiliary_array[num_read]) == 1 && num_read < MAX_RECORDS) {
        ++num_read;
    }

    if (num_read == 0) {
        fprintf(stderr, "No valid integers entered\n");
        free(offsets);
        free(keys);
        free(records);
        free(auxiliary_array);
        exit(EXIT_FAILURE);
    }

    find_largest_integer(auxiliary_array, num_read);

    free(offsets);
    free(keys);
    free(records);
    free(auxiliary_array);
}

void find_largest_integer(int *array, int size) {
    if (size == 0) {
        printf("No integers to analyze\n");
        return;
    }

    int largest = array[0];
    for (int i = 1; i < size; ++i) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }

    printf("Largest integer: %d\n", largest);
}

int main() {
    int range_start, range_end;
    printf("Enter the range start and end for random numbers: ");
    scanf("%d %d", &range_start, &range_end);

    process_and_analyze_data(range_start, range_end);

    return 0;
}
