#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    char status;
    size_t timestamp;
} record;

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

record* init_records(int num_records, int value_range_start, int value_range_end) {
    record* records = safe_malloc(num_records * sizeof(record));
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        if (value_range_start > value_range_end || value_range_end - value_range_start == 0) {
            fprintf(stderr, "Invalid value range\n");
            exit(EXIT_FAILURE);
        }
        records[i].value = rand() % (value_range_end - value_range_start + 1) + value_range_start;
        records[i].status = 'A'; // Active
        records[i].timestamp = time(NULL);
    }
    return records;
}

void update_records(record* records, int num_records, int new_value_range_start, int new_value_range_end) {
    if (new_value_range_start > new_value_range_end || new_value_range_end - new_value_range_start == 0) {
        fprintf(stderr, "Invalid value range for updates\n");
        return;
    }
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % (new_value_range_end - new_value_range_start + 1) + new_value_range_start;
        records[i].timestamp = time(NULL);
    }
}

void free_records(record* records, int num_records) {
    free(records);
}

int main() {
    int num_records = 1000;
    record* records = init_records(num_records, 1, 100);

    // Simulate updates
    update_records(records, num_records, 50, 200);

    free_records(records, num_records);
    return 0;
}
