#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_KEY_LENGTH 256
#define INITIAL_CAPACITY 10
#define LOAD_FACTOR_THRESHOLD 0.75

typedef struct entry {
    char* key;
    size_t length;
    time_t timestamp;
} Entry;

typedef struct hash_table {
    Entry** buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

unsigned long hash(const char* key, size_t capacity) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash % capacity;
}

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->buckets = (Entry**)calloc(initial_capacity, sizeof(Entry*));
    table->capacity = initial_capacity;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void insert_entry(HashTable* table, const char* key, size_t length) {
    pthread_mutex_lock(&table->lock);
    if ((double)table->size / table->capacity > LOAD_FACTOR_THRESHOLD) {
        // Rehash operation
    }
    unsigned long index = hash(key, table->capacity);
    while (table->buckets[index] != NULL) {
        index = (index + 1) % table->capacity;
    }
    Entry* entry = (Entry*)malloc(sizeof(Entry));
    entry->key = strdup(key);
    entry->length = length;
    entry->timestamp = time(NULL);
    table->buckets[index] = entry;
    table->size++;
    pthread_mutex_unlock(&table->lock);
}

void serialize_hash_table(HashTable* table, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }
    fwrite(&table->capacity, sizeof(size_t), 1, file);
    fwrite(&table->size, sizeof(size_t), 1, file);
    for (size_t i = 0; i < table->capacity; i++) {
        if (table->buckets[i] != NULL) {
            size_t key_length = strlen(table->buckets[i]->key);
            fwrite(&key_length, sizeof(size_t), 1, file);
            fwrite(table->buckets[i]->key, sizeof(char), key_length, file);
            fwrite(&table->buckets[i]->length, sizeof(size_t), 1, file);
            fwrite(&table->buckets[i]->timestamp, sizeof(time_t), 1, file);
        } else {
            size_t zero = 0;
            fwrite(&zero, sizeof(size_t), 1, file);
        }
    }
    fclose(file);
}

void deserialize_hash_table(HashTable* table, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file for reading");
        return;
    }
    size_t capacity, size;
    fread(&capacity, sizeof(size_t), 1, file);
    fread(&size, sizeof(size_t), 1, file);
    table->buckets = (Entry**)calloc(capacity, sizeof(Entry*));
    table->capacity = capacity;
    table->size = size;
    for (size_t i = 0; i < capacity; i++) {
        size_t key_length;
        fread(&key_length, sizeof(size_t), 1, file);
        if (key_length > 0) {
            Entry* entry = (Entry*)malloc(sizeof(Entry));
            entry->key = (char*)malloc(key_length + 1);
            fread(entry->key, sizeof(char), key_length, file);
            entry->key[key_length] = '\0';
            fread(&entry->length, sizeof(size_t), 1, file);
            fread(&entry->timestamp, sizeof(time_t), 1, file);
            table->buckets[i] = entry;
        }
    }
    fclose(file);
}

void free_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; i++) {
        if (table->buckets[i] != NULL) {
            free(table->buckets[i]->key);
            free(table->buckets[i]);
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}
