#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define TABLE_SIZE 10000
#define MAX_INVALID_ENTRIES (TABLE_SIZE * 0.05)
#define TEMP_STORAGE_LIMIT (TABLE_SIZE * 0.2)

typedef struct Entry {
    char* key;
    size_t length;
    time_t timestamp;
} Entry;

typedef struct HashTable {
    Entry** entries;
    int count;
    int capacity;
} HashTable;

HashTable* createHashTable() {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->entries = (Entry**)calloc(TABLE_SIZE, sizeof(Entry*));
    table->count = 0;
    table->capacity = TABLE_SIZE;
    return table;
}

unsigned int hashFunction(const char* key) {
    unsigned int hash = 5381;
    int c;
    while ((c = *key++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash % TABLE_SIZE;
}

void insertEntry(HashTable* table, const char* key, size_t length, time_t timestamp) {
    unsigned int index = hashFunction(key);
    while (table->entries[index] != NULL) {
        if (strcmp(table->entries[index]->key, key) == 0) {
            free(table->entries[index]->key);
            table->entries[index]->length = length;
            table->entries[index]->timestamp = timestamp;
            return;
        }
        index = (index + 1) % TABLE_SIZE;
    }
    if ((double)(table->count + 1) / table->capacity > 0.75) {
        // Rehashing logic here
    }
    Entry* newEntry = (Entry*)malloc(sizeof(Entry));
    newEntry->key = strdup(key);
    newEntry->length = length;
    newEntry->timestamp = timestamp;
    table->entries[index] = newEntry;
    table->count++;
}

Entry* getEntry(HashTable* table, const char* key) {
    unsigned int index = hashFunction(key);
    while (table->entries[index] != NULL) {
        if (strcmp(table->entries[index]->key, key) == 0) {
            return table->entries[index];
        }
        index = (index + 1) % TABLE_SIZE;
    }
    return NULL;
}

void freeHashTable(HashTable* table) {
    for (int i = 0; i < TABLE_SIZE; i++) {
        if (table->entries[i] != NULL) {
            free(table->entries[i]->key);
            free(table->entries[i]);
        }
    }
    free(table->entries);
    free(table);
}

int main() {
    HashTable* table = createHashTable();
    insertEntry(table, "example", 7, time(NULL));
    Entry* entry = getEntry(table, "example");
    if (entry != NULL) {
        printf("Key: %s, Length: %zu, Timestamp: %ld\n", entry->key, entry->length, entry->timestamp);
    }
    freeHashTable(table);
    return 0;
}
