#include <stdio.h>
#include <stdlib.h>
#include <math.h>

typedef struct {
    int x;
    int y;
} point;

typedef struct {
    point* p;
    double distance;
    char identifier;
} geometry;

double calculate_distance(point* p) {
    return sqrt(p->x * p->x + p->y * p->y);
}

int initialize_resources(int num_doubles, int char_size, int num_points, int num_geometries, point** points, char** chars, geometry** geometries, double reference_x, double reference_y) {
    // Allocate memory for arrays
    if ((*points = (point*)malloc(num_points * sizeof(point))) == NULL) {
        fprintf(stderr, "Memory allocation failed for points\n");
        return -1;
    }
    if ((*chars = (char*)malloc(char_size)) == NULL) {
        fprintf(stderr, "Memory allocation failed for chars\n");
        free(*points);
        return -1;
    }
    if ((*geometries = (geometry*)malloc(num_geometries * sizeof(geometry))) == NULL) {
        fprintf(stderr, "Memory allocation failed for geometries\n");
        free(*points);
        free(*chars);
        return -1;
    }

    // Initialize arrays
    for (int i = 0; i < num_points; i++) {
        (*points)[i].x = rand() % 100;
        (*points)[i].y = rand() % 100;
        (*geometries)[i].p = &(*points)[i];
        (*geometries)[i].distance = calculate_distance(&(*points)[i]);
        (*geometries)[i].identifier = 'A' + i % 26;
    }

    // Calculate distances from reference point
    for (int i = 0; i < num_points; i++) {
        double dx = (*points)[i].x - reference_x;
        double dy = (*points)[i].y - reference_y;
        (*geometries)[i].distance = sqrt(dx * dx + dy * dy);
    }

    return 0;
}

void free_resources(point* points, char* chars, geometry* geometries) {
    if (points != NULL) {
        free(points);
    }
    if (chars != NULL) {
        free(chars);
    }
    if (geometries != NULL) {
        free(geometries);
    }
}

int main() {
    int num_doubles = 10;
    int char_size = 256;
    int num_points = 5;
    int num_geometries = 5;

    point* points = NULL;
    char* chars = NULL;
    geometry* geometries = NULL;

    if (initialize_resources(num_doubles, char_size, num_points, num_geometries, &points, &chars, &geometries, 0.0, 0.0) == 0) {
        // Use resources
        for (int i = 0; i < num_geometries; i++) {
            printf("Point %d: (%d, %d), Distance from origin: %.2f\n", i, geometries[i].p->x, geometries[i].p->y, geometries[i].distance);
        }
    } else {
        fprintf(stderr, "Failed to initialize resources\n");
    }

    free_resources(points, chars, geometries);

    return 0;
}
