#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_NODES 1000
#define MAX_TRANSACTIONS 5000

typedef struct node {
    char label;
    struct node* next;
} Node;

typedef struct transaction {
    int timestamp;
    int id;
    double amount;
} Transaction;

typedef struct metadata {
    int access_count;
    int usage_pattern[MAX_NODES];
} Metadata;

Node* nodes[MAX_NODES] = {NULL};
Transaction transactions[MAX_TRANSACTIONS];
Metadata metadata[MAX_NODES];

pthread_mutex_t node_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t transaction_lock = PTHREAD_MUTEX_INITIALIZER;

int add_node(char label) {
    pthread_mutex_lock(&node_lock);
    for (int i = 0; i < MAX_NODES; i++) {
        if (nodes[i] == NULL) {
            nodes[i] = (Node*)malloc(sizeof(Node));
            if (nodes[i] == NULL) {
                pthread_mutex_unlock(&node_lock);
                return -1;
            }
            nodes[i]->label = label;
            nodes[i]->next = NULL;
            pthread_mutex_unlock(&node_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&node_lock);
    return -1;
}

int process_transaction(int id, double amount) {
    pthread_mutex_lock(&transaction_lock);
    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        if (transactions[i].id == 0) {
            transactions[i].id = id;
            transactions[i].amount = amount;
            transactions[i].timestamp = time(NULL);
            pthread_mutex_unlock(&transaction_lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&transaction_lock);
    return -1;
}

void* node_cleanup(void* arg) {
    int index = *(int*)arg;
    free(nodes[index]);
    nodes[index] = NULL;
    return NULL;
}

void remove_unused_nodes() {
    for (int i = 0; i < MAX_NODES; i++) {
        if (nodes[i] != NULL && metadata[i].access_count == 0) {
            pthread_t thread;
            int* index = (int*)malloc(sizeof(int));
            *index = i;
            pthread_create(&thread, NULL, node_cleanup, index);
            pthread_detach(thread);
        }
    }
}

void find_most_frequently_accessed_node() {
    Node* most_frequent = NULL;
    int max_count = 0;

    for (int i = 0; i < MAX_NODES; i++) {
        if (nodes[i] != NULL && metadata[i].access_count > max_count) {
            most_frequent = nodes[i];
            max_count = metadata[i].access_count;
        }
    }

    if (most_frequent != NULL) {
        printf("Most frequently accessed node: %c\n", most_frequent->label);
    } else {
        printf("No nodes available.\n");
    }
}

int main() {
    // Example usage
    add_node('A');
    process_transaction(1, 100.0);
    remove_unused_nodes();
    find_most_frequently_accessed_node();

    return 0;
}
