    private Configuration[] configurations;
    private Alert[] alerts;
    private Metrics[] metrics;

    public int initialize(int initialCapacity) {
        try {
            dataPoints = new DataPoint[initialCapacity];
            eventLogs = new EventLog[initialCapacity];
            configurations = new Configuration[initialCapacity];
            alerts = new Alert[initialCapacity];
            metrics = new Metrics[initialCapacity];
            return 0; // Success
        } catch (OutOfMemoryError e) {
            cleanup();
            return -1; // Memory allocation failed
        }
    }

    private void cleanup() {
        dataPoints = null;
        eventLogs = null;
        configurations = null;
        alerts = null;
        metrics = null;
    }

    public int resize(int newCapacity) {
        try {
            DataPoint[] newDataPoints = Arrays.copyOf(dataPoints, newCapacity);
            EventLog[] newEventLogs = Arrays.copyOf(eventLogs, newCapacity);
            Configuration[] newConfigurations = Arrays.copyOf(configurations, newCapacity);
            Alert[] newAlerts = Arrays.copyOf(alerts, newCapacity);
            Metrics[] newMetrics = Arrays.copyOf(metrics, newCapacity);

            dataPoints = newDataPoints;
            eventLogs = newEventLogs;
            configurations = newConfigurations;
            alerts = newAlerts;
            metrics = newMetrics;

            return 0; // Success
