        return -1; // Invalid input
    }

    *data = malloc(num_buffers * sizeof(CustomData));
    if (*data == NULL) {
        return -2; // Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < num_buffers; ++i) {
        size_t buffer_size = min_size + rand() % (max_size - min_size + 1);
        (*data)[i].buffer = malloc(buffer_size);
        if ((*data)[i].buffer == NULL) {
            // Free previously allocated buffers
            for (size_t j = 0; j < i; ++j) {
                free((*data)[j].buffer);
            }
            free(*data);
            return -2; // Memory allocation failed
        }

        (*data)[i].size = buffer_size;
        // Initialize buffer with unique random byte pattern
        for (size_t j = 0; j < buffer_size; ++j) {
            (*data)[i].buffer[j] = rand() % 256;
        }
    }

    return 0; // Success
}

void free_custom_data(CustomData* data, size_t num_buffers) {
