#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    unsigned char* buffer;
    size_t size;
} CustomData;

unsigned long hash(unsigned char* data, size_t length) {
    unsigned long hash = 5381;
    for (size_t i = 0; i < length; ++i) {
        hash = ((hash << 5) + hash) + data[i];
    }
    return hash;
}

int allocate_buffers(CustomData** buffers, size_t num_buffers, size_t* buffer_sizes) {
    *buffers = malloc(num_buffers * sizeof(CustomData));
    if (*buffers == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    for (size_t i = 0; i < num_buffers; ++i) {
        (*buffers)[i].buffer = malloc(buffer_sizes[i]);
        if ((*buffers)[i].buffer == NULL) {
            fprintf(stderr, "Memory allocation failed for buffer %zu\n", i);
            // Free previously allocated buffers
            for (size_t j = 0; j < i; ++j) {
                free((*buffers)[j].buffer);
            }
            free(*buffers);
            return -1;
        }

        (*buffers)[i].size = buffer_sizes[i];
        srand(time(NULL));
        for (size_t j = 0; j < buffer_sizes[i]; ++j) {
            (*buffers)[i].buffer[j] = rand() % 256;
        }

        unsigned long hash_value = hash((*buffers)[i].buffer, buffer_sizes[i]);
        printf("Buffer %zu allocated with size %zu and hash %lu\n", i, buffer_sizes[i], hash_value);
    }

    return 0;
}

void free_buffers(CustomData* buffers, size_t num_buffers) {
    for (size_t i = 0; i < num_buffers; ++i) {
        free(buffers[i].buffer);
    }
    free(buffers);
}

int main() {
    size_t buffer_sizes[] = {1024, 2048, 4096};
    CustomData* buffers;
    int result = allocate_buffers(&buffers, sizeof(buffer_sizes) / sizeof(buffer_sizes[0]), buffer_sizes);
    if (result == 0) {
        free_buffers(buffers, sizeof(buffer_sizes) / sizeof(buffer_sizes[0]));
    }
    return 0;
}
