#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define the structure for a node in the BST
typedef struct Node {
    char* key;
    int value;
    struct Node* left;
    struct Node* right;
} Node;

// Function to create a new node with given key and value
Node* createNode(char* key, int value) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    newNode->key = strdup(key);
    newNode->value = value;
    newNode->left = NULL;
    newNode->right = NULL;
    return newNode;
}

// Function to insert a node into the BST
Node* insertNode(Node* root, char* key, int value) {
    if (root == NULL) {
        return createNode(key, value);
    }
    if (strcmp(key, root->key) < 0) {
        root->left = insertNode(root->left, key, value);
    } else if (strcmp(key, root->key) > 0) {
        root->right = insertNode(root->right, key, value);
    }
    return root;
}

// Function to find the minimum value in the BST
int minValue(Node* node) {
    while (node->left != NULL) {
        node = node->left;
    }
    return node->value;
}

// Function to find the maximum value in the BST
int maxValue(Node* node) {
    while (node->right != NULL) {
        node = node->right;
    }
    return node->value;
}

// Function to free the memory allocated for the BST
void freeBST(Node* root) {
    if (root != NULL) {
        freeBST(root->left);
        freeBST(root->right);
        free(root->key);
        free(root);
    }
}

int main() {
    srand(time(NULL));
    Node* root = NULL;
    int max_size = 100;

    // Insert nodes into the BST
    for (int i = 0; i < max_size; i++) {
        char key[20];
        sprintf(key, "key%d", i);
        int value = rand() % 1000;
        root = insertNode(root, key, value);
    }

    // Find and print the minimum and maximum values
    printf("Minimum value: %d\n", minValue(root));
    printf("Maximum value: %d\n", maxValue(root));

    // Free the memory allocated for the BST
    freeBST(root);

    return 0;
}
