    for (int i = 0; i < size; i++) {
        records[i].value = rand() % (upper_bound + 1);
    }
}

int find_largest_integer(int* array, int size) {
    int max = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

void free_memory(int* int_array, record* record_array) {
    free(int_array);
    free(record_array);
}

int main() {
    srand(time(NULL));

    int size = 10;
    int upper_bound = 100;

    int* int_array = allocate_int_array(size);
    if (int_array == NULL) {
        fprintf(stderr, "Memory allocation failed for integer array\n");
        return 1;
    }

    record* record_array = allocate_record_array(size);
    if (record_array == NULL) {
        free_memory(int_array, NULL);
        fprintf(stderr, "Memory allocation failed for record array\n");
        return 1;
    }

    initialize_records(record_array, size, upper_bound);

    int largest_integer = find_largest_integer(int_array, size);
    printf("Largest integer: %d\n", largest_integer);

    free_memory(int_array, record_array);

    return 0;
}
