['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Node {
    char *key;
    double value;
    struct Node *next;
} Node;

Node* create_node(const char *key, double value) {
    Node *new_node = (Node *)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->key = strdup(key);
    new_node->value = value;
    new_node->next = NULL;
    return new_node;
}

void free_node(Node *node) {
    free(node->key);
    free(node);
}

Node* init_distributed_list(int num_nodes, double min_value, double max_value) {
    Node *head = NULL;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < num_nodes; ++i) {
        double value = min_value + (max_value - min_value) * ((double)rand() / RAND_MAX);
        Node *new_node = create_node("key", value);

        if (!new_node) {
            // Handle memory allocation failure
            pthread_mutex_lock(&lock);
            while (head != NULL) {
                Node *temp = head;
                head = head->next;
                free_node(temp);
            }
            pthread_mutex_unlock(&lock);
            return NULL;
        }

        pthread_mutex_lock(&lock);
        new_node->next = head;
        head = new_node;
        pthread_mutex_unlock(&lock);
    }

    pthread_mutex_destroy(&lock);
    return head;
}

void print_largest_value(Node *head) {
    double max_value = -1.0;
    while (head != NULL) {
        if (head->value > max_value) {
            max_value = head->value;
        }
        head = head->next;
    }
    printf("Largest value: %f\n", max_value);
}

int main() {
    int num_nodes = 10;
    Node *list = init_distributed_list(num_nodes, 0.0, 100.0);
    if (list != NULL) {
        print_largest_value(list);
        // Clean up the list
        while (list != NULL) {
            Node *temp = list;
            list = list->next;
            free_node(temp);
        }
    } else {
        printf("Failed to initialize distributed list.\n");
    }
    return 0;
}
```

