#define MAX_STRING_LENGTH 256

typedef struct {
    long offset;
} OffsetStruct;

typedef struct {
    int key;
} KeyStruct;

typedef struct {
    int value;
} RecordStruct;

typedef struct {
    char *identifier;
} IdentifierStruct;

int allocate_and_initialize(int size, int max_string_length) {
    OffsetStruct *offsets = (OffsetStruct *)malloc(size * sizeof(OffsetStruct));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        return -1;
    }

    KeyStruct *keys = (KeyStruct *)malloc(size * sizeof(KeyStruct));
    if (!keys) {
        free(offsets);
        fprintf(stderr, "Memory allocation failed for keys\n");
        return -1;
    }

    RecordStruct *records = (RecordStruct *)malloc(size * sizeof(RecordStruct));
    if (!records) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Memory allocation failed for records\n");
        return -1;
    }

    IdentifierStruct *identifiers = (IdentifierStruct *)malloc(size * sizeof(IdentifierStruct));
    if (!identifiers) {
        free(offsets);
        free(keys);
        free(records);
        fprintf(stderr, "Memory allocation failed for identifiers\n");
        return -1;
    }

    srand(time(NULL));

    for (int i = 0; i < size; i++) {
        offsets[i].offset = rand();
        keys[i].key = rand() % max_string_length;
        records[i].value = rand() % max_string_length;
        identifiers[i].identifier = (char *)malloc(max_string_length * sizeof(char));
        if (!identifiers[i].identifier) {
            for (int j = 0; j < i; j++) {
                free(identifiers[j].identifier);
            }
            free(offsets);
            free(keys);
            free(records);
            free(identifiers);
            fprintf(stderr, "Memory allocation failed for identifier at index %d\n", i);
            return -1;
        }
        snprintf(identifiers[i].identifier, max_string_length, "Identifier%d", i);
    }

    // Simulate external data service write
    int success = 0;
    while (!success) {
        // Attempt to write data to external service
        if (write_to_external_service(offsets, keys, records, identifiers, size)) {
            success = 1;
        } else {
            // Handle transient failure and retry with exponential backoff
            sleep(2);
        }
    }

    for (int i = 0; i < size; i++) {
        free(identifiers[i].identifier);
    }
    free(offsets);
    free(keys);
    free(records);
    free(identifiers);

    return 0;
}

int write_to_external_service(OffsetStruct *offsets, KeyStruct *keys, RecordStruct *records, IdentifierStruct *identifiers, int size) {
    // Simulate network latency and transient failure
    if (rand() % 2 == 0) {
        fprintf(stderr, "Transient failure writing to external service\n");
        return 0;
    }
    // Simulate successful write
    for (int i = 0; i < size; i++) {
        printf("Writing data: offset=%ld, key=%d, value=%d, identifier=%s\n", offsets[i].offset, keys[i].key, records[i].value, identifiers[i].identifier);
    }
    return 1;
}
