    long offset;
    int key;
    Record record;
} FirstCollectionRecord;

typedef struct {
    int key;
    char* value;
} SecondCollectionRecord;

int initializeCollections(FirstCollectionRecord** firstCollection, SecondCollectionRecord** secondCollection) {
    srand(time(NULL));

    *firstCollection = (FirstCollectionRecord*)malloc(MAX_RECORDS * sizeof(FirstCollectionRecord));
    if (*firstCollection == NULL) {
        return -1; // Memory allocation failed
    }

    *secondCollection = (SecondCollectionRecord*)malloc(MAX_RECORDS * sizeof(SecondCollectionRecord));
    if (*secondCollection == NULL) {
        free(*firstCollection);
        return -1; // Memory allocation failed
    }

    for (int i = 0; i < MAX_RECORDS; i++) {
        (*firstCollection)[i].offset = i * sizeof(FirstCollectionRecord);
        (*firstCollection)[i].key = rand() % 1000;
        (*firstCollection)[i].record.value = rand() % 1000;

        int key = rand() % 1000;
        char* value = (char*)malloc(MAX_STRING_LENGTH * sizeof(char));
        if (value == NULL) {
            free(*firstCollection);
            free(*secondCollection);
            return -1; // Memory allocation failed
        }
        snprintf(value, MAX_STRING_LENGTH, "String%d", key);
        (*secondCollection)[i].key = key;
        (*secondCollection)[i].value = value;
    }

    return 0; // Initialization successful
}

void freeCollections(FirstCollectionRecord* firstCollection, SecondCollectionRecord* secondCollection) {
    for (int i = 0; i < MAX_RECORDS; i++) {
        free(secondCollection[i].value);
