['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 16
#define LOAD_FACTOR_THRESHOLD 0.75

typedef struct {
    int value;
    void* nested_table; // Pointer to another hash table for nested storage
} ValueStruct;

typedef struct Node {
    char* key;
    ValueStruct value;
    struct Node* next;
} Node;

typedef struct {
    Node** buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

unsigned long hash(const char* str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash % capacity;
}

HashTable* create_hash_table() {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) {
        return NULL;
    }

    table->buckets = (Node**)calloc(INITIAL_CAPACITY, sizeof(Node*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }

    table->capacity = INITIAL_CAPACITY;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);

    return table;
}

void destroy_hash_table(HashTable* table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        Node* node = table->buckets[i];
        while (node) {
            Node* next = node->next;
            free(node->key);
            free(node);
            node = next;
        }
    }

    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

int insert(HashTable* table, const char* key, int value) {
    pthread_mutex_lock(&table->lock);

    size_t index = hash(key);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&table->lock);
        return -1;
    }

    new_node->key = strdup(key);
    new_node->value.value = value;
    new_node->value.nested_table = NULL; // Initialize nested table pointer
    new_node->next = table->buckets[index];
    table->buckets[index] = new_node;

    table->size++;

    if ((double)table->size / table->capacity > LOAD_FACTOR_THRESHOLD) {
        resize_hash_table(table);
    }

    pthread_mutex_unlock(&table->lock);
    return 0;
}

void resize_hash_table(HashTable* table) {
    size_t old_capacity = table->capacity;
    Node** old_buckets = table->buckets;

    table->capacity *= 2;
    table->buckets = (Node**)calloc(table->capacity, sizeof(Node*));
    if (!table->buckets) {
        // Handle memory allocation failure
        return;
    }

    for (size_t i = 0; i < old_capacity; ++i) {
        Node* node = old_buckets[i];
        while (node) {
            Node* next = node->next;
            size_t new_index = hash(node->key);
            node->next = table->buckets[new_index];
            table->buckets[new_index] = node;
            node = next;
        }
    }

    free(old_buckets);
}

int get(HashTable* table, const char* key) {
    pthread_mutex_lock(&table->lock);

    size_t index = hash(key);
    Node* node = table->buckets[index];
    while (node) {
        if (strcmp(node->key, key) == 0) {
            int value = node->value.value;
            pthread_mutex_unlock(&table->lock);
            return value;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&table->lock);
    return -1; // Key not found
}

int main() {
    HashTable* table = create_hash_table();
    if (!table) {
        fprintf(stderr, "Failed to create hash table\n");
        return 1;
    }

    for (size_t i = 0; i < 1000000; ++i) {
        char key[20];
        snprintf(key, sizeof(key), "key%d", i);
        if (insert(table, key, rand() % 1000) != 0) {
            fprintf(stderr, "Failed to insert key-value pair\n");
            destroy_hash_table(table);
            return 1;
        }
    }

    // Perform retrieval and other operations...

    destroy_hash_table(table);
    return 0;
}
```

This code provides a basic implementation of a scalable hash table in C. It includes functions for creating, destroying, inserting, and retrieving key-value pairs. The hash table dynamically resizes itself when the load factor exceeds a predefined threshold to maintain optimal performance. The `main` function demonstrates how to use the hash table by inserting 1 million random key-value pairs.']

