} IdentifierStruct;

typedef struct {
    time_t timestamp;
} TimestampStruct;

void log_error(const char *message) {
    // Implement error logging mechanism
}

int allocate_memory(OffsetStruct **offsets, KeyStruct **keys, RecordStruct **records, IdentifierStruct **identifiers, TimestampStruct **timestamps, int size, int max_string_length) {
    *offsets = (OffsetStruct *)malloc(size * sizeof(OffsetStruct));
    *keys = (KeyStruct *)malloc(size * sizeof(KeyStruct));
    *records = (RecordStruct *)malloc(size * sizeof(RecordStruct));
    *identifiers = (IdentifierStruct *)malloc(size * sizeof(IdentifierStruct));
    *timestamps = (TimestampStruct *)malloc(size * sizeof(TimestampStruct));

    if (!*offsets || !*keys || !*records || !*identifiers || !*timestamps) {
        log_error("Memory allocation failed");
        return -1;
    }

    for (int i = 0; i < size; i++) {
        (*records)[i].record = (record_struct *)malloc(sizeof(record_struct));
        if (!(*records)[i].record) {
            log_error("Record memory allocation failed");
            free_memory(offsets, keys, records, identifiers, timestamps, i);
            return -1;
        }
    }

    for (int i = 0; i < size; i++) {
        (*identifiers)[i].identifier = (char *)malloc(max_string_length * sizeof(char));
        if (!(*identifiers)[i].identifier) {
            log_error("Identifier memory allocation failed");
            free_memory(offsets, keys, records, identifiers, timestamps, i);
            return -1;
        }
    }

    return 0;
}

void initialize_data(OffsetStruct *offsets, KeyStruct *keys, RecordStruct *records, IdentifierStruct *identifiers, TimestampStruct *timestamps, int size, int max_string_length) {
    srand(time(NULL));

    for (int i = 0; i < size; i++) {
        offsets[i].offset = rand();
        keys[i].key = rand() % 1000;
        records[i].record->value = rand() % 1000;
        snprintf(identifiers[i].identifier, max_string_length, "Record%d", i);
        timestamps[i].timestamp = time(NULL);
    }
}

void free_memory(OffsetStruct **offsets, KeyStruct **keys, RecordStruct **records, IdentifierStruct **identifiers, TimestampStruct **timestamps, int size) {
    for (int i = 0; i < size; i++) {
        free((*records)[i].record);
        free((*identifiers)[i].identifier);
    }

    free(*offsets);
    free(*keys);
    free(*records);
    free(*identifiers);
    free(*timestamps);
}

void log_data(OffsetStruct *offsets, KeyStruct *keys, RecordStruct *records, IdentifierStruct *identifiers, TimestampStruct *timestamps, int size) {
    for (int i = 0; i < size; i++) {
        printf("Record %d: Offset=%ld, Key=%d, Value=%d, Identifier=%s, Timestamp=%ld\n", i, offsets[i].offset, keys[i].key, records[i].record->value, identifiers[i].identifier, timestamps[i].timestamp);
    }
}

int main() {
    int size = 5;
    int max_string_length = MAX_STRING_LENGTH;

    OffsetStruct *offsets;
    KeyStruct *keys;
    RecordStruct *records;
    IdentifierStruct *identifiers;
    TimestampStruct *timestamps;

    if (allocate_memory(&offsets, &keys, &records, &identifiers, &timestamps, size, max_string_length) == 0) {
        initialize_data(offsets, keys, records, identifiers, timestamps, size, max_string_length);
        log_data(offsets, keys, records, identifiers, timestamps, size);
        free_memory(&offsets, &keys, &records, &identifiers, &timestamps, size);
    }

    return 0;
}
