#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
} Node;

Node* create_node(Record data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void insert_node(Node** head, Record data) {
    Node* new_node = create_node(data);
    if (new_node == NULL) {
        return;
    }
    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
}

void free_list(Node** head) {
    Node* current = *head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int main() {
    srand(time(0));
    int num_records = 10;
    Node* record_list = NULL;

    for (int i = 0; i < num_records; i++) {
        Record data;
        data.value = rand() % 100; // Random value between 0 and 99
        insert_node(&record_list, data);
    }

    // Process the record list...

    free_list(&record_list);

    return 0;
}
