#include <stdio.h>
#include <stdlib.h>

// Define the structure for an edge
typedef struct Edge {
    int node1;
    int node2;
    int weight;
    struct Edge* next;
} Edge;

// Define the structure for a node
typedef struct Node {
    int id;
    Edge* edges;
} Node;

// Function to create a new edge
Edge* createEdge(int node1, int node2, int weight) {
    Edge* newEdge = (Edge*)malloc(sizeof(Edge));
    if (newEdge == NULL) {
        fprintf(stderr, "Memory allocation failed for edge\n");
        exit(EXIT_FAILURE);
    }
    newEdge->node1 = node1;
    newEdge->node2 = node2;
    newEdge->weight = weight;
    newEdge->next = NULL;
    return newEdge;
}

// Function to add an edge to a node
void addEdge(Node* node, int node2, int weight) {
    Edge* newEdge = createEdge(node->id, node2, weight);
    if (node->edges == NULL) {
        node->edges = newEdge;
    } else {
        Edge* current = node->edges;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newEdge;
    }
}

// Function to remove an edge from a node
void removeEdge(Node* node, int node2) {
    if (node->edges == NULL) return;

    Edge* current = node->edges;
    Edge* previous = NULL;

    while (current != NULL) {
        if (current->node2 == node2) {
            if (previous == NULL) {
                node->edges = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            return;
        }
        previous = current;
        current = current->next;
    }
}

// Function to update the weight of an edge
void updateEdgeWeight(Node* node, int node2, int newWeight) {
    Edge* current = node->edges;
    while (current != NULL) {
        if (current->node2 == node2) {
            current->weight = newWeight;
            return;
        }
        current = current->next;
    }
}

// Function to calculate the total weight of edges connected to a node
int getTotalEdgeWeight(Node* node) {
    int totalWeight = 0;
    Edge* current = node->edges;
    while (current != NULL) {
        totalWeight += current->weight;
        current = current->next;
    }
    return totalWeight;
}

// Function to free the memory allocated for a node
void freeNode(Node* node) {
    Edge* current = node->edges;
    while (current != NULL) {
        Edge* next = current->next;
        free(current);
        current = next;
    }
    free(node);
}
