typedef struct {
    int* values;
    char** buffers;
    size_t count;
} RecordSet;

RecordSet* allocate_records(size_t num_records, int value_range_start, int value_range_end, unsigned long seed, int enable_logging, int enable_profiling) {
    // Allocate memory for the record set
    RecordSet* records = (RecordSet*)malloc(sizeof(RecordSet));
    if (!records) {
        return NULL;
    }

    records->count = num_records;
    records->values = (int*)calloc(num_records, sizeof(int));
    records->buffers = (char**)calloc(num_records, sizeof(char*));

    if (!records->values || !records->buffers) {
        free(records);
        return NULL;
    }

    // Initialize random number generator
    srand(seed);

    // Allocate and initialize character buffers
    for (size_t i = 0; i < num_records; ++i) {
        records->buffers[i] = (char*)malloc(128 * sizeof(char));
        if (!records->buffers[i]) {
            for (size_t j = 0; j < i; ++j) {
                free(records->buffers[j]);
            }
            free(records->values);
            free(records);
            return NULL;
        }

        // Generate unique ASCII string based on index and seed
        snprintf(records->buffers[i], 128, "Record %zu", i);

        // Set integer field to random value within the specified range
        records->values[i] = rand() % (value_range_end - value_range_start + 1) + value_range_start;
    }

    return records;
}

void free_records(RecordSet* records) {
    if (!records) {
        return;
    }

    for (size_t i = 0; i < records->count; ++i) {
        free(records->buffers[i]);
    }
    free(records->values);
    free(records->buffers);
    free(records);
}
