    fscanf(file, "%d", num_structs);
    fclose(file);

    return 0;
}

MyStruct* allocate_memory(int num_structs) {
    MyStruct *array = (MyStruct*)malloc(num_structs * sizeof(MyStruct));
    if (!array) return NULL;

    for (int i = 0; i < num_structs; i++) {
        array[i].identifier = (char*)malloc(256);
        if (!array[i].identifier) {
            free_memory(array, i);
            return NULL;
        }
    }

    return array;
}

void initialize_structures(MyStruct *array, int num_structs, int upper_bound) {
    srand(time(NULL));
    for (int i = 0; i < num_structs; i++) {
        array[i].offset = rand();
        array[i].key = rand() % upper_bound;
        array[i].rec.value = rand() % upper_bound;
        snprintf(array[i].identifier, 256, "Record%d", i);
    }
}

void free_memory(MyStruct *array, int num_structs) {
    for (int i = 0; i < num_structs; i++) {
        free(array[i].identifier);
    }
    free(array);
}

int find_largest_integer(int *array, int size) {
    if (size <= 0) return -1;
    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) largest = array[i];
    }
    return largest;
}

void log_error(const char *message) {
