    int size;
    printf("Enter the number of integers: ");
    scanf("%d", &size);
    int *integers = (int*)malloc(size * sizeof(int));
    if (!integers) {
        log_error("Memory allocation failed.");
        free_memory(array, num_structs);
        return -1;
    }

    printf("Enter %d integers:\n", size);
    for (int i = 0; i < size; i++) {
        scanf("%d", &integers[i]);
    }

    int largest = find_largest_integer(integers, size);
    if (largest != -1) {
        printf("The largest integer is: %d\n", largest);
    } else {
        log_error("Failed to find the largest integer.");
    }

    free(integers);
    free_memory(array, num_structs);

    return 0;
}
