#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000
#define MAX_CONNECTIONS 500

typedef struct {
    int ip;
    int port;
    char status[20];
    time_t last_seen;
} NetworkConnection;

typedef struct {
    long offset;
    int key;
    record rec;
    NetworkConnection conn;
} Component;

int* read_integers(int *count) {
    int *array = NULL;
    char line[1024];
    printf("Enter integers separated by spaces: ");
    fgets(line, sizeof(line), stdin);
    char *token = strtok(line, " ");
    *count = 0;
    while (token != NULL) {
        (*count)++;
        array = realloc(array, (*count) * sizeof(int));
        if (array == NULL) {
            perror("Memory allocation failed");
            free(array);
            return NULL;
        }
        array[(*count) - 1] = atoi(token);
        token = strtok(NULL, " ");
    }
    return array;
}

int find_largest(int *array, int count) {
    if (count == 0) {
        fprintf(stderr, "Array is empty\n");
        return -1;
    }
    int largest = array[0];
    for (int i = 1; i < count; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

void initialize_components(Component *components, int record_count, int connection_count) {
    srand(time(NULL));
    for (int i = 0; i < record_count; i++) {
        components[i].offset = rand();
        components[i].key = rand() % 1000;
        // Initialize other fields as needed
    }
    for (int i = 0; i < connection_count; i++) {
        components[i + record_count].conn.ip = rand() & 0xFFFFFFFF;
        components[i + record_count].conn.port = rand() % 65536;
        strcpy(components[i + record_count].conn.status, "Active");
        components[i + record_count].conn.last_seen = time(NULL);
    }
}

int main() {
    int record_count, connection_count;
    Component *components = NULL;

    int *array = read_integers(&record_count);
    if (array == NULL) {
        return 1;
    }

    int largest = find_largest(array, record_count);
    printf("Largest integer: %d\n", largest);

    components = malloc((record_count + connection_count) * sizeof(Component));
    if (components == NULL) {
        perror("Memory allocation failed");
        free(array);
        return 1;
    }

    initialize_components(components, record_count, connection_count);

    // Free allocated memory
    free(array);
    free(components);

    return 0;
}
