int allocate_and_initialize_pipeline(size_t size, int max_record_value, int enable_logging) {
    DataPipeline* pipeline = (DataPipeline*)malloc(sizeof(DataPipeline));
    if (!pipeline) {
        if (enable_logging) {
            printf("Memory allocation failed for pipeline\n");
        }
        return -1;
    }

    pipeline->offsets = (long*)calloc(size, sizeof(long));
    pipeline->keys = (int*)calloc(size, sizeof(int));
    pipeline->records = (Record*)malloc(size * sizeof(Record));
    pipeline->metadata = (Metadata*)malloc(sizeof(Metadata));

    if (!pipeline->offsets || !pipeline->keys || !pipeline->records || !pipeline->metadata) {
        free(pipeline->offsets);
        free(pipeline->keys);
        free(pipeline->records);
        free(pipeline->metadata);
        free(pipeline);
        if (enable_logging) {
            printf("Memory allocation failed for pipeline components\n");
        }
        return -1;
    }

    pthread_mutex_init(&pipeline->lock, NULL);

    // Initialize records with random values within the specified range
    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        pipeline->records[i].value = rand() % max_record_value;
        pipeline->records[i].timestamp = time(NULL);
        pipeline->records[i].status_flag = 'A' + rand() % 26;
        pipeline->records[i].version = rand() % 100;
    }

    // Initialize other components as needed

    pipeline->size = size;

    return 0;
}

void free_pipeline(DataPipeline* pipeline) {
    if (pipeline) {
        pthread_mutex_destroy(&pipeline->lock);
        free(pipeline->offsets);
        free(pipeline->keys);
        free(pipeline->records);
        free(pipeline->metadata);
        free(pipeline);
    }
}
