['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef enum {
    STATUS_PENDING,
    STATUS_COMPLETED,
    STATUS_FAILED
} TransactionStatus;

typedef struct Transaction {
    time_t timestamp;
    TransactionStatus status;
    char *description;
    int id;
} Transaction;

typedef struct TransactionManager {
    Transaction **transactions;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} TransactionManager;

TransactionManager* create_transaction_manager(size_t initial_capacity) {
    TransactionManager *manager = malloc(sizeof(TransactionManager));
    if (!manager) {
        perror("Failed to allocate memory for transaction manager");
        return NULL;
    }
    manager->transactions = malloc(initial_capacity * sizeof(Transaction *));
    if (!manager->transactions) {
        perror("Failed to allocate memory for transactions array");
        free(manager);
        return NULL;
    }
    manager->capacity = initial_capacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_transaction_manager(TransactionManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->transactions[i]->description);
        free(manager->transactions[i]);
    }
    free(manager->transactions);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_transaction(TransactionManager *manager, time_t timestamp, TransactionStatus status, const char *description, int id) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count == manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 1;
        Transaction **new_transactions = realloc(manager->transactions, new_capacity * sizeof(Transaction *));
        if (!new_transactions) {
            perror("Failed to reallocate memory for transactions array");
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->transactions = new_transactions;
        manager->capacity = new_capacity;
    }
    Transaction *transaction = malloc(sizeof(Transaction));
    if (!transaction) {
        perror("Failed to allocate memory for transaction");
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    transaction->timestamp = timestamp;
    transaction->status = status;
    transaction->description = strdup(description);
    if (!transaction->description) {
        perror("Failed to allocate memory for description");
        free(transaction);
        pthread_mutex_unlock(&manager->lock);
        return -1;
    }
    transaction->id = id;
    manager->transactions[manager->count++] = transaction;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

Transaction* get_transaction(TransactionManager *manager, int id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->transactions[i]->id == id) {
            pthread_mutex_unlock(&manager->lock);
            return manager->transactions[i];
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

// Serialization and deserialization functions would go here
