typedef struct {
    int value;
    char* identifier;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record* records;
    size_t num_offsets;
    size_t num_records;
} data_structure;

data_structure* create_data_structure(size_t num_offsets, size_t num_records, int min_value, int max_value) {
    if (num_offsets == 0 || num_records == 0 || min_value > max_value) {
        return NULL; // Invalid input
    }

    data_structure* ds = (data_structure*)malloc(sizeof(data_structure));
    if (!ds) {
        return NULL; // Memory allocation failed
    }

    ds->offsets = (long*)calloc(num_offsets, sizeof(long));
    ds->keys = (int*)calloc(num_offsets, sizeof(int));
    ds->records = (record*)calloc(num_records, sizeof(record));
    ds->num_offsets = num_offsets;
    ds->num_records = num_records;

    if (!ds->offsets || !ds->keys || !ds->records) {
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        free(ds);
        return NULL; // Memory allocation failed
    }

    srand(time(NULL));
    for (size_t i = 0; i < num_offsets; ++i) {
        ds->offsets[i] = rand() % (max_value - min_value + 1) + min_value;
        ds->keys[i] = i; // Ensure non-repeating keys
    }

    for (size_t i = 0; i < num_records; ++i) {
        ds->records[i].value = rand() % (max_value - min_value + 1) + min_value;
        ds->records[i].identifier = (char*)malloc(256 * sizeof(char));
        if (!ds->records[i].identifier) {
            for (size_t j = 0; j < i; ++j) {
                free(ds->records[j].identifier);
            }
            free(ds->offsets);
            free(ds->keys);
            free(ds->records);
            free(ds);
            return NULL; // Memory allocation failed
        }
        snprintf(ds->records[i].identifier, 256, "user%d", i); // Example identifier format
    }

    return ds;
}

void print_records(data_structure* ds) {
    if (!ds) {
        return;
    }

    for (size_t i = 0; i < ds->num_records; ++i) {
        printf("Record %zu: Identifier=%s, Value=%d\n", i, ds->records[i].identifier, ds->records[i].value);
    }
}

void free_data_structure(data_structure* ds) {
    if (!ds) {
        return;
    }

    for (size_t i = 0; i < ds->num_records; ++i) {
        free(ds->records[i].identifier);
    }

    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    free(ds);
}
