const AWS = require('aws-sdk');
const GoogleCloudStorage = require('@google-cloud/storage');

async function listAndDownloadFiles(bucketName, filter, pageSize, pageToken) {
  const storageClients = {
    aws: new AWS.S3(),
    google: new GoogleCloudStorage()
  };

  let files = [];
  let nextPageToken;

  for (const [service, client] of Object.entries(storageClients)) {
    try {
      let response;
      if (service === 'aws') {
        response = await client.listObjectsV2({
          Bucket: bucketName,
          Prefix: filter,
          MaxKeys: pageSize,
          ContinuationToken: pageToken
        });
      } else if (service === 'google') {
        response = await client.bucket(bucketName).getFiles({
          prefix: filter,
          maxResults: pageSize,
          pageToken: pageToken
        });
      }

      files = files.concat(response.contents || response[0]);
      nextPageToken = response.NextContinuationToken || response.nextPageToken;
    } catch (error) {
      console.error(`Error fetching files from ${service}:`, error);
