char* normalizeAndAppendSlash(const char* path, size_t maxSize, DataSource* dataSource, bool shouldNormalize) {
    if (strlen(path) >= maxSize - 1) {
        return NULL;
    }

    char* normalizedPath = malloc(maxSize);
    if (!normalizedPath) {
        return NULL;
    }

    if (shouldNormalize) {
        // Normalize path separators and remove redundant separators
        strcpy(normalizedPath, path);
    } else {
        strncpy(normalizedPath, path, maxSize - 1);
        normalizedPath[maxSize - 1] = '\0';
    }

    size_t len = strlen(normalizedPath);
    if (len > 0 && normalizedPath[len - 1] != '/') {
        normalizedPath[len++] = '/';
        normalizedPath[len] = '\0';
    }

    for (char* token = strtok(normalizedPath, "/"); token; token = strtok(NULL, "/")) {
        if (!isValidPathSegment(token, dataSource)) {
            free(normalizedPath);
            return NULL;
        }
    }

    return normalizedPath;
}
