public class MessageProcessor
{
    private readonly IKeyManagementService _kms;
    private readonly ConcurrentDictionary<string, byte[]> _keyCache = new();
    private readonly ConcurrentDictionary<string, byte[]> _ivCache = new();

    public MessageProcessor(IKeyManagementService kms)
    {
        _kms = kms;
    }

    public async Task<string> ProcessMessageAsync(string base64Message, string metadata, CancellationToken cancellationToken)
    {
        try
        {
            var messageParts = metadata.Split(',');
            var algorithm = messageParts[0];
            var keyId = messageParts[1];
            var ivId = messageParts.Length > 2 ? messageParts[2] : null;
            var iterations = int.Parse(messageParts[3]);
            var hmacKey = Encoding.UTF8.GetBytes("hmacSecret");

            byte[] key, iv;
            if (_keyCache.TryGetValue(keyId, out key))
            {
                // Key is in cache
            }
            else
            {
                key = await _kms.GetKeyAsync(keyId, cancellationToken);
                _keyCache.TryAdd(keyId, key);
            }

            if (iv != null && _ivCache.TryGetValue(ivId, out iv))
            {
                // IV is in cache
            }
            else
            {
                iv = await _kms.GetIVAsync(ivId, cancellationToken);
                _ivCache.TryAdd(ivId, iv);
            }

            byte[] messageBytes = Convert.FromBase64String(base64Message);
            byte[] decryptedBytes;

            using (var decryptor = CreateDecryptor(algorithm, key, iv))
            {
                decryptedBytes = await Task.Run(() => decryptor.Decrypt(messageBytes), cancellationToken);
            }

            var hmac = new HMACSHA256(hmacKey);
            var computedHmac = hmac.ComputeHash(decryptedBytes);

            if (!computedHmac.SequenceEqual(messageBytes.Skip(decryptedBytes.Length)))
            {
                // HMAC verification failed
                return null;
            }

            return Encoding.UTF8.GetString(decryptedBytes);
        }
        catch (Exception ex)
        {
            // Log error and return null
            Console.WriteLine($"Error processing message: {ex.Message}");
            return null;
        }
    }

    private ICryptoTransform CreateDecryptor(string algorithm, byte[] key, byte[] iv)
    {
        switch (algorithm)
        {
            case "TripleDES":
                return new TripleDESCryptoServiceProvider { Key = key, IV = iv }.CreateDecryptor();
            case "AES":
                return Aes.Create().CreateDecryptor(key, iv);
            case "RSA":
                // Implement RSA decryption
                throw new NotSupportedException("RSA decryption is not supported.");
            default:
                throw new ArgumentException("Unsupported encryption algorithm.");
        }
    }
}
