#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_MEMORY_USAGE 1024 * 1024 // 1 MB
#define MAX_RECORDS 10000

typedef struct {
    int value;
} record;

void* allocate_and_initialize_memory(void* arg) {
    long* offsets = (long*)malloc(MAX_MEMORY_USAGE);
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        return NULL;
    }

    int* keys = (int*)malloc(MAX_MEMORY_USAGE);
    if (!keys) {
        free(offsets);
        fprintf(stderr, "Memory allocation failed for keys\n");
        return NULL;
    }

    record* records = (record*)malloc(MAX_RECORDS * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Memory allocation failed for records\n");
        return NULL;
    }

    // Initialize arrays
    for (int i = 0; i < MAX_MEMORY_USAGE / sizeof(long); i++) {
        offsets[i] = i * 1024; // Example initialization
    }
    for (int i = 0; i < MAX_MEMORY_USAGE / sizeof(int); i++) {
        keys[i] = i % 100; // Example initialization
    }

    // Initialize records with random values
    srand(time(NULL));
    int prev_value = -1;
    for (int i = 0; i < MAX_RECORDS; i++) {
        int value;
        do {
            value = rand() % 101;
        } while (value == prev_value);
        records[i].value = value;
        prev_value = value;
    }

    // Process records
    qsort(records, MAX_RECORDS, sizeof(record), compare_records);

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    return NULL;
}

int compare_records(const void* a, const void* b) {
    record* rec_a = (record*)a;
    record* rec_b = (record*)b;
    return rec_b->value - rec_a->value;
}

int main() {
    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, allocate_and_initialize_memory, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return 1;
    }

    pthread_join(thread_id, NULL);

    return 0;
}
