#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

int allocate_memory(long **offsets, int **keys, record ***records, size_t size) {
    *offsets = (long *)malloc(size * sizeof(long));
    *keys = (int *)malloc(size * sizeof(int));
    *records = (record **)malloc(size * sizeof(record *));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        return -1; // Memory allocation failed
    }

    for (size_t i = 0; i < size; ++i) {
        (*records)[i] = (record *)malloc(sizeof(record));
        if ((*records)[i] == NULL) {
            free(*offsets);
            free(*keys);
            for (size_t j = 0; j < i; ++j) {
                free((*records)[j]);
            }
            free(*records);
            return -1; // Memory allocation failed
        }
    }

    return 0; // Success
}

void initialize_memory(long *offsets, int *keys, record **records, size_t size, int min_value, int max_value) {
    srand(time(NULL));

    for (size_t i = 0; i < size; ++i) {
        offsets[i] = rand() % 1000L; // Example offset generation
        keys[i] = rand() % (max_value - min_value + 1) + min_value;
        records[i]->value = keys[i]; // Initialize record value with key
    }
}

void free_memory(long *offsets, int *keys, record **records, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    const size_t size = 1000;
    long *offsets;
    int *keys;
    record **records;

    if (allocate_memory(&offsets, &keys, &records, size) != 0) {
        // Handle memory allocation failure
        return -1;
    }

    initialize_memory(offsets, keys, records, size, 10, 100);

    // Use the allocated and initialized memory...

    free_memory(offsets, keys, records, size);

    return 0;
}
