using HtmlAgilityPack;
using Microsoft.Extensions.Logging;

public class PageUpdater
{
    private readonly ConcurrentQueue<(string pageSectionId, string elementId, string htmlContent)> _updateQueue = new();
    private readonly IDistributedLockService _lockService;
    private readonly IHtmlParser _htmlParser;
    private readonly ILogger<PageUpdater> _logger;
    private readonly IDatabaseService _databaseService;
    private readonly ICachingService _cachingService;
    private readonly IRateLimiter _rateLimiter;

    public PageUpdater(IDistributedLockService lockService, IHtmlParser htmlParser, ILogger<PageUpdater> logger, IDatabaseService databaseService, ICachingService cachingService, IRateLimiter rateLimiter)
    {
        _lockService = lockService;
        _htmlParser = htmlParser;
        _logger = logger;
        _databaseService = databaseService;
        _cachingService = cachingService;
        _rateLimiter = rateLimiter;
    }

    public async Task<HttpResponseMessage> HandlePostRequestAsync(string pageSectionId, string elementId, string htmlContent)
    {
        if (!_rateLimiter.AllowRequest(HttpContext.Current.Request.UserHostAddress))
        {
            return new HttpResponseMessage(HttpStatusCode.TooManyRequests);
        }

        _updateQueue.Enqueue((pageSectionId, elementId, htmlContent));

        await ProcessUpdateQueueAsync();

        var response = new HttpResponseMessage(HttpStatusCode.OK);
        response.Content = new StringContent("Page should be refreshed");
        return response;
    }

    private async Task ProcessUpdateQueueAsync()
    {
        while (_updateQueue.TryDequeue(out var update))
        {
            if (await _lockService.AcquireLockAsync(update.pageSectionId, TimeSpan.FromSeconds(10)))
            {
                try
                {
                    await ValidateHtmlContentAsync(update.htmlContent);
                    await UpdateElementAsync(update.pageSectionId, update.elementId, update.htmlContent);
                    await _cachingService.InvalidateCacheAsync(update.pageSectionId);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error processing update for page section {PageSectionId} and element {ElementId}", update.pageSectionId, update.elementId);
                    await RetryUpdateAsync(update);
                }
                finally
                {
                    await _lockService.ReleaseLockAsync(update.pageSectionId);
                }
            }
        }
    }

    private async Task ValidateHtmlContentAsync(string htmlContent)
    {
        var document = new HtmlDocument();
        document.LoadHtml(htmlContent);

        // Implement HTML validation logic here
        // Log warnings for invalid markup without crashing the application
    }

    private async Task UpdateElementAsync(string pageSectionId, string elementId, string htmlContent)
    {
        await _databaseService.UpdateElementAsync(pageSectionId, elementId, htmlContent);
    }

    private async Task RetryUpdateAsync((string pageSectionId, string elementId, string htmlContent) update)
    {
        for (int i = 0; i < 3; i++)
        {
            try
            {
                await ProcessUpdateQueueAsync();
                break;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error retrying update for page section {PageSectionId} and element {ElementId}", update.pageSectionId, update.elementId);
                await Task.Delay(TimeSpan.FromSeconds(Math.Pow(2, i)));
            }
        }
    }
}
