struct memory_pool {
    void* pool;
    size_t size;
    size_t used;
    pthread_mutex_t lock;
};

void init_memory_pool(struct memory_pool* mp, size_t size) {
    mp->pool = malloc(size);
    if (!mp->pool) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    mp->size = size;
    mp->used = 0;
    pthread_mutex_init(&mp->lock, NULL);
}

void* allocate_record(struct memory_pool* mp) {
    pthread_mutex_lock(&mp->lock);
    if (mp->used + RECORD_SIZE > mp->size) {
        fprintf(stderr, "Memory pool overflow\n");
        pthread_mutex_unlock(&mp->lock);
        return NULL;
    }
    void* ptr = (char*)mp->pool + mp->used;
    mp->used += RECORD_SIZE;
    pthread_mutex_unlock(&mp->lock);
    return ptr;
}

void deallocate_record(struct memory_pool* mp, void* ptr) {
    // In a real scenario, you would need to manage free list or similar
    // For simplicity, we assume records are not reused in this example
}

