#define MAX_EMAIL_LENGTH 256
#define MAX_IDENTIFIER_LENGTH 13

typedef struct {
    char identifier[MAX_IDENTIFIER_LENGTH];
    int count;
} IdentifierEntry;

IdentifierEntry *identifierTable = NULL;
int tableSize = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initializeIdentifierTable(int size) {
    tableSize = size;
    identifierTable = (IdentifierEntry *)malloc(size * sizeof(IdentifierEntry));
    for (int i = 0; i < size; i++) {
        strcpy(identifierTable[i].identifier, "");
        identifierTable[i].count = 0;
    }
}

void updateIdentifierTable(const char *identifier) {
    pthread_mutex_lock(&lock);
    int hash = 0;
    for (int i = 0; i < strlen(identifier); i++) {
        hash = (hash * 31 + identifier[i]) % tableSize;
    }
    if (strcmp(identifierTable[hash].identifier, "") == 0) {
        strcpy(identifierTable[hash].identifier, identifier);
        identifierTable[hash].count = 1;
    } else if (strcmp(identifierTable[hash].identifier, identifier) == 0) {
        identifierTable[hash].count++;
    }
    pthread_mutex_unlock(&lock);
}

int isAlphanumeric(char c) {
