char* generateIdentifier(const char *domain) {
    int frequency[256] = {0};
    int totalChars = 0;
    for (int i = 0; domain[i] != '\0'; i++) {
        if (isAlphanumeric(domain[i])) {
            frequency[(unsigned char)domain[i]]++;
            totalChars++;
        }
    }

    unsigned char identifier[MAX_IDENTIFIER_LENGTH];
    if (!RAND_bytes(identifier, sizeof(identifier))) {
        fprintf(stderr, "Error generating random bytes\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < sizeof(identifier); i++) {
        identifier[i] = frequency[identifier[i]] % 10 + '0';
    }
    identifier[sizeof(identifier) - 1] = '\0';

    updateIdentifierTable((char *)identifier);

    return (char *)identifier;
}

void processEmail(char *email) {
    char *domain = strchr(email, '@');
    if (domain == NULL || domain[1] == '\0') {
        fprintf(stderr, "Invalid email address\n");
        return;
    }

    replaceNonAlphanumericWithUnderscore(domain + 1);
    char *identifier = generateIdentifier(domain + 1);

    sprintf(email, "%s@%s%s", strtok(email, "@"), domain + 1, identifier);
}

void logStatistics() {
