using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using System.Text.RegularExpressions;

public struct entry
{
    public IntPtr dataPtr;
    public int index;
    public int dataSize;
}

public struct value
{
    public string strValue;
    public int intValue;
}

public class DynamicArrayManager
{
    private List<entry> entries = new List<entry>();
    private Dictionary<string, byte[]> hashDictionary = new Dictionary<string, byte[]>();

    public void ProcessAndHashDynamicArray(List<string> inputStrings)
    {
        foreach (var str in inputStrings)
        {
            string normalizedStr = Regex.Replace(str, "[^A-Za-z0-9]", "");
            byte[] hashBytes = ComputeSHA256(normalizedStr);
            hashDictionary[str] = hashBytes;
        }
    }

    private byte[] ComputeSHA256(string input)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            return sha256.ComputeHash(Encoding.UTF8.GetBytes(input));
        }
    }

    public void InitializeEntry(int index, int dataSize)
    {
        entry newEntry = new entry
        {
            dataPtr = Marshal.AllocHGlobal(dataSize * Marshal.SizeOf(typeof(value))),
            index = index,
            dataSize = dataSize
        };
        entries.Add(newEntry);
    }

    public void ResizeEntry(int index, int newSize)
    {
        if (index >= 0 && index < entries.Count)
        {
            entry currentEntry = entries[index];
            IntPtr newDataPtr = Marshal.AllocHGlobal(newSize * Marshal.SizeOf(typeof(value)));
            Marshal.Copy(currentEntry.dataPtr, 0, newDataPtr, Math.Min(currentEntry.dataSize, newSize));
            Marshal.FreeHGlobal(currentEntry.dataPtr);
            currentEntry.dataPtr = newDataPtr;
            currentEntry.dataSize = newSize;
            entries[index] = currentEntry;
        }
    }

    public void FreeAllMemory()
    {
        foreach (var entry in entries)
        {
            Marshal.FreeHGlobal(entry.dataPtr);
        }
        entries.Clear();
        hashDictionary.Clear();
    }
}
