#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_SESSIONS 1000
#define MAX_RESOURCES 50

typedef struct {
    char id[32];
    void* userProfile;
} UserProfile;

typedef struct {
    time_t timestamp;
    char resource[MAX_RESOURCES];
} ResourceAccess;

typedef struct {
    char id[32];
    UserProfile* userProfile;
    ResourceAccess recentResources[MAX_RESOURCES];
    int resourceCount;
    pthread_mutex_t lock;
} UserSession;

UserSession sessions[MAX_SESSIONS];
int sessionCount = 0;
pthread_mutex_t sessionLock;

void initializeSessionManager() {
    pthread_mutex_init(&sessionLock, NULL);
}

UserSession* createSession(UserProfile* userProfile) {
    pthread_mutex_lock(&sessionLock);
    if (sessionCount >= MAX_SESSIONS) {
        pthread_mutex_unlock(&sessionLock);
        return NULL;
    }
    UserSession* session = &sessions[sessionCount++];
    strcpy(session->id, generateUniqueId());
    session->userProfile = userProfile;
    session->resourceCount = 0;
    pthread_mutex_init(&session->lock, NULL);
    pthread_mutex_unlock(&sessionLock);
    return session;
}

void destroySession(UserSession* session) {
    pthread_mutex_lock(&session->lock);
    // Free any resources associated with the session
    pthread_mutex_unlock(&session->lock);
    pthread_mutex_destroy(&session->lock);
}

void addResourceAccess(UserSession* session, const char* resource) {
    pthread_mutex_lock(&session->lock);
    if (session->resourceCount < MAX_RESOURCES) {
        strcpy(session->recentResources[session->resourceCount].resource, resource);
        session->recentResources[session->resourceCount].timestamp = time(NULL);
        session->resourceCount++;
    }
    pthread_mutex_unlock(&session->lock);
}

void archiveInactiveSessions() {
    pthread_mutex_lock(&sessionLock);
    for (int i = 0; i < sessionCount; i++) {
        UserSession* session = &sessions[i];
        if (isSessionInactive(session)) {
            destroySession(session);
            // Shift remaining sessions to fill the gap
            memmove(&sessions[i], &sessions[i + 1], sizeof(UserSession) * (sessionCount - i - 1));
            sessionCount--;
            i--; // Adjust index after shifting
        }
    }
    pthread_mutex_unlock(&sessionLock);
}

void* manageSessions(void* arg) {
    while (1) {
        archiveInactiveSessions();
        sleep(60); // Check every minute
    }
    return NULL;
}

int main() {
    initializeSessionManager();
    pthread_t archiverThread;
    pthread_create(&archiverThread, NULL, manageSessions, NULL);

    // Example usage
    UserProfile userProfile;
    UserSession* session = createSession(&userProfile);
    if (session) {
        addResourceAccess(session, "resource1");
        destroySession(session);
    }

    pthread_join(archiverThread, NULL);
    return 0;
}
```

