int init_aes_cbc_cipher(const char *password, unsigned char **key, unsigned char **iv) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;

    int key_len = EVP_MAX_KEY_LENGTH;
    int iv_len = EVP_MAX_IV_LENGTH;

    if (EVP_BytesToKey(EVP_aes_256_cbc(), EVP_sha256(), NULL, (unsigned char *)password, strlen(password), 1, *key, &key_len) <= 0 ||
        !RAND_bytes(*iv, iv_len)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    EVP_CIPHER_CTX_init(ctx);
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, *key, *iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    EVP_CIPHER_CTX_free(ctx);
    return 0;
}
