public class CustomDataStructure
{
    private Dictionary<string, (long offset, int key, Record record)> _data;
    private MemoryPool _memoryPool;
    private Random _random;

    public CustomDataStructure(int maxStringLength)
    {
        _data = new Dictionary<string, (long offset, int key, Record record)>();
        _memoryPool = new MemoryPool(maxStringLength);
        _random = new Random();
    }

    public void Add(string identifier, long offset, int key, int minValue, int maxValue)
    {
        if (!_memoryPool.HasSufficientMemory(identifier.Length))
        {
            throw new InsufficientMemoryException("Not enough memory to allocate string.");
        }

        var recordValue = _random.Next(minValue, maxValue + 1);
        var record = new Record(recordValue);

        _data[identifier] = (offset, key, record);
        _memoryPool.Allocate(identifier.Length);
    }

    public void Remove(string identifier)
    {
        if (_data.ContainsKey(identifier))
        {
            _memoryPool.Deallocate(_data[identifier].offset);
            _data.Remove(identifier);
        }
    }

    public void SerializeToFile(string filePath)
    {
        using (var stream = new FileStream(filePath, FileMode.Create, FileAccess.Write, FileShare.None, bufferSize: 4096, useAsync: true))
        {
            using (var writer = new BinaryWriter(stream))
            {
                foreach (var item in _data)
                {
                    writer.Write(item.Key);
                    writer.Write(item.Value.offset);
                    writer.Write(item.Value.key);
                    writer.Write(item.Value.record.Value);
                }
            }
        }
    }

    public void DeserializeFromFile(string filePath)
    {
        using (var stream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.None, bufferSize: 4096, useAsync: true))
        {
            using (var reader = new BinaryReader(stream))
            {
                while (reader.BaseStream.Position < reader.BaseStream.Length)
                {
                    var identifier = reader.ReadString();
                    var offset = reader.ReadInt64();
                    var key = reader.ReadInt32();
                    var recordValue = reader.ReadInt32();

                    _data[identifier] = (offset, key, new Record(recordValue));
                    _memoryPool.Allocate(identifier.Length);
                }
            }
        }
    }

    public void Log(string message, LogLevel level)
    {
        // Implement logging logic here
    }
}

public struct Record
{
    public int Value { get; }

    public Record(int value)
    {
        Value = value;
    }
}

public enum LogLevel
{
    Debug,
    Info,
    Warning,
    Error
}

public class MemoryPool
{
    private Dictionary<string, long> _allocations;
    private int _maxStringLength;

    public MemoryPool(int maxStringLength)
    {
        _allocations = new Dictionary<string, long>();
        _maxStringLength = maxStringLength;
    }

    public bool HasSufficientMemory(int length)
    {
        return length <= _maxStringLength && !_allocations.Any(a => a.Value == 0);
    }

    public void Allocate(int length)
    {
        if (length > _maxStringLength)
        {
            throw new ArgumentException("String length exceeds maximum allowed.");
        }

        var identifier = GenerateUniqueIdentifier();
        _allocations[identifier] = length;
    }

    public void Deallocate(long offset)
    {
        // Implement deallocation logic here
    }

    private string GenerateUniqueIdentifier()
    {
        // Implement unique identifier generation logic here
        return Guid.NewGuid().ToString("N");
    }
}
