typedef struct node {
    unsigned long key;
    double value;
    struct node* next;
} Node;

Node* create_node(unsigned long key, double value) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_node->key = key;
    new_node->value = value;
    new_node->next = NULL;
    return new_node;
}

void insert_at_head(Node** head, unsigned long key, double value) {
    Node* new_node = create_node(key, value);
    new_node->next = *head;
    *head = new_node;
}

void insert_at_tail(Node** head, unsigned long key, double value) {
    Node* new_node = create_node(key, value);
    if (*head == NULL) {
        *head = new_node;
        return;
    }
    Node* temp = *head;
    while (temp->next != NULL) {
        temp = temp->next;
    }
    temp->next = new_node;
}

void traverse_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("Key: %lu, Value: %f\n", current->key, current->value);
        current = current->next;
    }
}

int main() {
    Node* head = NULL;

    // Example usage
    insert_at_head(&head, 1, 3.14);
    insert_at_tail(&head, 2, 2.718);
    traverse_list(head);

    return 0;
}
