typedef struct TreeNode {
    double value;
    int numChildren;
    struct TreeNode** children;
} TreeNode;

typedef struct Record {
    long offset;
    int key;
    TreeNode* tree;
} Record;

Record* createRecord(long minOffset, long maxOffset) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) return NULL;

    record->offset = rand() % (maxOffset - minOffset + 1) + minOffset;
    record->key = rand();
    record->tree = createTree(0, 0, 0); // Adjust parameters as needed
    if (!record->tree) {
        free(record);
        return NULL;
    }

    return record;
}

TreeNode* createNode(double value, int maxChildren) {
    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));
    if (!node) return NULL;

    node->value = value;
    node->numChildren = rand() % (maxChildren + 1);
    node->children = (TreeNode**)malloc(node->numChildren * sizeof(TreeNode*));
    for (int i = 0; i < node->numChildren; i++) {
        node->children[i] = createNode(rand(), maxChildren); // Adjust parameters as needed
        if (!node->children[i]) {
            freeTree(node);
            return NULL;
        }
    }

    return node;
}

TreeNode* createTree(double rootValue, int depth, int maxChildren) {
    if (depth == 0) {
        return createNode(rootValue, maxChildren);
    } else {
        TreeNode* root = createNode(rand(), maxChildren); // Adjust parameters as needed
        if (!root) return NULL;

        for (int i = 0; i < root->numChildren; i++) {
            root->children[i] = createTree(rand(), depth - 1, maxChildren); // Adjust parameters as needed
            if (!root->children[i]) {
                freeTree(root);
                return NULL;
            }
        }

        return root;
    }
}

void freeRecord(Record* record) {
    if (record) {
        freeTree(record->tree);
        free(record);
    }
}

void freeTree(TreeNode* node) {
    if (node) {
        for (int i = 0; i < node->numChildren; i++) {
            freeTree(node->children[i]);
        }
        free(node->children);
        free(node);
    }
}
