// Define data structures
typedef struct {
    int x;
    int y;
} Point;

typedef struct {
    int width;
    int height;
} Rectangle;

// Function to initialize dynamic memory and read integers from standard input
int* initIntegers(int *size) {
    printf("Enter the number of integers: ");
    scanf("%d", size);
    int *array = (int *)malloc(*size * sizeof(int));
    if (array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    printf("Enter %d integers:\n", *size);
    for (int i = 0; i < *size; i++) {
        scanf("%d", &array[i]);
    }
    return array;
}

// Helper function to find the largest integer
int findLargest(int *array, int size) {
    if (array == NULL || size <= 0) {
        fprintf(stderr, "Invalid input for finding largest integer\n");
        return -1; // Error indicator
    }
    int max = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    return max;
}

// Function to calculate Euclidean distance between two points
double euclideanDistance(Point p1, Point p2) {
    return sqrt(pow(p2.x - p1.x, 2) + pow(p2.y - p1.y, 2));
}

// Function to compute the area of a rectangle
int rectangleArea(Rectangle rect) {
    return rect.width * rect.height;
}

// Main function to demonstrate usage
int main() {
    int size = 0;
    int *integers = initIntegers(&size);
    if (integers != NULL) {
        printf("Largest integer: %d\n", findLargest(integers, size));
        free(integers);
    }

    // Example with points and rectangles
    Point p1 = {3, 4};
    Point p2 = {6, 8};
    Rectangle rect = {5, 10};

    printf("Euclidean distance between points: %f\n", euclideanDistance(p1, p2));
    printf("Area of rectangle: %d\n", rectangleArea(rect));

    return 0;
}
