#define MAX_RECORDS 10000

typedef struct {
    long offset;
    int key;
    char* data;
} Record;

Record records[MAX_RECORDS];
int record_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* initializeRecords(void* arg) {
    // Initialize records with unique filenames, random offsets, and values
    for (int i = 0; i < MAX_RECORDS; i++) {
        pthread_mutex_lock(&mutex);
        if (record_count >= MAX_RECORDS) {
            pthread_mutex_unlock(&mutex);
            break;
        }
        records[record_count].offset = rand();
        records[record_count].key = rand() % 1000;
        records[record_count].data = malloc(256 * sizeof(char));
        sprintf(records[record_count].data, "file%d.txt", i);
        record_count++;
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

void* monitorPerformance(void* arg) {
    // Monitor memory usage, cache hit rate, and average access time
    while (1) {
        // Perform monitoring logic here
        sleep(1); // Simulate periodic monitoring
    }
    return NULL;
}

int main() {
    pthread_t thread1, thread2;

    if (pthread_create(&thread1, NULL, initializeRecords, NULL) != 0) {
        perror("Failed to create thread");
        exit(EXIT_FAILURE);
    }

    if (pthread_create(&thread2, NULL, monitorPerformance, NULL) != 0) {
        perror("Failed to create thread");
        exit(EXIT_FAILURE);
    }

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    for (int i = 0; i < record_count; i++) {
        free(records[i].data);
    }

    return 0;
}
