public class DynamicDataProcessor
{
    private Random random = new Random();
    private Dictionary<string, float> rangeSettings = new Dictionary<string, float>();
    private List<GeographicLocation> locations = new List<GeographicLocation>();

    public void SetRange(string attribute, float min, float max)
    {
        if (min >= max)
            throw new ArgumentException("Invalid range: min must be less than max.");

        rangeSettings[attribute] = min;
        rangeSettings[attribute + "Max"] = max;
    }

    public float GenerateRandomFloat(string attribute, bool inclusive = true)
    {
        if (!rangeSettings.ContainsKey(attribute) || !rangeSettings.ContainsKey(attribute + "Max"))
            throw new InvalidOperationException("Range not set for the specified attribute.");

        float min = rangeSettings[attribute];
        float max = rangeSettings[attribute + "Max"];

        return inclusive ? random.NextFloat(min, max) : random.NextFloatExclusive(min, max);
    }

    public int GenerateRandomInt(string attribute, bool inclusive = true)
    {
        if (!rangeSettings.ContainsKey(attribute) || !rangeSettings.ContainsKey(attribute + "Max"))
            throw new InvalidOperationException("Range not set for the specified attribute.");

        int min = (int)Math.Ceiling(rangeSettings[attribute]);
        int max = (int)Math.Floor(rangeSettings[attribute + "Max"]);

        return inclusive ? random.Next(min, max + 1) : random.Next(min, max);
    }

    public override string ToString()
    {
        return $"Current Range Settings: {string.Join(", ", rangeSettings.Select(kv => $"{kv.Key}: {kv.Value}"))}";
    }
}

