UserProfileManager* userProfileManagerCreate(size_t initialCapacity) {
    UserProfileManager *manager = (UserProfileManager*)malloc(sizeof(UserProfileManager));
    manager->profiles = (UserProfile*)calloc(initialCapacity, sizeof(UserProfile));
    manager->capacity = initialCapacity;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void userProfileManagerAdd(UserProfileManager *manager, UserProfile profile) {
