    if (manager->count >= manager->capacity) {
        manager->profiles = realloc(manager->profiles, manager->capacity * 2 * sizeof(UserProfile));
        manager->capacity *= 2;
    }
    manager->profiles[manager->count++] = profile;
    pthread_mutex_unlock(&manager->lock);
}

