#include <pthread.h>

// Define data structures
typedef struct record {
    int value;
    char *log_entry;
} Record;

typedef struct log_entry {
    char *data;
} LogEntry;

typedef struct node {
    long offset;
    int key;
    Record *record;
    LogEntry *log;
    struct node *next, *prev;
} Node;

typedef struct circular_list {
    Node *head;
    pthread_mutex_t lock;
} CircularList;

// Function prototypes
Node* create_node(long offset, int key, Record *record, LogEntry *log);
void insert_node(CircularList *list, Node *node);
void delete_node(CircularList *list, Node *node);
Record* create_record(int value, char *log_entry);
LogEntry* create_log_entry(char *data);
void free_record(Record *record);
void free_log_entry(LogEntry *log);

// Implement the function
void processDynamicWorkloads() {
    // Initialize circular list and mutex
    CircularList list;
    pthread_mutex_init(&list.lock, NULL);
    list.head = NULL;

    // Example usage
    Record *rec = create_record(10, "Log entry 1");
    LogEntry *log = create_log_entry("Data for log 1");
    Node *node = create_node(1, 2, rec, log);

    pthread_mutex_lock(&list.lock);
    insert_node(&list, node);
    pthread_mutex_unlock(&list.lock);

    // Clean up
    free_record(rec);
    free_log_entry(log);
    delete_node(&list, node);
    pthread_mutex_destroy(&list.lock);
}

// Helper functions
Node* create_node(long offset, int key, Record *record, LogEntry *log) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->offset = offset;
    new_node->key = key;
    new_node->record = record;
    new_node->log = log;
    new_node->next = NULL;
    new_node->prev = NULL;
    return new_node;
}

void insert_node(CircularList *list, Node *node) {
    if (list->head == NULL) {
        list->head = node;
        node->next = node;
        node->prev = node;
    } else {
        Node *tail = list->head->prev;
        tail->next = node;
        node->prev = tail;
        node->next = list->head;
        list->head->prev = node;
    }
}

void delete_node(CircularList *list, Node *node) {
    if (node == list->head && node->next == node) {
        list->head = NULL;
    } else {
        node->prev->next = node->next;
        node->next->prev = node->prev;
        if (node == list->head) {
            list->head = node->next;
        }
    }
    free_record(node->record);
    free_log_entry(node->log);
    free(node);
}

Record* create_record(int value, char *log_entry) {
    Record *rec = (Record*)malloc(sizeof(Record));
    rec->value = value;
    rec->log_entry = strdup(log_entry);
    return rec;
}

LogEntry* create_log_entry(char *data) {
    LogEntry *log = (LogEntry*)malloc(sizeof(LogEntry));
    log->data = strdup(data);
    return log;
}

void free_record(Record *record) {
    free(record->log_entry);
    free(record);
}

void free_log_entry(LogEntry *log) {
    free(log->data);
    free(log);
}
