#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for the data
typedef struct Data {
    long offset;
    int key;
    char* filename;
    struct Data* next;
    struct Data* prev;
} Data;

// Define the circular doubly-linked list
typedef struct List {
    Data* head;
    pthread_mutex_t mutex;
} List;

// Function to create a new data structure
Data* create_data(long offset, int key, const char* filename) {
    Data* data = (Data*)malloc(sizeof(Data));
    if (data == NULL) {
        perror("Failed to allocate memory for data");
        return NULL;
    }
    data->offset = offset;
    data->key = key;
    data->filename = strdup(filename);
    data->next = data;
    data->prev = data;
    return data;
}

// Function to insert a new data structure into the list
void insert_data(List* list, Data* data) {
    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        list->head = data;
    } else {
        data->next = list->head;
        data->prev = list->head->prev;
        list->head->prev->next = data;
        list->head->prev = data;
    }
    pthread_mutex_unlock(&list->mutex);
}

// Function to delete a data structure from the list
void delete_data(List* list, Data* data) {
    pthread_mutex_lock(&list->mutex);
    if (data == list->head && list->head->next == list->head) {
        list->head = NULL;
    } else {
        data->prev->next = data->next;
        data->next->prev = data->prev;
        if (data == list->head) {
            list->head = data->next;
        }
    }
    free(data->filename);
    free(data);
    pthread_mutex_unlock(&list->mutex);
}

// Function to clean up the list
void cleanup_list(List* list) {
    pthread_mutex_lock(&list->mutex);
    Data* current = list->head;
    while (current != NULL) {
        Data* next = current->next;
        delete_data(list, current);
        current = next;
    }
    pthread_mutex_unlock(&list->mutex);
}

// Function to log messages
void log_message(const char* message, int level) {
    // Implement logging logic here based on the log level
}
