use clap::{App, Arg};
use tokio::runtime::Runtime;
use reqwest::Client;
use std::time::Duration;
use log::{info, error};

#[derive(Debug)]
enum Command {
    FetchData,
    ProcessData,
}

fn main() {
    let matches = App::new("Dynamic CLI Processor")
        .version("1.0")
        .author("Your Name <your.email@example.com>")
        .about("A Rust program to dynamically process command-line arguments.")
        .arg(
            Arg::with_name("command")
                .short('c')
                .long("command")
                .value_name("COMMAND")
                .takes_value(true)
                .possible_values(&["fetch", "process"])
                .required(true),
        )
        .get_matches();

    let command = match matches.value_of("command") {
        Some("fetch") => Command::FetchData,
        Some("process") => Command::ProcessData,
        _ => unreachable!(),
    };

    let rt = Runtime::new().unwrap();
    rt.block_on(async move {
        match command {
            Command::FetchData => fetch_data().await,
            Command::ProcessData => process_data().await,
        }
    });
}

async fn fetch_data() {
    let client = Client::builder()
        .timeout(Duration::from_secs(10))
        .build()
        .unwrap();

    let response = client.get("https://api.example.com/data")
        .send()
        .await
        .map_err(|e| error!("Failed to send request: {}", e))
        .and_then(|response| {
            response.error_for_status().map_err(|e| error!("Request failed: {}", e))
        })
        .and_then(|response| response.json::<serde_json::Value>().await)
        .map_err(|e| error!("Failed to parse JSON: {}", e));

    match response {
        Ok(data) => info!("Data fetched successfully: {:?}", data),
        Err(e) => error!("Error fetching data: {}", e),
    }
}

