use std::env;
use std::fs::{self, File};
use std::io::{self, Write};
use std::path::Path;
use log::{info, error};

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 4 {
        eprintln!("Usage: {} <environment> <config_name> [--overwrite]", args[0]);
        return;
    }

    let environment = &args[1];
    let config_name = &args[2];
    let overwrite_flag = args.contains(&"--overwrite".to_string());

    manage_config(environment, config_name, overwrite_flag);
}

fn manage_config(environment: &str, config_name: &str, overwrite_flag: bool) {
    let base_dir = Path::new("/path/to/configs");
    let env_dir = base_dir.join(environment);
    let config_path = env_dir.join(format!("{}.conf", config_name));

    if !env_dir.exists() {
        fs::create_dir_all(&env_dir).expect("Failed to create environment directory");
    }

    if config_path.exists() {
        if overwrite_flag {
            info!("Overwriting existing configuration file.");
        } else {
            error!("Configuration file already exists. Use --overwrite flag to replace it.");
            return;
        }
    }

    let mut file = File::create(&config_path).expect("Failed to create configuration file");
    writeln!(file, "# Configuration for {} environment", environment).unwrap();
    writeln!(file, "param1=placeholder").unwrap();
    writeln!(file, "param2=placeholder").unwrap();

    info!("Created default configuration file at {:?}", config_path);

    set_env_variable(environment, &config_path);
}

fn set_env_variable(environment: &str, config_path: &Path) {
    if let Ok(current_value) = env::var(format!("CONFIG_{}", environment.to_uppercase())) {
        if current_value != config_path.display().to_string() {
            info!("Environment variable CONFIG_{} is already set to {}. Not overwriting.", environment, current_value);
        } else {
            env::set_var(format!("CONFIG_{}", environment.to_uppercase()), config_path.display().to_string());
            info!("Set environment variable CONFIG_{} to {:?}", environment, config_path);
        }
    } else {
        env::set_var(format!("CONFIG_{}", environment.to_uppercase()), config_path.display().to_string());
        info!("Created new environment variable CONFIG_{} with value {:?}", environment, config_path);
    }
}
