#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct Item {
    char *key;
    int value;
    time_t timestamp;
    struct Item *next;
} Item;

typedef struct LinkedList {
    Item *head;
    pthread_mutex_t lock;
} LinkedList;

void initLinkedList(LinkedList *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void destroyLinkedList(LinkedList *list) {
    pthread_mutex_lock(&list->lock);
    Item *current = list->head;
    while (current != NULL) {
        Item *next = current->next;
        free(current->key);
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

void insertItem(LinkedList *list, const char *key, int value) {
    pthread_mutex_lock(&list->lock);
    Item *newItem = (Item *)malloc(sizeof(Item));
    newItem->key = strdup(key);
    newItem->value = value;
    newItem->timestamp = time(NULL);
    newItem->next = NULL;

    if (list->head == NULL || list->head->value > value) {
        newItem->next = list->head;
        list->head = newItem;
    } else {
        Item *current = list->head;
        while (current->next != NULL && current->next->value < value) {
            current = current->next;
        }
        newItem->next = current->next;
        current->next = newItem;
    }
    pthread_mutex_unlock(&list->lock);
}

void deleteItem(LinkedList *list, const char *key) {
    pthread_mutex_lock(&list->lock);
    Item *current = list->head;
    Item *prev = NULL;

    while (current != NULL && strcmp(current->key, key) != 0) {
        prev = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (prev == NULL) {
        list->head = current->next;
    } else {
        prev->next = current->next;
    }

    free(current->key);
    free(current);
    pthread_mutex_unlock(&list->lock);
}

void traverseList(LinkedList *list, void (*callback)(Item *)) {
    pthread_mutex_lock(&list->lock);
    Item *current = list->head;
    while (current != NULL) {
        callback(current);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}
