    *keys = (int *)malloc(size * sizeof(int));
    if (*keys == NULL) {
        return -1; // Memory allocation failed
    }

    *records = (record *)malloc(size * sizeof(record));
    if (*records == NULL) {
        free(*keys);
        return -1; // Memory allocation failed
    }

    return 0; // Success
}

void initialize_arrays(int size, int *keys, record *records, int upper_bound) {
    for (int i = 0; i < size; i++) {
        keys[i] = rand() % (upper_bound + 1);
        records[i].value = keys[i];
    }
}

int find_largest_integer(int *keys, int size) {
    int largest = keys[0];
    for (int i = 1; i < size; i++) {
        if (keys[i] > largest) {
            largest = keys[i];
        }
    }
    return largest;
}

void free_memory(int *keys, record *records) {
    free(keys);
    free(records);
}

int main() {
    int size = 500;
    int upper_bound = 1000;
    int *keys;
    record *records;

    if (allocate_memory(size, &keys, &records) != 0) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    initialize_arrays(size, keys, records, upper_bound);

    int largest = find_largest_integer(keys, size);
    printf("Largest integer: %d\n", largest);

    free_memory(keys, records);

    return 0;
}
