record* create_records(int num_records, int max_size, int seed) {
    if (num_records > max_size) {
        fprintf(stderr, "Error: Requested number of records exceeds maximum size limit.\n");
        return NULL;
    }

    srand(seed);
    record* records = malloc(num_records * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records.");
        return NULL;
    }

    int keys[1000] = {0}; // Assuming key range is 0-999
    long offsets[1000000] = {0}; // Assuming offset range is 0-999999

    for (int i = 0; i < num_records; ++i) {
        int key;
        do {
            key = rand() % 1000;
        } while (keys[key]);

        long offset;
        do {
            offset = rand() % 1000000;
        } while (offsets[offset]);

        records[i].value = rand();
        records[i].key = key;
        records[i].offset = offset;

        keys[key] = 1;
        offsets[offset] = 1;
    }

    return records;
}

void free_records(record* records, int num_records) {
    free(records);
}

int main() {
    int num_records = 50;
    int max_size = 100;
    int seed = time(NULL);

    record* records = create_records(num_records, max_size, seed);
    if (records) {
        printf("Records created successfully.\n");
        free_records(records, num_records);
    }

    return 0;
}
