    scanf("%d", &size);

    long* offsets = malloc(size * sizeof(long));
    Record* records = malloc(size * sizeof(Record));
    char** keys = malloc(size * sizeof(char*));
    time_t* timestamps = malloc(size * sizeof(time_t));

