#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    float x;
    float y;
    char name[20];
} Point;

typedef struct {
    Point* points;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} PointCollection;

void initPointCollection(PointCollection* collection, size_t initialCapacity) {
    collection->points = (Point*)malloc(initialCapacity * sizeof(Point));
    if (!collection->points) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    collection->count = 0;
    collection->capacity = initialCapacity;
    pthread_mutex_init(&collection->lock, NULL);
}

void freePointCollection(PointCollection* collection) {
    pthread_mutex_lock(&collection->lock);
    free(collection->points);
    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
}

int addPoint(PointCollection* collection, float x, float y, const char* name) {
    pthread_mutex_lock(&collection->lock);
    if (collection->count >= collection->capacity) {
        size_t newCapacity = collection->capacity * 2;
        Point* newPoints = (Point*)realloc(collection->points, newCapacity * sizeof(Point));
        if (!newPoints) {
            fprintf(stderr, "Memory reallocation failed\n");
            pthread_mutex_unlock(&collection->lock);
            return -1;
        }
        collection->points = newPoints;
        collection->capacity = newCapacity;
    }

    for (size_t i = 0; i < collection->count; ++i) {
        if (fabs(collection->points[i].x - x) < 0.0001 && fabs(collection->points[i].y - y) < 0.0001) {
            pthread_mutex_unlock(&collection->lock);
            return -2; // Conflict detected
        }
    }

    collection->points[collection->count].x = x;
    collection->points[collection->count].y = y;
    strncpy(collection->points[collection->count].name, name, sizeof(collection->points[collection->count].name) - 1);
    collection->points[collection->count].name[sizeof(collection->points[collection->count].name) - 1] = '\0';
    ++collection->count;
    pthread_mutex_unlock(&collection->lock);
    return 0;
}

int savePointCollection(const PointCollection* collection, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return -1;
    }

    fwrite(&collection->count, sizeof(size_t), 1, file);
    fwrite(collection->points, sizeof(Point), collection->count, file);

    fclose(file);
    return 0;
}

int loadPointCollection(PointCollection* collection, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return -1;
    }

    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    if (count > collection->capacity) {
        Point* newPoints = (Point*)realloc(collection->points, count * sizeof(Point));
        if (!newPoints) {
            fprintf(stderr, "Memory reallocation failed\n");
            fclose(file);
            return -1;
        }
        collection->points = newPoints;
        collection->capacity = count;
    }

    fread(collection->points, sizeof(Point), count, file);

    fclose(file);
    collection->count = count;
    return 0;
}
