record* create_records(int num_records, int max_size, unsigned int seed) {
    if (num_records > max_size) {
        fprintf(stderr, "Error: Requested number of records exceeds maximum size limit.\n");
        return NULL;
    }

    record* records = malloc(num_records * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records.");
        return NULL;
    }

    srand(seed);
    int keys[1000] = {0}; // Assuming key range is 0-999
    long offsets[1000] = {0}; // Assuming offset range is 0-999

    for (int i = 0; i < num_records; ++i) {
        int key;
        do {
            key = rand() % 1000;
        } while (keys[key]);
        keys[key] = 1;

        long offset;
        do {
            offset = rand() % 1000;
        } while (offsets[offset]);
        offsets[offset] = 1;

        records[i].value = rand();
        records[i].key = key;
        records[i].offset = offset;
    }

    return records;
}

void free_records(record* records, int num_records) {
    free(records);
}

EVP_CIPHER_CTX* init_aes_cipher(const char* password) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Error: Failed to create cipher context.\n");
        return NULL;
    }

    unsigned char key[32];
    unsigned char iv[16];

    // Derive key using SHA-1
    SHA1((unsigned char*)password, strlen(password), key);

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        fprintf(stderr, "Error: Failed to initialize AES cipher.\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

void cleanup_cipher(EVP_CIPHER_CTX* ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
}
