#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <math.h>

typedef struct {
    time_t timestamp;
    double value;
} data_point;

double gaussian(double mean, double stddev) {
    static const double two_pi = 2.0 * M_PI;
    double u1, u2, v1, v2, s;

    do {
        u1 = (double)rand() / RAND_MAX;
        u2 = (double)rand() / RAND_MAX;
        v1 = 2.0 * u1 - 1.0;
        v2 = 2.0 * u2 - 1.0;
        s = v1 * v1 + v2 * v2;
    } while (s >= 1.0);

    return mean + stddev * v1 * sqrt(-2.0 * log(s));
}

int initialize_data_arrays(int num_points, double mean, double stddev, double sampling_rate) {
    if (num_points <= 0 || sampling_rate <= 0) {
        fprintf(stderr, "Invalid input: num_points and sampling_rate must be positive.\n");
        return -1;
    }

    double *double_array = malloc(num_points * sizeof(double));
    unsigned short *short_array = malloc(num_points * sizeof(unsigned short));
    data_point *data_points = malloc(num_points * sizeof(data_point));

    if (!double_array || !short_array || !data_points) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(double_array);
        free(short_array);
        free(data_points);
        return -1;
    }

    srand(time(NULL));
    for (int i = 0; i < num_points; ++i) {
        double_array[i] = gaussian(mean, stddev);
        short_array[i] = (unsigned short)i;
        data_points[i].timestamp = time(NULL) + i * sampling_rate;
        data_points[i].value = gaussian(mean, stddev);
    }

    // Free allocated memory
    free(double_array);
    free(short_array);
    free(data_points);

    return 0;
}

int main() {
    int num_points = 100;
    double mean = 5.0;
    double stddev = 2.0;
    double sampling_rate = 1.0;

    if (initialize_data_arrays(num_points, mean, stddev, sampling_rate) != 0) {
        fprintf(stderr, "Failed to initialize data arrays.\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
