typedef struct {
    char *str;
    int value;
} Entry;

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    // Handle the data received from the network
    return realsize;
}

Entry* read_entries_from_file(const char *url, int *offsets, int *keys, int *num_entries) {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        FILE *fp;
        fp = fopen("temp.txt", "wb");
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, fp);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            fclose(fp);
            return NULL;
        }

        fclose(fp);
        curl_easy_cleanup(curl);
    } else {
        fprintf(stderr, "Failed to initialize libcurl\n");
        return NULL;
    }

    FILE *file = fopen("temp.txt", "r");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    Entry *entries = malloc(sizeof(Entry));
    int i = 0;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        entries = realloc(entries, (i + 1) * sizeof(Entry));
        entries[i].str = strtok(line, " ");
        entries[i].value = atoi(strtok(NULL, " "));
        offsets[i] = i;
        keys[i] = i;

        i++;
    }

    fclose(file);
    free(entries);

    *num_entries = i;
    return entries;
}

int main() {
    int num_entries;
    Entry *entries = read_entries_from_file("http://example.com/data.txt", NULL, NULL, &num_entries);
    if (entries) {
        for (int i = 0; i < num_entries; i++) {
            printf("Entry %d: String=%s, Value=%d\n", i, entries[i].str, entries[i].value);
        }
        free(entries);
    }

    return 0;
}
```

