#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <math.h>
#include <pthread.h>

#define MAX_MEMORY_USAGE 1024 * 1024 * 1024 // 1GB
#define RESIZE_THRESHOLD 0.8

typedef struct {
    time_t timestamp;
    double value;
} data_point;

typedef struct {
    double* doubles;
    unsigned short* shorts;
    data_point* points;
    size_t count;
    size_t capacity;
    size_t memory_usage;
    pthread_mutex_t mutex;
} dynamic_arrays;

void initialize_dynamic_arrays(dynamic_arrays* arrays, size_t initial_capacity) {
    arrays->doubles = (double*)malloc(initial_capacity * sizeof(double));
    arrays->shorts = (unsigned short*)malloc(initial_capacity * sizeof(unsigned short));
    arrays->points = (data_point*)malloc(initial_capacity * sizeof(data_point));
    arrays->count = 0;
    arrays->capacity = initial_capacity;
    arrays->memory_usage = initial_capacity * (sizeof(double) + sizeof(unsigned short) + sizeof(data_point));
    pthread_mutex_init(&arrays->mutex, NULL);
}

void free_dynamic_arrays(dynamic_arrays* arrays) {
    free(arrays->doubles);
    free(arrays->shorts);
    free(arrays->points);
    pthread_mutex_destroy(&arrays->mutex);
}

void resize_dynamic_arrays(dynamic_arrays* arrays, size_t new_capacity) {
    double* new_doubles = (double*)realloc(arrays->doubles, new_capacity * sizeof(double));
    unsigned short* new_shorts = (unsigned short*)realloc(arrays->shorts, new_capacity * sizeof(unsigned short));
    data_point* new_points = (data_point*)realloc(arrays->points, new_capacity * sizeof(data_point));

    if (!new_doubles || !new_shorts || !new_points) {
        fprintf(stderr, "Memory allocation failed during resize.\n");
        return;
    }

    arrays->doubles = new_doubles;
    arrays->shorts = new_shorts;
    arrays->points = new_points;
    arrays->capacity = new_capacity;
    arrays->memory_usage = new_capacity * (sizeof(double) + sizeof(unsigned short) + sizeof(data_point));
}

void add_data_point(dynamic_arrays* arrays, time_t timestamp, double value, unsigned short identifier) {
    pthread_mutex_lock(&arrays->mutex);
    if (arrays->memory_usage > MAX_MEMORY_USAGE * RESIZE_THRESHOLD) {
        size_t new_capacity = arrays->capacity * 2;
        resize_dynamic_arrays(arrays, new_capacity);
    }

    arrays->doubles[arrays->count] = value;
    arrays->shorts[arrays->count] = identifier;
    arrays->points[arrays->count].timestamp = timestamp;
    arrays->points[arrays->count].value = value;
    arrays->count++;
    pthread_mutex_unlock(&arrays->mutex);
}

void serialize_data(dynamic_arrays* arrays, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing.\n");
        return;
    }

    fwrite(arrays->doubles, sizeof(double), arrays->count, file);
    fwrite(arrays->shorts, sizeof(unsigned short), arrays->count, file);
    fwrite(arrays->points, sizeof(data_point), arrays->count, file);

    fclose(file);
}

void* generate_sensor_readings(void* arg) {
    dynamic_arrays* arrays = (dynamic_arrays*)arg;
    double mean = 0.0;
    double stddev = 1.0;
    srand(time(NULL));

    for (size_t i = 0; i < 1000000; i++) {
        time_t timestamp = time(NULL);
        double value = mean + stddev * rand() / (RAND_MAX + 1.0);
        unsigned short identifier = rand() % 256;
        add_data_point(arrays, timestamp, value, identifier);
    }

    return NULL;
}

int main() {
    dynamic_arrays arrays;
    initialize_dynamic_arrays(&arrays, 1000);

    pthread_t threads[4];
    for (size_t i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, generate_sensor_readings, &arrays);
    }

    for (size_t i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    serialize_data(&arrays, "sensor_data.bin");
    free_dynamic_arrays(&arrays);

    return 0;
}
