#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Metadata {
    int value;
    struct Metadata* next;
} Metadata;

typedef struct Record {
    int key;
    Metadata* metadata;
} Record;

typedef enum Status {
    SUCCESS,
    FAILURE
} Status;

Status initializeData(long** offsets, int** keys, Record** records, Status** statuses, int numRecords, int numMetadata, int upperBound) {
    srand(time(NULL));

    *offsets = (long*)malloc(numRecords * sizeof(long));
    *keys = (int*)malloc(numRecords * sizeof(int));
    *records = (Record*)malloc(numRecords * sizeof(Record));
    *statuses = (Status*)malloc(numRecords * sizeof(Status));

    if (*offsets == NULL || *keys == NULL || *records == NULL || *statuses == NULL) {
        free(*offsets);
        free(*keys);
        free(*records);
        free(*statuses);
        return FAILURE;
    }

    for (int i = 0; i < numRecords; i++) {
        (*offsets)[i] = rand() % 1000L; // Example offset initialization
        (*keys)[i] = rand() % upperBound + 1;

        (*records)[i].key = (*keys)[i];
        (*records)[i].metadata = NULL;

        for (int j = 0; j < numMetadata; j++) {
            Metadata* newMetadata = (Metadata*)malloc(sizeof(Metadata));
            if (newMetadata == NULL) {
                // Clean up previously allocated resources
                for (int k = 0; k < i; k++) {
                    Metadata* current = (*records)[k].metadata;
                    while (current != NULL) {
                        Metadata* temp = current;
                        current = current->next;
                        free(temp);
                    }
                }
                free(*offsets);
                free(*keys);
                free(*records);
                free(*statuses);
                return FAILURE;
            }

            newMetadata->value = rand() % upperBound + 1;
            newMetadata->next = (*records)[i].metadata;
            (*records)[i].metadata = newMetadata;
        }
    }

    for (int i = 0; i < numRecords; i++) {
        (*statuses)[i] = SUCCESS;
    }

    return SUCCESS;
}

void freeData(long* offsets, int* keys, Record* records, Status* statuses) {
    if (offsets != NULL) free(offsets);
    if (keys != NULL) free(keys);
    if (records != NULL) {
        for (int i = 0; i < numRecords; i++) {
            Metadata* current = records[i].metadata;
            while (current != NULL) {
                Metadata* temp = current;
                current = current->next;
                free(temp);
            }
        }
        free(records);
    }
    if (statuses != NULL) free(statuses);
}

int main() {
    long* offsets;
    int* keys;
    Record* records;
    Status* statuses;

    int numRecords = 1000;
    int numMetadata = 5;
    int upperBound = 100;

    if (initializeData(&offsets, &keys, &records, &statuses, numRecords, numMetadata, upperBound) == SUCCESS) {
        printf("Initialization successful.\n");
        freeData(offsets, keys, records, statuses);
    } else {
        printf("Initialization failed.\n");
    }

    return 0;
}
