int initialize_pipeline(size_t num_doubles, size_t num_strings, size_t num_events) {
    double* double_array = (double*)malloc(num_doubles * sizeof(double));
    char** string_array = (char**)malloc(num_strings * sizeof(char*));
    Event* event_array = (Event*)malloc(num_events * sizeof(Event));

    if (!double_array || !string_array || !event_array) {
        // Handle memory allocation failure
        free(double_array);
        free(string_array);
        free(event_array);
        return -1; // Return an error code
    }

    for (size_t i = 0; i < num_doubles; ++i) {
        double_array[i] = 0.0;
    }

    for (size_t i = 0; i < num_strings; ++i) {
        string_array[i] = (char*)malloc(256 * sizeof(char)); // Assuming max length of 255 characters
        if (!string_array[i]) {
            // Handle memory allocation failure for strings
            for (size_t j = 0; j < i; ++j) {
                free(string_array[j]);
            }
            free(double_array);
            free(string_array);
            free(event_array);
            return -1; // Return an error code
        }
    }

    time_t current_time;
    for (size_t i = 0; i < num_events; ++i) {
        time(&current_time);
        event_array[i].timestamp = current_time;
        event_array[i].status_code = 0; // Default status code
    }

    // Initialize other components of the pipeline

    // Free allocated memory when done
    free(double_array);
    for (size_t i = 0; i < num_strings; ++i) {
        free(string_array[i]);
    }
    free(string_array);
    free(event_array);

    return 0; // Return success code
}
