typedef struct Metadata {
    int data;
    struct Metadata* next;
} Metadata;

typedef struct Record {
    int value;
    Metadata* metadata;
    struct Record* crossRef;
} Record;

int allocateRecords(int recordCount, int metadataPerRecord, int maxValue) {
    srand(time(NULL));

    Record** records = (Record**)malloc(recordCount * sizeof(Record*));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        return -1;
    }

    for (int i = 0; i < recordCount; ++i) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed for record %d.\n", i);

            // Clean up previously allocated resources
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records);
            return -1;
        }

        records[i]->value = rand() % maxValue + 1;
        records[i]->metadata = NULL;
        records[i]->crossRef = NULL;
    }

    // Initialize metadata for each record
    for (int i = 0; i < recordCount; ++i) {
        Metadata* head = NULL;
        Metadata* tail = NULL;

        for (int j = 0; j < metadataPerRecord; ++j) {
            Metadata* newMetadata = (Metadata*)malloc(sizeof(Metadata));
            if (!newMetadata) {
                fprintf(stderr, "Memory allocation failed for metadata in record %d.\n", i);

                // Clean up previously allocated resources
                Metadata* current = records[i]->metadata;
                while (current) {
                    Metadata* next = current->next;
                    free(current);
                    current = next;
                }
                free(records[i]);

                for (int k = 0; k < i; ++k) {
                    free(records[k]);
                }
                free(records);
                return -1;
            }

            newMetadata->data = rand() % maxValue + 1;
            newMetadata->next = NULL;

            if (!head) {
                head = tail = newMetadata;
            } else {
                tail->next = newMetadata;
                tail = newMetadata;
            }
        }

        records[i]->metadata = head;
    }

    // Initialize cross-referencing
    for (int i = 0; i < recordCount; ++i) {
        int targetIndex = rand() % recordCount;
        if (targetIndex != i) {
            records[i]->crossRef = records[targetIndex];
        } else {
            records[i]->crossRef = NULL;
        }
    }

    // Log successful allocation
    printf("Records allocated successfully.\n");

    return 0;
}

int main() {
    int recordCount, metadataPerRecord, maxValue;

    printf("Enter the number of records: ");
    scanf("%d", &recordCount);

    printf("Enter the number of metadata elements per record: ");
    scanf("%d", &metadataPerRecord);

    printf("Enter the maximum value for the value field: ");
    scanf("%d", &maxValue);

    if (allocateRecords(recordCount, metadataPerRecord, maxValue) == 0) {
        // Proceed with further processing
    }

    return 0;
}
