// Define the structure for an observation
typedef struct Observation {
    time_t timestamp;
    double measurement_value;
    struct Observation *next;
} Observation;

// Define the structure for a feature
typedef struct Feature {
    double latitude;
    double longitude;
    char city_name[100];
    int elevation;
    char description[256];
    Observation *observations;
    struct Feature *next;
} Feature;

// Function to initialize an observation
Observation* init_observation(time_t timestamp, double measurement_value) {
    Observation *obs = (Observation*)malloc(sizeof(Observation));
    if (obs == NULL) return NULL;
    obs->timestamp = timestamp;
    obs->measurement_value = measurement_value;
    obs->next = NULL;
    return obs;
}

// Function to add an observation to a feature
void add_observation(Feature *feature, time_t timestamp, double measurement_value) {
    Observation *new_obs = init_observation(timestamp, measurement_value);
    if (new_obs == NULL) return;

    new_obs->next = feature->observations;
    feature->observations = new_obs;
}

// Function to initialize a feature
Feature* init_feature(double latitude, double longitude, const char *city_name, int elevation, const char *description) {
    Feature *feature = (Feature*)malloc(sizeof(Feature));
    if (feature == NULL) return NULL;
    feature->latitude = latitude;
    feature->longitude = longitude;
    strncpy(feature->city_name, city_name, sizeof(feature->city_name) - 1);
    feature->elevation = elevation;
    strncpy(feature->description, description, sizeof(feature->description) - 1);
    feature->observations = NULL;
    feature->next = NULL;
    return feature;
}

// Function to fetch data from a remote server
int fetch_data_from_server(Feature **features) {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        struct MemoryStruct chunk;
        chunk.memory = malloc(1);  // will be grown as needed by the realloc above
        chunk.size = 0;    // no data at this point

        curl_easy_setopt(curl, CURLOPT_URL, "http://example.com/api/data");
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void *)&chunk);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            return -1;
        }

        // Parse the JSON data and populate features
        // This part is not implemented here

        free(chunk.memory);
        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
    return 0;
}

// Function to write memory callback for libcurl
size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    struct MemoryStruct *mem = (struct MemoryStruct *)userp;

    char *ptr = realloc(mem->memory, mem->size + realsize + 1);
    if(ptr == NULL) {
        // out of memory!
        printf("not enough memory (realloc returned NULL)\n");
        return 0;
    }

    mem->memory = ptr;
    memcpy(&(mem->memory[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->memory[mem->size] = 0;

    return realsize;
}

// Main function to initialize the data structure
int main() {
    Feature *features = NULL;

    if (fetch_data_from_server(&features) != 0) {
        fprintf(stderr, "Failed to fetch data from server\n");
        return -1;
    }

    // Process features and observations here

    // Free allocated memory
    Feature *current_feature = features;
    while (current_feature != NULL) {
        Observation *current_observation = current_feature->observations;
        while (current_observation != NULL) {
            Observation *next_observation = current_observation->next;
            free(current_observation);
            current_observation = next_observation;
        }
        Feature *next_feature = current_feature->next;
        free(current_feature);
        current_feature = next_feature;
    }

    return 0;
}
