    // Perform compression here
    end = clock();
    cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;
    printf("Compression time: %f seconds\n", cpu_time_used);

    // Decompress data and measure performance
    start = clock();
    // Perform decompression here
    end = clock();
    cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;
    printf("Decompression time: %f seconds\n", cpu_time_used);

    // Free allocated memory
    free(profiles);
}

int main() {
    manageUserProfiles(10, "user_", "@example.com", 256);
    return 0;
}
