#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 10000

typedef struct record {
    int value;
    char data[20];
    struct record *next;
} Record;

Record* create_record(int min, int max) {
    Record *new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    new_record->value = rand() % (max - min + 1) + min;
    snprintf(new_record->data, sizeof(new_record->data), "%d", new_record->value);
    new_record->next = NULL;
    return new_record;
}

void add_record(Record **head, int min, int max) {
    Record *new_record = create_record(min, max);
    if (*head == NULL) {
        *head = new_record;
    } else {
        Record *current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_record;
    }
}

void print_records(Record *head) {
    Record *current = head;
    while (current != NULL) {
        printf("Value: %d, Data: %s\n", current->value, current->data);
        current = current->next;
    }
}

void free_records(Record **head) {
    Record *current = *head;
    Record *temp;
    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }
    *head = NULL;
}

int main() {
    srand(time(NULL));
    Record *records_head = NULL;

    for (int i = 0; i < MAX_RECORDS; i++) {
        add_record(&records_head, 1, 100);
    }

    print_records(records_head);

    free_records(&records_head);

    return 0;
}
