int manage_memory(long **offsets, int **keys, record **records, size_t size, int key_range) {
    srand(time(NULL));

    // Allocate memory for offsets
    *offsets = (long *)malloc(size * sizeof(long));
    if (*offsets == NULL) {
        return 0; // Handle allocation failure
    }

    // Allocate memory for keys
    *keys = (int *)malloc(size * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        return 0; // Handle allocation failure
    }

    // Allocate memory for records
    *records = (record *)malloc(size * sizeof(record));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return 0; // Handle allocation failure
    }

    int unique_values[key_range];
    for (int i = 0; i < key_range; ++i) {
        unique_values[i] = i;
    }

    // Initialize records with unique keys and random values
    for (size_t i = 0; i < size; ++i) {
        (*records)[i].key = &(*keys)[i];
        do {
            (*records)[i].value = unique_values[rand() % key_range];
        } while ((*records)[i].value == -1); // Assuming -1 is an invalid value
        unique_values[(*records)[i].value] = -1; // Mark as used
    }

    return size;
}

int main() {
    long *offsets;
    int *keys;
    record *records;
    size_t size = 1000;
    int key_range = 500;

    int initialized_records = manage_memory(&offsets, &keys, &records, size, key_range);
    if (initialized_records > 0) {
        printf("Successfully initialized %zu records.\n", initialized_records);
        // Free allocated memory
        free(offsets);
        free(keys);
        for (size_t i = 0; i < initialized_records; ++i) {
            free(records[i].key); // Assuming keys are dynamically allocated
        }
        free(records);
    } else {
        printf("Failed to initialize records.\n");
    }

    return 0;
}
