['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 10000
#define CACHE_SIZE 100

typedef struct Record {
    int key;
    char data[256];
    struct Record* next;
} Record;

typedef struct IndexNode {
    int key;
    Record* record;
    struct IndexNode* next;
} IndexNode;

typedef struct {
    Record** records;
    IndexNode* indexHead;
    pthread_mutex_t lock;
    Record* cache[CACHE_SIZE];
} DataStructure;

DataStructure* createDataStructure() {
    DataStructure* ds = (DataStructure*)malloc(sizeof(DataStructure));
    ds->records = (Record**)calloc(MAX_RECORDS, sizeof(Record*));
    ds->indexHead = NULL;
    pthread_mutex_init(&ds->lock, NULL);
    for (int i = 0; i < CACHE_SIZE; i++) {
        ds->cache[i] = NULL;
    }
    return ds;
}

void insertRecord(DataStructure* ds, int key, const char* data) {
    Record* newRecord = (Record*)malloc(sizeof(Record));
    newRecord->key = key;
    strcpy(newRecord->data, data);
    newRecord->next = NULL;

    pthread_mutex_lock(&ds->lock);

    // Insert into main linked list
    if (ds->records[key % MAX_RECORDS] == NULL) {
        ds->records[key % MAX_RECORDS] = newRecord;
    } else {
        Record* current = ds->records[key % MAX_RECORDS];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newRecord;
    }

    // Insert into index linked list
    IndexNode* newIndexNode = (IndexNode*)malloc(sizeof(IndexNode));
    newIndexNode->key = key;
    newIndexNode->record = newRecord;
    newIndexNode->next = ds->indexHead;
    ds->indexHead = newIndexNode;

    pthread_mutex_unlock(&ds->lock);
}

Record* findRecord(DataStructure* ds, int key) {
    Record* record = ds->cache[key % CACHE_SIZE];
    if (record != NULL && record->key == key) {
        return record;
    }

    pthread_mutex_lock(&ds->lock);

    // Search in main linked list
    Record* current = ds->records[key % MAX_RECORDS];
    while (current != NULL) {
        if (current->key == key) {
            ds->cache[key % CACHE_SIZE] = current; // Update cache
            pthread_mutex_unlock(&ds->lock);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&ds->lock);
    return NULL;
}

void deleteRecord(DataStructure* ds, int key) {
    pthread_mutex_lock(&ds->lock);

    // Delete from main linked list
    Record** prev = &ds->records[key % MAX_RECORDS];
    while (*prev != NULL) {
        if ((*prev)->key == key) {
            Record* temp = *prev;
            *prev = (*prev)->next;
            free(temp);
            break;
        }
        prev = &(*prev)->next;
    }

    // Delete from index linked list
    IndexNode** prevIndex = &ds->indexHead;
    while (*prevIndex != NULL) {
        if ((*prevIndex)->key == key) {
            IndexNode* temp = *prevIndex;
            *prevIndex = (*prevIndex)->next;
            free(temp);
            break;
        }
        prevIndex = &(*prevIndex)->next;
    }

    pthread_mutex_unlock(&ds->lock);
}

void serializeDataStructure(DataStructure* ds, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }

    // Write records
    for (int i = 0; i < MAX_RECORDS; i++) {
        Record* current = ds->records[i];
        while (current != NULL) {
            fwrite(&current->key, sizeof(int), 1, file);
            fwrite(current->data, sizeof(char), 256, file);
            current = current->next;
        }
    }

    fclose(file);
}

void deserializeDataStructure(DataStructure* ds, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file for reading");
        return;
    }

    // Read records
    while (!feof(file)) {
        int key;
        fread(&key, sizeof(int), 1, file);
        if (feof(file)) break;

        char data[256];
        fread(data, sizeof(char), 256, file);

        insertRecord(ds, key, data);
    }

    fclose(file);
}

void destroyDataStructure(DataStructure* ds) {
    for (int i = 0; i < MAX_RECORDS; i++) {
        Record* current = ds->records[i];
        while (current != NULL) {
            Record* temp = current;
            current = current->next;
            free(temp);
        }
    }

    IndexNode* current = ds->indexHead;
    while (current != NULL) {
        IndexNode* temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_destroy(&ds->lock);
    free(ds);
}
