#define MAX_RECORDS 10000

typedef struct record {
    int id;
    char data[20];
    struct record *next;
} Record;

Record* create_record(int id, const char* data) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (new_record == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    new_record->id = id;
    strncpy(new_record->data, data, sizeof(new_record->data) - 1);
    new_record->data[sizeof(new_record->data) - 1] = '\0';
    new_record->next = NULL;
    return new_record;
}

void free_records(Record* head) {
    Record* current = head;
    while (current != NULL) {
        Record* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    Record* records[MAX_RECORDS] = {NULL};
    int count = 0;

    // Example usage
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (count >= MAX_RECORDS) {
            fprintf(stderr, "Maximum number of records reached\n");
            break;
        }
        Record* new_record = create_record(i, "Sample Data");
        if (new_record != NULL) {
            records[count++] = new_record;
        } else {
            break;
        }
    }

    // Free allocated memory
    for (int i = 0; i < count; i++) {
        free_records(records[i]);
    }

    return 0;
}
