#define MAX_LABELS 10

typedef struct {
    int value;
    float timestamp;
    char label[20];
    double weight;
} Record;

int allocate_and_initialize_arrays(long long size, long* long_array, int* int_array, Record** record_array, char** char_array, double* double_array) {
    // Check available memory
    if (size > LLONG_MAX / sizeof(long)) return -1; // Insufficient memory

    // Allocate memory for arrays
    long_array = (long*)malloc(size * sizeof(long));
    int_array = (int*)malloc(size * sizeof(int));
    record_array = (Record**)malloc(size * sizeof(Record*));
    char_array = (char**)malloc(size * sizeof(char*));
    double_array = (double*)malloc(size * sizeof(double));

    if (!long_array || !int_array || !record_array || !char_array || !double_array) {
        // Clean up partially allocated resources
        free(long_array);
        free(int_array);
        free(record_array);
        free(char_array);
        free(double_array);
        return -1; // Memory allocation failed
    }

    // Initialize arrays with random values and current time
    srand(time(NULL));
    for (long long i = 0; i < size; i++) {
        long_array[i] = rand() % LLONG_MAX;
        int_array[i] = rand() % INT_MAX;

        record_array[i] = (Record*)malloc(sizeof(Record));
        if (!record_array[i]) {
            // Clean up partially allocated resources
            for (long long j = 0; j < i; j++) free(record_array[j]);
            free(long_array);
            free(int_array);
            free(record_array);
            free(char_array);
            free(double_array);
            return -1; // Memory allocation failed
        }
        record_array[i]->value = rand() % INT_MAX;
        record_array[i]->timestamp = (float)time(NULL);
        strcpy(record_array[i]->label, "Label" + rand() % MAX_LABELS);
        record_array[i]->weight = ((double)rand()) / RAND_MAX;

        char_array[i] = (char*)malloc(20 * sizeof(char));
        if (!char_array[i]) {
            // Clean up partially allocated resources
            for (long long j = 0; j <= i; j++) free(record_array[j]);
            free(long_array);
            free(int_array);
            free(record_array);
            free(char_array);
            return -1; // Memory allocation failed
        }
        sprintf(char_array[i], "Char%d", rand() % 10);

        double_array[i] = ((double)rand()) / RAND_MAX;
    }

    return 0; // Success
}

void free_arrays(long long size, long* long_array, int* int_array, Record** record_array, char** char_array, double* double_array) {
    for (long long i = 0; i < size; i++) {
        free(record_array[i]);
        free(char_array[i]);
    }
    free(long_array);
    free(int_array);
    free(record_array);
    free(char_array);
    free(double_array);
}

int main() {
    long long size = 1000000;
    long* long_array;
    int* int_array;
    Record** record_array;
    char** char_array;
    double* double_array;

    if (allocate_and_initialize_arrays(size, long_array, int_array, &record_array, &char_array, &double_array) == 0) {
        // Export data to file
        FILE* fp = fopen("data.json", "w");
        if (fp) {
            fprintf(fp, "[\n");
            for (long long i = 0; i < size; i++) {
                fprintf(fp, "{\"long\": %lld, \"int\": %d, \"record\": {\"value\": %d, \"timestamp\": %.2f, \"label\": \"%s\", \"weight\": %.2f}, \"char\": \"%s\", \"double\": %.2f}",
                        long_array[i], int_array[i], record_array[i]->value, record_array[i]->timestamp, record_array[i]->label, record_array[i]->weight, char_array[i], double_array[i]);
                if (i < size - 1) fprintf(fp, ",\n");
            }
            fprintf(fp, "\n]\n");
            fclose(fp);
        }

        // Free allocated memory
        free_arrays(size, long_array, int_array, record_array, char_array, double_array);
    } else {
        printf("Memory allocation failed.\n");
    }

    return 0;
}
