    int account_status;
    char preferences[256];
} UserProfile;

// Function to create a new user profile
UserProfile* create_user_profile(const char* username, const char* email, const char* password_hash, int account_status, const char* preferences) {
    UserProfile* profile = (UserProfile*)malloc(sizeof(UserProfile));
    if (profile == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    strcpy(profile->username, username);
    strcpy(profile->email, email);
    strcpy(profile->password_hash, password_hash);
    profile->account_status = account_status;
    strcpy(profile->preferences, preferences);
    return profile;
}

// Function to free a user profile
void free_user_profile(UserProfile* profile) {
    if (profile != NULL) {
        free(profile);
    }
}

// Function to update user profile information
int update_user_profile(UserProfile* profile, const char* email, const char* password_hash, int account_status, const char* preferences) {
    strcpy(profile->email, email);
    strcpy(profile->password_hash, password_hash);
    profile->account_status = account_status;
    strcpy(profile->preferences, preferences);
    return 0; // Return success
}

// Function to search for user profiles by email
UserProfile* search_user_profile_by_email(UserProfile** profiles, int count, const char* email) {
    for (int i = 0; i < count; i++) {
        if (strcmp(profiles[i]->email, email) == 0) {
            return profiles[i];
        }
    }
    return NULL; // Return NULL if not found
}

// Function to filter user profiles by account status
UserProfile** filter_user_profiles_by_status(UserProfile** profiles, int count, int status, int* result_count) {
    *result_count = 0;
    UserProfile** filtered_profiles = (UserProfile**)malloc(count * sizeof(UserProfile*));
    if (filtered_profiles == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    for (int i = 0; i < count; i++) {
        if (profiles[i]->account_status == status) {
            filtered_profiles[(*result_count)++] = profiles[i];
        }
    }
    return filtered_profiles;
}

// Function to free the filtered user profiles
void free_filtered_user_profiles(UserProfile** profiles, int count) {
    for (int i = 0; i < count; i++) {
        free(profiles[i]);
    }
    free(profiles);
}
