#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    time_t timestamp;
    double value;
    char* description;
} Measurement;

typedef struct {
    double real;
    double imag;
} ComplexNumber;

Measurement* readMeasurements(const char* filename, int* size) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    char* buffer = (char*)malloc(fileSize + 1);
    if (!buffer) {
        perror("Failed to allocate memory for file content");
        fclose(file);
        return NULL;
    }

    fread(buffer, 1, fileSize, file);
    fclose(file);
    buffer[fileSize] = '\0';

    char* token = strtok(buffer, "\n");
    *size = 0;

    while (token) {
        (*size)++;
        token = strtok(NULL, "\n");
    }

    Measurement* measurements = (Measurement*)malloc(*size * sizeof(Measurement));
    if (!measurements) {
        perror("Failed to allocate memory for measurements");
        free(buffer);
        return NULL;
    }

    token = strtok(buffer, "\n");
    int i = 0;

    while (token) {
        sscanf(token, "%ld,%lf,%[^,]", &measurements[i].timestamp, &measurements[i].value, measurements[i].description);
        token = strtok(NULL, "\n");
        i++;
    }

    free(buffer);
    return measurements;
}

double calculateAverage(Measurement* measurements, int size) {
    double sum = 0.0;

    for (int i = 0; i < size; i++) {
        sum += measurements[i].value;
    }

    return sum / size;
}

void initializeComplexNumbers(ComplexNumber* complexNumbers, int size, double minReal, double maxReal, double minImag, double maxImag) {
    srand(time(NULL));

    for (int i = 0; i < size; i++) {
        complexNumbers[i].real = minReal + (maxReal - minReal) * ((double)rand() / RAND_MAX);
        complexNumbers[i].imag = minImag + (maxImag - minImag) * ((double)rand() / RAND_MAX);
    }
}

int main() {
    int size;
    Measurement* measurements = readMeasurements("measurements.csv", &size);

    if (!measurements) {
        return 1;
    }

    double averageValue = calculateAverage(measurements, size);
    printf("Average value: %f\n", averageValue);

    ComplexNumber* complexNumbers = (ComplexNumber*)malloc(size * sizeof(ComplexNumber));
    initializeComplexNumbers(complexNumbers, size, -1.0, 1.0, -1.0, 1.0);

    for (int i = 0; i < size; i++) {
        printf("Complex number %d: %f + %fi\n", i, complexNumbers[i].real, complexNumbers[i].imag);
    }

    free(measurements);
    free(complexNumbers);

    return 0;
}
