class ProjectManager {
public:
    void addProject(const std::string& name, const std::vector<int>& milestones, const std::unordered_map<std::string, std::vector<double>>& productivityScores) {
        std::lock_guard<std::mutex> lock(mutex_);
        projects_[name] = {milestones, productivityScores};
        notifyUpdate();
    }

    void addDependency(const std::string& projectName, const Dependency& dependency) {
        std::lock_guard<std::mutex> lock(mutex_);
        dependencies_[projectName].push_back(dependency);
        notifyUpdate();
    }

    void updateProductivityScore(const std::string& member, const std::string& project, double score) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (projects_.find(project) != projects_.end()) {
            projects_[project].productivityScores[member] = score;
            notifyUpdate();
        }
    }

private:
    struct ProjectData {
        std::vector<int> milestones;
        std::unordered_map<std::string, std::vector<double>> productivityScores;
    };

    void notifyUpdate() {
        updateCondition_.notify_one();
    }

    std::mutex mutex_;
    std::condition_variable updateCondition_;
    std::unordered_map<std::string, ProjectData> projects_;
    std::unordered_map<std::string, std::vector<Dependency>> dependencies_;
};
