void* custom_alloc(size_t size, size_t alignment) {
    void *ptr;
    if (posix_memalign(&ptr, alignment, size)) {
        return NULL;
    }
    return ptr;
}

int allocate_memory(size_t num_offsets, size_t num_keys, size_t num_records, offset_t **offsets, key_t **keys, record_t **records) {
    *offsets = custom_alloc(num_offsets * sizeof(offset_t), alignof(offset_t));
    if (!*offsets) return -1;

    *keys = custom_alloc(num_keys * sizeof(key_t), alignof(key_t));
    if (!*keys) {
        free(*offsets);
        return -2;
    }

    *records = custom_alloc(num_records * sizeof(record_t), alignof(record_t));
    if (!*records) {
        free(*keys);
        free(*offsets);
        return -3;
    }

    return 0;
}

int fetch_keys(key_t **keys, size_t num_keys) {
    // Simulate fetching keys from an external service
    for (size_t i = 0; i < num_keys; ++i) {
        (*keys)[i].key = rand() % 1000;
    }
    return 0;
}

void fill_records(record_t *records, size_t num_records, offset_t *offsets, size_t num_offsets) {
    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        records[i].data = rand() % 1000;
        do {
            records[i].offset = &offsets[rand() % num_offsets];
        } while (records[i].offset->value != 0);
    }
}

void free_memory(offset_t *offsets, key_t *keys, record_t *records) {
    free(records);
    free(keys);
    free(offsets);
}

int check_uniqueness(record_t *records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        for (size_t j = i + 1; j < num_records; ++j) {
            if (records[i].offset == records[j].offset) {
                return -1;
            }
        }
    }
    return 0;
}

int main() {
    size_t num_offsets = 1000;
    size_t num_keys = 1000;
    size_t num_records = 1000;

    offset_t *offsets;
    key_t *keys;
    record_t *records;

    if (allocate_memory(num_offsets, num_keys, num_records, &offsets, &keys, &records) != 0) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    if (fetch_keys(&keys, num_keys) != 0) {
        fprintf(stderr, "Failed to fetch keys\n");
        free_memory(offsets, keys, records);
        return 1;
    }

    fill_records(records, num_records, offsets, num_offsets);

    if (check_uniqueness(records, num_records) != 0) {
        fprintf(stderr, "Uniqueness check failed\n");
        free_memory(offsets, keys, records);
        return 1;
    }

    free_memory(offsets, keys, records);
    return 0;
}
