#include <semaphore.h>

#define MAX_SEMAPHORES 10

typedef struct {
    sem_t *sems[MAX_SEMAPHORES];
    int count;
} SemaphoreManager;

SemaphoreManager *create_semaphore_manager() {
    SemaphoreManager *manager = (SemaphoreManager *)malloc(sizeof(SemaphoreManager));
    manager->count = 0;
    return manager;
}

int create_semaphore(SemaphoreManager *manager) {
    if (manager->count >= MAX_SEMAPHORES) {
        return -1; // Semaphore limit reached
    }
    sem_t *sem = (sem_t *)malloc(sizeof(sem_t));
    if (sem_init(sem, 0, 1) != 0) {
        free(sem);
        return -2; // Failed to initialize semaphore
    }
    manager->sems[manager->count++] = sem;
    return 0;
}

void destroy_semaphore(SemaphoreManager *manager, int index) {
    if (index < 0 || index >= manager->count) {
        return; // Invalid index
    }
    sem_t *sem = manager->sems[index];
    sem_destroy(sem);
    free(sem);
    for (int i = index; i < manager->count - 1; i++) {
        manager->sems[i] = manager->sems[i + 1];
    }
    manager->count--;
}

void destroy_semaphore_manager(SemaphoreManager *manager) {
    for (int i = 0; i < manager->count; i++) {
        sem_destroy(manager->sems[i]);
        free(manager->sems[i]);
    }
    free(manager);
}

