typedef struct teamMember {
    char* name;
    int roleID;
    float hourlyRate;
} TeamMember;

typedef struct project {
    char* name;
    Date dueDate;
    float budget;
    TeamMember** teamMembers;
    int memberCount;
} Project;

Project** projects = NULL;
int projectCount = 0;

void insertProject(Project* newProject) {
    // Allocate memory for the new project
    projects = realloc(projects, (projectCount + 1) * sizeof(Project*));
    if (projects == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    projects[projectCount++] = newProject;

    // Update team members' average hourly rate based on the project's budget
    for (int i = 0; i < newProject->memberCount; i++) {
        TeamMember* member = newProject->teamMembers[i];
        float totalRate = 0;
        for (int j = 0; j < projectCount; j++) {
            Project* proj = projects[j];
            for (int k = 0; k < proj->memberCount; k++) {
                if (strcmp(proj->teamMembers[k]->name, member->name) == 0) {
                    totalRate += proj->budget / proj->memberCount;
                    break;
                }
            }
        }
        member->hourlyRate = totalRate / projectCount;
    }
}

void calculateTotalBudget() {
    float totalBudget = 0;
    for (int i = 0; i < projectCount; i++) {
        totalBudget += projects[i]->budget;
    }
    printf("Total budget allocated across all projects: %.2f\n", totalBudget);
}

Project* createProject(char* name, Date dueDate, float budget) {
    Project* newProject = malloc(sizeof(Project));
    if (newProject == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    newProject->name = strdup(name);
    newProject->dueDate = dueDate;
    newProject->budget = budget;
    newProject->teamMembers = NULL;
    newProject->memberCount = 0;

    return newProject;
}

TeamMember* createTeamMember(char* name, int roleID, float hourlyRate) {
    TeamMember* member = malloc(sizeof(TeamMember));
    if (member == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    member->name = strdup(name);
    member->roleID = roleID;
    member->hourlyRate = hourlyRate;

    return member;
}

void addTeamMember(Project* project, TeamMember* member) {
    // Allocate memory for the new team member
    project->teamMembers = realloc(project->teamMembers, (project->memberCount + 1) * sizeof(TeamMember*));
    if (project->teamMembers == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    project->teamMembers[project->memberCount++] = member;
}

int main() {
    srand(time(NULL));

    // Simulate adding projects
    for (int i = 0; i < 5; i++) {
        char name[100];
        sprintf(name, "Project %d", i + 1);
        Date dueDate = {rand() % 28 + 1, rand() % 12 + 1, rand() % 4 + 2023};
        float budget = (float)(rand() % 10000) / 100;
        Project* project = createProject(name, dueDate, budget);

        // Add team members to the project
        for (int j = 0; j < rand() % 5 + 1; j++) {
            char memberName[100];
            sprintf(memberName, "Member %d", j + 1);
            TeamMember* member = createTeamMember(memberName, rand() % 3 + 1, (float)(rand() % 20) / 10);
            addTeamMember(project, member);
        }

        insertProject(project);
    }

    // Calculate and display the total budget
    calculateTotalBudget();

    return 0;
}
