        return;
    }

    record* records = (record*)malloc(size_keys * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        free(offsets);
        free(keys);
        return;
    }

    srand(time(NULL)); // Seed the random number generator

    for (long i = 0; i < size_keys; ++i) {
        keys[i] = 0;
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Use offsets, keys, and records as needed...

    free(records);
    free(keys);
    free(offsets);
