#define MAX_LABELS 10
#define MIN_SIZE 0
#define MAX_SIZE 10000

typedef struct entry {
    double measure;
    struct entry* next;
} entry;

void initialize_data(double** data_values, char** labels, entry** linked_list,
                     int size, const char* label, double min_measure, double max_measure) {
    if (size < MIN_SIZE || size > MAX_SIZE) {
        fprintf(stderr, "Invalid size. Must be between %d and %d.\n", MIN_SIZE, MAX_SIZE);
        return;
    }

    *data_values = (double*)calloc(size, sizeof(double));
    if (*data_values == NULL) {
        fprintf(stderr, "Memory allocation failed for data_values.\n");
        return;
    }

    *labels = (char*)malloc(size * sizeof(char));
    if (*labels == NULL) {
        fprintf(stderr, "Memory allocation failed for labels.\n");
        free(*data_values);
        return;
    }
    memset(*labels, label[0], size);

    srand(time(NULL));
    *linked_list = NULL;
    entry* current = NULL;
    for (int i = 0; i < size; ++i) {
        double measure = min_measure + (max_measure - min_measure) * ((double)rand() / RAND_MAX);
        entry* new_entry = (entry*)malloc(sizeof(entry));
        if (new_entry == NULL) {
            fprintf(stderr, "Memory allocation failed for linked list entry.\n");
            free(*data_values);
            free(*labels);
            while (*linked_list != NULL) {
                entry* temp = *linked_list;
                *linked_list = (*linked_list)->next;
                free(temp);
            }
            return;
        }
        new_entry->measure = measure;
        new_entry->next = NULL;

        if (i == 0) {
            *linked_list = new_entry;
            current = new_entry;
        } else {
            current->next = new_entry;
            current = new_entry;
        }
    }
}

void cleanup(double* data_values, char* labels, entry* linked_list) {
    free(data_values);
    free(labels);
    while (linked_list != NULL) {
        entry* temp = linked_list;
        linked_list = linked_list->next;
        free(temp);
    }
}
