        timestamps[i] = time(NULL);
        event_ids[i] = rand() % 1000;
        logs[i].id = event_ids[i];
        logs[i].timestamp = timestamps[i];
        if (rand() % 2 == 0) {
            strcpy(logs[i].status, "active");
        } else {
            strcpy(logs[i].status, "inactive");
        }
    }
}

void update_event_logs(event_log *logs, int num_events, long time_window) {
    for (int i = 0; i < num_events; i++) {
        if ((time(NULL) - logs[i].timestamp) > time_window) {
            if (rand() % 2 == 0) {
                strcpy(logs[i].status, "active");
            } else {
                strcpy(logs[i].status, "inactive");
            }
        }
    }
}

int main() {
    long *timestamps = malloc(MAX_EVENTS * sizeof(long));
    int *event_ids = malloc(MAX_EVENTS * sizeof(int));
    event_log *logs = malloc(MAX_EVENTS * sizeof(event_log));

    if (timestamps == NULL || event_ids == NULL || logs == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    initialize_event_logs(timestamps, event_ids, logs, MAX_EVENTS);

    long time_window = 3600; // 1 hour
    update_event_logs(logs, MAX_EVENTS, time_window);

    for (int i = 0; i < MAX_EVENTS; i++) {
        printf("Event ID: %d, Timestamp: %ld, Status: %s\n", logs[i].id, logs[i].timestamp, logs[i].status);
    }

    free(timestamps);
    free(event_ids);
    free(logs);

    return 0;
}
