#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int event_id;
    long timestamp;
    int status_flag;
} event_log;

typedef struct summary_node {
    int event_id;
    long total_timestamps;
    int count;
    int active_count;
    pthread_mutex_t lock;
    struct summary_node *next;
} summary_node;

summary_node* create_summary_node(int event_id) {
    summary_node *node = (summary_node*)malloc(sizeof(summary_node));
    node->event_id = event_id;
    node->total_timestamps = 0;
    node->count = 0;
    node->active_count = 0;
    pthread_mutex_init(&node->lock, NULL);
    node->next = NULL;
    return node;
}

void add_event_log(summary_node **head, event_log *log) {
    summary_node *current = *head;
    while (current != NULL) {
        if (current->event_id == log->event_id) {
            pthread_mutex_lock(&current->lock);
            current->total_timestamps += log->timestamp;
            current->count++;
            if (log->status_flag == 1) {
                current->active_count++;
            }
            pthread_mutex_unlock(&current->lock);
            return;
        }
        current = current->next;
    }
    summary_node *new_node = create_summary_node(log->event_id);
    new_node->total_timestamps = log->timestamp;
    new_node->count = 1;
    if (log->status_flag == 1) {
        new_node->active_count = 1;
    } else {
        new_node->active_count = 0;
    }
    new_node->next = *head;
    *head = new_node;
}

void free_summary_nodes(summary_node **head) {
    summary_node *current = *head;
    while (current != NULL) {
        summary_node *temp = current;
        current = current->next;
        pthread_mutex_destroy(&temp->lock);
        free(temp);
    }
    *head = NULL;
