    return profile;
}

void update_user_profile(UserProfile* profile, const char* name, int age, const char* email) {
    pthread_mutex_lock(&profile->lock);
    free(profile->name);
    free(profile->email);
    profile->name = strdup(name);
    profile->age = age;
    profile->email = strdup(email);
    pthread_mutex_unlock(&profile->lock);
}

void destroy_user_profile(UserProfile* profile) {
    if (profile) {
        pthread_mutex_lock(&profile->lock);
        free(profile->name);
        free(profile->email);
        pthread_mutex_destroy(&profile->lock);
        free(profile);
    }
}
