#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum {
    CELSIUS,
    FAHRENHEIT,
    KELVIN,
    RANKINE,
    CUSTOM
} temperature_unit;

typedef struct {
    double value;
    int id;
    char* unit;
    temperature_unit type;
} data_point;

int compare_data_points(const void* a, const void* b) {
    data_point* pointA = (data_point*)a;
    data_point* pointB = (data_point*)b;
    return (pointA->value > pointB->value) - (pointA->value < pointB->value);
}

data_point* initialize_and_sort_data_points(double start, double end, int ascending, char** units, int unit_count) {
    if (start >= end || unit_count <= 0) {
        return NULL;
    }

    data_point* points = malloc((end - start + 1) * sizeof(data_point));
    if (!points) {
        return NULL;
    }

    for (double temp = start; temp <= end; ++temp, ++points) {
        points->value = temp;
        points->id = (int)(temp * 100); // Unique identifier based on temperature
        points->unit = malloc(strlen(units[temp - start % unit_count]) + 1);
        if (!points->unit) {
            free(points);
            return NULL;
        }
        strcpy(points->unit, units[temp - start % unit_count]);
        points->type = CUSTOM; // Assuming all are custom for simplicity
    }

    qsort(points, end - start + 1, sizeof(data_point), compare_data_points);

    if (!ascending) {
        for (int i = 0; i < (end - start + 1) / 2; ++i) {
            data_point temp = points[i];
            points[i] = points[end - start - i];
            points[end - start - i] = temp;
        }
    }

    return points;
}

void free_data_points(data_point* points, int count) {
    for (int i = 0; i < count; ++i) {
        free(points[i].unit);
    }
    free(points);
}
