#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <openssl/md5.h>

typedef struct {
    int value;
    time_t timestamp;
} record;

void initializeData(long* offsets, int* keys, record* records, size_t numRecords, const char* inputString, FILE* logFile) {
    if (inputString == NULL || logFile == NULL) {
        fprintf(stderr, "Invalid input or log file\n");
        return;
    }

    // Initialize MD5 context
    MD5_CTX md5Context;
    MD5_Init(&md5Context);

    // Update MD5 hash with input string
    MD5_Update(&md5Context, inputString, strlen(inputString));

    // Finalize MD5 hash and store in static buffer
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_Final(digest, &md5Context);

    // Log the MD5 hash
    fprintf(logFile, "MD5 Hash: ");
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        fprintf(logFile, "%02x", digest[i]);
    }
    fprintf(logFile, "\n");

    // Initialize offsets and keys to zero
    memset(offsets, 0, numRecords * sizeof(long));
    memset(keys, 0, numRecords * sizeof(int));

    // Populate records with random values
    srand(time(NULL));
    for (size_t i = 0; i < numRecords; ++i) {
        records[i].value = rand() % 1000;
        records[i].timestamp = time(NULL);
    }

    // Log the initialization process
    fprintf(logFile, "Initialization complete with %zu records\n", numRecords);

    // Flush log buffer to disk
    fflush(logFile);
}
