#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define TABLE_SIZE 100003 // Prime number for better distribution

typedef struct Record {
    int key;
    void* value;
    struct Record* next;
} Record;

typedef struct HashTable {
    Record** buckets;
    pthread_mutex_t lock;
} HashTable;

unsigned long hash_function(int key) {
    return (unsigned long)key % TABLE_SIZE;
}

HashTable* create_hash_table() {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->buckets = (Record**)calloc(TABLE_SIZE, sizeof(Record*));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void insert_record(HashTable* table, int key, void* value) {
    pthread_mutex_lock(&table->lock);
    unsigned long index = hash_function(key);
    Record* new_record = (Record*)malloc(sizeof(Record));
    new_record->key = key;
    new_record->value = value;
    new_record->next = table->buckets[index];
    table->buckets[index] = new_record;
    pthread_mutex_unlock(&table->lock);
}

void* lookup_record(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);
    unsigned long index = hash_function(key);
    Record* current = table->buckets[index];
    while (current != NULL) {
        if (current->key == key) {
            pthread_mutex_unlock(&table->lock);
            return current->value;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void iterate_records(HashTable* table, void (*callback)(int, void*)) {
    pthread_mutex_lock(&table->lock);
    for (unsigned long i = 0; i < TABLE_SIZE; i++) {
        Record* current = table->buckets[i];
        while (current != NULL) {
            callback(current->key, current->value);
            current = current->next;
        }
    }
    pthread_mutex_unlock(&table->lock);
}

void free_hash_table(HashTable* table) {
    for (unsigned long i = 0; i < TABLE_SIZE; i++) {
        Record* current = table->buckets[i];
        while (current != NULL) {
            Record* next = current->next;
            free(current);
            current = next;
        }
    }
    pthread_mutex_destroy(&table->lock);
    free(table->buckets);
    free(table);
}
