#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
    float value;
} Record;

typedef struct {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} RecordArray;

RecordArray* create_record_array(size_t initial_capacity) {
    RecordArray* array = (RecordArray*)malloc(sizeof(RecordArray));
    if (!array) return NULL;

    array->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!array->records) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void destroy_record_array(RecordArray* array) {
    pthread_mutex_lock(&array->mutex);
    free(array->records);
    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int add_record(RecordArray* array, Record record) {
    pthread_mutex_lock(&array->mutex);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        Record* new_records = (Record*)realloc(array->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Memory allocation failed
        }

        array->records = new_records;
        array->capacity = new_capacity;
    }

    array->records[array->size++] = record;

    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int remove_record(RecordArray* array, int key) {
    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->records[i].key == key) {
            for (size_t j = i; j < array->size - 1; ++j) {
                array->records[j] = array->records[j + 1];
            }
            --array->size;

            // Optionally shrink the array to reduce memory usage
            if (array->size > 0 && array->size * 4 <= array->capacity) {
                size_t new_capacity = array->capacity / 2;
                Record* new_records = (Record*)realloc(array->records, new_capacity * sizeof(Record));
                if (new_records) {
                    array->records = new_records;
                    array->capacity = new_capacity;
                }
            }

            pthread_mutex_unlock(&array->mutex);
            return 0; // Record removed successfully
        }
    }

    pthread_mutex_unlock(&array->mutex);
    return -1; // Record not found
}

Record* search_record(RecordArray* array, int key) {
    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->records[i].key == key) {
            pthread_mutex_unlock(&array->mutex);
            return &array->records[i]; // Record found
        }
    }

    pthread_mutex_unlock(&array->mutex);
    return NULL; // Record not found
}
