Record* manageMemory(Record** array, size_t* size, size_t newSize) {
    if (newSize <= *size) return *array; // No need to resize

    Record* newArray = realloc(*array, newSize * sizeof(Record));
    if (!newArray) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (size_t i = *size; i < newSize; ++i) {
        newArray[i].offset = rand();
        newArray[i].key = rand() % 1000;
        newArray[i].value = ((float)rand()) / RAND_MAX * 100.0f;
    }

    *array = newArray;
    *size = newSize;
    return newArray;
}

int main() {
    srand(time(NULL));
    Record* records = NULL;
    size_t size = 0;

    for (size_t i = 0; i < 1000000; ++i) {
        if (!manageMemory(&records, &size, i + 1)) {
            break;
        }
    }

    // Free allocated memory
    free(records);

    return 0;
}
