#define MAX_COMPONENTS 100

typedef struct {
    int timestamp;
    char* data_ptr;
    int usage_count;
    int version;
} ComponentRecord;

double* create_double_array(int size) {
    return (double*)malloc(size * sizeof(double));
}

char* read_char_array_from_file(const char* filename, int* size) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    *size = ftell(file);
    fseek(file, 0, SEEK_SET);

    char* buffer = (char*)malloc(*size + 1);
    if (!buffer) {
        fclose(file);
        perror("Failed to allocate memory");
        return NULL;
    }

    size_t bytes_read = fread(buffer, 1, *size, file);
    if (bytes_read != *size) {
        free(buffer);
        fclose(file);
        perror("Failed to read file");
        return NULL;
    }
    buffer[*size] = '\0';

    fclose(file);
    return buffer;
}

ComponentRecord* create_component_records(int size) {
    ComponentRecord* records = (ComponentRecord*)malloc(size * sizeof(ComponentRecord));
    if (!records) {
        perror("Failed to allocate memory");
        return NULL;
    }

    for (int i = 0; i < size; ++i) {
        records[i].timestamp = time(NULL);
        records[i].data_ptr = NULL;
        records[i].usage_count = 0;
        records[i].version = 1;
    }

    return records;
}

void populate_component_records(ComponentRecord* records, char* data, int data_size, int record_size) {
    srand(time(NULL));
    for (int i = 0; i < record_size && i * sizeof(ComponentRecord) < data_size; ++i) {
        records[i].data_ptr = &data[i * sizeof(ComponentRecord)];
        records[i].timestamp = rand();
        records[i].usage_count = rand() % 10;
        records[i].version = rand() % 5 + 1;
    }
}

void free_memory(double* double_array, char* char_array, ComponentRecord* component_records) {
    free(double_array);
    free(char_array);
    for (int i = 0; i < MAX_COMPONENTS && component_records[i].data_ptr != NULL; ++i) {
        free(component_records[i].data_ptr);
    }
    free(component_records);
}

int main() {
    int double_size = 100;
    int char_size = 1024 * 1024; // 1MB
    int record_size = MAX_COMPONENTS;

    double* double_array = create_double_array(double_size);
    if (!double_array) return -1;

    char* char_array = read_char_array_from_file("data.bin", &char_size);
    if (!char_array) {
        free(double_array);
        return -1;
    }

    ComponentRecord* component_records = create_component_records(record_size);
    if (!component_records) {
        free(char_array);
        free(double_array);
        return -1;
    }

    populate_component_records(component_records, char_array, char_size, record_size);

    // Simulate usage
    for (int i = 0; i < record_size && component_records[i].data_ptr != NULL; ++i) {
        printf("Timestamp: %d, Usage Count: %d, Version: %d\n",
               component_records[i].timestamp,
               component_records[i].usage_count,
               component_records[i].version);
    }

    free_memory(double_array, char_array, component_records);

    return 0;
}
