    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i].offset = rand();
        records[i].key = rand();
        records[i].filename = malloc(256 * sizeof(char));
        snprintf(records[i].filename, 256, "file%d.txt", i);
    }
    pthread_mutex_unlock(&mutex);
}

void* recordThread(void* arg) {
    int threadId = *(int*)arg;
    for (int i = threadId; i < MAX_RECORDS; i += pthread_num_threads()) {
        pthread_mutex_lock(&mutex);
        printf("Thread %d processing record %d\n", threadId, i);
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

void monitorPerformance() {
    // Implement performance monitoring logic here
}

int main() {
    srand(time(NULL));
    initializeRecords();

    pthread_t threads[10];
    int threadIds[10];

    for (int i = 0; i < 10; i++) {
        threadIds[i] = i;
        pthread_create(&threads[i], NULL, recordThread, &threadIds[i]);
