typedef struct record {
    int value;
    time_t timestamp;
} Record;

typedef struct node {
    char identifier[256];
    int value;
    struct node* next;
} Node;

void initializeDataStructures(int numRecords, long* offsets, int* keys, Record** records, Node** head) {
    srand(time(NULL));
    setlocale(LC_ALL, "");

    for (int i = 0; i < numRecords; i++) {
        offsets[i] = rand() % 1000;
        keys[i] = rand() % 1000;

        records[i] = (Record*)malloc(sizeof(Record));
        records[i]->value = rand() % 1000;
        records[i]->timestamp = time(NULL);

        char keyStr[256];
        snprintf(keyStr, sizeof(keyStr), "key%d", keys[i]);
        strcpy(records[i]->identifier, keyStr);
    }

    *head = NULL;
    for (int i = 0; i < numRecords; i++) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        strcpy(newNode->identifier, records[i]->identifier);
        newNode->value = records[i]->value;
        newNode->next = *head;
        *head = newNode;
    }
}

void freeDataStructures(int numRecords, long* offsets, int* keys, Record** records, Node** head) {
    for (int i = 0; i < numRecords; i++) {
        free(records[i]);
    }

    Node* current = *head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
}

void findAndPrintLargest(int* array, int size) {
    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    printf("The largest number is: %d\n", largest);
}

int main() {
    int numRecords;
    printf("Enter the number of records: ");
    scanf("%d", &numRecords);

    long* offsets = (long*)malloc(numRecords * sizeof(long));
    int* keys = (int*)malloc(numRecords * sizeof(int));
    Record** records = (Record**)malloc(numRecords * sizeof(Record*));
    Node* head = NULL;

    initializeDataStructures(numRecords, offsets, keys, records, &head);

    int* array = (int*)malloc(numRecords * sizeof(int));
    for (int i = 0; i < numRecords; i++) {
        array[i] = records[i]->value;
    }

    findAndPrintLargest(array, numRecords);

    freeDataStructures(numRecords, offsets, keys, records, &head);
    free(array);

    return 0;
}
