#define MAX_RECORDS 100000
#define MEMORY_LIMIT 1024 * 1024 // 1 MB

typedef struct {
    int key;
    long* offset;
} Record;

Record** records;
int record_count = 0;
pthread_mutex_t lock;

void initialize_records(int range_start, int range_end) {
    pthread_mutex_lock(&lock);
    if (record_count >= MAX_RECORDS) {
        fprintf(stderr, "Error: Maximum number of records reached.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    Record* new_record = malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Error: Memory allocation failed for record.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    new_record->key = rand() % (range_end - range_start + 1) + range_start;

    long* offset_value = malloc(sizeof(long));
    if (!offset_value) {
        fprintf(stderr, "Error: Memory allocation failed for offset.\n");
        free(new_record);
        pthread_mutex_unlock(&lock);
        return;
    }

    *offset_value = (long)new_record; // Simulating an offset value
    new_record->offset = offset_value;

    records[record_count++] = new_record;
    pthread_mutex_unlock(&lock);
}

void* thread_function(void* arg) {
    int range_start = *(int*)arg;
    int range_end = range_start + 1000; // Example range for each thread

    srand(time(NULL));
    for (int i = 0; i < 1000; i++) {
        initialize_records(range_start, range_end);
    }

    return NULL;
}

int main() {
    pthread_t threads[10];
    int ranges[] = {0, 1000, 2000, 3000, 4000, 5000, 6000, 7000, 8000, 9000};

    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < 10; i++) {
        if (pthread_create(&threads[i], NULL, thread_function, &ranges[i]) != 0) {
            fprintf(stderr, "Error: Failed to create thread %d.\n", i);
            return 1;
        }
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    // Free all allocated memory
    for (int i = 0; i < record_count; i++) {
        free(records[i]->offset);
        free(records[i]);
    }
    free(records);

    pthread_mutex_destroy(&lock);

    return 0;
}
