#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_MESSAGES 1000
#define TABLE_SIZE 1024

typedef struct MessageNode {
    char *message;
    struct MessageNode *next;
} MessageNode;

typedef struct Record {
    int id;
    char *key;
    MessageNode *node;
    int status; // 0: inactive, 1: active
} Record;

typedef struct HashTable {
    Record **buckets;
    pthread_mutex_t lock;
} HashTable;

HashTable *create_hash_table() {
    HashTable *table = (HashTable *)malloc(sizeof(HashTable));
    table->buckets = (Record **)calloc(TABLE_SIZE, sizeof(Record *));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void destroy_hash_table(HashTable *table) {
    for (int i = 0; i < TABLE_SIZE; i++) {
        Record *record = table->buckets[i];
        while (record != NULL) {
            Record *next = record->next;
            free(record->key);
            MessageNode *node = record->node;
            while (node != NULL) {
                MessageNode *next_node = node->next;
                free(node->message);
                free(node);
                node = next_node;
            }
            free(record);
            record = next;
        }
    }
    pthread_mutex_destroy(&table->lock);
    free(table->buckets);
    free(table);
}

void add_message_to_list(MessageNode **head, const char *message) {
    MessageNode *new_node = (MessageNode *)malloc(sizeof(MessageNode));
    new_node->message = strdup(message);
    new_node->next = *head;
    *head = new_node;
}

int hash_function(int id) {
    return abs(id % TABLE_SIZE);
}

void add_record(HashTable *table, int id, const char *key, MessageNode *node) {
    pthread_mutex_lock(&table->lock);
    int index = hash_function(id);
    Record *new_record = (Record *)malloc(sizeof(Record));
    new_record->id = id;
    new_record->key = strdup(key);
    new_record->node = node;
    new_record->status = 1;
    new_record->next = table->buckets[index];
    table->buckets[index] = new_record;
    pthread_mutex_unlock(&table->lock);
}

void update_record(HashTable *table, int id, const char *key) {
    pthread_mutex_lock(&table->lock);
    int index = hash_function(id);
    Record *record = table->buckets[index];
    while (record != NULL) {
        if (record->id == id) {
            free(record->key);
            record->key = strdup(key);
            break;
        }
        record = record->next;
    }
    pthread_mutex_unlock(&table->lock);
}

void delete_record(HashTable *table, int id) {
    pthread_mutex_lock(&table->lock);
    int index = hash_function(id);
    Record **current = &table->buckets[index];
    while (*current != NULL) {
        if ((*current)->id == id) {
            Record *temp = *current;
            *current = temp->next;
            free(temp->key);
            MessageNode *node = temp->node;
            while (node != NULL) {
                MessageNode *next_node = node->next;
                free(node->message);
                free(node);
                node = next_node;
            }
            free(temp);
            break;
        }
        current = &(*current)->next;
    }
    pthread_mutex_unlock(&table->lock);
}

void read_messages_from_file(HashTable *table, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Failed to open file");
        return;
    }

    int id;
    char message[256];
    while (fscanf(file, "%d %s", &id, message) != EOF) {
        MessageNode *node = NULL;
        add_message_to_list(&node, message);
        add_record(table, id, message, node);
    }

    fclose(file);
}

int main() {
    HashTable *table = create_hash_table();
    read_messages_from_file(table, "messages.txt");
    // Perform other operations on the table
    destroy_hash_table(table);
    return 0;
}
