#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_MEMORY 1024 * 1024 // 1 MB
#define RECORD_SIZE sizeof(long) + sizeof(int)

typedef struct Node {
    int value;
    struct Node* next;
} Node;

typedef struct Record {
    long offset;
    int key;
    Node* values;
} Record;

Record** create_records(int num_records, int max_values_per_record, int min_value, int max_value, int* total_memory_used) {
    if (num_records * RECORD_SIZE > MAX_MEMORY) {
        fprintf(stderr, "Error: Maximum memory threshold exceeded.\n");
        return NULL;
    }

    Record** records = (Record**)malloc(num_records * sizeof(Record*));
    if (!records) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_records; ++i) {
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            fprintf(stderr, "Error: Memory allocation failed for record %d.\n", i);
            // Cleanup previously allocated resources
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records);
            return NULL;
        }

        records[i]->offset = rand() % MAX_MEMORY;
        records[i]->key = rand() % max_value + min_value;

        Node* head = NULL;
        Node* tail = NULL;
        for (int j = 0; j < rand() % max_values_per_record + 1; ++j) {
            Node* new_node = (Node*)malloc(sizeof(Node));
            if (!new_node) {
                fprintf(stderr, "Error: Memory allocation failed for value in record %d.\n", i);
                // Cleanup previously allocated resources
                while (head) {
                    Node* temp = head;
                    head = head->next;
                    free(temp);
                }
                free(records[i]);
                for (int k = 0; k < i; ++k) {
                    free(records[k]);
                }
                free(records);
                return NULL;
            }

            new_node->value = rand() % max_value + min_value;
            new_node->next = NULL;

            if (!head) {
                head = tail = new_node;
            } else {
                tail->next = new_node;
                tail = new_node;
            }
        }

        records[i]->values = head;
    }

    *total_memory_used = num_records * RECORD_SIZE;
    return records;
}

void free_records(Record** records, int num_records) {
    for (int i = 0; i < num_records; ++i) {
        Node* current = records[i]->values;
        while (current) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }
        free(records[i]);
    }
    free(records);
}

int main() {
    int num_records = 100;
    int max_values_per_record = 5;
    int min_value = 0;
    int max_value = 1000;

    int total_memory_used;
    Record** records = create_records(num_records, max_values_per_record, min_value, max_value, &total_memory_used);

    if (records) {
        printf("Total memory used: %d bytes\n", total_memory_used);
        free_records(records, num_records);
    }

    return 0;
}
