#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <locale.h>

#define MAX_RECORDS 1000
#define MAX_VALUES_PER_RECORD 100
#define MEMORY_THRESHOLD 1024 * 1024 // 1 MB

typedef struct ValueNode {
    int value;
    struct ValueNode* next;
} ValueNode;

typedef struct Record {
    long offset;
    int key;
    ValueNode* values;
    pthread_mutex_t lock;
} Record;

Record records[MAX_RECORDS];
int record_count = 0;
pthread_mutex_t global_lock;

void initialize_record(Record* record, long offset, int key) {
    record->offset = offset;
    record->key = key;
    record->values = NULL;
    pthread_mutex_init(&record->lock, NULL);
}

void add_value_to_record(Record* record, int value) {
    pthread_mutex_lock(&record->lock);
    ValueNode* new_node = (ValueNode*)malloc(sizeof(ValueNode));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    new_node->value = value;
    new_node->next = record->values;
    record->values = new_node;
    pthread_mutex_unlock(&record->lock);
}

void remove_value_from_record(Record* record, int value) {
    pthread_mutex_lock(&record->lock);
    ValueNode* current = record->values;
    ValueNode* previous = NULL;

    while (current != NULL) {
        if (current->value == value) {
            if (previous == NULL) {
                record->values = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&record->lock);
}

int find_largest_value(Record* record) {
    int largest = INT_MIN;
    ValueNode* current = record->values;

    while (current != NULL) {
        if (current->value > largest) {
            largest = current->value;
        }
        current = current->next;
    }

    return largest;
}

void* initialize_records(void* arg) {
    int upper_bound = *(int*)arg;
    pthread_mutex_lock(&global_lock);
    if (record_count >= MAX_RECORDS) {
        fprintf(stderr, "Maximum number of records reached\n");
        pthread_mutex_unlock(&global_lock);
        return NULL;
    }
    Record* record = &records[record_count];
    initialize_record(record, rand() % 1000000, rand() % upper_bound);
    record_count++;
    pthread_mutex_unlock(&global_lock);
    return NULL;
}

int main() {
    setlocale(LC_ALL, "");
    int upper_bound;

    printf("Enter the upper bound for random numbers: ");
    scanf("%d", &upper_bound);

    pthread_t threads[MAX_RECORDS];
    int thread_args[MAX_RECORDS];

    srand(time(NULL));

    for (int i = 0; i < MAX_RECORDS; i++) {
        thread_args[i] = upper_bound;
        if (pthread_create(&threads[i], NULL, initialize_records, &thread_args[i]) != 0) {
            fprintf(stderr, "Failed to create thread\n");
            return 1;
        }
    }

    for (int i = 0; i < MAX_RECORDS; i++) {
        pthread_join(threads[i], NULL);
    }

    int largest_value = INT_MIN;

    for (int i = 0; i < record_count; i++) {
        Record* record = &records[i];
        int value = find_largest_value(record);
        if (value > largest_value) {
            largest_value = value;
        }
    }

    printf("Largest value: %d\n", largest_value);

    return 0;
}
