import java.util.*;
import java.util.concurrent.*;

public class DeviceConfigProcessor {
    private final Map<String, Set<String>> deviceModels = new ConcurrentHashMap<>();
    private final ExecutorService executor = Executors.newFixedThreadPool(10);
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);

    public void processUpdate(String model, String config) {
        executor.submit(() -> {
            try {
                long startTime = System.currentTimeMillis();
                Set<String> secureSettings = fetchSecureSettings(model);
                if (secureSettings != null && !secureSettings.isEmpty()) {
                    deviceModels.computeIfAbsent(model, k -> new HashSet<>()).addAll(secureSettings);
                }
                long endTime = System.currentTimeMillis();
                System.out.println("Processed " + model + " in " + (endTime - startTime) + " ms");
            } catch (Exception e) {
                handleException(e);
            }
        });
    }

    private Set<String> fetchSecureSettings(String model) throws Exception {
        // Simulate fetching secure settings from an external data source
        Thread.sleep(100); // Simulate network delay
        if ("invalidModel".equals(model)) {
            throw new IllegalArgumentException("Invalid device model");
        }
        return Arrays.asList("setting1", "setting2"); // Example secure settings
    }

    private void handleException(Exception e) {
        System.err.println("Error processing update: " + e.getMessage());
    }

    public int getUniqueSecureModelsCount() {
        return deviceModels.size();
    }

    public void shutdown() {
        executor.shutdown();
        scheduler.shutdown();
    }
}
