// Define structures
typedef struct {
    int value;
} record;

typedef struct {
    time_t timestamp;
    char* file_path;
} metadata;

// Function to find and print the largest integer in an array
void find_and_print_largest(int* arr, int size) {
    if (size <= 0) return;
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    printf("Largest integer: %d\n", max);
}

// Function to initialize arrays and records
int initialize_arrays(int* keys, record** recs, metadata** metas, int size, int upper_bound) {
    srand(time(NULL));

    // Allocate memory for arrays
    if ((keys = (int*)malloc(size * sizeof(int))) == NULL) return -1;
    if ((recs = (record**)malloc(size * sizeof(record*))) == NULL) {
        free(keys);
        return -1;
    }
    if ((metas = (metadata**)malloc(size * sizeof(metadata*))) == NULL) {
        free(keys);
        free(recs);
        return -1;
    }

    // Initialize arrays
    for (int i = 0; i < size; i++) {
        keys[i] = rand() % upper_bound + 1;
        recs[i] = (record*)malloc(sizeof(record));
        metas[i] = (metadata*)malloc(sizeof(metadata));

        if (recs[i] == NULL || metas[i] == NULL) {
            for (int j = 0; j < i; j++) {
                free(recs[j]);
                free(metas[j]);
            }
            free(keys);
            free(recs);
            return -1;
        }

        recs[i]->value = rand() % upper_bound + 1;
        metas[i]->timestamp = time(NULL);
        metas[i]->file_path = (char*)malloc(256 * sizeof(char));
        sprintf(metas[i]->file_path, "record_%d.txt", i);
    }

    return 0;
}

// Function to free allocated memory
void free_memory(int* keys, record** recs, metadata** metas, int size) {
    for (int i = 0; i < size; i++) {
        free(recs[i]);
        free(metas[i]->file_path);
        free(metas[i]);
    }
    free(keys);
    free(recs);
    free(metas);
}

// Main function
int main() {
    int size, upper_bound;
    printf("Enter the number of elements: ");
    scanf("%d", &size);
    printf("Enter the upper bound for random numbers: ");
    scanf("%d", &upper_bound);

    int* keys = NULL;
    record** recs = NULL;
    metadata** metas = NULL;

    if (initialize_arrays(keys, recs, metas, size, upper_bound) == 0) {
        find_and_print_largest(keys, size);
        free_memory(keys, recs, metas, size);
    } else {
        printf("Memory allocation failed.\n");
    }

    return 0;
}
