LocationDatabase* initialize_records(size_t size, int upper_bound) {
    LocationDatabase *db = (LocationDatabase*)malloc(sizeof(LocationDatabase));
    if (!db) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    db->offsets = (long*)calloc(size, sizeof(long));
    db->keys = (int*)calloc(size, sizeof(int));
    db->records = (Record*)calloc(size, sizeof(Record));
    if (!db->offsets || !db->keys || !db->records) {
        fprintf(stderr, "Memory allocation failed\n");
        free(db);
        return NULL;
    }

    pthread_mutex_init(&db->lock, NULL);

    for (size_t i = 0; i < size; ++i) {
        db->offsets[i] = rand() % upper_bound;
        db->keys[i] = rand() % upper_bound;
        snprintf(db->records[i].name, sizeof(db->records[i].name), "Location%d", i);
    }

    db->size = size;

    return db;
}

void free_records(LocationDatabase *db) {
    if (db) {
        pthread_mutex_destroy(&db->lock);
        free(db->offsets);
        free(db->keys);
        free(db->records);
        free(db);
    }
}
