#include <stdlib.h>
#include <string.h>

typedef struct item {
    char* str;
    int value;
    struct item* next;
} Item;

Item* create_item(const char* str, int value) {
    Item* new_item = (Item*)malloc(sizeof(Item));
    if (new_item == NULL) return NULL;
    new_item->str = strdup(str);
    if (new_item->str == NULL) {
        free(new_item);
        return NULL;
    }
    new_item->value = value;
    new_item->next = NULL;
    return new_item;
}

void add_item(Item** head, const char* str, int value) {
    Item* new_item = create_item(str, value);
    if (new_item == NULL) return;

    new_item->next = *head;
    *head = new_item;
}

void traverse_list(const Item* head) {
    for (const Item* current = head; current != NULL; current = current->next) {
        printf("String: %s, Value: %d\n", current->str, current->value);
    }
}

void update_values(Item* head, int (*callback)(int)) {
    for (Item* current = head; current != NULL; current = current->next) {
        current->value = callback(current->value);
    }
}

void free_list(Item** head) {
    Item* current = *head;
    while (current != NULL) {
        Item* next = current->next;
        free(current->str);
        free(current);
        current = next;
    }
    *head = NULL;
}
