#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
    char* message;
    double average;
} record;

void initialize_records(record** records, long* offsets, int* keys, double* values, int size) {
    *records = (record*)malloc(size * sizeof(record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    for (int i = 0; i < size; i++) {
        (*records)[i].value = rand() % 100;
        (*records)[i].message = strdup("Default message");
        (*records)[i].average = 0.0;

        offsets[i] = rand();
        keys[i] = rand() % 100;
        values[i] = (double)rand() / RAND_MAX * 100.0;
    }
}

void find_largest_integer(record* records, int size) {
    int largest = records[0].value;
    for (int i = 1; i < size; i++) {
        if (records[i].value > largest) {
            largest = records[i].value;
        }
    }
    printf("Largest integer: %d\n", largest);
}

void find_smallest_double(record* records, int size) {
    double smallest = records[0].average;
    for (int i = 1; i < size; i++) {
        if (records[i].average < smallest) {
            smallest = records[i].average;
        }
    }
    printf("Smallest double: %f\n", smallest);
}

void validate_offsets(record* records, long* offsets, int size) {
    for (int i = 0; i < size; i++) {
        if (offsets[i] != records[i].value) {
            fprintf(stderr, "Offset validation failed at index %d\n", i);
        }
    }
}

void log_error(const char* message) {
    printf("Error: %s\n", message);
}

int main() {
    srand(time(NULL));

    int size = 10;
    record* records;
    long* offsets;
    int* keys;
    double* values;

    initialize_records(&records, &offsets, &keys, &values, size);

    find_largest_integer(records, size);
    find_smallest_double(records, size);

    validate_offsets(records, offsets, size);

    for (int i = 0; i < size; i++) {
        free(records[i].message);
    }
    free(records);
    free(offsets);
    free(keys);
    free(values);

    return 0;
}
