#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <pthread.h>

#define MAX_LOCATIONS 10000000

typedef struct {
    double latitude;
    double longitude;
    double elevation;
    char name[256];
} Location;

typedef struct {
    Location *locations;
    int count;
    pthread_mutex_t lock;
} LocationManager;

LocationManager *create_location_manager() {
    LocationManager *manager = (LocationManager *)malloc(sizeof(LocationManager));
    manager->locations = (Location *)malloc(MAX_LOCATIONS * sizeof(Location));
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_location_manager(LocationManager *manager) {
    free(manager->locations);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void add_location(LocationManager *manager, Location location) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count < MAX_LOCATIONS) {
        manager->locations[manager->count++] = location;
    }
    pthread_mutex_unlock(&manager->lock);
}

Location find_nearest_location(LocationManager *manager, double latitude, double longitude, double radius) {
    Location nearest;
    double min_distance = 180.0; // Maximum possible distance on Earth's surface
    for (int i = 0; i < manager->count; i++) {
        double distance = acos(sin(latitude) * sin(manager->locations[i].latitude) +
                               cos(latitude) * cos(manager->locations[i].latitude) *
                               cos(longitude - manager->locations[i].longitude)) * 6371.0;
        if (distance < min_distance && distance <= radius) {
            nearest = manager->locations[i];
            min_distance = distance;
        }
    }
    return nearest;
}

