// Define a simple R-tree node structure (simplified version)
typedef struct RTreeNode {
    GeoData *data;
    int count;
    struct RTreeNode **children;
} RTreeNode;

// Function to create a new R-tree node
RTreeNode* createRTreeNode() {
    RTreeNode *node = (RTreeNode*)malloc(sizeof(RTreeNode));
    if (node == NULL) {
        perror("Failed to allocate memory for R-tree node");
        exit(EXIT_FAILURE);
    }
    node->data = NULL;
    node->count = 0;
    node->children = NULL;
    return node;
}

// Function to insert data into the R-tree
void insertRTree(RTreeNode *node, GeoData *data) {
    // Simplified insertion logic (not thread-safe)
    if (node->count == 0) {
        node->data = data;
        node->count++;
    } else {
        // Split and redistribute nodes as needed
        printf("Splitting and redistributing nodes...\n");
    }
}

// Function to search for nearest location within a specified radius
GeoData* findNearestLocation(RTreeNode *node, double latitude, double longitude, double radius) {
    // Simplified search logic (not thread-safe)
    if (node->data != NULL) {
        double distance = calculateDistance(latitude, longitude, node->data->latitude, node->data->longitude);
        if (distance <= radius) {
            return node->data;
        }
    }
    return NULL;
}

// Function to calculate the Euclidean distance between two points
double calculateDistance(double lat1, double lon1, double lat2, double lon2) {
    // Simplified distance calculation logic
    const double R = 6371.0; // Earth's radius in kilometers
    double dLat = (lat2 - lat1) * M_PI / 180;
    double dLon = (lon2 - lon1) * M_PI / 180;
    double a = sin(dLat / 2) * sin(dLat / 2) +
               cos(lat1 * M_PI / 180) * cos(lat2 * M_PI / 180) *
               sin(dLon / 2) * sin(dLon / 2);
    double c = 2 * atan2(sqrt(a), sqrt(1 - a));
    return R * c;
}

// Function to handle concurrent access using mutexes
pthread_mutex_t lock;

void* insertData(void *arg) {
