    data->longitude = -118.2437;
    data->elevation = 0.0;
    insertRTree(rootNode, data);
    pthread_mutex_unlock(&lock);
    return NULL;
}

int main() {
    // Initialize the R-tree root node
    RTreeNode *rootNode = createRTreeNode();

    // Initialize mutex for thread-safe operations
    if (pthread_mutex_init(&lock, NULL) != 0) {
        perror("Failed to initialize mutex");
        exit(EXIT_FAILURE);
    }

    // Example usage of concurrent insertion
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        if (pthread_create(&threads[i], NULL, insertData, NULL) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
    }

    // Wait for all threads to complete
    for (int i = 0; i < 10; i++) {
