// Define the structure for a node in the linked list
typedef struct Node {
    char* str;
    int value;
    struct Node* next;
} Node;

// Function to create a new node with given string and integer value
Node* create_node(const char* str, int value) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        return NULL; // Memory allocation failed
    }
    new_node->str = strdup(str);
    new_node->value = value;
    new_node->next = NULL;
    return new_node;
}

// Function to insert a node into the linked list
void insert_node(Node** head, const char* str, int value) {
    Node* new_node = create_node(str, value);
    if (new_node == NULL) {
        // Handle memory allocation failure
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    new_node->next = *head;
    *head = new_node;
}

// Function to free the linked list and its nodes
void free_list(Node* head) {
    Node* current = head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->str);
        free(current);
        current = next;
    }
}

int main() {
    // Example usage of the linked list functions
    Node* head = NULL;

    insert_node(&head, "Hello", 10);
    insert_node(&head, "World", 20);

    // Free the allocated memory when done
    free_list(head);

    return 0;
}
