<?php
class GameConfig {
    private $config;
    private $cache;

    public function __construct($filePath) {
        $this->cache = new Cache();
        if ($this->cache->exists('game_config')) {
            $this->config = $this->cache->get('game_config');
        } else {
            $this->config = $this->loadConfig($filePath);
            $this->cache->set('game_config', $this->config, 3600); // Cache for 1 hour
        }
    }

    private function loadConfig($filePath) {
        if (file_exists($filePath)) {
            return json_decode(file_get_contents($filePath), true);
        } else {
            return [
                'tile_size' => 32,
                'world_dimensions' => ['width' => 100, 'height' => 100],
                'camera_settings' => ['zoom' => 1.0]
            ];
        }
    }

    public function getConfig($key) {
        return $this->config[$key] ?? null;
    }
}

class Cache {
    private $data = [];

    public function exists($key) {
        return array_key_exists($key, $this->data);
    }

    public function get($key) {
        return $this->data[$key];
    }

    public function set($key, $value, $ttl) {
        $this->data[$key] = [
            'value' => $value,
            'expiry' => time() + $ttl
        ];
    }
}
?>
