#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000
#define CACHE_SIZE 100

typedef struct {
    int value;
} record;

typedef struct {
    char *description;
} metadata;

typedef struct {
    long offset;
    int key;
    record rec;
    metadata meta;
} data_structure;

data_structure *cache[CACHE_SIZE];
int cache_size = 0;

void init_cache() {
    for (int i = 0; i < CACHE_SIZE; i++) {
        cache[i] = NULL;
    }
}

int find_in_cache(int key) {
    for (int i = 0; i < cache_size; i++) {
        if (cache[i]->key == key) {
            return i;
        }
    }
    return -1;
}

void add_to_cache(data_structure *ds) {
    if (cache_size >= CACHE_SIZE) {
        // Evict least recently used item
        free(cache[0]);
        for (int i = 1; i < cache_size; i++) {
            cache[i-1] = cache[i];
        }
        cache_size--;
    }
    cache[cache_size++] = ds;
}

data_structure *get_data_structure(int key) {
    int index = find_in_cache(key);
    if (index != -1) {
        return cache[index];
    } else {
        // Simulate fetching from external database
        data_structure *ds = malloc(sizeof(data_structure));
        ds->key = key;
        ds->rec.value = rand() % 100; // Random value within upper bound
        ds->meta.description = strdup("Sample metadata");
        add_to_cache(ds);
        return ds;
    }
}

void free_data_structures(data_structure *ds, int size) {
    for (int i = 0; i < size; i++) {
        free(ds[i].meta.description);
        free(&ds[i]);
    }
    free(ds);
}

int main() {
    srand(time(NULL));
    init_cache();

    int size = 5;
    data_structure *data = malloc(size * sizeof(data_structure));

    for (int i = 0; i < size; i++) {
        data[i] = get_data_structure(i);
    }

    // Simulate using the data
    for (int i = 0; i < size; i++) {
        printf("Key: %d, Value: %d\n", data[i].key, data[i].rec.value);
    }

    free_data_structures(data, size);

    return 0;
}
