#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_CONNECTIONS 100

typedef struct User {
    int id;
    char attributes[256];
    struct User* followers[MAX_CONNECTIONS];
    struct User* following[MAX_CONNECTIONS];
    int followerCount;
    int followingCount;
} User;

User* createUser(int id, const char* attributes) {
    User* newUser = (User*)malloc(sizeof(User));
    if (!newUser) {
        fprintf(stderr, "Memory allocation failed for user %d\n", id);
        return NULL;
    }
    newUser->id = id;
    strncpy(newUser->attributes, attributes, sizeof(newUser->attributes) - 1);
    newUser->attributes[sizeof(newUser->attributes) - 1] = '\0';
    newUser->followerCount = 0;
    newUser->followingCount = 0;
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        newUser->followers[i] = NULL;
        newUser->following[i] = NULL;
    }
    return newUser;
}

void freeUser(User* user) {
    if (!user) return;
    for (int i = 0; i < user->followerCount; i++) {
        freeUser(user->followers[i]);
    }
    for (int i = 0; i < user->followingCount; i++) {
        freeUser(user->following[i]);
    }
    free(user);
}

void addFollower(User* follower, User* following) {
    if (follower->followerCount >= MAX_CONNECTIONS || following->followingCount >= MAX_CONNECTIONS) {
        fprintf(stderr, "Maximum connections reached for user %d\n", follower->id);
        return;
    }
    follower->followers[follower->followerCount++] = following;
    following->following[following->followingCount++] = follower;
}

void removeFollower(User* follower, User* following) {
    for (int i = 0; i < follower->followerCount; i++) {
        if (follower->followers[i] == following) {
            follower->followers[i] = follower->followers[--follower->followerCount];
            break;
        }
    }
    for (int i = 0; i < following->followingCount; i++) {
        if (following->following[i] == follower) {
            following->following[i] = following->following[--following->followingCount];
            break;
        }
    }
}

// Additional functions for synchronization, logging, and performance monitoring can be added here
