Node** create_node_list(int size, int range_start, int range_end) {
    Node** list = (Node**)malloc(size * sizeof(Node*));
    if (!list) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < size; ++i) {
        list[i] = (Node*)malloc(sizeof(Node));
        if (!list[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            // Free previously allocated nodes
            for (int j = 0; j < i; ++j) {
                free(list[j]);
            }
            free(list);
            return NULL;
        }

        list[i]->key = (char*)malloc(10 * sizeof(char)); // Assuming key length <= 9
        if (!list[i]->key) {
            fprintf(stderr, "Memory allocation failed\n");
            // Free previously allocated nodes and keys
            for (int j = 0; j < i; ++j) {
                free(list[j]);
                free(list[j]->key);
            }
            free(list);
            return NULL;
        }

        list[i]->next = NULL;
        list[i]->values = (Value*)malloc(10 * sizeof(Value)); // Assuming initial capacity of 10 values
        if (!list[i]->values) {
            fprintf(stderr, "Memory allocation failed\n");
            // Free previously allocated nodes, keys, and values
            for (int j = 0; j < i; ++j) {
                free(list[j]);
                free(list[j]->key);
                free(list[j]->values);
            }
            free(list);
            return NULL;
        }

        list[i]->value_count = 0;

        // Initialize key and values
