    for (int i = 0; i < size; i++) {
        records[i] = malloc(sizeof(Record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        records[i]->value = i;
        records[i]->identifier = strdup(default_message);
    }
}

// Function to free allocated memory for records
void free_records(Record **records, int size) {
    for (int i = 0; i < size; i++) {
        if (records[i]) {
            free(records[i]->identifier);
            free(records[i]);
        }
    }
}

// Main function to demonstrate the library usage
int main() {
    const char *default_message = "Default Message";
    int num_records = 5;
    Record **records = malloc(num_records * sizeof(Record *));

    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    init_records(records, num_records, default_message);

    // Use the records...

    free_records(records, num_records);
    free(records);

    return EXIT_SUCCESS;
}
