typedef struct {
    int value;
    double accuracy;
} Measurement;

typedef struct {
    time_t timestamp;
} Timestamp;

int initializeArrays(int size, float** floatArray, char** tagArray, Measurement** measurementArray, Timestamp** timestampArray) {
    *floatArray = (float*)malloc(size * sizeof(float));
    *tagArray = (char*)malloc(size * sizeof(char));
    *measurementArray = (Measurement*)malloc(size * sizeof(Measurement));
    *timestampArray = (Timestamp*)malloc(size * sizeof(Timestamp));

    if (*floatArray == NULL || *tagArray == NULL || *measurementArray == NULL || *timestampArray == NULL) {
        free(*floatArray);
        free(*tagArray);
        free(*measurementArray);
        free(*timestampArray);
        return -1; // Memory allocation failed
    }

    srand(time(NULL));
    double scaleFactor = 0.01;

    for (int i = 0; i < size; i++) {
        (*floatArray)[i] = (float)(rand() % 100); // Random float between 0 and 99
        (*tagArray)[i] = 'A' + (i % 26); // Simple tag generation
        (*measurementArray)[i].value = rand() % 100; // Random int value
        (*measurementArray)[i].accuracy = scaleFactor * (*measurementArray)[i].value;
        (*timestampArray)[i].timestamp = time(NULL);
    }

