#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    int x;
    int y;
    bool valid;
} data_point;

typedef struct {
    double* doubles;
    char* chars;
    data_point* points;
    size_t count;
} initialized_arrays;

initialized_arrays* read_data_points(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    // Initial allocation
    size_t initial_count = 1024;
    double* doubles = malloc(initial_count * sizeof(double));
    char* chars = malloc(initial_count * sizeof(char));
    data_point* points = malloc(initial_count * sizeof(data_point));
    if (!doubles || !chars || !points) {
        perror("Initial memory allocation failed");
        free(doubles);
        free(chars);
        free(points);
        fclose(file);
        return NULL;
    }

    size_t count = 0;
    while (fread(&points[count].x, sizeof(int), 1, file) == 1 &&
           fread(&points[count].y, sizeof(int), 1, file) == 1 &&
           fread(&points[count].valid, sizeof(bool), 1, file) == 1) {
        if (points[count].x < -1000 || points[count].x > 1000 ||
            points[count].y < -1000 || points[count].y > 1000 ||
            abs(points[count].x + points[count].y) > 500) {
            continue; // Skip invalid data point
        }
        doubles[count] = (double)points[count].x;
        chars[count] = (char)points[count].y;
        count++;
        if (count == initial_count) {
            // Reallocate with more space
            double* new_doubles = realloc(doubles, 2 * initial_count * sizeof(double));
            char* new_chars = realloc(chars, 2 * initial_count * sizeof(char));
            data_point* new_points = realloc(points, 2 * initial_count * sizeof(data_point));
            if (!new_doubles || !new_chars || !new_points) {
                perror("Memory reallocation failed");
                free(doubles);
                free(chars);
                free(points);
                fclose(file);
                return NULL;
            }
            doubles = new_doubles;
            chars = new_chars;
            points = new_points;
            initial_count *= 2;
        }
    }

    // Resize arrays to fit exactly
    double* final_doubles = realloc(doubles, count * sizeof(double));
    char* final_chars = realloc(chars, count * sizeof(char));
    data_point* final_points = realloc(points, count * sizeof(data_point));
    if (!final_doubles || !final_chars || !final_points) {
        perror("Final memory reallocation failed");
        free(doubles);
        free(chars);
        free(points);
        fclose(file);
        return NULL;
    }
    doubles = final_doubles;
    chars = final_chars;
    points = final_points;

    initialized_arrays* result = malloc(sizeof(initialized_arrays));
    if (!result) {
        perror("Failed to allocate result structure");
        free(doubles);
        free(chars);
        free(points);
        fclose(file);
        return NULL;
    }
    result->doubles = doubles;
    result->chars = chars;
    result->points = points;
    result->count = count;

    fclose(file);
    return result;
}
