        reading->humidity < 0 || reading->humidity > 100 ||
        reading->pressure < 300 || reading->pressure > 1200) {
        return 0;
    }
    return 1;
}

void logError(const char *message) {
    printf("ERROR: %s\n", message);
}

int processSensorData(SensorData *data, float tempThreshold, float humThreshold, float pressThreshold) {
    for (int i = 0; i < data->count; i++) {
        if (!validateSensorReading(&data->readings[i], tempThreshold, humThreshold, pressThreshold)) {
            logError("Out-of-range sensor reading detected.");
        }
    }
    return 1;
}

int main() {
    SensorData data;
    data.count = 5;

    // Simulate receiving sensor readings
    for (int i = 0; i < data.count; i++) {
        data.readings[i].temperature = rand() % 200 - 50;
        data.readings[i].humidity = rand() % 101;
