        time_t now = time(NULL);
        data.metadata[i].timestamp = now;
    }

    float tempThreshold = 50, humThreshold = 80, pressThreshold = 600;
    if (!processSensorData(&data, tempThreshold, humThreshold, pressThreshold)) {
