#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SENSORS 10000

typedef struct sensor_data {
    long timestamp;
    float temperature;
    char location[50];
} SensorData;

typedef struct node {
    SensorData data;
    struct node* next;
} Node;

Node* head = NULL;
int count = 0;

void add_sensor_data(long timestamp, float temperature, const char* location) {
    if (count >= MAX_SENSORS) {
        printf("Sensor data limit reached.\n");
        return;
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        printf("Memory allocation failed.\n");
        return;
    }

    newNode->data.timestamp = timestamp;
    newNode->data.temperature = temperature;
    strcpy(newNode->data.location, location);
    newNode->next = NULL;

    Node* current = head;
    Node* previous = NULL;

    while (current != NULL && current->data.timestamp < timestamp) {
        previous = current;
        current = current->next;
    }

    if (previous == NULL) {
        newNode->next = head;
        head = newNode;
    } else {
        previous->next = newNode;
        newNode->next = current;
    }

    count++;
}

void print_all_data() {
    Node* current = head;
    while (current != NULL) {
        printf("Timestamp: %ld, Temperature: %.2f, Location: %s\n", 
               current->data.timestamp, current->data.temperature, current->data.location);
        current = current->next;
    }
}

Node* search_by_timestamp(long timestamp) {
    Node* current = head;
    while (current != NULL && current->data.timestamp != timestamp) {
        current = current->next;
    }
    return current;
}

void free_all_data() {
    Node* current = head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    head = NULL;
    count = 0;
}
