typedef struct record {
    int value;
    int *key_ptr;
    long *offset_ptr;
} Record;

Record* create_records(int num_records, int max_value_range) {
    if (num_records <= 0 || max_value_range <= 0) {
        return NULL; // Invalid input
    }

    Record *records = malloc(num_records * sizeof(Record));
    if (!records) {
        return NULL; // Memory allocation failed
    }

    long *offsets = malloc(num_records * sizeof(long));
    int *keys = malloc(num_records * sizeof(int));
    if (!offsets || !keys) {
        free(records);
        free(offsets); // Free previously allocated memory
        free(keys);
        return NULL; // Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < num_records; ++i) {
        do {
            keys[i] = rand() % max_value_range;
        } while (i > 0 && keys[i] == keys[i - 1]); // Ensure unique keys

        offsets[i] = i * sizeof(Record); // Example offset calculation
        records[i].value = rand() % max_value_range; // Random value for record
        records[i].key_ptr = &keys[i];
        records[i].offset_ptr = &offsets[i];
    }

    return records;
}

void free_records(Record *records, int num_records) {
    if (records) {
        free(records);
    }
}
