// Define sensor_data structure
typedef struct sensor_data {
    long timestamp;
    float temperature;
    char location[100];
    struct sensor_data *next;
} sensor_data;

// Function to create a new sensor_data record
sensor_data* create_sensor_record(long timestamp, float temperature, const char* location) {
    sensor_data* new_record = (sensor_data*)malloc(sizeof(sensor_data));
    if (new_record == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_record->timestamp = timestamp;
    new_record->temperature = temperature;
    strncpy(new_record->location, location, sizeof(new_record->location) - 1);
    new_record->next = NULL;
    return new_record;
}

// Function to insert a record into the linked list
void insert_sensor_record(sensor_data** head, long timestamp, float temperature, const char* location) {
    sensor_data* new_record = create_sensor_record(timestamp, temperature, location);
    if (*head == NULL) {
        *head = new_record;
    } else {
        sensor_data* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_record;
    }
}

// Function to search for a record by timestamp
sensor_data* search_sensor_record(sensor_data* head, long timestamp) {
    sensor_data* current = head;
    while (current != NULL) {
        if (current->timestamp == timestamp) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

// Function to free the linked list
void free_sensor_list(sensor_data* head) {
    sensor_data* current = head;
    while (current != NULL) {
        sensor_data* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    sensor_data* sensor_head = NULL;

    // Example usage
    insert_sensor_record(&sensor_head, time(NULL), 23.5, "Room A");
    insert_sensor_record(&sensor_head, time(NULL) + 60, 24.1, "Room B");

    long search_timestamp = time(NULL);
    sensor_data* found_record = search_sensor_record(sensor_head, search_timestamp);
    if (found_record != NULL) {
        printf("Found record: Timestamp=%ld, Temperature=%.1f, Location=%s\n",
               found_record->timestamp, found_record->temperature, found_record->location);
    } else {
        printf("Record not found\n");
    }

    free_sensor_list(sensor_head);

    return 0;
}
