class MemoryPool {
public:
    MemoryPool(size_t block_size, size_t num_blocks) : block_size(block_size), pool(num_blocks * block_size) {}

    void* allocate() {
        if (free_list.empty()) {
            return &pool[0];
        }
        void* ptr = free_list.back();
        free_list.pop_back();
        return ptr;
    }

    void deallocate(void* ptr) {
        free_list.push_back(ptr);
    }

