Node** initialize_nodes(int num_nodes, int initial_value) {
    Node** nodes = (Node**)malloc(num_nodes * sizeof(Node*));
    if (!nodes) {
        perror("Failed to allocate memory for nodes");
        return NULL;
    }

    for (int i = 0; i < num_nodes; ++i) {
        nodes[i] = (Node*)malloc(sizeof(Node));
        if (!nodes[i]) {
            perror("Failed to allocate memory for node");
            // Free previously allocated nodes
            for (int j = 0; j < i; ++j) {
                free(nodes[j]->data);
                free(nodes[j]);
            }
            free(nodes);
            return NULL;
        }

        nodes[i]->data = (Record*)malloc(sizeof(Record));
        if (!nodes[i]->data) {
            perror("Failed to allocate memory for record");
            // Free previously allocated nodes and records
            for (int j = 0; j <= i; ++j) {
                free(nodes[j]->data);
                free(nodes[j]);
            }
            free(nodes);
            return NULL;
        }

        nodes[i]->value = initial_value;
        nodes[i]->data->timestamp = time(NULL);
        nodes[i]->data->id = (unsigned short)i;
        nodes[i]->data->status = false;

        // Log initialization event
        log_event("INIT", i, nodes[i]->data->timestamp);
    }

    return nodes;
}

void free_nodes(Node** nodes, int num_nodes) {
    for (int i = 0; i < num_nodes; ++i) {
        free(nodes[i]->data);
        free(nodes[i]);
    }
    free(nodes);

    // Log deallocation event
    log_event("DEALLOC", -1, time(NULL));
}

void log_event(const char* operation, int node_index, long timestamp) {
    printf("%s at %ld for node %d\n", operation, timestamp, node_index);
}
