int initializeRecords(long numOffsets, int numKeys, int minOffset, int maxOffset, Record **records) {
    if (numKeys < numRecords) {
        printf("Error: Not enough unique keys for the number of records.\n");
        return -1;
    }

    long *offsets = (long *)malloc(numOffsets * sizeof(long));
    if (!offsets) {
        printf("Memory allocation failed for offsets.\n");
        return -1;
    }

    int *keys = (int *)malloc(numKeys * sizeof(int));
    if (!keys) {
        free(offsets);
        printf("Memory allocation failed for keys.\n");
        return -1;
    }

    Record *recordsArray = (Record *)malloc(numRecords * sizeof(Record));
    if (!recordsArray) {
        free(offsets);
        free(keys);
        printf("Memory allocation failed for records.\n");
        return -1;
    }

    srand(time(NULL));

    int keyIndex = 0;
    for (int i = 0; i < numRecords; ++i) {
        if (keyIndex >= numKeys) {
            keyIndex = 0; // Cycle through keys if not enough unique ones
        }
        recordsArray[i].offset = minOffset + rand() % (maxOffset - minOffset + 1);
        recordsArray[i].key = keys[keyIndex++];
    }

    *records = recordsArray;
    free(offsets);
    free(keys);

    return numRecords;
}

int main() {
    long numOffsets = 1000;
    int numKeys = 500;
    int minOffset = 0;
    int maxOffset = 10000;

    Record *records;
    int result = initializeRecords(numOffsets, numKeys, minOffset, maxOffset, &records);

    if (result != -1) {
        printf("Successfully initialized %d records.\n", result);
        // Free allocated memory
        free(records);
    }

    return 0;
}
