#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>

typedef struct {
    long timestamp;
    unsigned short id;
    bool status;
} record;

typedef struct node {
    record *data;
    int value;
} node;

typedef struct {
    node **nodes;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} node_array;

void init_node_array(node_array *array, size_t initial_capacity) {
    array->nodes = (node **)malloc(initial_capacity * sizeof(node *));
    for (size_t i = 0; i < initial_capacity; ++i) {
        array->nodes[i] = (node *)malloc(sizeof(node));
        array->nodes[i]->data = (record *)malloc(sizeof(record));
        array->nodes[i]->value = 0;
    }
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    pthread_cond_init(&array->cond, NULL);
}

void resize_node_array(node_array *array) {
    size_t new_capacity = array->capacity * 2;
    node **new_nodes = (node **)realloc(array->nodes, new_capacity * sizeof(node *));
    for (size_t i = array->capacity; i < new_capacity; ++i) {
        new_nodes[i] = (node *)malloc(sizeof(node));
        new_nodes[i]->data = (record *)malloc(sizeof(record));
        new_nodes[i]->value = 0;
    }
    array->nodes = new_nodes;
    array->capacity = new_capacity;
}

void add_node_to_array(node_array *array, record *new_record, int value) {
    pthread_mutex_lock(&array->lock);
    while (array->size == array->capacity) {
        pthread_cond_wait(&array->cond, &array->lock);
    }
    array->nodes[array->size]->data = new_record;
    array->nodes[array->size]->value = value;
    ++array->size;
    pthread_mutex_unlock(&array->lock);
    pthread_cond_signal(&array->cond);
}

void free_node_array(node_array *array) {
    for (size_t i = 0; i < array->capacity; ++i) {
        free(array->nodes[i]->data);
        free(array->nodes[i]);
    }
    free(array->nodes);
    pthread_mutex_destroy(&array->lock);
    pthread_cond_destroy(&array->cond);
}
