#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_PROFILES 100
#define CACHE_SIZE 50

typedef struct {
    char name[256];
    char email[256];
    char phone[20];
} UserProfile;

typedef struct {
    UserProfile profiles[MAX_PROFILES];
    int count;
    pthread_mutex_t lock;
} UserList;

UserList userList = { .count = 0, .lock = PTHREAD_MUTEX_INITIALIZER };

void addUserProfile(const UserProfile *profile) {
    pthread_mutex_lock(&userList.lock);
    if (userList.count < MAX_PROFILES) {
        memcpy(&userList.profiles[userList.count], profile, sizeof(UserProfile));
        userList.count++;
    }
    pthread_mutex_unlock(&userList.lock);
}

void removeUserProfile(int index) {
    pthread_mutex_lock(&userList.lock);
    if (index >= 0 && index < userList.count) {
        for (int i = index; i < userList.count - 1; i++) {
            memcpy(&userList.profiles[i], &userList.profiles[i + 1], sizeof(UserProfile));
        }
        userList.count--;
    }
    pthread_mutex_unlock(&userList.lock);
}

void serializeUserList(const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file != NULL) {
        fwrite(&userList.count, sizeof(int), 1, file);
        for (int i = 0; i < userList.count; i++) {
            fwrite(&userList.profiles[i], sizeof(UserProfile), 1, file);
        }
        fclose(file);
    }
}

void deserializeUserList(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file != NULL) {
        pthread_mutex_lock(&userList.lock);
        fread(&userList.count, sizeof(int), 1, file);
        for (int i = 0; i < userList.count && i < MAX_PROFILES; i++) {
            fread(&userList.profiles[i], sizeof(UserProfile), 1, file);
        }
        pthread_mutex_unlock(&userList.lock);
        fclose(file);
    }
}

void *getUserProfile(int index) {
    if (index >= 0 && index < userList.count) {
        return &userList.profiles[index];
    }
    return NULL;
}
