#include <string.h>
#include <pthread.h>

#define MAX_STRING_LENGTH 256

typedef struct {
    int id;
    double value;
    char* str;
} CustomStruct;

CustomStruct** create_and_initialize_array(int rows, int cols, const char* input_data[], double dataset[][3], int max_string_length) {
    if (rows <= 0 || cols <= 0 || !input_data || !dataset) {
        return NULL;
    }

    CustomStruct** array = (CustomStruct**)malloc(rows * sizeof(CustomStruct*));
    if (!array) {
        perror("Memory allocation failed for array");
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < rows; ++i) {
        array[i] = (CustomStruct*)malloc(cols * sizeof(CustomStruct));
        if (!array[i]) {
            perror("Memory allocation failed for row");
            // Clean up previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(array[j]);
            }
            free(array);
            return NULL;
        }

        pthread_mutex_lock(&mutex);

        for (int j = 0; j < cols; ++j) {
            array[i][j].id = dataset[i][j];
            array[i][j].value = dataset[i][j + 1];

            // Allocate memory for string and copy data
            array[i][j].str = (char*)malloc(max_string_length * sizeof(char));
            if (!array[i][j].str) {
                perror("Memory allocation failed for string");
                // Clean up previously allocated memory
                for (int k = 0; k <= j; ++k) {
                    free(array[i][k].str);
                }
                free(array[i]);
                for (int l = 0; l < i; ++l) {
                    free(array[l]);
                }
                free(array);
                pthread_mutex_unlock(&mutex);
                return NULL;
            }

            strncpy(array[i][j].str, input_data[j], max_string_length - 1);
            array[i][j].str[max_string_length - 1] = '\0'; // Ensure null-termination
        }

        pthread_mutex_unlock(&mutex);
    }

    pthread_mutex_destroy(&mutex);

    return array;
}

void free_array(CustomStruct** array, int rows) {
    if (!array) {
        return;
    }

    for (int i = 0; i < rows; ++i) {
        if (array[i]) {
            for (int j = 0; j < cols; ++j) {
                free(array[i][j].str);
            }
            free(array[i]);
        }
    }
    free(array);
}

int main() {
    const char* input_data[] = {"Hello", "World", "C Programming"};
    double dataset[][3] = {{1, 2.5, 3}, {4, 5.5, 6}, {7, 8.5, 9}};
    int rows = sizeof(dataset) / sizeof(dataset[0]);
    int cols = sizeof(dataset[0]) / sizeof(dataset[0][0]);

    CustomStruct** array = create_and_initialize_array(rows, cols, input_data, dataset, MAX_STRING_LENGTH);
    if (array) {
        // Use the array
        free_array(array, rows);
    }

    return 0;
}
