        return NULL;
    }

    Record* records = (Record*)malloc(size * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }

    int* keys = (int*)calloc(size, sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        free(records);
        return NULL;
    }

    long* offsets = (long*)malloc(size * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        free(keys);
        free(records);
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < size; ++i) {
        keys[i] = i;
        offsets[i] = rand() % offset_range;

        records[i].key = keys[i];
        records[i].offset = offsets[i];

        records[i].data = (int*)malloc(sizeof(int));
        if (!records[i].data) {
            perror("Failed to allocate memory for record data");
            for (int j = 0; j < i; ++j) {
                free(records[j].data);
            }
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }

        *records[i].data = rand() % data_range;
    }

    free(keys);
    free(offsets);

    return records;
}

void destroy_records(Record* records, int size) {
    if (!records) {
        return;
    }

    for (int i = 0; i < size; ++i) {
        free(records[i].data);
    }

    free(records);
}
