#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2

typedef struct Record {
    long offset;
    int key;
    int ref_count;
} Record;

typedef struct RecordManager {
    Record** records;
    size_t capacity;
    size_t size;
    size_t growth_factor;
} RecordManager;

Record* create_record(int key, long offset) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) return NULL;
    record->offset = offset;
    record->key = key;
    record->ref_count = 1;
    return record;
}

void free_record(Record* record) {
    free(record);
}

RecordManager* create_manager(size_t initial_capacity, size_t growth_factor) {
    RecordManager* manager = (RecordManager*)malloc(sizeof(RecordManager));
    if (!manager) return NULL;
    manager->records = (Record**)calloc(initial_capacity, sizeof(Record*));
    if (!manager->records) {
        free(manager);
        return NULL;
    }
    manager->capacity = initial_capacity;
    manager->size = 0;
    manager->growth_factor = growth_factor;
    return manager;
}

void free_manager(RecordManager* manager) {
    for (size_t i = 0; i < manager->size; ++i) {
        free_record(manager->records[i]);
    }
    free(manager->records);
    free(manager);
}

int add_record(RecordManager* manager, int key) {
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * manager->growth_factor;
        Record** new_records = (Record**)realloc(manager->records, new_capacity * sizeof(Record*));
        if (!new_records) return -1;
        manager->records = new_records;
        manager->capacity = new_capacity;
    }
    long offset = manager->size * 10; // Fixed increment value
    Record* record = create_record(key, offset);
    if (!record) return -1;
    manager->records[manager->size++] = record;
    return 0;
}

void increase_ref_count(RecordManager* manager, int key) {
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->records[i]->key == key) {
            manager->records[i]->ref_count++;
            break;
        }
    }
}

void decrease_ref_count(RecordManager* manager, int key) {
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->records[i]->key == key) {
            manager->records[i]->ref_count--;
            if (manager->records[i]->ref_count == 0) {
                free_record(manager->records[i]);
                for (size_t j = i; j < manager->size - 1; ++j) {
                    manager->records[j] = manager->records[j + 1];
                }
                manager->size--;
            }
            break;
        }
    }
}

void log_event(const char* event, int key, long offset) {
    printf("%s: Key=%d, Offset=%ld\n", event, key, offset);
}
