        // Initialize additional data with a random value
        *result->components[i]->record.additional_data = rand() % 100;

        result->components[i]->record.meta_info = i + 1; // Predefined meta information

        // Allocate memory for external dependency
        result->components[i]->record.external_dependency = malloc(sizeof(void *));

        if (!result->components[i]->record.external_dependency) {
