typedef struct {
    int id;
    double value;
    char* str;
} CustomStruct;

CustomStruct** createAndInitializeArray(int rows, int cols, const char* inputString, int maxStringLength) {
    if (rows <= 0 || cols <= 0 || maxStringLength <= 0) {
        return NULL; // Invalid parameters
    }

    CustomStruct** array = (CustomStruct**)malloc(rows * sizeof(CustomStruct*));
    if (!array) {
        return NULL; // Memory allocation failed
    }

    int totalElements = rows * cols;
    double sumId = 0, sumValue = 0;

    for (int i = 0; i < rows; ++i) {
        array[i] = (CustomStruct*)malloc(cols * sizeof(CustomStruct));
        if (!array[i]) {
            // Clean up previously allocated memory
            for (int j = 0; j < i; ++j) {
                free(array[j]);
            }
            free(array);
            return NULL; // Memory allocation failed
        }

        for (int j = 0; j < cols; ++j) {
            int index = i * cols + j;
            array[i][j].id = index + 1;
            sumId += array[i][j].id;

            array[i][j].value = (double)index / totalElements;
            sumValue += array[i][j].value;

            // Allocate memory for string and copy data
            array[i][j].str = (char*)malloc((maxStringLength + 1) * sizeof(char));
            if (!array[i][j].str) {
                // Clean up previously allocated memory
                for (int k = 0; k <= i; ++k) {
                    for (int l = 0; l < cols; ++l) {
                        free(array[k][l].str);
                    }
                    free(array[k]);
                }
                free(array);
                return NULL; // Memory allocation failed
            }

            snprintf(array[i][j].str, maxStringLength + 1, "String%d", index);
        }
    }

    // Calculate averages
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            array[i][j].id /= totalElements;
            array[i][j].value /= totalElements;
        }
    }

    return array;
}

void freeArray(CustomStruct** array, int rows) {
    if (!array) {
        return;
    }

    for (int i = 0; i < rows; ++i) {
        if (array[i]) {
            for (int j = 0; j < cols; ++j) {
                free(array[i][j].str);
            }
            free(array[i]);
        }
    }
    free(array);
}

int main() {
    int rows = 3, cols = 4;
    const char* inputString = "SampleInput";
    int maxStringLength = 20;

    CustomStruct** array = createAndInitializeArray(rows, cols, inputString, maxStringLength);
    if (array) {
        // Use the array
        freeArray(array, rows);
    } else {
        printf("Memory allocation failed.\n");
    }

    return 0;
}
