// Function to find and print the largest integer in an array
void findAndPrintLargest(int* arr, int size) {
    if (size <= 0) {
        printf("Array is empty.\n");
        return;
    }
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    printf("Largest integer: %d\n", max);
}

// Function to initialize arrays and records with random numbers
int initializeArrays(int* keys, Record** records, int size, int upperBound) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        keys[i] = rand() % (upperBound + 1);
        (*records)[i].value = rand() % (upperBound + 1);
    }
    return 0;
}

// Function to free allocated memory
void freeMemory(int* keys, Record** records) {
    if (keys != NULL) {
        free(keys);
    }
    if (*records != NULL) {
        free(*records);
    }
}

int main() {
    int size = 10; // Example size
    int upperBound = 100; // Example upper bound

    int* keys = (int*)malloc(size * sizeof(int));
    Record* records = (Record*)malloc(size * sizeof(Record));

    if (keys == NULL || records == NULL) {
        printf("Memory allocation failed.\n");
        freeMemory(keys, &records);
        return 1;
    }

    initializeArrays(keys, &records, size, upperBound);

    findAndPrintLargest(keys, size);

    freeMemory(keys, &records);

    return 0;
}
