#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>
#include <zlib.h>

#define MAX_URLS 1000
#define MAX_STATUS_CODE 600
#define TIMEOUT_SECONDS 5

typedef struct node {
    char* url;
    int status_code;
    struct node* next;
} Node;

Node* head = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* fetch_url(void* arg) {
    char** urls = (char**)arg;
    for (int i = 0; i < MAX_URLS; i++) {
        if (urls[i] == NULL) break;
        CURL *curl;
        CURLcode res;
        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl = curl_easy_init();
        if(curl) {
            pthread_mutex_lock(&mutex);
            curl_easy_setopt(curl, CURLOPT_URL, urls[i]);
            curl_easy_setopt(curl, CURLOPT_TIMEOUT, TIMEOUT_SECONDS);
            res = curl_easy_perform(curl);
            if(res != CURLE_OK) {
                fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            } else {
                long http_code;
                curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
                Node* new_node = (Node*)malloc(sizeof(Node));
                new_node->url = strdup(urls[i]);
                new_node->status_code = (int)http_code;
                new_node->next = head;
                head = new_node;
            }
            curl_easy_cleanup(curl);
            pthread_mutex_unlock(&mutex);
        }
    }
    return NULL;
}

void compress_data(char* data, size_t length, char** compressed_data, size_t* compressed_length) {
    z_stream stream;
    stream.zalloc = Z_NULL;
    stream.zfree = Z_NULL;
    stream.opaque = Z_NULL;
    deflateInit(&stream, Z_DEFAULT_COMPRESSION);
    stream.avail_in = length;
    stream.next_in = (unsigned char*)data;
    *compressed_length = compressBound(length);
    *compressed_data = (char*)malloc(*compressed_length);
    stream.avail_out = *compressed_length;
    stream.next_out = (unsigned char*)(*compressed_data);
    deflate(&stream, Z_FINISH);
    deflateEnd(&stream);
}

void decompress_data(char* compressed_data, size_t compressed_length, char** data, size_t* length) {
    z_stream stream;
    stream.zalloc = Z_NULL;
    stream.zfree = Z_NULL;
    stream.opaque = Z_NULL;
    inflateInit(&stream);
    stream.avail_in = compressed_length;
    stream.next_in = (unsigned char*)compressed_data;
    *length = strlen(compressed_data) + 1;
    *data = (char*)malloc(*length);
    stream.avail_out = *length;
    stream.next_out = (unsigned char*)(*data);
    inflate(&stream, Z_FINISH);
    inflateEnd(&stream);
}

int main() {
    char* urls[MAX_URLS] = {"http://example.com", "http://example.org"};
    pthread_t threads[2];
    for (int i = 0; i < 2; i++) {
        pthread_create(&threads[i], NULL, fetch_url, (void*)urls);
    }
    for (int i = 0; i < 2; i++) {
        pthread_join(threads[i], NULL);
    }

    Node* current = head;
    while (current != NULL) {
        printf("URL: %s, Status Code: %d\n", current->url, current->status_code);
        free(current->url);
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    return 0;
}
