typedef struct UserProfile {
    int userID;
    time_t creationTimestamp;
    char email[256];
    char username[100];
    char profilePictureURL[256];
    char userStatus[50];
} UserProfile;

typedef struct UserDataset {
    UserProfile* profiles;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} UserDataset;

void initializeUserProfiles(UserDataset* dataset, size_t initialCapacity) {
    dataset->profiles = (UserProfile*)malloc(initialCapacity * sizeof(UserProfile));
    dataset->count = 0;
    dataset->capacity = initialCapacity;
    pthread_mutex_init(&dataset->lock, NULL);
}

void addUserProfile(UserDataset* dataset, UserProfile profile) {
    pthread_mutex_lock(&dataset->lock);
    if (dataset->count >= dataset->capacity) {
        dataset->capacity *= 2;
        dataset->profiles = (UserProfile*)realloc(dataset->profiles, dataset->capacity * sizeof(UserProfile));
    }
    dataset->profiles[dataset->count++] = profile;
    pthread_mutex_unlock(&dataset->lock);
}

void manageUserProfiles(UserDataset* dataset, int specialFlag) {
    if (specialFlag == 1) {
        // Free memory
        free(dataset->profiles);
        pthread_mutex_destroy(&dataset->lock);
    } else {
        // Add or update profiles
        UserProfile newProfile = { /* Initialize with appropriate values */ };
        addUserProfile(dataset, newProfile);
    }
}

int main() {
    UserDataset dataset;
    initializeUserProfiles(&dataset, 100);

    // Example usage
    manageUserProfiles(&dataset, 0); // Add a profile

    if (manageUserProfiles(&dataset, 1) == 0) { // Free memory
        printf("Memory freed successfully.\n");
    }

    return 0;
}
