#include <stdlib.h>
#include <stdio.h>

#define MAX_RECORDS 1000

typedef struct {
    long *offsets;
    int *keys;
    double *values;
} Record;

typedef struct {
    Record *records;
    int error_flag;
} AllocationResult;

AllocationResult allocate_records(int num_records) {
    AllocationResult result;
    result.records = NULL;
    result.error_flag = 0;

    if (num_records <= 0 || num_records > MAX_RECORDS) {
        result.error_flag = -1; // Invalid number of records
        return result;
    }

    // Allocate memory for the arrays in a single block
    size_t total_size = sizeof(Record) * num_records;
    char *memory_block = (char *)malloc(total_size);
    if (!memory_block) {
        result.error_flag = -2; // Memory allocation failed
        return result;
    }

    // Initialize the record array within the memory block
    result.records = (Record *)memory_block;

    for (int i = 0; i < num_records; ++i) {
        result.records[i].offsets = (long *)(memory_block + sizeof(Record) * i);
        result.records[i].keys = (int *)(result.records[i].offsets + 1);
        result.records[i].values = (double *)(result.records[i].keys + 1);
        result.records[i].values[0] = 0.0; // Initialize value to zero
    }

    return result;
}

void free_records(AllocationResult *result) {
    if (result->records) {
        free(result->records);
        result->records = NULL;
    }
}
