#define MAX_RECORDS 1000
#define MAX_MEMORY_SIZE (1 * 1024 * 1024) // 1 MB

typedef struct {
    long* offsets;
    int* keys;
    record* records;
    char* flags;
} RecordManager;

typedef struct {
    RecordManager* manager;
    int error_code;
    int last_accessed_index;
} Result;

int is_aligned(void* ptr, size_t alignment) {
    return ((uintptr_t)ptr % alignment) == 0;
}

Result create_record_manager(int num_records) {
    if (num_records <= 0 || num_records > MAX_RECORDS) {
        return (Result){NULL, -1, -1};
    }

    size_t total_size = sizeof(long*) * num_records + 
                        sizeof(int) * num_records + 
                        sizeof(record) * num_records + 
                        sizeof(char) * num_records;

    if (total_size > MAX_MEMORY_SIZE) {
        return (Result){NULL, -2, -1};
    }

    RecordManager* manager = malloc(total_size);
    if (!manager) {
        return (Result){NULL, -3, -1};
    }

    char* ptr = (char*)manager;
    manager->offsets = (long*)ptr;
    ptr += sizeof(long*) * num_records;

    manager->keys = (int*)ptr;
    ptr += sizeof(int) * num_records;

    manager->records = (record*)ptr;
    ptr += sizeof(record) * num_records;

    manager->flags = (char*)ptr;
    ptr += sizeof(char) * num_records;

    for (int i = 0; i < num_records; i++) {
        if (!is_aligned(manager->offsets[i], alignof(long))) {
            free(manager);
            return (Result){NULL, -4, -1};
        }
        manager->keys[i] = rand() % 101;
        manager->records[i].offset = &manager->offsets[i];
        manager->records[i].key = manager->keys[i];
        manager->records[i].value = ((double)rand() / RAND_MAX) * 2.0 - 1.0;
        manager->flags[i] = 0;
    }

    return (Result){manager, 0, -1};
}

void free_record_manager(RecordManager* manager) {
    if (manager) {
        free(manager);
    }
}
