#include <stdlib.h>
#include <pthread.h>
#include <endian.h>

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    size_t count;
    size_t capacity;
    size_t memory_limit;
    pthread_mutex_t lock;
} dataset;

dataset* create_dataset(size_t initial_capacity, size_t memory_limit) {
    dataset *ds = malloc(sizeof(dataset));
    ds->offsets = malloc(initial_capacity * sizeof(long));
    ds->keys = malloc(initial_capacity * sizeof(int));
    ds->records = malloc(initial_capacity * sizeof(record *));
    for (size_t i = 0; i < initial_capacity; ++i) {
        ds->records[i] = malloc(sizeof(record));
    }
    ds->count = 0;
    ds->capacity = initial_capacity;
    ds->memory_limit = memory_limit;
    pthread_mutex_init(&ds->lock, NULL);
    return ds;
}

void destroy_dataset(dataset *ds) {
    for (size_t i = 0; i < ds->count; ++i) {
        free(ds->records[i]);
    }
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

void add_record(dataset *ds, long offset, int key, int value) {
    pthread_mutex_lock(&ds->lock);
    if (ds->count >= ds->capacity) {
        // Double the capacity or handle memory limit
        size_t new_capacity = ds->capacity * 2;
        if (new_capacity > ds->memory_limit / sizeof(long)) {
            // Handle memory limit exceeded
            pthread_mutex_unlock(&ds->lock);
            return;
        }
        ds->offsets = realloc(ds->offsets, new_capacity * sizeof(long));
        ds->keys = realloc(ds->keys, new_capacity * sizeof(int));
        ds->records = realloc(ds->records, new_capacity * sizeof(record *));
        for (size_t i = ds->capacity; i < new_capacity; ++i) {
            ds->records[i] = malloc(sizeof(record));
        }
        ds->capacity = new_capacity;
    }
    ds->offsets[ds->count] = offset;
    ds->keys[ds->count] = key;
    ds->records[ds->count]->value = value;
    ++ds->count;
    pthread_mutex_unlock(&ds->lock);
}

void serialize_dataset(dataset *ds, FILE *file) {
    // Serialize dataset to binary format
    fwrite(ds->offsets, sizeof(long), ds->count, file);
    fwrite(ds->keys, sizeof(int), ds->count, file);
    for (size_t i = 0; i < ds->count; ++i) {
        fwrite(&ds->records[i]->value, sizeof(int), 1, file);
    }
}

void deserialize_dataset(dataset *ds, FILE *file) {
    // Deserialize dataset from binary format
    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    if (count > ds->capacity) {
        // Handle capacity exceeded
        return;
    }
    ds->count = count;
    for (size_t i = 0; i < count; ++i) {
        fread(&ds->offsets[i], sizeof(long), 1, file);
        fread(&ds->keys[i], sizeof(int), 1, file);
        fread(&ds->records[i]->value, sizeof(int), 1, file);
    }
}

