#include <pthread.h>

#define MAX_SETTINGS 500

typedef struct {
    void **settings;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} ConfigManager;

ConfigManager* config_manager_init(size_t initial_capacity) {
    if (initial_capacity > MAX_SETTINGS) {
        return NULL; // Error: Initial capacity exceeds maximum allowed
    }

    ConfigManager *manager = malloc(sizeof(ConfigManager));
    if (!manager) {
        return NULL; // Memory allocation failed
    }

    manager->settings = malloc(initial_capacity * sizeof(void*));
    if (!manager->settings) {
        free(manager);
        return NULL; // Memory allocation failed
    }

    manager->count = 0;
    manager->capacity = initial_capacity;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

int config_manager_add(ConfigManager *manager, void *setting) {
    if (manager->count >= manager->capacity) {
        // Double the capacity
        size_t new_capacity = manager->capacity * 2;
        if (new_capacity > MAX_SETTINGS) {
            new_capacity = MAX_SETTINGS; // Cap at maximum allowed
        }

        void **new_settings = realloc(manager->settings, new_capacity * sizeof(void*));
        if (!new_settings) {
            return -1; // Memory reallocation failed
        }

        manager->settings = new_settings;
        manager->capacity = new_capacity;
    }

    pthread_mutex_lock(&manager->lock);
    manager->settings[manager->count++] = setting;
    pthread_mutex_unlock(&manager->lock);

    return 0; // Success
}

void config_manager_free(ConfigManager *manager) {
    if (manager) {
        free(manager->settings);
        pthread_mutex_destroy(&manager->lock);
        free(manager);
    }
}
