void geographicDataManager(GeographicEntry **entries, size_t *count) {
    srand(time(NULL)); // Seed for random number generation

    // Allocate memory for entries
    *count = 5; // Example count
    *entries = (GeographicEntry *)malloc(*count * sizeof(GeographicEntry));

    // Initialize each entry with sample data and unique identifiers
    for (size_t i = 0; i < *count; ++i) {
        snprintf((*entries)[i].name, sizeof((*entries)[i].name), "Location%d", i);
        (*entries)[i].latitude = 34.0522 + i * 0.1;
        (*entries)[i].longitude = -118.2437 + i * 0.1;
        (*entries)[i].elevation = 100 + i * 10;
        generateIdentifier((*entries)[i].identifier, sizeof((*entries)[i].identifier));
    }
}

// Function to free the allocated memory for entries
