    if (!array) {
        fprintf(stderr, "Memory allocation failed for integers.\n");
        return NULL;
    }
    printf("Enter %d integers:\n", size);
    for (int i = 0; i < size; i++) {
        scanf("%d", &array[i]);
    }
    return array;
}

void find_largest(int* array, int size) {
    if (!array || size <= 0) {
        fprintf(stderr, "Invalid input for finding largest integer.\n");
        return;
    }
    int max = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > max) {
            max = array[i];
        }
    }
    printf("Largest integer: %d\n", max);
}

record* initialize_records(int size, int upper_bound) {
    record* records = (record*)malloc(size * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        return NULL;
    }
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        records[i].value = rand() % (upper_bound + 1);
    }
    return records;
}

void free_memory(int* array, record* records) {
    if (array) free(array);
    if (records) free(records);
}

int main() {
    int size, upper_bound;
    printf("Enter the number of integers and upper bound for records: ");
    scanf("%d %d", &size, &upper_bound);

    int* array = read_integers(size);
    if (!array) return 1;

    record* records = initialize_records(size, upper_bound);
    if (!records) {
        free_memory(array, NULL);
        return 1;
    }

    find_largest(array, size);
    free_memory(array, records);

    return 0;
}
