#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_SIZE 1024
#define RECORD_COUNT 5

typedef struct {
    int value;
} Record;

void* custom_malloc(size_t size) {
    // Implement a simple custom allocator here
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

void custom_free(void* ptr) {
    free(ptr);
}

int is_unique(int value, Record records[], int count) {
    for (int i = 0; i < count; i++) {
        if (records[i].value == value) {
            return 0;
        }
    }
    return 1;
}

Record* create_records(int min_value, int max_value) {
    Record* records = custom_malloc(RECORD_COUNT * sizeof(Record));
    srand(time(NULL));

    for (int i = 0; i < RECORD_COUNT; ) {
        int value = rand() % (max_value - min_value + 1) + min_value;
        if (is_unique(value, records, i)) {
            records[i].value = value;
            i++;
        }
    }

    return records;
}

void verify_uniqueness(Record records[], int count) {
    for (int i = 0; i < count - 1; i++) {
        for (int j = i + 1; j < count; j++) {
            if (records[i].value == records[j].value) {
                fprintf(stderr, "Error: Duplicate value found\n");
                exit(1);
            }
        }
    }
}

int main() {
    Record* records = create_records(10, 100);
    verify_uniqueness(records, RECORD_COUNT);

    for (int i = 0; i < RECORD_COUNT; i++) {
        printf("Record %d: Value = %d\n", i, records[i].value);
    }

    custom_free(records);
    return 0;
}
