#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    long offset;
    int key;
} record;

typedef struct {
    record* records;
    int* keys;
    int size;
    int capacity;
    pthread_mutex_t lock;
} record_collection;

record_collection* create_record_collection(int initial_capacity) {
    record_collection* collection = (record_collection*)malloc(sizeof(record_collection));
    collection->records = (record*)malloc(initial_capacity * sizeof(record));
    collection->keys = (int*)malloc(initial_capacity * sizeof(int));
    collection->size = 0;
    collection->capacity = initial_capacity;
    pthread_mutex_init(&collection->lock, NULL);
    return collection;
}

void destroy_record_collection(record_collection* collection) {
    free(collection->records);
    free(collection->keys);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_record(record_collection* collection, int key) {
    pthread_mutex_lock(&collection->lock);
    if (collection->size >= collection->capacity) {
        // Handle capacity increase
        record* new_records = (record*)realloc(collection->records, 2 * collection->capacity * sizeof(record));
        int* new_keys = (int*)realloc(collection->keys, 2 * collection->capacity * sizeof(int));
        if (!new_records || !new_keys) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Memory allocation failed
        }
        collection->records = new_records;
        collection->keys = new_keys;
        collection->capacity *= 2;
    }

    for (int i = 0; i < collection->size; ++i) {
        if (collection->keys[i] == key) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Key already exists
        }
    }

    collection->records[collection->size].offset = collection->size;
    collection->records[collection->size].key = key;
    collection->keys[collection->size++] = key;
    pthread_mutex_unlock(&collection->lock);
    return 0;
}

void print_records(record_collection* collection, void (*print_func)(record*)) {
    pthread_mutex_lock(&collection->lock);
    for (int i = 0; i < collection->size; ++i) {
        print_func(collection->records[i]);
    }
    pthread_mutex_unlock(&collection->lock);
}

void default_print_record(record record) {
    printf("Offset: %ld, Key: %d\n", record.offset, record.key);
}
```

