#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define TABLE_SIZE 100

typedef struct Record {
    int key;
    struct Record *next;
} Record;

typedef struct HashTable {
    Record **buckets;
    int capacity;
    pthread_mutex_t lock;
} HashTable;

HashTable* createHashTable(int capacity) {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    table->capacity = capacity;
    table->buckets = (Record**)calloc(capacity, sizeof(Record*));
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

unsigned int hashFunction(int key, int capacity) {
    return abs(key % capacity);
}

void insertRecord(HashTable *table, int key) {
    pthread_mutex_lock(&table->lock);
    unsigned int index = hashFunction(key, table->capacity);
    Record *newRecord = (Record*)malloc(sizeof(Record));
    newRecord->key = key;
    newRecord->next = table->buckets[index];
    table->buckets[index] = newRecord;
    pthread_mutex_unlock(&table->lock);
}

int lookupRecord(HashTable *table, int key) {
    pthread_mutex_lock(&table->lock);
    unsigned int index = hashFunction(key, table->capacity);
    Record *current = table->buckets[index];
    while (current != NULL) {
        if (current->key == key) {
            pthread_mutex_unlock(&table->lock);
            return 1;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&table->lock);
    return 0;
}

void deleteRecord(HashTable *table, int key) {
    pthread_mutex_lock(&table->lock);
    unsigned int index = hashFunction(key, table->capacity);
    Record *current = table->buckets[index];
    Record *prev = NULL;
    while (current != NULL) {
        if (current->key == key) {
            if (prev == NULL) {
                table->buckets[index] = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&table->lock);
            return;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&table->lock);
}

void destroyHashTable(HashTable *table) {
    for (int i = 0; i < table->capacity; i++) {
        Record *current = table->buckets[i];
        while (current != NULL) {
            Record *temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}
