typedef struct {
    Record records[MAX_RECORDS];
    int count;
} DataCollection;

DataCollection* create_data_collection() {
    DataCollection* collection = (DataCollection*)malloc(sizeof(DataCollection));
    if (collection == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    collection->count = 0;
    return collection;
}

void destroy_data_collection(DataCollection* collection) {
    free(collection);
}

int add_record(DataCollection* collection, int key, long offset, double value) {
    if (collection->count >= MAX_RECORDS) {
        fprintf(stderr, "Data collection is full\n");
        return -1;
    }
    Record new_record = {key, offset, value};
    collection->records[collection->count++] = new_record;
    return 0;
}

int find_record(DataCollection* collection, int key) {
    for (int i = 0; i < collection->count; i++) {
        if (collection->records[i].key == key) {
            return i;
        }
    }
    return -1;
}

void update_record(DataCollection* collection, int key, long offset, double value) {
    int index = find_record(collection, key);
    if (index != -1) {
        collection->records[index].offset = offset;
        collection->records[index].value = value;
    }
}

double get_value(DataCollection* collection, int key) {
    int index = find_record(collection, key);
    if (index != -1) {
        return collection->records[index].value;
    }
    return NAN; // Not a Number
}

int main() {
    DataCollection* collection = create_data_collection();

    add_record(collection, 1, 10L, 3.14);
    add_record(collection, 2, 20L, 2.71);

    printf("Value for key 1: %f\n", get_value(collection, 1));
    printf("Value for key 2: %f\n", get_value(collection, 2));

    update_record(collection, 1, 30L, 6.28);
    printf("Updated value for key 1: %f\n", get_value(collection, 1));

    destroy_data_collection(collection);
    return 0;
}
