#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct record {
    int value;
    struct record *next;
} Record;

typedef struct {
    long *offsets;
    int *keys;
    Record **records;
    pthread_mutex_t lock;
    FILE *file;
} DataStore;

DataStore* create_data_store(int size, int key_range) {
    DataStore *ds = (DataStore*)malloc(sizeof(DataStore));
    if (!ds) {
        perror("Failed to allocate memory for DataStore");
        exit(EXIT_FAILURE);
    }

    ds->offsets = (long*)malloc(size * sizeof(long));
    ds->keys = (int*)malloc(size * sizeof(int));
    ds->records = (Record**)malloc(size * sizeof(Record*));
    if (!ds->offsets || !ds->keys || !ds->records) {
        perror("Failed to allocate memory for arrays");
        free(ds);
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&ds->lock, NULL);

    ds->file = fopen("data_store.dat", "w+b");
    if (!ds->file) {
        perror("Failed to open file for data storage");
        free(ds->offsets);
        free(ds->keys);
        free(ds->records);
        pthread_mutex_destroy(&ds->lock);
        free(ds);
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    for (int i = 0; i < size; ++i) {
        ds->offsets[i] = ftell(ds->file);
        ds->keys[i] = rand() % key_range;
        Record *rec = (Record*)malloc(sizeof(Record));
        if (!rec) {
            perror("Failed to allocate memory for record");
            free(ds->offsets);
            free(ds->keys);
            for (int j = 0; j < i; ++j)
                free(ds->records[j]);
            pthread_mutex_destroy(&ds->lock);
            fclose(ds->file);
            free(ds);
            exit(EXIT_FAILURE);
        }
        rec->value = rand() % key_range;
        rec->next = NULL;
        ds->records[i] = rec;

        fwrite(&rec->value, sizeof(int), 1, ds->file);
    }

    return ds;
}

void destroy_data_store(DataStore *ds) {
    for (int i = 0; i < size; ++i)
        free(ds->records[i]);
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    pthread_mutex_destroy(&ds->lock);
    fclose(ds->file);
    free(ds);
}

void insert_record(DataStore *ds, int key, int value) {
    pthread_mutex_lock(&ds->lock);

    Record *new_rec = (Record*)malloc(sizeof(Record));
    if (!new_rec) {
        perror("Failed to allocate memory for new record");
        pthread_mutex_unlock(&ds->lock);
        return;
    }
    new_rec->value = value;
    new_rec->next = NULL;

    int index = find_index(ds, key);
    Record *prev = ds->records[index];
    if (prev) {
        while (prev->next)
            prev = prev->next;
        prev->next = new_rec;
    } else
        ds->records[index] = new_rec;

    pthread_mutex_unlock(&ds->lock);
}

void delete_record(DataStore *ds, int key) {
    pthread_mutex_lock(&ds->lock);

    int index = find_index(ds, key);
    Record *prev = NULL;
    Record *curr = ds->records[index];
    while (curr && curr->value != key) {
        prev = curr;
        curr = curr->next;
    }
    if (curr) {
        if (prev)
            prev->next = curr->next;
        else
            ds->records[index] = curr->next;
        free(curr);
    }

    pthread_mutex_unlock(&ds->lock);
}

