#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 16
#define LOAD_FACTOR_THRESHOLD 0.75

typedef struct Record {
    int key;
    struct Record *next;
} Record;

typedef struct HashTable {
    Record **buckets;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

unsigned long hash_function(int key, size_t capacity) {
    return (unsigned long)key % capacity;
}

HashTable* create_hash_table(size_t initial_capacity) {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    table->buckets = (Record**)calloc(initial_capacity, sizeof(Record*));
    table->capacity = initial_capacity;
    table->size = 0;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void insert_record(HashTable *table, int key) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(key, table->capacity);
    Record *new_record = (Record*)malloc(sizeof(Record));
    new_record->key = key;
    new_record->next = table->buckets[index];
    table->buckets[index] = new_record;
    table->size++;
    if ((double)table->size / table->capacity > LOAD_FACTOR_THRESHOLD) {
        // Resize the hash table
        size_t new_capacity = table->capacity * 2;
        Record **new_buckets = (Record**)calloc(new_capacity, sizeof(Record*));
        for (size_t i = 0; i < table->capacity; i++) {
            Record *current = table->buckets[i];
            while (current != NULL) {
                size_t new_index = hash_function(current->key, new_capacity);
                Record *next = current->next;
                current->next = new_buckets[new_index];
                new_buckets[new_index] = current;
                current = next;
            }
        }
        free(table->buckets);
        table->buckets = new_buckets;
        table->capacity = new_capacity;
    }
    pthread_mutex_unlock(&table->lock);
}

Record* lookup_record(HashTable *table, int key) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(key, table->capacity);
    Record *current = table->buckets[index];
    while (current != NULL) {
        if (current->key == key) {
            pthread_mutex_unlock(&table->lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void delete_record(HashTable *table, int key) {
    pthread_mutex_lock(&table->lock);
    size_t index = hash_function(key, table->capacity);
    Record *current = table->buckets[index];
    Record *prev = NULL;
    while (current != NULL) {
        if (current->key == key) {
            if (prev == NULL) {
                table->buckets[index] = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            table->size--;
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&table->lock);
}

void destroy_hash_table(HashTable *table) {
    for (size_t i = 0; i < table->capacity; i++) {
        Record *current = table->buckets[i];
        while (current != NULL) {
            Record *next = current->next;
            free(current);
            current = next;
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}
