DocumentList* create_document_list(size_t initial_capacity, size_t max_size) {
    DocumentList *list = (DocumentList*)malloc(sizeof(DocumentList));
    list->docs = (Document*)calloc(initial_capacity, sizeof(Document));
    list->count = 0;
    list->capacity = initial_capacity;
    list->max_size = max_size;
    return list;
}

void destroy_document_list(DocumentList *list) {
    free(list->docs);
    free(list);
}

void add_document(DocumentList *list, const char *title, const char *content, time_t timestamp) {
    if (list->count >= list->capacity && list->count < list->max_size) {
        list->capacity *= 2;
        list->docs = realloc(list->docs, list->capacity * sizeof(Document));
    }
    strcpy(list->docs[list->count].title, title);
    strncpy(list->docs[list->count].content, content, MAX_CONTENT_LENGTH - 1);
    list->docs[list->count].timestamp = timestamp;
    list->count++;
}

