#define MAX_LOG_ENTRIES 1000000
#define MAX_MESSAGE_LENGTH 256

typedef enum {
    DEBUG,
    INFO,
    WARN,
    ERROR
} Severity;

typedef struct logEntry {
    time_t timestamp;
    Severity severity;
    char message[MAX_MESSAGE_LENGTH];
} logEntry;

typedef struct logManager {
    logEntry *entries;
    size_t count;
    size_t capacity;
    size_t maxMemoryBudget;
    void (*logServiceAPI)(const logEntry *, size_t);
} logManager;

void initLogManager(logManager *manager, size_t initialCapacity, size_t maxMemoryBudget, void (*api)(const logEntry *, size_t)) {
    manager->entries = (logEntry *)malloc(initialCapacity * sizeof(logEntry));
    if (!manager->entries) {
        fprintf(stderr, "Failed to allocate memory for log entries.\n");
        exit(EXIT_FAILURE);
    }
    manager->count = 0;
    manager->capacity = initialCapacity;
    manager->maxMemoryBudget = maxMemoryBudget;
    manager->logServiceAPI = api;
}

void freeLogManager(logManager *manager) {
    free(manager->entries);
}

void addLogEntry(logManager *manager, time_t timestamp, Severity severity, const char *message) {
    if (manager->count >= manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        logEntry *newEntries = (logEntry *)realloc(manager->entries, newCapacity * sizeof(logEntry));
        if (!newEntries) {
            fprintf(stderr, "Failed to reallocate memory for log entries.\n");
            exit(EXIT_FAILURE);
        }
        manager->entries = newEntries;
        manager->capacity = newCapacity;
    }

    manager->entries[manager->count].timestamp = timestamp;
    manager->entries[manager->count].severity = severity;
    strncpy(manager->entries[manager->count].message, message, MAX_MESSAGE_LENGTH - 1);
    manager->entries[manager->count].message[MAX_MESSAGE_LENGTH - 1] = '\0';
    manager->count++;
}

void transmitLogs(logManager *manager) {
    if (manager->count > 0) {
        manager->logServiceAPI(manager->entries, manager->count);
        manager->count = 0;
    }
}
