    *offsets = (long*)malloc(size * sizeof(long));
    *keys = (int*)malloc(size * sizeof(int));
    *records = (record*)malloc(size * sizeof(record));
    *metadata = (char**)malloc(size * sizeof(char*));

    if (*offsets == NULL || *keys == NULL || *records == NULL || *metadata == NULL) {
        free(*offsets);
        free(*keys);
        free(*records);
        free(*metadata);
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        (*offsets)[i] = rand();
        (*keys)[i] = rand() % 1000;
        (*records)[i].value = rand() % 10000;
        (*records)[i].timestamp = time(NULL);
        (*metadata)[i] = (char*)malloc(256 * sizeof(char));
        snprintf((*metadata)[i], 256, "Default metadata for record %d", i);
    }

    return NULL; // Return success
}

void free_memory(long* offsets, int* keys, record* records, char** metadata, int size) {
    for (int i = 0; i < size; i++) {
        free(metadata[i]);
    }
    free(offsets);
    free(keys);
    free(records);
    free(metadata);
}

int main(int argc, char* argv[]) {
    int size = 100;
    long* offsets;
    int* keys;
    record* records;
    char** metadata;

    if (allocate_and_initialize(size, &offsets, &keys, &records, &metadata) != NULL) {
        printf("Memory allocation failed\n");
        return 1;
    }

    // Use the allocated memory for database operations

    free_memory(offsets, keys, records, metadata, size);

    return 0;
}
