#define MAX_DESCRIPTION_LENGTH 256

typedef struct Task {
    int priority;
    char status[10];
    char description[MAX_DESCRIPTION_LENGTH];
    struct Task* next;
} Task;

Task* create_task_list(int num_tasks) {
    if (num_tasks <= 0) {
        return NULL;
    }

    Task* head = NULL;
    Task* current = NULL;

    for (int i = 1; i <= num_tasks; i++) {
        Task* new_task = (Task*)malloc(sizeof(Task));
        if (!new_task) {
            // Handle memory allocation failure
            fprintf(stderr, "Memory allocation failed\n");
            free_list(head);
            return NULL;
        }

        new_task->priority = i;
        strcpy(new_task->status, "Pending");

        // Generate a random description
        for (int j = 0; j < MAX_DESCRIPTION_LENGTH - 1; j++) {
            new_task->description[j] = 'a' + rand() % 26;
        }
        new_task->description[MAX_DESCRIPTION_LENGTH - 1] = '\0';

        new_task->next = NULL;

        if (head == NULL) {
            head = new_task;
        } else {
            current->next = new_task;
        }

        current = new_task;
    }

    return head;
}

void free_list(Task* head) {
    Task* current = head;
    while (current != NULL) {
        Task* next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    int num_tasks = 5;
    Task* task_list = create_task_list(num_tasks);

    if (task_list != NULL) {
        // Process the task list
        Task* current = task_list;
        while (current != NULL) {
            printf("Task %d: Priority=%d, Status=%s, Description=%s\n",
                   current->priority, current->priority, current->status, current->description);
            current = current->next;
        }

        // Free the allocated memory
        free_list(task_list);
    } else {
        printf("Failed to create task list\n");
    }

    return 0;
}
