typedef struct {
    int value;
    time_t timestamp;
} record;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int allocate_memory(size_t size, long **offsets, int **keys, record **records, char ***metadata) {
    *offsets = (long *)malloc(size * sizeof(long));
    *keys = (int *)malloc(size * sizeof(int));
    *records = (record *)malloc(size * sizeof(record));
    *metadata = (char **)malloc(size * sizeof(char *));

    if (!*offsets || !*keys || !*records || !*metadata) {
        log_error("Memory allocation failed");
        free(*offsets);
        free(*keys);
        free(*records);
        free(*metadata);
        return 0;
    }

    for (size_t i = 0; i < size; ++i) {
        (*metadata)[i] = (char *)malloc(256 * sizeof(char));
        if (!(*metadata)[i]) {
            log_error("Memory allocation failed");
            for (size_t j = 0; j < i; ++j) {
                free((*metadata)[j]);
            }
            free(*offsets);
            free(*keys);
            free(*records);
            free(*metadata);
            return 0;
        }
    }

    return 1;
}

void initialize_data(size_t size, long *offsets, int *keys, record *records, char **metadata) {
    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        offsets[i] = rand();
        keys[i] = rand() % 1000;
        records[i].value = rand() % 1000;
        records[i].timestamp = time(NULL);
        snprintf(metadata[i], 256, "Record created at %s", ctime(&records[i].timestamp));
    }
}

void free_memory(size_t size, long *offsets, int *keys, record *records, char **metadata) {
    for (size_t i = 0; i < size; ++i) {
        free(metadata[i]);
    }
    free(offsets);
    free(keys);
    free(records);
    free(metadata);
}

int main() {
    size_t size;
    printf("Enter the number of elements: ");
    scanf("%zu", &size);

    long *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;
    char **metadata = NULL;

    if (!allocate_memory(size, &offsets, &keys, &records, &metadata)) {
        return 1;
    }

    initialize_data(size, offsets, keys, records, metadata);

    // Example usage of the data structures
    for (size_t i = 0; i < size; ++i) {
        printf("Offset: %ld, Key: %d, Value: %d, Timestamp: %s\n", offsets[i], keys[i], records[i].value, ctime(&records[i].timestamp));
    }

    free_memory(size, offsets, keys, records, metadata);

    return 0;
}
