    for (int i = 0; i < 500; i++) {
        session_records[i].user_id = rand() % 100;
        session_records[i].login_time = time(NULL) - rand() % 3600 * 24;
        session_records[i].logout_time = session_records[i].login_time + rand() % 3600 * 24;
    }

    // Calculate total active session duration for each user
    int *user_durations = (int *)calloc(100, sizeof(int));
    for (int i = 0; i < 500; i++) {
        if (session_records[i].logout_time > session_records[i].login_time) {
            user_durations[session_records[i].user_id] += difftime(session_records[i].logout_time, session_records[i].login_time);
        }
    }

