    for (size_t i = 0; i < size; ++i) {
        timestamps[i] = rand() % upper_bound;
        temperatures[i] = ((float)rand() / RAND_MAX) * 100.0f;

        sensors[i].measurement = ((double)rand() / RAND_MAX) * 1000.0;
        sensors[i].type = 'A' + (i % 26);

        events[i] = i % 5;
    }

    FILE *log_file = fopen("sensor_data.log", "w");
    if (!log_file) {
        free(timestamps);
        free(temperatures);
        free(sensors);
        free(events);
        return FAILURE;
    }

    for (size_t i = 0; i < size; ++i) {
        fprintf(log_file, "Timestamp: %ld, Temperature: %.2f, Sensor Type: %c, Event ID: %d\n",
                timestamps[i], temperatures[i], sensors[i].type, events[i]);
    }

    fclose(log_file);

    free(timestamps);
    free(temperatures);
    free(sensors);
    free(events);

    return SUCCESS;
}
