} record;

typedef struct {
    record *records;
    int count;
    pthread_mutex_t lock;
} dynamic_array;

void init_dynamic_array(dynamic_array *da) {
    da->records = (record *)malloc(MAX_RECORDS * sizeof(record));
    if (!da->records) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    da->count = 0;
    pthread_mutex_init(&da->lock, NULL);
}

void destroy_dynamic_array(dynamic_array *da) {
    free(da->records);
    pthread_mutex_destroy(&da->lock);
}

int add_record(dynamic_array *da, int key) {
    pthread_mutex_lock(&da->lock);
    if (da->count >= MAX_RECORDS) {
        pthread_mutex_unlock(&da->lock);
        return -1; // Array is full
    }
    da->records[da->count].offset = rand();
    da->records[da->count].key = key;
    da->records[da->count].value = rand() % (VALUE_RANGE_MAX - VALUE_RANGE_MIN + 1) + VALUE_RANGE_MIN;
    da->count++;
    pthread_mutex_unlock(&da->lock);
    return 0;
}

record *get_record(dynamic_array *da, int key) {
    pthread_mutex_lock(&da->lock);
    for (int i = 0; i < da->count; i++) {
        if (da->records[i].key == key) {
            pthread_mutex_unlock(&da->lock);
            return &da->records[i];
        }
    }
    pthread_mutex_unlock(&da->lock);
    return NULL;
}

void reset_dynamic_array(dynamic_array *da) {
    pthread_mutex_lock(&da->lock);
    for (int i = 0; i < da->count; i++) {
        da->records[i].value = rand() % (VALUE_RANGE_MAX - VALUE_RANGE_MIN + 1) + VALUE_RANGE_MIN;
    }
    pthread_mutex_unlock(&da->lock);
}

void update_records_from_source(dynamic_array *da, void (*update_function)(record *)) {
    pthread_mutex_lock(&da->lock);
    for (int i = 0; i < da->count; i++) {
        update_function(&da->records[i]);
    }
    pthread_mutex_unlock(&da->lock);
}

void example_update_function(record *r) {
    r->value += rand() % 10 - 5; // Randomly adjust the value
}
