#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define INITIAL_CAPACITY 100
#define GROWTH_FACTOR 2

typedef struct {
    int value;
} Record;

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

Record* create_records(int initial_capacity) {
    Record* records = (Record*)safe_malloc(initial_capacity * sizeof(Record));
    for (int i = 0; i < initial_capacity; i++) {
        records[i].value = rand() % 1000; // Initialize with random values
    }
    return records;
}

void update_record(Record* records, int key, int new_value) {
    if (key >= 0 && key < INITIAL_CAPACITY) {
        records[key].value = new_value;
    } else {
        fprintf(stderr, "Invalid key\n");
    }
}

int lookup_record(const Record* records, int key) {
    if (key >= 0 && key < INITIAL_CAPACITY) {
        return records[key].value;
    } else {
        fprintf(stderr, "Invalid key\n");
        return -1; // Return an error value
    }
}

void free_records(Record* records) {
    free(records);
}

int main() {
    srand(time(NULL));

    Record* records = create_records(INITIAL_CAPACITY);

    update_record(records, 50, 999);
    printf("Updated record at key 50: %d\n", lookup_record(records, 50));

    free_records(records);

    return 0;
}
