#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 10000
#define RESIZE_THRESHOLD 0.8
#define GARBAGE_COLLECTION_INTERVAL 60

typedef struct {
    long offset;
    int key;
    int value;
} record;

record* offsets = NULL;
int* keys = NULL;
record** records = NULL;
int size = 0;
int capacity = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void init_memory() {
    srand(time(NULL));
    capacity = MAX_RECORDS;
    offsets = (long*)malloc(capacity * sizeof(long));
    keys = (int*)malloc(capacity * sizeof(int));
    records = (record**)malloc(capacity * sizeof(record*));
}

void resize_memory() {
    pthread_mutex_lock(&mutex);
    if ((double)size / capacity >= RESIZE_THRESHOLD) {
        int new_capacity = capacity * 2;
        offsets = (long*)realloc(offsets, new_capacity * sizeof(long));
        keys = (int*)realloc(keys, new_capacity * sizeof(int));
        records = (record**)realloc(records, new_capacity * sizeof(record*));
        if (!offsets || !keys || !records) {
            // Handle memory allocation failure
        }
        capacity = new_capacity;
    }
    pthread_mutex_unlock(&mutex);
}

void add_record(long offset, int key) {
    pthread_mutex_lock(&mutex);
    if (size >= capacity) {
        resize_memory();
    }
    offsets[size] = offset;
    keys[size] = key;
    records[size] = (record*)malloc(sizeof(record));
    records[size]->offset = offset;
    records[size]->key = key;
    records[size]->value = rand() % 100; // Random value between 0 and 99
    size++;
    pthread_mutex_unlock(&mutex);
}

void clear_memory() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < size; i++) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);
    offsets = NULL;
    keys = NULL;
    records = NULL;
    size = 0;
    capacity = 0;
    pthread_mutex_unlock(&mutex);
}

void* garbage_collection(void* arg) {
    while (1) {
        sleep(GARBAGE_COLLECTION_INTERVAL);
        pthread_mutex_lock(&mutex);
        for (int i = 0; i < size; i++) {
            // Check if record has not been accessed for a specified period
            if (/* condition */) {
                free(records[i]);
                records[i] = NULL;
                size--;
                i--; // Adjust index after removal
            }
        }
        pthread_mutex_unlock(&mutex);
    }
}

int main() {
    init_memory();
    pthread_t gc_thread;
    pthread_create(&gc_thread, NULL, garbage_collection, NULL);

    // Simulate adding records
    for (int i = 0; i < MAX_RECORDS * 2; i++) {
        add_record(i, i);
    }

    clear_memory();
    pthread_join(gc_thread, NULL);
    return 0;
}
