#include <pthread.h>

#define MAX_RECORDS 10000000

typedef struct {
    int value;
    int* key;
    long offset;
} record;

void* allocate_and_initialize_records(int num_records, int key_range_start, int key_range_end) {
    if (num_records > MAX_RECORDS) {
        fprintf(stderr, "Error: Requested number of records exceeds maximum limit.\n");
        return NULL;
    }

    // Allocate memory for long offsets array
    long* offsets = aligned_alloc(64, num_records * sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        return NULL;
    }

    // Allocate memory for int keys array
    int* keys = aligned_alloc(64, num_records * sizeof(int));
    if (!keys) {
        perror("Failed to allocate memory for keys");
        free(offsets);
        return NULL;
    }

    // Initialize records
    record* records = malloc(num_records * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        free(keys);
        free(offsets);
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < num_records; i++) {
        pthread_mutex_lock(&mutex);
        records[i].value = rand() % (key_range_end - key_range_start + 1) + key_range_start;
        records[i].key = &keys[i];
        records[i].offset = offsets[i];
        pthread_mutex_unlock(&mutex);
    }

    // Initialize keys and offsets
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % (key_range_end - key_range_start + 1) + key_range_start;
        offsets[i] = i * sizeof(record);
    }

    pthread_mutex_destroy(&mutex);

    return records;
}

int main() {
    srand(time(NULL));
    int num_records = 5000000; // Example number of records
    int key_range_start = 1;
    int key_range_end = 100;

    record* records = allocate_and_initialize_records(num_records, key_range_start, key_range_end);

    if (records) {
        printf("Records initialized successfully.\n");
        free(records);
    }

    return 0;
}
