#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INITIAL_CAPACITY 16
#define LOAD_FACTOR_THRESHOLD 0.75

typedef struct KeyValue {
    char *key;
    int value;
    struct KeyValue *next;
} KeyValue;

typedef struct HashTable {
    KeyValue **buckets;
    size_t capacity;
    size_t size;
} HashTable;

unsigned long hash(const char *key, size_t capacity) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash % capacity;
}

HashTable* createHashTable(size_t initialCapacity) {
    HashTable *table = (HashTable*)malloc(sizeof(HashTable));
    if (!table) {
        fprintf(stderr, "Memory allocation failed for hash table\n");
        return NULL;
    }

    table->buckets = (KeyValue**)calloc(initialCapacity, sizeof(KeyValue*));
    if (!table->buckets) {
        free(table);
        fprintf(stderr, "Memory allocation failed for buckets\n");
        return NULL;
    }

    table->capacity = initialCapacity;
    table->size = 0;

    return table;
}

void destroyHashTable(HashTable *table) {
    for (size_t i = 0; i < table->capacity; ++i) {
        KeyValue *current = table->buckets[i];
        while (current) {
            KeyValue *next = current->next;
            free(current->key);
            free(current);
            current = next;
        }
    }

    free(table->buckets);
    free(table);
}

int insert(HashTable *table, const char *key, int value) {
    if ((double)table->size / table->capacity >= LOAD_FACTOR_THRESHOLD) {
        // Resize the hash table
        size_t newCapacity = table->capacity * 2;
        KeyValue **newBuckets = (KeyValue**)calloc(newCapacity, sizeof(KeyValue*));
        if (!newBuckets) {
            fprintf(stderr, "Memory allocation failed for new buckets\n");
            return -1;
        }

        for (size_t i = 0; i < table->capacity; ++i) {
            KeyValue *current = table->buckets[i];
            while (current) {
                size_t newIndex = hash(current->key, newCapacity);
                KeyValue *next = current->next;
                current->next = newBuckets[newIndex];
                newBuckets[newIndex] = current;
                current = next;
            }
        }

        free(table->buckets);
        table->buckets = newBuckets;
        table->capacity = newCapacity;
    }

    size_t index = hash(key, table->capacity);
    KeyValue *newNode = (KeyValue*)malloc(sizeof(KeyValue));
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed for new key-value pair\n");
        return -1;
    }

    newNode->key = strdup(key);
    newNode->value = value;
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;
    ++table->size;

    return 0;
}

int lookup(HashTable *table, const char *key) {
    size_t index = hash(key, table->capacity);
    KeyValue *current = table->buckets[index];
    while (current) {
        if (strcmp(current->key, key) == 0) {
            return current->value;
        }
        current = current->next;
    }

    return -1; // Key not found
}

int main() {
    HashTable *table = createHashTable(INITIAL_CAPACITY);
    if (!table) {
        fprintf(stderr, "Failed to create hash table\n");
        return 1;
    }

    insert(table, "key1", 42);
    insert(table, "key2", 99);

    int value = lookup(table, "key1");
    printf("Value for key1: %d\n", value);

    destroyHashTable(table);
    return 0;
}
```

This code provides a basic implementation of a hash table with dynamic resizing and memory management. It includes functions to create, insert into, and look up values in the hash table. The `hash` function is used to compute the index for each key based on its hash value. The `insert` function handles resizing when the load factor exceeds a threshold. The `lookup` function searches for a key and returns its associated value.

Please note that this code does not include external data storage integration, performance optimization techniques, logging mechanisms, or handling of network failures. These aspects would require additional implementation based on specific requirements and constraints.']

