typedef struct {
    int value;
    char name[RECORD_NAME_LENGTH];
} record;

typedef struct {
    long* offsets;
    int* keys;
    record* records;
    NFAPI_CRC_INDICATION_PDU_T* rf_data;
    size_t offset_size;
    size_t key_size;
    size_t record_size;
    size_t rf_data_size;
    pthread_mutex_t mutex;
} dynamic_system;

int initialize_dynamic_system(dynamic_system* system, size_t offset_size, size_t key_size, size_t record_size, size_t rf_data_size) {
    if (offset_size > MAX_OFFSETS || key_size > MAX_KEYS || record_size * RECORD_NAME_LENGTH > MAX_RECORD_SIZE || rf_data_size > NFAPI_CRC_INDICATION_PDU_T_SIZE) {
        return -1; // Error: Exceeds upper bounds
    }

    system->offset_size = offset_size;
    system->key_size = key_size;
    system->record_size = record_size;
    system->rf_data_size = rf_data_size;

    pthread_mutex_init(&system->mutex, NULL);

    system->offsets = (long*)malloc(offset_size * sizeof(long));
    if (!system->offsets) {
        goto cleanup;
    }

    system->keys = (int*)malloc(key_size * sizeof(int));
    if (!system->keys) {
        goto cleanup;
    }

    system->records = (record*)malloc(record_size * sizeof(record));
    if (!system->records) {
        goto cleanup;
    }

    system->rf_data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(rf_data_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!system->rf_data) {
        goto cleanup;
    }

    return 0; // Success

cleanup:
    free(system->offsets);
    free(system->keys);
    free(system->records);
    free(system->rf_data);
    pthread_mutex_destroy(&system->mutex);
    return -1; // Failure
}

void destroy_dynamic_system(dynamic_system* system) {
    free(system->offsets);
    free(system->keys);
    free(system->records);
    free(system->rf_data);
    pthread_mutex_destroy(&system->mutex);
}
