    }

    // Allocate memory for log entries
    log_entry *logs = (log_entry *)malloc(num_entries * sizeof(log_entry));
    if (!logs) {
        log_error("Failed to allocate memory for log entries", verbosity);
        free(metadata); // Clean up partially allocated resources
        return -1;
    }

    // Initialize log entries
    time_t current_time;
    for (int i = 0; i < num_entries; i++) {
        time(&current_time);
        logs[i].timestamp = current_time;
        snprintf(logs[i].message, sizeof(logs[i].message), "Log entry %d", i);
