typedef enum {
    LOW,
    MEDIUM,
    HIGH
} Priority;

typedef struct {
    double value;
    Priority type;
} Measurement;

typedef struct {
    float* float_values;
    char** identifiers;
    Measurement* measurements;
    Priority* priorities;
    int* processing_flags;
    size_t size;
} DataStruct;

DataStruct* create_data_struct(size_t initial_size) {
    DataStruct* data = (DataStruct*)malloc(sizeof(DataStruct));
    if (!data) return NULL;

    data->float_values = (float*)calloc(initial_size, sizeof(float));
    data->identifiers = (char**)calloc(initial_size, sizeof(char*));
    data->measurements = (Measurement*)calloc(initial_size, sizeof(Measurement));
    data->priorities = (Priority*)calloc(initial_size, sizeof(Priority));
    data->processing_flags = (int*)calloc(initial_size, sizeof(int));

    if (!data->float_values || !data->identifiers || !data->measurements || !data->priorities || !data->processing_flags) {
        free(data->float_values);
        free(data->identifiers);
        free(data->measurements);
        free(data->priorities);
        free(data->processing_flags);
        free(data);
        return NULL;
    }

    data->size = initial_size;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    if (pthread_mutex_init(&data->mutex, &mutex) != 0) {
        free(data->float_values);
        free(data->identifiers);
        free(data->measurements);
        free(data->priorities);
        free(data->processing_flags);
        free(data);
        return NULL;
    }

    return data;
}

void destroy_data_struct(DataStruct* data) {
    if (!data) return;

    pthread_mutex_destroy(&data->mutex);

    for (size_t i = 0; i < data->size; ++i) {
        free(data->identifiers[i]);
    }
    free(data->float_values);
    free(data->identifiers);
    free(data->measurements);
    free(data->priorities);
    free(data->processing_flags);

    free(data);
}

int initialize_data_struct(DataStruct* data, size_t size, double value_range_start, double value_range_end) {
    if (!data || size == 0) return -1;

    pthread_mutex_lock(&data->mutex);

    if (size > data->size) {
        DataStruct* new_data = create_data_struct(size);
        if (!new_data) {
            pthread_mutex_unlock(&data->mutex);
            return -1;
        }

        free(data->float_values);
        free(data->identifiers);
        free(data->measurements);
        free(data->priorities);
        free(data->processing_flags);

        *data = *new_data;
    }

    data->size = size;

    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        data->float_values[i] = value_range_start + (rand() / (RAND_MAX / (value_range_end - value_range_start)));
        data->identifiers[i] = (char*)malloc(10 * sizeof(char));
        snprintf(data->identifiers[i], 10, "ID%d", i);
        data->measurements[i].value = data->float_values[i];
        data->measurements[i].type = (Priority)(rand() % 3);
        data->priorities[i] = (Priority)(rand() % 3);
        data->processing_flags[i] = 0;
    }

    pthread_mutex_unlock(&data->mutex);

    return 0;
}
