#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

int initialize_data(int* keys, record** records, int size, int upper_bound) {
    if (size > MAX_SIZE || upper_bound > MAX_UPPER_BOUND) {
        return -1; // Error: Size or upper bound exceeds limits
    }

    *records = (record*)malloc(size * sizeof(record));
    if (*records == NULL) {
        return -2; // Error: Memory allocation failed
    }

    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        keys[i] = i;
        (*records)[i].value = rand() % upper_bound;
    }

    return 0; // Success
}

void find_largest(int* keys, record* records, int size) {
    int largest = records[keys[0]].value;
    for (int i = 1; i < size; i++) {
        if (records[keys[i]].value > largest) {
            largest = records[keys[i]].value;
        }
    }
    printf("Largest value: %d\n", largest);
}

void serialize_data(record* records, int size, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Error opening file for writing");
        return;
    }

    fwrite(records, sizeof(record), size, file);
    fclose(file);
}

void deserialize_data(record** records, int* size, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Error opening file for reading");
        return;
    }

    fseek(file, 0, SEEK_END);
    *size = ftell(file) / sizeof(record);
    fseek(file, 0, SEEK_SET);

    *records = (record*)malloc(*size * sizeof(record));
    if (*records == NULL) {
        perror("Error allocating memory for records");
        fclose(file);
        return;
    }

    fread(*records, sizeof(record), *size, file);
    fclose(file);
}

int main() {
    int keys[100];
    record* records;
    int size = 50;
    int upper_bound = 100;

    if (initialize_data(keys, &records, size, upper_bound) != 0) {
        printf("Failed to initialize data\n");
        return 1;
    }

    find_largest(keys, records, size);

    serialize_data(records, size, "data.bin");

    record* deserialized_records;
    int deserialized_size;
    deserialize_data(&deserialized_records, &deserialized_size, "data.bin");

    free(records);
    free(deserialized_records);

    return 0;
}
