    int errorCode;
} LogEntry;

IntKeyRecord* createIntKeyRecords(int size, int upperBound) {
    IntKeyRecord *records = (IntKeyRecord*)malloc(size * sizeof(IntKeyRecord));
    if (!records) return NULL;

    for (int i = 0; i < size; i++) {
        records[i].key = i;
        records[i].record = (Record*)malloc(sizeof(Record));
        if (!records[i].record) {
            // Clean up previously allocated resources
            for (int j = 0; j < i; j++) free(records[j].record);
            free(records);
            return NULL;
        }
        records[i].record->value = rand() % upperBound + 1;
        records[i].record->timestamp = time(NULL);
    }

    return records;
}

void freeIntKeyRecords(IntKeyRecord *records, int size) {
    for (int i = 0; i < size; i++) free(records[i].record);
    free(records);
}

int findLargestInteger(int *array, int size) {
    if (size <= 0) return -1;
    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) largest = array[i];
    }
    return largest;
}

void logMemoryAllocation(LogEntry *log, int size, int success, int errorCode) {
    for (int i = 0; i < size; i++) {
        log[i].timestamp = time(NULL);
        if (success) {
            sprintf(log[i].message, "Memory allocation successful for record %d", i);
        } else {
            sprintf(log[i].message, "Memory allocation failed for record %d with error code %d", i, errorCode);
        }
    }
}

int main() {
    srand(time(NULL));
    int size = 10;
    int upperBound = 100;

    IntKeyRecord *records = createIntKeyRecords(size, upperBound);
    if (!records) {
        printf("Memory allocation failed\n");
        return 1;
    }

    int array[size];
    for (int i = 0; i < size; i++) {
        array[i] = records[i].record->value;
    }

    int largest = findLargestInteger(array, size);
    printf("The largest integer is: %d\n", largest);

    freeIntKeyRecords(records, size);

    return 0;
}
