};

void free_all_memory(double* measurements, char** strings, Point* points, enum Status* statuses, long long* timestamps) {
    free(measurements);
    for (int i = 0; i < MAX_STRING_LENGTH; i++) {
        free(strings[i]);
    }
    free(points);
    free(statuses);
    free(timestamps);
