enum Status initialize_data(int size, double** measurements, char*** strings, Point** points, enum Status** statuses, long long** timestamps) {
    *measurements = (double*)malloc(size * sizeof(double));
    if (*measurements == NULL) return MEMORY_ERROR;

    *strings = (char**)malloc(size * sizeof(char*));
    if (*strings == NULL) {
        free(*measurements);
        return MEMORY_ERROR;
    }

    for (int i = 0; i < size; i++) {
        (*strings)[i] = (char*)malloc(MAX_STRING_LENGTH * sizeof(char));
        if ((*strings)[i] == NULL) {
            free_all_memory(*measurements, *strings, *points, *statuses, *timestamps);
            return MEMORY_ERROR;
        }
    }

    *points = (Point*)malloc(size * sizeof(Point));
    if (*points == NULL) {
        free_all_memory(*measurements, *strings, *points, *statuses, *timestamps);
        return MEMORY_ERROR;
    }

    *statuses = (enum Status*)malloc(size * sizeof(enum Status));
    if (*statuses == NULL) {
        free_all_memory(*measurements, *strings, *points, *statuses, *timestamps);
        return MEMORY_ERROR;
    }

    *timestamps = (long long*)malloc(size * sizeof(long long));
    if (*timestamps == NULL) {
        free_all_memory(*measurements, *strings, *points, *statuses, *timestamps);
        return MEMORY_ERROR;
    }

    // Initialize data
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        (*measurements)[i] = ((double)rand() / RAND_MAX) * 100.0;
        snprintf((*strings)[i], MAX_STRING_LENGTH, "String%d", i);
        (*points)[i].x = ((float)rand() / RAND_MAX) * 360.0 - 180.0;
        (*points)[i].y = ((float)rand() / RAND_MAX) * 180.0 - 90.0;
        (*statuses)[i] = OK;
        (*timestamps)[i] = time(NULL);
    }

    return OK;
}

int main() {
    int size = 1000;
    double* measurements;
    char** strings;
    Point* points;
    enum Status* statuses;
    long long* timestamps;

    enum Status status = initialize_data(size, &measurements, &strings, &points, &statuses, &timestamps);
    if (status != OK) {
        printf("Initialization failed with status: %d\n", status);
        return 1;
    }

    // Use the initialized data...

    free_all_memory(measurements, strings, points, statuses, timestamps);

    return 0;
}
