#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_READINGS 1000
#define TEMP_MIN -50
#define TEMP_MAX 120
#define HUMIDITY_MIN 0
#define HUMIDITY_MAX 100

typedef struct {
    time_t timestamp;
    int device_id;
    float temperature;
    float humidity;
    char status[20];
} SensorReading;

SensorReading *sensor_readings[MAX_READINGS];
int current_index = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_sensor_reading(SensorReading **reading) {
    *reading = (SensorReading *)malloc(sizeof(SensorReading));
    if (*reading == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void free_sensor_readings() {
    for (int i = 0; i < current_index; i++) {
        free(sensor_readings[i]);
    }
    current_index = 0;
}

void add_sensor_reading(int device_id, float temperature, float humidity) {
    pthread_mutex_lock(&mutex);
    if (current_index >= MAX_READINGS) {
        fprintf(stderr, "Sensor readings limit reached\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    initialize_sensor_reading(&sensor_readings[current_index]);
    SensorReading *reading = sensor_readings[current_index];
    reading->timestamp = time(NULL);
    reading->device_id = device_id;

    if (temperature < TEMP_MIN || temperature > TEMP_MAX) {
        fprintf(stderr, "Invalid temperature value\n");
        free(reading);
        pthread_mutex_unlock(&mutex);
        return;
    }
    reading->temperature = temperature;

    if (humidity < HUMIDITY_MIN || humidity > HUMIDITY_MAX) {
        fprintf(stderr, "Invalid humidity value\n");
        free(reading);
        pthread_mutex_unlock(&mutex);
        return;
    }
    reading->humidity = humidity;

    snprintf(reading->status, sizeof(reading->status), "OK");

    current_index++;
    pthread_mutex_unlock(&mutex);
}

void filter_sensor_readings(float temp_threshold, float humidity_threshold) {
    for (int i = 0; i < current_index; i++) {
        if (sensor_readings[i]->temperature > temp_threshold ||
            sensor_readings[i]->humidity > humidity_threshold) {
            printf("Filtered reading: Device ID %d, Temp %.2f, Humidity %.2f\n",
                   sensor_readings[i]->device_id,
                   sensor_readings[i]->temperature,
                   sensor_readings[i]->humidity);
        }
    }
}

void *monitor_sensor_data(void *arg) {
    while (1) {
        // Simulate data collection
        add_sensor_reading(1, 25.0, 45.0);

        // Calculate and log average temperature and humidity
        float total_temp = 0, total_humidity = 0;
        for (int i = 0; i < current_index; i++) {
            total_temp += sensor_readings[i]->temperature;
            total_humidity += sensor_readings[i]->humidity;
        }
        printf("Average Temperature: %.2f, Average Humidity: %.2f\n",
               total_temp / current_index,
               total_humidity / current_index);

        // Sleep for a while before next collection
        sleep(10);
    }

    return NULL;
}

int main() {
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, monitor_sensor_data, NULL);

    pthread_join(thread_id, NULL);

    free_sensor_readings();

    return 0;
}
```

This code provides a basic implementation of the described functionality. It includes functions to initialize and free sensor readings, add new readings with validation, filter readings based on thresholds, and monitor sensor data in a separate thread. The main function creates a monitoring thread that periodically collects and processes sensor data.']

