#include <time.h>
#include <string.h>

#define MAX_MEMORY_USAGE 0.8

typedef struct {
    int* values;
    int size;
} Record;

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_memory(void** ptr) {
    if (*ptr) {
        free(*ptr);
        *ptr = NULL;
    }
}

int main() {
    size_t total_memory = sysconf(_SC_PHYS_PAGES) * sysconf(_SC_PAGE_SIZE);
    size_t max_allowed_memory = (size_t)(total_memory * MAX_MEMORY_USAGE);

    // Get user input for array sizes and random value range
    size_t offset_size, key_size;
    int min_value, max_value;
    printf("Enter the size of the offset array: ");
    scanf("%zu", &offset_size);
    printf("Enter the size of the key array: ");
    scanf("%zu", &key_size);
    printf("Enter the minimum value for random numbers: ");
    scanf("%d", &min_value);
    printf("Enter the maximum value for random numbers: ");
    scanf("%d", &max_value);

    // Validate user input
    if (offset_size * sizeof(long) + key_size * sizeof(int) > max_allowed_memory) {
        fprintf(stderr, "Requested memory exceeds 80%% of available system RAM\n");
        return EXIT_FAILURE;
    }
    if (min_value >= max_value) {
        fprintf(stderr, "Invalid range for random numbers\n");
        return EXIT_FAILURE;
    }

    // Allocate memory for arrays
    long* offsets = allocate_memory(offset_size * sizeof(long));
    int* keys = allocate_memory(key_size * sizeof(int));

    // Initialize arrays
    srand(time(NULL)); // Seed the random number generator
    for (size_t i = 0; i < offset_size; ++i) {
        offsets[i] = rand();
    }
    for (size_t i = 0; i < key_size; ++i) {
        keys[i] = min_value + rand() % (max_value - min_value + 1);
    }

    // Allocate memory for record structures
    size_t record_count;
    printf("Enter the number of records: ");
    scanf("%zu", &record_count);

    Record* records = allocate_memory(record_count * sizeof(Record));
    for (size_t i = 0; i < record_count; ++i) {
        size_t record_size;
        printf("Enter the size of the values array for record %zu: ", i);
        scanf("%zu", &record_size);

        if (record_size * sizeof(int) > max_allowed_memory - offset_size * sizeof(long) - key_size * sizeof(int)) {
            fprintf(stderr, "Requested memory exceeds 80%% of available system RAM\n");
            free_memory((void**)&records[i].values);
            continue;
        }

        records[i].values = allocate_memory(record_size * sizeof(int));
        records[i].size = record_size;

        // Initialize values array with random numbers
        for (size_t j = 0; j < record_size; ++j) {
            records[i].values[j] = rand();
        }
    }

    // Free allocated memory
    free_memory((void**)&offsets);
    free_memory((void**)&keys);
    for (size_t i = 0; i < record_count; ++i) {
        free_memory((void**)&records[i].values);
    }
    free_memory((void**)&records);

    return EXIT_SUCCESS;
}
