typedef struct {
    char** strings;
    int priority;
    int ref_count;
} item;

item* create_item(int string_count, const char* strings[], int min_priority, int max_priority, unsigned int seed) {
    if (string_count <= 0 || min_priority > max_priority) {
        return NULL; // Invalid input
    }

    item* new_item = malloc(sizeof(item));
    if (!new_item) {
        return NULL; // Memory allocation failed
    }

    new_item->strings = malloc(string_count * sizeof(char*));
    if (!new_item->strings) {
        free(new_item);
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < string_count; ++i) {
        new_item->strings[i] = strdup(strings[i]);
        if (!new_item->strings[i]) {
            for (int j = 0; j < i; ++j) {
                free(new_item->strings[j]);
            }
            free(new_item->strings);
            free(new_item);
            return NULL; // Memory allocation failed
        }
    }

    srand(seed);
    new_item->priority = min_priority + rand() % (max_priority - min_priority + 1);

    new_item->ref_count = 0;

    return new_item;
}

void destroy_item(item* item) {
    if (!item) {
        return; // Null pointer
    }

    for (int i = 0; i < strlen(item->strings); ++i) {
        free(item->strings[i]);
    }
    free(item->strings);
    free(item);
}
