    data->strings = (char **)calloc(size, sizeof(char *));
    data->points = (Point *)calloc(size, sizeof(Point));
    data->statuses = (Status *)calloc(size, sizeof(Status));
    data->timestamps = (long long *)calloc(size, sizeof(long long));
    data->metadata = (Metadata *)calloc(size, sizeof(Metadata));
    data->size = size;

    if (!data->measurements || !data->strings || !data->points || !data->statuses || !data->timestamps || !data->metadata) {
        fprintf(stderr, "Memory allocation failed for one or more data structures\n");
        free(data);
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        data->measurements[i] = ((double)rand() / RAND_MAX) * 100.0 - 50.0; // Random double between -50 and 50
        data->strings[i] = (char *)malloc(MAX_STRING_LENGTH);
        if (!data->strings[i]) {
            fprintf(stderr, "Memory allocation failed for string at index %d\n", i);
            free_geospatial_data(data);
            return NULL;
