        snprintf(data->strings[i], MAX_STRING_LENGTH, "%c%c%c", 'A' + rand() % 26, 'a' + rand() % 26, '0' + rand() % 10);
        data->points[i].x = ((float)rand() / RAND_MAX) * 360.0 - 180.0; // Random float between -180 and 180
        data->points[i].y = ((float)rand() / RAND_MAX) * 180.0 - 90.0; // Random float between -90 and 90
        data->statuses[i] = (rand() % 2 == 0) ? STATUS_OK : STATUS_ERROR;
        data->timestamps[i] = time(NULL);
        snprintf(data->metadata[i].metadata, MAX_STRING_LENGTH, "Metadata for point %d", i);
    }

    return data;
}

void free_geospatial_data(GeospatialData *data) {
    if (data) {
        for (int i = 0; i < data->size; i++) {
            free(data->strings[i]);
        }
        free(data->measurements);
        free(data->strings);
        free(data->points);
        free(data->statuses);
        free(data->timestamps);
        free(data->metadata);
        free(data);
    }
}

