#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct {
    time_t timestamp;
    size_t size;
} metadata;

int find_largest(int* array, int size) {
    if (size <= 0) return -1; // Handle edge case
    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

void initialize_data(int* keys, record* records, metadata* metadata_tags, int key_count, int upper_bound) {
    for (int i = 0; i < key_count; i++) {
        keys[i] = rand() % (upper_bound + 1);
        records[i].value = keys[i];
        metadata_tags[i].timestamp = time(NULL);
        metadata_tags[i].size = sizeof(record);
    }
}

void free_memory(int* keys, record* records, metadata* metadata_tags) {
    free(keys);
    free(records);
    free(metadata_tags);
}

int main() {
    srand(time(NULL));
    int key_count;
    printf("Enter the number of keys: ");
    scanf("%d", &key_count);

    int* keys = (int*)malloc(key_count * sizeof(int));
    record* records = (record*)malloc(key_count * sizeof(record));
    metadata* metadata_tags = (metadata*)malloc(key_count * sizeof(metadata));

    if (!keys || !records || !metadata_tags) {
        printf("Memory allocation failed.\n");
        free_memory(keys, records, metadata_tags);
        return 1;
    }

    initialize_data(keys, records, metadata_tags, key_count, 100); // Upper bound set to 100

    int largest = find_largest(keys, key_count);
    printf("Largest integer: %d\n", largest);

    free_memory(keys, records, metadata_tags);
    return 0;
}
