int find_largest(int* keys, int count) {
    int largest = keys[0];
    for (int i = 1; i < count; i++) {
        if (keys[i] > largest) {
            largest = keys[i];
        }
    }
    printf("Largest key: %d\n", largest);
    return largest;
}

void initialize_system(int* keys, record** records, int* log, int key_count, int upper_bound) {
    srand(time(NULL));
    *records = (record*)safe_malloc(key_count * sizeof(record));
    for (int i = 0; i < key_count; i++) {
        (*records)[i].value = rand() % (upper_bound + 1);
    }
    find_largest(keys, key_count);
}

void cleanup(int* keys, record** records, int* log) {
    free(*records);
    // Additional cleanup for log if needed
}

int main(int argc, char* argv[]) {
    int key_count = 5;
    int upper_bound = 100;
    int* keys = (int*)safe_malloc(key_count * sizeof(int));
    record* records;

    // Initialize keys from command-line arguments or CSV file
    for (int i = 0; i < key_count; i++) {
        keys[i] = atoi(argv[i + 1]);
    }

    initialize_system(keys, &records, NULL, key_count, upper_bound);

    cleanup(keys, &records, NULL);

    free(keys);
    return 0;
}
