// Define the structures
typedef struct Node {
    long value;
    struct Node* next;
    struct Node* prev;
} Node;

typedef struct Record {
    char* str;
    double dbl;
    Node* node;
} Record;

// Function to allocate memory and initialize linked lists
int init_linked_lists(int size, int max_double, int start_node, int end_node) {
    // Allocate memory for the linked lists
    Node** double_list = (Node**)malloc(size * sizeof(Node*));
    char*** string_list = (char***)malloc(size * sizeof(char**));
    Record** record_list = (Record**)malloc(size * sizeof(Record*));

    if (!double_list || !string_list || !record_list) {
        // Handle memory allocation failure
        free(double_list);
        free(string_list);
        free(record_list);
        return -1;
    }

    // Initialize the linked lists
    for (int i = 0; i < size; i++) {
        double_list[i] = NULL;
        string_list[i] = NULL;
        record_list[i] = (Record*)malloc(sizeof(Record));
        if (!record_list[i]) {
            // Handle memory allocation failure
            for (int j = 0; j < i; j++) {
                free(record_list[j]);
            }
            free(double_list);
            free(string_list);
            free(record_list);
            return -1;
        }

        record_list[i]->str = (char*)malloc(256 * sizeof(char));
        if (!record_list[i]->str) {
            // Handle memory allocation failure
            free(record_list[i]);
            for (int j = 0; j < i; j++) {
                free(record_list[j]);
            }
            free(double_list);
            free(string_list);
            free(record_list);
            return -1;
        }

        record_list[i]->dbl = ((double)rand() / RAND_MAX) * max_double;

        Node* head = NULL;
        for (int j = start_node; j <= end_node; j++) {
            Node* new_node = (Node*)malloc(sizeof(Node));
            if (!new_node) {
                // Handle memory allocation failure
                free(record_list[i]->str);
                free(record_list[i]);
                for (int k = 0; k < i; k++) {
                    free(record_list[k]->str);
                    free(record_list[k]);
                }
                free(double_list);
                free(string_list);
                free(record_list);
                return -1;
            }
            new_node->value = j;
            new_node->next = head;
            new_node->prev = NULL;
            if (head) {
                head->prev = new_node;
            }
            head = new_node;
        }

        record_list[i]->node = head;
    }

    // Free the allocated memory
    for (int i = 0; i < size; i++) {
        Node* current = record_list[i]->node;
        while (current) {
            Node* next = current->next;
            free(current);
            current = next;
        }
        free(record_list[i]->str);
        free(record_list[i]);
    }

    free(double_list);
    free(string_list);
    free(record_list);

    return 0;
}

int main() {
    srand(time(NULL));
    int size = 10;
    int max_double = 100.0;
    int start_node = 1;
    int end_node = 10;

    if (init_linked_lists(size, max_double, start_node, end_node) == -1) {
        printf("Memory allocation failed.\n");
    } else {
        printf("Linked lists initialized successfully.\n");
    }

    return 0;
}
