    }

    for (int i = 0; i < MAX_RECORDS; i++) {
        (*labels)[i] = (char *)malloc(MAX_LABEL_LENGTH * sizeof(char));
        if (!(*labels)[i]) {
            free_memory(offsets, keys, records, labels, error_codes);
            return -1; // Memory allocation failed
        }
    }

