import java.util.ArrayList;
import java.util.List;
import java.util.Random;

public class ProductCatalogManager {
    private static final int MAX_MEMORY_FOOTPRINT = 1024 * 1024; // 1 MB
    private List<Product> catalog;
    private Random random;

    public ProductCatalogManager() {
        this.catalog = new ArrayList<>();
        this.random = new Random();
    }

    public boolean createCatalog(int size, int priceUpperBound) {
        if (size * (Product.NAME_LENGTH + Product.PRICE_SIZE + Product.CATEGORY_LENGTH + Product.ID_SIZE) > MAX_MEMORY_FOOTPRINT) {
            return false; // Insufficient memory
        }

        for (int i = 0; i < size; i++) {
            String name = generateRandomString(Product.NAME_LENGTH);
            double price = random.nextDouble() * priceUpperBound;
            String category = generateRandomString(Product.CATEGORY_LENGTH);
            String id = generateRandomString(Product.ID_SIZE);

            Product product = new Product(name, price, category, id);
            catalog.add(product);
        }

        return true; // Success
    }

    public String convertToJson() {
        StringBuilder jsonBuilder = new StringBuilder();
        jsonBuilder.append("[");
        for (int i = 0; i < catalog.size(); i++) {
            if (i > 0) {
                jsonBuilder.append(",");
            }
            jsonBuilder.append(catalog.get(i).toJson());
        }
        jsonBuilder.append("]");
        return jsonBuilder.toString();
    }

    private String generateRandomString(int length) {
        StringBuilder sb = new StringBuilder(length);
        for (int i = 0; i < length; i++) {
            char c = (char) ('a' + random.nextInt(26));
            sb.append(c);
        }
        return sb.toString();
    }

    private static class Product {
        public static final int NAME_LENGTH = 50;
        public static final int PRICE_SIZE = 8;
        public static final int CATEGORY_LENGTH = 30;
        public static final int ID_SIZE = 10;

        private String name;
        private double price;
        private String category;
        private String id;

        public Product(String name, double price, String category, String id) {
            this.name = name;
            this.price = price;
            this.category = category;
            this.id = id;
        }

        public String toJson() {
            return "{\"name\":\"" + name + "\",\"price\":" + price + ",\"category\":\"" + category + "\",\"id\":\"" + id + "\"}";
        }
    }
}
