#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int value;
    int *key;
    long *offset;
    char *variable_name;
    struct timestamp *timestamp;
} record;

typedef struct {
    time_t seconds;
    suseconds_t microseconds;
} timestamp;

#define INITIAL_CAPACITY 1024

record **records = NULL;
int records_capacity = 0;
int records_size = 0;
pthread_mutex_t records_mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_records() {
    pthread_mutex_lock(&records_mutex);
    if (records == NULL) {
        records_capacity = INITIAL_CAPACITY;
        records = (record **)malloc(records_capacity * sizeof(record *));
        if (records == NULL) {
            fprintf(stderr, "Failed to allocate memory for records\n");
            exit(EXIT_FAILURE);
        }
        memset(records, 0, records_capacity * sizeof(record *));
    }
    pthread_mutex_unlock(&records_mutex);
}

void add_record(int key, long offset, const char *variable_name, timestamp *timestamp) {
    pthread_mutex_lock(&records_mutex);
    if (records_size >= records_capacity) {
        records_capacity *= 2;
        record **new_records = (record **)realloc(records, records_capacity * sizeof(record *));
        if (new_records == NULL) {
            fprintf(stderr, "Failed to reallocate memory for records\n");
            exit(EXIT_FAILURE);
        }
        records = new_records;
    }

    records[records_size] = (record *)malloc(sizeof(record));
    if (records[records_size] == NULL) {
        fprintf(stderr, "Failed to allocate memory for record\n");
        exit(EXIT_FAILURE);
    }

    records[records_size]->value = 0; // Initialize value
    records[records_size]->key = &key;
    records[records_size]->offset = &offset;
    records[records_size]->variable_name = strdup(variable_name);
    records[records_size]->timestamp = timestamp;

    records_size++;
    pthread_mutex_unlock(&records_mutex);
}

void free_records() {
    pthread_mutex_lock(&records_mutex);
    for (int i = 0; i < records_size; i++) {
        if (records[i] != NULL) {
            free(records[i]);
        }
    }
    free(records);
    records = NULL;
    records_capacity = 0;
    records_size = 0;
    pthread_mutex_unlock(&records_mutex);
}

int main() {
    initialize_records();
    add_record(1, 12345, "variable1", (timestamp *)malloc(sizeof(timestamp)));
    // Add more records as needed
    free_records();
    return 0;
}
```

This code provides a basic structure for managing a dataset of records with dynamic memory allocation and thread safety. It includes functions to initialize the records array, add new records, and free the allocated memory when done. The use of mutexes ensures that concurrent access is handled safely.']

