void free_node(Node *node) {
    if (node != NULL) {
        free_record(node->record);
        free(node);
    }
}

Node* insert_node(Node **head, int key, Record *record) {
    Node *new_node = create_node(key, record);
    if (new_node == NULL) {
        return *head;
    }
    new_node->next = *head;
    *head = new_node;
    return *head;
}

void delete_node(Node **head, int key) {
    Node *current = *head;
    Node *previous = NULL;

    while (current != NULL && current->key != key) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        return;
    }

    if (previous == NULL) {
        *head = current->next;
    } else {
        previous->next = current->next;
    }

    free_node(current);
}

Record* get_record(Node **head, int key) {
    Node *current = *head;

    while (current != NULL && current->key != key) {
        current = current->next;
    }

    if (current == NULL) {
        return NULL;
    }

    return current->record;
}

void update_record(Node **head, int key, Record *new_record) {
    Node *node = get_record(head, key);
    if (node != NULL) {
        free_record(node->record);
        node->record = new_record;
        node->timestamp = time(NULL);
    }
}

int main() {
    srand(time(NULL));

    Node *head = NULL;

    for (int i = 0; i < MAX_RECORDS; i++) {
        int key = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;
        Record *record = (Record *)malloc(sizeof(Record));
        if (record == NULL) {
            perror("Failed to allocate memory for record");
            continue;
        }
        record->value = i;

        head = insert_node(&head, key, record);
    }

    // Example usage
    int search_key = rand() % (MAX_KEY - MIN_KEY + 1) + MIN_KEY;
    Record *found_record = get_record(&head, search_key);
    if (found_record != NULL) {
        printf("Found record with value: %d\n", found_record->value);
    }

    // Clean up
    while (head != NULL) {
        Node *temp = head;
        head = head->next;
        free_node(temp);
    }

    return 0;
}
