#include <stdio.h>
#include <stdlib.h>

// Define structures for offset, key, record, and linked list node
typedef struct Offset {
    long value;
} Offset;

typedef struct Key {
    int value;
} Key;

typedef struct Record {
    int data;
    Offset* offset;
    struct Record* next;
} Record;

typedef struct Node {
    Key* key;
    Record* record;
    struct Node* next;
} Node;

// Function to create a new offset
Offset* create_offset(long value) {
    Offset* offset = (Offset*)malloc(sizeof(Offset));
    if (offset == NULL) {
        fprintf(stderr, "Memory allocation failed for offset\n");
        exit(EXIT_FAILURE);
    }
    offset->value = value;
    return offset;
}

// Function to create a new key
Key* create_key(int value) {
    Key* key = (Key*)malloc(sizeof(Key));
    if (key == NULL) {
        fprintf(stderr, "Memory allocation failed for key\n");
        exit(EXIT_FAILURE);
    }
    key->value = value;
    return key;
}

// Function to create a new record
Record* create_record(int data, Offset* offset) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (record == NULL) {
        fprintf(stderr, "Memory allocation failed for record\n");
        exit(EXIT_FAILURE);
    }
    record->data = data;
    record->offset = offset;
    record->next = NULL;
    return record;
}

// Function to create a new node
Node* create_node(Key* key, Record* record) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (node == NULL) {
        fprintf(stderr, "Memory allocation failed for node\n");
        exit(EXIT_FAILURE);
    }
    node->key = key;
    node->record = record;
    node->next = NULL;
    return node;
}

// Function to insert a new record into the linked list
void insert_record(Node** head, Key* key, Record* record) {
    Node* newNode = create_node(key, record);
    if (*head == NULL) {
        *head = newNode;
    } else {
        Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
}

// Function to delete a record from the linked list based on key
void delete_record(Node** head, int key_value) {
    if (*head == NULL) return;

    Node* temp = *head;
    Node* prev = NULL;

    if (temp != NULL && temp->key->value == key_value) {
        *head = temp->next;
        free(temp);
        return;
    }

    while (temp != NULL && temp->key->value != key_value) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return;

    prev->next = temp->next;
    free(temp);
}

// Function to search for a record in the linked list based on key
Record* search_record(Node* head, int key_value) {
    Node* current = head;
    while (current != NULL) {
        if (current->key->value == key_value) {
            return current->record;
        }
        current = current->next;
    }
    return NULL;
}

// Function to free the memory allocated for the linked list
void free_list(Node* head) {
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp->key);
        free(temp->record->offset);
        free(temp->record);
        free(temp);
    }
}
```

