struct CustomStruct {
    double value;
    std::unique_ptr<std::string> str;

    CustomStruct(double v, const std::string& s) : value(v), str(std::make_unique<std::string>(s)) {}
};

class ServiceComponent {
public:
    void start() {
        running = true;
        workerThread = std::thread(&ServiceComponent::run, this);
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            running = false;
        }
        condition.notify_all();
        if (workerThread.joinable()) {
            workerThread.join();
        }
    }

private:
    void run() {
        while (true) {
            std::unique_lock<std::mutex> lock(mutex);
            condition.wait(lock, [this] { return !running || !tasks.empty(); });
            if (!running && tasks.empty()) {
                break;
            }
            auto task = std::move(tasks.front());
            tasks.pop();
            lock.unlock();

            // Simulate processing task
            processTask(task);
        }
    }

    void processTask(const CustomStruct& task) {
        // Placeholder for task processing logic
        std::cout << "Processing task with value: " << task.value << " and string: " << *task.str << std::endl;
    }

    std::mutex mutex;
    std::condition_variable condition;
    bool running = false;
    std::queue<CustomStruct> tasks;
};

int main() {
