    customer->ID = ID;
    customer->orderIDs = (int*)malloc(10 * sizeof(int)); // Assuming a maximum of 10 orders
    if (!customer->orderIDs) {
        free(customer);
        return NULL;
    }
    customer->transactionCount = 0;

    customer->transactions = (Transaction**)malloc(maxTransactions * sizeof(Transaction*));
    if (!customer->transactions) {
        free(customer->orderIDs);
        free(customer);
        return NULL;
    }

    for (int i = 0; i < maxTransactions; i++) {
        customer->transactions[i] = (Transaction*)malloc(sizeof(Transaction));
        if (!customer->transactions[i]) {
            for (int j = 0; j < i; j++) {
                free(customer->transactions[j]);
            }
            free(customer->transactions);
            free(customer->orderIDs);
            free(customer);
            return NULL;
        }
    }

    // Initialize customer data
    srand(time(NULL));
    snprintf(customer->name, MAX_NAME_LENGTH, "Customer%d", ID);
    strcpy(customer->status, "Active");

    return customer;
}

void freeCustomer(Customer* customer) {
    if (customer) {
        for (int i = 0; i < customer->transactionCount; i++) {
            free(customer->transactions[i]);
        }
        free(customer->transactions);
        free(customer->orderIDs);
        free(customer);
