typedef struct UserProfile {
    int userID;
    char name[100];
    char email[100];
    char contactID[256];
    char preferences[512];
    int membershipStatus;
} UserProfile;

UserProfile* createProfile(int userID, const char* name, const char* email, const char* prefix, const char* suffix, int maxContactLength) {
    UserProfile* profile = (UserProfile*)malloc(sizeof(UserProfile));
    if (!profile) return NULL;

    profile->userID = userID;
    strncpy(profile->name, name, sizeof(profile->name) - 1);
    strncpy(profile->email, email, sizeof(profile->email) - 1);

    size_t prefixLen = strlen(prefix);
    size_t suffixLen = strlen(suffix);
    if (prefixLen + suffixLen > maxContactLength - 1) {
        free(profile);
        return NULL;
    }

    snprintf(profile->contactID, maxContactLength, "%s%.*s%s", prefix, maxContactLength - prefixLen - suffixLen - 1, name, suffix);

    // Initialize preferences and membership status
    memset(profile->preferences, 0, sizeof(profile->preferences));
    profile->membershipStatus = 0;

    return profile;
}

void freeProfile(UserProfile* profile) {
    if (profile) {
        free(profile);
    }
}
