#define MAX_ITEMS 10000
#define MAX_BUFFER_LENGTH 256

typedef struct {
    long id;
    int priority;
    char buffer[MAX_BUFFER_LENGTH];
} item;

item* items = NULL;
int allocated_size = 0;
int current_size = 0;

void initialize_memory() {
    allocated_size = 100; // Initial allocation size
    items = (item*)malloc(allocated_size * sizeof(item));
}

void resize_memory(int new_size) {
    if (new_size > allocated_size) {
        item* temp = (item*)realloc(items, new_size * sizeof(item));
        if (temp == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        items = temp;
        allocated_size = new_size;
    }
}

void add_item(long id, int priority, const char* buffer) {
    if (current_size >= allocated_size) {
        resize_memory(allocated_size * 2); // Double the size on demand
    }
    item* new_item = &items[current_size++];
    new_item->id = id;
    new_item->priority = priority;
    strncpy(new_item->buffer, buffer, MAX_BUFFER_LENGTH - 1);
    new_item->buffer[MAX_BUFFER_LENGTH - 1] = '\0'; // Ensure null-termination
}

void free_memory() {
    free(items);
    items = NULL;
    allocated_size = 0;
    current_size = 0;
}
