    srand(time(NULL)); // Seed the random number generator

    for (size_t i = 0; i < numRecords; ++i) {
        metadataEntries[i] = (MetadataEntry*)malloc(sizeof(MetadataEntry));
        if (!metadataEntries[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        metadataEntries[i]->offset = generateRandomNumber(100); // Example offset generation
        metadataEntries[i]->record.count = generateRandomNumber(10) + 1; // Random number of integers per record

        metadataEntries[i]->record.values = (int*)malloc(metadataEntries[i]->record.count * sizeof(int));
        if (!metadataEntries[i]->record.values) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        for (size_t j = 0; j < metadataEntries[i]->record.count; ++j) {
            metadataEntries[i]->record.values[j] = generateRandomNumber(upperBound);
        }
    }
}

// Function to read integers from standard input and find the largest
int findLargestInteger() {
    int num;
    int max = INT_MIN;

    while (scanf("%d", &num) != EOF) {
        if (num > max) {
            max = num;
        }
    }

    return max;
}

// Function to free allocated memory
void freeMemory(MetadataEntry** metadataEntries, size_t numRecords) {
    for (size_t i = 0; i < numRecords; ++i) {
        free(metadataEntries[i]->record.values);
        free(metadataEntries[i]);
    }
    free(metadataEntries);
}

