wchar_t* appendSlashIfLimit(wchar_t* str, size_t maxBytes) {
    size_t length = wcslen(str);
    size_t byteSize = wcstombs(NULL, str, 0);

    if (byteSize <= maxBytes) {
        wchar_t* newStr = realloc(str, (length + 2) * sizeof(wchar_t));
        if (newStr == NULL) return NULL;
        newStr[length] = L'/';
        newStr[length + 1] = L'\0';
