#include <string.h>
#include <time.h>

#define MAX_STRING_LENGTH 256

typedef struct {
    int* intKeys;
    double* doubleValues;
    char** stringRecords;
    size_t size;
} DataContainer;

int initializeData(DataContainer* container, size_t size) {
    container->size = size;

    container->intKeys = (int*)malloc(size * sizeof(int));
    if (container->intKeys == NULL) {
        return -1; // Memory allocation failed
    }

    container->doubleValues = (double*)malloc(size * sizeof(double));
    if (container->doubleValues == NULL) {
        free(container->intKeys);
        return -1; // Memory allocation failed
    }

    container->stringRecords = (char**)malloc(size * sizeof(char*));
    if (container->stringRecords == NULL) {
        free(container->intKeys);
        free(container->doubleValues);
        return -1; // Memory allocation failed
    }

    for (size_t i = 0; i < size; i++) {
        container->stringRecords[i] = (char*)malloc(MAX_STRING_LENGTH * sizeof(char));
        if (container->stringRecords[i] == NULL) {
            for (size_t j = 0; j < i; j++) {
                free(container->stringRecords[j]);
            }
            free(container->intKeys);
            free(container->doubleValues);
            free(container->stringRecords);
            return -1; // Memory allocation failed
        }
    }

    srand(time(NULL));
    for (size_t i = 0; i < size; i++) {
        container->intKeys[i] = rand() % 100; // Random number between 0 and 99
        container->doubleValues[i] = ((double)rand()) / RAND_MAX * 100.0; // Random double between 0 and 100
        snprintf(container->stringRecords[i], MAX_STRING_LENGTH, "Record %zu", i);
    }

    return 0; // Success
}

void freeData(DataContainer* container) {
    for (size_t i = 0; i < container->size; i++) {
        free(container->stringRecords[i]);
    }
    free(container->intKeys);
    free(container->doubleValues);
    free(container->stringRecords);
}

int main() {
    size_t size;
    printf("Enter the number of elements: ");
    scanf("%zu", &size);

    DataContainer container;
    if (initializeData(&container, size) != 0) {
        fprintf(stderr, "Failed to initialize data.\n");
        return 1;
    }

    // Perform operations
    int maxInt = container.intKeys[0];
    double sumDouble = 0.0;
    for (size_t i = 0; i < size; i++) {
        if (container.intKeys[i] > maxInt) {
            maxInt = container.intKeys[i];
        }
        sumDouble += container.doubleValues[i];
    }

    printf("Maximum integer: %d\n", maxInt);
    printf("Average of double values: %.2f\n", sumDouble / size);

    // Concatenate all strings
    char* concatenatedString = (char*)malloc((size * MAX_STRING_LENGTH) * sizeof(char));
    if (concatenatedString == NULL) {
        fprintf(stderr, "Failed to allocate memory for concatenated string.\n");
        freeData(&container);
        return 1;
    }

    concatenatedString[0] = '\0';
    for (size_t i = 0; i < size; i++) {
        strcat(concatenatedString, container.stringRecords[i]);
    }

    printf("Concatenated string: %s\n", concatenatedString);

    free(concatenatedString);
    freeData(&container);

    return 0;
}
