#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <json-c/json.h>

#define MAX_KEYS 1000
#define MAX_RECORD_SIZE 256

typedef struct {
    int value;
} Record;

typedef struct {
    int key;
    Record record;
    char log[MAX_RECORD_SIZE];
} SystemRecord;

SystemRecord *system_records = NULL;
int num_records = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* initialize_system(void* config_file_path) {
    json_object *config_json, *upper_bound_obj, *log_level_obj;
    int upper_bound, log_level;

    // Read configuration from JSON file
    FILE *fp = fopen((char*)config_file_path, "r");
    if (!fp) {
        perror("Failed to open config file");
        return NULL;
    }
    config_json = json_tokener_parse_file(fp);
    fclose(fp);

    upper_bound_obj = json_object_object_get_ex(config_json, "upper_bound", &upper_bound);
    log_level_obj = json_object_object_get_ex(config_json, "log_level", &log_level);

    if (!upper_bound_obj || !log_level_obj) {
        fprintf(stderr, "Invalid config file\n");
        return NULL;
    }

    upper_bound = json_object_get_int(upper_bound_obj);
    log_level = json_object_get_int(log_level_obj);

    // Allocate memory for system records
    system_records = (SystemRecord*)malloc(MAX_KEYS * sizeof(SystemRecord));
    if (!system_records) {
        perror("Failed to allocate memory");
        return NULL;
    }

    num_records = 0;

    // Initialize records with random values
    srand(time(NULL));
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_KEYS; i++) {
        system_records[i].key = i;
        system_records[i].record.value = rand() % upper_bound;
        snprintf(system_records[i].log, MAX_RECORD_SIZE, "Record initialized with value: %d", system_records[i].record.value);
        num_records++;
    }
    pthread_mutex_unlock(&mutex);

    return NULL;
}

void* retrieve_record(void* key_ptr) {
    int *key = (int*)key_ptr;
    SystemRecord *record;

    pthread_mutex_lock(&mutex);
    if (*key >= 0 && *key < num_records) {
        record = &system_records[*key];
        printf("Retrieved record: Key=%d, Value=%d\n", record->key, record->record.value);
    } else {
        printf("Invalid key\n");
    }
    pthread_mutex_unlock(&mutex);

    return NULL;
}

int main() {
    char config_file_path[] = "config.json";
    pthread_t init_thread, retrieve_threads[MAX_KEYS];
    int keys[MAX_KEYS];

    // Initialize system
    if (pthread_create(&init_thread, NULL, initialize_system, config_file_path) != 0) {
        perror("Failed to create initialization thread");
        return EXIT_FAILURE;
    }
    pthread_join(init_thread, NULL);

    // Retrieve records concurrently
    for (int i = 0; i < MAX_KEYS; i++) {
        keys[i] = i % num_records;
        if (pthread_create(&retrieve_threads[i], NULL, retrieve_record, &keys[i]) != 0) {
            perror("Failed to create retrieval thread");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < MAX_KEYS; i++) {
        pthread_join(retrieve_threads[i], NULL);
    }

    // Cleanup
    free(system_records);

    return EXIT_SUCCESS;
}
