                free(records[j]);
            }
            free(keys);
            free(records);
            return -3; // Insufficient memory
        }
        records[i]->value = rand() % (upper_bound + 1);
    }

    int* input_keys = (int*)malloc(key_count * sizeof(int));
    if (!input_keys) {
        for (int i = 0; i < record_count; i++) {
            free(records[i]);
        }
        free(keys);
        free(records);
        return -4; // Insufficient memory
    }

    printf("Enter %d integers:\n", key_count);
    int read_count = scanf("%d", input_keys);
    while (read_count != key_count) {
        for (int i = 0; i < record_count; i++) {
            free(records[i]);
        }
        free(keys);
        free(records);
        free(input_keys);
        return -5; // Invalid input
    }

    int max_value = find_max_record_value(records, record_count);

    for (int i = 0; i < record_count; i++) {
        free(records[i]);
    }
    free(keys);
    free(records);
    free(input_keys);

    printf("Maximum value: %d\n", max_value);
    return 0;
}

int find_max_record_value(record* records, int record_count) {
    int max_value = records[0]->value;
    for (int i = 1; i < record_count; i++) {
        if (records[i]->value > max_value) {
            max_value = records[i]->value;
        }
    }
    return max_value;
}
