#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_URL_LENGTH 1024
#define IDENTIFIER_LENGTH 16

typedef struct {
    char path[MAX_URL_LENGTH];
    int frequency[256];
} PathInfo;

unsigned long custom_hash(const char *str) {
    unsigned long hash = 5381;
    int c;
    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash % IDENTIFIER_LENGTH;
}

void classify_character(char ch, int *categories) {
    if (ch >= 'a' && ch <= 'z') categories[0]++;
    else if (ch >= 'A' && ch <= 'Z') categories[1]++;
    else if (ch >= '0' && ch <= '9') categories[2]++;
    else categories[3]++;
}

void process_url(const char *url, char *output) {
    PathInfo path_info;
    memset(&path_info, 0, sizeof(PathInfo));

    // Extract path part
    const char *last_slash = strrchr(url, '/');
    if (last_slash != NULL) {
        strncpy(path_info.path, last_slash + 1, MAX_URL_LENGTH - 1);
    }

    // Calculate character frequency
    for (int i = 0; path_info.path[i] != '\0'; i++) {
        classify_character(path_info.path[i], path_info.frequency);
    }

    // Generate identifier
    unsigned long identifier = custom_hash(path_info.path);

    // Replace non-alphanumeric characters with hyphens
    char temp_path[MAX_URL_LENGTH];
    strcpy(temp_path, path_info.path);
    for (int i = 0; temp_path[i] != '\0'; i++) {
        if (!isalnum(temp_path[i])) {
            temp_path[i] = '-';
        }
    }

    // Format output URL
    snprintf(output, MAX_URL_LENGTH, "%s", url);
    strcat(output, "/");
    char identifier_str[IDENTIFIER_LENGTH + 1];
    sprintf(identifier_str, "%lu", identifier);
    strcat(output, identifier_str);

    // Log statistical information (simulated)
    printf("Path: %s\nIdentifier: %lu\n", path_info.path, identifier);
}

int main() {
    const char *url = "https://example.com/path/to/resource?query=param";
    char output[MAX_URL_LENGTH];
    process_url(url, output);
    printf("Processed URL: %s\n", output);
    return 0;
}
