#define MAX_STR_LEN 256

typedef struct {
    int* keys;
    double* values;
    char** strings;
    bool* flags;
    size_t size;
} DataStructures;

void log_error(const char* message) {
    // Implement logging mechanism here
}

bool allocate_memory(DataStructures* ds, size_t size) {
    ds->keys = (int*)malloc(size * sizeof(int));
    ds->values = (double*)malloc(size * sizeof(double));
    ds->strings = (char**)malloc(size * sizeof(char*));
    ds->flags = (bool*)malloc(size * sizeof(bool));

    if (!ds->keys || !ds->values || !ds->strings || !ds->flags) {
        log_error("Memory allocation failed");
        return false;
    }

    for (size_t i = 0; i < size; ++i) {
        ds->strings[i] = (char*)malloc(MAX_STR_LEN * sizeof(char));
        if (!ds->strings[i]) {
            log_error("String memory allocation failed");
            free_memory(ds);
            return false;
        }
    }

    ds->size = size;
    return true;
}

void free_memory(DataStructures* ds) {
    for (size_t i = 0; i < ds->size; ++i) {
        free(ds->strings[i]);
    }
    free(ds->keys);
    free(ds->values);
    free(ds->strings);
    free(ds->flags);
}

bool read_input(DataStructures* ds, size_t size) {
    for (size_t i = 0; i < size; ++i) {
        if (scanf("%d %lf %s %d", &ds->keys[i], &ds->values[i], ds->strings[i], &ds->flags[i]) != 4) {
            log_error("Input reading failed");
            return false;
        }
    }
    return true;
}

void process_data(DataStructures* ds, size_t size) {
    int max_key = ds->keys[0];
    double sum_values = ds->values[0];
    bool all_valid = ds->flags[0];

    for (size_t i = 1; i < size; ++i) {
        if (ds->keys[i] > max_key) {
            max_key = ds->keys[i];
        }
        sum_values += ds->values[i];
        all_valid &= ds->flags[i];
    }

    printf("Max Key: %d\n", max_key);
    printf("Average Value: %.2f\n", sum_values / size);
    printf("All Strings Valid: %s\n", all_valid ? "Yes" : "No");
}

int main() {
    size_t size;
    printf("Enter the number of data entries: ");
    scanf("%zu", &size);

    DataStructures ds;
    if (!allocate_memory(&ds, size)) {
        return 1;
    }

    if (!read_input(&ds, size)) {
        free_memory(&ds);
        return 1;
    }

    process_data(&ds, size);

    free_memory(&ds);
    return 0;
}
