#include <stdlib.h>
#include <time.h>

typedef enum {
    CELSIUS,
    FAHRENHEIT,
    KELVIN,
    RANKINE,
    CUSTOM
} temperature_unit;

typedef struct {
    long offset;
    int key;
    int value;
} record;

typedef struct {
    double temperature;
    int id;
    char* unit;
    temperature_unit type;
} data_point;

int allocate_and_init_records(long start_offset, long end_offset, int start_key, int end_key,
                              double start_temp, double end_temp, int num_records,
                              int sort_ascending, int randomize_offsets, record** records_ptr,
                              data_point** data_points_ptr) {
    if (num_records <= 0 || start_offset > end_offset || start_key > end_key ||
        start_temp > end_temp) {
        return -1; // Invalid input parameters
    }

    *records_ptr = malloc(num_records * sizeof(record));
    *data_points_ptr = malloc(num_records * sizeof(data_point));

    if (*records_ptr == NULL || *data_points_ptr == NULL) {
        free(*records_ptr);
        free(*data_points_ptr);
        return -2; // Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < num_records; i++) {
        (*records_ptr)[i].offset = randomize_offsets ? rand() % (end_offset - start_offset + 1) + start_offset : i;
        (*records_ptr)[i].key = rand() % (end_key - start_key + 1) + start_key;
        (*records_ptr)[i].value = rand();

        double temp = ((double)rand() / RAND_MAX) * (end_temp - start_temp) + start_temp;
        (*data_points_ptr)[i].temperature = temp;
        (*data_points_ptr)[i].id = i;
        (*data_points_ptr)[i].unit = "Celsius"; // Default unit
        (*data_points_ptr)[i].type = CELSIUS;   // Default type
    }

    if (sort_ascending) {
        qsort(*data_points_ptr, num_records, sizeof(data_point), compare_temperatures);
    } else {
        qsort(*data_points_ptr, num_records, sizeof(data_point), compare_temperatures_desc);
    }

    return 0; // Success
}

int compare_temperatures(const void* a, const void* b) {
    data_point* point_a = (data_point*)a;
    data_point* point_b = (data_point*)b;

    if (point_a->temperature < point_b->temperature) return -1;
    if (point_a->temperature > point_b->temperature) return 1;
    return 0;
}

int compare_temperatures_desc(const void* a, const void* b) {
    return compare_temperatures(b, a);
}
