}

int main() {
    int n;
    printf("Enter the number of points: ");
    scanf("%d", &n);

    if (n <= 0) {
        fprintf(stderr, "Invalid number of points.\n");
        return 1;
    }

    Point *points = malloc(n * sizeof(Point));
    char **metadata = malloc(n * sizeof(char *));
    if (!points || !metadata) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(points);
        free(metadata);
        return 1;
    }

    for (int i = 0; i < n; ++i) {
        printf("Enter coordinates for point %d: ", i + 1);
        scanf("%f %f", &points[i].x, &points[i].y);

        metadata[i] = malloc(256 * sizeof(char));
        if (!metadata[i]) {
            fprintf(stderr, "Memory allocation failed.\n");
            for (int j = 0; j < i; ++j) {
                free(metadata[j]);
            }
            free(points);
            free(metadata);
            return 1;
        }

        printf("Enter metadata for point %d: ", i + 1);
        scanf("%s", metadata[i]);
    }

    for (int i = 0; i < n - 1; ++i) {
        float dist = calculateDistance(points[i], points[i + 1]);
        printf("Distance between point %d and %d: %.2f\n", i + 1, i + 2, dist);
    }

    for (int i = 0; i < n; ++i) {
        free(metadata[i]);
    }
    free(points);
    free(metadata);

    return 0;
