        return NULL; // Memory pool exhausted
    }
    Node* node = &memory_pool[pool_index++];
    node->record.key = key;
    node->record.length = strlen(data);
    strncpy(node->record.data, data, MAX_RECORD_SIZE - 1);
    node->next = NULL;
    return node;
