    Node* current = memory_pool;
    while (current != NULL) {
        if (current->record.key == key) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void print_records() {
    Node* current = memory_pool;
    while (current != NULL) {
        printf("Key: %d, Length: %zu, Data: %s\n", current->record.key, current->record.length, current->record.data);
        current = current->next;
    }
