int initEnvironmentalData(float** temperatures, struct measurement** humidities, time_t** timestamps, int size) {
    srand(time(0));
    *temperatures = new float[size];
    *humidities = new struct measurement[size];
    *timestamps = new time_t[size];

    if (!*temperatures || !*humidities || !*timestamps) {
        delete[] *temperatures;
        delete[] *humidities;
        delete[] *timestamps;
        return -1; // Memory allocation failed
    }

    for (int i = 0; i < size; ++i) {
        (*temperatures)[i] = static_cast<float>(rand()) / RAND_MAX * 40 + 20; // Random temperature between 20 and 60
        (*humidities)[i].humidity = static_cast<double>(rand()) / RAND_MAX * 100; // Random humidity between 0 and 100
        (*timestamps)[i] = time(nullptr); // Current timestamp
    }

    return 0; // Success
}

// Function to free allocated memory
