void* initialize_data(void* arg) {
    DataStruct* data = (DataStruct*)arg;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Allocate memory for arrays
    data->int_keys = (int*)malloc(data->size * sizeof(int));
    data->double_values = (double*)malloc(data->size * sizeof(double));
    data->string_records = (char**)malloc(data->size * sizeof(char*));
    data->status_flags = (bool*)malloc(data->size * sizeof(bool));

    if (!data->int_keys || !data->double_values || !data->string_records || !data->status_flags) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Initialize arrays
