        data->int_keys[i] = rand() % 100; // Example initialization
        data->double_values[i] = ((double)rand()) / RAND_MAX * 100.0;
        data->string_records[i] = (char*)malloc(50 * sizeof(char));
        snprintf(data->string_records[i], 50, "Record %zu", i);
        data->status_flags[i] = rand() % 2 == 0; // Random boolean
    }

    pthread_mutex_unlock(&mutex);
    return NULL;
}

void free_data(DataStruct* data) {
    for (size_t i = 0; i < data->size; ++i) {
        free(data->string_records[i]);
    }
    free(data->int_keys);
    free(data->double_values);
    free(data->string_records);
    free(data->status_flags);
}

