    for (size_t i = 0; i < data.size; ++i) {
        if (data.int_keys[i] > max_int) {
            max_int = data.int_keys[i];
        }
        sum_double += data.double_values[i];
        strcat(concatenated_string, data.string_records[i]);
    }

    printf("Max Integer: %d\n", max_int);
    printf("Average Double: %.2f\n", sum_double / data.size);
    printf("Concatenated String: %s\n", concatenated_string);

    free(concatenated_string);
