using System.Threading.Tasks;

public struct record
{
    public long timestamp;
    public ushort uniqueId;
    public bool statusFlag;
}

public struct node
{
    public record* data;
    public int value;
}

public class NodeManager
{
    private ConcurrentDictionary<int, node> _nodes = new ConcurrentDictionary<int, node>();
    private ILogger _logger;

    public NodeManager(ILogger logger)
    {
        _logger = logger;
    }

    public bool InitializeNodes(string directoryPath, int timeoutMilliseconds)
    {
        if (!File.Exists(Path.Combine(directoryPath, "web.config")) || !File.Exists(Path.Combine(directoryPath, "appsettings.json")))
        {
            _logger.LogError("Missing web.config or appsettings.json file.");
            return false;
        }

        if (!IsValidUrlPath(directoryPath))
        {
            _logger.LogError("Invalid directory path.");
            return false;
        }

        try
        {
            var tasks = new List<Task>();
            for (int i = 0; i < 1000; i++) // Example loop to simulate node creation
            {
                tasks.Add(Task.Run(() => InitializeNode(i, timeoutMilliseconds)));
            }

            Task.WhenAll(tasks).Wait(timeoutMilliseconds);
        }
        catch (TimeoutException)
        {
            _logger.LogError("Initialization timed out.");
            CleanupResources();
            return false;
        }

        return true;
    }

    private bool IsValidUrlPath(string path)
    {
        // Implement URL validation logic here
        return true; // Placeholder
    }

    private void InitializeNode(int nodeId, int timeoutMilliseconds)
    {
        if (!_nodes.TryAdd(nodeId, new node()))
        {
            _logger.LogError($"Failed to add node {nodeId}.");
            return;
        }

        var newNode = _nodes[nodeId];
        newNode.data = (record*)Marshal.AllocHGlobal(Marshal.SizeOf(typeof(record)));
        newNode.value = nodeId;

        try
        {
            // Simulate record initialization logic here
            Marshal.WriteInt64(newNode.data, 0, DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
            Marshal.WriteUInt16(newNode.data, 8, (ushort)nodeId);
            Marshal.WriteByte(newNode.data, 10, 0); // Assuming statusFlag is false

            _logger.LogInfo($"Initialized node {nodeId}.");
        }
        catch
        {
            _logger.LogError($"Failed to initialize node {nodeId}.");
            CleanupResource(nodeId);
        }
    }

    private void CleanupResources()
    {
        foreach (var kvp in _nodes)
        {
            CleanupResource(kvp.Key);
        }
    }

    private void CleanupResource(int nodeId)
    {
        if (_nodes.TryRemove(nodeId, out var node))
        {
            Marshal.FreeHGlobal((IntPtr)node.data);
            _logger.LogInfo($"Cleaned up resource for node {nodeId}.");
        }
    }
}

public interface ILogger
{
    void LogError(string message);
    void LogInfo(string message);
}
