#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a simple record structure
typedef struct {
    int key;
    int value;
} Record;

// Define a hash table entry
typedef struct HashEntry {
    int key;
    Record *record;
    struct HashEntry *next;
} HashEntry;

// Define the hash table
typedef struct {
    int size;
    HashEntry **buckets;
} HashTable;

// Function to initialize the hash table
HashTable* initHashTable(int size) {
    HashTable *ht = (HashTable*)malloc(sizeof(HashTable));
    ht->size = size;
    ht->buckets = (HashEntry**)calloc(size, sizeof(HashEntry*));
    return ht;
}

// Function to insert a record into the hash table
void insertRecord(HashTable *ht, int key, Record *record) {
    int index = key % ht->size;
    HashEntry *entry = (HashEntry*)malloc(sizeof(HashEntry));
    entry->key = key;
    entry->record = record;
    entry->next = ht->buckets[index];
    ht->buckets[index] = entry;
}

// Function to retrieve a record from the hash table
Record* getRecord(HashTable *ht, int key) {
    int index = key % ht->size;
    HashEntry *entry = ht->buckets[index];
    while (entry != NULL) {
        if (entry->key == key) {
            return entry->record;
        }
        entry = entry->next;
    }
    return NULL;
}

// Function to free the hash table
void freeHashTable(HashTable *ht) {
    for (int i = 0; i < ht->size; i++) {
        HashEntry *entry = ht->buckets[i];
        while (entry != NULL) {
            HashEntry *temp = entry;
            entry = entry->next;
            free(temp);
        }
    }
    free(ht->buckets);
    free(ht);
}

// Function to initialize records with random values
void initRecords(HashTable *ht, int upperBound, int seed) {
    srand(seed);
    for (int i = 0; i < ht->size; i++) {
        Record *record = (Record*)malloc(sizeof(Record));
        record->key = i;
        record->value = rand() % upperBound;
        insertRecord(ht, i, record);
    }
}

// Function to log memory allocation and initialization events
void logEvent(const char *message) {
