}

// Function to handle concurrent access using mutexes
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* threadFunction(void *arg) {
    HashTable *ht = (HashTable*)arg;
    pthread_mutex_lock(&lock);
    // Perform operations on the hash table
    Record *record = getRecord(ht, 0);
    if (record != NULL) {
        printf("Value: %d\n", record->value);
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

int main() {
    HashTable *ht = initHashTable(1000);
    loadConfig("config.csv", ht);

    // Example of concurrent access
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, threadFunction, ht);
    }
    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    persistData(ht);
    freeHashTable(ht);

