#define MAX_MEMORY_USAGE 0.60
#define MAX_RECORDS 1500

typedef struct {
    int value;
} Record;

int allocate_memory(long **offsets, int **keys, Record **records, int *num_records) {
    // Get total system memory and calculate the limit for allocation
    size_t total_memory = get_total_system_memory();
    size_t max_allocation_size = (size_t)(total_memory * MAX_MEMORY_USAGE);

    // Allocate memory for offsets array
    *offsets = (long *)malloc(max_allocation_size);
    if (*offsets == NULL) {
        return -1; // Memory allocation failed
    }

    // Initialize offsets with non-zero values
    for (int i = 0; i < max_allocation_size / sizeof(long); i++) {
        (*offsets)[i] = rand() % 100 + 1;
    }

    // Allocate memory for keys array
    *keys = (int *)malloc(max_allocation_size);
    if (*keys == NULL) {
        free(*offsets);
        return -2; // Memory allocation failed
    }

    // Initialize keys with non-zero values
    for (int i = 0; i < max_allocation_size / sizeof(int); i++) {
        (*keys)[i] = rand() % 100 + 1;
    }

    // Get user input for the number of records
    printf("Enter the number of records (max %d): ", MAX_RECORDS);
    scanf("%d", num_records);

    if (*num_records > MAX_RECORDS) {
        *num_records = MAX_RECORDS; // Cap the number of records at the maximum allowed
    }

    // Allocate memory for records array
    *records = (Record *)malloc(*num_records * sizeof(Record));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return -3; // Memory allocation failed
    }

    // Initialize records with unique keys from the keys array
    for (int i = 0; i < *num_records; i++) {
        (*records)[i].value = (*keys)[i];
    }

    return 0; // Success
}

void generate_offsets(long *offsets, int num_records, long limit) {
    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % limit + 1;
    }
}

void deallocate_memory(long *offsets, int *keys, Record *records) {
    free(offsets);
    free(keys);
    free(records);
}

void log_memory_usage(size_t allocated_size, size_t total_memory) {
    printf("Memory Usage: %.2f%%\n", (allocated_size / (float)total_memory) * 100);
}

int main() {
    long *offsets;
    int *keys;
    Record *records;
    int num_records;

    if (allocate_memory(&offsets, &keys, &records, &num_records) != 0) {
        printf("Memory allocation failed.\n");
        return 1;
    }

    generate_offsets(offsets, num_records, 1000);

    log_memory_usage(num_records * sizeof(Record), get_total_system_memory());

    deallocate_memory(offsets, keys, records);

    return 0;
}
