#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_EVENTS 2000
#define MEMORY_LIMIT 60

typedef struct {
    time_t timestamp;
    int event_id;
    char description[100];
} Event;

typedef struct {
    Event events[MAX_EVENTS];
    int count;
    pthread_mutex_t lock;
} EventLog;

EventLog log;

void init_log() {
    pthread_mutex_init(&log.lock, NULL);
    log.count = 0;
}

int add_event(time_t timestamp, int event_id, const char* description) {
    pthread_mutex_lock(&log.lock);
    if (log.count >= MAX_EVENTS || log.count * sizeof(Event) > (MEMORY_LIMIT / 100.0) * sysconf(_SC_PHYS_PAGES) * sysconf(_SC_PAGE_SIZE)) {
        pthread_mutex_unlock(&log.lock);
        return -1; // Memory limit exceeded
    }
    Event new_event = {timestamp, event_id, {0}};
    strncpy(new_event.description, description, sizeof(new_event.description));
    log.events[log.count++] = new_event;
    pthread_mutex_unlock(&log.lock);
    return 0;
}

int get_events_in_range(time_t start, time_t end, Event** events) {
    int count = 0;
    for (int i = 0; i < log.count; i++) {
        if (log.events[i].timestamp >= start && log.events[i].timestamp <= end) {
            events[count++] = &log.events[i];
        }
    }
    return count;
}

void get_summary_statistics(double* avg_description_length, int* event_id_frequency[]) {
    *avg_description_length = 0;
    for (int i = 0; i < log.count; i++) {
        *avg_description_length += strlen(log.events[i].description);
    }
    *avg_description_length /= log.count;

    for (int i = 0; i < MAX_EVENTS; i++) {
        event_id_frequency[i] = 0;
    }
    for (int i = 0; i < log.count; i++) {
        event_id_frequency[log.events[i].event_id]++;
    }
}

void free_log() {
    pthread_mutex_destroy(&log.lock);
}
