MemoryManager* create_memory_manager(size_t max_memory) {
    MemoryManager* manager = (MemoryManager*)malloc(sizeof(MemoryManager));
    if (!manager) return NULL;

    manager->offsets = (long*)malloc(max_memory * sizeof(long));
    manager->keys = (int*)malloc(max_memory * sizeof(int));
    manager->records = (Record*)malloc(max_memory * sizeof(Record));
    manager->num_records = 0;
    manager->total_memory_usage = 0;
    pthread_mutex_init(&manager->mutex, NULL);

    return manager;
}

void destroy_memory_manager(MemoryManager* manager) {
    free(manager->offsets);
    free(manager->keys);
    free(manager->records);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

int initialize_records(MemoryManager* manager, size_t max_records, int key_limit) {
    if (max_records > MAX_RECORDS || key_limit <= 0) return -1;

    for (size_t i = 0; i < max_records; ++i) {
        pthread_mutex_lock(&manager->mutex);
        if (manager->total_memory_usage + sizeof(long) + sizeof(int) > manager->offsets[0] * MAX_MEMORY_USAGE) {
            pthread_mutex_unlock(&manager->mutex);
            break;
        }
        manager->offsets[i] = rand() % manager->offsets[0];
        manager->keys[i] = rand() % key_limit;
        manager->records[i].value = i;
        manager->total_memory_usage += sizeof(long) + sizeof(int);
        pthread_mutex_unlock(&manager->mutex);
    }

    return 0;
}

void* thread_function(void* arg) {
    MemoryManager* manager = (MemoryManager*)arg;
    // Simulate concurrent access and modification of data structures
    return NULL;
}

int main() {
    size_t max_memory = 1024 * 1024; // Example: 1MB
    MemoryManager* manager = create_memory_manager(max_memory);
    if (!manager) {
        fprintf(stderr, "Failed to create memory manager\n");
        return -1;
    }

    int key_limit = 1000;
    if (initialize_records(manager, MAX_RECORDS, key_limit) != 0) {
        fprintf(stderr, "Failed to initialize records\n");
        destroy_memory_manager(manager);
        return -1;
    }

    pthread_t threads[10];
    for (int i = 0; i < 10; ++i) {
        if (pthread_create(&threads[i], NULL, thread_function, manager) != 0) {
            fprintf(stderr, "Failed to create thread %d\n", i);
            destroy_memory_manager(manager);
            return -1;
