        // Example: server_address=192.168.1.1
        if (sscanf(line, "server_address=%s", config->server_address) == 1) {
            continue;
        }
        if (sscanf(line, "port_number=%d", &config->port_number) == 1) {
            continue;
        }
        if (sscanf(line, "logging_level=%d", &config->logging_level) == 1) {
            continue;
        }
        if (sscanf(line, "retry_policy=%d", &config->retry_policy) == 1) {
            continue;
        }
    }

    fclose(file);
    return config;
}

void freeConfig(Config* config) {
    free(config);
