void initializeCollections(int *integerKeys, Record **records, StringKey **stringKeys, int size, int upperBound, const char *prefix) {
    srand(time(NULL));

    // Allocate memory for records and string keys
    records = (Record **)malloc(size * sizeof(Record *));
    stringKeys = (StringKey **)malloc(size * sizeof(StringKey *));
    if (!records || !stringKeys) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize records with random values and generate string keys
    for (int i = 0; i < size; i++) {
        records[i] = (Record *)malloc(sizeof(Record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        records[i]->value = rand() % (upperBound + 1);

        stringKeys[i] = (StringKey *)malloc(sizeof(StringKey));
        if (!stringKeys[i]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        stringKeys[i]->key = (char *)malloc(20 * sizeof(char)); // Assuming prefix + 19 digits
        sprintf(stringKeys[i]->key, "%s%d", prefix, records[i]->value);
    }

    // Find and print the largest integer in the array
    int largestInteger = findLargestInteger(integerKeys, size);
    printf("Largest Integer: %d\n", largestInteger);

    // Free allocated memory
    for (int i = 0; i < size; i++) {
        free(records[i]);
        free(stringKeys[i]->key);
        free(stringKeys[i]);
