    Record* records = (Record*)malloc(num_records * sizeof(Record));
    if (!records) {
        perror("Memory allocation failed");
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < num_records; ++i) {
        records[i].key = rand() % upper_bound + 1;
        records[i].value = rand() % upper_bound + 1;

        snprintf(records[i].unique_id, sizeof(records[i].unique_id), "rec%d", records[i].key);
        snprintf(records[i].prefix_based_id, sizeof(records[i].prefix_based_id), "%s_%d", prefix, records[i].key);

        // Simulate database insertion
        printf("Inserted record with key %d and value %d\n", records[i].key, records[i].value);
    }

    return records;
}

int find_largest_key(Record* records, int num_records) {
    if (num_records == 0) {
        fprintf(stderr, "No records to process\n");
        return -1;
    }

    int largest_key = records[0].key;
    for (int i = 1; i < num_records; ++i) {
        if (records[i].key > largest_key) {
            largest_key = records[i].key;
        }
    }

    printf("Largest key: %d\n", largest_key);
    return largest_key;
}

void free_records(Record* records, int num_records) {
    free(records);
}

int main() {
    int num_records, upper_bound;
    char prefix[256];

    printf("Enter number of records: ");
    scanf("%d", &num_records);

    printf("Enter upper bound for values: ");
