RecordCollection* create_record_collection() {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;
    collection->offsets = (long*)malloc(MAX_RECORDS * sizeof(long));
    collection->keys = (int*)malloc(MAX_RECORDS * sizeof(int));
    collection->count = 0;
    collection->capacity = MAX_RECORDS;
    collection->memory_usage = 0;
    if (!collection->offsets || !collection->keys) {
        free(collection);
        return NULL;
    }
    return collection;
}

void destroy_record_collection(RecordCollection* collection) {
    free(collection->offsets);
    free(collection->keys);
    free(collection);
}

int add_record(RecordCollection* collection, int key, long offset) {
    if (collection->memory_usage + sizeof(int) + sizeof(long) > MEMORY_LIMIT) return -1;
    if (collection->count >= collection->capacity) {
        size_t new_capacity = collection->capacity * 2;
        long* new_offsets = (long*)realloc(collection->offsets, new_capacity * sizeof(long));
        int* new_keys = (int*)realloc(collection->keys, new_capacity * sizeof(int));
        if (!new_offsets || !new_keys) return -1;
        collection->offsets = new_offsets;
        collection->keys = new_keys;
        collection->capacity = new_capacity;
    }
    collection->offsets[collection->count] = offset;
    collection->keys[collection->count] = key;
    collection->memory_usage += sizeof(int) + sizeof(long);
    collection->count++;
    return 0;
}

