int allocate_memory(int size, int* keys, record_int** records_int, record_float** records_float, char*** labels) {
    if (size > MAX_MEMORY_BUDGET / sizeof(int)) {
        fprintf(stderr, "Memory allocation failed: Exceeds maximum budget.\n");
        return -1;
    }

    *keys = (int*)malloc(size * sizeof(int));
    *records_int = (record_int*)malloc(size * sizeof(record_int));
    *records_float = (record_float*)malloc(size * sizeof(record_float));
    *labels = (char**)malloc(size * sizeof(char*));

    if (!(*keys) || !(*records_int) || !(*records_float) || !(*labels)) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(*keys);
        free(*records_int);
        free(*records_float);
        free(*labels);
        return -1;
    }

    for (int i = 0; i < size; i++) {
        (*keys)[i] = rand() % 100; // Example range
        (*records_int)[i].value = rand() % 100; // Example range
        (*records_float)[i].value = round((rand() / (float)RAND_MAX) * 100) / 100; // Rounded to two decimal places
        (*labels)[i] = (char*)malloc(256 * sizeof(char));
        sprintf((*labels)[i], "Label%d", i);
    }

    return 0;
}

void free_memory(int* keys, record_int** records_int, record_float** records_float, char*** labels, int size) {
    for (int i = 0; i < size; i++) {
        free(labels[i]);
    }
    free(keys);
    free(*records_int);
    free(*records_float);
    free(*labels);
}

void find_largest_and_smallest(int* keys, int size, int* largest, int* smallest) {
    *largest = *smallest = keys[0];
    for (int i = 1; i < size; i++) {
        if (keys[i] > *largest) {
            *largest = keys[i];
        }
        if (keys[i] < *smallest) {
            *smallest = keys[i];
        }
    }
}

void find_largest_and_smallest_float(record_float* records_float, int size, float* largest, float* smallest) {
    *largest = *smallest = records_float[0].value;
    for (int i = 1; i < size; i++) {
        if (records_float[i].value > *largest) {
            *largest = records_float[i].value;
        }
        if (records_float[i].value < *smallest) {
            *smallest = records_float[i].value;
        }
    }
}

int main() {
    srand(time(NULL));

    int size;
    printf("Enter the number of elements: ");
    scanf("%d", &size);

    int* keys;
    record_int* records_int;
    record_float* records_float;
    char** labels;

    if (allocate_memory(size, &keys, &records_int, &records_float, &labels) != 0) {
        return -1;
    }

    printf("Enter integers:\n");
    for (int i = 0; i < size; i++) {
        scanf("%d", &keys[i]);
    }

    printf("Enter floats:\n");
    for (int i = 0; i < size; i++) {
        scanf("%f", &records_float[i].value);
    }

    int largest_int, smallest_int;
    find_largest_and_smallest(keys, size, &largest_int, &smallest_int);
    printf("Largest integer: %d\n", largest_int);
    printf("Smallest integer: %d\n", smallest_int);

    float largest_float, smallest_float;
    find_largest_and_smallest_float(records_float, size, &largest_float, &smallest_float);
    printf("Largest float: %.2f\n", largest_float);
    printf("Smallest float: %.2f\n", smallest_float);

    free_memory(keys, &records_int, &records_float, &labels, size);

    return 0;
}
