#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

typedef struct Task {
    char* description;
    int priority;
    long* resource_offsets;
    size_t num_resources;
} Task;

Task* create_task(const char* desc, int prio, const long* offsets, size_t num_offs) {
    Task* task = (Task*)malloc(sizeof(Task));
    if (!task) return NULL;

    task->description = strdup(desc);
    task->priority = prio;
    task->resource_offsets = (long*)malloc(num_offs * sizeof(long));
    if (!task->resource_offsets) {
        free(task->description);
        free(task);
        return NULL;
    }
    memcpy(task->resource_offsets, offsets, num_offs * sizeof(long));
    task->num_resources = num_offs;

    return task;
}

void destroy_task(Task* task) {
    if (task) {
        free(task->description);
        free(task->resource_offsets);
        free(task);
    }
}

json_object* serialize_task(const Task* task) {
    json_object* jobj = json_object_new_object();
    json_object_object_add(jobj, "description", json_object_new_string(task->description));
    json_object_object_add(jobj, "priority", json_object_new_int(task->priority));

    json_object_array* offsets_arr = json_object_new_array();
    for (size_t i = 0; i < task->num_resources; ++i) {
        json_object_array_add(offsets_arr, json_object_new_int64(task->resource_offsets[i]));
    }
    json_object_object_add(jobj, "resource_offsets", offsets_arr);

    return jobj;
}

Task* deserialize_task(const json_object* jobj) {
    const char* desc = json_object_get_string(json_object_object_get_ex((json_object*)jobj, "description", NULL));
    int prio = json_object_get_int(json_object_object_get_ex((json_object*)jobj, "priority", NULL));

    json_object* offsets_arr = json_object_object_get_ex((json_object*)jobj, "resource_offsets", NULL);
    size_t num_offs = json_object_array_length(offsets_arr);
    long* offsets = (long*)malloc(num_offs * sizeof(long));
    for (size_t i = 0; i < num_offs; ++i) {
        offsets[i] = json_object_get_int64(json_object_array_get_idx(offsets_arr, i));
    }

    return create_task(desc, prio, offsets, num_offs);
}

int main() {
    long offsets[] = {12345, 67890};
    Task* task = create_task("Task 1", 5, offsets, 2);
    if (task) {
        json_object* jobj = serialize_task(task);
        if (jobj) {
            printf("%s\n", json_object_to_json_string(jobj));
            json_object_put(jobj);
        }

        Task* deserialized_task = deserialize_task(jobj);
        if (deserialized_task) {
            destroy_task(deserialized_task);
        }

        destroy_task(task);
    }

    return 0;
}
