        int key = generate_unique_key(*keys, i, min_value, max_value);
        if (key == -1) {
            free(*offsets);
            free(*keys);
            free(*records);
            return -3; // Maximum attempts reached
        }
        (*keys)[i] = key;
    }

    for (int i = 0; i < keys_size; i++) {
        (*records)[i] = (record *)malloc(sizeof(record));
        if ((*records)[i] == NULL) {
            free(*offsets);
            free(*keys);
            for (int j = 0; j < i; j++) {
                free((*records)[j]);
            }
            free(*records);
            return -2; // Memory allocation failed
        }
        (*records)[i]->value = rand() % (max_value - min_value + 1) + min_value;
    }

    return 0; // Success
}

void free_memory(int *offsets, int *keys, record **records, int keys_size) {
    free(offsets);
    free(keys);
    for (int i = 0; i < keys_size; i++) {
        free(records[i]);
    }
    free(records);
}

int main() {
    int offsets_size;
    long *offsets;
    int *keys;
    record **records;

    if (initialize_arrays(&offsets_size, &offsets, &keys, &records, 10, 100) == 0) {
        printf("Arrays initialized successfully.\n");
        // Use the arrays here
        free_memory(offsets, keys, records, offsets_size / 2);
    } else {
        printf("Failed to initialize arrays.\n");
    }

