#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define TABLE_SIZE 1024

typedef struct node {
    char* key;
    int priority;
    struct node* next;
} Node;

typedef struct hash_table {
    Node** table;
    size_t size;
    pthread_mutex_t lock;
} HashTable;

HashTable* create_hash_table(size_t size) {
    HashTable* ht = (HashTable*)malloc(sizeof(HashTable));
    if (!ht) return NULL;

    ht->table = (Node**)calloc(size, sizeof(Node*));
    if (!ht->table) {
        free(ht);
        return NULL;
    }

    ht->size = size;
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

void destroy_hash_table(HashTable* ht) {
    for (size_t i = 0; i < ht->size; ++i) {
        Node* node = ht->table[i];
        while (node) {
            Node* next = node->next;
            free(node->key);
            free(node);
            node = next;
        }
    }
    free(ht->table);
    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

size_t hash_function(const char* key, size_t size) {
    size_t hash = 0;
    while (*key) {
        hash = (hash * 31) + *key++;
    }
    return hash % size;
}

void insert(HashTable* ht, const char* key, int priority) {
    pthread_mutex_lock(&ht->lock);
    size_t index = hash_function(key, ht->size);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&ht->lock);
        return;
    }

    new_node->key = strdup(key);
    new_node->priority = priority;
    new_node->next = ht->table[index];
    ht->table[index] = new_node;
    pthread_mutex_unlock(&ht->lock);
}

void remove_key(HashTable* ht, const char* key) {
    pthread_mutex_lock(&ht->lock);
    size_t index = hash_function(key, ht->size);
    Node* node = ht->table[index];
    Node* prev = NULL;

    while (node) {
        if (strcmp(node->key, key) == 0) {
            if (prev) {
                prev->next = node->next;
            } else {
                ht->table[index] = node->next;
            }
            free(node->key);
            free(node);
            break;
        }
        prev = node;
        node = node->next;
    }
    pthread_mutex_unlock(&ht->lock);
}

Node* lookup(HashTable* ht, const char* key) {
    pthread_mutex_lock(&ht->lock);
    size_t index = hash_function(key, ht->size);
    Node* node = ht->table[index];

    while (node) {
        if (strcmp(node->key, key) == 0) {
            pthread_mutex_unlock(&ht->lock);
            return node;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&ht->lock);
    return NULL;
}

int main() {
    HashTable* ht = create_hash_table(TABLE_SIZE);
    if (!ht) {
        fprintf(stderr, "Failed to create hash table\n");
        return 1;
    }

    insert(ht, "key1", 10);
    insert(ht, "key2", 20);

    Node* node = lookup(ht, "key1");
    if (node) {
        printf("Found key1 with priority %d\n", node->priority);
    } else {
        printf("Key1 not found\n");
    }

    remove_key(ht, "key1");

    destroy_hash_table(ht);
    return 0;
}
```

This code provides a basic implementation of a hash table using separate chaining for collision resolution. It includes functions to create and destroy the hash table, insert key-value pairs, remove keys, and look up values. The hash function is simple but effective for demonstration purposes. The use of mutexes ensures thread safety when accessing the hash table concurrently.

Please note that this code does not include dynamic resizing or advanced memory management strategies. For a production environment, you would need to add these features and ensure proper error handling and resource cleanup.']

