// Function to create a new task node
TaskNode* create_task_node(char* name, int priority, long* resource_offsets, void* metadata) {
    TaskNode* new_node = (TaskNode*)malloc(sizeof(TaskNode));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_node->name = strdup(name);
    new_node->priority = priority;
    new_node->resource_offsets = resource_offsets;
    new_node->metadata = metadata;
    new_node->next = NULL;
    return new_node;
}

// Function to add a task to a category
void add_task_to_category(Category* category, TaskNode* task) {
    if (category->head == NULL) {
        category->head = task;
    } else {
        TaskNode* current = category->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = task;
    }
}

// Function to update a task in a category
void update_task_in_category(Category* category, char* name, int new_priority, long* new_resource_offsets, void* new_metadata) {
    TaskNode* current = category->head;
    while (current != NULL) {
        if (strcmp(current->name, name) == 0) {
            free(current->name);
            current->name = strdup(name);
            current->priority = new_priority;
            free(current->resource_offsets);
            current->resource_offsets = new_resource_offsets;
            current->metadata = new_metadata;
            return;
        }
        current = current->next;
    }
}

// Function to remove a task from a category
void remove_task_from_category(Category* category, char* name) {
    TaskNode* current = category->head;
    TaskNode* previous = NULL;
    while (current != NULL) {
        if (strcmp(current->name, name) == 0) {
            if (previous == NULL) {
                category->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current->name);
            free(current->resource_offsets);
            free(current);
            return;
        }
        previous = current;
        current = current->next;
    }
}

// Function to create a new category
Category* create_category(char* name) {
    Category* new_category = (Category*)malloc(sizeof(Category));
    if (new_category == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_category->name = strdup(name);
    new_category->head = NULL;
    new_category->next = NULL;
    return new_category;
}

// Function to add a category
void add_category(Category** categories, Category* new_category) {
    if (*categories == NULL) {
        *categories = new_category;
    } else {
        Category* current = *categories;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_category;
    }
}

// Function to remove a category
void remove_category(Category** categories, char* name) {
    Category* current = *categories;
    Category* previous = NULL;
    while (current != NULL) {
        if (strcmp(current->name, name) == 0) {
            if (previous == NULL) {
                *categories = current->next;
            } else {
                previous->next = current->next;
            }
            free(current->name);
            TaskNode* task = current->head;
            while (task != NULL) {
                TaskNode* next_task = task->next;
                free(task->name);
                free(task->resource_offsets);
                free(task);
                task = next_task;
            }
            free(current);
            return;
        }
        previous = current;
        current = current->next;
    }
}

