#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define structures
typedef struct date {
    int day;
    int month;
    int year;
} Date;

typedef struct teamMember {
    char* name;
    int roleID;
    float hourlyRate;
} TeamMember;

typedef struct project {
    char* name;
    Date dueDate;
    float budget;
    TeamMember** members;
    int memberCount;
} Project;

typedef struct record {
    int value;
} Record;

// Function to allocate memory for a project
Project* createProject(char* name, int memberCount) {
    Project* proj = (Project*)malloc(sizeof(Project));
    if (!proj) return NULL;

    proj->name = strdup(name);
    proj->dueDate.day = 1;
    proj->dueDate.month = rand() % 12 + 1; // Random month
    proj->dueDate.year = rand() % 5 + 2023; // Random year from 2023 to 2027
    proj->budget = (float)(rand() % 10000) / 100.0f; // Random budget between 0 and 100000

    proj->members = (TeamMember**)malloc(memberCount * sizeof(TeamMember*));
    if (!proj->members) {
        free(proj->name);
        free(proj);
        return NULL;
    }

    for (int i = 0; i < memberCount; i++) {
        proj->members[i] = (TeamMember*)malloc(sizeof(TeamMember));
        if (!proj->members[i]) {
            for (int j = 0; j < i; j++) free(proj->members[j]);
            free(proj->name);
            free(proj->members);
            free(proj);
            return NULL;
        }

        proj->members[i]->name = strdup("Member");
        proj->members[i]->roleID = rand() % 10 + 1; // Random role ID
        proj->members[i]->hourlyRate = (float)(rand() % 50) / 10.0f; // Random hourly rate between 0 and 50
    }

    proj->memberCount = memberCount;
    return proj;
}

// Function to free memory allocated for a project
void freeProject(Project* proj) {
    if (proj) {
        free(proj->name);
        for (int i = 0; i < proj->memberCount; i++) {
            free(proj->members[i]->name);
            free(proj->members[i]);
        }
        free(proj->members);
        free(proj);
    }
}

// Function to initialize arrays
void initArrays(long* offsets, int* keys, Record** records, int count, int upperBound) {
    for (int i = 0; i < count; i++) {
        offsets[i] = rand() % (upperBound + 1);
        keys[i] = rand() % (upperBound + 1);

        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) return;
        records[i]->value = rand() % (upperBound + 1);
    }
}

// Function to free memory allocated for arrays
void freeArrays(long* offsets, int* keys, Record** records, int count) {
    for (int i = 0; i < count; i++) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);
}

// Main function to demonstrate memory management and initialization
int main() {
    srand(time(NULL));

    Project* proj1 = createProject("Project A", 3);
    if (!proj1) {
        printf("Failed to allocate memory for project\n");
        return -1;
    }

    long offsets[5];
    int keys[5];
    Record* records[5];
    initArrays(offsets, keys, records, 5, 100);

    // Simulate operations with proj1 and other projects

    freeProject(proj1);
    freeArrays(offsets, keys, records, 5);

    return 0;
}
