["```javascript
const express = require('express');
const axios = require('axios');
const LRU = require('lru-cache');

const app = express();
const port = 3000;

// Configuration for third-party weather APIs
const apiConfigs = [
  { name: 'WeatherAPI1', apiKey: 'key1', url: 'https://api.weatherapi1.com/v1/current.json' },
  { name: 'WeatherAPI2', apiKey: 'key2', url: 'https://api.weatherapi2.com/v1/current.json' }
];

// Cache setup
const cache = new LRU({ max: 500, maxAge: 1000 * 60 * 15 }); // 15 minutes

// Middleware to handle API rate limiting and rotating keys
app.use((req, res, next) => {
  const apiKey = req.headers['x-api-key'];
  if (!apiKey || !apiConfigs.some(config => config.apiKey === apiKey)) {
    return res.status(403).send('Invalid API key');
  }
  // Rotate API keys logic here
  next();
});

// Route to fetch weather data
app.get('/weather', async (req, res) => {
  const { city } = req.query;
  if (!city) return res.status(400).send('City parameter is required');

  const cacheKey = `weather:${city}`;
  const cachedData = cache.get(cacheKey);
  if (cachedData) {
    return res.json(cachedData);
  }

  try {
    let weatherData;
    for (const config of apiConfigs) {
      try {
        const response = await axios.get(config.url, { params: { key: config.apiKey, q: city } });
        weatherData = response.data;
        break; // Use the first successful API response
      } catch (error) {
        console.error(`Failed to fetch weather data from ${config.name}:`, error);
      }
    }

    if (!weatherData) {
      return res.status(503).send('Unable to retrieve weather data');
    }

    cache.set(cacheKey, weatherData);
    res.json(weatherData);
  } catch (error) {
    console.error('Error fetching weather data:', error);
    res.status(500).send('Internal server error');
  }
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).send('Something broke!');
});

app.listen(port, () => {
  console.log(`Weather service listening at http://localhost:${port}`);
});
```

This code provides a basic structure for a scalable Node.js service that integrates with multiple third-party weather APIs. It includes caching, rate limiting, and error handling mechanisms to ensure minimal impact on user experience. The service is designed to be modular and easily extendable."]

