    float floatValue;
} FloatRecord;

typedef struct {
    char* label;
} StringRecord;

typedef struct {
    int intValue;
    float floatValue;
    char* stringValue;
} ComplexRecord;

int allocateMemory(int size, int* intArray, IntRecord** intRecords, FloatRecord** floatRecords, StringRecord** stringRecords, ComplexRecord** complexRecords) {
    // Allocate memory for arrays
    if ((intArray = (int*)malloc(size * sizeof(int))) == NULL) return -1;
    if ((intRecords = (IntRecord**)malloc(size * sizeof(IntRecord*))) == NULL) {
        free(intArray);
        return -1;
    }
    if ((floatRecords = (FloatRecord**)malloc(size * sizeof(FloatRecord*))) == NULL) {
        free(intArray);
        free(intRecords);
        return -1;
    }
    if ((stringRecords = (StringRecord**)malloc(size * sizeof(StringRecord*))) == NULL) {
        free(intArray);
        free(intRecords);
        free(floatRecords);
        return -1;
    }
    if ((complexRecords = (ComplexRecord**)malloc(size * sizeof(ComplexRecord*))) == NULL) {
        free(intArray);
        free(intRecords);
        free(floatRecords);
        free(stringRecords);
        return -1;
    }

    // Initialize records with random values
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        intArray[i] = rand() % 100; // Random integer between 0 and 99
        if ((intRecords[i] = (IntRecord*)malloc(sizeof(IntRecord))) == NULL) return -1;
        intRecords[i]->intValue = intArray[i];

        float floatValue = (float)(rand() % 100) / 10.0f; // Random float between 0 and 9.9
        if ((floatRecords[i] = (FloatRecord*)malloc(sizeof(FloatRecord))) == NULL) return -1;
        floatRecords[i]->floatValue = floatValue;

        if ((stringRecords[i] = (StringRecord*)malloc(20 * sizeof(char))) == NULL) return -1;
        sprintf(stringRecords[i]->label, "Label%d", i);

        if ((complexRecords[i] = (ComplexRecord*)malloc(sizeof(ComplexRecord))) == NULL) return -1;
        complexRecords[i]->intValue = intArray[i];
        complexRecords[i]->floatValue = floatValue;
        if ((complexRecords[i]->stringValue = (char*)malloc(20 * sizeof(char))) == NULL) return -1;
        sprintf(complexRecords[i]->stringValue, "Complex%d", i);
    }

    return 0;
}

void freeMemory(int size, int* intArray, IntRecord** intRecords, FloatRecord** floatRecords, StringRecord** stringRecords, ComplexRecord** complexRecords) {
    for (int i = 0; i < size; i++) {
        free(intRecords[i]);
        free(floatRecords[i]);
        free(stringRecords[i]->label);
        free(stringRecords[i]);
        free(complexRecords[i]->stringValue);
        free(complexRecords[i]);
    }
    free(intArray);
    free(intRecords);
    free(floatRecords);
    free(stringRecords);
    free(complexRecords);
}

int main() {
    int size;
    printf("Enter the number of elements: ");
    scanf("%d", &size);

    if (size > MAX_MEMORY_BUDGET / sizeof(int)) {
        printf("Memory budget exceeded.\n");
        return -1;
    }

    int* intArray = NULL;
    IntRecord** intRecords = NULL;
    FloatRecord** floatRecords = NULL;
    StringRecord** stringRecords = NULL;
    ComplexRecord** complexRecords = NULL;

    if (allocateMemory(size, intArray, intRecords, floatRecords, stringRecords, complexRecords) != 0) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    // Read input and store in arrays
    for (int i = 0; i < size; i++) {
        scanf("%d %f %s", &intArray[i], &floatRecords[i]->floatValue, stringRecords[i]->label);
        complexRecords[i]->intValue = intArray[i];
        complexRecords[i]->floatValue = floatRecords[i]->floatValue;
    }

    // Find and print largest integer and smallest/largest float
    printf("Largest Integer: %d\n", *intArray);
    printf("Smallest Float: %.2f\n", floatRecords[0]->floatValue);
    printf("Largest Float: %.2f\n", floatRecords[size - 1]->floatValue);

    // Free allocated memory
    freeMemory(size, intArray, intRecords, floatRecords, stringRecords, complexRecords);

    return 0;
}
