#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
    struct record *next;
} Record;

Record* create_record(int value) {
    Record *new_record = (Record*)malloc(sizeof(Record));
    if (new_record == NULL) {
        perror("Failed to allocate memory for new record");
        return NULL;
    }
    new_record->value = value;
    new_record->next = NULL;
    return new_record;
}

void free_records(Record *head) {
    Record *current = head;
    while (current != NULL) {
        Record *temp = current;
        current = current->next;
        free(temp);
    }
}

int initialize_data_structures(int upper_bound, int local_file_size, int remote_api_size) {
    srand(time(NULL));

    // Allocate memory for linked list
    Record *head = create_record(rand() % (upper_bound + 1));
    if (head == NULL) {
        return -1;
    }
    Record *current = head;

    // Initialize local file data
    for (int i = 0; i < local_file_size; i++) {
        current->next = create_record(rand() % (upper_bound + 1));
        if (current->next == NULL) {
            free_records(head);
            return -1;
        }
        current = current->next;
    }

    // Initialize remote API data
    for (int i = 0; i < remote_api_size; i++) {
        current->next = create_record(rand() % (upper_bound + 1));
        if (current->next == NULL) {
            free_records(head);
            return -1;
        }
        current = current->next;
    }

    // Merge local and remote data
    Record *local_head = head;
    while (local_head != NULL && local_head->next != NULL) {
        local_head = local_head->next;
    }
    local_head->next = create_record(rand() % (upper_bound + 1));
    if (local_head->next == NULL) {
        free_records(head);
        return -1;
    }

    // Find and print the largest integer
    Record *max_node = head;
    while (current != NULL) {
        if (current->value > max_node->value) {
            max_node = current;
        }
        current = current->next;
    }
    printf("Largest integer: %d\n", max_node->value);

    // Free allocated memory
    free_records(head);

    return 0;
}
