#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
    struct record *next;
} Record;

void initialize_data_structures(int max_size) {
    if (max_size <= 0) {
        fprintf(stderr, "Error: Invalid dataset size.\n");
        return;
    }

    long *offsets = malloc(max_size * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Error: Memory allocation failed for offsets.\n");
        return;
    }

    int *keys = malloc(max_size * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Error: Memory allocation failed for keys.\n");
        free(offsets);
        return;
    }

    Record *head = NULL;
    srand(time(NULL));
    int prev_value = -1;
    for (int i = 0; i < max_size; ++i) {
        int value;
        do {
            value = rand() % 101;
        } while (value == prev_value);
        prev_value = value;

        Record *new_record = malloc(sizeof(Record));
        if (!new_record) {
            fprintf(stderr, "Error: Memory allocation failed for record.\n");
            free(offsets);
            free(keys);
            // Clean up existing records
            Record *current = head;
            while (current) {
                Record *next = current->next;
                free(current);
                current = next;
            }
            return;
        }

        new_record->value = value;
        new_record->next = head;
        head = new_record;
    }

    // Initialize integer list from standard input
    int *int_list = NULL;
    int list_size = 0;
    while (1) {
        int num;
        if (scanf("%d", &num) != 1) break;
        int_list = realloc(int_list, (list_size + 1) * sizeof(int));
        if (!int_list) {
            fprintf(stderr, "Error: Memory allocation failed for integer list.\n");
            // Clean up existing records
            Record *current = head;
            while (current) {
                Record *next = current->next;
                free(current);
                current = next;
            }
            free(offsets);
            free(keys);
            return;
        }
        int_list[list_size++] = num;
    }

    // Find and print the largest integer
    int max_value = int_list[0];
    for (int i = 1; i < list_size; ++i) {
        if (int_list[i] > max_value) {
            max_value = int_list[i];
        }
    }
    printf("Largest integer: %d\n", max_value);

    // Clean up allocated memory
    Record *current = head;
    while (current) {
        Record *next = current->next;
        free(current);
        current = next;
    }
    free(offsets);
    free(keys);
    free(int_list);
}

int main() {
    int max_size;
    printf("Enter the maximum dataset size: ");
    scanf("%d", &max_size);

    initialize_data_structures(max_size);

    return 0;
}
