#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_RECORDS 1000
#define MEMORY_THRESHOLD 500000

typedef struct {
    int *integers;
    float *floats;
    char **strings;
    time_t *dates;
    int *status_flags;
} RecordSet;

RecordSet* create_record_set(int size, int max_memory) {
    if (size > MAX_RECORDS || size * sizeof(RecordSet) > max_memory) {
        fprintf(stderr, "Memory allocation failed: Exceeds threshold or maximum records.\n");
        return NULL;
    }

    RecordSet *record_set = malloc(size * sizeof(RecordSet));
    if (!record_set) {
        fprintf(stderr, "Memory allocation failed: Out of memory.\n");
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        record_set[i].integers = malloc(sizeof(int));
        record_set[i].floats = malloc(sizeof(float));
        record_set[i].strings = malloc(256 * sizeof(char));
        record_set[i].dates = malloc(sizeof(time_t));
        record_set[i].status_flags = malloc(sizeof(int));

        if (!record_set[i].integers || !record_set[i].floats || !record_set[i].strings || !record_set[i].dates || !record_set[i].status_flags) {
            fprintf(stderr, "Memory allocation failed: Out of memory.\n");
            for (int j = 0; j < i; j++) {
                free(record_set[j].integers);
                free(record_set[j].floats);
                free(record_set[j].strings);
                free(record_set[j].dates);
                free(record_set[j].status_flags);
            }
            free(record_set);
            return NULL;
        }

        *record_set[i].integers = rand() % 100; // Random integer between 0 and 99
        *record_set[i].floats = (rand() / (float)RAND_MAX) * 100.0f; // Random float between 0 and 100
        sprintf(record_set[i].strings, "Record %d", i);
        record_set[i].dates = time(NULL);
        *record_set[i].status_flags = rand() % 2; // Random status flag (0 or 1)
    }

    return record_set;
}

void free_record_set(RecordSet *record_set, int size) {
    for (int i = 0; i < size; i++) {
        free(record_set[i].integers);
        free(record_set[i].floats);
        free(record_set[i].strings);
        free(record_set[i].dates);
        free(record_set[i].status_flags);
    }
    free(record_set);
}

int main() {
    srand(time(NULL));
    int size = 10;
    int max_memory = MEMORY_THRESHOLD;

    RecordSet *record_set = create_record_set(size, max_memory);
    if (record_set) {
        printf("Record set created successfully.\n");
        free_record_set(record_set, size);
    }

    return 0;
}
