data_entry* manage_memory(size_t size, int min_index, int max_index) {
    if (size == 0 || min_index > max_index) {
        return NULL; // Invalid input
    }

    double* double_array = malloc(size * sizeof(double));
    char* key_identifiers = malloc(size * sizeof(char));
    data_entry* entries = malloc(size * sizeof(data_entry));

    if (!double_array || !key_identifiers || !entries) {
        free(double_array);
        free(key_identifiers);
        free(entries);
        return NULL; // Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    for (size_t i = 0; i < size; ++i) {
        double_array[i] = (double)i * 1.1; // Example initialization
        key_identifiers[i] = 'A' + (i % 26); // Example initialization
        entries[i].value = double_array[i];
        entries[i].index = rand() % (max_index - min_index + 1) + min_index;
        entries[i].identifier = key_identifiers[i];
    }

    return entries;
}

void free_memory(data_entry* entries, size_t size) {
    if (!entries || size == 0) {
        return; // Invalid input
    }

    free(entries);
