typedef struct Node {
    int value;
    struct Node* next;
    int ref_count;
} Node;

typedef struct NodeList {
    Node** nodes;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} NodeList;

NodeList* create_node_list(size_t initial_capacity) {
    NodeList* list = (NodeList*)malloc(sizeof(NodeList));
    if (!list) return NULL;

    list->nodes = (Node**)calloc(initial_capacity, sizeof(Node*));
    if (!list->nodes) {
        free(list);
        return NULL;
    }

    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_node_list(NodeList* list) {
    for (size_t i = 0; i < list->size; ++i) {
        Node* node = list->nodes[i];
        while (node) {
            Node* next = node->next;
            free(node);
            node = next;
        }
    }

    pthread_mutex_destroy(&list->lock);
    free(list->nodes);
    free(list);
}

Node* create_node(int value, Node* next) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) return NULL;

    node->value = value;
    node->next = next;
    node->ref_count = 0;

    return node;
}

void increment_ref_count(Node* node) {
    pthread_mutex_lock(&node->lock);
    ++node->ref_count;
    pthread_mutex_unlock(&node->lock);
}

void decrement_ref_count(Node* node, NodeList* list) {
    pthread_mutex_lock(&node->lock);
    --node->ref_count;

    if (node->ref_count == 0) {
        Node* next = node->next;
        free(node);
        pthread_mutex_unlock(&list->lock);

        // Log deallocation
        log_deallocation();

        return next;
    }

    pthread_mutex_unlock(&node->lock);
}

void resize_node_list(NodeList* list, size_t new_capacity) {
    Node** new_nodes = (Node**)realloc(list->nodes, new_capacity * sizeof(Node*));
    if (!new_nodes) return;

    list->nodes = new_nodes;
    list->capacity = new_capacity;
}
