#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    double value;
    int id;
    char name[20];
} record;

record** create_records(int count, int min_id, int max_id) {
    record** records = (record**)malloc(count * sizeof(record*));
    if (!records) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    srand(time(NULL));
    for (int i = 0; i < count; ++i) {
        records[i] = (record*)malloc(sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Memory allocation failed for record %d\n", i);
            // Free previously allocated records
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records);
            return NULL;
        }

        printf("Enter double value for record %d: ", i);
        scanf("%lf", &records[i]->value);

        records[i]->id = rand() % (max_id - min_id + 1) + min_id;

        printf("Enter char name for record %d: ", i);
        scanf("%s", records[i]->name);
    }

    return records;
}

void sort_records(record** records, int count) {
    // Simple bubble sort for demonstration purposes
    for (int i = 0; i < count - 1; ++i) {
        for (int j = 0; j < count - i - 1; ++j) {
            if (records[j]->value > records[j + 1]->value) {
                record* temp = records[j];
                records[j] = records[j + 1];
                records[j + 1] = temp;
            }
        }
    }
}

void free_records(record** records, int count) {
    for (int i = 0; i < count; ++i) {
        free(records[i]);
    }
    free(records);
}

int main() {
    int count;
    printf("Enter the number of records: ");
    scanf("%d", &count);

    record** records = create_records(count, 1, 100);
    if (records) {
        sort_records(records, count);

        for (int i = 0; i < count; ++i) {
            printf("Record %d: Value=%.2f, ID=%d, Name=%s\n", i, records[i]->value, records[i]->id, records[i]->name);
        }

        free_records(records, count);
    }

    return 0;
}
