#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>

typedef struct {
    unsigned int counter;
    char* name;
} data_item;

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    ((char*)userp)[0] = '\0';
    strncat((char*)userp, (char*)contents, size * nmemb);
    return size * nmemb;
}

int fetch_data_from_api(char* url, char** data) {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, data);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            return -1;
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
    return 0;
}

void initialize_arrays(double** double_array, unsigned short** ushort_array, data_item** data_items, int count) {
    *double_array = (double*)malloc(count * sizeof(double));
    *ushort_array = (unsigned short*)malloc(count * sizeof(unsigned short));
    *data_items = (data_item*)malloc(count * sizeof(data_item));

    if (*double_array == NULL || *ushort_array == NULL || *data_items == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    for (int i = 0; i < count; i++) {
        (*double_array)[i] = i * 1.1;
        (*ushort_array)[i] = i + 1;

        char url[256];
        snprintf(url, sizeof(url), "http://api.example.com/identifier/%d", i);

        char identifier_name[256];
        if (fetch_data_from_api(url, identifier_name) == 0) {
            (*data_items)[i].counter = i + 1;
            (*data_items)[i].name = strdup(identifier_name);
        } else {
            fprintf(stderr, "Failed to fetch data for identifier %d\n", i);
            exit(1);
        }
    }
}

void free_arrays(double* double_array, unsigned short* ushort_array, data_item* data_items, int count) {
    for (int i = 0; i < count; i++) {
        free(data_items[i].name);
    }

    free(double_array);
    free(ushort_array);
    free(data_items);
}

int main() {
    const int count = 10;
    double* double_array;
    unsigned short* ushort_array;
    data_item* data_items;

    initialize_arrays(&double_array, &ushort_array, &data_items, count);

    // Use the arrays...

    free_arrays(double_array, ushort_array, data_items, count);

    return 0;
}
