    for (int i = 0; i < count; i++) {
        entries[i].id = rand() % (max_id - min_id + 1) + min_id;
        entries[i].value = (double)rand() / RAND_MAX;
        entries[i].key = 'A' + rand() % 26;
        entries[i].validity = STATUS_VALID;
    }

    return entries;
}

void free_memory(void* ptr) {
    free(ptr);
}

