#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define CACHE_LINE_SIZE 64

typedef struct Node {
    int value;
    struct Node* next;
    int ref_count;
} Node;

typedef struct Record {
    int* key;
    char* str;
} Record;

Node* allocate_node(int value) {
    Node* node = (Node*)aligned_alloc(CACHE_LINE_SIZE, sizeof(Node));
    if (!node) return NULL;
    node->value = value;
    node->next = NULL;
    node->ref_count = 0;
    return node;
}

int allocate_keys(int m, int** keys) {
    *keys = (int*)malloc(m * sizeof(int));
    if (!*keys) return -1;
    for (int i = 0; i < m; ++i) {
        (*keys)[i] = rand();
    }
    return 0;
}

Record* allocate_records(int n, int k, int min_val, int max_val) {
    if (n > k) return NULL;
    Record* records = (Record*)malloc(n * sizeof(Record));
    if (!records) return NULL;
    for (int i = 0; i < n; ++i) {
        records[i].key = (int*)malloc(sizeof(int));
        if (!records[i].key) {
            free(records);
            return NULL;
        }
        *records[i].key = rand() % (max_val - min_val + 1) + min_val;
        records[i].str = (char*)malloc(256); // Assuming max string length
        if (!records[i].str) {
            free(records[i].key);
            free(records);
            return NULL;
        }
        strcpy(records[i].str, "default");
    }
    return records;
}

void deallocate_records(int n, Record* records) {
    for (int i = 0; i < n; ++i) {
        free(records[i].key);
        free(records[i].str);
    }
    free(records);
}

void log_event(const char* operation, const char* details) {
    printf("[%s] %s\n", __TIMESTAMP__, details);
}

int main() {
    int n = 10;
    int m = 20;
    int k = 50;
    int min_val = 0;
    int max_val = 100;

    Node* node = allocate_node(42);
    if (!node) {
        fprintf(stderr, "Failed to allocate node\n");
        return 1;
    }

    int* keys;
    if (allocate_keys(m, &keys) != 0) {
        fprintf(stderr, "Failed to allocate keys\n");
        free(node);
        return 1;
    }

    Record* records = allocate_records(n, k, min_val, max_val);
    if (!records) {
        fprintf(stderr, "Failed to allocate records\n");
        free(keys);
        free(node);
        return 1;
    }

    deallocate_records(n, records);
    free(keys);
    free(node);

    log_event("Memory allocation", "All operations completed successfully");

    return 0;
}
