#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define INITIAL_CAPACITY 10
#define RESIZE_THRESHOLD 20
#define MAX_RETRIES 5
#define BASE_DELAY 100 // milliseconds

typedef struct Node {
    int value;
    struct Node* next;
    int ref_count;
} Node;

typedef struct DataPoint {
    time_t timestamp;
    char unit_info[50];
    double temperature;
} DataPoint;

Node** create_node_array(int initial_capacity) {
    Node** array = (Node**)malloc(initial_capacity * sizeof(Node*));
    for (int i = 0; i < initial_capacity; i++) {
        array[i] = NULL;
    }
    return array;
}

void resize_node_array(Node*** array, int* capacity) {
    *capacity *= 2;
    Node** new_array = create_node_array(*capacity);
    for (int i = 0; i < *capacity / 2; i++) {
        if ((*array)[i] != NULL) {
            new_array[i] = (*array)[i];
        }
    }
    free(*array);
    *array = new_array;
}

void increment_ref_count(Node* node) {
    pthread_mutex_lock(&node->mutex);
    node->ref_count++;
    pthread_mutex_unlock(&node->mutex);
}

void decrement_ref_count(Node** array, int index) {
    Node* node = array[index];
    pthread_mutex_lock(&node->mutex);
    if (--node->ref_count == 0) {
        free(node);
        array[index] = NULL;
    }
    pthread_mutex_unlock(&node->mutex);
}

int fetch_temperature_with_retry() {
    for (int retry = 0; retry < MAX_RETRIES; retry++) {
        // Simulate fetching temperature from external API
        if (rand() % 2 == 0) {
            return rand() % 100;
        }
        usleep(BASE_DELAY * (1 << retry));
    }
    return -1; // Fallback value on failure
}

void update_data_point(DataPoint* dp, int new_temperature) {
    pthread_mutex_lock(&dp->mutex);
    dp->temperature = new_temperature;
    dp->timestamp = time(NULL);
    pthread_mutex_unlock(&dp->mutex);
}

int main() {
    Node** node_array = create_node_array(INITIAL_CAPACITY);
    DataPoint data_point;

    // Example usage
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->value = 42;
    new_node->next = NULL;
    new_node->ref_count = 0;
    pthread_mutex_init(&new_node->mutex, NULL);

    increment_ref_count(new_node);
    node_array[0] = new_node;

    int temperature = fetch_temperature_with_retry();
    if (temperature != -1) {
        update_data_point(&data_point, temperature);
    }

    decrement_ref_count(node_array, 0);

    free(new_node);
    pthread_mutex_destroy(&new_node->mutex);
    free(node_array);

    return 0;
}
