#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>

#define MAX_TRANSACTIONS 1000
#define BUFFER_SIZE 1024

typedef struct {
    int id;
    time_t timestamp;
    char account[50];
    double amount;
    char currency[3];
    char status[20];
} Transaction;

typedef struct {
    Transaction *transactions;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} TransactionDataset;

void initTransactionDataset(TransactionDataset *dataset) {
    dataset->transactions = (Transaction *)malloc(MAX_TRANSACTIONS * sizeof(Transaction));
    dataset->count = 0;
    dataset->capacity = MAX_TRANSACTIONS;
    pthread_mutex_init(&dataset->lock, NULL);
}

void addTransaction(TransactionDataset *dataset, Transaction transaction) {
    pthread_mutex_lock(&dataset->lock);
    if (dataset->count >= dataset->capacity) {
        dataset->capacity *= 2;
        dataset->transactions = (Transaction *)realloc(dataset->transactions, dataset->capacity * sizeof(Transaction));
    }
    dataset->transactions[dataset->count++] = transaction;
    pthread_mutex_unlock(&dataset->lock);
}

void freeTransactionDataset(TransactionDataset *dataset) {
    pthread_mutex_lock(&dataset->lock);
    free(dataset->transactions);
    dataset->transactions = NULL;
    dataset->count = 0;
    dataset->capacity = 0;
    pthread_mutex_destroy(&dataset->lock);
}

int processFinancialTransactions(TransactionDataset *dataset, int action) {
    if (action == 1) {
        // Add a new transaction
        Transaction newTransaction = { .id = rand(), .timestamp = time(NULL), .amount = 100.0 };
        addTransaction(dataset, newTransaction);
        return 0;
    } else if (action == 2) {
        // Free all allocated memory
        freeTransactionDataset(dataset);
        return 0;
    }
    return -1;
}

int resolveDNS(const char *hostname, u_char *ipAddress) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        memcpy(ipAddress, &(ipv4->sin_addr), sizeof ipv4->sin_addr);
        break;
    }

    freeaddrinfo(res); // free the linked list
    return 0;
}

int main() {
    TransactionDataset dataset;
    initTransactionDataset(&dataset);

    processFinancialTransactions(&dataset, 1); // Add a new transaction

    u_char ipAddress[BUFFER_SIZE];
    resolveDNS("example.com", ipAddress);
    printf("IP Address: %s\n", inet_ntoa(*(struct in_addr *)ipAddress));

    processFinancialTransactions(&dataset, 2); // Free all allocated memory

    return 0;
}
