#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_RECORDS 1000
#define MAX_ELEMENTS 50
#define MAX_KEY 1000
#define MAX_VALUE 100
#define MAX_THRESHOLD 1024 * 1024 * 1024 // 1GB

typedef struct Element {
    int value;
    struct Element* next;
} Element;

typedef struct Record {
    long offset;
    int key;
    Element* elements;
    int elementCount;
} Record;

Record** records = NULL;
int recordCount = 0;
int allocatedMemory = 0;

void initializeRecords(int size) {
    if (size > MAX_RECORDS || allocatedMemory + size * sizeof(Record*) > MAX_THRESHOLD) {
        fprintf(stderr, "Error: Size exceeds maximum threshold or limit.\n");
        return;
    }
    records = realloc(records, (recordCount + size) * sizeof(Record*));
    for (int i = 0; i < size; i++) {
        records[recordCount + i] = malloc(sizeof(Record));
        records[recordCount + i]->offset = rand();
        records[recordCount + i]->key = rand() % MAX_KEY;
        records[recordCount + i]->elements = NULL;
        records[recordCount + i]->elementCount = 0;
    }
    recordCount += size;
    allocatedMemory += size * sizeof(Record*);
}

void addElement(int index, int value) {
    if (index < 0 || index >= recordCount || records[index]->elementCount >= MAX_ELEMENTS) {
        fprintf(stderr, "Error: Invalid index or element limit exceeded.\n");
        return;
    }
    Element* newElement = malloc(sizeof(Element));
    newElement->value = rand() % (MAX_VALUE + 1);
    newElement->next = records[index]->elements;
    records[index]->elements = newElement;
    records[index]->elementCount++;
}

void removeElement(int index, int value) {
    if (index < 0 || index >= recordCount) {
        fprintf(stderr, "Error: Invalid index.\n");
        return;
    }
    Element* current = records[index]->elements;
    Element* previous = NULL;
    while (current != NULL) {
        if (current->value == value) {
            if (previous == NULL) {
                records[index]->elements = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            records[index]->elementCount--;
            return;
        }
        previous = current;
        current = current->next;
    }
}

int searchKey(int key) {
    for (int i = 0; i < recordCount; i++) {
        if (records[i]->key == key) {
            return i;
        }
    }
    return -1;
}

double calculateAverage(int index) {
    if (index < 0 || index >= recordCount || records[index]->elementCount == 0) {
        fprintf(stderr, "Error: Invalid index or no elements.\n");
        return -1.0;
    }
    Element* current = records[index]->elements;
    int sum = 0;
    while (current != NULL) {
        sum += current->value;
        current = current->next;
    }
    return (double)sum / records[index]->elementCount;
}

void persistRecordsToDatabase() {
    // Code to persist records to a relational database
}

int main() {
    srand(time(NULL));
    initializeRecords(10);
    addElement(0, 50);
    removeElement(0, 50);
    int index = searchKey(42);
    if (index != -1) {
        printf("Record found at index: %d\n", index);
    }
    double average = calculateAverage(0);
    if (average != -1.0) {
        printf("Average value: %.2f\n", average);
    }
    persistRecordsToDatabase();
    return 0;
}
