#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    float amount;
    char description[100];
} Transaction;

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int allocate_memory(size_t size, float **float_array, Transaction **transaction_array, char ***metadata_array) {
    *float_array = (float *)malloc(size * sizeof(float));
    if (*float_array == NULL) {
        log_error("Failed to allocate memory for float array");
        return 0;
    }

    *transaction_array = (Transaction *)malloc(size * sizeof(Transaction));
    if (*transaction_array == NULL) {
        free(*float_array);
        log_error("Failed to allocate memory for transaction array");
        return 0;
    }

    *metadata_array = (char **)malloc(size * sizeof(char *));
    if (*metadata_array == NULL) {
        free(*float_array);
        free(*transaction_array);
        log_error("Failed to allocate memory for metadata array");
        return 0;
    }

    for (size_t i = 0; i < size; ++i) {
        (*metadata_array)[i] = (char *)malloc(100 * sizeof(char));
        if ((*metadata_array)[i] == NULL) {
            free(*float_array);
            free(*transaction_array);
            for (size_t j = 0; j < i; ++j) {
                free((*metadata_array)[j]);
            }
            log_error("Failed to allocate memory for metadata string");
            return 0;
        }
    }

    return 1;
}

void initialize_arrays(size_t size, float *float_array, Transaction *transaction_array, char **metadata_array, float upper_bound) {
    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        float_array[i] = ((float)rand() / RAND_MAX) * upper_bound;
        snprintf(transaction_array[i].description, sizeof(transaction_array[i].description), "Transaction %zu", i);
        transaction_array[i].amount = float_array[i];
        snprintf(metadata_array[i], 100, "Metadata for Transaction %zu", i);
    }
}

float calculate_total_sum(float *float_array, size_t size) {
    float total_sum = 0.0f;
    for (size_t i = 0; i < size; ++i) {
        total_sum += float_array[i];
    }
    return total_sum;
}

void free_memory(size_t size, float *float_array, Transaction *transaction_array, char **metadata_array) {
    for (size_t i = 0; i < size; ++i) {
        free(metadata_array[i]);
    }
    free(float_array);
    free(transaction_array);
    free(metadata_array);
}

int main() {
    size_t size;
    float upper_bound;

