        (*timestamps)[i].unix_time = time(NULL);
        (*timestamps)[i].timezone_offset = rand() % 24 * 60 * 60; // Random timezone offset
    }

    return temperatures;
}

void calculate_moving_average(float* temperatures, Timestamp* timestamps, int size) {
    if (size <= 1) {
        fprintf(stderr, "Not enough data to calculate moving average\n");
        return;
    }

    float sum = 0.0f;
    for (int i = 0; i < size; ++i) {
        sum += temperatures[i];
    }
    printf("Initial moving average: %f\n", sum / size);

    // Simulate rolling window calculation
    for (int i = 1; i < size; ++i) {
        sum -= temperatures[i - 1];
        sum += temperatures[i];
        printf("Moving average at index %d: %f\n", i, sum / size);
    }
}

