        perror("Failed to allocate memory for temperature readings or timestamps");
        free(data);
        return NULL;
    }
    data->count = 0;
    return data;
}

void free_temperature_data(TemperatureData *data) {
    if (data) {
        free(data->temperatures);
        free(data->timestamps);
        free(data);
    }
}

int read_integer_from_stdin() {
    int value;
    printf("Enter an integer: ");
    if (scanf("%d", &value) != 1) {
        printf("Invalid input. Please enter a valid integer.\n");
        return -1;
    }
    return value;
}

void process_temperature_data(TemperatureData *data, double temperature, time_t timestamp) {
    if (data->count >= MAX_READINGS) {
        printf("Maximum number of readings reached. Cannot add more data.\n");
        return;
    }
    data->temperatures[data->count] = temperature;
    data->timestamps[data->count] = timestamp;
    data->offsets[data->count] = data->count % 10; // Example offset calculation
    data->count++;
}

double compute_rolling_average(TemperatureData *data, int window_size) {
    if (window_size <= 0 || window_size > data->count) {
        printf("Invalid window size. Please enter a valid window size.\n");
        return -1;
    }
    double sum = 0;
    for (int i = data->count - window_size; i < data->count; i++) {
        sum += data->temperatures[i];
    }
    return sum / window_size;
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int main() {
    TemperatureData *data = allocate_temperature_data();
    if (!data) {
        return 1;
    }

