    while (1) {
        printf("1. Add temperature reading\n");
        printf("2. Compute rolling average\n");
        printf("3. Exit\n");
        choice = read_integer_from_stdin();
        if (choice == -1) continue;

        switch (choice) {
            case 1: {
                double temperature;
                time_t timestamp = time(NULL);
                printf("Enter temperature reading: ");
                if (scanf("%lf", &temperature) != 1) {
                    log_error("Invalid input. Please enter a valid temperature.");
                    break;
                }
                process_temperature_data(data, temperature, timestamp);
                break;
            }
            case 2: {
