                if (window_size == -1) continue;
                double average = compute_rolling_average(data, window_size);
                if (average != -1) {
                    printf("Rolling average over last %d readings: %.2f\n", window_size, average);
                }
                break;
            }
            case 3:
                free_temperature_data(data);
                return 0;
            default:
                log_error("Invalid choice. Please enter a valid option.");
        }
    }

    return 0;
}
