#include <pthread.h>

typedef struct {
    int value;
    time_t timestamp;
} Record;

typedef struct Node {
    Record data;
    struct Node* next;
} Node;

int allocate_memory(long** offsets, int** keys, Node** records, time_t** timestamps, int size, int upper_bound) {
    pthread_mutex_lock(&mutex);

    *offsets = (long*)malloc(size * sizeof(long));
    *keys = (int*)malloc(size * sizeof(int));
    *records = (Node*)malloc(size * sizeof(Node));
    *timestamps = (time_t*)malloc(size * sizeof(time_t));

    if (*offsets == NULL || *keys == NULL || *records == NULL || *timestamps == NULL) {
        free(*offsets);
        free(*keys);
        free(*records);
        free(*timestamps);
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    srand(time(NULL));
    int failed_records = 0;

    for (int i = 0; i < size; i++) {
        (*offsets)[i] = rand() % upper_bound;
        (*keys)[i] = rand() % upper_bound;
        (*timestamps)[i] = time(NULL);

        Node* new_node = (Node*)malloc(sizeof(Node));
        if (new_node == NULL) {
            failed_records++;
            continue;
        }

        new_node->data.value = (*keys)[i];
        new_node->data.timestamp = (*timestamps)[i];
        new_node->next = *records;
        *records = new_node;
    }

    pthread_mutex_unlock(&mutex);
    printf("Failed records: %d\n", failed_records);
    return 0;
}

void free_memory(long* offsets, int* keys, Node** records, time_t* timestamps) {
    pthread_mutex_lock(&mutex);

    Node* current = *records;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }

    free(offsets);
    free(keys);
    free(timestamps);

    pthread_mutex_unlock(&mutex);
}

int main() {
    long* offsets;
    int* keys;
    Node* records = NULL;
    time_t* timestamps;

    if (allocate_memory(&offsets, &keys, &records, &timestamps, 1000, 100) != 0) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    // Use the allocated memory for further processing

    free_memory(offsets, keys, &records, timestamps);

    return 0;
}
