    offsets = (int*)malloc(num_records * sizeof(int));
    keys = (int*)malloc(num_records * sizeof(int));

    if (!offsets || !keys) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Initialize records array with random values within a specified range
    records = (record*)calloc(num_records, sizeof(record));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 1000 + 1; // Random value between 1 and 1000
    }

    // Find the largest integer among keys
    max_value = find_largest_integer(keys, num_records);

    // Free allocated memory
    free(offsets);
    free(keys);
