#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Data {
    int value;
} Data;

typedef struct Entry {
    Data* data;
    int key;
    int ref_count;
    struct Entry* next;
} Entry;

typedef struct List {
    Entry* head;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_entry(Entry* entry) {
    free(entry->data);
    free(entry);
}

void destroy_list(List* list) {
    Entry* current = list->head;
    while (current != NULL) {
        Entry* next = current->next;
        destroy_entry(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

Entry* create_entry(int key, int value) {
    Entry* entry = (Entry*)malloc(sizeof(Entry));
    entry->data = (Data*)malloc(sizeof(Data));
    entry->data->value = value;
    entry->key = key;
    entry->ref_count = 0;
    entry->next = NULL;
    return entry;
}

void add_entry(List* list, int key, int value) {
    pthread_mutex_lock(&list->lock);
    Entry* new_entry = create_entry(key, value);
    new_entry->next = list->head;
    list->head = new_entry;
    pthread_mutex_unlock(&list->lock);
}

void remove_entry(List* list, int key) {
    pthread_mutex_lock(&list->lock);
    Entry* current = list->head;
    Entry* prev = NULL;
    while (current != NULL) {
        if (current->key == key && current->ref_count == 0) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            destroy_entry(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void increment_ref_count(List* list, int key) {
    pthread_mutex_lock(&list->lock);
    Entry* current = list->head;
    while (current != NULL) {
        if (current->key == key) {
            current->ref_count++;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void decrement_ref_count(List* list, int key) {
    pthread_mutex_lock(&list->lock);
    Entry* current = list->head;
    while (current != NULL) {
        if (current->key == key) {
            current->ref_count--;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void print_list(List* list) {
    pthread_mutex_lock(&list->lock);
    Entry* current = list->head;
    while (current != NULL) {
        printf("Key: %d, Data Value: %d\n", current->key, current->data->value);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}
