    }
    calculator->sum = 0.0;
    calculator->window_size = window_size;
    calculator->current_index = 0;

    return calculator;
}

int calculate_moving_average(TemperatureData *data, MovingAverageCalculator *calculator) {
    if (data->count == 0 || calculator->window_size <= 0) {
        return -1; // Invalid input
    }

    for (int i = 0; i < data->count; i++) {
        calculator->sum += data->readings[i].temperature;
        if (i >= calculator->window_size) {
            calculator->sum -= data->readings[i - calculator->window_size].temperature;
        }
        calculator->current_index = (calculator->current_index + 1) % calculator->window_size;
    }

    return 0; // Success
}

void free_temperature_data(TemperatureData *data) {
    if (data) {
        free(data->readings);
        free(data);
    }
}

void free_moving_average_calculator(MovingAverageCalculator *calculator) {
    if (calculator) {
        free(calculator);
    }
}
