void manage_memory(int initial_size, long** offsets, int** keys, record** records) {
    if (initial_size <= 0) {
        fprintf(stderr, "Initial size must be positive.\n");
        return;
    }

    *offsets = (long*)malloc(initial_size * sizeof(long));
    *keys = (int*)malloc(initial_size * sizeof(int));
    *records = (record*)malloc(initial_size * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return;
    }

    srand(time(NULL));

    for (int i = 0; i < initial_size; i++) {
        (*offsets)[i] = i;
        (*keys)[i] = i;

        char buffer[20];
        snprintf(buffer, sizeof(buffer), "Key%dOffset%d", (*keys)[i], (*offsets)[i]);
        (*records)[i].str = (char*)malloc(strlen(buffer) + 1);
        strcpy((*records)[i].str, buffer);

        (*records)[i].value = rand() % 100; // Random number between 0 and 99
    }
}

void free_memory(long* offsets, int* keys, record* records, int size) {
    for (int i = 0; i < size; i++) {
        free(records[i].str);
    }

    free(offsets);
    free(keys);
    free(records);
