    *offsets = (long *)malloc(max_records * sizeof(long));
    *keys = (int *)malloc(max_records * sizeof(int));
    *records = (record *)malloc(max_records * sizeof(record));

    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    srand(time(NULL));

    for (int i = 0; i < max_records; i++) {
        (*offsets)[i] = rand();
        (*keys)[i] = rand() % max_records;

        // Check for duplicate keys
        for (int j = 0; j < i; j++) {
            if ((*keys)[i] == (*keys)[j]) {
                fprintf(stderr, "Duplicate key found: %d\n", (*keys)[i]);
                free(*offsets);
                free(*keys);
                free(*records);
                return -1;
            }
        }

        (*records)[i].value = rand();
        for (int k = 0; k < buffer_length; k++) {
            (*records)[i].buffer[k] = 'a' + rand() % 26;
        }
    }

    printf("Total memory usage: %zu bytes\n", sizeof(long) * max_records + sizeof(int) * max_records + sizeof(record) * max_records);
    return 0;
}

int main() {
    long *offsets;
    int *keys;
    record *records;

    if (allocate_and_initialize_arrays(&offsets, &keys, &records, MAX_RECORDS, BUFFER_LENGTH) == 0) {
        // Use the allocated arrays here
        free(offsets);
        free(keys);
        free(records);
    }

    return 0;
}
