typedef struct Customer {
    char name[100];
    char contactInfo[100];
    int satisfactionRating;
} Customer;

typedef struct Service {
    char serviceName[100];
    Customer** customers;
    int customerCount;
    time_t scheduledTime;
    double cost;
} Service;

Service* createService(char* serviceName, time_t scheduledTime, double cost) {
    Service* service = (Service*)malloc(sizeof(Service));
    if (service == NULL) {
        perror("Failed to allocate memory for service");
        return NULL;
    }
    strcpy(service->serviceName, serviceName);
    service->customers = NULL;
    service->customerCount = 0;
    service->scheduledTime = scheduledTime;
    service->cost = cost;
    return service;
}

void addCustomerToService(Service* service, Customer* customer) {
    service->customerCount++;
    service->customers = (Customer**)realloc(service->customers, service->customerCount * sizeof(Customer*));
    if (service->customers == NULL) {
        perror("Failed to allocate memory for customers");
        return;
    }
    service->customers[service->customerCount - 1] = customer;
}

void fetchCustomerData(Service* service) {
    // Simulate fetching data from an external API
    Customer* customer = (Customer*)malloc(sizeof(Customer));
    if (customer == NULL) {
        perror("Failed to allocate memory for customer");
        return;
    }
    strcpy(customer->name, "John Doe");
    strcpy(customer->contactInfo, "john.doe@example.com");
    customer->satisfactionRating = 4;
    addCustomerToService(service, customer);
}

void synchronizeDataWithCRM(Service* service) {
    // Simulate data synchronization with an external CRM system
    printf("Synchronizing data for %s\n", service->serviceName);
}

void logError(const char* message) {
    // Log error to a file or console
    fprintf(stderr, "ERROR: %s\n", message);
}

void freeService(Service* service) {
    if (service != NULL) {
        for (int i = 0; i < service->customerCount; i++) {
            free(service->customers[i]);
        }
        free(service->customers);
        free(service);
    }
}

int main() {
    pthread_t thread1, thread2;
    Service* service1 = createService("Web Development", time(NULL) + 3600, 500.0);
    Service* service2 = createService("Graphic Design", time(NULL) + 7200, 300.0);

    pthread_create(&thread1, NULL, (void*)fetchCustomerData, (void*)service1);
    pthread_create(&thread2, NULL, (void*)fetchCustomerData, (void*)service2);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    synchronizeDataWithCRM(service1);
    synchronizeDataWithCRM(service2);

    freeService(service1);
    freeService(service2);

    return 0;
}
