typedef struct {
    int value;
    char* str;
} record;

typedef struct {
    int x, y;
} point;

typedef struct {
    int width, height;
} rectangle;

int find_largest(int* arr, int size) {
    if (size <= 0) return -1; // Handle edge case
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    return max;
}

double euclidean_distance(point p1, point p2) {
    return sqrt(pow(p2.x - p1.x, 2) + pow(p2.y - p1.y, 2));
}

int calculate_distances(point* points, int size, double** distances) {
    if (size <= 0 || !distances) return -1; // Handle edge case
    *distances = malloc(size * size * sizeof(double));
    if (!*distances) return -1; // Memory allocation failure
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < size; j++) {
            (*distances)[i * size + j] = euclidean_distance(points[i], points[j]);
        }
    }
    return 0;
}

int main() {
    int n;
    printf("Enter the number of elements: ");
    scanf("%d", &n);

    if (n <= 0) {
        printf("Invalid input. Exiting.\n");
        return -1;
    }

    int* offsets = malloc(n * sizeof(int));
    int* keys = malloc(n * sizeof(int));
    record* records = malloc(n * sizeof(record));
    point* points = malloc(n * sizeof(point));
    rectangle* rectangles = malloc(n * sizeof(rectangle));
    double* distances;

    if (!offsets || !keys || !records || !points || !rectangles) {
        printf("Memory allocation failed. Exiting.\n");
        free(offsets);
        free(keys);
        free(records);
        free(points);
        free(rectangles);
        return -1;
    }

    srand(time(NULL));

    for (int i = 0; i < n; i++) {
        offsets[i] = i;
        keys[i] = i;
        records[i].value = rand() % 100 + 1;
        records[i].str = malloc(20 * sizeof(char));
        sprintf(records[i].str, "Key%dOffset%d", keys[i], offsets[i]);
        points[i].x = rand() % 100;
        points[i].y = rand() % 100;
        rectangles[i].width = rand() % 50 + 1;
        rectangles[i].height = rand() % 50 + 1;
    }

    int largest_offset = find_largest(offsets, n);
    printf("Largest offset: %d\n", largest_offset);

    if (calculate_distances(points, n, &distances) != 0) {
        printf("Failed to calculate distances. Exiting.\n");
        for (int i = 0; i < n; i++) {
            free(records[i].str);
        }
        free(offsets);
        free(keys);
        free(records);
        free(points);
        free(rectangles);
        return -1;
    }

    printf("Distances:\n");
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            printf("%.2f ", distances[i * n + j]);
        }
        printf("\n");
    }

    free(distances);
    for (int i = 0; i < n; i++) {
        free(records[i].str);
    }
    free(offsets);
    free(keys);
    free(records);
    free(points);
    free(rectangles);

    return 0;
}
