#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

#define POOL_SIZE 1024

typedef struct Node {
    int id;
    float value;
    char *timestamp;
    struct Node *next;
} Node;

Node *pool[POOL_SIZE];
int pool_index = 0;

char *generate_timestamp() {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    static char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    return strdup(timestamp);
}

float generate_random_value(float min, float max) {
    return min + (max - min) * ((float)rand() / RAND_MAX);
}

Node* create_node(int id, float value) {
    if (pool_index >= POOL_SIZE) {
        printf("Pool overflow\n");
        exit(1);
    }
    Node *node = pool[pool_index++];
    node->id = id;
    node->value = value;
    node->timestamp = generate_timestamp();
    node->next = NULL;
    return node;
}

void insert_node(Node **head, int position, int id, float value) {
    if (position < 0) {
        printf("Invalid position\n");
        return;
    }
    Node *new_node = create_node(id, value);
    if (*head == NULL || position == 0) {
        new_node->next = *head;
        *head = new_node;
    } else {
        Node *current = *head;
        for (int i = 1; current != NULL && i < position; i++) {
            current = current->next;
        }
        if (current == NULL) {
            printf("Position out of bounds\n");
            return;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
}

void delete_node(Node **head, int position) {
    if (*head == NULL || position < 0) {
        printf("Invalid position\n");
        return;
    }
    Node *current = *head;
    if (position == 0) {
        *head = current->next;
        free(current);
    } else {
        for (int i = 1; current != NULL && i < position; i++) {
            current = current->next;
        }
        if (current == NULL || current->next == NULL) {
            printf("Position out of bounds\n");
            return;
        }
        Node *temp = current->next;
        current->next = temp->next;
        free(temp);
    }
}

void traverse_list(Node *head) {
    Node *current = head;
    while (current != NULL) {
        printf("ID: %d, Value: %.2f, Timestamp: %s\n", current->id, current->value, current->timestamp);
        current = current->next;
    }
}

void free_list(Node **head) {
    Node *current = *head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp->timestamp);
        free(temp);
    }
    *head = NULL;
}
