#define MAX_OFFSETS 100
#define MAX_KEYS 1000

typedef struct {
    long value;
} Offset;

typedef struct {
    int value;
} Key;

typedef struct {
    int value;
} Record;

int is_key_unique(Key *keys, int key_count, int new_key) {
    for (int i = 0; i < key_count; i++) {
        if (keys[i].value == new_key) {
            return 0;
        }
    }
    return 1;
}

Record* manage_memory(int max_offsets, Key **key_list, int *key_count) {
    srand(time(NULL));

    Offset *offsets = (Offset *)malloc(max_offsets * sizeof(Offset));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offsets\n");
        return NULL;
    }

    Key *keys = (Key *)malloc(MAX_KEYS * sizeof(Key));
    if (!keys) {
        free(offsets);
        fprintf(stderr, "Memory allocation failed for keys\n");
        return NULL;
    }
    *key_count = 0;

    Record *records = (Record *)malloc(max_offsets * sizeof(Record));
    if (!records) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Memory allocation failed for records\n");
        return NULL;
    }

    for (int i = 0; i < max_offsets; i++) {
        offsets[i].value = rand() % 101;

        int new_key;
        do {
            new_key = rand() % 1000;
        } while (!is_key_unique(keys, *key_count, new_key));

        keys[*key_count].value = new_key;
        (*key_count)++;
        records[i].value = (new_key * offsets[i].value) % 1000;
    }

    *key_list = keys;
    return records;
}

void free_memory(Record *records, Key *keys, Offset *offsets) {
    free(records);
    free(keys);
    free(offsets);
}
