typedef struct {
    char* buffer;
    size_t size;
} CustomData;

typedef struct {
    long offset;
    int key;
} Record;

CustomData* create_custom_data(size_t num_elements, size_t initial_buffer_size) {
    CustomData* data = (CustomData*)malloc(num_elements * sizeof(CustomData));
    for (size_t i = 0; i < num_elements; ++i) {
        data[i].buffer = (char*)malloc(initial_buffer_size);
        data[i].size = initial_buffer_size;
    }
    return data;
}

void initialize_records(Record* records, size_t num_records, int min_key, int max_key) {
    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        records[i].offset = rand();
        records[i].key = rand() % (max_key - min_key + 1) + min_key;
    }
}

void log_buffer_allocation(size_t size, const char* message) {
    // Implement lazy logging strategy
    printf("Allocated %zu bytes for buffer: %s\n", size, message);
}

int validate_buffer_integrity(const CustomData* data, size_t index, int (*hash_func)(const void*, size_t)) {
    if (data[index].buffer == NULL) return 0;
    return hash_func(data[index].buffer, data[index].size) != -1;
}

void free_custom_data(CustomData* data, size_t num_elements) {
    for (size_t i = 0; i < num_elements; ++i) {
        free(data[i].buffer);
    }
    free(data);
}

int default_hash_func(const void* buffer, size_t size) {
    // Implement a simple hash function
    unsigned int hash = 0;
    for (size_t i = 0; i < size; ++i) {
        hash = hash * 31 + ((unsigned char*)buffer)[i];
    }
    return hash != 0 ? hash : -1;
}

int main() {
    size_t num_elements = 1000;
    size_t initial_buffer_size = 1024;
    CustomData* data = create_custom_data(num_elements, initial_buffer_size);
    Record* records = (Record*)malloc(num_elements * sizeof(Record));
    initialize_records(records, num_elements, 1, 100);

    for (size_t i = 0; i < num_elements; ++i) {
        log_buffer_allocation(data[i].size, "CustomData buffer");
        if (!validate_buffer_integrity(&data[i], i, default_hash_func)) {
            printf("Buffer integrity check failed for index %zu\n", i);
        }
    }

    free_custom_data(data, num_elements);
    free(records);

    return 0;
}
