['```rust
use std::collections::HashMap;
use std::env;
use std::fs::{self, DirBuilder};
use std::hash::{Hash, Hasher};
use std::path::Path;
use std::sync::{Arc, Mutex};

struct Record {
    buffer: Vec<u8>,
    size: usize,
}

impl Record {
    fn new(size: usize) -> Self {
        let mut buffer = vec![0; size];
        rand::thread_rng().fill(&mut buffer);
        Record { buffer, size }
    }

    fn hash(&self) -> u64 {
        let mut hasher = std::collections::hash_map::DefaultHasher::new();
        self.buffer.hash(&mut hasher);
        hasher.finish()
    }
}

struct DirectoryManager {
    records: HashMap<u32, Record>,
    long_offsets: Vec<u64>,
    int_keys: Vec<i32>,
    memory_pool: Arc<Mutex<Vec<Vec<u8>>>>,
}

impl DirectoryManager {
    fn new() -> Self {
        DirectoryManager {
            records: HashMap::new(),
            long_offsets: Vec::new(),
            int_keys: Vec::new(),
            memory_pool: Arc::new(Mutex::new(Vec::new())),
        }
    }

    fn create_directory_with_resource_management(
        &mut self,
        dir_name: &str,
        buffer_size: usize,
        num_records: usize,
    ) {
        let mut memory_pool = self.memory_pool.lock().unwrap();
        if memory_pool.len() < num_records {
            for _ in 0..(num_records - memory_pool.len()) {
                memory_pool.push(vec![0; buffer_size]);
            }
        }

        for i in 0..num_records {
            let record = Record::new(buffer_size);
            self.records.insert(i as u32, record);
            self.long_offsets.push(record.hash());
            self.int_keys.push(rand::random());

            if i % 10 == 0 {
                log::info!("Allocated buffer for record {}", i);
            }
        }

        let dir_path = Path::new(dir_name);
        if !dir_path.exists() {
            DirBuilder::new().create(dir_path).unwrap();
        }

        env::set_var("DIRECTORY_PATH", dir_path.to_str().unwrap());
    }
}
