#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <pthread.h>

#define EARTH_RADIUS 6371.0

typedef struct {
    double latitude;
    double longitude;
    double elevation;
    char name[256];
} Location;

typedef struct Node {
    Location data;
    struct Node *left, *right;
} Node;

Node* createNode(Location data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newNode->data = data;
    newNode->left = newNode->right = NULL;
    return newNode;
}

void insertNode(Node** root, Location data) {
    if (*root == NULL) {
        *root = createNode(data);
        return;
    }

    double distance1 = acos(sin((*root)->data.latitude * M_PI / 180) * sin(data.latitude * M_PI / 180)
                          + cos((*root)->data.latitude * M_PI / 180) * cos(data.latitude * M_PI / 180)
                          * cos((*root)->data.longitude * M_PI / 180 - data.longitude * M_PI / 180)) * EARTH_RADIUS;
    double distance2 = acos(sin(data.latitude * M_PI / 180) * sin((*root)->data.latitude * M_PI / 180)
                          + cos(data.latitude * M_PI / 180) * cos((*root)->data.latitude * M_PI / 180)
                          * cos(data.longitude * M_PI / 180 - (*root)->data.longitude * M_PI / 180)) * EARTH_RADIUS;

    if (distance2 < distance1) {
        insertNode(&(*root)->left, data);
    } else {
        insertNode(&(*root)->right, data);
    }
}

Node* searchNearest(Node* root, Location query, double radius) {
    if (root == NULL) return NULL;

    double distance = acos(sin(root->data.latitude * M_PI / 180) * sin(query.latitude * M_PI / 180)
                          + cos(root->data.latitude * M_PI / 180) * cos(query.latitude * M_PI / 180)
                          * cos(root->data.longitude * M_PI / 180 - query.longitude * M_PI / 180)) * EARTH_RADIUS;

    if (distance <= radius) {
        return root;
    }

    Node* left = searchNearest(root->left, query, radius);
    Node* right = searchNearest(root->right, query, radius);

    if (left != NULL && right != NULL) {
        double distanceLeft = acos(sin(left->data.latitude * M_PI / 180) * sin(query.latitude * M_PI / 180)
                                  + cos(left->data.latitude * M_PI / 180) * cos(query.latitude * M_PI / 180)
                                  * cos(left->data.longitude * M_PI / 180 - query.longitude * M_PI / 180)) * EARTH_RADIUS;
        double distanceRight = acos(sin(right->data.latitude * M_PI / 180) * sin(query.latitude * M_PI / 180)
                                   + cos(right->data.latitude * M_PI / 180) * cos(query.latitude * M_PI / 180)
                                   * cos(right->data.longitude * M_PI / 180 - query.longitude * M_PI / 180)) * EARTH_RADIUS;

        return distanceLeft < distanceRight ? left : right;
    }

    if (left != NULL) return left;
    if (right != NULL) return right;

    return NULL;
}

void freeTree(Node* root) {
    if (root == NULL) return;
    freeTree(root->left);
    freeTree(root->right);
    free(root);
}

int main() {
    Node* root = NULL;
    Location locations[] = {
        {34.0522, -118.2437, 0, "Los Angeles"},
        {40.7128, -74.0060, 0, "New York"},
        {48.8566, 2.3522, 0, "Paris"}
    };

    for (int i = 0; i < sizeof(locations) / sizeof(Location); i++) {
        insertNode(&root, locations[i]);
    }

    Location query = {37.7749, -122.4194, 0, ""}; // San Francisco
    double radius = 5000; // 5 km

    Node* nearest = searchNearest(root, query, radius);
    if (nearest != NULL) {
        printf("Nearest location: %s\n", nearest->data.name);
    } else {
        printf("No location found within the specified radius.\n");
    }

    freeTree(root);

    return 0;
}
