#include <stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 1024
#define GROWTH_FACTOR 2

typedef struct {
    long key;
    int value;
    double extended_value;
} record;

typedef struct {
    record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} record_collection;

record_collection* create_record_collection() {
    record_collection* collection = (record_collection*)malloc(sizeof(record_collection));
    if (!collection) return NULL;

    collection->records = (record*)calloc(INITIAL_CAPACITY, sizeof(record));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->capacity = INITIAL_CAPACITY;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_record_collection(record_collection* collection) {
    pthread_mutex_lock(&collection->lock);
    free(collection->records);
    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

int add_record(record_collection* collection, long key, int value, double extended_value) {
    pthread_mutex_lock(&collection->lock);

    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity * GROWTH_FACTOR;
        record* new_records = (record*)realloc(collection->records, new_capacity * sizeof(record));
        if (!new_records) {
            pthread_mutex_unlock(&collection->lock);
            return -1; // Allocation failed
        }

        collection->records = new_records;
        collection->capacity = new_capacity;
    }

    collection->records[collection->size].key = key;
    collection->records[collection->size].value = value;
    collection->records[collection->size].extended_value = extended_value;
    collection->size++;

    pthread_mutex_unlock(&collection->lock);
    return 0; // Success
}

record* get_record(record_collection* collection, long key) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->size; i++) {
        if (collection->records[i].key == key) {
            record* result = &collection->records[i];
            pthread_mutex_unlock(&collection->lock);
            return result;
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return NULL; // Record not found
}

int remove_record(record_collection* collection, long key) {
    pthread_mutex_lock(&collection->lock);

    for (size_t i = 0; i < collection->size; i++) {
        if (collection->records[i].key == key) {
            for (size_t j = i; j < collection->size - 1; j++) {
                collection->records[j] = collection->records[j + 1];
            }
            collection->size--;
            pthread_mutex_unlock(&collection->lock);
            return 0; // Success
        }
    }

    pthread_mutex_unlock(&collection->lock);
    return -1; // Record not found
}
