#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include "logging_lib.h"
#include "random_gen_lib.h"

#define MAX_RECORDS 1000

typedef struct {
    int key;
    long offset;
    char buffer[256];
    int random_value;
} Record;

Record* records[MAX_RECORDS];
int record_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initialize_records(int count, long min_offset, long max_offset) {
    if (count > MAX_RECORDS) {
        log_error("Too many records requested");
        return;
    }

    for (int i = 0; i < count; i++) {
        Record* record = malloc(sizeof(Record));
        if (!record) {
            log_error("Failed to allocate memory for record");
            continue;
        }
        record->key = i;
        record->offset = min_offset + rand() % (max_offset - min_offset);
        snprintf(record->buffer, sizeof(record->buffer), "Log entry %d", i);
        record->random_value = rand();
        records[i] = record;
        record_count++;
    }
}

void* thread_function(void* arg) {
    int index = *(int*)arg;
    pthread_mutex_lock(&mutex);
    if (index >= 0 && index < record_count) {
        Record* record = records[index];
        log_info("Thread %d accessed record with key %d and offset %ld", pthread_self(), record->key, record->offset);
    } else {
        log_error("Invalid record index");
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void cleanup_records() {
    for (int i = 0; i < record_count; i++) {
        free(records[i]);
    }
    record_count = 0;
    pthread_mutex_destroy(&mutex);
}

int main() {
    if (!init_logging()) {
        log_error("Failed to initialize logging library");
        return EXIT_FAILURE;
    }

    if (!init_random_gen()) {
        log_error("Failed to initialize random number generator library");
        cleanup_logging();
        return EXIT_FAILURE;
    }

    srand(time(NULL));
    initialize_records(10, 1000, 2000);

    pthread_t threads[5];
    int thread_indices[5] = {0, 1, 2, 3, 4};

    for (int i = 0; i < 5; i++) {
        if (pthread_create(&threads[i], NULL, thread_function, &thread_indices[i]) != 0) {
            log_error("Failed to create thread");
            cleanup_records();
            cleanup_logging();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    cleanup_records();
    cleanup_logging();

    return EXIT_SUCCESS;
}
