void initialize_data_structures(int array_size, int key_range, void* (*malloc_func)(size_t)) {
    if (array_size <= 0 || malloc_func == NULL) {
        return;
    }

    long* offset_array = (long*)malloc_func(array_size * sizeof(long));
    int* key_array = (int*)malloc_func(array_size * sizeof(int));
    Record* record_list = (Record*)malloc_func(array_size * sizeof(Record));

    if (offset_array == NULL || key_array == NULL || record_list == NULL) {
        // Handle memory allocation failure
        return;
    }

    srand(time(NULL));
    for (int i = 0; i < array_size; i++) {
        offset_array[i] = rand();
        key_array[i] = rand() % key_range;
        record_list[i].field1 = (short)rand();
        record_list[i].field2 = (unsigned int)rand();
        record_list[i].field3 = (char)rand();
    }

    // Initialize linked list
    Record* head = NULL;
    for (int i = 0; i < array_size; i++) {
        Record* new_record = (Record*)malloc_func(sizeof(Record));
        if (new_record == NULL) {
            // Handle memory allocation failure
            continue;
        }
        *new_record = record_list[i];
        new_record->next = head;
        head = new_record;
    }

    // Traverse and update linked list based on key lookup
    int target_key = rand() % key_range;
    Record* current = head;
    while (current != NULL) {
        if (current->field2 == target_key) {
            current->field3 = 'A'; // Example update
        }
        current = current->next;
    }

    // Free allocated memory in reverse order of allocation
    current = head;
    Record* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    free(record_list);
    free(key_array);
    free(offset_array);
}
