measurement** create_measurements(int num_sensors, int num_readings, float temp_range_min, float temp_range_max, float threshold) {
    measurement** measurements = (measurement**)malloc(num_sensors * sizeof(measurement*));
    if (!measurements) {
        log_error("Failed to allocate memory for measurements");
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < num_sensors; i++) {
        measurements[i] = (measurement*)malloc(num_readings * sizeof(measurement));
        if (!measurements[i]) {
            log_error("Failed to allocate memory for sensor %d", i);
            // Clean up previously allocated memory
            for (int j = 0; j < i; j++) {
                free_measurements(measurements[j], num_readings);
            }
            free(measurements);
            return NULL;
        }

        for (int j = 0; j < num_readings; j++) {
            measurements[i][j].timestamp = get_current_time();
            measurements[i][j].temperature = generate_random_number(temp_range_min, temp_range_max);
            if (measurements[i][j].temperature > threshold) {
                measurements[i][j].log_message = (char*)malloc(100 * sizeof(char));
                sprintf(measurements[i][j].log_message, "Sensor %d reading above threshold: %.2f", i, measurements[i][j].temperature);
            } else {
                measurements[i][j].log_message = NULL;
            }
        }
    }

    return measurements;
}

void free_measurements(measurement* measurements, int num_readings) {
    for (int j = 0; j < num_readings; j++) {
        if (measurements[j].log_message) {
            free(measurements[j].log_message);
        }
    }
    free(measurements);
}

void clean_up_measurements(measurement** measurements, int num_sensors, int num_readings) {
    for (int i = 0; i < num_sensors; i++) {
        free_measurements(measurements[i], num_readings);
    }
    free(measurements);
}
