#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2

typedef struct {
    int key;
    double value;
    char* str;
} record;

typedef struct {
    long* offsets;
    int* keys;
    double* values;
    record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} metadata_manager;

metadata_manager* create_metadata_manager() {
    metadata_manager* manager = (metadata_manager*)malloc(sizeof(metadata_manager));
    if (!manager) return NULL;

    manager->offsets = (long*)malloc(INITIAL_CAPACITY * sizeof(long));
    manager->keys = (int*)malloc(INITIAL_CAPACITY * sizeof(int));
    manager->values = (double*)malloc(INITIAL_CAPACITY * sizeof(double));
    manager->records = (record**)malloc(INITIAL_CAPACITY * sizeof(record*));
    if (!manager->offsets || !manager->keys || !manager->values || !manager->records) {
        free(manager);
        return NULL;
    }

    manager->capacity = INITIAL_CAPACITY;
    manager->size = 0;
    pthread_mutex_init(&manager->mutex, NULL);

    return manager;
}

void destroy_metadata_manager(metadata_manager* manager) {
    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->records[i]->str);
        free(manager->records[i]);
    }
    free(manager->offsets);
    free(manager->keys);
    free(manager->values);
    free(manager->records);
    pthread_mutex_destroy(&manager->mutex);
    free(manager);
}

void resize_metadata_manager(metadata_manager* manager) {
    size_t new_capacity = manager->capacity * GROWTH_FACTOR;
    long* new_offsets = (long*)realloc(manager->offsets, new_capacity * sizeof(long));
    int* new_keys = (int*)realloc(manager->keys, new_capacity * sizeof(int));
    double* new_values = (double*)realloc(manager->values, new_capacity * sizeof(double));
    record** new_records = (record**)realloc(manager->records, new_capacity * sizeof(record*));

    if (!new_offsets || !new_keys || !new_values || !new_records) {
        fprintf(stderr, "Memory reallocation failed\n");
        return;
    }

    manager->offsets = new_offsets;
    manager->keys = new_keys;
    manager->values = new_values;
    manager->records = new_records;
    manager->capacity = new_capacity;
}

void add_record(metadata_manager* manager, int key, double value, const char* str) {
    pthread_mutex_lock(&manager->mutex);
    if (manager->size == manager->capacity) resize_metadata_manager(manager);

    record* rec = (record*)malloc(sizeof(record));
    if (!rec) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    rec->key = key;
    rec->value = value;
    rec->str = strdup(str);
    if (!rec->str) {
        free(rec);
        fprintf(stderr, "String duplication failed\n");
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    manager->offsets[manager->size] = (long)rec;
    manager->keys[manager->size] = key;
    manager->values[manager->size] = value;
    manager->records[manager->size++] = rec;

    pthread_mutex_unlock(&manager->mutex);
}

void* process_records(void* arg) {
    metadata_manager* manager = (metadata_manager*)arg;
    for (size_t i = 0; i < manager->size; ++i) {
        // Perform bulk operations on records
        printf("Processing record with key %d and value %.2f\n", manager->keys[i], manager->values[i]);
    }
    return NULL;
}

int main() {
    metadata_manager* manager = create_metadata_manager();
    if (!manager) return 1;

    add_record(manager, 1, 3.14, "Record 1");
    add_record(manager, 2, 2.71, "Record 2");

    pthread_t thread;
    pthread_create(&thread, NULL, process_records, manager);
    pthread_join(thread, NULL);

    destroy_metadata_manager(manager);
    return 0;
}
