    pthread_mutex_init(&bst->lock, NULL);
    bst->root = NULL;
    return bst;
}

void insert(BST* bst, char* key, int value) {
    pthread_mutex_lock(&bst->lock);
    // Insert logic here
    pthread_mutex_unlock(&bst->lock);
}

Node* search(BST* bst, char* key) {
    pthread_mutex_lock(&bst->lock);
    // Search logic here
    pthread_mutex_unlock(&bst->lock);
    return NULL;
}

void delete_node(Node** node, char* key) {
    pthread_mutex_lock(&(*node)->lock);
    // Delete logic here
    pthread_mutex_unlock(&(*node)->lock);
}

void free_bst(BST* bst) {
    pthread_mutex_lock(&bst->lock);
    // Free BST logic here
