    if (!offsets || !keys || !records) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return -1;
    }

    // Initialize offsets and keys
    srand(time(NULL));
    for (int i = 0; i < n_packets; ++i) {
        offsets[i] = rand() % 1000000L; // Random timestamp within a range
        keys[i] = hash_function("packet_header", 13); // Example header
    }

    // Allocate and initialize records
    for (int i = 0; i < n_packets; ++i) {
        records[i] = (record*)malloc(sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            return -1;
        }
        records[i]->data = (int*)malloc(sizeof(int));
        *records[i]->data = rand() % KEY_RANGE; // Random data within a range
        records[i]->offset = offsets[i];
        records[i]->flag = 'A'; // Example flag
    }

    return 0;
}

void free_network_module(int n_packets, record** records) {
    for (int i = 0; i < n_packets; ++i) {
        if (records[i]) {
            free(records[i]->data);
            free(records[i]);
        }
    }
    free(records);
