#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/rand.h>

#define MAX_ACCOUNT_LENGTH 100

typedef struct {
    int id;
    time_t timestamp;
    char account[MAX_ACCOUNT_LENGTH];
    double amount;
    char currency[3];
    char status[20];
} Transaction;

typedef struct {
    Transaction *transactions;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} TransactionPool;

void initTransactionPool(TransactionPool *pool, size_t initialCapacity) {
    pool->transactions = (Transaction *)malloc(initialCapacity * sizeof(Transaction));
    if (!pool->transactions) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pool->count = 0;
    pool->capacity = initialCapacity;
    pthread_mutex_init(&pool->lock, NULL);
}

void addTransaction(TransactionPool *pool, Transaction transaction) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count == pool->capacity) {
        size_t newCapacity = pool->capacity * 2;
        pool->transactions = (Transaction *)realloc(pool->transactions, newCapacity * sizeof(Transaction));
        if (!pool->transactions) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        pool->capacity = newCapacity;
    }
    pool->transactions[pool->count++] = transaction;
    pthread_mutex_unlock(&pool->lock);
}

void generateRandomAccount(char *account, const char *prefix, const char *suffix) {
    int length = MAX_ACCOUNT_LENGTH - strlen(prefix) - strlen(suffix);
    if (length <= 0) {
        fprintf(stderr, "Invalid account length\n");
        exit(EXIT_FAILURE);
    }
    RAND_bytes((unsigned char *)account + strlen(prefix), length);
    account[strlen(prefix) + length] = '\0';
    strcat(account, suffix);
}

void handleFinancialStream(TransactionPool *pool, const char *prefix, const char *suffix) {
    Transaction transaction;
    // Simulate receiving transactions
    for (int i = 0; i < 100; ++i) {
        transaction.id = i;
        time(&transaction.timestamp);
        generateRandomAccount(transaction.account, prefix, suffix);
        transaction.amount = rand() / (double)RAND_MAX * 1000.0;
        strcpy(transaction.currency, "USD");
        strcpy(transaction.status, "Completed");
        addTransaction(pool, transaction);
    }
}

int main() {
    TransactionPool pool;
    initTransactionPool(&pool, 10);

    handleFinancialStream(&pool, "ACC_", "_XYZ");

    // Clean up
    pthread_mutex_destroy(&pool.lock);
    free(pool.transactions);

    return 0;
}
