#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char* name;
    double latitude;
    double longitude;
    double elevation;
} GeographicLocation;

typedef struct {
    char* prefix;
    size_t max_length;
} EntryConfig;

typedef struct {
    GeographicLocation** locations;
    size_t count;
    pthread_mutex_t lock;
} DynamicGeographicData;

DynamicGeographicData* handleDynamicGeographicData(EntryConfig config, size_t initial_capacity) {
    DynamicGeographicData* data = (DynamicGeographicData*)malloc(sizeof(DynamicGeographicData));
    if (!data) {
        perror("Failed to allocate memory for DynamicGeographicData");
        return NULL;
    }
    data->locations = (GeographicLocation**)calloc(initial_capacity, sizeof(GeographicLocation*));
    if (!data->locations) {
        perror("Failed to allocate memory for locations array");
        free(data);
        return NULL;
    }
    data->count = 0;
    pthread_mutex_init(&data->lock, NULL);
    return data;
}

void addGeographicLocation(DynamicGeographicData* data, const char* name, double latitude, double longitude, double elevation) {
    pthread_mutex_lock(&data->lock);
    if (data->count >= initial_capacity) {
        // Resize the locations array
        GeographicLocation** new_locations = (GeographicLocation**)realloc(data->locations, 2 * initial_capacity * sizeof(GeographicLocation*));
        if (!new_locations) {
            perror("Failed to reallocate memory for locations array");
            pthread_mutex_unlock(&data->lock);
            return;
        }
        data->locations = new_locations;
    }
    GeographicLocation* location = (GeographicLocation*)malloc(sizeof(GeographicLocation));
    if (!location) {
        perror("Failed to allocate memory for GeographicLocation");
        pthread_mutex_unlock(&data->lock);
        return;
    }
    location->name = strdup(name);
    location->latitude = latitude;
    location->longitude = longitude;
    location->elevation = elevation;
    data->locations[data->count++] = location;
    pthread_mutex_unlock(&data->lock);
}

void freeDynamicGeographicData(DynamicGeographicData* data) {
    for (size_t i = 0; i < data->count; ++i) {
        free(data->locations[i]->name);
        free(data->locations[i]);
    }
    free(data->locations);
    pthread_mutex_destroy(&data->lock);
    free(data);
}
