#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* str;
    int value;
} CustomStruct;

int initializeArray(int size, int maxLen) {
    CustomStruct* array = (CustomStruct*)malloc(size * sizeof(CustomStruct));
    if (!array) {
        perror("Memory allocation failed");
        return -1;
    }

    for (int i = 0; i < size; ++i) {
        array[i].str = (char*)malloc(maxLen + 1);
        if (!array[i].str) {
            perror("Memory allocation failed");
            // Clean up previously allocated resources
            for (int j = 0; j < i; ++j) {
                free(array[j].str);
            }
            free(array);
            return -1;
        }

        printf("Enter string and integer for element %d: ", i);
        if (scanf("%s %d", array[i].str, &array[i].value) != 2) {
            fprintf(stderr, "Invalid input\n");
            // Clean up previously allocated resources
            for (int j = 0; j <= i; ++j) {
                free(array[j].str);
            }
            free(array);
            return -1;
        }

        if (strlen(array[i].str) > maxLen) {
            fprintf(stderr, "String too long\n");
            // Clean up previously allocated resources
            for (int j = 0; j <= i; ++j) {
                free(array[j].str);
            }
            free(array);
            return -1;
        }
    }

    int totalLength = 0;
    for (int i = 0; i < size; ++i) {
        totalLength += strlen(array[i].str);
    }

    double averageLength = (double)totalLength / size;
    printf("Average length of strings: %.2f\n", averageLength);

    // Free allocated memory
    for (int i = 0; i < size; ++i) {
        free(array[i].str);
    }
    free(array);

    return 0;
}

int main() {
    int size, maxLen;

    printf("Enter the number of elements: ");
    scanf("%d", &size);

    printf("Enter the maximum length of strings: ");
    scanf("%d", &maxLen);

    if (initializeArray(size, maxLen) != 0) {
        fprintf(stderr, "Failed to initialize array\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
