    // Allocate memory for arrays
    *keys = (int*)malloc(MAX_KEY_LENGTH * sizeof(int));
    if (*keys == NULL) {
        pthread_mutex_unlock(&mutex);
        return -1; // Memory allocation failed
    }

    *records = (record*)malloc(MAX_RECORDS * sizeof(record));
