    }

    pthread_mutex_unlock(&mutex);
    return 0; // Success
}

void free_system(int* keys, record** records, NFAPI_CRC_INDICATION_PDU_T** rf_data) {
    pthread_mutex_lock(&mutex);

    if (keys != NULL) {
        free(keys);
    }
    if (records != NULL) {
        free(*records);
    }
    if (rf_data != NULL) {
        free(*rf_data);
    }

    pthread_mutex_unlock(&mutex);
}

int main() {
