    int* keys;
    record** records;
    NFAPI_CRC_INDICATION_PDU_T** rf_data;

    srand(time(NULL));

    if (initialize_system(offsets, &keys, &records, &rf_data) == 0) {
        printf("System initialized successfully.\n");
        // Perform further operations with the system
        free_system(keys, records, rf_data);
    } else {
        printf("Failed to initialize system.\n");
    }

    return 0;
}
