void manageResourceAllocation(int operation, int requestId, int userId, const char* resourceTypePrefix, const char* resourceTypeSuffix, int requestedQuantity, int allocationStatus) {
    pthread_mutex_lock(&lock);
    if (operation == 1) { // Add request
        if (requestCount < MAX_REQUESTS) {
            requests[requestCount].requestId = requestId;
            requests[requestCount].userId = userId;
            snprintf(requests[requestCount].resourceType, sizeof(requests[requestCount].resourceType), "%s%s", resourceTypePrefix, resourceTypeSuffix);
            requests[requestCount].requestedQuantity = requestedQuantity;
            requests[requestCount].allocationStatus = allocationStatus;
            requestCount++;
        }
    } else if (operation == 2) { // Update request
        for (int i = 0; i < requestCount; i++) {
            if (requests[i].requestId == requestId) {
                snprintf(requests[i].resourceType, sizeof(requests[i].resourceType), "%s%s", resourceTypePrefix, resourceTypeSuffix);
                requests[i].requestedQuantity = requestedQuantity;
                requests[i].allocationStatus = allocationStatus;
                break;
            }
        }
    } else if (operation == 3) { // Free all allocated memory
        requestCount = 0;
    }
    pthread_mutex_unlock(&lock);
}

int main() {
    manageResourceAllocation(1, 1, 101, "TypeA_", "_End", 5, 0);
    manageResourceAllocation(2, 1, 101, "TypeB_", "_End", 3, 1);
