// Define the Node structure
typedef struct Node {
    char* str;
    int value;
    struct Node* prev;
    struct Node* next;
} Node;

// Define the DoublyLinkedList structure
typedef struct DoublyLinkedList {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

// Function to create a new node
Node* create_node(const char* str, int value) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        return NULL; // Handle memory allocation failure
    }
    newNode->str = strdup(str);
    newNode->value = value;
    newNode->prev = NULL;
    newNode->next = NULL;
    return newNode;
}

// Function to insert a node into the sorted list
void insert_node(DoublyLinkedList* list, Node* newNode) {
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL || list->head->value >= newNode->value) {
        newNode->next = list->head;
        if (list->head != NULL) {
            list->head->prev = newNode;
        }
        list->head = newNode;
        if (list->tail == NULL) {
            list->tail = newNode;
        }
    } else {
        Node* current = list->head;
        while (current->next != NULL && current->next->value < newNode->value) {
            current = current->next;
        }
        newNode->prev = current;
        newNode->next = current->next;
        if (current->next != NULL) {
            current->next->prev = newNode;
        } else {
            list->tail = newNode;
        }
        current->next = newNode;
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to delete a node from the list
void delete_node(DoublyLinkedList* list, Node* node) {
    pthread_mutex_lock(&list->lock);
    if (node->prev != NULL) {
        node->prev->next = node->next;
    } else {
        list->head = node->next;
    }
    if (node->next != NULL) {
        node->next->prev = node->prev;
    } else {
        list->tail = node->prev;
    }
    free(node->str);
    free(node);
    pthread_mutex_unlock(&list->lock);
}

// Function to traverse the list and print nodes
void traverse_list(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        printf("String: %s, Value: %d\n", current->str, current->value);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

// Function to batch insert nodes from a CSV file
int batch_insert_from_csv(DoublyLinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        return -1; // Handle file opening failure
    }
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        char* str = strtok(line, ",");
        int value = atoi(strtok(NULL, ","));
        Node* newNode = create_node(str, value);
        if (newNode == NULL) {
            fclose(file);
            return -1; // Handle memory allocation failure
        }
        insert_node(list, newNode);
    }
    fclose(file);
    return 0;
}

// Function to export the list to a JSON file
int export_to_json(DoublyLinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "w");
    if (file == NULL) {
        return -1; // Handle file opening failure
    }
    fprintf(file, "[\n");
    Node* current = list->head;
    while (current != NULL) {
        fprintf(file, "{\"str\":\"%s\",\"value\":%d}", current->str, current->value);
        if (current->next != NULL) {
            fprintf(file, ",\n");
        }
        current = current->next;
    }
    fprintf(file, "\n]\n");
    fclose(file);
    return 0;
}

