#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <curl/curl.h>
#include <sqlite3.h>

#define MAX_URLS 10000
#define MAX_CONCURRENT_DB_CONNECTIONS 5
#define COMPRESSION_LEVEL_DEFAULT 6

typedef struct node {
    char* url;
    int status_code;
    struct node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
sqlite3* db = NULL;

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

int fetch_url_status(char* url, int* status_code) {
    CURL *curl;
    CURLcode res;
    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
        curl_easy_setopt(curl, CURLOPT_TIMEOUT, 5L);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            log_error(curl_easy_strerror(res));
            return -1;
        }
        long http_code = 0;
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
        *status_code = (int)http_code;
        curl_easy_cleanup(curl);
    }
    return 0;
}

void* process_url(void* arg) {
    int index = *(int*)arg;
    char url[256];
    int status_code;

    if(fetch_url_status(url, &status_code) == 0) {
        pthread_mutex_lock(&lock);
        Node* new_node = (Node*)malloc(sizeof(Node));
        if(new_node == NULL) {
            log_error("Memory allocation failed");
            return NULL;
        }
        new_node->url = strdup(url);
        new_node->status_code = status_code;
        new_node->next = head;
        head = new_node;
        pthread_mutex_unlock(&lock);
    }

    free(arg);
    return NULL;
}

void init_db(const char* driver, const char* db_name) {
    char conn_str[256];
    snprintf(conn_str, sizeof(conn_str), "%s:%s", driver, db_name);
    int rc = sqlite3_open_v2(conn_str, &db, SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE, NULL);
    if(rc != SQLITE_OK) {
        log_error(sqlite3_errmsg(db));
        sqlite3_close(db);
        exit(EXIT_FAILURE);
    }
}

void insert_url_status(const char* url, int status_code) {
    pthread_mutex_lock(&lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if(new_node == NULL) {
        log_error("Memory allocation failed");
        return;
    }
    new_node->url = strdup(url);
    new_node->status_code = status_code;
    new_node->next = head;
    head = new_node;
    pthread_mutex_unlock(&lock);

    sqlite3_stmt* stmt;
    const char* sql = "INSERT INTO url_status (url, status_code) VALUES (?, ?)";
    int rc = sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);
    if(rc != SQLITE_OK) {
        log_error(sqlite3_errmsg(db));
        return;
    }
    sqlite3_bind_text(stmt, 1, url, -1, SQLITE_STATIC);
    sqlite3_bind_int(stmt, 2, status_code);
    rc = sqlite3_step(stmt);
    if(rc != SQLITE_DONE) {
        log_error(sqlite3_errmsg(db));
    }
    sqlite3_finalize(stmt);
}

int main(int argc, char* argv[]) {
    // Initialize database
    init_db("sqlite3", "url_status.db");

    // Create table for URL and status code pairs
    const char* create_table_sql = "CREATE TABLE IF NOT EXISTS url_status (id INTEGER PRIMARY KEY AUTOINCREMENT, url TEXT UNIQUE, status_code INTEGER)";
    sqlite3_stmt* stmt;
    int rc = sqlite3_prepare_v2(db, create_table_sql, -1, &stmt, NULL);
    if(rc != SQLITE_OK) {
        log_error(sqlite3_errmsg(db));
        return EXIT_FAILURE;
    }
    sqlite3_step(stmt);
    sqlite3_finalize(stmt);

    // Process URLs concurrently
    pthread_t threads[MAX_URLS];
    int indices[MAX_URLS];

    for(int i = 0; i < MAX_URLS; i++) {
        indices[i] = i;
        rc = pthread_create(&threads[i], NULL, process_url, &indices[i]);
        if(rc != 0) {
            log_error("Failed to create thread");
            return EXIT_FAILURE;
        }
    }

    for(int i = 0; i < MAX_URLS; i++) {
        pthread_join(threads[i], NULL);
    }

    // Insert URL and status code pairs into database
    Node* current = head;
    while(current != NULL) {
        insert_url_status(current->url, current->status_code);
        free(current->url);
        Node* temp = current;
        current = current->next;
        free(temp);
    }

    sqlite3_close(db);

    return EXIT_SUCCESS;
}
