    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} EventQueue;

void init_event_queue(EventQueue *queue, size_t initial_capacity) {
    queue->capacity = initial_capacity;
    queue->size = 0;
    queue->events = (NetworkEvent *)malloc(initial_capacity * sizeof(NetworkEvent));
    pthread_mutex_init(&queue->lock, NULL);
}

void enqueue_event(EventQueue *queue, NetworkEvent event) {
    pthread_mutex_lock(&queue->lock);
    if (queue->size >= queue->capacity) {
        queue->capacity *= 2;
        queue->events = (NetworkEvent *)realloc(queue->events, queue->capacity * sizeof(NetworkEvent));
    }
    memcpy(&queue->events[queue->size], &event, sizeof(NetworkEvent));
    queue->size++;
    pthread_mutex_unlock(&queue->lock);
}

void free_event_queue(EventQueue *queue) {
    pthread_mutex_lock(&queue->lock);
    free(queue->events);
    pthread_mutex_destroy(&queue->lock);
}

