        locations[i].longitude = rand() / (double)RAND_MAX;
        locations[i].elevation = rand() % 10000;
        snprintf(locations[i].name, sizeof(locations[i].name), "Location%d", i);
    }

    // Initialize records with random data
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 1000000;
    }

    // Free allocated memory
    free(locations);
    free(records);
}

