// Function to read a list of integers from standard input
int* read_integers(int* num_elements) {
    int* array = NULL;
    char line[256];
    if (fgets(line, sizeof(line), stdin)) {
        *num_elements = 0;
        char* token = strtok(line, " ");
        while (token != NULL) {
            (*num_elements)++;
            array = realloc(array, *num_elements * sizeof(int));
            array[*num_elements - 1] = atoi(token);
            token = strtok(NULL, " ");
        }
    }
    return array;
}

