// Function to allocate and initialize structures
void* allocate_and_initialize(int n, int min_val, int max_val) {
    if (n == 0) return NULL; // Handle zero gracefully

    long *offsets = malloc(n * sizeof(long));
    if (!offsets) return NULL;

    int *keys = malloc(n * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    record *records = malloc(offsets[0] * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
    }

