        printf("Enter key %d: ", i);
        scanf("%d", &keys[i]);
        if (!validate_key(keys[i])) {
            fprintf(stderr, "Invalid key value\n");
            free(offsets);
            free(keys);
            free(records);
            return NULL;
        }
    }

