    scanf("%d", size);

    // Allocate memory for keys and records
    *keys = (int *)malloc(*size * sizeof(int));
    *records = (record *)malloc(*size * sizeof(record));

    if (*keys == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(*keys);
        free(*records);
        return -1;
    }

    // Initialize records with timestamp
    for (int i = 0; i < *size; i++) {
        scanf("%d", &(*keys)[i]);
        (*records)[i].value = (*keys)[i];
        (*records)[i].timestamp = time(NULL);
    }

    return 0;
}

void findAndPrintLargest(int *keys, int size) {
    int largest = keys[0];
    for (int i = 1; i < size; i++) {
        if (keys[i] > largest) {
            largest = keys[i];
        }
    }
    printf("Largest number: %d\n", largest);
}

int main() {
    int *keys;
    record *records;
    int size;

    if (initializeData(&keys, &records, &size) == 0) {
        findAndPrintLargest(keys, size);

        // Free allocated memory
        free(keys);
        free(records);
    }

    return 0;
}
