#define MAX_KEYS 1000
#define MAX_OFFSETS 10000
#define RECORD_SIZE sizeof(struct Record)

struct Record {
    int* data;
    long offset;
    char flag;
};

int hashFunction(const char* header, int maxKeys) {
    // Custom hashing function implementation
    return abs(header[0] * 31 + header[1] * 7 + header[2]) % maxKeys;
}

void initializeNetworkModule(int n_packets, struct Record** records, int** keys, long** offsets) {
    srand(time(NULL));

    if (*records == NULL || *keys == NULL || *offsets == NULL) {
        *records = (struct Record*)malloc(n_packets * RECORD_SIZE);
        *keys = (int*)malloc(n_packets * sizeof(int));
        *offsets = (long*)malloc(n_packets * sizeof(long));
    }

    for (int i = 0; i < n_packets; i++) {
        (*records)[i].data = (int*)malloc(sizeof(int));
        (*keys)[i] = hashFunction("packet_header", MAX_KEYS);
        (*offsets)[i] = rand() % MAX_OFFSETS;

        // Ensure unique keys and valid offsets
        while ((*keys)[i] >= MAX_KEYS || (*offsets)[i] < 0 || (*offsets)[i] >= MAX_OFFSETS) {
            (*keys)[i] = hashFunction("packet_header", MAX_KEYS);
            (*offsets)[i] = rand() % MAX_OFFSETS;
        }

        // Initialize record data
        *(*records)[i].data = rand() % 1000; // Random value between 0 and 999
        (*records)[i].flag = 'A'; // Example flag
    }
}

void freeNetworkModule(struct Record** records, int** keys, long** offsets) {
    if (*records != NULL) {
        for (int i = 0; i < MAX_KEYS; i++) {
            if ((*records)[i].data != NULL) {
                free((*records)[i].data);
            }
        }
        free(*records);
        *records = NULL;
    }

    if (*keys != NULL) {
        free(*keys);
        *keys = NULL;
    }

    if (*offsets != NULL) {
        free(*offsets);
        *offsets = NULL;
    }
}

int main() {
    struct Record* records = NULL;
    int* keys = NULL;
    long* offsets = NULL;

    initializeNetworkModule(10, &records, &keys, &offsets);

    // Use the initialized data...

    freeNetworkModule(&records, &keys, &offsets);

    return 0;
}
