void initialize_records(int min_key, int max_key) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < MAX_RECORDS; i++) {
        if ((records[i] = malloc(sizeof(record))) == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
