        records[i]->offset = rand();
        records[i]->key = rand() % (max_key - min_key + 1) + min_key;
        records[i]->name = malloc(KEY_LENGTH * sizeof(char));
        if ((records[i]->name = malloc(KEY_LENGTH * sizeof(char))) == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        snprintf(records[i]->name, KEY_LENGTH, "key%d", i);
    }
    record_count = MAX_RECORDS;
    pthread_mutex_unlock(&mutex);
}

void free_records() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < record_count; i++) {
        free(records[i]->name);
        free(records[i]);
    }
    record_count = 0;
    pthread_mutex_unlock(&mutex);
