#define MAX_RECORDS 1000
#define KEY_LENGTH 256

typedef struct {
    char *key;
    int value;
} Record;

Record* allocate_records(int count) {
    Record *records = (Record*)malloc(count * sizeof(Record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return NULL;
    }
    for (int i = 0; i < count; i++) {
        records[i].key = (char*)malloc(KEY_LENGTH);
        if (!records[i].key) {
            perror("Failed to allocate memory for key");
            // Free previously allocated keys
            for (int j = 0; j < i; j++) {
                free(records[j].key);
            }
            free(records);
            return NULL;
        }
    }
    return records;
}

void initialize_records(Record *records, int count) {
    srand(time(NULL));
    for (int i = 0; i < count; i++) {
        snprintf(records[i].key, KEY_LENGTH, "key%d", i);
        records[i].value = rand() % 1000;
    }
}

void load_data_from_file(Record *records, int count, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }
    fread(records, sizeof(Record), count, file);
    fclose(file);
}

void deserialize_records(Record *records, int count, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return;
    }
    for (int i = 0; i < count; i++) {
        fread(&records[i].value, sizeof(int), 1, file);
        records[i].key = (char*)malloc(KEY_LENGTH);
        if (!records[i].key) {
            perror("Failed to allocate memory for key");
            // Free previously allocated keys
            for (int j = 0; j < i; j++) {
                free(records[j].key);
            }
            fclose(file);
            return;
        }
        fread(records[i].key, sizeof(char), KEY_LENGTH, file);
    }
    fclose(file);
}

void free_records(Record *records, int count) {
    for (int i = 0; i < count; i++) {
        free(records[i].key);
    }
    free(records);
}

int main() {
    Record *records = allocate_records(MAX_RECORDS);
    if (!records) {
        return EXIT_FAILURE;
    }

    initialize_records(records, MAX_RECORDS);

    deserialize_records(records, MAX_RECORDS, "data.bin");

    // Perform operations with records...

    free_records(records, MAX_RECORDS);

    return EXIT_SUCCESS;
}
