#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int key;
    struct Node* prev;
    struct Node* next;
} Node;

Node* createNode(int key) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newNode->key = key;
    newNode->prev = NULL;
    newNode->next = NULL;
    return newNode;
}

void insertSorted(Node** head, int key) {
    Node* newNode = createNode(key);
    if (*head == NULL || (*head)->key >= key) {
        newNode->next = *head;
        if (*head != NULL)
            (*head)->prev = newNode;
        *head = newNode;
    } else {
        Node* current = *head;
        while (current->next != NULL && current->next->key < key) {
            current = current->next;
        }
        newNode->next = current->next;
        if (current->next != NULL)
            current->next->prev = newNode;
        current->next = newNode;
        newNode->prev = current;
    }
}

void printList(Node* head) {
    Node* current = head;
    while (current != NULL) {
        printf("%d ", current->key);
        current = current->next;
    }
    printf("\n");
}

int main() {
    Node* head = NULL;

    insertSorted(&head, 5);
    insertSorted(&head, 3);
    insertSorted(&head, 8);
    insertSorted(&head, 1);

    printList(head); // Output: 1 3 5 8

    return 0;
}
