    nodes[index]->elements = (Element**)malloc(MAX_ELEMENTS * sizeof(Element*));
    nodes[index]->key = key;
    pthread_mutex_init(&nodes[index]->lock, NULL);
}

void initialize_operation(int index, Node* node) {
