    operations[index]->node = node;
    time_t now = time(NULL);
    operations[index]->timestamp = now + rand() % 11; // Random delay between 0 and 10 seconds
    pthread_mutex_init(&operations[index]->lock, NULL);
}

void update_node(int index, int new_key) {
    pthread_mutex_lock(&nodes[index]->lock);
    nodes[index]->key = new_key;
    pthread_mutex_unlock(&nodes[index]->lock);
}

