            free(nodes[index]->elements[i]->str);
            free(nodes[index]->elements[i]);
        }
    }
    free(nodes[index]->elements);
    pthread_mutex_unlock(&nodes[index]->lock);
    pthread_mutex_destroy(&nodes[index]->lock);
    free(nodes[index]);
}

