#include <stdlib.h>
#include <string.h>

typedef struct Node {
    int value;
    int ref_count;
    struct Node* next_node;
} Node;

typedef struct Event {
    int timestamp;
    char* identifier;
} Event;

typedef struct Session {
    Node* head_node;
    Event** events;
    int event_count;
    int max_events;
} Session;

Session* create_session(int initial_nodes, int initial_events) {
    Session* session = (Session*)malloc(sizeof(Session));
    if (!session) return NULL;

    session->head_node = NULL;
    session->events = (Event**)malloc(initial_events * sizeof(Event*));
    if (!session->events) {
        free(session);
        return NULL;
    }
    memset(session->events, 0, initial_events * sizeof(Event*));
    session->event_count = 0;
    session->max_events = initial_events;

    // Populate initial nodes
    for (int i = 0; i < initial_nodes; ++i) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (!new_node) {
            free(session->events);
            free(session);
            return NULL;
        }
        new_node->value = i;
        new_node->ref_count = 1;
        new_node->next_node = session->head_node;
        session->head_node = new_node;
    }

    return session;
}

void add_event(Session* session, int timestamp, const char* identifier) {
    if (session->event_count >= session->max_events) {
        // Resize events array
        Event** new_events = (Event**)realloc(session->events, session->max_events * 2 * sizeof(Event*));
        if (!new_events) return;
        session->events = new_events;
        session->max_events *= 2;
    }

    Event* new_event = (Event*)malloc(sizeof(Event));
    if (!new_event) return;

    new_event->timestamp = timestamp;
    new_event->identifier = strdup(identifier);
    if (!new_event->identifier) {
        free(new_event);
        return;
    }

    session->events[session->event_count++] = new_event;
}

void remove_node(Session* session, Node* node) {
    if (node == NULL) return;

    // Decrease ref count of all nodes pointed by this node
    Node* current = session->head_node;
    while (current != NULL) {
        if (current->next_node == node) {
            current->ref_count--;
        }
        current = current->next_node;
    }

    // Remove the node from the list
    Node** prev_ptr = &session->head_node;
    while (*prev_ptr != node) {
        prev_ptr = &(*prev_ptr)->next_node;
    }
    *prev_ptr = node->next_node;

    // Free the node and its identifier
    free(node->identifier);
    free(node);
}

void free_session(Session* session) {
    if (session == NULL) return;

    // Free all nodes
    Node* current = session->head_node;
    while (current != NULL) {
        Node* next = current->next_node;
        free(current->identifier);
        free(current);
        current = next;
    }

    // Free all events
    for (int i = 0; i < session->event_count; ++i) {
        free(session->events[i]->identifier);
        free(session->events[i]);
    }
    free(session->events);

    // Free the session itself
    free(session);
}
