#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct Element {
    char* str;
    int value;
    int ref_count;
    struct Element* next;
} Element;

typedef struct Node {
    int key;
    int ref_count;
    Element* elements;
    pthread_mutex_t lock;
    struct Node* next;
} Node;

typedef struct Operation {
    Node* node;
    time_t timestamp;
    int status_flag;
    pthread_mutex_t lock;
} Operation;

Node* create_node(int key) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->key = key;
    new_node->ref_count = 1;
    new_node->elements = NULL;
    pthread_mutex_init(&new_node->lock, NULL);
    new_node->next = NULL;
    return new_node;
}

Element* create_element(char* str, int value) {
    Element* new_element = (Element*)malloc(sizeof(Element));
    new_element->str = strdup(str);
    new_element->value = value;
    new_element->ref_count = 1;
    new_element->next = NULL;
    return new_element;
}

void add_element_to_node(Node* node, char* str, int value) {
    pthread_mutex_lock(&node->lock);
    Element* new_element = create_element(str, value);
    if (node->elements == NULL) {
        node->elements = new_element;
    } else {
        Element* current = node->elements;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_element;
    }
    pthread_mutex_unlock(&node->lock);
}

void remove_element_from_node(Node* node, char* str) {
    pthread_mutex_lock(&node->lock);
    Element* current = node->elements;
    Element* prev = NULL;
    while (current != NULL) {
        if (strcmp(current->str, str) == 0) {
            if (prev == NULL) {
                node->elements = current->next;
            } else {
                prev->next = current->next;
            }
            free(current->str);
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&node->lock);
}

Operation* create_operation(Node* node) {
    Operation* new_operation = (Operation*)malloc(sizeof(Operation));
    new_operation->node = node;
    new_operation->timestamp = time(NULL) + rand() % 11; // Random delay between 0 and 10 seconds
    new_operation->status_flag = 0;
    pthread_mutex_init(&new_operation->lock, NULL);
    return new_operation;
}

void update_operation_status(Operation* operation, int status) {
    pthread_mutex_lock(&operation->lock);
    operation->status_flag = status;
    pthread_mutex_unlock(&operation->lock);
}

void free_node(Node* node) {
    Element* current_element = node->elements;
    while (current_element != NULL) {
        Element* next_element = current_element->next;
        free(current_element->str);
        free(current_element);
        current_element = next_element;
    }
    pthread_mutex_destroy(&node->lock);
    free(node);
}

void free_operation(Operation* operation) {
    pthread_mutex_destroy(&operation->lock);
    free(operation);
}
