Record records[MAX_RECORDS];
char *identifiers[MAX_RECORDS];
int record_count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void resize_records() {
    if (record_count < THRESHOLD) return;

    pthread_mutex_lock(&lock);
    Record new_records[MAX_RECORDS * 2];
    char *new_identifiers[MAX_RECORDS * 2];

    for (int i = 0; i < record_count; i++) {
        new_records[i] = records[i];
        new_identifiers[i] = identifiers[i];
    }

    free(records);
    free(identifiers);
    records = new_records;
    identifiers = new_identifiers;
    pthread_mutex_unlock(&lock);
}

int add_record(int key, const char *name) {
    if (record_count >= MAX_RECORDS) {
        resize_records();
    }

    pthread_mutex_lock(&lock);
    Record *new_record = &records[record_count];
    new_record->key = key;
    new_record->name = malloc((strlen(name) + 1) * sizeof(char));
    strcpy(new_record->name, name);

    char identifier[NAME_LENGTH + 10];
    snprintf(identifier, sizeof(identifier), "%d_%s", key, name);
    identifiers[record_count] = strdup(identifier);

    record_count++;
    pthread_mutex_unlock(&lock);

    return 0;
}

void free_records() {
    for (int i = 0; i < record_count; i++) {
        free(records[i].name);
        free(identifiers[i]);
    }
    free(records);
    free(identifiers);
}
