#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct item {
    double value;
    char *str;
} item;

typedef struct list_node {
    item data;
    struct list_node *next;
} list_node;

typedef struct dynamic_list {
    list_node *head;
    size_t count;
} dynamic_list;

// Function to create a new item
item* create_item(double value, const char *str) {
    item *new_item = (item *)malloc(sizeof(item));
    if (new_item == NULL) return NULL;
    new_item->value = value;
    new_item->str = strdup(str);
    return new_item;
}

// Function to add an item to the list
void add_item(dynamic_list *list, double value, const char *str) {
    item *new_item = create_item(value, str);
    if (new_item == NULL) return;

    list_node *new_node = (list_node *)malloc(sizeof(list_node));
    if (new_node == NULL) {
        free(new_item->str);
        free(new_item);
        return;
    }
    new_node->data = *new_item;
    new_node->next = list->head;
    list->head = new_node;
    list->count++;
}

// Function to traverse the list
void traverse_list(dynamic_list *list, void (*callback)(item *)) {
    list_node *current = list->head;
    while (current != NULL) {
        callback(current->data);
        current = current->next;
    }
}

// Function to sort the list using stable sorting algorithm
void sort_list(dynamic_list *list) {
    // Implement a stable sorting algorithm here, e.g., merge sort
    // This is a placeholder for the actual sorting logic
}

// Function to free all allocated memory in the list
void free_list(dynamic_list *list) {
    list_node *current = list->head;
    while (current != NULL) {
        list_node *next = current->next;
        free(current->data.str);
        free(current);
        current = next;
    }
    list->head = NULL;
    list->count = 0;
}

// Example callback function for traversal
void print_item(item item) {
    printf("Value: %f, String: %s\n", item.value, item.str);
}
```

