            // Free previously allocated memory
            for (int j = 0; j < i; j++) {
                free(records[j].string);
                free(records[j].metadata);
            }
            free(records);
            return NULL;
        }

        records[i].metadata = (Metadata*)malloc(sizeof(Metadata));
        if (!records[i].metadata) {
            perror("Failed to allocate memory for metadata.");
