            for (int j = 0; j <= i; j++) {
                free(records[j].string);
                free(records[j].metadata);
            }
            free(records);
            return NULL;
        }

        records[i].metadata->timestamp = time(NULL);
        records[i].metadata->reference_count = 1;

        // Initialize string with a random value
        snprintf(records[i].string, MAX_STRING_LENGTH, "Record %d", i + 1);
    }

    return records;
}

void free_records(Record* records, int size) {
