#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 100
#define NAME_LENGTH 50
#define THRESHOLD 80

typedef struct {
    int key;
    char name[NAME_LENGTH];
    unsigned long id;
    unsigned int checksum;
} Record;

Record records[MAX_RECORDS];
unsigned long ids[MAX_RECORDS];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int record_count = 0;

unsigned long calculate_id(int key, const char* name) {
    return (unsigned long)(key * 1000 + hash(name));
}

unsigned int calculate_checksum(unsigned long id) {
    unsigned int sum = 0;
    while (id > 0) {
        sum += id % 256;
        id /= 256;
    }
    return sum;
}

int add_record(int key, const char* name) {
    pthread_mutex_lock(&lock);
    if (record_count >= MAX_RECORDS) {
        pthread_mutex_unlock(&lock);
        return -1; // Record limit reached
    }

    strcpy(records[record_count].name, name);
    records[record_count].key = key;
    records[record_count].id = calculate_id(key, name);
    records[record_count].checksum = calculate_checksum(records[record_count].id);

    ids[record_count] = records[record_count].id;

    record_count++;
    pthread_mutex_unlock(&lock);
    return 0;
}

int get_record(int key, const char* name) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < record_count; i++) {
        if (records[i].key == key && strcmp(records[i].name, name) == 0) {
            unsigned long id = calculate_id(key, name);
            if (id != records[i].id || calculate_checksum(id) != records[i].checksum) {
                pthread_mutex_unlock(&lock);
                return -2; // Corrupted record
            }
            pthread_mutex_unlock(&lock);
            return i;
        }
    }
    pthread_mutex_unlock(&lock);
    return -1; // Record not found
}

void* resize_records(void* arg) {
    int new_size = MAX_RECORDS * 2;
    Record* new_records = (Record*)realloc(records, new_size * sizeof(Record));
    if (new_records == NULL) {
        perror("Failed to resize records");
        return NULL;
    }
    records = new_records;

    unsigned long* new_ids = (unsigned long*)realloc(ids, new_size * sizeof(unsigned long));
    if (new_ids == NULL) {
        perror("Failed to resize ids");
        free(records);
        return NULL;
    }
    ids = new_ids;

    MAX_RECORDS = new_size;
    return NULL;
}

void* worker_thread(void* arg) {
    while (1) {
        // Asynchronously check if resizing is needed
        pthread_mutex_lock(&lock);
        if (record_count > THRESHOLD && record_count < MAX_RECORDS) {
            pthread_t resize_tid;
            pthread_create(&resize_tid, NULL, resize_records, NULL);
            pthread_detach(resize_tid);
        }
        pthread_mutex_unlock(&lock);

        // Perform other background tasks
        sleep(1); // Simulate work
    }
    return NULL;
}

int main() {
    pthread_t worker_tid;
    pthread_create(&worker_tid, NULL, worker_thread, NULL);
    pthread_detach(worker_tid);

    add_record(1, "Alice");
    add_record(2, "Bob");

    int index = get_record(1, "Alice");
    if (index != -1) {
        printf("Record found at index %d\n", index);
    } else {
        printf("Record not found\n");
    }

    return 0;
}
```

This code provides a basic structure for managing a dynamic record system with thread safety and fine-grained locking. It includes functions to add records, retrieve records by key and name, and handle resizing of the record storage asynchronously. The code also demonstrates how to use pthreads for concurrent operations and error handling for memory allocations.']

