#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000
#define UPPER_BOUND 100

typedef struct {
    int key;
    int value;
} Record;

Record* records[MAX_RECORDS];
int record_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* initialize_records(void* arg) {
    int* input_array = (int*)arg;
    int largest_value = find_largest(input_array, record_count);

    for (int i = 0; i < record_count; i++) {
        pthread_mutex_lock(&mutex);
        records[i] = (Record*)malloc(sizeof(Record));
        if (!records[i]) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }
        records[i]->key = input_array[i];
        records[i]->value = generate_unique_random(largest_value, i);
        pthread_mutex_unlock(&mutex);
    }

    return NULL;
}

int find_largest(int* array, int size) {
    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

int generate_unique_random(int upper_bound, int index) {
    srand(time(NULL) + index);
    int random_value;
    do {
        random_value = rand() % (upper_bound + 1);
    } while (is_duplicate(random_value));
    return random_value;
}

int is_duplicate(int value) {
    for (int i = 0; i < record_count; i++) {
        if (records[i]->value == value) {
            return 1;
        }
    }
    return 0;
}

void free_records() {
    for (int i = 0; i < record_count; i++) {
        free(records[i]);
    }
}

int main() {
    int input_array[MAX_RECORDS];
    printf("Enter the number of records: ");
    scanf("%d", &record_count);
    printf("Enter %d integers:\n", record_count);
    for (int i = 0; i < record_count; i++) {
        scanf("%d", &input_array[i]);
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, initialize_records, input_array) != 0) {
        perror("Thread creation failed");
        exit(EXIT_FAILURE);
    }
    pthread_join(thread, NULL);

    // Simulate usage
    for (int i = 0; i < record_count; i++) {
        printf("Key: %d, Value: %d\n", records[i]->key, records[i]->value);
    }

    free_records();
    return 0;
}
