typedef struct Node {
    int value;
    struct Node* next;
} Node;

typedef struct Record {
    long offset;
    int key;
    Node* list;
} Record;

int initializeRecords(Record** records, int size, int upperBound) {
    *records = (Record*)malloc(size * sizeof(Record));
    if (*records == NULL) {
        return -1; // Memory allocation failed
    }

    srand(time(NULL));

    for (int i = 0; i < size; i++) {
        (*records)[i].offset = rand();
        (*records)[i].key = rand() % upperBound;
        (*records)[i].list = NULL;

        int listSize = rand() % 10 + 1; // Random linked list size
        for (int j = 0; j < listSize; j++) {
            Node* newNode = (Node*)malloc(sizeof(Node));
            if (newNode == NULL) {
                freeRecords(*records, i);
                return -2; // Memory allocation failed
            }
            newNode->value = rand() % upperBound;
            newNode->next = (*records)[i].list;
            (*records)[i].list = newNode;
        }
    }

    return 0; // Initialization successful
}

void freeRecords(Record* records, int size) {
    for (int i = 0; i < size; i++) {
        Node* current = records[i].list;
        while (current != NULL) {
            Node* next = current->next;
            free(current);
            current = next;
        }
    }
    free(records);
}

