typedef struct {
    int id;
    double amount;
    char status[20];
} Transaction;

typedef struct {
    int transaction_id;
    char source_account[50];
    char target_account[50];
} AccountLog;

double calculate_average_transaction_amount(Transaction *transactions, int size) {
    double sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += transactions[i].amount;
    }
    return sum / size;
}

void process_transactions(int num_transactions, int min_amount, int max_amount) {
    Transaction *transactions = malloc(num_transactions * sizeof(Transaction));
    AccountLog *logs = malloc(num_transactions * sizeof(AccountLog));

    if (transactions == NULL || logs == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        free(transactions);
        free(logs);
        return;
    }

    srand(time(NULL));
    for (int i = 0; i < num_transactions; i++) {
        transactions[i].id = time(NULL) + i;
        transactions[i].amount = min_amount + rand() % (max_amount - min_amount + 1);
        strcpy(transactions[i].status, "Pending");
        sprintf(logs[i].source_account, "Account%d", i);
        sprintf(logs[i].target_account, "Account%d", (i + 1) % num_transactions);
    }

    double average_amount = calculate_average_transaction_amount(transactions, num_transactions);
    printf("Average Transaction Amount: %.2f\n", average_amount);

    free(transactions);
    free(logs);
}

int main() {
    int num_transactions;
    printf("Enter the number of transactions: ");
    scanf("%d", &num_transactions);

