#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
    time_t timestamp;
    char metadata[100];
} record;

typedef struct {
    int key;
    record *data;
    pthread_mutex_t lock;
} shared_data;

shared_data *init_shared_data(int size, int range) {
    shared_data *sd = (shared_data *)malloc(sizeof(shared_data));
    if (!sd) return NULL;

    sd->data = (record *)calloc(size, sizeof(record));
    if (!sd->data) {
        free(sd);
        return NULL;
    }

    pthread_mutex_init(&sd->lock, NULL);

    for (int i = 0; i < size; i++) {
        sd->data[i].value = rand() % range + 1;
        time_t now = time(NULL);
        sd->data[i].timestamp = now;
        snprintf(sd->data[i].metadata, sizeof(sd->data[i].metadata), "Record %d", i);
    }

    return sd;
}

void free_shared_data(shared_data *sd) {
    if (sd) {
        pthread_mutex_destroy(&sd->lock);
        free(sd->data);
        free(sd);
    }
}

int find_largest(int *array, int size) {
    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

void *worker_thread(void *arg) {
    shared_data *sd = (shared_data *)arg;

    pthread_mutex_lock(&sd->lock);
    int largest = find_largest((int *)sd->data, 10); // Assuming size is 10 for simplicity
    printf("Largest value: %d\n", largest);
    pthread_mutex_unlock(&sd->lock);

    return NULL;
}

int main() {
    srand(time(NULL));

    shared_data *sd = init_shared_data(10, 100);
    if (!sd) {
        fprintf(stderr, "Failed to initialize shared data.\n");
        return EXIT_FAILURE;
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, worker_thread, sd) != 0) {
        fprintf(stderr, "Failed to create thread.\n");
        free_shared_data(sd);
        return EXIT_FAILURE;
    }

    pthread_join(thread, NULL);

    free_shared_data(sd);
    return EXIT_SUCCESS;
}
```

