    time_t timestamp;
    int success;
    char *error_message;
    struct log_entry *next;
} log_entry;

int find_largest(int *array, int size) {
    if (size <= 0) return -1; // Handle edge case
    int largest = array[0];
    for (int i = 1; i < size; i++) {
        if (array[i] > largest) {
            largest = array[i];
        }
    }
    return largest;
}

void initialize_data(int *keys, record **records, log_entry **logs, int key_count, int upper_bound) {
    srand(time(NULL));
    for (int i = 0; i < key_count; i++) {
        keys[i] = rand() % (upper_bound + 1);
        records[i]->value = rand() % (upper_bound + 1);

        time_t now = time(NULL);
        logs[i] = (log_entry *)malloc(sizeof(log_entry));
        if (logs[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for log entry\n");
            // Clean up previously allocated resources
            return;
        }
        logs[i]->timestamp = now;
        logs[i]->success = 1; // Assuming all allocations succeed for simplicity
        logs[i]->error_message = NULL;
        logs[i]->next = NULL;

        printf("Record %d: Value = %d\n", i, records[i]->value);
    }

    int largest = find_largest(keys, key_count);
    printf("Largest Key: %d\n", largest);

    // Free allocated memory
    for (int i = 0; i < key_count; i++) {
        free(logs[i]);
    }
}

int main() {
    int key_count;
    printf("Enter the number of keys: ");
    scanf("%d", &key_count);

    int *keys = (int *)malloc(key_count * sizeof(int));
    record **records = (record **)malloc(key_count * sizeof(record *));
    log_entry **logs = (log_entry **)malloc(key_count * sizeof(log_entry *));

    if (keys == NULL || records == NULL || logs == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    for (int i = 0; i < key_count; i++) {
        records[i] = (record *)malloc(sizeof(record));
        if (records[i] == NULL) {
            fprintf(stderr, "Memory allocation failed for record %d\n", i);
            // Clean up previously allocated resources
            return 1;
        }
    }

    initialize_data(keys, records, logs, key_count, 100);

    free(keys);
    for (int i = 0; i < key_count; i++) {
        free(records[i]);
    }
    free(records);
    free(logs);

    return 0;
}
