#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RECORDS 1000000
#define UPPER_BOUND 1000

typedef struct {
    int key;
    int value;
} Record;

Record* dynamicArray = NULL;
int arraySize = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
int recordsCount = 0;

void* initializeRecords(void* arg) {
    int size = *(int*)arg;
    pthread_mutex_lock(&mutex);
    while (recordsCount >= MAX_RECORDS) {
        pthread_cond_wait(&cond, &mutex);
    }
    if (arraySize < size) {
        dynamicArray = realloc(dynamicArray, size * sizeof(Record));
        if (!dynamicArray) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }
        arraySize = size;
    }
    for (int i = 0; i < size; i++) {
        dynamicArray[i].key = recordsCount++;
        dynamicArray[i].value = rand() % UPPER_BOUND + 1;
    }
    pthread_mutex_unlock(&mutex);
    pthread_cond_signal(&cond);
    return NULL;
}

void* findLargestValue(void* arg) {
    int largest = 0;
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < arraySize; i++) {
        if (dynamicArray[i].value > largest) {
            largest = dynamicArray[i].value;
        }
    }
    printf("Largest value: %d\n", largest);
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void* updateRecord(void* arg) {
    int key = *(int*)arg;
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < arraySize; i++) {
        if (dynamicArray[i].key == key) {
            dynamicArray[i].value = rand() % UPPER_BOUND + 1;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void* monitorSystem(void* arg) {
    while (1) {
        pthread_mutex_lock(&mutex);
        printf("Active records: %d, Memory usage: %zu bytes\n", recordsCount, arraySize * sizeof(Record));
        pthread_mutex_unlock(&mutex);
        sleep(5); // Monitor every 5 seconds
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    int size = 1000;
    pthread_t threads[4];

    pthread_create(&threads[0], NULL, initializeRecords, &size);
    pthread_create(&threads[1], NULL, findLargestValue, NULL);
    pthread_create(&threads[2], NULL, updateRecord, (void*)&dynamicArray[500].key);
    pthread_create(&threads[3], NULL, monitorSystem, NULL);

    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    free(dynamicArray);
    return 0;
}
