#define MAX_RECORDS 1000000
#define UPPER_BOUND 1000

typedef struct {
    int key;
    int value;
} Record;

Record* records[MAX_RECORDS];
int record_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* initialize_records(void* arg) {
    int upper_bound = *(int*)arg;
    srand(time(NULL));

    for (int i = 0; i < MAX_RECORDS; i++) {
        pthread_mutex_lock(&mutex);
        if (record_count >= MAX_RECORDS) {
            pthread_mutex_unlock(&mutex);
            break;
        }
        records[record_count] = (Record*)malloc(sizeof(Record));
        if (!records[record_count]) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        records[record_count]->key = i + 1;
        records[record_count]->value = rand() % upper_bound;
        record_count++;
        pthread_mutex_unlock(&mutex);
    }

    return NULL;
}

void free_records() {
    for (int i = 0; i < record_count; i++) {
        free(records[i]);
    }
}

int main() {
    int upper_bound;
    printf("Enter the upper bound: ");
    scanf("%d", &upper_bound);

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, initialize_records, &upper_bound);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    free_records();

    return 0;
}
