#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure for product inventory entries
typedef struct {
    int id;
    char name[100];
    float price;
    int quantity;
} Product;

// Define a linked list node for dynamic memory management
typedef struct Node {
    Product data;
    struct Node* next;
} Node;

// Function to create a new product entry
Node* createProduct(int id, const char* name, float price, int quantity) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    newNode->data.id = id;
    strncpy(newNode->data.name, name, sizeof(newNode->data.name));
    newNode->data.price = price;
    newNode->data.quantity = quantity;
    newNode->next = NULL;
    return newNode;
}

// Function to insert a product entry into the linked list
void insertProduct(Node** head, int id, const char* name, float price, int quantity) {
    Node* newNode = createProduct(id, name, price, quantity);
    if (*head == NULL) {
        *head = newNode;
    } else {
        Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
}

// Function to free the memory allocated for the linked list
void freeInventory(Node** head) {
    Node* current = *head;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

// Function to save the inventory to a JSON file
void saveInventoryToJson(Node* head, const char* filePath) {
    FILE* file = fopen(filePath, "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }
    fprintf(file, "[\n");
    Node* current = head;
    while (current != NULL) {
        fprintf(file, "  {\n    \"id\": %d,\n    \"name\": \"%s\",\n    \"price\": %.2f,\n    \"quantity\": %d\n  }", 
                current->data.id, current->data.name, current->data.price, current->data.quantity);
        if (current->next != NULL) {
            fprintf(file, ",\n");
        }
        current = current->next;
    }
    fprintf(file, "\n]\n");
    fclose(file);
}

// Function to load inventory from an XML file
Node* loadInventoryFromXml(const char* filePath) {
    // Implement XML parsing logic here
    return NULL; // Placeholder
}

int main() {
    Node* head = NULL;
    insertProduct(&head, 1, "Laptop", 999.99, 50);
    insertProduct(&head, 2, "Mouse", 29.99, 100);

    saveInventoryToJson(head, "inventory.json");

    freeInventory(&head);

    return 0;
}
