#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct {
    long* offsets;
    int* keys;
    record* records;
    size_t capacity;
    size_t size;
    size_t memory_usage;
    size_t max_memory_usage;
    pthread_mutex_t lock;
} data_structure;

data_structure* create_data_structure(size_t initial_capacity, size_t max_memory_usage) {
    data_structure* ds = (data_structure*)malloc(sizeof(data_structure));
    if (!ds) return NULL;

    ds->offsets = (long*)malloc(initial_capacity * sizeof(long));
    ds->keys = (int*)malloc(initial_capacity * sizeof(int));
    ds->records = (record*)malloc(initial_capacity * sizeof(record));
    ds->capacity = initial_capacity;
    ds->size = 0;
    ds->memory_usage = 0;
    ds->max_memory_usage = max_memory_usage;

    if (!ds->offsets || !ds->keys || !ds->records) {
        free(ds);
        return NULL;
    }

    pthread_mutex_init(&ds->lock, NULL);

    srand(time(NULL));
    for (size_t i = 0; i < initial_capacity; ++i) {
        ds->records[i].value = rand() % 1000;
        ds->memory_usage += sizeof(long) + sizeof(int) + sizeof(record);
    }

    return ds;
}

void destroy_data_structure(data_structure* ds) {
    free(ds->offsets);
    free(ds->keys);
    free(ds->records);
    pthread_mutex_destroy(&ds->lock);
    free(ds);
}

int add_record(data_structure* ds, int value) {
    pthread_mutex_lock(&ds->lock);

    if (ds->size >= ds->capacity) {
        size_t new_capacity = ds->capacity * 2;
        long* new_offsets = (long*)realloc(ds->offsets, new_capacity * sizeof(long));
        int* new_keys = (int*)realloc(ds->keys, new_capacity * sizeof(int));
        record* new_records = (record*)realloc(ds->records, new_capacity * sizeof(record));

        if (!new_offsets || !new_keys || !new_records) {
            pthread_mutex_unlock(&ds->lock);
            return -1;
        }

        ds->offsets = new_offsets;
        ds->keys = new_keys;
        ds->records = new_records;
        ds->capacity = new_capacity;
    }

    ds->records[ds->size].value = value;
    ds->memory_usage += sizeof(record);

    if (ds->memory_usage > ds->max_memory_usage) {
        pthread_mutex_unlock(&ds->lock);
        return -2; // Memory usage exceeded
    }

    ++ds->size;

    pthread_mutex_unlock(&ds->lock);
    return 0;
}

int get_record(data_structure* ds, size_t index, int* value) {
    if (index >= ds->size) return -1;

    *value = ds->records[index].value;
    return 0;
}
