} Record;

typedef struct {
    Record** records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} RecordCollection;

RecordCollection* create_record_collection() {
    RecordCollection* collection = (RecordCollection*)malloc(sizeof(RecordCollection));
    if (!collection) return NULL;

    collection->records = (Record**)calloc(MAX_RECORDS, sizeof(Record*));
    if (!collection->records) {
        free(collection);
        return NULL;
    }

    collection->capacity = MAX_RECORDS;
    collection->size = 0;
    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void destroy_record_collection(RecordCollection* collection) {
    for (size_t i = 0; i < collection->size; ++i) {
        Record* record = collection->records[i];
        free(record->offsets);
        free(record->keys);
        free(record);
    }
    free(collection->records);
    pthread_mutex_destroy(&collection->lock);
    free(collection);
}

Record* create_record(int value, size_t offset_count, size_t key_count) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) return NULL;

    record->value = value;
    record->offsets = (long*)calloc(offset_count, sizeof(long));
    if (!record->offsets) {
        free(record);
        return NULL;
    }

    record->keys = (int*)calloc(key_count, sizeof(int));
    if (!record->keys) {
        free(record->offsets);
        free(record);
        return NULL;
    }

    return record;
}

void destroy_record(Record* record) {
    free(record->offsets);
    free(record->keys);
    free(record);
}

int add_record(RecordCollection* collection, Record* record) {
    pthread_mutex_lock(&collection->lock);
    if (collection->size >= collection->capacity) {
        pthread_mutex_unlock(&collection->lock);
        return -1; // Collection is full
    }

    collection->records[collection->size++] = record;
    pthread_mutex_unlock(&collection->lock);
    return 0;
}

Record* get_record(RecordCollection* collection, size_t index) {
    if (index >= collection->size) return NULL;
    return collection->records[index];
}

void update_record(Record* record, int new_value, long* new_offsets, int* new_keys, size_t offset_count, size_t key_count) {
    record->value = new_value;
    free(record->offsets);
    free(record->keys);

    record->offsets = (long*)calloc(offset_count, sizeof(long));
    if (!record->offsets) return;

    record->keys = (int*)calloc(key_count, sizeof(int));
    if (!record->keys) {
        free(record->offsets);
        return;
    }

    for (size_t i = 0; i < offset_count; ++i) {
        record->offsets[i] = new_offsets[i];
    }
    for (size_t i = 0; i < key_count; ++i) {
        record->keys[i] = new_keys[i];
    }
}
