void* initialize_arrays(int num_elements, int key_range, int offset_range) {
    if (num_elements <= 0 || key_range <= 0 || offset_range <= 0) {
        return NULL; // Invalid input
    }

    long *offsets = malloc(num_elements * sizeof(long));
    int *keys = malloc(num_elements * sizeof(int));
    record **records = malloc(num_elements * sizeof(record*));

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return NULL; // Memory allocation failed
    }

    pthread_mutex_t mutex;
    pthread_mutex_init(&mutex, NULL);

    for (int i = 0; i < num_elements; i++) {
        offsets[i] = rand() % offset_range;
        keys[i] = rand() % key_range;

        records[i] = malloc(sizeof(record));
        if (!records[i]) {
            // Handle memory allocation failure
            for (int j = 0; j < i; j++) {
                free(records[j]);
            }
            free(offsets);
            free(keys);
            free(records);
            pthread_mutex_destroy(&mutex);
            return NULL;
        }

        records[i]->value = rand() % key_range;

        // Simulate concurrent access
        pthread_mutex_lock(&mutex);
        // Perform operations on offsets, keys, and records
        pthread_mutex_unlock(&mutex);
    }

    pthread_mutex_destroy(&mutex);

    // Return a pointer to the array of record pointers for efficient access
    return records;
}

void free_arrays(void *array_of_records) {
    if (array_of_records) {
        record **records = (record**)array_of_records;
        int num_elements = 0;

        while (records[num_elements]) {
            free(records[num_elements]);
            num_elements++;
        }

        free(array_of_records);
    }
}
