#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define TABLE_SIZE 1024

typedef struct record {
    int key;
    long *offset;
    int ref_count;
    struct record *next;
} record;

typedef struct hash_table {
    record **buckets;
    pthread_mutex_t lock;
} hash_table;

hash_table *create_hash_table() {
    hash_table *ht = (hash_table *)malloc(sizeof(hash_table));
    if (!ht) return NULL;

    ht->buckets = (record **)calloc(TABLE_SIZE, sizeof(record *));
    if (!ht->buckets) {
        free(ht);
        return NULL;
    }

    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

unsigned int hash_function(int key) {
    return abs(key % TABLE_SIZE);
}

record *create_record(int key, long offset) {
    record *rec = (record *)malloc(sizeof(record));
    if (!rec) return NULL;

    rec->key = key;
    rec->offset = (long *)malloc(sizeof(long));
    if (!rec->offset) {
        free(rec);
        return NULL;
    }
    *rec->offset = offset;
    rec->ref_count = 0;
    rec->next = NULL;
    return rec;
}

void insert_record(hash_table *ht, int key, long offset) {
    pthread_mutex_lock(&ht->lock);
    unsigned int index = hash_function(key);
    record *new_rec = create_record(key, offset);

    if (!new_rec) {
        pthread_mutex_unlock(&ht->lock);
        return;
    }

    if (ht->buckets[index] == NULL) {
        ht->buckets[index] = new_rec;
    } else {
        record *current = ht->buckets[index];
        while (current->next != NULL && current->key != key) {
            current = current->next;
        }

        if (current->key == key) {
            free(new_rec->offset);
            free(new_rec);
        } else {
            current->next = new_rec;
        }
    }

    pthread_mutex_unlock(&ht->lock);
}

void increment_ref_count(hash_table *ht, int key) {
    pthread_mutex_lock(&ht->lock);
    unsigned int index = hash_function(key);
    record *current = ht->buckets[index];

    while (current != NULL && current->key != key) {
        current = current->next;
    }

    if (current != NULL) {
        current->ref_count++;
    }

    pthread_mutex_unlock(&ht->lock);
}

void free_record(record *rec) {
    if (rec) {
        free(rec->offset);
        free(rec);
    }
}

void destroy_hash_table(hash_table *ht) {
    for (int i = 0; i < TABLE_SIZE; i++) {
        record *current = ht->buckets[i];
        while (current != NULL) {
            record *temp = current;
            current = current->next;
            free_record(temp);
        }
    }

    pthread_mutex_destroy(&ht->lock);
    free(ht->buckets);
    free(ht);
}
