#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define user profile structure
typedef struct {
    int id;
    char name[100];
    char email[100];
    char preferences[256];
} UserProfile;

// Function to allocate memory for a new user profile
UserProfile* create_profile(int id, const char* name, const char* email, const char* preferences) {
    UserProfile* profile = (UserProfile*)malloc(sizeof(UserProfile));
    if (profile == NULL) {
        perror("Failed to allocate memory for user profile");
        return NULL;
    }
    profile->id = id;
    strncpy(profile->name, name, sizeof(profile->name) - 1);
    strncpy(profile->email, email, sizeof(profile->email) - 1);
    strncpy(profile->preferences, preferences, sizeof(profile->preferences) - 1);
    return profile;
}

// Function to free memory allocated for a user profile
void free_profile(UserProfile* profile) {
    if (profile != NULL) {
        free(profile);
    }
}

// Helper function to calculate and print the average length of names
double average_name_length(UserProfile** profiles, int count) {
    double total_length = 0;
    for (int i = 0; i < count; i++) {
        total_length += strlen(profiles[i]->name);
    }
    return total_length / count;
}

// Function to parse CSV file and initialize user profiles
int init_user_profiles(const char* filename, UserProfile*** profiles, int* count) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        perror("Failed to open CSV file");
        return -1;
    }

    // Count the number of lines in the file
    *count = 0;
    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file)) {
        (*count)++;
    }
    fclose(file);

    // Allocate memory for user profiles
    *profiles = (UserProfile**)malloc((*count) * sizeof(UserProfile*));
    if (*profiles == NULL) {
        perror("Failed to allocate memory for user profiles");
        return -1;
    }

    // Reopen file and parse data
    file = fopen(filename, "r");
    int i = 0;
    while (fgets(buffer, sizeof(buffer), file)) {
        char* token = strtok(buffer, ",");
        if (token == NULL) continue;

        int id = atoi(token);
        token = strtok(NULL, ",");
        if (token == NULL) continue;

        char name[100];
        strncpy(name, token, sizeof(name) - 1);

        token = strtok(NULL, ",");
        if (token == NULL) continue;

        char email[100];
        strncpy(email, token, sizeof(email) - 1);

        token = strtok(NULL, ",");
        if (token == NULL) continue;

        char preferences[256];
        strncpy(preferences, token, sizeof(preferences) - 1);

        (*profiles)[i] = create_profile(id, name, email, preferences);
        if ((*profiles)[i] == NULL) {
            // Clean up previously allocated profiles
            for (int j = 0; j < i; j++) {
                free_profile((*profiles)[j]);
            }
            free(*profiles);
            fclose(file);
            return -1;
        }
        i++;
    }
    fclose(file);

    return 0;
}

// Function to clean up user profiles
void cleanup_user_profiles(UserProfile** profiles, int count) {
    for (int i = 0; i < count; i++) {
        free_profile(profiles[i]);
    }
    free(profiles);
}

// Main function to demonstrate usage
int main() {
    UserProfile** profiles;
    int count;

    if (init_user_profiles("users.csv", &profiles, &count) == 0) {
        printf("Average name length: %.2f\n", average_name_length(profiles, count));
        cleanup_user_profiles(profiles, count);
    } else {
        fprintf(stderr, "Failed to initialize user profiles\n");
    }

    return 0;
}
