#include <string.h>
#include <time.h>

typedef struct {
    int value;
    char tag[50];
} Record;

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

int find_largest(int* keys, int size) {
    int largest = keys[0];
    for (int i = 1; i < size; i++) {
        if (keys[i] > largest) {
            largest = keys[i];
        }
    }
    return largest;
}

void initialize_records(Record** records, int* keys, int size, int upper_bound) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        records[i]->value = rand() % (upper_bound + 1);
        snprintf(records[i]->tag, sizeof(records[i]->tag), "Record%d", keys[i]);
    }
}

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
}

int main(int argc, char* argv[]) {
    int size;
    printf("Enter the number of elements: ");
    scanf("%d", &size);

    int* keys = (int*)safe_malloc(size * sizeof(int));
    Record** records = (Record**)safe_malloc(size * sizeof(Record*));

    for (int i = 0; i < size; i++) {
        printf("Enter key %d: ", i);
        scanf("%d", &keys[i]);
        records[i] = (Record*)safe_malloc(sizeof(Record));
    }

    int largest_key = find_largest(keys, size);
    printf("Largest key: %d\n", largest_key);

    initialize_records(records, keys, size, 100); // Assuming upper bound of 100

    for (int i = 0; i < size; i++) {
        printf("Record %d: Value=%d, Tag=%s\n", keys[i], records[i]->value, records[i]->tag);
        free(records[i]);
    }

    free(keys);
    free(records);

    return 0;
}
