#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct Item {
    char *key;
    int value;
    time_t timestamp;
    struct Item *next;
} Item;

typedef struct LinkedList {
    Item *head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_list() {
    LinkedList *list = (LinkedList*)malloc(sizeof(LinkedList));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void insert_item(LinkedList *list, char *key, int value) {
    pthread_mutex_lock(&list->lock);
    Item *new_item = (Item*)malloc(sizeof(Item));
    new_item->key = strdup(key);
    new_item->value = value;
    new_item->timestamp = time(NULL);
    new_item->next = NULL;

    if (list->head == NULL || list->head->value > value) {
        new_item->next = list->head;
        list->head = new_item;
    } else {
        Item *current = list->head;
        while (current->next != NULL && current->next->value < value) {
            current = current->next;
        }
        new_item->next = current->next;
        current->next = new_item;
    }
    pthread_mutex_unlock(&list->lock);
}

void delete_item(LinkedList *list, char *key) {
    pthread_mutex_lock(&list->lock);
    Item *current = list->head;
    Item *previous = NULL;

    while (current != NULL && strcmp(current->key, key) != 0) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    if (previous == NULL) {
        list->head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current->key);
    free(current);
    pthread_mutex_unlock(&list->lock);
}

void traverse_list(LinkedList *list) {
    pthread_mutex_lock(&list->lock);
    Item *current = list->head;
    while (current != NULL) {
        printf("Key: %s, Value: %d, Timestamp: %ld\n", current->key, current->value, current->timestamp);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void free_list(LinkedList *list) {
    pthread_mutex_lock(&list->lock);
    Item *current = list->head;
    while (current != NULL) {
        Item *temp = current;
        current = current->next;
        free(temp->key);
        free(temp);
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
